window.COMPTIA_EXAM_DATA = {"version": "3.1.0", "title": "CompTIA A+ (220-1201 Core 1 & 220-1202 Core 2) Master Question Bank", "description": "Blueprint-aligned question bank with single, multi-select, matching, and ordering items. Scaled 100-900 scoring.", "passing_score_core1": 675, "passing_score_core2": 700, "max_time_minutes": 90, "max_questions_per_exam": 90, "blueprint": {"core1": {"1.0 Mobile Devices": 13, "2.0 Networking": 23, "3.0 Hardware": 25, "4.0 Virtualization and Cloud Computing": 11, "5.0 Hardware and Network Troubleshooting": 28}, "core2": {"1.0 Operating Systems": 28, "2.0 Security": 28, "3.0 Software Troubleshooting": 23, "4.0 Operational Procedures": 21}}, "core1": [{"id": "C1-001", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which of the following is an environmental threat or phenomenon that damages electronic components rather than a physical tool found in a technician's toolkit?", "options": ["Multimeter / voltage tester", "Electromagnetic pulse (EMP) discharge", "USB thumb drive with diagnostic utilities", "Hex nut driver for motherboard standoffs"], "answer": 1, "explanation": "An electromagnetic pulse (EMP) is a sudden burst of electromagnetic radiation that damages or destroys electronic circuits; it is an environmental hazard, not a tool. Diagnostic thumb drives, nut drivers for mounting standoffs, and multimeters/voltage testers are standard physical equipment carried in a technician's toolkit.", "distractor_analysis": {"0": "USB thumb drives with diagnostic software and bootable ISOs are essential portable tools for field technicians.", "1": "Nut drivers are standard mechanical hand tools used to tighten motherboard standoffs and chassis mounting screws.", "2": "Multimeters and voltage testers are essential diagnostic electrical tools used to verify AC wall outlets and DC PSU rail voltages."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["tools", "safety", "environmental"]}, {"id": "C1-002", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "A datacenter technician needs to measure the AC line voltage and verify proper grounding at a standard commercial wall receptacle. Which tool should the technician use?", "options": ["Radio frequency interference (RFI) probe", "Electrostatic discharge (ESD) field meter", "Digital multimeter / voltmeter", "Precision mechanical tweezers"], "answer": 2, "explanation": "A digital multimeter (or dedicated voltmeter/receptacle tester) measures AC voltage, DC voltage, resistance, and circuit continuity, making it the proper tool to verify that an electrical wall outlet supplies expected line voltage (e.g., 120V in North America or 230V in Europe). RFI probes detect wireless electromagnetic interference. ESD field meters measure static charge accumulation. Tweezers are assembly tools that present severe shock hazards if inserted into electrical outlets.", "distractor_analysis": {"0": "RFI probes measure high-frequency radio signal emissions, not 50/60 Hz AC electrical line power.", "1": "ESD field meters measure static electrostatic potential on surfaces, not line voltage from power mains.", "3": "Inserting metal tweezers into an energized AC wall receptacle creates a dangerous short circuit and severe electric shock hazard."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["tools", "multimeter", "power", "electrical"]}, {"id": "C1-003", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A tier-1 help desk technician is troubleshooting a complex server failure that exceeds their technical expertise and authorization level. According to professional support best practices, what should the technician do next?", "options": ["Escalate the issue to a senior engineer following established support procedures", "Ask the end user for technical advice on how to repair the server", "Completely disassemble the server hardware without a diagnostic plan", "Inform the customer that the problem is impossible to fix and close the ticket"], "answer": 2, "explanation": "When an issue falls outside a technician's skill set, access permissions, or organizational scope of practice, the professional and standard procedure is to escalate the ticket to senior engineering or specialized vendor support. Asking the customer for technical instructions is unprofessional, disassembling hardware blindly causes further downtime, and dismissing the problem without escalation damages customer trust.", "distractor_analysis": {"0": "End users look to IT support for technical solutions; asking them how to fix server infrastructure is unprofessional.", "1": "Disassembling complex systems without a tested diagnostic theory wastes time and risks damaging hardware.", "2": "Telling a customer a problem cannot be fixed instead of seeking higher-tier engineering support violates SLA and customer service standards."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "methodology", "escalation"]}, {"id": "C1-004", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.7", "type": "single", "difficulty": "easy", "question": "Which of the following computer peripheral devices functions strictly as an output device for presenting data to users?", "options": ["USB web camera", "Mechanical keyboard", "Studio condenser microphone", "Standalone laser printer"], "answer": 3, "explanation": "A printer is an output device that converts digital electronic documents into hardcopy physical media. Microphones capture acoustic audio signals into digital data (input), web cameras capture video streams (input), and keyboards capture keystrokes and user commands (input).", "distractor_analysis": {"0": "A microphone captures analog sound waves and converts them into digital audio data, making it an input device.", "2": "A web camera captures optical images and transmits video data into the computer system, making it an input device.", "3": "A keyboard sends keystroke scan codes into the operating system, making it a primary human input device."}, "video_reference": {"title": "Multifunction Devices - CompTIA A+ 220-1201 - 3.7", "url": "https://www.youtube.com/watch?v=ctAOL7WyEUY", "duration": "14:25", "objective": "3.7"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "peripherals", "input-output"]}, {"id": "C1-005", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following is a specialized AI accelerator processor developed specifically by Google for cloud machine learning workloads rather than a standard commodity PC component?", "options": ["Central Processing Unit (CPU)", "Tensor Processing Unit (TPU)", "Graphics Processing Unit (GPU)", "Random Access Memory (RAM)"], "answer": 1, "explanation": "A Tensor Processing Unit (TPU) is a proprietary application-specific integrated circuit (ASIC) custom-built by Google for machine learning and neural network training in cloud datacenters, not a standard commodity PC component. CPUs, GPUs, and RAM modules are the foundational components found in standard personal computers and workstations.", "distractor_analysis": {"0": "A GPU is a standard PC component responsible for rendering graphics and executing parallel compute tasks.", "1": "RAM is the primary volatile system memory installed on every personal computer motherboard.", "2": "The CPU is the central processing unit that executes general-purpose operating system and application instructions in every PC."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "processors", "cpu", "tpu"]}, {"id": "C1-006", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "A community technology center provides public access to shared electronic workbenches, 3D printers, soldering stations, and PC building tools. What term describes this collaborative community workspace?", "options": ["Demilitarized zone (DMZ)", "Makerspace / hackerspace", "Server blade chassis", "Cleanroom laboratory"], "answer": 3, "explanation": "A makerspace (or hackerspace) is a collaborative community workspace located in schools, libraries, or public facilities where students, technicians, and hobbyists can gain hands-on experience with computer hardware, electronics, microcontrollers, and fabrication tools at little or no cost. A blade chassis is a datacenter server enclosure, a cleanroom is a sealed facility for silicon manufacturing/drive recovery, and a DMZ is a network perimeter segment.", "distractor_analysis": {"1": "A server blade chassis is high-density datacenter rack hardware housing modular blade servers, not a community learning space.", "2": "A cleanroom is an ultra-filtered industrial laboratory used for semiconductor fabrication or platter-level hard drive recovery.", "3": "A DMZ is a physical or logical subnet that exposes external-facing services to an untrusted network like the Internet."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "community", "makerspace"]}, {"id": "C1-007", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "When a CPU receives binary machine language patterns from system RAM across the data bus, what internal microprocessor component or structure decodes the opcodes into execution micro-operations?", "options": ["General-purpose register", "Instruction decoder / microcode table", "Address bus transceiver", "External data bus"], "answer": 3, "explanation": "The instruction decoder (utilizing the internal microcode engine and instruction lookup logic) interprets incoming binary machine code opcodes fetched from memory and translates them into control signals and micro-operations executed by the ALU and execution units. Registers are internal high-speed storage locations. The external data bus transfers data between the CPU and memory controller. The address bus conveys memory physical addresses.", "distractor_analysis": {"0": "The external data bus consists of physical conductive traces carrying raw binary data between the CPU and RAM, but does not decode instructions.", "1": "Registers are tiny, ultra-fast memory cells inside the CPU used to temporarily hold operands and memory pointers during computation.", "3": "The address bus carries memory addresses specifying where data should be read from or written to in RAM."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "architecture", "microcode"]}, {"id": "C1-008", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following is NOT a recognized CPU Instruction Set Architecture (ISA) standard used in modern computing?", "options": ["x84 architecture", "x86 (32-bit IA-32)", "x86-64 / AMD64 (64-bit)", "ARM / AArch64"], "answer": 2, "explanation": "'x84' is a non-existent, fictitious term. The prominent instruction set architectures in modern computing include x86 (the 32-bit architecture originated by Intel), x86-64/AMD64 (the 64-bit extension designed by AMD and adopted industry-wide), and ARM/AArch64 (widely used in mobile, embedded, and modern power-efficient cloud servers).", "distractor_analysis": {"0": "x86 is the foundational 32-bit instruction set architecture used in personal computers for decades.", "1": "x86-64 (AMD64/Intel 64) is the dominant 64-bit processor architecture used in contemporary PC and datacenter x86 servers.", "2": "ARM is a widely adopted RISC processor architecture powering smartphones, tablets, and modern cloud server processors."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "isa", "architecture"]}, {"id": "C1-009", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "In the processor model designation 'Intel Core i9-12900K', which component of the alphanumeric string specifies the CPU generation?", "options": ["Core i9 (Product line and tier)", "12 (Microprocessor generation)", "K (Unlocked multiplier suffix)", "Intel (Manufacturer brand)"], "answer": 3, "explanation": "In Intel's Core processor naming convention, the first one or two digits of the model number indicate the generation. In 'i9-12900K', '12' represents the 12th Generation Core architecture. 'Intel' is the brand, 'Core i9' is the product brand and performance tier, '900' is the SKU/model number, and 'K' is the suffix designating an unlocked overclocking multiplier.", "distractor_analysis": {"0": "'Intel' is the corporation name and master brand, not a generation identifier.", "1": "'Core i9' designates the performance brand modifier and tier within Intel's product line.", "3": "'K' is a product suffix indicating that the processor has an unlocked multiplier for overclocking."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "intel", "specifications"]}, {"id": "C1-010", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A technician is preparing to unpack and install an expensive server CPU into a motherboard socket. What is the primary safety practice to prevent electrostatic damage to the processor before and during installation?", "options": ["Pre-apply thermal paste directly into the socket pin holes", "Rely entirely on the socket plastic orientation notch for ESD grounding", "Work on a grounded ESD mat while wearing an antistatic wrist strap", "Connect the OEM CPU cooling fan to power before seating the chip"], "answer": 2, "explanation": "Working on a dissipative, grounded Electrostatic Discharge (ESD) mat while wearing an antistatic wrist strap bonded to chassis ground equalizes electrical potential and safely drains static charge away from sensitive semiconductor microcircuits. Applying thermal paste into socket pin holes destroys electrical contact and ruins the motherboard. Powering the fan beforehand or relying on plastic alignment notches provides zero ESD protection.", "distractor_analysis": {"1": "Connecting the cooling fan before the CPU is installed does not provide ESD protection and could cause physical interference during socket latching.", "2": "Thermal paste must only be applied between the CPU integrated heat spreader (IHS) and the heatsink base; placing it in the socket pins causes catastrophic electrical faults.", "3": "Orientation notches are physical alignment keys that ensure correct socket orientation, not conductive electrical grounds."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "esd", "safety"]}, {"id": "C1-011", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "easy", "question": "A desktop computer technician is installing a 16 GB DDR4 desktop memory module into a motherboard DIMM slot. How many physical pins does a standard DDR4 desktop DIMM possess?", "options": ["184 pins", "168 pins", "240 pins", "288 pins"], "answer": 1, "explanation": "DDR4 desktop unbuffered DIMMs feature 288 pins and a notched keyed edge to prevent insertion into incompatible slots. Legacy DDR3 and DDR2 desktop DIMMs have 240 pins, original DDR DIMMs have 184 pins, and legacy SDR SDRAM DIMMs have 168 pins.", "distractor_analysis": {"0": "168 pins is the pin count for legacy single data rate (SDR) SDRAM desktop DIMMs.", "1": "240 pins is the pin count for DDR2 and DDR3 desktop DIMM modules.", "3": "184 pins is the pin count for first-generation DDR (DDR1) desktop DIMMs."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "ddr4", "pin-counts"]}, {"id": "C1-012", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which memory form factor is engineered specifically for compact laptops, small-form-factor devices, and thin clients due to its smaller physical dimensions?", "options": ["Small Outline Dual In-line Memory Module (SO-DIMM)", "Single In-line Memory Module (SIMM)", "Registered ECC full-height server DIMM", "Standard desktop unbuffered DIMM"], "answer": 2, "explanation": "SO-DIMMs (Small Outline Dual In-line Memory Modules) are approximately half the physical length of standard desktop DIMMs, making them the universal standard memory module form factor for laptops, notebooks, all-in-one PCs, and compact small-form-factor systems. Desktop DIMMs, SIMMs, and full-height server DIMMs are physically too large to fit into laptop chassis.", "distractor_analysis": {"0": "Desktop DIMMs are full-length modules designed for desktop ATX and microATX motherboards, unable to fit into laptop memory slots.", "2": "SIMMs are obsolete 30-pin and 72-pin memory modules from legacy 1990s personal computers.", "3": "Registered ECC server DIMMs are full-height enterprise modules designed for multi-socket rackmount servers."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "ram", "so-dimm"]}, {"id": "C1-013", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A server administrator requires memory modules that detect single-bit and multi-bit memory errors and automatically correct single-bit errors on the fly to prevent server crashes. What type of RAM must be specified?", "options": ["Non-ECC unbuffered desktop RAM", "Error-Correcting Code (ECC) RAM", "Single-channel dynamic RAM", "Double-sided consumer RAM"], "answer": 1, "explanation": "Error-Correcting Code (ECC) RAM includes extra memory bits and dedicated controller logic that calculate checksums to detect and correct single-bit memory corruption in real time, as well as detect multi-bit errors and halt safely. This is critical for enterprise datacenter servers and mission-critical financial systems. Non-ECC RAM lacks error correction. Channel configurations and double-sided physical layouts do not provide error correction.", "distractor_analysis": {"0": "Non-ECC RAM cannot detect or correct memory bit flips, which can lead to silent data corruption or blue-screen system crashes.", "2": "Single-channel describes memory bus architecture width (64 bits), not data integrity error detection capabilities.", "3": "Double-sided RAM refers to memory chips being mounted on both physical sides of the PCB, which is unrelated to error correction."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "ecc", "data-integrity"]}, {"id": "C1-014", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "When populating RAM modules on a newly assembled motherboard to enable multi-channel memory performance, what documentation should the technician consult to determine the exact slot population order?", "options": ["Operating system installation media documentation", "Power supply modular cable pinout diagram", "Computer case chassis front-panel wiring sheet", "Motherboard manufacturer user manual / technical specification guide"], "answer": 1, "explanation": "The motherboard manufacturer's manual explicitly defines the recommended memory slot population order (such as slots DIMM_A2 and DIMM_B2 for dual-channel operation) and supported speeds. Following manufacturer specifications ensures optimal stability and enables multi-channel bandwidth. OS documentation, PSU diagrams, and chassis wiring sheets do not contain motherboard memory trace routing rules.", "distractor_analysis": {"1": "Operating system manuals explain software installation and kernel settings, not motherboard-specific physical memory slot population topologies.", "2": "Power supply cable diagrams detail voltage rails and modular connector pinouts, having no information on RAM channeling.", "3": "Chassis front-panel wiring diagrams show power switch and LED header connections, not memory configuration."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "ram", "motherboard", "best-practices"]}, {"id": "C1-015", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A workstation running memory-intensive CAD software experiences significant performance slowdowns and constant drive thrashing due to heavy paging to the virtual memory swap file. What is the most effective hardware upgrade to resolve this bottleneck?", "options": ["Downgrade to an older single-core processor with higher clock frequency", "Replace the existing motherboard with a smaller Mini-ITX form factor", "Install additional physical RAM to reduce paging to secondary storage", "Disable virtual memory entirely in the operating system advanced settings"], "answer": 2, "explanation": "When physical RAM is exhausted, the operating system pages inactive memory pages to the disk (virtual memory/swap file), which causes severe performance degradation (disk thrashing) because storage access latency is orders of magnitude slower than physical RAM. Adding more physical RAM ensures applications remain in high-speed system memory, eliminating page thrashing. Disabling virtual memory causes crashes. CPU downgrades or changing form factors do not alleviate memory exhaustion.", "distractor_analysis": {"1": "Disabling virtual memory when physical memory is already constrained leads to out-of-memory errors and immediate application crashes.", "2": "Downgrading the CPU reduces processing capability and does nothing to solve physical memory capacity constraints.", "3": "Switching to a Mini-ITX motherboard typically reduces the number of available DIMM slots, making memory expansion even harder."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "virtual-memory", "troubleshooting"]}, {"id": "C1-016", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A technician is following the CompTIA Troubleshooting Methodology to resolve intermittent memory errors. The technician has identified the problem, established a theory of probable cause (unseated RAM), and successfully tested the theory. What is the NEXT step in the methodology?", "options": ["Verify full system functionality and implement preventive measures", "Establish a plan of action to resolve the problem and implement the solution", "Document findings, actions, and outcomes in the ticketing system", "Question the user about environmental and software changes"], "answer": 3, "explanation": "The CompTIA 6-step Troubleshooting Methodology proceeds in order: (1) Identify the problem, (2) Establish a theory of probable cause, (3) Test the theory to determine cause, (4) Establish a plan of action to resolve the problem and implement the solution, (5) Verify full system functionality and implement preventive measures, and (6) Document findings, actions, and outcomes. After testing and confirming the theory, the technician must establish a plan of action and implement the solution (reseating or replacing the RAM).", "distractor_analysis": {"1": "Documenting findings is Step 6, the final step performed after the issue is fully resolved, verified, and closed.", "2": "Questioning the user is part of Step 1 (Identify the problem), which occurred at the very start of troubleshooting.", "3": "Verifying full system functionality is Step 5, performed after the solution has been implemented in Step 4."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "methodology", "comptia"]}, {"id": "C1-017", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "Firmware routines stored permanently in non-volatile ROM/Flash chips on a motherboard that provide basic low-level hardware abstraction and communication before an OS loads are known as:", "options": ["Power-On Self-Test (POST) diagnostic scripts", "System BIOS / UEFI firmware services", "Complementary Metal-Oxide Semiconductor (CMOS) volatile RAM", "Operating system ring-0 kernel device drivers"], "answer": 1, "explanation": "System BIOS (Basic Input/Output System) and modern UEFI firmware contain firmware routines/services that initialize hardware, provide low-level abstraction, and facilitate early communication between motherboard hardware components before the operating system boots. POST is the diagnostic self-test run by BIOS. CMOS is the small volatile memory that holds user settings. OS device drivers execute after the operating system kernel is initialized.", "distractor_analysis": {"0": "POST is a diagnostic routine executed during startup to verify essential hardware components, not the general firmware interface itself.", "2": "CMOS is the volatile memory chip historically used to store BIOS setup parameters, powered by a coin-cell battery.", "3": "OS device drivers are software modules loaded by the operating system to interact with hardware, not firmware stored on motherboard ROM."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "uefi", "firmware"]}, {"id": "C1-018", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following critical diagnostic programs is stored directly inside the motherboard BIOS/UEFI firmware chip?", "options": ["Central Processing Unit (CPU) silicon die", "CR2032 lithium coin-cell battery", "Real-Time Clock (RTC) crystal oscillator", "Power-On Self-Test (POST)"], "answer": 1, "explanation": "The Power-On Self-Test (POST) is a firmware routine embedded directly within the BIOS/UEFI flash memory chip on the motherboard. Upon power-on, POST verifies system hardware (CPU, RAM, video, keyboard) before handing off control to the bootloader. The CPU is seated in the socket, the CR2032 battery is a physical power cell mounted on the PCB, and the RTC crystal is a discrete timing component.", "distractor_analysis": {"1": "The CPU is a separate microprocessor installed into the motherboard socket, not software contained inside the BIOS firmware chip.", "2": "The CR2032 battery is an external lithium cell mounted on the motherboard to provide continuous power to volatile CMOS/RTC settings.", "3": "The RTC crystal is a physical quartz oscillator on the motherboard circuit board, not a program inside firmware."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "post", "firmware"]}, {"id": "C1-019", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "What is the primary function of the Power-On Self-Test (POST) during computer startup?", "options": ["It supplies regulated +12V DC power to the processor VRM circuits", "It encrypts local storage drive sectors using BitLocker hardware keys", "It conducts initial hardware diagnostic checks before booting the operating system", "It serves as a secondary expansion card to benchmark 3D graphics rendering"], "answer": 2, "explanation": "The primary role of POST is to perform rapid pre-boot hardware diagnostic checks on critical subsystems (CPU registers, system memory, video controller, firmware integrity) to verify system viability before attempting to load the operating system bootloader. POST is firmware, not a graphics card; power is supplied by the PSU/VRM; and disk encryption is handled by BitLocker/TPM.", "distractor_analysis": {"1": "POST is a firmware routine inside BIOS, not an add-in PCIe graphics card used for 3D rendering.", "2": "The power supply unit (PSU) and motherboard voltage regulator modules (VRMs) supply DC power, not POST.", "3": "Storage encryption is managed by disk encryption software and TPM security chips, not basic POST routines."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "post", "hardware", "boot"]}, {"id": "C1-020", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A workstation fails to display any video on screen during power-on, and the motherboard speaker emits a specific series of beep codes. Which subsystem failure is most commonly indicated by pre-video POST beep codes?", "options": ["Operating system partition file system corruption", "Video adapter or system RAM initialization failure", "Missing USB mouse or keyboard device", "Shared network printer offline"], "answer": 3, "explanation": "POST beep codes are designed to signal catastrophic hardware failures that occur before the video display subsystem can be initialized (such as faulty/unseated video adapters, missing/corrupted RAM, or motherboard faults). Missing USB mice or network printers do not halt POST with fatal beep codes, and OS partition corruption occurs later during the bootloader stage with on-screen error messages.", "distractor_analysis": {"1": "Missing USB input devices are either ignored or produce on-screen warning messages once the display initializes, rather than fatal beep codes.", "2": "Network printer issues have no impact on local workstation motherboard POST execution.", "3": "Operating system corruption occurs after POST passes and the BIOS hands control to the drive boot sector."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "post", "beep-codes", "hardware"]}, {"id": "C1-021", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "How does a technician typically enter the UEFI/BIOS Setup utility on a standard PC during power-on?", "options": ["Press and hold the physical power button on the chassis for 30 seconds while running Windows", "Unplug the AC power cord while the system is running and reconnect it immediately", "Type a setup command at the Windows operating system command prompt without administrative rights", "Press the designated manufacturer function key (e.g., F2, F12, or Del) during initial startup"], "answer": 1, "explanation": "Entering the BIOS/UEFI setup utility requires pressing a specific key designated by the motherboard manufacturer (commonly Del, F2, F10, or F12) immediately after powering on the computer before the OS bootloader initializes. Holding the power button forces an emergency hard shutdown. Unplugging power can cause disk corruption. Standard Windows CLI prompts require specific commands and reboot parameters (e.g., shutdown /r /fw).", "distractor_analysis": {"1": "Holding down the power button forces a hard power cutoff, potentially corrupting active disk write operations.", "2": "Disconnecting AC power abruptly causes power loss without entering firmware setup.", "3": "Standard command prompt execution without specific UEFI reboot flags cannot launch firmware menus while Windows is running."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "uefi", "configuration"]}, {"id": "C1-022", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A system administrator needs to prevent unauthorized users in a public computer lab from booting an operating system or accessing local data without authentication. Which firmware security setting should be configured in UEFI/BIOS?", "options": ["Remove the CR2032 CMOS battery from the motherboard", "Change the display refresh rate from 60 Hz to 120 Hz", "Configure a BIOS/UEFI User / Power-On boot password", "Flash the motherboard firmware to a beta version"], "answer": 2, "explanation": "Configuring a User (or Power-On / Boot) password in the BIOS/UEFI setup prevents the computer from loading the operating system or accessing drives until the correct password is entered during POST. Flashing firmware updates code but does not restrict boot access. Removing the CMOS battery resets settings. Display refresh rates only affect monitor scanning speed.", "distractor_analysis": {"1": "Flashing firmware updates code features and security patches, but does not enforce pre-boot authentication.", "2": "Removing the CMOS battery resets volatile firmware settings to factory defaults and disables security passwords on older systems.", "3": "Display refresh rate is a video timing parameter with no relation to boot security or access control."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "security", "passwords"]}, {"id": "C1-023", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "Which firmware security feature built into UEFI environments prevents unauthorized operating systems, bootloaders, and rootkits from executing at startup by verifying digital signatures against trusted keys?", "options": ["Hyper-Threading", "Secure Boot", "Fast Boot", "Wake-on-LAN (WoL)"], "answer": 3, "explanation": "Secure Boot is a UEFI security standard that ensures a system boots using only software and kernel drivers that are trusted by the Original Equipment Manufacturer (OEM), checking digital signatures of bootloaders and option ROMs against stored PKI certificates. Fast Boot skips certain hardware initialization steps to decrease boot times. Wake-on-LAN powers on systems via network magic packets. Hyper-Threading creates logical CPU cores.", "distractor_analysis": {"1": "Fast Boot optimizes boot speed by bypassing full peripheral self-checks, offering no digital signature verification.", "2": "Wake-on-LAN allows a sleeping computer to be powered on remotely via an Ethernet network packet.", "3": "Hyper-Threading is a CPU architectural feature that presents two logical execution threads per physical core."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "uefi", "secure-boot", "security"]}, {"id": "C1-024", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which dedicated hardware microchip installed on modern motherboards securely generates, stores, and protects cryptographic keys, platform certificates, and biometric measurements used for full disk encryption?", "options": ["Real-Time Clock (RTC)", "Complementary Metal-Oxide Semiconductor (CMOS)", "Serial Peripheral Interface (SPI) flash chip", "Trusted Platform Module (TPM)"], "answer": 1, "explanation": "A Trusted Platform Module (TPM) is a dedicated international standard microcontroller designed to provide hardware-based cryptographic operations, secure key generation, platform integrity measurements, and tamper-resistant storage for encryption systems like BitLocker and Measured Boot. The RTC maintains time, CMOS stores legacy settings, and SPI flash holds firmware code.", "distractor_analysis": {"1": "The RTC maintains system time and date, not cryptographic encryption keys.", "2": "CMOS is volatile memory holding legacy configuration data, lacking cryptographic encryption processors.", "3": "The SPI flash chip holds the binary BIOS/UEFI firmware image, not protected cryptographic encryption keys."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "tpm", "security", "encryption"]}, {"id": "C1-025", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A technician flashes the motherboard firmware to the latest version. What is the primary operational benefit and purpose of performing a BIOS/UEFI firmware update?", "options": ["To convert an analog VGA video port into a digital HDMI connector", "To repair physical bad sectors on a mechanical hard drive", "To add support for newer CPU models, improve system stability, and patch firmware security vulnerabilities", "To permanently increase the physical capacity of installed DDR4 RAM modules"], "answer": 2, "explanation": "Firmware updates provide microcode updates to support newly released CPU models, enhance memory timing stability, fix known hardware bugs, and patch firmware-level security vulnerabilities. Firmware cannot change physical hardware dimensions, expand RAM capacity, alter physical video port pinouts, or fix physical platter defects on hard drives.", "distractor_analysis": {"1": "Physical RAM capacity is determined by the memory chips soldered onto the DIMMs, which cannot be expanded by software or firmware.", "2": "Physical video ports and their electrical wiring cannot be modified by updating system firmware.", "3": "Physical platter bad sectors on a hard drive are magnetic hardware defects that cannot be repaired by a motherboard BIOS flash."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "firmware", "upgrade"]}, {"id": "C1-026", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "hard", "question": "Which of the following describes the potential danger of an unexpected power outage occurring midway through a BIOS/UEFI firmware flashing process?", "options": ["The network interface card MAC address will be permanently deleted from the switch", "The motherboard firmware chip may become corrupted, leaving the system in an unbootable bricked state", "The computer's liquid crystal display panel will permanently crack", "The power supply unit will reverse its output polarity and destroy connected USB devices"], "answer": 3, "explanation": "Flashing overwrites the non-volatile EEPROM/flash memory that contains the boot initialization code. If power is interrupted mid-flash, incomplete or corrupt code is written, leaving the motherboard unable to execute POST or boot (bricked), unless the board has a dual-BIOS or dedicated hardware flashback recovery mechanism. Power cuts during flashing do not crack LCDs, invert PSU polarity, or erase network switch MAC tables.", "distractor_analysis": {"1": "Power failure during firmware flashing has no physical or mechanical impact on the LCD display panel.", "2": "Power supplies operate on independent voltage regulation circuitry; a firmware crash cannot invert electrical polarity.", "3": "Network switches dynamically rebuild MAC address tables, and hardware MAC addresses are burned into NIC ROMs, unaffected by motherboard flashing."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "flashing", "troubleshooting"]}, {"id": "C1-027", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A technician is selecting a motherboard form factor for a high-performance datacenter workstation requiring four PCIe 4.0 expansion cards and four memory channels. Which standard desktop motherboard form factor measures 12 x 9.6 inches and provides the maximum expansion slots?", "options": ["Mini-ITX, 170 mm square with a single expansion slot", "MicroATX, 244 mm square with up to four expansion slots", "Nano-ITX, 120 mm square with no expansion slots", "ATX, 305 mm by 244 mm with up to seven expansion slots"], "answer": 1, "explanation": "Standard ATX motherboards measure 12 x 9.6 inches (305 x 244 mm) and typically offer up to seven expansion slots, providing maximum flexibility for multiple GPUs, sound cards, and storage controllers. MicroATX measures 9.6 x 9.6 inches with up to four slots, Mini-ITX measures 6.7 x 6.7 inches with only one slot, and Nano-ITX is an ultra-small embedded form factor.", "distractor_analysis": {"1": "Mini-ITX gives one slot and two DIMMs, so it cannot host four PCIe cards or four memory channels.", "2": "MicroATX tops out at four slots but is usually dual channel, and the four-card build leaves no clearance.", "3": "Nano-ITX is an embedded form factor with no expansion slots at all."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "motherboards", "form-factors", "atx"]}, {"id": "C1-028", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "What is the primary physical dimension and expansion slot limitation of a Mini-ITX motherboard compared to standard ATX?", "options": ["It cannot support 64-bit multi-core processors or solid-state storage", "It uses liquid nitrogen cooling by default instead of standard heatsinks", "It measures 6.7 x 6.7 inches and typically features only a single PCIe expansion slot", "It requires three separate 24-pin ATX main power connectors to boot"], "answer": 2, "explanation": "Mini-ITX motherboards measure 6.7 x 6.7 inches (170 x 170 mm) and are designed for space-constrained, small-form-factor builds, featuring exactly one PCIe expansion slot and usually two RAM slots. Mini-ITX boards use standard 24-pin power connectors, fully support modern 64-bit CPUs and SSDs, and utilize standard air or liquid cooling solutions.", "distractor_analysis": {"1": "Mini-ITX motherboards use a single standard 24-pin ATX power connector (or external DC adapter), not three connectors.", "2": "Mini-ITX boards support standard modern high-performance 64-bit multi-core CPUs and NVMe SSDs.", "3": "Mini-ITX boards utilize standard copper/aluminum heatsinks or all-in-one liquid coolers, not liquid nitrogen."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "motherboards", "mini-itx", "form-factors"]}, {"id": "C1-029", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "Which motherboard component or chipset bus architecture historically managed high-speed communication between the CPU, system RAM, and the primary PCIe x16 graphics slot?", "options": ["Platform Controller Hub legacy serial bridge", "Northbridge controller", "Southbridge controller", "Super I/O controller"], "answer": 3, "explanation": "In traditional PC motherboard chipset architecture, the Northbridge (or Memory Controller Hub) handled high-speed communication between the CPU, RAM, and high-speed PCIe/AGP graphics. (In modern CPUs, these Northbridge functions are fully integrated directly into the processor die). The Southbridge managed slower peripherals (USB, SATA, audio, legacy PCI). The Super I/O chip handles legacy serial, parallel, and sensor interfaces.", "distractor_analysis": {"1": "The Southbridge managed lower-speed peripheral connections, including SATA storage, USB ports, onboard audio, and legacy expansion buses.", "2": "The Super I/O controller manages low-bandwidth legacy ports such as PS/2, serial COM ports, floppy drives, and temperature sensors.", "3": "The Platform Controller Hub (PCH) replaced the Southbridge in modern unified chipset designs."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "chipsets", "northbridge", "architecture"]}, {"id": "C1-030", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which PCIe expansion slot configuration provides the highest raw bandwidth for modern discrete graphics cards and high-speed NVMe RAID adapter cards?", "options": ["PCIe x1 slot", "PCIe x4 slot", "Legacy PCI 32-bit slot", "PCIe x16 slot"], "answer": 1, "explanation": "A PCIe x16 slot contains 16 full-duplex differential data lanes, providing the highest throughput of standard PCIe slot configurations and serving as the universal standard for discrete graphics cards and high-bandwidth expansion adapters. PCIe x1 and x4 slots have fewer lanes and lower total bandwidth. Legacy 32-bit PCI is a slow, obsolete parallel bus sharing 133 MB/s total.", "distractor_analysis": {"1": "PCIe x1 features only one data lane, providing 1/16th of the bandwidth of an x16 slot, typically used for network cards or sound cards.", "2": "PCIe x4 provides four data lanes, commonly used for storage expansion cards and capture cards, but less bandwidth than an x16 slot.", "3": "Legacy 32-bit PCI is an obsolete parallel bus limited to 133 MB/s shared among all devices on the bus."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "pcie", "expansion-cards", "bandwidth"]}, {"id": "C1-031", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A technician is installing an expansion card into a PCIe slot. What physical feature of the PCI Express standard allows a smaller PCIe card (such as a PCIe x4 card) to be installed into a larger physical slot (such as a PCIe x16 slot)?", "options": ["AGP Universal Voltage keying switches", "Direct IDE ribbon cable jumper adaptation", "Up-plugging compatibility in the PCIe serial point-to-point architecture", "PCI parallel bus bridging and termination"], "answer": 2, "explanation": "PCI Express is a serial point-to-point architecture that supports up-plugging: a card with fewer lanes (e.g., x1 or x4) can be physically installed and operated in any slot with equal or greater lane count (e.g., x8 or x16), and the link will automatically negotiate to the card's maximum supported lane width. Parallel bus bridging, AGP voltage keys, and IDE jumpers do not apply to PCI Express.", "distractor_analysis": {"1": "PCIe is a serial point-to-point packetized bus, not a shared parallel bus requiring termination resistors.", "2": "AGP voltage keying was a mechanism used in legacy 1990s AGP slots to prevent 3.3V and 1.5V card mismatches.", "3": "IDE jumpers configured master/slave relationships on legacy parallel ATA ribbon cables, completely unrelated to PCIe."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "pcie", "expansion-slots", "compatibility"]}, {"id": "C1-032", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which motherboard CPU socket architecture features physical spring-loaded contact pins mounted inside the motherboard socket while the underside of the processor has flat gold contact pads?", "options": ["Single Edge Contact Cartridge (SECC)", "Land Grid Array (LGA)", "Pin Grid Array (PGA)", "Ball Grid Array (BGA)"], "answer": 3, "explanation": "In a Land Grid Array (LGA) socket (standard for modern Intel desktop CPUs and AMD AM5 / EPYC / Threadripper processors), the delicate contact pins reside on the motherboard socket itself, while the underside of the CPU features flat gold contact pads (lands). Pin Grid Array (PGA) has pins on the CPU. Ball Grid Array (BGA) is permanently soldered. SECC is an obsolete cartridge format.", "distractor_analysis": {"1": "Pin Grid Array (PGA) sockets have holes that receive physical pins protruding from the bottom of the CPU package.", "2": "Ball Grid Array (BGA) packages are surface-mounted and soldered directly to the motherboard PCB using solder balls.", "3": "Single Edge Contact Cartridge (SECC) is a legacy late-1990s cartridge design used for Pentium II and III processors."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "sockets", "lga", "pga"]}, {"id": "C1-033", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which CPU socket type features physical pins extending from the underside of the CPU package that insert into corresponding pin holes on the motherboard socket and lock via a Zero Insertion Force (ZIF) lever?", "options": ["Land Grid Array (LGA)", "Ball Grid Array (BGA)", "Surface-Mount Device (SMD)", "Pin Grid Array (PGA)"], "answer": 1, "explanation": "In a Pin Grid Array (PGA) design (used by legacy Intel and AMD AM4 processors), the pins are attached to the underside of the CPU package and mate with holes in the motherboard socket, secured with a Zero Insertion Force (ZIF) lever. LGA places the pins on the socket. BGA is soldered to the board. SMD is a generic component mounting classification.", "distractor_analysis": {"1": "Land Grid Array (LGA) features flat contact pads on the processor and pins in the socket, the inverse of PGA.", "2": "Ball Grid Array (BGA) processors are permanently soldered to the motherboard during manufacturing and cannot be replaced via socket levers.", "3": "Surface-Mount Device (SMD) describes electronic components soldered directly to PCB pads, not a CPU socket standard."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "pga", "sockets"]}, {"id": "C1-034", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A technician is installing a server-class CPU onto a high-performance motherboard. What substance must be applied between the top of the CPU integrated heat spreader (IHS) and the base of the heatsink to eliminate microscopic air gaps?", "options": ["Mineral oil immersion fluid", "Cyanoacrylate super glue", "Thermal paste / thermal interface material (TIM)", "Dielectric silicone adhesive sealant"], "answer": 2, "explanation": "Thermal Interface Material (TIM / thermal paste) fills microscopic imperfections and air pockets between the CPU integrated heat spreader (IHS) and the metal base of the heatsink. Because air is a terrible thermal conductor, TIM provides high thermal conductivity to efficiently transfer heat away from the processor. Adhesives, mineral oil, and glue are improper and can destroy hardware.", "distractor_analysis": {"1": "Silicone adhesive sealants are rubberizing insulators that act as thermal barriers and glue components permanently.", "2": "Mineral oil is used in specialized whole-system submersion cooling tanks, not as a concentrated thermal compound between CPU and heatsink.", "3": "Cyanoacrylate glue permanently bonds surfaces, provides poor thermal conduction, and destroys the CPU upon removal."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "cooling", "thermal-paste"]}, {"id": "C1-035", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "Which of the following thermal cooling solutions utilizes a closed loop containing a water block, liquid coolant, a motorized pump, tubing, and an external radiator with fans to dissipate processor heat?", "options": ["Standard passive copper heat pipe array", "All-In-One (AIO) liquid cooling system", "Passive aluminum finned heatsink", "Single-phase phase-change refrigeration compressor"], "answer": 3, "explanation": "An All-In-One (AIO) liquid cooling system circulates liquid coolant through a closed loop: a pump-integrated water block absorbs heat from the CPU, tubes carry the heated fluid to a radiator, and fans blow air across the radiator fins to dissipate heat before returning the cooled liquid to the block. Passive heatsinks and heat pipes rely solely on air convection without pumps or liquid loops.", "distractor_analysis": {"1": "Passive heatsinks rely purely on natural thermal conduction and case airflow without pumps, tubing, or liquid loops.", "2": "Phase-change systems use active vapor-compression refrigeration compressors, which are complex industrial units rarely used in standard PCs.", "3": "Heat pipes use small sealed copper tubes containing a phase-change fluid that evaporates and condenses internally, but lack external pumps and radiators."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cooling", "liquid-cooling", "aio"]}, {"id": "C1-036", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "easy", "question": "What is the primary main power connector used to supply DC power from a modern ATX power supply to the system motherboard?", "options": ["4-pin peripheral Molex connector", "15-pin SATA power connector", "6-pin PCIe auxiliary power cable", "24-pin ATX main power connector (20+4 pin)"], "answer": 1, "explanation": "The 24-pin ATX main power connector (often configured as a 20+4 pin connector for backward compatibility) is the primary electrical harness that delivers +3.3V, +5V, +12V, and -12V DC power from the power supply unit (PSU) to the motherboard. Molex supplies legacy peripherals, SATA powers storage drives, and 6-pin PCIe supplies auxiliary power to graphics cards.", "distractor_analysis": {"1": "The 4-pin Molex connector supplies +12V and +5V to legacy IDE hard drives, optical drives, and case fans.", "2": "The 15-pin SATA power connector supplies power directly to SATA hard drives and optical storage devices.", "3": "The 6-pin PCIe connector provides dedicated auxiliary +12V power directly to high-draw PCIe expansion cards."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "psu", "atx"]}, {"id": "C1-037", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "medium", "question": "A power supply certification program rates PSUs based on energy efficiency under varying workload levels (20%, 50%, and 100% load). Which of the following is the highest 80 PLUS efficiency rating level?", "options": ["80 PLUS Gold", "80 PLUS Bronze", "80 PLUS Titanium", "80 PLUS Platinum"], "answer": 2, "explanation": "The 80 PLUS certification ranks power supply efficiency in ascending order: 80 PLUS (Standard/White) -> Bronze -> Silver -> Gold -> Platinum -> Titanium. 80 PLUS Titanium represents the highest standard, requiring at least 90% to 94% efficiency across all load ranges and including efficiency testing at 10% load.", "distractor_analysis": {"1": "80 PLUS Platinum is the second highest tier (up to 92-94% efficiency), exceeded only by 80 PLUS Titanium.", "2": "80 PLUS Gold is a mid-tier efficiency level (87-90% efficiency), below Platinum and Titanium.", "3": "80 PLUS Bronze is an entry-level efficiency rating (82-85% efficiency), lower than Silver, Gold, Platinum, and Titanium."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "80-plus", "efficiency"]}, {"id": "C1-038", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "medium", "question": "When configuring a dual-voltage power supply on a server shipped from North America (115V) to Europe (230V), what physical component must the technician adjust before plugging into wall power if the PSU lacks active Power Factor Correction (PFC)?", "options": ["The optical drive region code switch", "The red voltage selector slider switch on the rear of the PSU", "The motherboard CMOS clear jumper pins", "The CPU fan speed potentiometer dial"], "answer": 3, "explanation": "On power supplies that feature manual dual-voltage input (lacking auto-switching active PFC), a red slider switch on the rear of the power supply unit toggles between 115V (for North America/Japan) and 230V (for Europe and most other countries). Plugging a PSU set to 115V into a 230V outlet without changing the switch causes immediate catastrophic overvoltage failure and explosive capacitor blowout. CMOS jumpers, fan dials, and region codes do not adjust electrical mains voltage.", "distractor_analysis": {"1": "The CMOS clear jumper resets firmware parameters to default, having no role in electrical voltage rectification.", "2": "Fan speed potentiometers adjust cooling fan RPM, not electrical AC input voltage.", "3": "Optical drive region codes are firmware settings for DVD/Blu-ray playback, unrelated to power supply electronics."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "voltage", "psu"]}, {"id": "C1-039", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "What is the standard physical drive form factor commonly used for traditional 3.5-inch desktop hard disk drives (HDDs) versus 2.5-inch laptop and SATA solid-state drives?", "options": ["5.25-inch form factor for all modern laptop NVMe solid-state storage", "1.8-inch form factor for enterprise 3U datacenter storage enclosures", "M.2 2280 form factor for traditional spinning magnetic platters", "3.5-inch form factor for desktop HDDs and 2.5-inch for laptop/SATA SSDs"], "answer": 1, "explanation": "Standard desktop mechanical hard disk drives use the 3.5-inch form factor, while laptop drives and standard SATA solid-state drives utilize the 2.5-inch form factor. 5.25-inch was used for optical drives and vintage HDDs, 1.8-inch was for ultra-portable legacy media players, and M.2 2280 is a small gumstick form factor for flash memory (not spinning magnetic platters).", "distractor_analysis": {"1": "5.25-inch is the form factor for optical disc drives (DVD/Blu-ray), far too large for any laptop storage.", "2": "1.8-inch drives were micro-drives used in early portable MP3 players and ultra-thin laptops, not enterprise 3U server arrays.", "3": "M.2 2280 is a flash memory card form factor measuring 22x80 mm, incapable of holding spinning mechanical platters."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "form-factors", "hdd", "ssd"]}, {"id": "C1-040", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "Which of the following rotational speeds is a standard spindle speed for high-performance server-class mechanical hard disk drives (HDDs)?", "options": ["45,000 RPM, used in high-density arrays", "100,000 RPM, used in write-cache tiers", "15,000 RPM, with 10,000 and 7,200 also in service", "1,200 RPM, typical of archive-tier media"], "answer": 2, "explanation": "Standard mechanical hard disk drive spindle speeds include 5,400 RPM (energy-efficient laptops/desktops), 7,200 RPM (standard performance desktops), and 10,000 / 15,000 RPM (high-performance enterprise SAS server drives). Speeds such as 1,200 RPM are too slow, and 45,000 or 100,000 RPM are mechanically impossible for HDD magnetic platters without catastrophic disintegration.", "distractor_analysis": {"1": "No production hard drive spins that slowly. Even laptop drives sit at 5,400 RPM.", "2": "45,000 RPM is not a manufactured spindle speed. Mechanical limits stop well below it.", "3": "100,000 RPM is physically implausible for a platter drive. Flash covers that tier instead."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "hdd", "rpm"]}, {"id": "C1-041", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "What is the maximum theoretical interface data transfer speed of the Serial ATA Revision 3.0 (SATA III / 6 Gbps) standard?", "options": ["40 Gbps (approximately 5 GB/s actual throughput)", "6 Gbps (approximately 600 MB/s actual throughput)", "1.5 Gbps (approximately 150 MB/s actual throughput)", "32 Gbps (approximately 4 GB/s actual throughput)"], "answer": 3, "explanation": "The SATA Revision 3.0 (SATA III) specification defines a maximum physical signaling rate of 6 Gbps, which after 8b/10b line encoding yields a maximum uncompressed data throughput of approximately 600 MB/s. SATA I operates at 1.5 Gbps (150 MB/s), SATA II at 3.0 Gbps (300 MB/s), PCIe 3.0 x4 at 32 Gbps (4 GB/s), and Thunderbolt 3/4 at 40 Gbps.", "distractor_analysis": {"1": "1.5 Gbps is the legacy speed of first-generation SATA Revision 1.0 (SATA I).", "2": "32 Gbps is the bandwidth of a PCIe 3.0 x4 M.2 NVMe connection, not SATA III.", "3": "40 Gbps is the bandwidth of Thunderbolt 3 and Thunderbolt 4 external interfaces."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "sata", "bandwidth"]}, {"id": "C1-042", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "Which solid-state drive host communications protocol communicates directly across high-speed PCI Express lanes rather than utilizing the legacy AHCI protocol designed for spinning disks?", "options": ["Advanced Host Controller Interface (AHCI)", "Integrated Drive Electronics (IDE)", "Small Computer System Interface (SCSI-1)", "Non-Volatile Memory Express (NVMe)"], "answer": 1, "explanation": "Non-Volatile Memory Express (NVMe) is an open host controller interface specification engineered from the ground up for solid-state storage. It communicates directly over PCI Express bus lanes, supporting up to 64,000 command queues with 64,000 commands per queue, vastly outperforming legacy AHCI (which was designed for high-latency rotating hard disks and limited to 1 queue of 32 commands).", "distractor_analysis": {"1": "AHCI was developed for spinning mechanical SATA drives and is bottlenecked by single command queues and SATA bus bandwidth limits.", "2": "IDE is an obsolete 1980s/1990s parallel ATA storage interface limited to 133 MB/s.", "3": "SCSI-1 is a legacy 1986 parallel storage standard, completely unrelated to modern PCIe solid-state drives."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "nvme", "ssd", "pcie"]}, {"id": "C1-043", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "Among the following storage interfaces, which provides the fastest maximum throughput and lowest latency by communicating directly across dedicated PCIe lanes?", "options": ["External eSATA 3 Gbps hard disk drive", "USB 2.0 HighSpeed external flash drive", "PCIe NVMe M.2 solid-state drive", "SATA Revision 3.0 2.5-inch solid-state drive"], "answer": 2, "explanation": "PCIe NVMe M.2 drives communicate directly over PCIe lanes (e.g., PCIe 4.0 x4 provides ~7,000 MB/s, and PCIe 5.0 x4 provides ~14,000 MB/s), making NVMe orders of magnitude faster than SATA III (capped at 600 MB/s), eSATA (capped at 300-600 MB/s), and USB 2.0 (capped at 60 MB/s).", "distractor_analysis": {"1": "SATA Revision 3.0 is capped at a maximum throughput of 6 Gbps (~600 MB/s), far slower than PCIe NVMe.", "2": "eSATA is an external SATA interface limited to 3 or 6 Gbps bandwidth.", "3": "USB 2.0 is an old external bus limited to a theoretical maximum of 480 Mbps (~48 MB/s practical throughput)."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "nvme", "performance"]}, {"id": "C1-044", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "Which server storage interface combines the command set and reliability of SCSI with the point-to-point serial physical interface compatible with SATA drive bays?", "options": ["Enhanced IDE (EIDE)", "Serial Attached SCSI (SAS)", "Parallel ATA (PATA)", "Fibre Channel over IP (FCIP)"], "answer": 3, "explanation": "Serial Attached SCSI (SAS) is an enterprise point-to-point serial storage interface that transmits SCSI commands over high-speed serial links (supporting 12 Gbps or 24 Gbps). SAS backplanes are backward-compatible with SATA drives, allowing enterprise systems to mix high-performance SAS drives and cost-effective SATA drives in the same enclosure. PATA and EIDE are legacy ribbon-cable interfaces, and FCIP is a SAN tunneling protocol.", "distractor_analysis": {"1": "Parallel ATA (PATA) is an obsolete 40-pin or 80-conductor parallel ribbon cable interface.", "2": "FCIP is a storage networking protocol used to encapsulate Fibre Channel frames inside TCP/IP packets across WANs.", "3": "Enhanced IDE (EIDE) is an early 1990s standard that expanded original IDE storage limits to 8.4 GB."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "sas", "scsi", "enterprise"]}, {"id": "C1-045", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "What storage networking protocol encapsulates SCSI storage commands directly inside standard TCP/IP packets to allow servers to access remote block-level SAN storage over Ethernet networks?", "options": ["Dynamic Host Configuration Protocol (DHCP)", "Simple Mail Transfer Protocol (SMTP)", "Hypertext Transfer Protocol Secure (HTTPS)", "Internet Small Computer System Interface (iSCSI)"], "answer": 1, "explanation": "iSCSI (Internet Small Computer System Interface) encapsulates SCSI command blocks within standard IP packets (typically over TCP port 3260), allowing client initiators to attach to remote storage targets over standard Ethernet networks and treat them as local block devices. DHCP assigns IP addresses, SMTP transfers emails, and HTTPS serves encrypted web pages.", "distractor_analysis": {"1": "DHCP is a network service that dynamically distributes IP addresses and subnet masks to network clients.", "2": "SMTP is an application-layer protocol used to transmit email between mail servers over TCP port 25.", "3": "HTTPS is an encrypted web protocol used to deliver secure web content to browsers over TCP port 443."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "storage", "iscsi", "san", "protocols"]}, {"id": "C1-046", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "Which storage device classification contains no moving mechanical parts, resulting in silent operation, lower power consumption, and extreme resistance to physical shock?", "options": ["Digital Versatile Disc (DVD) drive", "Magnetic tape backup drive", "Solid-State Drive (SSD)", "Hard Disk Drive (HDD)"], "answer": 2, "explanation": "Solid-State Drives (SSDs) use non-volatile NAND flash memory chips and electronic controllers without any spinning platters, spindle motors, or mechanical actuator arms. This makes SSDs completely silent, fast, energy-efficient, and highly resistant to physical shocks and vibration. HDDs, optical drives, and magnetic tape drives all rely on mechanical motors and moving parts.", "distractor_analysis": {"1": "Mechanical hard disk drives contain spinning magnetic platters and actuator read/write heads vulnerable to physical drops and vibration.", "2": "DVD optical drives utilize rotating spindle motors and optical laser pickup sleds with moving parts.", "3": "Magnetic tape drives use mechanical reels and capstans to physically wind tape across magnetic read heads."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "ssd", "nand"]}, {"id": "C1-047", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "What is the primary operational advantage of implementing a Redundant Array of Independent Disks (RAID) in server storage?", "options": ["To convert SATA storage drives into high-voltage AC electrical generators", "To provide fault tolerance, data redundancy, and increased read/write performance", "To eliminate the need for regular off-site and cloud data backups", "To permanently increase the rotational speed of installed magnetic drive spindles"], "answer": 3, "explanation": "RAID combines multiple physical disk drives into a single logical unit to achieve data redundancy/fault tolerance (protecting against drive failure) and/or increased performance (striping I/O across multiple spindles/channels). However, RAID is not a backup solution. RAID cannot modify physical drive spindle speeds or generate electricity.", "distractor_analysis": {"1": "RAID provides high availability against drive hardware failures, but does not protect against malware, accidental deletion, or disaster; backups remain essential.", "2": "RAID is a logical drive controller configuration; it cannot alter the physical rotational speed of hard drive spindle motors.", "3": "Storage drives consume DC power and cannot function as electrical generators."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "fault-tolerance"]}, {"id": "C1-048", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "Which RAID configuration stripes data across two or more drives to maximize read/write performance but provides ZERO fault tolerance or data redundancy?", "options": ["RAID 1 (Disk Mirroring)", "RAID 5 (Striping with Distributed Parity)", "RAID 10 (Striped Mirrors)", "RAID 0 (Disk Striping)"], "answer": 1, "explanation": "RAID 0 (Disk Striping) divides data across two or more physical drives without parity or mirroring, maximizing read and write throughput and utilizing 100% of raw disk capacity. However, if any single drive in the array fails, all data across the entire volume is lost. RAID 1, 5, and 10 all provide fault tolerance.", "distractor_analysis": {"1": "RAID 1 duplicates (mirrors) identical data across two drives, providing complete 1-drive fault tolerance.", "2": "RAID 5 stripes data and distributed parity across three or more drives, tolerating the failure of one single drive.", "3": "RAID 10 combines mirroring and striping across at least four drives, tolerating drive failures in redundant pairs."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "raid0"]}, {"id": "C1-049", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "A technician needs to configure a storage volume using two identical hard drives that provides complete data redundancy so that if one drive fails, the system continues running without data loss. Which RAID level should be deployed?", "options": ["RAID 5 (Distributed Parity)", "JBOD (Just a Bunch of Disks)", "RAID 1 (Disk Mirroring)", "RAID 0 (Disk Striping)"], "answer": 2, "explanation": "RAID 1 (Disk Mirroring) writes identical copies of all data simultaneously to two separate physical drives. If either drive suffers a hardware failure, the remaining drive continues to service all read and write requests with zero downtime or data loss. RAID 0 provides no redundancy, RAID 5 requires at least three drives, and JBOD simply concatenates drives without redundancy.", "distractor_analysis": {"1": "RAID 0 offers no fault tolerance; the failure of either drive destroys all data on the volume.", "2": "RAID 5 requires a minimum of three physical drives to calculate distributed parity, so it cannot be deployed on two drives.", "3": "JBOD simply spans storage capacity across separate drives without providing any data redundancy or fault tolerance."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "raid1"]}, {"id": "C1-050", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "What is the minimum number of physical hard drives required to create a RAID 5 array with distributed parity?", "options": ["8 physical drives", "3 physical drives", "1 physical drive", "2 physical drives"], "answer": 3, "explanation": "RAID 5 (Striping with Distributed Parity) requires a minimum of 3 physical hard drives. Data and parity information are striped across all drives in the array, allowing the array to survive the total failure of any single drive without data loss. RAID 0/1 requires 2 drives, and a single drive cannot form a redundant array.", "distractor_analysis": {"1": "A single drive cannot form a RAID array; it represents a single standalone disk with no redundancy.", "2": "Two drives can form RAID 0 or RAID 1, but cannot support RAID 5 because distributed parity calculations require at least three members.", "3": "Eight drives can be used in large RAID 5 or RAID 6 arrays, but the minimum required drive count for RAID 5 is 3."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "raid5"]}, {"id": "C1-051", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "In a software RAID implementation, which system components handle array management, stripe calculations, and parity operations?", "options": ["The onboard microcontrollers inside the individual drives", "A dedicated PCIe hardware RAID controller card", "The motherboard chipset hardware RAID controller", "The host operating system kernel and system CPU"], "answer": 1, "explanation": "Software RAID relies directly on the host operating system kernel (such as Windows Storage Spaces or Linux mdadm) and the system CPU to process drive striping, mirroring, and parity calculations without requiring a specialized hardware controller. Dedicated expansion cards and motherboard chipset RAID are forms of hardware/firmware RAID, and storage drives lack built-in array management.", "distractor_analysis": {"0": "Dedicated PCIe RAID expansion cards perform hardware RAID using onboard cache and dedicated ASIC processors, offloading the CPU.", "1": "Motherboard chipset RAID is firmware-based hardware RAID managed at the BIOS/UEFI level before OS boot.", "3": "Individual hard drives have internal disk controllers for motor and head timing, not multi-drive array management engines."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "software-raid"]}, {"id": "C1-052", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which dedicated physical security microchip on a motherboard securely stores encryption keys for full-disk encryption technologies such as Microsoft BitLocker?", "options": ["System Management Controller (SMC)", "Real-Time Clock (RTC)", "Trusted Platform Module (TPM)", "Master Boot Record (MBR)"], "answer": 2, "explanation": "A Trusted Platform Module (TPM) is a dedicated cryptographic hardware chip on the motherboard that securely stores BitLocker volume encryption keys, platform integrity measurements, and certificates. MBR is a legacy partition table format, SMC is an Apple power/thermal controller, and RTC is the system clock.", "distractor_analysis": {"1": "The Master Boot Record (MBR) is the first sector of a partitioned storage drive that contains partition tables and boot code, not a crypto chip.", "2": "The System Management Controller (SMC) is a microcontroller on older Mac hardware that manages power and fans, not a TPM cryptographic chip.", "3": "The Real-Time Clock (RTC) maintains current date and time on the motherboard, lacking cryptographic storage capabilities."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "tpm", "security", "bitlocker"]}, {"id": "C1-053", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "Which of the following symptoms is most commonly caused by corrupt operating system boot files or a damaged system registry during startup?", "options": ["The system BIOS automatically changing its hardware boot device order priority", "A sudden decrease in physical cooling fan rotational speed", "Continuous system reboot loop (boot loop) or kernel panic before reaching the desktop", "Loud physical metallic clicking and grinding sounds coming from the drive chassis"], "answer": 2, "explanation": "When critical operating system kernel files, driver binaries, or system registry hives become corrupted, the OS fails to initialize and triggers a blue screen / kernel panic, causing the computer to enter a continuous reboot loop. Loud clicking indicates physical mechanical hard drive head failure. BIOS boot order is stored in NVRAM/CMOS. Fan speed is managed by motherboard thermal sensors.", "distractor_analysis": {"1": "Loud clicking (the 'click of death') indicates a severe mechanical actuator arm or spindle motor failure inside a physical hard drive.", "2": "UEFI/BIOS boot order is controlled by motherboard firmware settings, which do not spontaneously change due to corrupted OS files.", "3": "Cooling fan RPM is regulated by hardware PWM controllers based on thermal sensor readings, not OS file corruption."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "os", "boot-loop", "hardware"]}, {"id": "C1-054", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which of the following is NOT a standard USB transfer speed defined in official USB specifications?", "options": ["12 Mbps (USB 1.1 Full Speed)", "480 Mbps (USB 2.0 HighSpeed)", "5 Gbps (USB 3.2 Gen 1 SuperSpeed)", "1.1 Gbps transfer speed"], "answer": 3, "explanation": "1.1 Gbps is a non-existent, fictitious specification. Standard USB specification speeds include 1.5 Mbps (Low Speed), 12 Mbps (Full Speed USB 1.1), 480 Mbps (HighSpeed USB 2.0), 5 Gbps (SuperSpeed USB 3.0 / 3.2 Gen 1), 10 Gbps (SuperSpeed+ USB 3.2 Gen 2), 20 Gbps (USB 3.2 Gen 2x2), and 40/80 Gbps (USB4).", "distractor_analysis": {"0": "12 Mbps is the official transfer rate for USB 1.1 Full Speed devices.", "1": "480 Mbps is the maximum theoretical signaling rate for USB 2.0 HighSpeed connections.", "2": "5 Gbps is the official transfer rate for USB 3.0 / USB 3.2 Gen 1 SuperSpeed."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "usb", "bandwidth"]}, {"id": "C1-055", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "In a PC architecture, what dedicated motherboard hardware component manages communication between the CPU and all connected USB devices and root hubs?", "options": ["Analog audio Digital-to-Analog Converter (DAC)", "USB Host Controller (e.g., xHCI or EHCI)", "USB downstream peripheral Type-B port", "Dedicated hardware GPU frame buffer"], "answer": 3, "explanation": "The USB Host Controller (such as xHCI for USB 3.x/4 or EHCI for USB 2.0) is the hardware engine inside the chipset or CPU that interfaces between the system bus and USB root hubs, managing packet scheduling, bandwidth allocation, and device communication. A Type-B port is a physical socket on peripherals, a GPU frame buffer holds display frames, and a DAC processes audio.", "distractor_analysis": {"1": "A USB Type-B port is a physical connector located on downstream peripheral devices like printers, not a motherboard controller.", "2": "A GPU frame buffer is specialized video memory holding raster images for display output.", "3": "An audio DAC converts digital sound streams to analog signals for speakers and headphones."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "usb", "controllers", "architecture"]}, {"id": "C1-056", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "When connecting standard modern USB peripherals (such as USB mice, keyboards, and flash drives) to a Windows 11 PC, why do they function immediately without manual installation media?", "options": ["Every USB device contains a hardware TPM security processor", "USB cables use fiber-optic laser signaling to bypass device drivers", "The system motherboard flashes its BIOS firmware automatically", "Windows includes pre-installed generic inbox class drivers (HID, Mass Storage)"], "answer": 1, "explanation": "Modern operating systems like Windows include extensive libraries of native 'inbox' class drivers (e.g., USB Human Interface Device/HID, USB Mass Storage, and USB Audio) that automatically recognize standard compliant USB devices and bind drivers without requiring external vendor media. USB devices do not require TPMs, use standard copper wiring, and do not trigger BIOS flashes.", "distractor_analysis": {"1": "TPM microchips are security processors on motherboards, not hardware required inside basic USB mice and keyboards.", "2": "Standard USB peripherals use copper wires for electrical signaling and DC power, requiring OS software drivers.", "3": "Connecting a USB peripheral does not re-flash motherboard BIOS firmware."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "usb", "drivers", "plug-and-play"]}, {"id": "C1-057", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which of the following is NOT a standard maximum bandwidth specification for any generation of the Thunderbolt interface?", "options": ["30 Gbps transfer speed", "10 Gbps (Thunderbolt 1)", "20 Gbps (Thunderbolt 2)", "40 Gbps (Thunderbolt 3 and Thunderbolt 4)"], "answer": 2, "explanation": "30 Gbps is not a valid Thunderbolt specification speed. Thunderbolt 1 supports 10 Gbps per channel (20 Gbps total), Thunderbolt 2 aggregates channels to 20 Gbps, Thunderbolt 3 and Thunderbolt 4 support 40 Gbps bidirectional bandwidth, and Thunderbolt 5 supports up to 80/120 Gbps.", "distractor_analysis": {"0": "10 Gbps is the native per-channel data rate of Thunderbolt 1.", "1": "20 Gbps is the aggregated bidirectional bandwidth of Thunderbolt 2.", "2": "40 Gbps is the standard certified bandwidth of Thunderbolt 3 and Thunderbolt 4."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "thunderbolt", "bandwidth"]}, {"id": "C1-058", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "What is the standard audio and data capacity of a standard 700 MB Compact Disc (CD-ROM)?", "options": ["120 minutes of dual-layer DVD video", "80 minutes of uncompressed audio (or 700 MB data)", "4.7 gigabytes of uncompressed audio", "25 gigabytes of high-definition video"], "answer": 3, "explanation": "Standard Compact Discs (CD-ROM/CD-R) have a standard capacity of 700 MB of data or 80 minutes of uncompressed Red Book audio (early CDs were 650 MB / 74 minutes). 4.7 GB is the capacity of a single-layer DVD, 25 GB is a single-layer Blu-ray Disc, and 120 minutes / 8.5 GB is a dual-layer DVD.", "distractor_analysis": {"1": "4.7 GB is the storage capacity of a standard single-layer DVD-ROM, not a CD.", "2": "25 GB is the storage capacity of a standard single-layer Blu-ray disc (BD-ROM).", "3": "8.5 GB / dual-layer storage is characteristic of DVD-9 (DVD-R DL) media."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "optical", "cd-rom"]}, {"id": "C1-059", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "In personal computing and workstation terminology, peripheral devices are categorized based on their functional data flow into which two primary classifications?", "options": ["Primary storage and secondary cache", "Input devices and output devices", "Static devices and dynamic devices", "Analog modulators and digital demodulators"], "answer": 3, "explanation": "Peripheral devices are broadly categorized by data direction: Input devices (keyboards, mice, scanners, microphones, cameras) send data into the computer, while Output devices (monitors, printers, speakers) present data from the computer to the external environment. Some peripherals (touchscreens, multi-function printers) are hybrid input/output devices.", "distractor_analysis": {"1": "'Static and dynamic' are electronic circuit classifications (such as SRAM vs DRAM), not peripheral categories.", "2": "Modulators and demodulators are signal conversion components inside modems.", "3": "Primary storage and secondary cache refer to RAM and CPU cache memory hierarchies."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "peripherals", "input-output"]}, {"id": "C1-060", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "easy", "question": "During a remote collaboration conference, a presenter broadcasts their active desktop workspace in real time to all remote participants. What technology enables this feature?", "options": ["DisplayPort Multi-Stream Transport daisy-chaining", "Dynamic Domain Name System record registration", "Hardware Overclocking Voltage Stepping", "Real-time screen sharing / desktop presentation"], "answer": 1, "explanation": "Screen sharing (remote desktop broadcasting) captures the graphical frame buffer of the presenter's operating system, compresses the video stream, and transmits it across the network to videoconferencing clients in real time. DisplayPort MST is a physical monitor cable standard, DDNS is a DNS record mapping tool, and voltage stepping regulates CPU power.", "distractor_analysis": {"1": "DisplayPort MST is a hardware standard for chaining multiple physical monitors to a single DisplayPort output, not software remote streaming.", "2": "DDNS automatically updates DNS hostname records when an IP address changes.", "3": "Voltage stepping alters CPU core voltage to regulate clock speed and power consumption."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "display", "collaboration", "software"]}, {"id": "C1-061", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Modern high-performance discrete graphics processing units (GPUs) are installed into which type of motherboard expansion slot to provide maximum bandwidth to the CPU and RAM?", "options": ["ATX 24-pin power socket", "SATA Revision 3.0 header", "PCIe x16 slot", "Legacy 32-bit PCI slot"], "answer": 2, "explanation": "Modern discrete graphics cards require high bandwidth and low latency, connecting to the primary PCIe x16 slot, which connects directly to the CPU's dedicated PCIe controller lanes. Legacy PCI slots provide inadequate bandwidth (133 MB/s), ATX sockets supply power to motherboards, and SATA headers connect storage drives.", "distractor_analysis": {"1": "Legacy 32-bit PCI is an obsolete parallel bus limited to 133 MB/s, completely unable to support modern 3D graphics bandwidth.", "2": "The ATX 24-pin power socket delivers electrical power from the PSU to the motherboard, not a data expansion slot.", "3": "SATA headers connect storage drives (HDDs/SSDs) and cannot accept graphics expansion cards."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "gpu", "pcie", "expansion-cards"]}, {"id": "C1-062", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "easy", "question": "Which of the following display illumination technologies is used as a backlight source for standard modern Liquid Crystal Display (LCD) computer monitors?", "options": ["Cathode Ray Tube (CRT) electron guns", "Light-Emitting Diode (LED) arrays", "Organic Light-Emitting Diode (OLED) self-emissive pixels", "Incandescent halogen reflector bulbs"], "answer": 3, "explanation": "Modern LCD monitors use Light-Emitting Diodes (LEDs) arranged either along the edges (edge-lit) or in a grid behind the panel (direct/full-array LED) as their backlight light source. In contrast, OLED displays are self-emissive (each pixel produces its own light without any separate backlight), halogen bulbs are for projectors, and CRTs use electron guns.", "distractor_analysis": {"1": "OLED panels are self-emissive displays where individual organic diodes emit light directly; they do not use a separate backlight panel.", "2": "Incandescent halogen bulbs are high-heat lamps used in commercial stage lighting and overhead projectors.", "3": "CRT electron guns fire electron beams at a phosphorescent glass screen, an obsolete pre-flat-panel display technology."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "display", "led", "lcd", "backlight"]}, {"id": "C1-063", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Which video projection technology utilizes a semiconductor Digital Micromirror Device (DMD) containing millions of microscopic tilting aluminum mirrors to project images?", "options": ["Liquid Crystal on Silicon (LCoS)", "Cold Cathode Fluorescent Lamp (CCFL)", "Active Matrix Organic LED (AMOLED)", "Digital Light Processing (DLP)"], "answer": 1, "explanation": "Digital Light Processing (DLP), originally developed by Texas Instruments, uses a Digital Micromirror Device (DMD) optical semiconductor chip containing millions of microscopic hinged mirrors that tilt rapidly toward or away from a light source through a spinning color wheel to project crisp images. CCFL is a fluorescent backlight tube, and AMOLED is a flat-panel display.", "distractor_analysis": {"1": "LCoS uses liquid crystals applied on a reflective silicon backplane without mechanical tilting micromirrors.", "2": "CCFL is a legacy glass fluorescent tube used to backlight older LCD monitors.", "3": "AMOLED is a solid-state active-matrix organic LED display panel used in smartphones and premium televisions."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "display", "projectors", "dlp"]}, {"id": "C1-064", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "What term describes a microprocessor package that integrates both the Central Processing Unit (CPU) cores and a Graphics Processing Unit (GPU) onto a single silicon die?", "options": ["High-Definition Multimedia Interface (HDMI) decoder", "Digital Visual Interface (DVI) multiplexer", "Accelerated Processing Unit (APU) / Integrated Graphics Processor", "Video Graphics Array (VGA) analog transceiver"], "answer": 2, "explanation": "An Accelerated Processing Unit (APU, AMD's branding) or CPU with Integrated Graphics (Intel HD/UHD/Iris Graphics) integrates both the central processor cores and graphics execution units onto the same physical silicon die. VGA, HDMI, and DVI are external video connector and cabling standards.", "distractor_analysis": {"1": "VGA is an analog 15-pin video connector standard dating back to 1987, not a combined CPU/GPU processor.", "2": "HDMI is a proprietary digital audio/video interface standard for connecting displays and audiovisual equipment.", "3": "DVI is a digital display interface standard, not an integrated processor architecture."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "gpu", "apu", "integrated-graphics"]}, {"id": "C1-065", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "After physically installing a new discrete PCIe graphics card and connecting the monitor, which of the following is NOT a valid operating system configuration step performed in Windows?", "options": ["Configuring multi-monitor layout and display refresh rate in Windows", "Manually adjusting PCIe motherboard electrical wattage in Windows Display Settings", "Installing the latest OEM manufacturer graphics device drivers", "Setting the desktop display resolution to the monitor native resolution"], "answer": 3, "explanation": "PCIe slot electrical wattage delivery (+12V and +3.3V up to 75W from the slot) is governed by physical hardware electrical design and ATX power specifications; it cannot be manually adjusted through Windows Display Settings. Installing vendor graphics drivers, configuring native resolution, and setting refresh rates are standard post-installation procedures.", "distractor_analysis": {"1": "Installing manufacturer drivers is essential to enable hardware 3D acceleration, CUDA/OpenCL support, and control panel features.", "2": "Configuring the display to its native resolution ensures the sharpest possible image without scaling artifacts.", "3": "Adjusting monitor arrangement, scaling, and refresh rate in Windows Display Settings is standard for optimal viewing."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "gpu", "display", "windows", "troubleshooting"]}, {"id": "C1-066", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "easy", "question": "When configuring a ceiling-mounted optical projector that displays a distorted, trapezoidal image because the projector is angled relative to the screen, which setting adjusts the image geometry back to a rectangle?", "options": ["Optical threading", "CRT degaussing coil", "Color temperature Kelvin calibration", "Keystone correction"], "answer": 1, "explanation": "Keystone correction digitally or optically adjusts the trapezoidal distortion that occurs when a projector lens is tilted at an angle relative to the flat projection surface, squaring the projected image into a true rectangle. Optical threading is a fictitious term, degaussing is for CRT monitors, and color temperature adjusts white balance.", "distractor_analysis": {"1": "Optical threading is a made-up term that has no meaning in video projector configuration.", "2": "Degaussing eliminates stray magnetic fields from cathode ray tube (CRT) glass monitors, not used in digital projectors.", "3": "Color temperature adjusts the warmth or coolness of white tones on screen, but does not alter geometric image trapezoid distortion."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "projectors", "keystone"]}, {"id": "C1-067", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "In a standard IEEE 802.3 Ethernet frame, which trailing field contains a 32-bit cyclic redundancy check (CRC) checksum used by the receiver to detect bit errors during transmission?", "options": ["EtherType / Length field", "Preamble and Start Frame Delimiter (SFD)", "Frame Check Sequence (FCS)", "Destination MAC address"], "answer": 2, "explanation": "The Frame Check Sequence (FCS) is the 4-byte (32-bit) field located at the very end of an Ethernet frame. It contains a Cyclic Redundancy Check (CRC) value calculated by the transmitting station; the receiver calculates its own CRC on the received frame and drops the frame if the values do not match. Destination MAC is at the start of the header, EtherType identifies the Layer 3 protocol, and the Preamble synchronizes clock timing.", "distractor_analysis": {"1": "The Destination MAC address is the first 6-byte addressing field located at the start of the Ethernet header.", "2": "The EtherType field indicates the encapsulated Layer 3 protocol (e.g., 0x0800 for IPv4) within the payload.", "3": "The Preamble is a 7-byte pattern of alternating 1s and 0s at the start of the frame used for physical layer clock synchronization."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ethernet", "frames", "fcs", "crc"]}, {"id": "C1-068", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "How many total bits make up a standard IEEE 802 Layer 2 Media Access Control (MAC) physical address?", "options": ["128 bits (16 bytes, formatted in hexadecimal hextets)", "48 bits (6 bytes, typically written as 12 hexadecimal digits)", "32 bits (4 bytes, formatted in dotted decimal)", "64 bits (8 bytes, formatted in binary chunks)"], "answer": 3, "explanation": "A MAC address is a 48-bit (6-byte) physical hardware address burned into the network interface card (NIC). The first 24 bits represent the Organizationally Unique Identifier (OUI) assigned to the manufacturer, and the remaining 24 bits represent the unique device serial number. 32 bits is an IPv4 address, and 128 bits is an IPv6 address.", "distractor_analysis": {"1": "32 bits is the length of an Internet Protocol version 4 (IPv4) logical address.", "2": "64 bits is the length of an IPv6 interface identifier (EUI-64) or 64-bit CPU register.", "3": "128 bits is the total length of an Internet Protocol version 6 (IPv6) address."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "mac-address", "layer-2", "addressing"]}, {"id": "C1-069", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "Which legacy Layer 1 network device operates as a multiport repeater, blindly repeating electrical signals received on one port out to all other connected ports and creating a single shared collision domain?", "options": ["Managed Layer 2 Switch", "Layer 3 Network Router", "Hardware Load Balancer", "Legacy Network Hub"], "answer": 1, "explanation": "A legacy network hub operates at Layer 1 (Physical layer) without inspecting MAC addresses or frame contents. Any electrical signal received on one port is broadcast out to every other port, creating a single shared collision domain and causing frequent packet collisions under load. Switches isolate collision domains using MAC tables, routers segment broadcast domains, and load balancers distribute application traffic.", "distractor_analysis": {"1": "A switch operates at Layer 2, maintaining a MAC address table to forward frames only to the specific port connected to the destination device.", "2": "A router operates at Layer 3, forwarding packets between different subnets based on IP routing tables.", "3": "A load balancer distributes incoming network traffic across multiple backend servers based on application health and performance metrics."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "devices", "hub", "switch", "collision-domain"]}, {"id": "C1-070", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "How does a Layer 2 Ethernet switch dynamically build and maintain its MAC address forwarding table (CAM table)?", "options": ["An administrator must manually enter every workstation MAC address via the CLI console", "It queries the local DNS server database to resolve IP addresses to physical ports", "It inspects the source MAC address of incoming frames on each port and maps them to that port", "It broadcasts continuous ARP queries to every connected host every five seconds"], "answer": 2, "explanation": "A Layer 2 switch dynamically builds its Content Addressable Memory (CAM / MAC address) table by examining the source MAC address of every incoming frame received on each physical switch port. It records the MAC address and associating port with a timestamp, allowing future frames destined for that MAC to be forwarded directly out that specific port rather than flooded. Manual entry is for static MACs, and DNS resolves hostnames, not switch ports.", "distractor_analysis": {"1": "Switches do not broadcast ARP queries to build MAC tables; host computers send ARP requests to resolve IP-to-MAC mappings.", "2": "While static MAC entries can be configured, switches learn MAC addresses automatically and dynamically without manual configuration.", "3": "DNS servers translate domain names into IP addresses and have no communication with Layer 2 switch CAM tables."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "switch", "mac-table", "cam-table", "layer-2"]}, {"id": "C1-071", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "At Layer 3 of the OSI model, how are individual network interfaces and subnets uniquely identified across a Wide Area Network (WAN)?", "options": ["Storage volume Serial Attached SCSI LUNs", "Logical IP addresses (IPv4 / IPv6)", "Physical Layer 2 MAC hardware addresses", "Motherboard BIOS UUID identifiers"], "answer": 3, "explanation": "At Layer 3 (Network layer), devices and networks are identified by logical IP addresses (IPv4 and IPv6), which allow routers to forward packets across Wide Area Networks (WANs) and the Internet. MAC addresses operate at Layer 2 within local broadcast domains, BIOS UUIDs identify computer motherboards, and SCSI LUNs identify SAN storage volumes.", "distractor_analysis": {"1": "MAC addresses are physical Layer 2 hardware identifiers that do not traverse routers or route across WAN boundaries.", "2": "BIOS UUIDs are unique hardware identifiers used by system management tools, not routable network addresses.", "3": "SCSI LUNs are logical unit numbers identifying block storage partitions in a SAN array."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ip-addressing", "layer-3", "wan"]}, {"id": "C1-072", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "Which dedicated network device operates at Layer 3 to route data packets between different IP subnets and separate broadcast domains?", "options": ["Unmanaged Ethernet Switch", "Layer 1 Repeater / Hub", "Patch Panel", "Network Router"], "answer": 1, "explanation": "A router is a Layer 3 network device that maintains routing tables to forward IP packets between distinct logical networks (subnets) and separate broadcast domains. Layer 2 switches forward traffic within a local broadcast domain, repeaters/hubs amplify electrical signals at Layer 1, and patch panels are passive cable termination fixtures.", "distractor_analysis": {"1": "An unmanaged switch forwards frames within a single local broadcast domain based on MAC addresses, unable to route across IP subnets.", "2": "A repeater/hub operates at Layer 1 to regenerate physical electrical signals without understanding IP addresses or routing.", "3": "A patch panel is a passive hardware assembly containing RJ-45 jacks used for structured cable termination."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "devices", "router", "layer-3"]}, {"id": "C1-073", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "Which term describes a fire-safety rating for network cable jackets that produce low smoke and non-toxic fumes when burning, allowing installation in building air-handling spaces?", "options": ["Shielded Twisted Pair (STP)", "Coaxial RG-6 cabling", "Plenum-rated (CMP) cabling", "Unshielded Twisted Pair (UTP)"], "answer": 2, "explanation": "Plenum-rated (CMP) cabling is coated with a specialized fire-retardant jacket (such as FEP or low-smoke PVC) designed to resist fire and emit minimal smoke and non-toxic fumes when exposed to flame, making it mandatory by building fire codes for use in plenum air-handling spaces (dropped ceilings and raised floors). UTP, STP, and coax are physical cable constructions, not fire safety ratings.", "distractor_analysis": {"1": "UTP describes the internal twisted copper pair construction lacking foil shielding, which can be jacketed in either PVC or plenum materials.", "2": "STP describes twisted pair cable with braided or foil shielding against electromagnetic interference, regardless of its jacket fire rating.", "3": "Coaxial RG-6 describes a cylindrical copper cable with a center conductor, dielectric insulator, and braided shield."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cabling", "plenum", "safety", "fire-rating"]}, {"id": "C1-074", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "What is the primary light source commonly used in short-to-medium distance Multimode Fiber (MMF) optical network transceivers (such as 1000BASE-SX)?", "options": ["Ultraviolet gas discharge quartz tubes", "Light-Emitting Diodes (LEDs) or Vertical-Cavity Surface-Emitting Lasers (VCSELs)", "High-power long-wavelength infrared laser diodes", "Incandescent tungsten-halogen filaments"], "answer": 3, "explanation": "Multimode Fiber (MMF) optic cables feature a larger core diameter (50 or 62.5 microns) and typically utilize cost-effective LEDs or Vertical-Cavity Surface-Emitting Lasers (VCSELs) operating at 850 nm wavelengths for short-to-medium distance campus/datacenter runs. Long-wavelength single-mode lasers are used for long-haul Single-Mode Fiber (SMF), while incandescent bulbs and UV tubes cannot generate high-frequency optical network signals.", "distractor_analysis": {"1": "High-power long-wavelength (1310 nm / 1550 nm) lasers are used for Single-Mode Fiber (SMF) for long-haul telecommunication links.", "2": "Incandescent filaments produce diffuse, incoherent thermal light incapable of rapid modulation for digital optical networks.", "3": "Ultraviolet discharge tubes are used in sterilization and blacklights, completely unsuitable for fiber-optic communications."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "fiber", "multimode", "optics", "cabling"]}, {"id": "C1-075", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "How many total individual insulated copper conductors (organized into color-coded twisted pairs) are present inside a standard Category 5e or Category 6 UTP Ethernet cable?", "options": ["4 individual conductors (2 twisted pairs)", "6 individual conductors (3 twisted pairs)", "2 individual conductors (1 twisted pair)", "8 individual conductors (4 twisted pairs)"], "answer": 1, "explanation": "Standard Category 5e, 6, and 6a Unshielded Twisted Pair (UTP) Ethernet cables contain exactly 8 individual insulated copper wires arranged into 4 color-coded twisted pairs (Blue, Orange, Green, Brown and their striped white counterparts), terminating into an 8-position 8-contact (8P8C / RJ-45) connector.", "distractor_analysis": {"1": "4 conductors (2 pairs) was used in legacy 10BASE-T/100BASE-TX wiring or standard telephone lines, but modern Cat5e/6 cables physically contain all 8 conductors.", "2": "6 conductors is used in 3-pair telephone wiring (RJ-12/RJ-25), not standard Ethernet cables.", "3": "2 conductors (1 pair) is used in basic single-line POTS analog telephone circuits (RJ-11)."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cabling", "utp", "twisted-pair", "cat6"]}, {"id": "C1-076", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "A datacenter technician needs to locate and trace a specific unlabeled network drop from an office wall jack to the correct termination port on a high-density patch panel in the server room. Which tool should the technician use?", "options": ["Cable crimper and wire stripper", "Punch-down tool with 110 blade", "Tone generator and probe (toner / fox and hound)", "Time-Domain Reflectometer (TDR)"], "answer": 2, "explanation": "A tone generator and probe (commonly known as a toner or 'fox and hound') is the standard tool for tracing and locating specific cables within a bundle: the generator injects an audible RF tone into the wire at the jack, and the inductive amplifier probe emits sound when placed near the corresponding cable end at the patch panel. A TDR measures distance to cable faults, crimpers attach connectors, and punch-down tools seat wires into terminal blocks.", "distractor_analysis": {"1": "A Time-Domain Reflectometer (TDR) measures cable impedance and pinpoints the exact distance to physical breaks or shorts, not tracing unlabeled runs.", "2": "A cable crimper physically crimps RJ-45 connector plugs onto copper cable ends, providing no diagnostic tracing function.", "3": "A punch-down tool pushes insulated wires into 110 or Krone punch-down blocks and cuts excess wire, used for installation rather than tracing."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "tools", "toner", "probe", "troubleshooting"]}, {"id": "C1-077", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "In structured cabling installations, where is solid-core twisted-pair copper cable primarily deployed rather than stranded-core cable?", "options": ["Mobile laptop Ethernet adapter dongle leads", "Permanent horizontal cable runs inside walls, conduits, and ceiling plenums", "Short flexible patch cables connecting workstations to wall outlets", "Patch cords connecting switches to patch panels inside rack cabinets"], "answer": 3, "explanation": "Solid-core UTP cabling features a single solid copper wire per conductor, providing lower electrical attenuation and superior transmission over long distances (up to 90 meters for horizontal runs), but is rigid and vulnerable to breaking if repeatedly flexed. Therefore, solid-core cable is installed permanently inside walls and ceilings. Stranded-core cabling uses multiple tiny copper strands, offering extreme flexibility for patch cables that are moved and handled frequently.", "distractor_analysis": {"1": "Workstation patch cords use stranded-core copper because it withstands repeated bending, twisting, and physical movement without snapping.", "2": "Rack patch cords use flexible stranded-core cable to facilitate tight bends and easy cable management between patch panels and switches.", "3": "Mobile dongle leads require high mechanical flexibility, necessitating stranded-conductor wiring."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cabling", "solid-core", "stranded", "structured-cabling"]}, {"id": "C1-078", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "When inspecting the LED diagnostic link status indicator lights on a Gigabit Ethernet network adapter, which of the following is NOT typically indicated by the LEDs?", "options": ["Physical Layer 1 link presence and carrier detection", "Negotiated link speed (e.g., 100 Mbps green vs 1000 Mbps amber)", "Real-time packet transmission and reception activity (flashing LED)", "Ethernet port duplex mode (Half-duplex vs Full-duplex)"], "answer": 1, "explanation": "Standard Ethernet NIC and switch port LEDs indicate Physical Link (solid LED), negotiated Link Speed (color variations such as amber for 100 Mbps or green for 1 Gbps), and Network Activity (flashing/blinking LED). Standard physical LEDs do not display duplex negotiation status (half vs full duplex), which must be checked via software diagnostic tools or switch CLI management consoles.", "distractor_analysis": {"1": "Link LEDs illuminate solid when an active electrical or optical carrier signal is detected between the NIC and the switch.", "2": "Speed LEDs use distinct colors (e.g., green for 1000 Mbps, amber for 100 Mbps) to visually display the negotiated link speed.", "3": "Activity LEDs flicker or pulse whenever data packets are transmitted or received across the physical interface."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "hardware", "nic", "led", "diagnostics"]}, {"id": "C1-079", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "What type of specially formatted Layer 2 network broadcast frame triggers a network interface card to power on a sleeping or shut-down computer via Wake-on-LAN (WoL)?", "options": ["SNMP trap notification message over UDP port 162", "Spanning Tree Protocol (STP) Bridge Protocol Data Unit", "Magic packet (containing 6 bytes of 0xFF followed by 16 repetitions of the target MAC address)", "Encrypted IPsec tunnel key exchange handshake frame"], "answer": 2, "explanation": "Wake-on-LAN (WoL) is triggered when the computer's network interface card (which remains in low-power standby listening mode) detects a 'magic packet'. A magic packet is a broadcast frame containing a synchronization stream of 6 bytes of 0xFF (FF:FF:FF:FF:FF:FF) followed immediately by 16 seamless repetitions of the target workstation's 48-bit MAC address. IPsec handshakes, SNMP traps, and STP BPDUs do not trigger WoL power circuits.", "distractor_analysis": {"1": "IPsec IKE handshakes establish encrypted VPN tunnels and do not contain the magic packet signature needed for hardware WoL.", "2": "SNMP traps are alert notifications sent by managed network devices to a management station, unrelated to hardware power-on.", "3": "STP BPDUs are frames exchanged between switches to prevent Layer 2 bridging loops."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "networking", "wake-on-lan", "bios", "mac"]}, {"id": "C1-080", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "In traditional IPv4 classful addressing, how many octets are dedicated to the network ID in a default Class A network (default subnet mask 255.0.0.0 /8)?", "options": ["4 octets for Network ID and 0 octets for Host IDs", "1 octet for Network ID and 3 octets for Host IDs", "2 octets for Network ID and 2 octets for Host IDs", "3 octets for Network ID and 1 octet for Host IDs"], "answer": 3, "explanation": "In classful IPv4 addressing, a Class A network uses a default /8 mask (255.0.0.0), meaning the first 1 octet (8 bits) identifies the network ID, while the remaining 3 octets (24 bits) are allocated for host addresses (allowing over 16 million hosts per network). Class B allocates 2 octets for network and 2 for host (255.255.0.0 /16), and Class C allocates 3 octets for network and 1 for host (255.255.255.0 /24).", "distractor_analysis": {"1": "2 octets for network and 2 octets for hosts is the definition of a Class B IPv4 network (default mask 255.255.0.0 /16).", "2": "3 octets for network and 1 octet for hosts is the definition of a Class C IPv4 network (default mask 255.255.255.0 /24).", "3": "4 octets for network (255.255.255.255 /32) represents a single host route, not a routable Class A network block."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ipv4", "addressing", "subnetting", "classful"]}, {"id": "C1-081", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "What is the total bit length and address space size of an Internet Protocol version 6 (IPv6) address?", "options": ["32 bits (4 bytes, formatted as 4 decimal octets)", "64 bits (8 bytes, formatted as 2 long words)", "256 bits (32 bytes, formatted as cryptographic hash strings)", "128 bits (16 bytes, formatted as 8 groups of 4 hexadecimal characters)"], "answer": 1, "explanation": "An IPv6 address is 128 bits in length, providing approximately 3.4 x 10^38 unique addresses to overcome the exhaustion of 32-bit IPv4 addresses (which provide ~4.3 billion addresses). IPv6 addresses are written in hexadecimal notation separated into eight 16-bit blocks (hextets) by colons.", "distractor_analysis": {"1": "32 bits is the length of an Internet Protocol version 4 (IPv4) address.", "2": "64 bits is the size of standard IPv6 interface identifiers (the host portion of a /64 subnet), not the full address.", "3": "256 bits is the hash digest size of SHA-256 cryptographic algorithms, not an IP address standard."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ipv6", "addressing", "specifications"]}, {"id": "C1-082", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which standard transport protocol and TCP port number is utilized by Microsoft Server Message Block (SMB) for native network file sharing over IP?", "options": ["TCP port 143 (IMAP email)", "UDP port 67 (DHCP server)", "TCP port 445 (SMB over IP)", "TCP port 443 (HTTPS secure web)"], "answer": 2, "explanation": "Microsoft Server Message Block (SMB) operates natively over TCP port 445 (SMB direct over IP) for file and printer sharing, named pipes, and RPC services in Windows and Samba environments. TCP port 443 is used for secure HTTPS web traffic, TCP port 143 is used for unencrypted IMAP email access, and UDP port 67 is used by DHCP servers.", "distractor_analysis": {"1": "TCP port 443 is the standard port for Hypertext Transfer Protocol Secure (HTTPS), which delivers encrypted web sessions.", "2": "TCP port 143 is used by the Internet Message Access Protocol (IMAP) for unencrypted email retrieval.", "3": "UDP port 67 is used by Dynamic Host Configuration Protocol (DHCP) servers to listen for client IP requests."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "smb", "protocols"]}, {"id": "C1-083", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "According to Internet Engineering Task Force (IETF) standards (RFC 1035), what is the maximum total length of a Fully Qualified Domain Name (FQDN), including all domain labels and separating dots?", "options": ["1024 characters total, with 128 characters per label", "255 characters total, with 63 characters per label", "128 characters total, with 32 characters per label", "512 characters total, with 64 characters per label"], "answer": 3, "explanation": "RFC 1035 specifies that a Fully Qualified Domain Name (FQDN) can have a maximum total length of 255 octets/characters (including all subdomains and separating dots), and each individual label between dots cannot exceed 63 characters. 128, 512, and 1024 characters are non-standard limits.", "distractor_analysis": {"1": "128 is a common guess but is not the RFC 1035 limit for a fully qualified name.", "2": "512 bytes is the classic DNS UDP message limit, not the name length limit.", "3": "1024 matches no DNS limit. The name ceiling is 255 with 63 per label."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "fqdn", "standards"]}, {"id": "C1-084", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "Which of the following network devices functions strictly as a wired Layer 2 packet-forwarding hardware appliance and does NOT contain integrated wireless radio transceivers?", "options": ["Wireless Access Point (WAP)", "Enterprise smartphone", "Wi-Fi connected tablet", "Dedicated 48-port rackmount Ethernet Switch"], "answer": 1, "explanation": "A standard dedicated rackmount Ethernet switch is a hard-wired Layer 2 network device that connects client workstations, servers, and access points using copper twisted-pair or fiber-optic patch cables, lacking internal Wi-Fi radio antennas. WAPs, smartphones, and tablets all integrate 802.11 wireless radio transceivers.", "distractor_analysis": {"1": "A Wireless Access Point (WAP) is explicitly designed with Wi-Fi transceivers to bridge wireless client devices to the wired Ethernet LAN.", "2": "Smartphones contain integrated Wi-Fi, cellular, and Bluetooth radio chips.", "3": "Tablets integrate Wi-Fi and Bluetooth antennas to communicate over wireless networks."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "devices", "switch", "wireless"]}, {"id": "C1-085", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which legacy IEEE 802.11 wireless networking standard was designed to operate exclusively in the 5 GHz radio frequency band, achieving maximum data rates up to 54 Mbps?", "options": ["IEEE 802.11g", "IEEE 802.11ax (Wi-Fi 6)", "IEEE 802.11a", "IEEE 802.11b"], "answer": 2, "explanation": "IEEE 802.11a was released in 1999 and operates exclusively in the 5 GHz radio frequency spectrum using OFDM modulation, providing maximum theoretical bandwidth of 54 Mbps. IEEE 802.11b (11 Mbps) and 802.11g (54 Mbps) operate in the crowded 2.4 GHz band, while 802.11ax operates across 2.4 GHz, 5 GHz, and 6 GHz (Wi-Fi 6E).", "distractor_analysis": {"1": "IEEE 802.11b operates exclusively in the 2.4 GHz band with a maximum speed of 11 Mbps using DSSS modulation.", "2": "IEEE 802.11g operates in the 2.4 GHz band providing up to 54 Mbps, but is not a 5 GHz standard.", "3": "IEEE 802.11ax (Wi-Fi 6) is a modern multi-gigabit standard operating across 2.4 GHz, 5 GHz, and 6 GHz bands."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "802.11a", "5ghz"]}, {"id": "C1-086", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "Which of the following statements is NOT true regarding consumer Wireless Mesh Networks (WMN) deployed in residential or small office environments?", "options": ["Mesh systems provide seamless single-SSID wireless coverage across large homes and small offices", "Wireless mesh networks are designed to replace complex multi-switch enterprise controllers in large enterprise datacenters", "Mesh networks consist of a primary gateway base station connected to the modem and one or more wireless satellite nodes", "Mesh satellite nodes automatically form dynamic self-healing wireless backhauls to relay client traffic"], "answer": 3, "explanation": "Wireless mesh networks are designed for consumer residential and SOHO environments to eliminate Wi-Fi dead zones easily without running Ethernet cables. They lack the advanced VLAN trunking, multi-SSID RADIUS integration, and granular RF management required for large-scale enterprise campus/datacenter deployments. All other statements accurately describe mesh topology and self-healing backhaul capabilities.", "distractor_analysis": {"1": "Mesh networks indeed use a primary router node plugged into the WAN modem plus multiple satellite access points distributed throughout the premises.", "2": "Mesh nodes dynamically calculate optimal routing paths and self-heal by redirecting traffic if an intermediate node goes offline.", "3": "Mesh systems broadcast a single unified SSID across all nodes and support seamless client roaming protocols (802.11k/v/r)."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "mesh", "soho"]}, {"id": "C1-087", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "A network technician installs a commercial Wireless Access Point (WAP) mounted high on a hallway ceiling where no electrical AC power outlets exist. How is electrical power most commonly supplied to the access point?", "options": ["Replaceable 9V alkaline dry-cell batteries inside the mounting bracket", "A rooftop solar collector wired directly to the ceiling drop tile", "A high-frequency wireless microwave induction power beam", "Power over Ethernet (PoE / 802.3af/at/bt) supplied through the Cat 6 network cable"], "answer": 1, "explanation": "Power over Ethernet (PoE, standardized as IEEE 802.3af, 802.3at PoE+, and 802.3bt PoE++) delivers low-voltage direct current (DC) electrical power alongside data packets over standard Cat 5e/6 twisted-pair cabling from a PoE-capable network switch or PoE power injector. Alkaline batteries require constant maintenance, solar panels cannot operate indoors, and microwave power beams are not commercial IT technologies.", "distractor_analysis": {"1": "Commercial enterprise access points draw continuous electrical power (15W to 30W+) and cannot operate on consumer alkaline dry-cell batteries.", "2": "Indoor ceiling mounts have no access to sunlight, making solar panels non-viable for powering commercial access points.", "3": "Microwave induction power beaming is experimental physics technology not deployed for standard networking equipment."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "poe", "power", "cabling", "wap"]}, {"id": "C1-088", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which of the following wireless technologies utilizes optical light waves rather than radio frequency (RF) electromagnetic waves to communicate between devices, requiring direct line-of-sight?", "options": ["Near Field Communication (NFC)", "Radio Frequency Identification (RFID)", "Infrared (IR)", "Bluetooth (IEEE 802.15.1)"], "answer": 2, "explanation": "Infrared (IR) communication uses invisible optical light waves (in the 850 nm to 940 nm range) transmitted by an LED to an optical photodiode sensor, requiring direct line-of-sight and unable to penetrate walls or opaque objects. Bluetooth, NFC, and RFID are all radio-frequency (RF) technologies that use electromagnetic radio waves.", "distractor_analysis": {"1": "Bluetooth operates on 2.4 GHz ultra-high-frequency radio waves, which can penetrate walls and do not require optical line-of-sight.", "2": "Near Field Communication (NFC) uses high-frequency radio electromagnetic induction (13.56 MHz) over very short distances (a few centimeters).", "3": "RFID uses electromagnetic radio frequency fields to automatically identify and track tags attached to objects."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wireless", "infrared", "rf"]}, {"id": "C1-089", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A user brings a laptop to a branch office and reports that the device cannot connect to the corporate Wi-Fi network, which was working yesterday. Other branch employees are connected and working normally. What is the most likely cause of this specific failure?", "options": ["The DHCP server ran out of IP addresses across the entire worldwide enterprise", "The wireless network pre-shared key or SSID security profile on the WAP was updated, causing a profile mismatch on the laptop", "The building main internet fiber-optic gateway connection has completely failed", "The WAP internal antenna orientation shifted by two degrees"], "answer": 3, "explanation": "When an individual device suddenly fails to connect to a known wireless network while all other devices continue working normally, the most probable cause is a cached wireless profile mismatch (e.g., the network SSID passphrase, security type WPA2/WPA3, or certificate was changed, while the client is attempting to authenticate with old credentials). Deleting the saved wireless profile and reconnecting prompts for the new credentials. If the fiber gateway or global DHCP failed, all users would be impacted.", "distractor_analysis": {"1": "If the building internet fiber failed, all users in the branch office would experience internet loss, not just a single laptop.", "2": "A slight shift in antenna orientation might cause minor signal variance, but would not completely prevent network authentication.", "3": "A global DHCP failure would cause widespread IP configuration failures across all clients in the enterprise."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["troubleshooting", "wireless", "ssid", "profiles"]}, {"id": "C1-090", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "To allow client web browsers inside a corporate LAN to access external public HTTP web servers, what traffic rule must the perimeter stateful firewall permit?", "options": ["Inbound traffic from external sources to destination TCP port 80 on local workstations", "Outbound traffic to destination TCP port 143 (IMAP)", "Inbound broadcast traffic on UDP port 67 (DHCP)", "Outbound traffic to destination TCP port 80 (HTTP) and TCP port 443 (HTTPS)"], "answer": 1, "explanation": "Web clients initiate outgoing connections to remote web servers by sending packets to standard web ports: TCP port 80 (unencrypted HTTP) and TCP port 443 (encrypted HTTPS). Stateful firewalls inspect outbound requests and automatically allow returning response traffic. Allowing unsolicited inbound traffic to port 80 on internal workstations would create severe security vulnerabilities. Port 143 is for IMAP mail, and UDP 67 is for DHCP.", "distractor_analysis": {"1": "Inbound port 80 connections should only be permitted on public web servers, not on internal desktop client workstations.", "2": "TCP port 143 is used to retrieve email from IMAP mail servers, having no role in web browsing.", "3": "UDP port 67 handles local DHCP broadcast discovery within LANs and should never be routed across WAN firewall perimeters."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "firewall", "security", "http", "https"]}, {"id": "C1-091", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which of the following port numbers is NOT associated with standard Internet email transmission or mailbox retrieval protocols?", "options": ["TCP port 110 (Post Office Protocol version 3 - POP3)", "TCP port 143 (Internet Message Access Protocol - IMAP)", "TCP port 443 (HTTPS secure web delivery)", "TCP port 25 (Simple Mail Transfer Protocol - SMTP)"], "answer": 2, "explanation": "TCP port 443 is the standard port for Hypertext Transfer Protocol Secure (HTTPS), which provides encrypted web traffic, not a dedicated email protocol. Port 25 is used for SMTP (sending email between servers), Port 110 is for POP3 (retrieving email), and Port 143 is for IMAP (accessing/synchronizing email mailboxes).", "distractor_analysis": {"1": "TCP port 25 is the standard listening port for Simple Mail Transfer Protocol (SMTP) mail servers.", "2": "TCP port 110 is the default port for unencrypted Post Office Protocol (POP3) client mailbox retrieval.", "3": "TCP port 143 is the default port for unencrypted Internet Message Access Protocol (IMAP) mailbox synchronization."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "email", "protocols"]}, {"id": "C1-092", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which of the following is a physical wired Ethernet standard rather than a low-power wireless communication protocol commonly used in Internet of Things (IoT) home and building automation?", "options": ["Bluetooth Low Energy (BLE)", "IEEE 802.3 1000BASE-T wired copper Ethernet", "Zigbee (IEEE 802.15.4 wireless mesh)", "Z-Wave (sub-1 GHz proprietary wireless mesh)"], "answer": 3, "explanation": "IEEE 802.3 1000BASE-T is a wired Gigabit Ethernet standard utilizing 4-pair twisted copper cabling. In contrast, Zigbee, Z-Wave, and Bluetooth Low Energy (BLE) are wireless, low-power RF protocols specifically designed for battery-powered IoT smart home devices (sensors, smart locks, thermostats, lighting controls).", "distractor_analysis": {"1": "Zigbee is a low-power, low-data-rate wireless mesh network standard operating primarily at 2.4 GHz for smart home sensors.", "2": "Z-Wave is a proprietary wireless mesh technology operating in the 900 MHz ISM band designed for home automation.", "3": "Bluetooth Low Energy (BLE) is a power-conserving wireless protocol used extensively in portable IoT and wearable devices."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "iot", "zigbee", "zwave"]}, {"id": "C1-093", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "In hardware virtualization terminology, a virtual machine executing inside a hypervisor is called the _______ operating system, running on top of the underlying physical server known as the _______ system.", "options": ["Host OS; Guest system", "Kernel space; User space", "Master node; Worker pod", "Guest OS; Host system"], "answer": 1, "explanation": "In virtualization, the virtualized instance running inside the VM environment is designated the 'Guest' operating system, while the physical server, hardware layer, and hypervisor providing physical resources is designated the 'Host' system. Kernel and user spaces are OS memory protection rings, and master/worker are container orchestration terms.", "distractor_analysis": {"1": "The terms are inverted; the host is the physical provider of hardware resources and the guest is the virtualized instance.", "2": "Kernel space and user space are memory isolation domains within an operating system kernel, not virtualization host/guest relationships.", "3": "Master nodes and worker pods are terminology from Kubernetes container cluster orchestration."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "terminology", "guest", "host"]}, {"id": "C1-094", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "When provisioning a new virtual machine on a Type 2 hypervisor workstation, which physical component is NOT strictly required because it can be emulated using an ISO image file?", "options": ["Allocated virtual disk storage space", "Allocated virtual RAM from host physical memory", "Physical optical DVD/CD-ROM disc drive", "Hypervisor software layer"], "answer": 2, "explanation": "Hypervisors support virtual optical drives that mount standard ISO image files directly from local storage, eliminating any requirement for a physical optical DVD/CD drive. However, a hypervisor, allocated virtual storage (VHD/VMDK), and physical host RAM are mandatory prerequisites to instantiate and run a virtual machine.", "distractor_analysis": {"1": "A hypervisor is the essential virtualization management layer required to allocate CPU and memory to guest VMs.", "2": "A virtual disk file (VHDX or VMDK) is required to provide block storage for the guest operating system file system.", "3": "Allocating virtual RAM backed by physical host memory is mandatory for the guest OS kernel and programs to execute."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "vm", "iso", "hypervisor"]}, {"id": "C1-095", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "Which of the following workloads is least suitable for deployment inside a standard virtual machine due to virtualization overhead and lack of direct bare-metal graphics hardware acceleration?", "options": ["Hosting a legacy Windows XP application for accounting audits", "High-end competitive 3D gaming requiring low-latency native GPU rendering", "Testing software updates and patches in an isolated sandbox", "Emulating multiple network topologies with virtual switches"], "answer": 3, "explanation": "Virtual machines run through an abstraction layer where virtualized display adapters lack full native direct GPU pipeline throughput, making latency-sensitive high-performance 3D gaming poorly suited for standard VMs. Sandboxing, virtual networking labs, and running legacy OS environments are ideal, classic use cases for virtualization.", "distractor_analysis": {"1": "Sandboxing test environments is a primary benefit of virtualization, allowing non-destructive snapshot rollbacks if a patch fails.", "2": "Virtual networking allows complex multi-router and multi-switch topologies to be simulated without buying physical hardware.", "3": "Running legacy operating systems (like Windows XP or older Linux distros) allows critical legacy apps to run on modern hardware."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "use-cases", "limitations", "performance"]}, {"id": "C1-096", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A project manager asks you to label each tier of the new hosting design using the NIST cloud vocabulary so the architecture document matches the audit checklist. Which of the following is NOT one of the NIST-defined cloud deployment models?", "options": ["Private cloud", "Public cloud", "Hybrid cloud", "Corporate cloud"], "answer": 1, "explanation": "The official NIST (National Institute of Standards and Technology) cloud computing standard defines exactly four cloud deployment models: Public cloud, Private cloud, Hybrid cloud, and Community cloud. 'Corporate cloud' is not a recognized NIST deployment model.", "distractor_analysis": {"1": "Private cloud is an official model provisioned for exclusive use by a single organization.", "2": "Public cloud is an official model provisioned for open use by the general public across multi-tenant infrastructure.", "3": "Hybrid cloud is an official model combining two or more distinct cloud infrastructures (private, community, or public) bound by standardized technology."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "nist", "deployment-models"]}, {"id": "C1-097", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "When performing an internal hardware repair or component replacement on a company laptop, what is the first safety and preparatory step a technician should perform?", "options": ["Use a metal flathead screwdriver to pry apart plastic chassis clips with maximum force", "Leave the laptop powered on in sleep mode so hardware changes can be detected instantly", "Disconnect external AC power, remove or disconnect the battery, and review the manufacturer service manual", "Place all removed screws of different lengths together into a single magnetic dish"], "answer": 2, "explanation": "Safety procedures for laptop disassembly require disconnecting external AC power, removing or disconnecting the internal battery to prevent short circuits, and consulting the manufacturer service manual for proper teardown sequences. Mixing different length screws risks puncturing PCB traces (screw damage), prying with metal tools damages plastics, and working on an energized system risks electric shock and board destruction.", "distractor_analysis": {"1": "Laptops use screws of varying thread pitches and lengths; mixing them risks driving a long screw through the motherboard or palmrest during reassembly.", "2": "Metal screwdrivers gouge plastic chassis seams and scratch motherboard traces; specialized non-marring plastic spudgers should be used.", "3": "Working inside an energized laptop with the battery connected risks catastrophic short circuits from dropped screws or metallic tools."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "safety", "disassembly"]}, {"id": "C1-098", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which best-practice documentation technique is most effective for ensuring an accurate and error-free reassembly of a complex laptop teardown?", "options": ["Discard internal EMI copper shielding tape to save weight and improve airflow", "Take high-resolution digital photos and organize removed screws into labeled organizers at each disassembly step", "Replace all original screws with longer generic sheet-metal screws for tighter clamping", "Force plastic chassis seams together with mechanical clamps before inserting screws"], "answer": 3, "explanation": "Taking detailed digital photos at each step of disassembly and utilizing a partitioned, labeled screw organizer or magnetic grid mat ensures that cables are routed correctly, connectors are seated properly, and the exact screws are returned to their original threaded holes. Using longer screws destroys motherboards, forcing clips breaks tabs, and removing shielding invites electromagnetic interference.", "distractor_analysis": {"1": "Using longer replacement screws will penetrate through the motherboard or puncture the cosmetic top casing.", "2": "Forcing chassis halves with clamps will snap internal plastic alignment tabs and crack fragile mounting bosses.", "3": "Discarding internal metal shielding compromises electromagnetic interference (EMI) containment and thermal dissipation paths."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "reassembly", "best-practices"]}, {"id": "C1-099", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "On most modern thin-and-light corporate laptops, which internal component typically requires the most extensive disassembly, or may be permanently soldered directly to the motherboard?", "options": ["Removable battery pack", "M.2 NVMe solid-state drive", "Standard SO-DIMM RAM module", "Central Processing Unit (CPU) / System-on-Chip (SoC)"], "answer": 1, "explanation": "In modern thin-and-light laptops, the CPU/SoC is permanently soldered to the motherboard using a Ball Grid Array (BGA) package, requiring a complete motherboard replacement (or deep teardown removing cooling pipes, fans, and display assemblies on older socketed units). In contrast, modular batteries, M.2 SSDs, and SO-DIMMs are easily accessible beneath the bottom cover.", "distractor_analysis": {"1": "Removable batteries can be released via external latches or accessed immediately upon removing the bottom chassis cover.", "2": "M.2 SSDs are typically held by a single retaining screw directly beneath the bottom maintenance hatch.", "3": "SO-DIMM RAM slots are usually accessible under the bottom access panel or immediately beneath the keyboard on older designs."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "cpu", "bga", "motherboard"]}, {"id": "C1-100", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "Why is replacing or servicing an internal laptop LCD display assembly often more labor-intensive and challenging than servicing desktop monitors?", "options": ["Laptop displays contain radioactive phosphors requiring hazardous waste permits to disassemble", "Laptop displays must be calibrated inside an industrial cleanroom using cryogenic lasers", "The display panel, Wi-Fi/Bluetooth antenna wires, webcam, microphone, and delicate eDP video cables are tightly routed through hinge mechanisms inside a glued or clipped bezel", "Laptop displays operate on 480V three-phase alternating current power requiring an electrician license"], "answer": 2, "explanation": "Laptop display assemblies pack the LCD panel, LED backlight circuits, embedded DisplayPort (eDP) micro-coaxial cable, integrated webcam, microphones, and wireless antenna leads through narrow physical hinges and tightly glued/snapped plastic bezels, making disassembly delicate and labor-intensive. Laptop displays operate on low DC voltage (typically 3.3V-19V), use safe solid-state LEDs, and require no cryogenic equipment.", "distractor_analysis": {"1": "Laptop displays operate on low-voltage DC power supplied through the motherboard (typically 3.3V logic and 12V-19V backlight power), not three-phase AC mains.", "2": "Modern flat-panel LCDs use safe non-toxic LEDs and liquid crystal polymers, containing no radioactive phosphors.", "3": "Laptop display panels are modular components that can be serviced at a standard ESD-safe electronics workbench without cleanrooms or lasers."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "display", "antennas", "repair"]}, {"id": "C1-101", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which of the following characteristics is NOT typical of modern consumer smartphones and mobile devices compared to desktop computers?", "options": ["Integrated multi-band wireless antennas (Wi-Fi, Bluetooth, Cellular)", "Modular field-upgradeable internal CPU and RAM sockets", "Sealed, compact integrated chassis construction", "Touch-driven mobile operating system (e.g., iOS or Android)"], "answer": 3, "explanation": "Consumer smartphones and tablets feature tightly integrated, sealed architectures with System-on-Chip (SoC) processors and RAM permanently soldered to the logic board; they do not have modular, user-upgradeable CPU or RAM sockets. Desktop PCs, in contrast, feature modular sockets and slots designed for field upgrades.", "distractor_analysis": {"1": "Smartphones are manufactured as sealed units with glued glass and metal frames to maximize water and dust resistance.", "2": "Mobile devices run specialized mobile operating systems tailored for touch interfaces, power management, and sandboxed apps.", "3": "Smartphones integrate multi-frequency antennas for 5G cellular, Wi-Fi 6, Bluetooth, and GPS into the chassis frame."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "hardware", "architecture", "soc"]}, {"id": "C1-102", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which of the following physical connector types is NOT a standard native wired interface built directly into modern smartphones for charging and data synchronization?", "options": ["USB Type-C reversible port", "Apple proprietary 8-pin Lightning connector", "Micro-USB 2.0 Type-B connector", "Direct 8P8C (RJ-45) modular Ethernet port"], "answer": 1, "explanation": "Smartphones are too thin to house a physical 8P8C (RJ-45) Ethernet modular jack natively, requiring a USB-C or Lightning-to-Ethernet adapter for wired network connectivity. USB Type-C, Apple Lightning, and legacy Micro-USB are standard native physical mobile connectors.", "distractor_analysis": {"1": "USB Type-C is the universal industry-standard reversible port for charging, data transfer, and video output on modern smartphones.", "2": "The Lightning connector is Apple's proprietary reversible 8-pin connector used across older iPhone and iPad models.", "3": "Micro-USB 2.0 was the historical standard charging and data port on older generation Android smartphones."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "connectors", "cabling"]}, {"id": "C1-103", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "What is the primary official application repository and distribution platform for certified Android apps and digital content?", "options": ["Microsoft Store for Windows", "Valve Steam Client", "Google Play Store", "Apple App Store"], "answer": 2, "explanation": "The Google Play Store is the primary official digital distribution service operated by Google for downloading certified Android applications, games, and media. The Apple App Store distributes iOS/macOS apps, Microsoft Store serves Windows software, and Steam distributes PC gaming software.", "distractor_analysis": {"1": "The Apple App Store is the official application store exclusively for iOS, iPadOS, and macOS devices.", "2": "The Microsoft Store distributes applications and Universal Windows Platform (UWP) software for Windows PCs.", "3": "Steam is a gaming platform and digital storefront for Windows, macOS, and Linux PCs, not mobile Android APKs."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "android", "apps", "play-store"]}, {"id": "C1-104", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which of the following is a cellular configuration update historically used by CDMA carriers to specify radio bands, sub-bands, and service provider cell tower priorities on a mobile phone?", "options": ["Graphics Processing Unit shader cache compile", "Preferred Roaming List (PRL) update", "Dynamic Host Configuration Protocol lease renewal", "Spanning Tree Protocol (STP) convergence recalculation"], "answer": 3, "explanation": "A Preferred Roaming List (PRL) update delivers carrier-specified database tables to a mobile phone, informing the device which radio bands, frequencies, and partner cellular towers to prioritize when connecting or roaming. DHCP manages local IP leases, STP manages switch loop prevention, and shader caches optimize 3D GPU rendering.", "distractor_analysis": {"1": "DHCP lease renewals occur on local IP networks to refresh client IP address leases, not cellular tower roaming tables.", "2": "STP convergence is an Ethernet switch protocol mechanism to prevent Layer 2 bridging loops in wired networks.", "3": "Shader cache compilation compiles graphics shaders for GPU execution, completely unrelated to cellular radio provisioning."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "prl", "roaming"]}, {"id": "C1-105", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which of the following port numbers is used for unencrypted, plaintext Internet Message Access Protocol (IMAP) communication?", "options": ["TCP port 993 (IMAPS / IMAP over TLS)", "TCP port 587 (SMTP Submission with STARTTLS)", "TCP port 995 (POP3S / POP3 over TLS)", "TCP port 143 (Plaintext IMAP)"], "answer": 1, "explanation": "TCP port 143 is the default port for standard unencrypted IMAP, transmitting email queries and credentials across the network in plaintext. TCP port 993 is IMAPS (IMAP over SSL/TLS), TCP port 587 is secure SMTP submission, and TCP port 995 is POP3S (POP3 over SSL/TLS).", "distractor_analysis": {"1": "TCP port 993 is the standard secure port for IMAP over TLS (IMAPS), providing transport-layer encryption.", "2": "TCP port 587 is used by email clients to submit outgoing mail to SMTP servers securely via STARTTLS.", "3": "TCP port 995 is the secure port for Post Office Protocol version 3 over TLS (POP3S)."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "imap", "email", "security"]}, {"id": "C1-106", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "In mobile device data management, what is the key distinction between real-time data synchronization and an asynchronous data backup?", "options": ["Backups continuously delete user contacts on the mobile phone, whereas synchronization preserves them", "Synchronization requires rooting or jailbreaking the mobile operating system", "Synchronization continuously reconciles two-way additions and edits across active devices, whereas a backup is a point-in-time snapshot for recovery", "Synchronization only operates over 10GbE fiber-optic cables, whereas backups require Bluetooth"], "answer": 2, "explanation": "Data synchronization is a continuous bidirectional (two-way) process that ensures changes made on one device (such as adding a calendar event or editing a contact) are immediately updated across all linked devices and cloud services. A backup is a static, one-way, point-in-time archive of device data created for disaster recovery. Neither requires fiber/Bluetooth exclusively, neither erases contacts, and jailbreaking is not required.", "distractor_analysis": {"1": "Synchronization operates over standard Wi-Fi and cellular IP connections, not specialized 10GbE fiber cables.", "2": "Backups create safe redundant archives and do not delete local user contacts or data.", "3": "Data synchronization is a native feature supported by all standard mobile operating systems without jailbreaking."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronization", "backup", "cloud"]}, {"id": "C1-107", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "Which of the following is a hardware two-factor authentication generator rather than a standard direct screen lock passcode option on a smartphone?", "options": ["Geometric directional gesture swipe pattern", "Hardware RSA SecurID hardware token fob", "Numeric PIN passcode", "Complex alphanumeric password"], "answer": 3, "explanation": "A hardware token (such as an RSA SecurID key fob or YubiKey) is an external hardware device that generates one-time authentication codes, rather than a direct screen unlock method configured in phone settings. Native screen lock methods on smartphones include PINs, alphanumeric passwords, swipe patterns, and biometrics (fingerprint/facial recognition).", "distractor_analysis": {"1": "Numeric PINs (4 to 6+ digits) are standard native lock screen security options on Android and iOS devices.", "2": "Alphanumeric passwords provide high entropy for locking mobile device screens and decrypting user partitions.", "3": "Gesture swipe patterns allow users to connect a grid of dots on screen as a native lock screen credential."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "security", "screen-lock", "authentication"]}, {"id": "C1-108", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "easy", "question": "A user reports that their smartphone screen appears very dim while working in bright sunlight. Which setting or sensor should the technician check first before diagnosing hardware failure?", "options": ["Cellular baseband radio transceiver power output", "NFC mobile payment antenna configuration", "SIM card IMSI carrier registration", "Adaptive / Auto-brightness setting and ambient light sensor occlusion"], "answer": 1, "explanation": "A dim display in changing light conditions is typically caused by the Adaptive / Auto-brightness feature being disabled, set too low, or the ambient light sensor at the top of the phone being blocked by a dirty screen protector or case. Checking brightness settings and cleaning the sensor is the first troubleshooting step. Cellular radios, NFC, and SIM cards have no control over display brightness.", "distractor_analysis": {"1": "Cellular radio output regulates wireless signal strength to cell towers, with no effect on display backlight brightness.", "2": "NFC handles contactless payment communication over short distances, unrelated to screen illumination.", "3": "SIM card IMSI identifies the subscriber to the mobile network operator, having no impact on screen display brightness."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "display", "brightness"]}, {"id": "C1-109", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "What consumable consumable material is used in electrophotographic laser printers to form the visible printed image on paper before being fused with heat and pressure?", "options": ["Wax-impregnated dot-matrix fabric ribbon", "Thermally reactive chemical coating on specialty paper", "Toner powder (composed of plastic resin, iron oxide, and pigments)", "Liquid dye-sublimation ink cartridges"], "answer": 2, "explanation": "Laser printers use toner, a fine, dry powder composed of plastic polymer resins, color pigments, and iron oxide/carbon black. The toner is electrostatically attracted to the photosensitive drum and transferred to paper before heat and pressure from the fuser melt the plastic particles into the paper fibers. Inkjet printers use liquid ink, impact printers use ribbons, and thermal printers use heat-sensitive paper.", "distractor_analysis": {"1": "Liquid ink is used in inkjet printers, which spray liquid droplets onto paper via thermal or piezoelectric nozzles.", "2": "Inked fabric ribbons are used in impact dot-matrix printers, where physical pins strike the ribbon against paper.", "3": "Thermally reactive paper is used in direct thermal printers (e.g., POS receipt printers) where heated elements activate dye in the paper."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "laser", "toner"]}, {"id": "C1-110", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "Which four standard process color inks are used in full-color inkjet and color laser printing systems to reproduce full color photographic images?", "options": ["Infrared, Ultraviolet, Red, and Blue (IURB)", "Cyan, Magenta, Yellow, and Key/Black (CMYK)", "Red, Green, Blue, and White (RGBW)", "Orange, Purple, Brown, and Gray (OPBG)"], "answer": 3, "explanation": "Subtractive color printing utilizes CMYK (Cyan, Magenta, Yellow, and Key/Black) inks or toners. By combining varying percentages of these four subtractive primary pigments, printers absorb specific wavelengths of reflected light to reproduce a full gamut of visible colors. RGB is an additive color model used for illuminated computer monitors and screens, not physical printing inks.", "distractor_analysis": {"1": "RGBW is an additive color model used in video displays and LED stage lighting, not standard subtractive ink printing.", "2": "OPBG is a fictitious color combination not used as a primary printing standard.", "3": "Infrared and ultraviolet are invisible electromagnetic spectra outside the human visual printing range."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "cmyk", "color-model"]}, {"id": "C1-111", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "Which of the following operations is NOT part of the mechanical printing process of an impact dot-matrix printer?", "options": ["Solenoid electromagnets driving stiff metal pins forward against a fabric ribbon", "Inked cloth or carbon ribbon transferring ink impressions onto multi-part paper", "Tractor-feed sprockets pulling continuous form paper past the platen roller", "Pre-heating the printhead to 200 degrees Celsius using a ceramic thermal heating bar"], "answer": 1, "explanation": "Impact dot-matrix printers operate purely through mechanical force: electromagnetic solenoids propel stiff metal pins forward to strike an inked ribbon against paper; they do not heat the printhead. Thermal printheads (used in thermal receipt printers) use heated elements, but impact printers are unheated mechanical impact devices.", "distractor_analysis": {"1": "Solenoid coils inside the impact printhead fire pins against the ribbon; this is the core mechanism of impact printing.", "2": "Striking the inked ribbon transfers ink to paper and creates physical carbon impressions on multi-part forms.", "3": "Tractor-feed mechanisms with sprocket wheels advance continuous perforated paper through impact printers."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "impact", "dot-matrix"]}, {"id": "C1-112", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "Which of the following maintenance procedures is NOT applicable to direct thermal receipt printers because the component does not exist in thermal printer architectures?", "options": ["Replacing the roll of specialized heat-sensitive thermal paper", "Blowing out paper dust and debris with compressed air", "Replacing the fuser assembly and halogen heating lamp", "Cleaning the thermal heating element line using isopropyl alcohol (IPA)"], "answer": 2, "explanation": "Thermal printers do not use toner and therefore have no fuser assembly, heat lamps, or pressure rollers. Fusers exist only in electrophotographic laser printers to melt toner into paper. Thermal printer maintenance consists of wiping the thermal printhead with isopropyl alcohol, clearing paper dust, and replacing thermal paper rolls.", "distractor_analysis": {"1": "Cleaning the thermal printhead with an alcohol swab or cleaning pen is standard preventive maintenance to remove residue.", "2": "Replacing thermal paper rolls when depleted is standard routine maintenance for receipt and label printers.", "3": "Clearing paper dust and debris with compressed air prevents paper feed jams on thermal roller assemblies."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "thermal", "maintenance"]}, {"id": "C1-113", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "What is the most ubiquitous physical local connection interface used to connect a dedicated desktop printer directly to a personal computer workstation?", "options": ["Optical TOSLINK digital audio cable", "Universal Serial Bus (USB Type-A to Type-B)", "DB-25 IEEE 1284 Centronics Parallel cable", "Legacy RS-232 9-pin Serial COM port"], "answer": 3, "explanation": "Universal Serial Bus (USB), typically using a USB Type-A connection at the PC and a USB Type-B port on the printer, is the universal standard physical interface for locally attached desktop printers. DB-25 parallel and RS-232 serial are obsolete legacy interfaces, and TOSLINK is for digital audio.", "distractor_analysis": {"1": "Centronics parallel (IEEE 1284) was the dominant printer interface in the 1990s, but has been completely superseded by USB.", "2": "RS-232 serial ports are legacy interfaces occasionally found on industrial equipment, not standard modern desktop printers.", "3": "TOSLINK optical cables transmit digital audio streams to AV receivers, not printer control data."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "connectivity", "usb"]}, {"id": "C1-114", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "When sharing a locally connected printer across a Windows workgroup network, which of the following statements is INCORRECT?", "options": ["The host computer sharing the printer must remain powered on and connected to the network for clients to print", "File and Printer Sharing must be enabled in the host Windows Network and Sharing Center", "Connecting clients can discover and attach to the shared printer via its UNC path (\\\\HostName\\PrinterShareName)", "A client computer must first install a local dummy printer and then convert its physical port to shared mode"], "answer": 1, "explanation": "To connect to a shared network printer in Windows, the client computer does NOT create a local printer and convert it; rather, the user selects 'Add a printer', chooses 'Add a network, wireless or Bluetooth printer', and browses or enters the UNC path directly. The host PC must stay powered on, File and Printer Sharing must be enabled, and UNC paths are standard.", "distractor_analysis": {"1": "If the host computer connected locally to the printer is turned off or sleeping, client print jobs cannot reach the printer.", "2": "Windows Firewall and Network settings must allow File and Printer Sharing for remote clients to access the shared print queue.", "3": "Clients can map shared printers directly using Universal Naming Convention (UNC) paths like \\\\Server\\LaserPrinter."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "printers", "sharing", "windows"]}, {"id": "C1-115", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "Which of the following steps is NOT a standard phase in the computer-aided design and 3D additive manufacturing printing workflow?", "options": ["Generating G-code toolpaths using specialized slicing software", "Pre-heating the thermal extruder nozzle and heated print bed to the filament target temperatures", "Executing an optical laser transfer corona cleaning cycle on an electrostatic drum", "Creating or acquiring a 3D digital model file (.STL or .OBJ)"], "answer": 2, "explanation": "Laser transfer corona cleaning cycles are part of electrophotographic 2D laser printing, not 3D printing. The 3D printing workflow consists of: (1) Designing a 3D CAD model (.STL/.OBJ), (2) Slicing the model into horizontal layers and generating G-code instructions, (3) Preheating the extruder and bed, and (4) Extruding molten filament layer-by-layer (Fused Deposition Modeling).", "distractor_analysis": {"1": "Creating an STL or OBJ polygonal mesh 3D model is the foundational first step of any 3D print job.", "2": "Slicing software converts 3D geometry into precise layer-by-layer motor coordinates and extrusion rates (G-code).", "3": "Preheating the hotend nozzle and heated bed ensures proper thermoplastic filament flow and bed adhesion."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "3d-printing", "additive-manufacturing"]}, {"id": "C1-116", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "What is the primary thermodynamic performance advantage of a closed-loop liquid cooling system over a standard compact aluminum heatsink fan for an overclocked processor?", "options": ["Liquid cooling prevents all software operating system malware infections", "Liquid coolant has significantly higher specific heat capacity and transfers heat to a larger remote radiator surface area", "Liquid cooling eliminates all electrical power consumption inside the PC chassis", "Liquid cooling converts the CPU from x86 architecture into an ARM RISC processor"], "answer": 3, "explanation": "Liquid cooling utilizes water/glycol coolant, which has a vastly higher specific heat capacity and thermal conductivity than air, rapidly absorbing thermal energy from the CPU water block and transporting it to a large-surface-area external radiator where large, slow-spinning fans dissipate heat efficiently. Liquid cooling still requires electrical pump/fan power, does not change CPU architecture, and has no impact on software security.", "distractor_analysis": {"1": "Liquid cooling systems require continuous electrical power to run the motorized pump and radiator fans.", "2": "Cooling systems only dissipate thermal heat and cannot alter CPU microarchitecture or instruction sets.", "3": "Thermal cooling solutions have zero relationship to operating system malware defense."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cooling", "liquid-cooling", "thermodynamics"]}, {"id": "C1-117", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "easy", "question": "Which generation of double-data-rate (DDR) SDRAM desktop memory modules features a standard 240-pin DIMM layout?", "options": ["DDR4 desktop DIMMs (288 pins)", "DDR5 desktop DIMMs (288 pins with onboard PMIC)", "Legacy DDR1 desktop DIMMs (184 pins)", "DDR3 and DDR2 desktop DIMMs (240 pins)"], "answer": 1, "explanation": "Both DDR2 and DDR3 desktop unbuffered DIMMs feature 240 pins (though their keying notches are placed in different physical positions to prevent accidental cross-insertion). DDR4 and DDR5 desktop DIMMs have 288 pins, and original DDR1 DIMMs have 184 pins.", "distractor_analysis": {"1": "DDR4 desktop DIMMs have 288 pins and a slightly curved contact edge to reduce insertion force.", "2": "DDR5 desktop DIMMs feature 288 pins with an onboard Power Management IC (PMIC) and dual 32-bit subchannels.", "3": "DDR1 (original DDR) desktop DIMMs have 184 pins."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "ddr3", "ddr2", "pin-counts"]}, {"id": "C1-118", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following firmware diagnostic programs is stored directly within the non-volatile motherboard BIOS/UEFI ROM chip?", "options": ["Physical quartz Real-Time Clock crystal", "Chassis front-panel power reset switch", "Power-On Self-Test (POST)", "External CR2032 coin-cell lithium battery"], "answer": 2, "explanation": "The Power-On Self-Test (POST) is a firmware program stored permanently in the motherboard BIOS/UEFI flash ROM chip that runs diagnostic tests on essential hardware components upon startup. The battery, RTC crystal, and reset switch are physical hardware components, not firmware routines.", "distractor_analysis": {"1": "The CR2032 battery is an external replaceable chemical battery that powers volatile CMOS RAM when mains AC is unplugged.", "2": "The RTC crystal is an analog quartz timing oscillator on the motherboard circuit board.", "3": "The front-panel power switch is a mechanical momentary push-button wired to the motherboard front panel header."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "post", "firmware"]}, {"id": "C1-119", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which digital video interface standard natively supports High-bandwidth Digital Content Protection (HDCP) encryption to protect commercial high-definition digital media streams?", "options": ["S-Video 4-pin mini-DIN", "High-Definition Multimedia Interface (HDMI)", "Legacy 15-pin analog VGA", "Composite RCA analog video"], "answer": 3, "explanation": "HDMI natively implements High-bandwidth Digital Content Protection (HDCP), a cryptographic handshake protocol that encrypts digital video and audio streams between source devices (Blu-ray players, PCs, consoles) and displays to prevent unauthorized digital copying. Legacy analog standards like VGA, Composite RCA, and S-Video transmit unencrypted analog electrical waves without HDCP support.", "distractor_analysis": {"1": "VGA is an analog video signal standard that cannot carry digital HDCP encryption handshakes.", "2": "Composite RCA transmits an unencrypted analog composite baseband signal with no digital DRM capability.", "3": "S-Video separates analog luma and chroma signals over analog pins without any digital encryption features."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "hdmi", "hdcp", "drm", "video"]}, {"id": "C1-120", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "A datacenter technician needs to quickly verify that a commercial 3-prong AC wall receptacle has correct hot, neutral, and ground wiring polarity before plugging in an equipment rack. Which tool provides immediate three-light indicator verification?", "options": ["Electrostatic discharge (ESD) wrist strap", "Radio frequency field strength meter", "Fiber optic visual fault locator", "AC receptacle tester / circuit analyzer"], "answer": 1, "explanation": "An AC receptacle tester (or 3-prong circuit analyzer) plugs directly into a standard wall outlet and uses three diagnostic indicator lights to instantly confirm correct wiring, open ground, open neutral, open hot, or reversed hot/neutral polarity. ESD straps ground technicians, RF meters detect wireless waves, and visual fault locators test fiber optic continuity.", "distractor_analysis": {"1": "An ESD wrist strap drains static electricity from a technician's body to ground, but cannot test AC wall outlet polarity.", "2": "RF field meters measure high-frequency electromagnetic radiation, having no ability to test 120V/230V AC wall wiring.", "3": "A visual fault locator (VFL) uses a visible red laser to identify breaks in fiber optic strands, not electrical wall sockets."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["tools", "electrical", "receptacle-tester", "safety"]}, {"id": "C1-121", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "According to the CompTIA 6-step Troubleshooting Methodology, what is the very first step a technician must perform when responding to a technical support ticket?", "options": ["Implement the solution or escalate as necessary", "Document findings, actions, and outcomes", "Identify the problem (gather information, question user, identify symptoms)", "Establish a theory of probable cause (question the obvious)"], "answer": 2, "explanation": "Step 1 of the CompTIA Troubleshooting Methodology is to 'Identify the problem', which involves questioning the user, identifying user changes, performing backups before changes, inquiring about environmental changes, and reviewing system logs. Step 2 is establishing a theory, Step 4 is implementing the solution, and Step 6 is documenting findings.", "distractor_analysis": {"1": "Establishing a theory of probable cause is Step 2, performed after information is gathered in Step 1.", "2": "Implementing the solution is Step 4, performed after testing and confirming the theory in Step 3.", "3": "Documenting findings is Step 6, the final step performed after verifying full system functionality."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "methodology", "comptia", "best-practices"]}, {"id": "C1-122", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which standardized 8-position 8-contact (8P8C) modular copper connector is used on twisted-pair network cables to connect computer workstations to Ethernet LANs?", "options": ["BNC coaxial connector", "RJ-45 (8P8C) connector", "PS/2 Mini-DIN 6-pin connector", "DB-25 parallel printer connector"], "answer": 3, "explanation": "RJ-45 (Registered Jack 45 / 8P8C) is the universal standard modular connector used on Category 5e, 6, and 6a unshielded and shielded twisted-pair Ethernet cables. PS/2 connects legacy keyboards/mice, DB-25 connects legacy parallel printers, and BNC connects legacy coaxial video or 10BASE2 networks.", "distractor_analysis": {"1": "PS/2 Mini-DIN connectors were used for legacy keyboard (purple) and mouse (green) connections on older motherboards.", "2": "DB-25 is a 25-pin D-subminiature connector used for legacy IEEE 1284 parallel printer connections.", "3": "BNC is a bayonet-style coaxial cable connector used for CCTV video feeds and legacy 10BASE2 Thinnet networks."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "connectors", "rj45", "ethernet"]}, {"id": "C1-123", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "During custom PC assembly, which of the following materials is applied strictly as an interface layer between the top of the processor and the heatsink base, rather than being seated into a motherboard socket or slot?", "options": ["Central Processing Unit (CPU)", "DDR4 RAM memory module", "PCIe NVMe M.2 expansion card", "Thermal paste / thermal grease"], "answer": 1, "explanation": "Thermal paste (thermal interface material) is applied exclusively between the CPU integrated heat spreader (IHS) and the heatsink/waterblock base plate; it must never be allowed into CPU sockets or RAM slots. The CPU installs in the CPU socket, RAM inserts into DIMM slots, and M.2 SSDs install into M.2 slots on the motherboard.", "distractor_analysis": {"1": "The CPU is a semiconductor component that installs directly into the motherboard CPU socket (LGA or PGA).", "2": "RAM modules are printed circuit boards that insert directly into motherboard DIMM memory slots.", "3": "PCIe NVMe M.2 SSDs screw directly into dedicated M.2 slots on the motherboard PCB."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "thermal-paste", "motherboard", "assembly"]}, {"id": "C1-124", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following is an individual processing microchip component that requires a motherboard, RAM, power supply, and firmware to function, rather than being a complete standalone computer system?", "options": ["Touchscreen tablet", "Raspberry Pi single-board computer", "Central Processing Unit (CPU)", "Enterprise laptop"], "answer": 2, "explanation": "A CPU is an integrated circuit microchip that executes calculations and instructions; it is an individual component that cannot function on its own without supporting subsystems (motherboard, RAM, storage, power supply, firmware). Laptops, tablets, and Raspberry Pi devices are complete, fully functional computing systems containing all necessary subsystems.", "distractor_analysis": {"1": "A laptop is a complete standalone computer integrating motherboard, CPU, RAM, storage, display, keyboard, and battery.", "2": "A tablet is a complete mobile computer integrating processor, memory, storage, touchscreen, and operating system.", "3": "A Raspberry Pi is a complete single-board computer containing SoC, RAM, video output, USB controllers, and GPIO interfaces on one board."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "architecture", "concepts"]}, {"id": "C1-125", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "What term describes the fundamental internal hardware design, circuit layout, and pipeline implementation upon which specific families of microprocessors (such as Intel Alder Lake or AMD Zen 4) are engineered?", "options": ["Operating system swap file", "Microarchitecture", "High-level programming language", "Base-10 decimal numbering system"], "answer": 3, "explanation": "A microarchitecture is the underlying physical hardware implementation of an instruction set architecture (ISA), detailing pipeline stages, execution units, branch prediction logic, cache hierarchies, and semiconductor fabrication layouts for a CPU family (e.g., Intel Golden Cove, AMD Zen 4). High-level languages are software, decimal is a number system, and swap files are disk-based virtual memory.", "distractor_analysis": {"1": "High-level programming languages (Python, C++) are human-readable code compiled into machine instructions, not silicon CPU circuit designs.", "2": "Base-10 is standard human decimal counting; computer hardware operates internally in base-2 binary.", "3": "A swap file is operating system storage used for virtual memory paging, having no role in CPU semiconductor design."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "microarchitecture", "engineering"]}, {"id": "C1-126", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "How does a modern processor achieve multi-gigahertz core clock speeds (e.g., 4.5 GHz) when the motherboard base clock (BCLK) generator crystal operates at a standard frequency of 100 MHz?", "options": ["Liquid cooling radiator pumps", "Dual-channel memory bus interleaving", "Software virtual memory paging tables", "Internal CPU clock multipliers (Phase-Locked Loop / PLL circuitry)"], "answer": 1, "explanation": "Modern CPUs use internal clock multipliers driven by Phase-Locked Loop (PLL) circuits. The motherboard provides a stable base reference clock (BCLK, typically 100 MHz), and the CPU multiplies this frequency by an internal ratio multiplier (e.g., 100 MHz base clock x 45 multiplier = 4.5 GHz core frequency). Coolers regulate temperature, RAM interleaving increases memory bandwidth, and paging manages virtual storage.", "distractor_analysis": {"1": "Radiator pumps circulate cooling liquid to dissipate heat, but do not generate or multiply clock timing signals.", "2": "Memory bus interleaving distributes memory access across multiple channels to improve throughput, not CPU clock frequencies.", "3": "Virtual memory paging tables map virtual address spaces to physical memory, unrelated to hardware clock synthesis."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "clock-multiplier", "bclk"]}, {"id": "C1-127", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "In a modern multi-core processor's SRAM cache hierarchy, which level of cache has the largest capacity but the slowest access latency compared to the other internal caches?", "options": ["Level 2 (L2) dedicated core cache", "CPU internal general-purpose registers", "Level 3 (L3) shared cache", "Level 1 (L1) instruction/data cache"], "answer": 2, "explanation": "The CPU cache hierarchy is structured by speed and capacity: Registers are the fastest and smallest -> L1 Cache is next fastest (per core) -> L2 Cache is larger but slightly slower (per core) -> L3 Cache is the largest (shared across all cores) but has the highest latency of on-die SRAM caches. All caches remain significantly faster than system DRAM.", "distractor_analysis": {"1": "L1 cache is the fastest on-die SRAM cache, located directly adjacent to the CPU core execution pipelines with minimal single-cycle latency.", "2": "L2 cache is faster than L3 cache, typically dedicated to individual cores to provide low-latency intermediate storage.", "3": "Internal registers are tiny, ultra-fast memory cells integrated directly inside the execution ALU with zero wait states."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "cache", "l3-cache", "hierarchy"]}, {"id": "C1-128", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "A technician is about to remove a sensitive server CPU from its packaging and insert it into a motherboard. Which safety device must be attached to the technician's wrist and connected to unpainted chassis ground to prevent electrostatic damage?", "options": ["Magnetic screwdriver wristband", "Antistatic ESD wrist strap", "Insulated rubber high-voltage lineman gloves", "Grounding rod driven through the datacenter floor tile"], "answer": 3, "explanation": "An antistatic Electrostatic Discharge (ESD) wrist strap contains a conductive band and a 1-Megaohm current-limiting resistor attached via a clip to unpainted metal chassis ground. It continuously drains static electrical charges from the technician's body, preventing ESD damage to delicate semiconductor transistors. Rubber gloves are for high-voltage electricians, ground rods are building earth grounds, and magnetic wristbands hold steel screws.", "distractor_analysis": {"1": "High-voltage lineman gloves are thick rubber insulators used for working on energized high-voltage power lines, not delicate computer microelectronics.", "2": "Building ground rods are structural earthing components installed during building construction, not handheld technician wearables.", "3": "Magnetic screw wristbands hold steel screws and do not provide an electrical ground path for electrostatic discharge."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "esd", "safety", "wrist-strap"]}, {"id": "C1-129", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "In memory hardware terminology, what does the term 'double-sided RAM' traditionally signify regarding the electrical memory ranks and physical layout of the module?", "options": ["The RAM module can be physically installed upside down into the motherboard slot", "The RAM module provides both volatile DRAM and non-volatile NAND flash storage simultaneously", "The RAM module features two physical notch keys on opposite sides", "The memory module contains two separate electrical 64-bit ranks of chips, requiring the memory controller to switch between ranks"], "answer": 1, "explanation": "Electrically, 'double-sided' memory refers to a dual-rank module where memory chips are grouped into two separate 64-bit ranks (often physically mounted on both sides of the PCB). The memory controller accesses one rank at a time by toggling chip select lines. RAM modules are physically keyed and cannot be inserted upside down, do not mix NAND flash on standard DIMMs, and feature a single off-center keying notch.", "distractor_analysis": {"1": "DIMM slots have asymmetrical keying notches that strictly prevent installing modules upside down or in reverse orientation.", "2": "Standard DDR DIMMs use volatile dynamic RAM chips exclusively, not non-volatile flash storage.", "3": "Standard DDR DIMM modules feature a single physical keying notch positioned along the bottom contact edge."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "memory-ranks", "double-sided"]}, {"id": "C1-130", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "What term describes short adapter cables that plug into internal motherboard headers or proprietary ports to present standard external I/O connectors (such as USB, serial, or display jacks) at the chassis rear or front panel?", "options": ["PCIe riser bracket slot covers", "Heat spreader clamps", "Header adapter cables / breakout dongles", "Motherboard standoff screws"], "answer": 2, "explanation": "Header cables and breakout dongles plug into internal pin headers on the motherboard (e.g., USB 3.0, COM serial, audio, or Thunderbolt headers) and route the signals to external mounting brackets or chassis ports. Standoffs hold motherboards off the chassis, slot covers seal unused expansion bays, and clamps secure heatsinks.", "distractor_analysis": {"1": "Motherboard standoffs are threaded brass or steel spacers that physically support the motherboard and prevent electrical shorts to the chassis.", "2": "Slot covers are flat metal brackets that cover unused PCIe expansion openings at the rear of the computer case.", "3": "Heat spreader clamps physically fasten CPU heatsinks to socket retention brackets."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "motherboard", "cables", "dongles", "headers"]}, {"id": "C1-131", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "What is the primary operational benefit of implementing meticulous internal cable management (routing cables through chassis cutouts, behind the motherboard tray, and securing with zip ties)?", "options": ["It eliminates the need for grounded AC wall receptacles", "It optimizes internal chassis airflow, enhances cooling efficiency, and prevents cables from obstructing fan blades", "It automatically doubles the data transfer bandwidth of connected SATA storage drives", "It converts standard copper power wires into high-speed fiber-optic connections"], "answer": 3, "explanation": "Proper internal cable management secures wires neatly behind the motherboard tray and along chassis channels, eliminating tangled clutter that impedes intake/exhaust airflow across CPU and GPU heatsinks, while preventing loose cables from getting caught in spinning fan blades. Cable routing does not alter storage bus speed, change wire physics to fiber, or eliminate electrical grounding requirements.", "distractor_analysis": {"1": "SATA transfer speed is governed by the SATA revision specification and controller capabilities (e.g., 6 Gbps), unaffected by external cable routing aesthetics.", "2": "Cable management organizes physical copper wires; it cannot transform copper conductors into optical fiber.", "3": "Grounding electrical receptacles is a mandatory building safety standard, completely unrelated to chassis wire routing."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cable-management", "airflow", "cooling"]}, {"id": "C1-132", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following physical interface panels is mounted on the external front or top of a PC chassis to provide immediate user access to power controls and peripheral jacks?", "options": ["Motherboard rear I/O shield plate", "Power supply internal high-voltage transformer", "CPU voltage regulator module (VRM) chokes", "Front-panel I/O assembly (Power switch, Reset switch, Activity LEDs, USB and Audio ports)"], "answer": 1, "explanation": "The front-panel I/O assembly is mounted on the front or top of the computer case, containing the power push-button, reset switch, drive activity LEDs, front USB ports, and 3.5mm headphone/mic jacks wired via headers to the motherboard. The rear I/O shield sits at the back, transformers are sealed inside the PSU, and VRM chokes are on the motherboard.", "distractor_analysis": {"1": "The rear I/O shield is a metal bezel snapped into the back of the case around the motherboard onboard port cluster.", "2": "The high-voltage transformer is an internal electrical component inside the sealed PSU enclosure.", "3": "VRM chokes are square inductive power components soldered onto the motherboard near the CPU socket."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "case", "front-panel", "chassis"]}, {"id": "C1-133", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "When building or upgrading a workstation, why is it recommended to perform an out-of-case 'bench test' (installing CPU, cooler, RAM, and PSU on a non-conductive surface) before mounting the motherboard into the chassis?", "options": ["To format all secondary storage drives with FAT16 file systems", "To permanently solder the motherboard to the brass standoffs", "To verify POST functionality and ensure basic hardware operation before investing time in full chassis mounting and cable management", "To calibrate the internal liquid crystal display panel refresh rate"], "answer": 2, "explanation": "Bench testing (or breadboarding) the core components (motherboard, CPU, cooler, RAM, PSU, and display) on a non-conductive box or antistatic mat verifies that the core hardware initializes and passes POST. If a component is DOA (dead on arrival) or improperly seated, troubleshooting is fast and easy without having to disassemble a fully screwed-in case. Bench testing does not format disks, calibrate screens, or solder boards.", "distractor_analysis": {"1": "Bench testing verifies pre-boot electrical and POST viability, having no relation to LCD panel calibration.", "2": "Bench testing checks hardware initialization prior to OS boot, before any storage formatting occurs.", "3": "Motherboards are secured to standoffs using removable Phillips screws, never soldered permanently."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "motherboard", "assembly", "bench-testing"]}, {"id": "C1-134", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "easy", "question": "What dedicated auxiliary power cable connects directly from an ATX power supply to a 4-pin or 8-pin (EPS12V) header located near the CPU socket on the motherboard to provide dedicated power for the processor?", "options": ["Berg 4-pin floppy drive connector", "4-pin / 8-pin ATX12V / EPS12V CPU power connector", "15-pin SATA power connector", "4-pin Molex peripheral connector"], "answer": 3, "explanation": "The 4-pin ATX12V or 8-pin EPS12V connector connects directly from the power supply to the dedicated power header adjacent to the CPU socket, supplying dedicated +12V DC power to the processor voltage regulator modules (VRMs). SATA cables power storage drives, Molex powers legacy accessories, and Berg powered legacy floppy drives.", "distractor_analysis": {"1": "15-pin SATA power connectors deliver +3.3V, +5V, and +12V DC power to storage drives (HDDs, SSDs, optical drives).", "2": "4-pin Molex connectors supply +12V and +5V to legacy PATA hard drives, optical drives, and case accessories.", "3": "Berg connectors are small 4-pin power connectors designed for legacy 3.5-inch floppy diskette drives."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "psu", "cpu", "atx12v"]}, {"id": "C1-135", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following processor cooling architectures typically offers the lowest acoustic noise levels during high-workload processing?", "options": ["Small high-RPM 40mm server chassis blower fan", "Stock low-profile aluminum air heatsink with a screaming 70mm fan", "Unmuffled industrial server delta-vane fan running at 8,000 RPM", "Large-radiator closed-loop liquid cooling with large low-RPM fans"], "answer": 1, "explanation": "Liquid cooling systems featuring large radiators (280mm or 360mm) equipped with large-diameter (120mm/140mm) fans can spin at much lower RPM while dissipating large amounts of thermal energy, producing whisper-quiet acoustic noise. Small fans must spin at extreme RPMs (e.g., 5,000-8,000 RPM in 1U/2U rack servers), producing loud, high-pitched whining noise.", "distractor_analysis": {"1": "Small 40mm blower fans must spin at extreme speeds to move sufficient air volume, generating loud, high-pitched whine.", "2": "Low-profile small aluminum heatsinks have low thermal mass, forcing small fans to spin at maximum speed under load.", "3": "High-RPM server delta fans generate industrial-grade noise exceeding 60-70 dB, designed purely for datacenter airflow rather than quiet operation."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cooling", "acoustics", "noise", "liquid-cooling"]}, {"id": "C1-136", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "When a computer CPU reaches critical thermal junction limits (Tjunction Max) due to a failed cooling fan or unseated heatsink, what safety behavior is automatically triggered by the processor hardware?", "options": ["Automatic deletion of the operating system bootloader partition", "Reversing the AC power plug polarity at the wall outlet", "Aggressive thermal throttling (reducing clock multipliers and voltage) followed by thermal emergency shutdown", "Permanent overclocking to burn off excess heat through copper traces"], "answer": 2, "explanation": "Modern processors have built-in digital thermal sensors (DTS) that monitor junction temperature in real time. If temperatures exceed safe operating thresholds (typically 95-105 C), the CPU automatically engages thermal throttling (lowering clock frequencies and voltages to reduce heat); if temperatures continue rising, the CPU triggers an immediate hardware thermal trip shutdown to prevent physical silicon destruction. CPUs do not delete bootloaders or invert AC polarity.", "distractor_analysis": {"1": "Overclocking increases power draw and thermal generation, accelerating thermal destruction rather than cooling.", "2": "Thermal protection circuits are purely hardware safety triggers that cut CPU power; they do not modify or delete disk partitions.", "3": "Processor thermal sensors operate within the CPU die and cannot physically manipulate external building AC wall wiring."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "cpu", "thermal-throttling", "overheating"]}, {"id": "C1-137", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which dedicated diagnostic testing tool plugs into all output harnesses of an ATX power supply (24-pin, EPS12V, PCIe, SATA, Molex) to measure and verify +12V, +5V, +3.3V, and Power Good (PG) signals under load?", "options": ["Loopback plug inserted into a USB port", "Power supply tester (PSU tester)", "Bent metal paperclip inserted into green wire pins", "Optical time-domain reflectometer"], "answer": 3, "explanation": "A specialized power supply tester connects to the 24-pin ATX main harness, 8-pin CPU, PCIe, and peripheral connectors, displaying exact voltage levels for the +12V, +5V, +3.3V, -12V, and +5VSB rails on an LCD screen along with the Power Good (PG) millisecond delay timer. Paperclips only short the PS_ON pin to ground to test basic spin-up without measuring voltage stability, TDRs test cables, and loopback plugs test network/serial ports.", "distractor_analysis": {"1": "The paperclip test only bridges PS_ON (green wire) to ground (black wire) to see if fans spin, but cannot measure voltage tolerance or voltage drop under load.", "2": "An OTDR is an optical testing instrument used to characterize fiber-optic cabling, not electrical power supplies.", "3": "A loopback plug tests physical network, serial, or parallel port transceiver circuitry, not power supply voltage rails."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["tools", "psu", "power-supply-tester", "troubleshooting"]}, {"id": "C1-138", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A technician hears a loud pop inside a desktop computer case followed immediately by complete power loss and an acrid, pungent burning chemical odor. What catastrophic hardware failure has occurred?", "options": ["Operating system screen saver timeout", "DisplayPort cable shielding grounding loop", "Thermal paste curing on the CPU heatsink", "Power supply unit capacitor rupture / electrical blowout"], "answer": 1, "explanation": "A loud popping sound followed by immediate power shutdown and a pungent burning chemical smell is the classic signature of an electrolytic capacitor blowout or catastrophic switching MOSFET failure inside the power supply unit (or motherboard VRM). Screen savers are software, cable grounding loops cause subtle hums/flicker, and thermal paste curing is odorless.", "distractor_analysis": {"1": "Screen savers are graphical OS utilities that activate during idle periods without making sounds or emitting burning odors.", "2": "Ground loops in display cables cause visual hum bars or audio buzzing, not loud mechanical pops or burning smells.", "3": "Thermal paste curing is a gradual, odorless thermodynamic bonding process between heatsinks and CPUs."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "power", "psu", "capacitors"]}, {"id": "C1-139", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A user reports a loud, rhythmic clicking or buzzing noise coming from inside a running desktop tower that started immediately after the PC was moved. What is the most probable mechanical cause?", "options": ["The CPU instruction decoder is processing floating-point calculations", "The optical fiber patch cord is transmitting high-speed laser pulses", "A loose internal power or data cable has shifted into contact with spinning cooling fan blades", "The system RAM memory chips are executing parity error checksums"], "answer": 2, "explanation": "Loud, rhythmic buzzing or clicking sounds that appear after moving a computer are almost universally caused by an unmanaged internal cable or zip tie shifting into the path of spinning chassis or heatsink fan blades. Solid-state RAM chips, CPU execution units, and fiber-optic pulses make zero acoustic mechanical noise.", "distractor_analysis": {"1": "RAM is solid-state semiconductor memory with no moving physical parts; parity checks generate zero audible sound.", "2": "CPU floating-point calculation occurs at the microscopic transistor level and produces no mechanical sound.", "3": "Optical fiber carries modulated light photons through glass, which generates zero acoustic mechanical noise."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "noise", "fans", "cables"]}, {"id": "C1-140", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A technician installs two new 16 GB DDR4 memory modules into a desktop computer. When booting into the UEFI/BIOS setup utility, only 16 GB of RAM is detected across all channels instead of 32 GB. What is the first troubleshooting action the technician should take?", "options": ["Reinstall the 64-bit operating system from installation media", "Power off the system, remove the RAM modules, inspect for dust, and firmly reseat both modules into the designated primary slots until latches click", "Replace the motherboard voltage regulator modules with higher amperage capacitors", "Flash the solid-state drive firmware to a legacy version"], "answer": 3, "explanation": "When installed memory fails to register in BIOS/UEFI setup, the most common issue is improper physical seating (DIMM latches not fully locked) or debris in the slot contacts. Powering off, inspecting the slot, and firmly reseating the modules until the retaining latches snap into place resolves the vast majority of memory detection issues. Soldering VRMs, flashing SSDs, or reinstalling the OS does not fix pre-boot hardware DIMM detection.", "distractor_analysis": {"1": "Motherboard VRM capacitors are factory-soldered components that should not be modified by field technicians.", "2": "SSD firmware manages storage controller flash translation layers and has no impact on RAM detection in BIOS.", "3": "Operating system reinstallation only affects secondary disk software; the BIOS detects RAM long before the OS loads."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "ram", "seating", "bios"]}, {"id": "C1-141", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following is a system firmware management interface rather than a physical bootable storage medium that can be configured in a BIOS/UEFI boot device priority list?", "options": ["USB Flash Drive", "M.2 NVMe Solid-State Drive", "PXE Network Boot Interface (Ethernet NIC)", "UEFI Firmware Setup Utility"], "answer": 1, "explanation": "UEFI (Unified Extensible Firmware Interface) is the motherboard firmware environment and setup utility itself, not a storage medium containing an operating system bootloader. USB flash drives, NVMe SSDs, optical discs, and PXE network adapters are valid boot devices that can be set in the boot order list.", "distractor_analysis": {"1": "USB flash drives containing bootable ISO media (e.g., Windows installer) are standard primary boot choices.", "2": "M.2 NVMe SSDs hosting the primary OS partition (e.g., Windows Boot Manager) are standard primary boot devices.", "3": "PXE network boot allows a computer to boot an OS image across the local network via its NIC."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "uefi", "boot-order"]}, {"id": "C1-142", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A user turns on their desktop computer and encounters a black screen with the error message: 'No bootable device found. Press any key to retry.' What is the most likely cause of this error?", "options": ["The USB mouse optical sensor is dirty and failing to register movement", "The monitor HDMI cable is operating in High-Speed mode instead of Standard mode", "The UEFI/BIOS boot order is prioritized to a non-bootable USB drive or the internal primary drive boot sector is disconnected/corrupted", "The computer case fan speed is set to Silent mode in motherboard settings"], "answer": 2, "explanation": "'No bootable device found' occurs when the BIOS/UEFI attempts to boot from the configured boot sequence but finds no valid Master Boot Record (MBR) or EFI System Partition (ESP) bootloader (e.g., an unbootable flash drive was left plugged in, the internal drive SATA/NVMe cable became disconnected, or the drive failed). Fan speeds, mouse sensors, and HDMI cable modes do not trigger boot sector errors.", "distractor_analysis": {"1": "Fan speed profiles control cooling noise and thermal curves, having no impact on storage boot device detection.", "2": "A dirty optical mouse sensor affects cursor tracking in the OS, completely unrelated to firmware boot device discovery.", "3": "HDMI cable speed modes govern digital video bandwidth, with no influence on storage bootloader execution."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "boot", "no-boot-device", "bios"]}, {"id": "C1-143", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "According to the legacy PC 99 system design standard, what color coding is designated for the physical 6-pin Mini-DIN PS/2 mouse port?", "options": ["Pink (Microphone Input)", "Green (PS/2 Mouse)", "Purple (PS/2 Keyboard)", "Teal (Serial COM Port)"], "answer": 3, "explanation": "Under the industry-standard Microsoft/Intel PC 99 design guide, PS/2 mouse ports are color-coded Green, while PS/2 keyboard ports are color-coded Purple. Pink is color-coded for analog microphone inputs, and Light Blue is for audio line-in.", "distractor_analysis": {"1": "Purple is the designated standard color for the PS/2 Mini-DIN keyboard port.", "2": "Teal/Turquoise was historically used for legacy DB-9 serial COM ports on older ATX motherboards.", "3": "Pink is the universal standard color coding for the 3.5mm analog microphone input jack."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "connectors", "ps2", "color-coding"]}, {"id": "C1-144", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which standard Windows operating system management console or configuration applet allows a technician to customize mouse pointer speed, double-click sensitivity, and button mapping?", "options": ["Disk Management console (diskmgmt.msc)", "Performance Monitor (perfmon.msc)", "Services management console (services.msc)", "Windows Settings (Bluetooth & devices -> Mouse) / Control Panel (Mouse applet)"], "answer": 1, "explanation": "Mouse settings (pointer speed, acceleration, primary button swapping, double-click speed, scroll wheel lines) are configured in Windows Settings under 'Bluetooth & devices -> Mouse' or via the classic 'Mouse' applet (main.cpl) in Control Panel. Disk Management handles drive partitions, Performance Monitor graphs hardware metrics, and Services manages background OS services.", "distractor_analysis": {"1": "Disk Management is used to partition, format, and assign drive letters to storage drives.", "2": "Performance Monitor graphs real-time CPU, memory, and disk counters for system performance analysis.", "3": "Services console is used to start, stop, and configure startup types for background Windows services."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "peripherals", "mouse", "windows", "configuration"]}, {"id": "C1-145", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which dedicated audio interface standard provides pure multi-channel digital audio output over optical fiber (TOSLINK) or coaxial RCA cables to home theater receivers without analog conversion loss?", "options": ["Analog pink 3.5mm microphone jack", "DB-15 legacy MIDI/gameport connector", "Sony/Philips Digital Interface (S/PDIF)", "3.5mm analog stereo headphone jack"], "answer": 2, "explanation": "S/PDIF (Sony/Philips Digital Interface) is a dedicated digital audio interconnect standard that carries uncompressed stereo PCM or compressed 5.1/7.1 surround sound (Dolby Digital/DTS) over optical fiber (TOSLINK) or 75-ohm coaxial RCA cables without suffering analog signal degradation. Standard 3.5mm jacks carry analog electrical voltages.", "distractor_analysis": {"1": "The 3.5mm TRS stereo jack transmits analog audio voltages prone to electrical noise and ground loop hum.", "2": "The pink 3.5mm jack is an analog microphone input, converting analog voice signals to electrical voltages.", "3": "The DB-15 gameport was a legacy 1990s port for analog joysticks and MIDI musical instruments."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "audio", "spdif", "toslink", "digital-audio"]}, {"id": "C1-146", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "When selecting a physical expansion slot on a motherboard to install a high-end dual-slot discrete graphics card, which of the following is NOT a physical hardware clearance or architectural consideration?", "options": ["The physical lane width and generation of the slot (e.g., PCIe 4.0 x16 wired directly to the CPU)", "The specific version and edition of the desktop operating system to be installed later", "Physical slot clearance and obstruction of adjacent PCIe slots by the thick cooler shroud", "Adequate chassis airflow spacing between the GPU intake fans and the PSU shroud or adjacent cards"], "answer": 3, "explanation": "The specific software operating system version has zero bearing on the physical slot selection on the motherboard PCB; PCIe hardware standards are universally governed by hardware geometry and electrical signaling. Physical slot spacing, cooler clearance, airflow obstruction, and electrical lane routing (x16 directly to CPU vs chipset) are critical hardware considerations.", "distractor_analysis": {"1": "Multi-slot GPU cooler shrouds often physically block adjacent PCIe slots, requiring careful placement planning.", "2": "Ensuring adequate clearance between GPU fans and adjacent components is critical to prevent thermal throttling.", "3": "Installing a GPU in a slot with full x16 CPU lanes ensures maximum memory and compute bandwidth."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "pcie", "expansion-cards", "motherboard", "form-factor"]}, {"id": "C1-147", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following is a dangerous, incorrect procedure that must NEVER be performed when installing an internal PCIe expansion card onto a motherboard?", "options": ["Powering off the PC, unplugging the AC power cord, and pressing the power button to discharge capacitors", "Aligning the card bracket with the chassis opening and pressing firmly until seated evenly", "Securing the metal card retention bracket to the chassis frame with a mounting screw", "Installing the expansion card into the PCIe slot while the computer is fully powered on and running"], "answer": 1, "explanation": "Standard PCIe expansion cards on desktop motherboards are not hot-pluggable. Attempting to insert or remove a PCIe card while the system is powered on causes massive electrical short circuits across power pins (+12V/+3.3V), instantly destroying the expansion card, motherboard, and processor. Proper procedure requires shutting down, unplugging AC power, discharging residual power, seating the card, and screwing down the bracket before powering on.", "distractor_analysis": {"1": "Disconnecting AC power and draining residual capacitance is the mandatory electrical safety procedure for internal PC maintenance.", "2": "Aligning the card and pressing firmly until it seats evenly into the PCIe slot is the standard installation procedure.", "3": "Securing the bracket with a screw or chassis latch prevents mechanical sagging and prevents the card from pulling out of the slot."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "pcie", "safety", "installation"]}, {"id": "C1-148", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "When sizing and building a dedicated workstation intended to host multiple concurrent virtual machines simultaneously, which two hardware resources require the largest capacity allocations?", "options": ["Analog 5.1 surround sound audio expansion card and microphone preamp", "Optical Blu-ray writer drive and mechanical floppy drive", "Physical System RAM capacity and Multi-Core CPU processing threads", "High-end 3D ray-tracing gaming graphics card and RGB lighting controller"], "answer": 2, "explanation": "Virtualization workstations partition physical host compute resources among multiple guest operating systems. Therefore, maximizing physical RAM capacity (so each guest VM has sufficient dedicated memory without paging) and multi-core CPU threads (providing vCPUs for concurrent execution) are the two most critical hardware requirements. 3D gaming GPUs, sound cards, and optical drives are non-essential for virtualization hosts.", "distractor_analysis": {"1": "High-end 3D ray-tracing GPUs are built for gaming and workstation 3D rendering, unnecessary for standard server virtualization hosts.", "2": "Surround sound audio cards provide analog audio output, having no impact on virtualization capacity or VM density.", "3": "Optical Blu-ray and floppy drives are legacy storage devices completely unnecessary for modern VM provisioning via ISO images."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hardware", "cpu", "ram", "sizing"]}, {"id": "C1-149", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "What is the core hardware storage technology implemented inside a Network Attached Storage (NAS) appliance to ensure high data availability and protect stored shared files against drive failure?", "options": ["Dual-port analog 56k dial-up modem card", "Redundant Array of Independent Disks (RAID array)", "Single standalone unpartitioned dynamic disk", "Internal optical DVD-RAM jukebox"], "answer": 3, "explanation": "Network Attached Storage (NAS) appliances rely on RAID arrays (such as RAID 1, RAID 5, RAID 6, or RAID 10) across multiple hard drives or SSDs to provide storage pooling, data redundancy, and uninterrupted file-sharing services even if one or two drives fail. Standalone single disks provide no redundancy, optical jukeboxes are legacy archives, and 56k modems are obsolete dial-up interfaces.", "distractor_analysis": {"1": "A single standalone disk has no fault tolerance; if that drive fails, all shared NAS data is immediately lost.", "2": "Optical jukeboxes are specialized legacy archival hardware, not standard NAS file storage engines.", "3": "56k dial-up modems provide slow analog serial WAN communication, completely irrelevant to LAN NAS storage arrays."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "nas", "raid", "fault-tolerance"]}, {"id": "C1-150", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "Which of the following statements is INCORRECT regarding Digital Visual Interface (DVI) video connectors and signaling standards?", "options": ["DVI-I (Integrated) carries both digital video signals and analog RGB video signals on the same physical connector", "DVI-D (Digital-only) carries purely digital video streams and cannot be connected to VGA with a passive pin adapter", "Dual-Link DVI incorporates a second TMDS data transmitter to support higher resolutions (e.g., 2560x1600 at 60Hz)", "DVI-I connectors can only carry analog RGB signals and are incapable of transmitting digital video"], "answer": 1, "explanation": "DVI-I (Integrated) carries BOTH digital signals (via TMDS pins) and analog RGB signals (via the four pins surrounding the flat blade). Therefore, stating that DVI-I can only carry analog signals is false. DVI-D is digital-only, and Dual-Link DVI doubles bandwidth for high-resolution displays.", "distractor_analysis": {"1": "DVI-I indeed integrates both digital and analog pins, allowing passive DVI-to-VGA adapters to extract the analog signal.", "2": "DVI-D omits the analog pins around the flat blade and only transmits digital TMDS signals.", "3": "Dual-link DVI features 24 digital pins utilizing two TMDS transmitters to support resolutions up to 2560x1600."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "dvi", "video", "connectors"]}, {"id": "C1-151", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A user notices that their external desktop monitor displays distorted color patterns (such as a severe pink or green color tint across the entire image). Which troubleshooting action should the technician perform first?", "options": ["Degauss the LED backlit monitor using an electromagnetic wand", "Permanently disable hardware graphics acceleration in the OS", "Inspect the video cable pins and firmly reseat the video cable connectors at both ends", "Replace the liquid crystal display panel subpixel matrix"], "answer": 2, "explanation": "Incorrect or tinted color patterns across a display are commonly caused by a loose, unseated, or damaged video cable (VGA, DVI, HDMI, DisplayPort) where individual color signal pins (red, green, or blue channels) lose physical electrical contact. Reseating or replacing the cable resolves this. Dead pixels or subpixel physical defects require panel replacement, degaussing only applies to vintage CRT monitors, and disabling GPU acceleration does not fix physical pin contacts.", "distractor_analysis": {"1": "Replacing the LCD panel is an expensive physical teardown and should only be considered after testing basic external cable seating.", "2": "Degaussing is a magnetic demagnetizing procedure used exclusively on cathode ray tube (CRT) monitors, not flat-panel LED displays.", "3": "Disabling GPU hardware acceleration alters software rendering pipelines and cannot restore disconnected physical video cable pins."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "cables", "color-tint"]}, {"id": "C1-152", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "Which of the following conditions is NOT a cause of graphics card (GPU) overheating and thermal throttling inside a workstation chassis?", "options": ["Sustained 100% compute workload during 3D rendering or cryptographic hashing", "A failed CCFL high-voltage backlight inverter inside an external monitor", "A seized or malfunctioning GPU cooling fan", "Clogged chassis intake dust filters and inadequate case ventilation"], "answer": 3, "explanation": "A high-voltage backlight inverter is an internal component of older CCFL-backlit LCD monitors; if it fails, the external monitor screen goes black or very dim, but it has zero physical or thermal connection to the computer's internal PCIe graphics card. Seized GPU fans, clogged chassis filters, and sustained 100% GPU compute workloads directly cause graphics card overheating.", "distractor_analysis": {"1": "A failed or seized GPU fan stops forced-air convection across the GPU heatsink fins, causing immediate thermal spikes.", "2": "Clogged dust filters prevent cool ambient air from entering the chassis, starving internal components of cooling airflow.", "3": "Sustained heavy 3D or compute workloads push GPU power draw to maximum TDP, generating high continuous heat."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "gpu", "overheating", "display"]}, {"id": "C1-153", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "What is the correct hexadecimal character representation of the 4-bit binary nibble 1100?", "options": ["Hexadecimal A (decimal value 10)", "Hexadecimal B (decimal value 11)", "Hexadecimal D (decimal value 13)", "Hexadecimal C (decimal value 12)"], "answer": 1, "explanation": "In hexadecimal conversion, 4-bit binary values map as follows: 1010 = A (10), 1011 = B (11), 1100 = C (12), 1101 = D (13), 1110 = E (14), and 1111 = F (15). Therefore, 1100 (8 + 4 = 12) equals hexadecimal C.", "distractor_analysis": {"1": "Hexadecimal A represents binary 1010 (decimal 10).", "2": "Hexadecimal B represents binary 1011 (decimal 11).", "3": "Hexadecimal D represents binary 1101 (decimal 13)."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "hexadecimal", "binary", "addressing"]}, {"id": "C1-154", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "How many hexadecimal characters are used to represent a 48-bit Layer 2 Media Access Control (MAC) address?", "options": ["16 hex characters, arranged as eight pairs", "32 hex characters, arranged as sixteen pairs", "12 hex characters, six pairs such as 00:1A:2B:3C:4D:5E", "8 hex characters, arranged as four pairs"], "answer": 2, "explanation": "A standard MAC address is 48 bits long. Because each hexadecimal character represents exactly 4 bits (a nibble), 48 bits / 4 bits = 12 hexadecimal characters (expressed as 6 colon- or hyphen-separated octets, e.g., 00:1A:2B:3C:4D:5E, or 3 groups of 4 digits in Cisco format 001a.2b3c.4d5e).", "distractor_analysis": {"1": "8 hex characters is 32 bits, the size of an IPv4 address, not a MAC.", "2": "16 hex characters is 64 bits, which matches an EUI-64 interface identifier rather than a MAC.", "3": "32 hex characters is 128 bits, the size of an IPv6 address."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "mac-address", "hexadecimal", "layer-2"]}, {"id": "C1-155", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "In an IPv4 subnet mask (such as 255.255.255.0), what does the value 255 in an octet indicate to the IP routing stack?", "options": ["The network interface must operate in half-duplex mode", "All 8 bits in that octet represent the network portion of the address and must match within the subnet", "All 8 bits in that octet are available for assigning unique host interfaces", "The octet is reserved exclusively for multicast streaming groups"], "answer": 3, "explanation": "In IPv4 subnet masking, 255 in decimal equals 11111111 in binary (all 1s). A bit value of 1 in a subnet mask designates that the corresponding bit in the IP address belongs to the Network/Subnet ID. Conversely, a bit value of 0 (e.g., in the last octet of a /24 mask) indicates available Host ID bits.", "distractor_analysis": {"1": "Host address bits are indicated by 0s in the subnet mask, not 255 (which is all 1s).", "2": "Multicast addresses are defined by Class D IPv4 address ranges (224.0.0.0/4), not the subnet mask value 255.", "3": "Duplex mode is a Layer 2 physical/data link layer negotiation setting completely independent of Layer 3 subnet masks."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "subnet-mask", "ipv4", "addressing"]}, {"id": "C1-156", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A traveling executive cannot connect to a hotel wireless network that their laptop previously used last month. The hotel reports the Wi-Fi is working for other guests. What is the most practical first troubleshooting step on the executive's laptop?", "options": ["Reboot the hotel core gateway router into recovery mode", "Install a high-gain directional Yagi antenna onto the laptop display bezel", "Re-flash the laptop motherboard BIOS firmware", "Delete / forget the saved wireless network profile and reconnect by entering the current credentials"], "answer": 1, "explanation": "When a client device cannot connect to a previously used public or commercial Wi-Fi network, the cached wireless profile on the laptop often contains outdated security certificates, encryption keys, or authentication parameters from the previous stay. Deleting ('forgetting') the network profile in Windows/macOS forces the OS to re-probe the SSID and prompt for fresh authentication credentials. Guests cannot reboot hotel infrastructure, hardware antennas are unnecessary, and BIOS flashing is inappropriate.", "distractor_analysis": {"1": "End users and guests have no administrative authorization or physical access to hotel enterprise network routers.", "2": "Attaching external directional Yagi antennas is unnecessary for standard hotel Wi-Fi and impractical for business travel.", "3": "Flashing system BIOS firmware is high-risk and irrelevant to standard 802.11 cached SSID profile authentication errors."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["troubleshooting", "wireless", "wifi", "profiles", "forget-network"]}, {"id": "C1-157", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "Which of the following statements is INCORRECT regarding legacy analog dial-up Internet connections compared to modern broadband connections?", "options": ["Broadband connections (DSL, Cable, Fiber) provide 'always-on' high-speed connectivity", "Cable broadband networks transmit data over coaxial lines using the DOCSIS specification", "Analog dial-up connections support multi-megabit broadband speeds of 1.5 Mbps to 100 Mbps", "Analog dial-up connections max out at a theoretical maximum speed of 56 Kbps using the V.90/V.92 standard"], "answer": 2, "explanation": "Analog dial-up connections over the public switched telephone network (PSTN) are fundamentally limited by voice-band analog audio bandwidth to a theoretical maximum of 56 Kbps (0.056 Mbps); they cannot achieve multi-megabit broadband speeds. Broadband is always-on, DSL uses PPPoE/ATM over copper phone pairs, and cable broadband uses DOCSIS over hybrid fiber-coaxial lines.", "distractor_analysis": {"1": "Dial-up modem technology historically peaked at 56 Kbps under the ITU V.90 and V.92 standards.", "2": "Broadband services maintain continuous dedicated digital connections without dialing up phone numbers.", "3": "Cable modems utilize Data Over Cable Service Interface Specification (DOCSIS) standards to provide high-speed internet over TV coaxial cable."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "internet-connections", "dial-up", "broadband", "docsis"]}, {"id": "C1-158", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "In File Transfer Protocol (FTP) operations, which standard TCP port is used for command/control session management, and which TCP port is used for active mode data transfers?", "options": ["TCP port 80 for Control and TCP port 443 for Data", "TCP port 21 for Control/Commands and TCP port 20 for Active Data transfer", "TCP port 20 for Control and TCP port 21 for Data", "TCP port 22 for Control and TCP port 23 for Data"], "answer": 3, "explanation": "Standard File Transfer Protocol (FTP) uses two separate TCP ports: TCP port 21 is the Control port (used for establishing the connection, authentication, and issuing commands like GET/PUT), while TCP port 20 is the Data port used in Active FTP mode for transferring the actual files. Port 22 is SSH/SFTP, Port 23 is Telnet, Port 80 is HTTP, and Port 443 is HTTPS.", "distractor_analysis": {"1": "The port roles are reversed; port 21 handles control commands and port 20 handles active data connections.", "2": "TCP port 22 is Secure Shell (SSH) and TCP port 23 is Telnet, which are remote command-line terminal protocols.", "3": "TCP port 80 (HTTP) and TCP port 443 (HTTPS) are web protocols, not standard FTP ports."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "ftp", "protocols"]}, {"id": "C1-159", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which of the following built-in hardware input devices is permanently integrated directly into the palmrest of standard portable laptop computers but absent on standalone desktop tower cases?", "options": ["Dedicated function keys (F1 through F12)", "Operating system graphics driver stack", "Direct motherboard expansion slots", "Integrated capacitive touchpad / trackpad with gesture support"], "answer": 1, "explanation": "A capacitive touchpad (or trackpad) is integrated directly into the laptop palmrest assembly to provide pointing and gesture control without requiring an external mouse. Desktop computers rely on external standalone mice. Function keys exist on desktop keyboards, graphics drivers are software, and expansion slots are internal.", "distractor_analysis": {"1": "Function keys (F1-F12) are standard on all full-size desktop keyboards as well as laptop keyboards.", "2": "Operating system graphics drivers are software modules present on both desktop and laptop systems.", "3": "Direct expansion slots (PCIe) are standard features on desktop motherboards."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "touchpad", "hardware"]}, {"id": "C1-160", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "What technology superimposes computer-generated digital graphical elements, text, and 3D overlays onto the user's real-world physical visual environment in real time?", "options": ["DisplayPort Multi-Stream Transport (MST)", "Liquid Crystal Subpixel Addressing", "Augmented Reality (AR)", "Fully immersive Virtual Reality (VR)"], "answer": 2, "explanation": "Augmented Reality (AR) superimposes computer-generated graphics, sensor telemetry, and digital annotations on top of the real physical world (viewed through smartphone cameras, smart glasses, or heads-up displays). Virtual Reality (VR) replaces the physical world entirely with a simulated virtual environment. MST is display daisy-chaining, and subpixel addressing is an LCD panel driving method.", "distractor_analysis": {"1": "Virtual Reality (VR) occludes the physical world completely, immersing the user in an entirely synthetic 3D environment via a closed headset.", "2": "DisplayPort MST is a video cable standard that allows daisy-chaining multiple physical monitors.", "3": "Subpixel addressing is the electronic driving of individual red, green, and blue subpixels in flat-panel displays."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "augmented-reality", "ar", "vr"]}, {"id": "C1-161", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "easy", "question": "Which of the following user actions is a high-risk security hazard that invites malware infections and phishing exploits rather than a cybersecurity best practice?", "options": ["Enabling and configuring a host-based stateful firewall", "Opening and executing unexpected email file attachments and embedded macro links from unknown senders", "Applying operating system and application security patches regularly", "Maintaining active, updated anti-malware and endpoint detection software"], "answer": 3, "explanation": "Opening unverified email attachments, downloading unknown payloads, or executing embedded macros from untrusted sources is a major vector for ransomware, trojans, and credential harvesting. In contrast, applying security updates promptly, running anti-malware protection, and maintaining host firewalls are core defense-in-depth best practices.", "distractor_analysis": {"1": "Regularly applying software security patches closes known vulnerabilities before attackers can exploit them.", "2": "Running updated anti-malware software detects and blocks malicious binaries in real time.", "3": "Configuring a host-based firewall restricts unauthorized incoming network probes and rogue connections."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["security", "best-practices", "malware", "email"]}, {"id": "C1-162", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "easy", "question": "On a standard 4-pin Molex peripheral power connector from an ATX power supply, what DC voltage is delivered by the yellow wire?", "options": ["+5 V DC (Red wire)", "+3.3 V DC (Orange wire)", "Ground / Common 0V (Black wires)", "+12 V DC (Yellow wire)"], "answer": 1, "explanation": "On a standard 4-pin Molex power connector: the Yellow wire delivers +12V DC (primarily powering drive spindle motors and fans), the Red wire delivers +5V DC (powering logic circuitry), and the two center Black wires provide electrical Ground. +3.3V is delivered via Orange wires on 24-pin ATX and SATA power connectors.", "distractor_analysis": {"1": "+5V DC is supplied by the Red wire on Molex, 24-pin ATX, and SATA power connectors.", "2": "+3.3V DC is supplied by Orange wires on modern SATA power and 24-pin main ATX connectors, absent on 4-pin Molex.", "3": "Ground (0V reference) is provided by the two center Black wires on the 4-pin Molex connector."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "molex", "voltage", "color-coding"]}, {"id": "C1-163", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which CPU socket architecture features arrayed metal contact pins protruding from the bottom of the processor package that insert into matching socket holes on the motherboard?", "options": ["Ball Grid Array (BGA)", "Surface Mount Technology (SMT)", "Pin Grid Array (PGA)", "Land Grid Array (LGA)"], "answer": 2, "explanation": "In a Pin Grid Array (PGA) socket design (traditionally used on AMD socket AM4 and older Intel processors), the physical connector pins are attached to the processor package and insert into mating holes on the motherboard socket, locked in place by a Zero Insertion Force (ZIF) lever. LGA places the pins in the socket, and BGA is soldered.", "distractor_analysis": {"1": "Land Grid Array (LGA) places the spring-loaded pins inside the motherboard socket, while the processor has flat gold contact pads.", "2": "Ball Grid Array (BGA) solders the processor directly onto the motherboard PCB using microscopic solder balls.", "3": "Surface Mount Technology (SMT) is an automated manufacturing process for soldering components onto PCBs."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "cpu", "pga", "sockets"]}, {"id": "C1-164", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "easy", "question": "How many total electrical contact pins are present on a standard desktop DDR4 unbuffered Dual In-line Memory Module (DIMM)?", "options": ["204 pins", "288 pins", "240 pins", "260 pins"], "answer": 3, "explanation": "DDR4 desktop unbuffered DIMMs feature 288 pins with an off-center keying notch and slightly curved bottom edge to reduce insertion force. 240 pins is used for DDR2 and DDR3 desktop DIMMs, 260 pins is for DDR4 laptop SO-DIMMs, and 204 pins is for DDR3 laptop SO-DIMMs.", "distractor_analysis": {"1": "240 pins is the standard pin count for DDR2 and DDR3 desktop DIMMs.", "2": "260 pins is the standard pin count for DDR4 laptop SO-DIMM modules.", "3": "204 pins is the standard pin count for DDR3 laptop SO-DIMM modules."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "ddr4", "pin-counts"]}, {"id": "C1-165", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "What is the maximum theoretical interface signaling bandwidth of the Serial ATA Revision 3.0 (SATA III) storage specification?", "options": ["1.5 Gbps (yielding ~150 MB/s throughput)", "3 Gbps (yielding ~300 MB/s throughput)", "10 Gbps (yielding ~1 GB/s throughput)", "6 Gbps (yielding ~600 MB/s actual uncompressed throughput)"], "answer": 1, "explanation": "The SATA Revision 3.0 (SATA III) standard operates at a bus speed of 6 Gbps, which after 8b/10b line encoding overhead provides a maximum net data throughput of approximately 600 MB/s. SATA I operates at 1.5 Gbps, SATA II operates at 3 Gbps, and 10 Gbps is standard for USB 3.2 Gen 2.", "distractor_analysis": {"1": "1.5 Gbps was the bandwidth of first-generation SATA Revision 1.0 (SATA I).", "2": "3 Gbps was the bandwidth of second-generation SATA Revision 2.0 (SATA II).", "3": "10 Gbps is the bandwidth of USB 3.2 Gen 2 or 10GBASE-T Ethernet, not SATA."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "sata", "bandwidth", "specifications"]}, {"id": "C1-166", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "Which high-performance solid-state drive host interface communicates directly across PCIe lanes to achieve multi-gigabyte per second throughput and ultra-low command latency?", "options": ["mSATA (Mini-SATA)", "Parallel ATA (PATA / IDE)", "Non-Volatile Memory Express (NVMe)", "Legacy SATA Revision 3.0"], "answer": 2, "explanation": "Non-Volatile Memory Express (NVMe) communicates directly across high-speed PCI Express bus lanes (e.g., PCIe 4.0 x4 providing up to 8 GB/s bandwidth) with 64,000 deep command queues, bypassing the legacy AHCI bottleneck. SATA and mSATA are capped at 6 Gbps (600 MB/s) over SATA controllers, and PATA is legacy 133 MB/s.", "distractor_analysis": {"1": "SATA III is limited by SATA controller architecture to a maximum theoretical throughput of 6 Gbps (~600 MB/s).", "2": "mSATA uses the SATA protocol across a mini-PCIe physical form factor, sharing the same 6 Gbps SATA speed ceiling.", "3": "Parallel ATA is an obsolete legacy ribbon interface limited to 133 MB/s maximum burst bandwidth."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "nvme", "pcie", "ssd"]}, {"id": "C1-167", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A desktop computer functions normally while powered on, but every time the AC power cord is disconnected or the power strip is switched off, the system clock resets to January 1st and BIOS settings revert to default. What is the permanent fix?", "options": ["Flash the motherboard BIOS with beta overclocking firmware", "Replace the CR2032 lithium coin-cell battery on the motherboard", "Replace the main power supply unit (PSU)", "Reinstall the 64-bit Windows operating system"], "answer": 3, "explanation": "The CR2032 3V lithium coin-cell battery on the motherboard provides continuous trickle power to the volatile CMOS RAM and Real-Time Clock (RTC) chip when the computer is unplugged from AC mains. When this battery dies, disconnecting mains power drains volatile memory, causing the clock to reset and BIOS settings to revert to factory defaults. Replacing the battery permanently resolves the issue.", "distractor_analysis": {"1": "The PSU powers the computer while plugged in; it does not maintain RTC clock state when unplugged from the wall.", "2": "Operating system reinstallation does not affect pre-boot motherboard RTC hardware registers.", "3": "Flashing firmware updates code logic but does not restore electrical power to depleted CMOS battery cells."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "cmos", "battery", "cr2032", "rtc"]}, {"id": "C1-168", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "What is the primary security function of the UEFI Secure Boot feature during system initialization?", "options": ["It enforces complex user passwords before unlocking BIOS menus", "It scans installed system RAM memory chips for physical bit flip errors", "It automatically encrypts the entire solid-state drive with AES-256", "It validates the cryptographic digital signatures of bootloader binaries, Option ROMs, and OS kernel drivers against trusted OEM certificates"], "answer": 1, "explanation": "UEFI Secure Boot uses a Public Key Infrastructure (PKI) hierarchy embedded in firmware (the Signature Database / db and KEK) to verify that the bootloader (e.g., Windows Boot Manager, bootx64.efi), Option ROMs, and kernel drivers are digitally signed by a trusted certificate authority before allowing them to execute. This blocks rootkits and unauthorized boot media. Password enforcement, RAM parity checks, and disk encryption are separate features.", "distractor_analysis": {"1": "BIOS User and Administrator passwords enforce pre-boot authentication, which is distinct from digital signature verification.", "2": "RAM error checking is performed by ECC memory hardware and POST memory tests, not Secure Boot.", "3": "Full-disk encryption (BitLocker) encrypts storage sectors using TPM keys, independent of Secure Boot signature verification."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "uefi", "secure-boot", "security", "certificates"]}, {"id": "C1-169", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which specific hardware cryptographic security processor specification is a mandatory platform prerequisite for installing or upgrading to the Microsoft Windows 11 operating system?", "options": ["Hardware Security Module (HSM) PCIe expansion blade", "Smart card CAC reader terminal", "Trusted Platform Module version 2.0 (TPM 2.0)", "Legacy TPM version 1.2"], "answer": 2, "explanation": "Microsoft Windows 11 mandates hardware-based security requirements, including UEFI firmware with Secure Boot capability and a Trusted Platform Module (TPM) version 2.0 (either discrete dTPM or firmware fTPM / Intel PTT / AMD fTPM) for secure identity, credential protection, and virtualization-based security (VBS). TPM 1.2 does not meet Windows 11 requirements.", "distractor_analysis": {"1": "TPM 1.2 is an older standard that lacks modern cryptographic algorithms (SHA-256) and does not satisfy the official Windows 11 hardware baseline.", "2": "A Hardware Security Module (HSM) is an enterprise cryptographic accelerator for datacenter servers, not a consumer Windows 11 requirement.", "3": "Smart card readers are authentication peripherals used for two-factor login, not a mandatory OS prerequisite."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "tpm", "windows11", "security", "specifications"]}, {"id": "C1-170", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A user brings in a laptop whose display appears completely black, but when a bright flashlight is shined at a close angle against the screen, the Windows desktop icons and open windows are faintly visible. What is the root cause of this failure?", "options": ["A loose external HDMI audio cable", "A failed CCFL/LED backlight assembly or inverter board", "A completely dead discrete graphics processing unit (GPU)", "A cracked capacitive digitizer glass layer"], "answer": 3, "explanation": "If the LCD panel is rendering images properly (visible with a flashlight) but no illumination is produced, the liquid crystals are active while the illumination system has failed (either a faulty LED backlight strip, defective backlight driver circuitry on the motherboard, or a failed CCFL inverter on older laptops). If the GPU were dead, no image would be generated at all. A broken digitizer affects touch input, and HDMI audio cables have no relation to internal laptop screens.", "distractor_analysis": {"1": "If the GPU were dead or unseated, the frame buffer would not generate any image on the LCD panel, even under a flashlight.", "2": "A cracked digitizer impacts touch and pen recognition, but does not extinguish the screen's backlight.", "3": "External HDMI audio cables carry sound to external TVs/monitors and have no connection to internal laptop LCD backlighting."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "backlight", "inverter", "flashlight-test"]}, {"id": "C1-171", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A tablet displays a clear, vibrant image with no visual defects, but tapping, swiping, or touching the glass produces zero response across the entire screen. Which component has failed and must be replaced?", "options": ["The LED backlight array", "The high-voltage backlight inverter", "The graphics processing unit (GPU)", "The capacitive touchscreen digitizer panel"], "answer": 1, "explanation": "A touchscreen display assembly consists of two distinct layers: the display panel (LCD/OLED) that produces visual images and the digitizer (a transparent capacitive glass grid) that detects touch coordinates and converts touch into digital input. When the image is perfect but touch does not register, the digitizer (or its flex cable) has failed. Backlight/inverter failures cause dark screens, and GPU failures cause graphical artifacts or black screens.", "distractor_analysis": {"1": "The LED backlight provides screen brightness; if it failed, the screen would be dark, but touch input would still function.", "2": "The backlight inverter powers CCFL backlights on older screens and does not process touch input signals.", "3": "The GPU renders visual frames; if it failed, the display would show graphical corruption, artifacts, or no video output."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "digitizer", "touchscreen"]}, {"id": "C1-172", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "During a presentation, a conference room projector suddenly goes completely dark, the warning LED flashes amber, and its internal cooling fan spins at maximum speed for several minutes. What is the most likely cause?", "options": ["The HDMI cable lost ground pin continuity", "The operating system video device driver crashed silently", "The projector lamp/bulb has overheated or burned out due to thermal thermal buildup or clogged air filters", "The video source resolution was automatically changed from 1080p to 4K"], "answer": 2, "explanation": "Projector high-intensity discharge (HID) lamps generate immense heat. If thermal sensors detect excessive temperature (e.g., due to clogged intake filters or a failed cooling fan) or if the bulb reaches its end-of-life and burns out, the projector shuts off the lamp immediately while running fans at maximum speed to cool internal optical prisms and prevent glass meltdown. Resolution changes or driver crashes do not trigger maximum emergency fan cooling cycles.", "distractor_analysis": {"1": "Resolution mismatches cause 'Out of Range' on-screen messages, not emergency high-speed thermal fan cool-down cycles.", "2": "A disconnected HDMI cable produces a 'No Signal' blue/black screen while fans run at normal whisper-quiet speeds.", "3": "An OS driver crash stops video output from the PC, but does not trigger the projector's internal thermal warning LEDs."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "projectors", "bulb", "overheating"]}, {"id": "C1-173", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which USB specification standard was the first to introduce a maximum data transfer rate of 10 Gbps (SuperSpeed+)?", "options": ["USB 1.1 (Full Speed)", "USB 3.1 Gen 2 (USB 3.2 Gen 2 / SuperSpeed+)", "USB 2.0 (HighSpeed)", "USB 3.0 / USB 3.1 Gen 1 (SuperSpeed)"], "answer": 3, "explanation": "USB 3.1 Gen 2 (later rebranded as USB 3.2 Gen 2) introduced the 10 Gbps SuperSpeed+ signaling rate using 128b/132b encoding. USB 2.0 maxes at 480 Mbps, USB 3.0 / 3.1 Gen 1 maxes at 5 Gbps, and USB 1.1 operates at 12 Mbps.", "distractor_analysis": {"1": "USB 2.0 HighSpeed is capped at a maximum signaling rate of 480 Mbps.", "2": "USB 3.0 / USB 3.1 Gen 1 SuperSpeed operates at a maximum rate of 5 Gbps.", "3": "USB 1.1 Full Speed operates at a maximum rate of 12 Mbps."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "usb", "bandwidth", "specifications"]}, {"id": "C1-174", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which physical connector standard is utilized by Thunderbolt 3 and Thunderbolt 4 interfaces to achieve 40 Gbps bandwidth?", "options": ["Mini DisplayPort connector", "Standard USB Type-A connector", "Apple 30-pin dock connector", "USB Type-C connector"], "answer": 1, "explanation": "Starting with Thunderbolt 3 (and continuing with Thunderbolt 4 and 5), Intel adopted the 24-pin reversible USB Type-C connector as the universal physical interface, supporting up to 40 Gbps bandwidth, PCIe tunneling, DisplayPort Alternate Mode, and USB Power Delivery. Thunderbolt 1 and 2 used Mini DisplayPort, USB-A cannot support 40 Gbps, and 30-pin is legacy Apple.", "distractor_analysis": {"1": "Mini DisplayPort was the physical connector used exclusively on legacy Thunderbolt 1 and Thunderbolt 2 ports.", "2": "USB Type-A is the non-reversible rectangular connector limited to legacy USB speeds and cannot support Thunderbolt 40 Gbps protocols.", "3": "The 30-pin dock connector is an obsolete proprietary connector used on early iPod and iPhone models."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "thunderbolt", "usb-c", "connectors"]}, {"id": "C1-175", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "easy", "question": "Which display technology utilizes self-emissive organic pixels that generate their own individual light, requiring NO separate backlight panel and achieving true infinite contrast ratios?", "options": ["In-Plane Switching (IPS) LCD", "Vertical Alignment (VA) LCD", "Organic Light-Emitting Diode (OLED / AMOLED)", "Twisted Nematic (TN) LCD"], "answer": 2, "explanation": "OLED (Organic Light-Emitting Diode) displays use self-emissive organic electroluminescent compounds where every individual pixel emits its own light and color when energized. When displaying pure black, pixels are turned completely off, achieving true 0-nit black and infinite contrast without needing a separate backlight. TN, IPS, and VA are all non-emissive LCD panel technologies that require an LED backlight.", "distractor_analysis": {"1": "TN (Twisted Nematic) is an LCD panel type that requires an external LED backlight to illuminate pixels.", "2": "IPS (In-Plane Switching) is an LCD panel type known for wide viewing angles and color accuracy, but strictly requires an LED backlight.", "3": "VA (Vertical Alignment) is an LCD panel type offering good static contrast, but still requires an LED backlight."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "display", "oled", "lcd", "contrast"]}, {"id": "C1-176", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which of the following legacy video cabling standards transmits purely analog red, green, blue, and sync video signals and is completely incapable of carrying digital audio streams?", "options": ["USB-C with DisplayPort Alternate Mode", "Video Graphics Array (15-pin DE-15 / VGA)", "High-Definition Multimedia Interface (HDMI)", "DisplayPort (DP)"], "answer": 3, "explanation": "VGA (Video Graphics Array) uses a 15-pin DE-15 connector to transmit analog RGB video signals (pins 1, 2, 3 for Red, Green, Blue and pins 13, 14 for Horizontal and Vertical Sync) and carries zero audio pins or audio encoding capabilities. HDMI, DisplayPort, and USB-C DisplayPort Alt Mode all natively carry multi-channel digital audio alongside high-resolution digital video.", "distractor_analysis": {"1": "HDMI transmits up to 8 channels of uncompressed digital audio or 32 channels of spatial audio alongside video.", "2": "DisplayPort natively transmits high-definition multi-channel digital audio streams through auxiliary audio packets.", "3": "USB-C in DisplayPort Alternate Mode encapsulates full DisplayPort audio and video packets across high-speed lanes."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "vga", "audio", "video"]}, {"id": "C1-177", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "What standard display protocol feature allows a workstation to connect a single video output port to a primary monitor and 'daisy-chain' a cable from that monitor to a secondary monitor to drive independent displays?", "options": ["Standard HDMI 1.4 Consumer Electronics Control", "Dual-Link DVI-D Analog Pass-Through", "VGA Splitter Y-Cable Mirroring", "DisplayPort Multi-Stream Transport (MST)"], "answer": 1, "explanation": "DisplayPort 1.2 and later introduced Multi-Stream Transport (MST), which enables a single DisplayPort (or USB-C) output to carry multiple independent video streams. This allows monitors equipped with DisplayPort Out ports to be connected in a daisy-chain configuration, presenting extended independent desktop displays to the OS. Standard HDMI does not support daisy-chaining, DVI lacks MST, and VGA Y-splitters only mirror identical signals.", "distractor_analysis": {"1": "HDMI CEC transmits device control commands (e.g., turning on a TV via a game console) and cannot daisy-chain independent video streams.", "2": "Dual-Link DVI provides extra bandwidth for a single high-resolution monitor, lacking packetized multi-stream routing.", "3": "A VGA Y-splitter physically duplicates identical analog voltages to two displays, resulting in mirrored screens with degraded brightness."}, "video_reference": {"title": "Display Types - CompTIA A+ 220-1201 - 3.1", "url": "https://www.youtube.com/watch?v=xOyialyd4JU", "duration": "9:13", "objective": "3.1"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "display", "displayport", "mst", "daisy-chain"]}, {"id": "C1-178", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "easy", "question": "In the 80 PLUS power supply energy efficiency certification hierarchy, an 80 PLUS Gold certified PSU is tested to deliver higher electrical efficiency under load than which tier?", "options": ["80 PLUS Titanium", "80 PLUS Diamond", "80 PLUS Silver / Bronze / Standard", "80 PLUS Platinum"], "answer": 2, "explanation": "The official 80 PLUS efficiency certification tiers in ascending order of efficiency are: 80 PLUS Standard (White) -> Bronze (82-85%) -> Silver (85-88%) -> Gold (87-90%) -> Platinum (90-92%) -> Titanium (90-94%). Therefore, 80 PLUS Gold is more efficient than Silver, Bronze, and Standard, but less efficient than Platinum and Titanium. 'Diamond' is a non-existent tier.", "distractor_analysis": {"1": "80 PLUS Platinum is higher in the certification hierarchy than Gold, achieving up to 92-94% efficiency.", "2": "80 PLUS Titanium is the highest tier in the 80 PLUS program, achieving up to 94-96% efficiency.", "3": "80 PLUS Diamond is a fictitious certification tier that does not exist in the 80 PLUS program."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "80-plus", "efficiency", "gold", "silver"]}, {"id": "C1-179", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A user retrieves printouts from a departmental laser printer and reports that black toner smudges easily and rubs off onto their fingers like dry powder. Which component in the printer has failed and must be replaced?", "options": ["Toner supply hopper cartridge", "Fuser assembly (heating lamp / pressure roller)", "Photosensitive imaging drum unit", "Primary corona / charge roller wire"], "answer": 3, "explanation": "In a laser printer, the fuser assembly consists of a heated roller (halogen lamp or ceramic element reaching ~200 C) and a pressure roller that physically melt and press toner powder into the fibers of the paper. If the fuser heater fails or fails to reach fusing temperature, toner rests loosely on the page and immediately rubs off as dry powder. Drum defects cause streaks/ghosts, and charge rollers regulate drum surface charge.", "distractor_analysis": {"1": "The imaging drum holds the electrostatic latent image; drum failures cause repeating marks, streaks, or ghosting, not unfused toner.", "2": "The primary charge roller applies a uniform negative charge (-600V) to the drum; failure causes totally black pages.", "3": "The toner cartridge supplies toner particles; if it is functioning to put powder on the page, the failure is downstream at the fuser."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "laser", "fuser", "toner-smudge"]}, {"id": "C1-180", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "medium", "question": "In the standard 7-step electrophotographic (EP) laser printing process, which step occurs immediately AFTER the Exposing (writing) step?", "options": ["Charging (primary charge roller applies uniform high-voltage negative charge)", "Transferring (transfer corona applies positive charge to paper to pull toner off drum)", "Fusing (heated rollers melt toner into the paper fibers)", "Developing (toner roller applies charged toner to the discharged areas of the drum)"], "answer": 1, "explanation": "The 7 steps of the electrophotographic laser printing process proceed in exact order: (1) Processing, (2) Charging, (3) Exposing, (4) Developing, (5) Transferring, (6) Fusing, and (7) Cleaning. During Developing, the developing roller attracts negatively charged toner particles to the neutralized areas of the drum written by the laser during the Exposing step.", "distractor_analysis": {"1": "Charging is Step 2, which occurs before the laser exposes the drum in Step 3.", "2": "Transferring is Step 5, which occurs after Developing in Step 4.", "3": "Fusing is Step 6, which bonds toner to paper after transferring."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "laser", "ep-process", "developing"]}, {"id": "C1-181", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "easy", "question": "Which printer technology is uniquely required in accounting and logistics environments to print on multi-part carbon or carbonless continuous-feed forms?", "options": ["Thermal Drop-on-Demand Inkjet printer", "Direct Thermal receipt printer", "Impact / Dot-Matrix printer", "Electrophotographic Laser printer"], "answer": 2, "explanation": "Impact dot-matrix printers use physical metal printhead pins that strike an inked ribbon with mechanical force, creating the physical pressure necessary to transfer duplicate impressions through multiple layers of carbon or carbonless multi-part paper (e.g., invoices, bills of lading). Laser, inkjet, and thermal printers apply non-impact heat, ink sprays, or toner to surface sheets without mechanical strike pressure.", "distractor_analysis": {"1": "Laser printers are non-impact devices that use heat and electrostatic charges; they cannot press impressions through multipart carbon sheets.", "2": "Inkjet printers spray microscopic liquid droplets onto top sheets without physical impact force.", "3": "Direct thermal printers use heat elements on specialty paper, unable to generate physical pressure across multi-part forms."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "impact", "dot-matrix", "multipart-forms"]}, {"id": "C1-182", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which standard TCP port number is utilized by the Secure Shell (SSH) protocol for encrypted remote command-line management and secure file transfer (SFTP)?", "options": ["TCP port 25 (SMTP mail transfer)", "TCP port 22 (SSH)", "TCP port 21 (FTP Control)", "TCP port 23 (Telnet unencrypted)"], "answer": 3, "explanation": "TCP port 22 is the standard port for Secure Shell (SSH), which provides cryptographic confidentiality, integrity, and authentication for remote terminal sessions and SFTP transfers, replacing insecure plaintext Telnet (port 23) and FTP (port 21). TCP port 25 is used for SMTP.", "distractor_analysis": {"1": "TCP port 21 is used for File Transfer Protocol (FTP) control sessions.", "2": "TCP port 23 is used for unencrypted Telnet terminal sessions.", "3": "TCP port 25 is used for Simple Mail Transfer Protocol (SMTP) server-to-server mail delivery."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "ssh", "security", "protocols"]}, {"id": "C1-183", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which default TCP port number is used by Microsoft Remote Desktop Protocol (RDP) to establish remote graphical desktop sessions into Windows systems?", "options": ["TCP port 5900 (VNC)", "TCP port 443 (HTTPS)", "TCP port 389 (LDAP)", "TCP port 3389 (RDP)"], "answer": 1, "explanation": "Microsoft Remote Desktop Protocol (RDP) listens on TCP port 3389 (and optionally UDP port 3389) by default to deliver encrypted graphical desktop and application sessions. Port 5900 is used by Virtual Network Computing (VNC), Port 443 is HTTPS, and Port 389 is unencrypted LDAP.", "distractor_analysis": {"1": "TCP port 5900 is the standard port used by Virtual Network Computing (VNC) remote desktop servers.", "2": "TCP port 443 is used for secure encrypted web traffic via HTTPS.", "3": "TCP port 389 is used for unencrypted Lightweight Directory Access Protocol (LDAP) directory queries."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "rdp", "remote-access"]}, {"id": "C1-184", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which network management protocol utilizes UDP ports 161 (for queries/polling) and UDP port 162 (for asynchronous trap notifications) to monitor the health and performance of network switches, routers, and servers?", "options": ["Network Time Protocol (NTP)", "Lightweight Directory Access Protocol (LDAP)", "Simple Network Management Protocol (SNMP)", "Syslog event logging protocol"], "answer": 2, "explanation": "Simple Network Management Protocol (SNMP) uses UDP port 161 for SNMP managers to query (GET/SET) agent Management Information Bases (MIBs) on network devices, and UDP port 162 to receive unsolicited SNMP Traps and InformRequests. Syslog uses UDP 514, NTP uses UDP 123, and LDAP uses TCP/UDP 389.", "distractor_analysis": {"1": "Syslog operates over UDP port 514 to receive system log event messages from network equipment.", "2": "Network Time Protocol (NTP) synchronizes clock time across network hosts using UDP port 123.", "3": "LDAP queries network directory services over TCP and UDP port 389."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "snmp", "monitoring", "management"]}, {"id": "C1-185", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which standard TCP port number is utilized by Internet Message Access Protocol over SSL/TLS (IMAPS) for secure encrypted email mailbox synchronization?", "options": ["TCP port 995 (POP3S)", "TCP port 993 (IMAPS)", "TCP port 143 (Plaintext IMAP)", "TCP port 110 (Plaintext POP3)"], "answer": 3, "explanation": "TCP port 993 is the standard IANA-assigned port for IMAP over SSL/TLS (IMAPS), providing transport-layer encryption for email access and folder synchronization. TCP port 143 is unencrypted IMAP, TCP port 110 is unencrypted POP3, and TCP port 995 is POP3 over TLS (POP3S).", "distractor_analysis": {"1": "TCP port 143 is the standard port for unencrypted, plaintext IMAP.", "2": "TCP port 110 is the standard port for unencrypted, plaintext POP3 mailbox retrieval.", "3": "TCP port 995 is the standard secure port for POP3 over TLS (POP3S)."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "imaps", "email", "security"]}, {"id": "C1-186", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which pair of UDP ports is utilized by the Dynamic Host Configuration Protocol (DHCP) for server listening and client communication?", "options": ["UDP port 53 (DNS)", "TCP port 80 (HTTP) and TCP port 443 (HTTPS)", "TCP port 20 and 21 (FTP)", "UDP port 67 (DHCP Server) and UDP port 68 (DHCP Client)"], "answer": 1, "explanation": "Dynamic Host Configuration Protocol (DHCP) operates over UDP: DHCP servers listen on UDP port 67 for incoming Discover/Request messages from clients, and DHCP clients listen on UDP port 68 to receive Offer/ACK configuration packets from servers. Port 53 is DNS, ports 80/443 are web, and ports 20/21 are FTP.", "distractor_analysis": {"1": "UDP/TCP port 53 is used by Domain Name System (DNS) servers to resolve hostnames to IP addresses.", "2": "TCP ports 80 and 443 are web delivery ports for HTTP and HTTPS traffic.", "3": "TCP ports 20 and 21 are used for File Transfer Protocol (FTP) data and control connections."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "dhcp", "protocols"]}, {"id": "C1-187", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which Layer 4 transport protocol operates in a connectionless, best-effort manner without establishing sessions or requiring packet acknowledgments, prioritizing low overhead and speed for streaming audio/video and DNS queries?", "options": ["Hypertext Transfer Protocol (HTTP)", "Secure Shell (SSH)", "User Datagram Protocol (UDP)", "Transmission Control Protocol (TCP)"], "answer": 2, "explanation": "User Datagram Protocol (UDP) is a connectionless, lightweight transport-layer protocol that does not establish three-way handshakes, track sequence numbers, or require acknowledgments (ACKs), making it ideal for latency-sensitive streaming media, VoIP, DHCP, and DNS lookups. TCP is connection-oriented with guaranteed delivery, while HTTP and SSH are application-layer protocols running over TCP.", "distractor_analysis": {"1": "Transmission Control Protocol (TCP) is connection-oriented, utilizing sequence numbers, three-way handshakes, and acknowledgments to guarantee delivery.", "2": "HTTP is an application-layer protocol that rides on top of connection-oriented TCP.", "3": "SSH is an encrypted application-layer management protocol running on top of connection-oriented TCP."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "protocols", "udp", "tcp", "transport-layer"]}, {"id": "C1-188", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "In Transmission Control Protocol (TCP) connection establishment, what is the exact 3-step sequence of control flag packets exchanged during the three-way handshake?", "options": ["SYN, then ACK, then FIN", "SYN, then SYN/ACK, then ACK", "ACK, then SYN, then SYN/ACK", "SYN/ACK, then SYN, then ACK"], "answer": 3, "explanation": "The TCP three-way handshake establishes a reliable full-duplex connection in three steps: (1) The client sends a SYN packet with an initial sequence number (ISN), (2) The server responds with a SYN/ACK packet acknowledging the client's sequence number and providing its own ISN, and (3) The client sends an ACK packet confirming the server's sequence number, opening the active connection.", "distractor_analysis": {"1": "A bare ACK first has nothing to acknowledge. The client always opens with SYN.", "2": "SYN/ACK is the server response. It cannot arrive before the client SYN it answers.", "3": "FIN closes a connection. It has no part in opening one."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "tcp", "handshake", "protocols"]}, {"id": "C1-189", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "A technician inspects a Windows workstation network configuration and discovers an IPv4 address of 169.254.10.5 with a subnet mask of 255.255.0.0. The workstation cannot access the local intranet servers or the Internet. What does this IP address indicate?", "options": ["The client successfully obtained a static public IP reservation from the ISP router", "The client is communicating over the local loopback diagnostic interface", "The network interface card has been permanently disabled in device manager", "The client is configured for dynamic DHCP but could not reach a DHCP server, defaulting to Automatic Private IP Addressing (APIPA)"], "answer": 1, "explanation": "IPv4 addresses in the 169.254.0.0/16 range (from 169.254.0.1 to 169.254.255.254) are reserved for Automatic Private IP Addressing (APIPA / link-local). When a client configured for DHCP fails to receive a response from a DHCP server after sending Discover broadcasts, Windows automatically assigns an APIPA address, allowing local subnet communication but no gateway routing or Internet access.", "distractor_analysis": {"1": "169.254.0.0/16 is a private, non-routable link-local address block, not a public ISP routable address.", "2": "The IPv4 loopback diagnostic address range is 127.0.0.0/8 (commonly 127.0.0.1).", "3": "If the NIC were disabled in Device Manager, the interface would have no active IP address assigned at all."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "apipa", "dhcp", "troubleshooting", "ip-addressing"]}, {"id": "C1-190", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "According to RFC 1918 private IPv4 address allocation standards, which of the following IP addresses belongs to the private Class B address block (172.16.0.0 to 172.31.255.255 /12)?", "options": ["192.168.1.1", "172.32.0.1", "172.20.5.5", "10.1.1.1"], "answer": 2, "explanation": "RFC 1918 defines three private IPv4 address ranges: Class A (10.0.0.0/8: 10.0.0.0 - 10.255.255.255), Class B (172.16.0.0/12: 172.16.0.0 - 172.31.255.255), and Class C (192.168.0.0/16: 192.168.0.0 - 192.168.255.255). 172.20.5.5 falls squarely within the private Class B 172.16-172.31 range. 10.1.1.1 is Class A private, 192.168.1.1 is Class C private, and 172.32.0.1 is a public routable IP.", "distractor_analysis": {"1": "10.1.1.1 is in the 10.0.0.0/8 private address space, which is Class A, not Class B.", "2": "192.168.1.1 is in the 192.168.0.0/16 private address space, which is Class C, not Class B.", "3": "172.32.0.1 is outside the 172.16.0.0 - 172.31.255.255 private range, making it a public Internet address."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ipv4", "rfc1918", "private-ip", "class-b"]}, {"id": "C1-191", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "What is the standard default subnet mask for a traditional classful Class C IPv4 network (prefix /24)?", "options": ["255.255.255.255 (/32 host mask)", "255.255.255.0 (/24 prefix)", "255.0.0.0 (/8 prefix)", "255.255.0.0 (/16 prefix)"], "answer": 3, "explanation": "In classful IPv4 addressing, the default subnet mask for Class C networks (address ranges 192.0.0.0 to 223.255.255.255) is 255.255.255.0 (/24), allocating 24 bits for the network ID and 8 bits for host addresses (up to 254 usable hosts). 255.0.0.0 is default Class A (/8), and 255.255.0.0 is default Class B (/16).", "distractor_analysis": {"1": "255.0.0.0 is the default /8 subnet mask for Class A IPv4 networks.", "2": "255.255.0.0 is the default /16 subnet mask for Class B IPv4 networks.", "3": "255.255.255.255 (/32) is a single-host route mask, not a network subnet mask."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "subnet-mask", "ipv4", "class-c"]}, {"id": "C1-192", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "How many total bits are contained in an Internet Protocol version 6 (IPv6) address?", "options": ["32 bits (4 bytes)", "48 bits (6 bytes)", "64 bits (8 bytes)", "128 bits (16 bytes)"], "answer": 1, "explanation": "IPv6 addresses are exactly 128 bits (16 bytes) in length, expressed as 8 colon-separated hexadecimal 16-bit blocks (hextets), providing approximately 3.4 x 10^38 unique global addresses. 32 bits is an IPv4 address, 48 bits is an Ethernet MAC address, and 64 bits is an IPv6 interface ID.", "distractor_analysis": {"1": "32 bits is the length of an Internet Protocol version 4 (IPv4) address.", "2": "48 bits is the length of an IEEE 802 Media Access Control (MAC) hardware address.", "3": "64 bits is the size of standard IPv6 interface identifiers (the host half of a /64 subnet)."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ipv6", "addressing", "specifications"]}, {"id": "C1-193", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "What is the primary operational function of Network Address Translation (NAT) and Port Address Translation (PAT) on a border gateway router?", "options": ["It encrypts all internal LAN network traffic using AES-256 GCM", "It balances incoming power voltage across redundant server power supplies", "It translates private RFC 1918 internal IP addresses to one or more routable public IP addresses for Internet access", "It automatically resolves domain hostnames into numerical IP addresses"], "answer": 2, "explanation": "Network Address Translation (NAT / PAT / Source NAT) modifies the IP header source addresses of outgoing packets, mapping multiple private, non-routable internal IP addresses (RFC 1918) to a single public routable IP address using unique Layer 4 source port numbers. DNS resolves hostnames, IPsec encrypts network traffic, and power PDUs balance voltage.", "distractor_analysis": {"1": "Translating domain names to IP addresses is the role of Domain Name System (DNS) servers, not NAT.", "2": "Encrypting network traffic is handled by cryptographic protocols like IPsec, TLS, or SSH, not standard NAT.", "3": "Balancing electrical voltage is the role of power distribution units (PDUs) and electrical transformers."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "nat", "pat", "gateway", "addressing"]}, {"id": "C1-194", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "easy", "question": "Which DNS resource record type maps a domain hostname directly to a 128-bit IPv6 address?", "options": ["PTR (Pointer) record", "AAAA (Quad-A) record", "A (Address) record", "MX (Mail Exchanger) record"], "answer": 3, "explanation": "An AAAA record (Quad-A record, named because 128 bits is four times the 32-bit size of an IPv4 address) maps a DNS hostname to an IPv6 address. An 'A' record maps a hostname to a 32-bit IPv4 address, an 'MX' record designates mail servers, and a 'PTR' record performs reverse DNS lookups (IP to hostname).", "distractor_analysis": {"1": "An 'A' record maps a hostname to a 32-bit IPv4 address, not an IPv6 address.", "2": "An 'MX' record specifies the mail exchange servers responsible for receiving email for a domain.", "3": "A 'PTR' record maps an IP address back to a hostname in reverse lookup zones."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "records", "aaaa", "ipv6"]}, {"id": "C1-195", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "easy", "question": "Which DNS resource record type specifies the priority and hostname of mail servers responsible for accepting incoming email for a domain?", "options": ["Canonical Name (CNAME) alias record", "Service Location (SRV) record", "Text (TXT) verification record", "Mail Exchanger (MX) record"], "answer": 1, "explanation": "A Mail Exchanger (MX) record specifies the mail servers responsible for accepting email messages on behalf of a recipient's domain name, accompanied by a preference number (priority ranking). CNAME creates domain aliases, SRV defines specific host/port services (like Kerberos/SIP), and TXT stores text records.", "distractor_analysis": {"1": "A CNAME (Canonical Name) record aliases one domain name to another canonical hostname, not specifically for routing email.", "2": "An SRV record defines hostname and port locations for specific services like LDAP or Active Directory domain controllers.", "3": "A TXT record holds arbitrary human- or machine-readable text data used for domain verification and email authentication."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "mx", "email", "records"]}, {"id": "C1-196", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "Which DNS resource record type is utilized by email security frameworks to publish SPF (Sender Policy Framework), DKIM public keys, and DMARC policies to prevent email spoofing?", "options": ["NS (Name Server) record", "PTR (Pointer) record", "TXT (Text) record", "A (Address) record"], "answer": 2, "explanation": "DNS TXT (Text) records allow domain owners to store arbitrary text strings in DNS, which are utilized by email authentication standards: SPF (v=spf1 ... to define authorized sending IPs), DKIM (publishing public cryptographic keys for signature verification), and DMARC (v=DMARC1 ... defining enforcement policy). A records store IPv4 addresses, NS records identify authoritative DNS servers, and PTR records perform reverse lookups.", "distractor_analysis": {"1": "An 'A' record maps a hostname to an IPv4 address and cannot store SPF or DKIM policy text strings.", "2": "An 'NS' record delegates a DNS zone to authoritative name servers.", "3": "A 'PTR' record maps an IP address to a canonical hostname in reverse lookup zones."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "txt", "spf", "dkim", "dmarc", "email"]}, {"id": "C1-197", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "easy", "question": "In the standard 4-step DHCP lease negotiation process known by the acronym DORA, what does the letter 'R' represent?", "options": ["Release, the DHCPRELEASE that returns the address", "Request, the DHCPREQUEST that accepts the offered address", "Reply, a DHCPREPLY returned by the relay agent", "Renew, a DHCPRENEW sent at half the lease time"], "answer": 3, "explanation": "The standard DHCP leasing process is known by the acronym DORA: (1) Discover (client broadcasts DHCPDISCOVER), (2) Offer (server sends DHCPOFFER with available IP), (3) Request (client broadcasts DHCPREQUEST formally requesting that IP lease), and (4) Acknowledge (server sends DHCPACK finalizing the lease). Reply, Renew, and Release are other DHCP message types or operations, but 'Request' is the third step of DORA.", "distractor_analysis": {"1": "There is no DHCPREPLY message type in DHCPv4. The relay forwards, it does not answer.", "2": "Renewal happens at T1, halfway through the lease, but it reuses DHCPREQUEST and is not part of DORA.", "3": "DHCPRELEASE hands the lease back early. It is not one of the four negotiation steps."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dhcp", "dora", "request", "protocols"]}, {"id": "C1-198", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Under TIA/EIA commercial building telecommunications cabling standards, what is the maximum certified physical segment length for standard twisted-pair copper Ethernet horizontal cable runs (including patch cords)?", "options": ["55 meters (180 feet)", "185 meters (607 feet)", "500 meters (1,640 feet)", "100 meters (328 feet)"], "answer": 1, "explanation": "Under TIA/EIA-568 standards, the maximum allowable total channel length for standard Category 5e, 6, and 6a twisted-pair copper Ethernet is exactly 100 meters (328 feet), typically structured as a 90-meter permanent solid horizontal cable run plus up to 10 meters of combined stranded patch cords. 55 meters is the limit for 10G on Cat6, 185m was legacy 10BASE2 Thinnet, and 500m was legacy 10BASE5 Thicknet.", "distractor_analysis": {"1": "55 meters is the maximum distance Cat 6 copper cable can support 10GBASE-T before signal attenuation requires Cat 6a.", "2": "185 meters was the maximum segment length of legacy 10BASE2 coaxial Thinnet Ethernet.", "3": "500 meters was the maximum segment length of legacy 10BASE5 coaxial Thicknet Ethernet."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "ethernet", "distance-limits", "cat6", "standards"]}, {"id": "C1-199", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "What is the maximum certified transmission distance for standard Category 6 (Cat 6) unshielded twisted-pair copper cabling when operating at 10 Gigabit Ethernet (10GBASE-T) speeds before alien crosstalk limits performance?", "options": ["30 meters (98 feet)", "15 meters (50 feet)", "55 meters (180 feet)", "100 meters (328 feet)"], "answer": 2, "explanation": "Category 6 (Cat 6) cabling is rated for 250 MHz and can support 10GBASE-T up to a maximum distance of 55 meters (180 feet) under favorable alien crosstalk conditions (reduced to ~37 meters in high-density bundles). To achieve full 100-meter segment lengths at 10 Gbps, Category 6a (Augmented Cat 6 rated at 500 MHz) or Cat 7/8 must be installed.", "distractor_analysis": {"1": "100 meters is the maximum 10GBASE-T distance supported by Category 6a (Cat 6a) cabling, but standard Cat 6 cannot reliably reach 100m at 10 Gbps.", "2": "30 meters is the certified distance for Category 8 (Cat 8) 40GBASE-T datacenter top-of-rack links.", "3": "15 meters is a non-standard short distance not used as a specification boundary for Cat 6."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "cat6", "10gbps", "distance-limits"]}, {"id": "C1-200", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "According to the ANSI/TIA-568-B (T568B) commercial wiring standard for RJ-45 copper Ethernet connectors, what is the color of the wire connected to Pin 1?", "options": ["Solid Orange (Pin 2 in T568B)", "White/Orange (Pin 1 in T568B)", "White/Green (Pin 1 in T568A)", "Solid Blue (Pin 4 in both standards)"], "answer": 3, "explanation": "The TIA/EIA T568B wiring standard defines the 8-pin sequence as: Pin 1: White/Orange, Pin 2: Solid Orange, Pin 3: White/Green, Pin 4: Solid Blue, Pin 5: White/Blue, Pin 6: Solid Green, Pin 7: White/Brown, Pin 8: Solid Brown. In contrast, T568A begins with White/Green on Pin 1 and Solid Green on Pin 2.", "distractor_analysis": {"1": "White/Green is Pin 1 under the T568A wiring standard.", "2": "Solid Blue is Pin 4 in both T568A and T568B wiring standards.", "3": "Solid Orange is Pin 2 under the T568B wiring standard."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "t568b", "pinouts", "color-coding"]}, {"id": "C1-201", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which specialized diagnostic tool pair is used to locate and identify a specific copper network cable hidden inside a drywall partition or congested wire bundle by emitting an audible tone?", "options": ["Modular RJ-45 cable crimper", "Hardware Ethernet loopback plug", "Impact punch-down tool with 110 blade", "Tone generator and inductive probe (toner / fox and hound)"], "answer": 1, "explanation": "A tone generator injects an alternating electrical audio tone onto a copper cable, and the handheld inductive tone probe amplifies that tone into an audible sound when brought near the specific wire in a bundle or wall cavity. Crimpers terminate connectors, loopback plugs test NICs, and punch-down tools terminate cables into patch panels.", "distractor_analysis": {"1": "A cable crimper physically compresses RJ-45 or RJ-11 modular connectors onto cable ends, lacking audio tracing electronics.", "2": "A loopback plug routes transmit pins directly to receive pins on a single NIC to test transceiver health.", "3": "A punch-down tool pushes individual conductors into insulation-displacement terminal blocks on patch panels."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "tools", "tone-generator", "probe", "troubleshooting"]}, {"id": "C1-202", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which installation hand tool is used to seat individual insulated copper conductors into 110-block or Krone terminal slots on a patch panel while simultaneously trimming the excess wire?", "options": ["Continuity wire map tester", "Coaxial cable stripper", "Punch-down tool", "Modular RJ-45 crimper"], "answer": 2, "explanation": "A punch-down tool uses an internal spring-loaded impact mechanism to push insulated copper wires into the V-shaped metal blades of an Insulation Displacement Connector (IDC / 110 block) on patch panels and keystone jacks, while the sharp side of the blade shears off excess conductor flush. Crimpers terminate modular plugs, wire map testers check continuity, and strippers score cable jackets.", "distractor_analysis": {"1": "Crimpers attach RJ-45 plugs onto the ends of patch cords, not for terminating structured wiring into patch panel punch-down blocks.", "2": "Continuity wire map testers verify pin-to-pin electrical continuity across an already-terminated cable.", "3": "Cable strippers score and remove outer PVC/CMP plastic jackets, not for seating wires into terminal slots."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "tools", "punch-down", "patch-panel", "cabling"]}, {"id": "C1-203", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which fiber-optic cable classification utilizes a narrow 8-10 micron glass core and single-wavelength laser diodes to transmit data across long-haul metropolitan and WAN distances with minimal modal dispersion?", "options": ["Shielded Twisted Pair (STP)", "Single-Mode Fiber (SMF)", "Multimode Fiber (MMF)", "Coaxial RG-6 Cable"], "answer": 3, "explanation": "Single-Mode Fiber (SMF) features a tiny 8-10 micron core diameter through which light travels down a single optical path (mode) driven by high-powered laser diodes (1310 nm / 1550 nm), virtually eliminating modal dispersion and allowing signal transmission across tens of kilometers. Multimode fiber uses larger cores (50-62.5 um) for shorter LAN runs, while coax and STP are copper media.", "distractor_analysis": {"1": "Multimode Fiber (MMF) has a larger core (50/62.5 microns) where light rays bounce in multiple modes, limited to shorter distances by modal dispersion.", "2": "Coaxial cable is copper cabling used for cable television and broadband modems, not laser optical transmission.", "3": "Shielded Twisted Pair (STP) is copper Ethernet cabling shielded against EMI, limited to 100-meter segment lengths."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "fiber", "single-mode", "smf"]}, {"id": "C1-204", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which threaded metallic RF connector is standardly crimped onto RG-6 coaxial cables used for cable modems, DOCSIS broadband, and satellite television receivers?", "options": ["RJ-45 modular 8P8C connector", "BNC bayonet connector", "LC optical fiber connector", "F-type threaded connector"], "answer": 1, "explanation": "The F-type connector is a threaded radio-frequency (RF) connector universally used on RG-6 and RG-59 coaxial cables to connect cable modems, television tuners, and satellite set-top boxes. RJ-45 is for twisted-pair Ethernet, BNC is a twist-lock bayonet connector used on legacy 10BASE2 or professional SDI video, and LC is a small-form-factor fiber connector.", "distractor_analysis": {"1": "RJ-45 is an 8-position modular plastic connector used for twisted-pair copper Ethernet cabling.", "2": "BNC (Bayonet Neill-Concelman) uses a quarter-turn twist-lock mechanism for professional video feeds and legacy Thinnet coax.", "3": "LC (Lucent Connector) is a compact push-pull optical fiber connector used in high-density SFP/SFP+ transceivers."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "coaxial", "f-type", "connectors"]}, {"id": "C1-205", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "What is the maximum DC electrical power delivered per switch port by the IEEE 802.3at (Power over Ethernet Plus / PoE+) standard to powered network devices?", "options": ["60.0 Watts (802.3bt Type 3 4PPoE standard)", "90.0 Watts (802.3bt Type 4 High-Power PoE standard)", "30.0 Watts (with ~25.5 Watts minimum available at the PD device)", "15.4 Watts (original 802.3af PoE standard)"], "answer": 2, "explanation": "IEEE 802.3at (PoE+ / Type 2) specifies up to 30.0 Watts of DC power output from the power sourcing equipment (PSE) port, guaranteeing at least 25.5 Watts of usable power at the powered device (PD) after cable resistance loss over a 100m run. 15.4W is original 802.3af PoE, 60W is 802.3bt Type 3, and 90W is 802.3bt Type 4.", "distractor_analysis": {"1": "15.4 Watts is the maximum port power provided by the original IEEE 802.3af (PoE) standard.", "2": "60 Watts is the power delivery specification for IEEE 802.3bt Type 3 (4PPoE / PoE++).", "3": "90 Watts is the maximum power delivered by IEEE 802.3bt Type 4 (PoE++) high-power standard."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "poe", "802.3at", "power", "standards"]}, {"id": "C1-206", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which legacy IEEE 802.11 wireless networking standard was designed to operate exclusively in the 5 GHz frequency band, delivering multi-gigabit speeds using wide 80/160 MHz channels and 256-QAM modulation?", "options": ["IEEE 802.11g", "IEEE 802.11ac (Wi-Fi 5)", "IEEE 802.11n (Wi-Fi 4)", "IEEE 802.11ax (Wi-Fi 6)"], "answer": 3, "explanation": "IEEE 802.11ac (Wi-Fi 5) operates exclusively in the 5 GHz band (relying on backward-compatible 802.11n for 2.4 GHz communication). 802.11n operates in both 2.4 GHz and 5 GHz, 802.11ax (Wi-Fi 6) operates across 2.4 GHz, 5 GHz, and 6 GHz (6E), and 802.11g operates exclusively in the 2.4 GHz spectrum.", "distractor_analysis": {"1": "IEEE 802.11n (Wi-Fi 4) is a dual-band standard that can operate in both the 2.4 GHz and 5 GHz bands.", "2": "IEEE 802.11ax (Wi-Fi 6) operates across all three bands: 2.4 GHz, 5 GHz, and 6 GHz.", "3": "IEEE 802.11g operates exclusively in the 2.4 GHz radio band."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "802.11ac", "5ghz", "wifi5"]}, {"id": "C1-207", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "In North America, which three 20 MHz wireless channels are the only non-overlapping channels available in the standard 2.4 GHz Wi-Fi spectrum?", "options": ["Channels 1, 5, and 9", "Channels 2, 7, and 12", "Channels 36, 40, and 44", "Channels 1, 6, and 11"], "answer": 1, "explanation": "The 2.4 GHz Wi-Fi band is divided into 11 channels spaced 5 MHz apart in North America, but each 802.11 transmission spans a 20-22 MHz channel width. Therefore, only channels 1 (center 2.412 GHz), 6 (center 2.437 GHz), and 11 (center 2.462 GHz) have sufficient 25 MHz separation to operate simultaneously without causing co-channel or adjacent-channel radio interference. Channels 36, 40, 44 are 5 GHz UNII-1 channels.", "distractor_analysis": {"1": "Channels 1, 5, and 9 overlap significantly, causing heavy adjacent channel interference and packet collisions.", "2": "Channels 2, 7, and 12 are overlapping channels in North America (where channel 12 is restricted).", "3": "Channels 36, 40, and 44 are non-overlapping channels in the 5 GHz band, not the 2.4 GHz band."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "2.4ghz", "channels", "interference"]}, {"id": "C1-208", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "At Layer 2 of the OSI model, what addressing information does a standard Ethernet switch inspect to determine which specific switch port to forward an incoming frame to?", "options": ["TCP/UDP application destination port number", "Domain Name System (DNS) Fully Qualified Domain Name", "Destination MAC physical hardware address", "Destination IPv4/IPv6 logical IP address"], "answer": 2, "explanation": "A Layer 2 Ethernet switch reads the 48-bit Destination MAC address in the Ethernet frame header, looks up the MAC address in its Content Addressable Memory (CAM / MAC table), and forwards the frame directly out the associated physical switch port. Routers forward by IP, firewalls/load balancers inspect transport port numbers, and DNS resolves hostnames.", "distractor_analysis": {"1": "Destination IP addresses are evaluated by Layer 3 network routers, not Layer 2 Ethernet switches.", "2": "TCP/UDP port numbers operate at Layer 4 (Transport layer) and are evaluated by firewalls and load balancers.", "3": "DNS hostnames operate at Layer 7 (Application layer) and are resolved by DNS servers."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "switch", "layer-2", "mac-address", "forwarding"]}, {"id": "C1-209", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "Which dedicated network device operates at Layer 3 of the OSI model to route IP packets between different subnets and prevent Layer 2 broadcast frames from crossing network boundaries?", "options": ["Physical Layer Repeater", "Network Router", "Unmanaged Ethernet Switch", "Passive Layer 1 Network Hub"], "answer": 3, "explanation": "A network router connects different IP subnets and stops Layer 2 broadcast frames (such as FF:FF:FF:FF:FF:FF) from propagating across interfaces, creating distinct broadcast domains. Switches segment collision domains but forward broadcasts to all ports in a VLAN, and hubs/repeaters flood all electrical signals.", "distractor_analysis": {"1": "A switch creates separate collision domains per port, but maintains a single shared broadcast domain across all ports within the same VLAN.", "2": "A hub creates a single shared collision domain and a single shared broadcast domain.", "3": "A repeater regenerates electrical signals at Layer 1, having no capability to segment broadcast domains."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "router", "broadcast-domain", "layer-3"]}, {"id": "C1-210", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "What is the primary technical drawback and performance limitation of geostationary (GEO) satellite Internet connections for real-time interactive applications (such as VoIP calls and videoconferencing)?", "options": ["Complete lack of upload capability for transmitting return data", "Mandatory requirement for underground fiber-optic cabling to the dish", "Inability to transmit standard encrypted HTTPS web traffic", "High propagation latency (typically 500-700+ ms round-trip) due to the immense physical distance to geostationary orbit (35,786 km)"], "answer": 1, "explanation": "Geostationary orbit (GEO) satellites orbit at 35,786 km (22,236 miles) above the equator. Radio waves traveling at the speed of light must make a four-way journey (client -> satellite -> ground station -> satellite -> client), introducing a minimum round-trip propagation latency of 500-700 ms, which creates noticeable delays in real-time interactive VoIP and video. Satellite connections do support bidirectional upload/download and standard encryption.", "distractor_analysis": {"1": "Modern satellite internet terminals are bidirectional, transmitting uploads via satellite RF transponders.", "2": "Satellite links communicate purely through free-space radio frequencies to satellite dishes without underground fiber drops.", "3": "Satellite connections carry standard TCP/IP traffic, fully supporting TLS and HTTPS encryption."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "satellite", "latency", "internet-types", "wan"]}, {"id": "C1-211", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "Which of the following hypervisor platforms is classified as a Type 1 (bare-metal) hypervisor that runs directly on physical server hardware without an underlying host operating system?", "options": ["VMware Workstation Pro for Windows", "Parallels Desktop for Mac", "Microsoft Hyper-V Server / VMware ESXi", "Oracle VM VirtualBox"], "answer": 2, "explanation": "Type 1 (bare-metal) hypervisors (such as VMware ESXi, Microsoft Hyper-V, KVM, and Xen) install directly onto the physical server hardware, managing hardware resources and scheduling guest virtual machines with minimal overhead. Oracle VirtualBox, VMware Workstation, and Parallels Desktop are Type 2 (hosted) hypervisors that run as applications inside a general-purpose host OS.", "distractor_analysis": {"1": "Oracle VM VirtualBox is a Type 2 hypervisor running on top of Windows, macOS, or Linux host operating systems.", "2": "VMware Workstation is a Type 2 hypervisor application that executes within desktop operating systems.", "3": "Parallels Desktop is a Type 2 hosted hypervisor designed to run virtual machines inside macOS."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hypervisor", "type-1", "bare-metal"]}, {"id": "C1-212", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A company leases virtual machines, virtual block storage, and virtual networking from a cloud service provider, while the customer internal IT team remains fully responsible for installing, patching, and securing the guest operating systems and application software. Which cloud service model is being utilized?", "options": ["Desktop as a Service (DaaS)", "Infrastructure as a Service (IaaS)", "Software as a Service (SaaS)", "Platform as a Service (PaaS)"], "answer": 3, "explanation": "Infrastructure as a Service (IaaS) provides virtualized raw computing resources (virtual servers, network switches, storage volumes, IP subnets) on demand. The customer is responsible for installing, configuring, patching, and maintaining the operating systems and application middleware. SaaS delivers turnkey applications, PaaS provides developer runtime stacks, and DaaS delivers virtual desktop workspaces.", "distractor_analysis": {"1": "Software as a Service (SaaS) delivers complete applications (e.g., Microsoft 365, Salesforce) where the provider manages everything including OS and application code.", "2": "Platform as a Service (PaaS) provides development frameworks, databases, and runtimes where the provider manages the underlying OS and patching.", "3": "Desktop as a Service (DaaS) provides virtualized desktop environments streamed to thin clients."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "service-models", "shared-responsibility"]}, {"id": "C1-213", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which cloud computing characteristic describes the automated capability to dynamically scale compute instances and storage capacity up and down in real time based on fluctuating workload demand?", "options": ["Measured Service", "Broad Network Access", "Resource Pooling", "Rapid Elasticity"], "answer": 1, "explanation": "Rapid Elasticity is the ability of cloud computing infrastructure to dynamically and automatically expand (scale out/up) and contract (scale in/down) resources based on workload metrics without human intervention. Measured service refers to resource metering for billing, broad network access means availability across diverse network clients, and resource pooling refers to multi-tenant resource sharing.", "distractor_analysis": {"1": "Measured service tracks and logs resource consumption (CPU hours, gigabytes transferred) for billing purposes.", "2": "Broad network access ensures cloud services are accessible over standard network mechanisms from any device.", "3": "Resource pooling describes how providers dynamically pool physical hardware across multiple tenant organizations."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "characteristics", "elasticity", "nist"]}, {"id": "C1-214", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A defense contractor requires a cloud deployment hosted in an external commercial datacenter where the physical server hardware and storage arrays are strictly isolated and dedicated exclusively to their single organization. Which deployment model is this?", "options": ["Community cloud shared by similar agencies", "Hybrid cloud spanning on-premises and public", "Hosted private cloud on dedicated hardware", "Multi-tenant public cloud with shared hosts"], "answer": 2, "explanation": "A Hosted Private Cloud (or Dedicated Private Cloud) is an infrastructure hosted off-premises in a third-party cloud provider's datacenter, but where physical hardware, hypervisors, and storage are dedicated exclusively to a single organization (single-tenant) rather than shared across public multi-tenant pools. Public cloud is multi-tenant, community cloud is shared by specific peer groups, and hybrid links private and public clouds.", "distractor_analysis": {"1": "Public cloud shares physical hosts between tenants, which the isolation requirement rules out.", "2": "A community cloud is shared by several organizations with a common concern, so it is not dedicated.", "3": "Hybrid describes how two environments are joined, not who owns the physical hardware."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "deployment-models", "private-cloud", "security"]}, {"id": "C1-215", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "What processor feature and UEFI/BIOS firmware setting must be explicitly enabled on a physical computer to allow hypervisors to execute 64-bit guest virtual machines with hardware acceleration?", "options": ["Extreme Memory Profile (XMP / DOCP)", "Hardware-Assisted Virtualization (Intel VT-x / AMD-V)", "UEFI Secure Boot certificate validation", "Trusted Platform Module (TPM 2.0)"], "answer": 3, "explanation": "Hardware-assisted virtualization (Intel VT-x for Intel CPUs and AMD-V for AMD CPUs) must be enabled in UEFI/BIOS firmware to allow the hypervisor to access CPU virtualization instruction extensions and execute guest virtual machines at near-native hardware speed. Secure Boot verifies signatures, TPM stores keys, and XMP overclocks RAM.", "distractor_analysis": {"1": "Secure Boot checks digital signatures of bootloaders during power-on, but does not provide CPU virtualization instruction extensions.", "2": "TPM 2.0 provides cryptographic storage for BitLocker encryption keys, unrelated to hypervisor CPU virtualization support.", "3": "XMP (Extreme Memory Profile) applies overclocked memory frequency and timings to RAM modules."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "uefi", "vt-x", "amd-v", "hardware"]}, {"id": "C1-216", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which mobile device accessory allows a laptop computer to easily connect to multiple full-size desktop monitors, wired Gigabit Ethernet, multiple USB peripherals, and external power through a single integrated docking port or cable?", "options": ["USB Flash Drive", "KVM Switch", "Bluetooth Audio Receiver", "Laptop Docking Station"], "answer": 1, "explanation": "A laptop docking station (proprietary snap-in dock or modern Thunderbolt 4 / USB-C dock) expands a laptop into a full desktop workstation by providing multiple display outputs (DisplayPort/HDMI), gigabit wired Ethernet, multiple USB-A/C ports, audio jacks, and simultaneous DC charging power over a single connection. Flash drives provide storage, KVM switches share peripherals between multiple PCs, and Bluetooth receivers handle audio.", "distractor_analysis": {"1": "A USB flash drive is portable solid-state storage, offering no port replication, video expansion, or charging capabilities.", "2": "A KVM switch allows one monitor, keyboard, and mouse to switch between multiple separate physical computers.", "3": "A Bluetooth receiver connects audio devices wirelessly, providing no docking or video capabilities."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "docking-station", "laptop"]}, {"id": "C1-217", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "What term describes the practice of sharing a smartphone's cellular Internet connection directly with a single laptop computer via a physical USB cable?", "options": ["Near Field Communication (NFC)", "Cellular Tower Roaming", "USB Tethering", "Wi-Fi Mobile Hotspot"], "answer": 2, "explanation": "USB Tethering is the configuration where a mobile device shares its cellular data connection with a connected computer over a direct physical USB cable, functioning as an external network adapter. A Wi-Fi hotspot broadcasts the connection wirelessly over 802.11, NFC communicates across a few centimeters, and roaming connects to partner cell towers.", "distractor_analysis": {"1": "A Wi-Fi mobile hotspot broadcasts an 802.11 wireless network SSID to multiple wireless devices simultaneously.", "2": "NFC is a short-range radio technology (up to 4 cm) used for contactless payments, not high-speed data tethering.", "3": "Cellular roaming occurs when a phone connects to partner cellular carrier towers outside its primary home network."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "connectivity", "tethering", "usb", "cellular"]}, {"id": "C1-218", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "Which modern mobile device technology allows users to activate, store, and switch between multiple cellular carrier subscription profiles digitally on a single smartphone without inserting a physical plastic SIM card?", "options": ["Preferred Roaming List (PRL)", "Embedded SIM (eSIM)", "International Mobile Equipment Identity (IMEI)", "MicroSD expandable storage card"], "answer": 3, "explanation": "An embedded SIM (eSIM) is a programmable microchip soldered directly onto the smartphone's logic board that allows users to download and store multiple carrier subscription profiles digitally, enabling multi-carrier switching and international roaming without physical plastic SIM cards. IMEI is a hardware serial number, MicroSD is flash storage, and PRL is roaming database tables.", "distractor_analysis": {"1": "The IMEI is a globally unique 15-digit hardware serial number that identifies a physical mobile phone, not a carrier subscription profile.", "2": "A MicroSD card expands flash storage capacity for photos and documents, not cellular carrier credentials.", "3": "A PRL is a legacy carrier frequency database table used on CDMA networks."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "esim", "sim"]}, {"id": "C1-219", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which memory form factor is utilized in modern laptop computers and compact small-form-factor devices due to its compact physical size?", "options": ["Standard Desktop Unbuffered DIMM", "Rambus In-line Memory Module (RIMM)", "Single In-line Memory Module (SIMM)", "Small Outline Dual In-line Memory Module (SO-DIMM)"], "answer": 1, "explanation": "SO-DIMMs (Small Outline DIMMs) are specifically engineered for laptops, all-in-one PCs, and thin clients, measuring approximately half the physical length of full-size desktop DIMMs. Desktop DIMMs are too large for laptops, RIMMs are obsolete proprietary Rambus modules, and SIMMs are legacy 30/72-pin modules from the 1990s.", "distractor_analysis": {"1": "Full-size desktop DIMMs are 133mm long and cannot physically fit into compact laptop memory slots.", "2": "RIMMs were proprietary memory modules used with early Intel Pentium 4 processors, long obsolete.", "3": "SIMMs are obsolete single-sided contact memory modules from vintage 1990s PCs."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "ram", "so-dimm", "form-factors"]}, {"id": "C1-220", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A technician observes that a laptop chassis is bulging outward, lifting the trackpad and separating the bottom casing seam due to a swollen lithium-ion battery. What is the FIRST and most critical safety action?", "options": ["Puncture the battery pouch with a small pin to vent trapped gases", "Place the swollen laptop inside a freezer overnight to condense the cells", "Immediately power down the laptop, disconnect the AC charger, and safely remove the battery for hazardous disposal without puncturing it", "Connect the high-wattage fast charger to fully charge the battery to 100%"], "answer": 2, "explanation": "A swollen lithium-ion battery indicates severe internal chemical degradation and gas buildup that presents an immediate risk of fire and explosive thermal runaway. The technician must immediately power down the laptop, disconnect external AC power, avoid puncturing the battery pouch (which causes violent chemical ignition upon contact with air), remove it safely, and place it in a fireproof sand container for hazardous waste recycling. Puncturing, freezing, or charging a swollen battery is extremely dangerous.", "distractor_analysis": {"1": "Charging a swollen lithium-ion battery increases internal heat and voltage pressure, triggering catastrophic thermal runaway and fire.", "2": "Puncturing a lithium-ion cell exposes volatile lithium electrolytes to oxygen and moisture, causing an immediate explosive fire.", "3": "Freezing causes moisture condensation and damages internal cell separators without fixing chemical swelling."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "battery", "safety", "swollen-battery"]}, {"id": "C1-221", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "According to the official CompTIA 6-step Troubleshooting Methodology, what is the FIRST step a technician must execute when diagnosing an issue?", "options": ["Document findings, actions, and outcomes", "Identify the problem", "Establish a theory of probable cause", "Test the theory to determine cause"], "answer": 3, "explanation": "The CompTIA Troubleshooting Methodology begins with Step 1: 'Identify the problem', which involves questioning the user, identifying user changes, performing backups before making changes, inquiring about environmental/infrastructure changes, and reviewing system logs. Step 2 is establishing a theory, Step 3 is testing the theory, and Step 6 is documenting findings.", "distractor_analysis": {"1": "Establishing a theory of probable cause is Step 2, performed after gathering problem details in Step 1.", "2": "Testing the theory is Step 3, performed to confirm or disprove the theory established in Step 2.", "3": "Documenting findings is Step 6, the final step performed after verifying full system functionality."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "methodology", "comptia", "step-1"]}, {"id": "C1-222", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A technician has tested their theory of probable cause regarding a system fault and successfully confirmed the root cause. What is the NEXT step in the CompTIA Troubleshooting Methodology?", "options": ["Document findings, actions, and outcomes and close the ticket", "Verify full system functionality and implement preventive measures", "Question the user to identify recent environmental changes", "Establish a plan of action to resolve the problem and implement the solution"], "answer": 1, "explanation": "Once Step 3 ('Test the theory to determine cause') confirms the root cause, the technician proceeds immediately to Step 4: 'Establish a plan of action to resolve the problem and implement the solution'. Step 5 (Verify functionality) follows implementation, Step 6 (Document findings) completes the process, and questioning the user is part of Step 1.", "distractor_analysis": {"1": "Documenting findings is Step 6, which is only performed after the solution is implemented and verified.", "2": "Verifying full system functionality is Step 5, performed after the plan of action is implemented in Step 4.", "3": "Questioning the user is part of Step 1 (Identify the problem), which took place at the start of troubleshooting."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "methodology", "comptia", "plan-of-action"]}, {"id": "C1-223", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A laser printer outputs pages that have dense, repeating vertical black lines or a completely black page across the entire sheet. Which component is the primary cause of this fault?", "options": ["Transfer corona wire assembly", "Duplexer reversing solenoid", "Primary charge roller (PCR) / High-voltage power supply", "Paper feed pickup roller"], "answer": 2, "explanation": "In a laser printer, the primary charge roller (or corona wire) applies a uniform high-voltage negative charge (-600V) across the photosensitive drum to repel toner. If the charge roller or high-voltage power supply fails, the drum has zero negative charge; toner is attracted to the entire drum surface, printing an entirely black page or heavy black stripes. Pickup rollers feed paper, transfer coronas pull toner to paper, and duplexers flip paper.", "distractor_analysis": {"1": "Worn paper pickup rollers cause paper feed failure, paper jams, or multi-sheet feeds, not black pages.", "2": "A failed transfer corona prevents toner from moving from the drum to the paper, producing completely blank white pages.", "3": "A duplexer solenoid controls mechanical paper reversal for two-sided printing, unrelated to drum electrostatic charging."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "laser", "charge-roller", "black-pages"]}, {"id": "C1-224", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "easy", "question": "Users in an office report that all print jobs sent to a network printer are stuck in the Windows print queue with status 'Printing' or 'Error - Printing', and no new jobs will process. What is the fastest administrative fix?", "options": ["Refill the cyan toner cartridge hopper", "Stop and restart the Windows Print Spooler service (or clear the C:\\Windows\\System32\\spool\\PRINTERS directory)", "Reinstall the Windows operating system on all client workstations", "Replace the physical fuser assembly in the laser printer"], "answer": 3, "explanation": "When a corrupted print job halts the Windows print queue, restarting the Windows Print Spooler service (via services.msc or 'net stop spooler && net start spooler') and clearing out stuck .SPL and .SHD spool files from the spool directory flushes the stalled job and restores normal printing. Reinstalling Windows is unnecessary, and fusers/toner do not freeze software print queues.", "distractor_analysis": {"1": "Reinstalling the operating system on workstations is extreme, disruptive, and unnecessary for a simple software spooler hang.", "2": "The fuser is a mechanical heating element; a frozen software queue is a Windows spooler service issue.", "3": "Low toner generates an on-screen warning or faded print, but does not lock the software print spooler queue."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "spooler", "windows", "queue"]}, {"id": "C1-225", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A laser printer continuously spits out dozens of pages printed with endless lines of garbled text, random ASCII symbols, and binary code. What is the root cause of this problem?", "options": ["Low toner levels inside the black toner hopper", "A physical paper jam in the duplex assembly", "A blown thermal fuse in the fuser unit", "An incorrect or corrupted printer driver / Page Description Language (PostScript vs PCL) mismatch"], "answer": 1, "explanation": "When a printer receives data formatted in a Page Description Language (PDL) it cannot interpret (e.g., sending PostScript code to a printer expecting PCL, or using an incompatible generic driver), the printer treats the raw binary formatting code as plain ASCII text and prints endless pages of garbled characters and symbols. Installing the correct manufacturer PostScript/PCL driver resolves this. Low toner causes faded text, and jams stop paper motion.", "distractor_analysis": {"1": "Low toner produces faint, washed-out printing or streaks, not garbled binary characters.", "2": "A paper jam halts the physical paper path and triggers an immediate paper jam error on the printer control panel.", "3": "A blown fuser fuse prevents heating, resulting in loose, smudged toner rather than garbled text."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "driver", "pdl", "pcl", "postscript", "garbled-print"]}, {"id": "C1-226", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "A user reports that every few days their desktop workstation clock falls behind by several minutes, and during power-on the computer displays a pre-boot BIOS checksum error. Which component should the technician replace?", "options": ["The primary system RAM module", "The active CPU heatsink fan", "The CR2032 lithium coin-cell CMOS battery on the motherboard", "The desktop power supply unit (PSU)"], "answer": 2, "explanation": "A depleted CR2032 3V lithium coin-cell battery cannot maintain sufficient voltage to power the Real-Time Clock (RTC) oscillator and volatile CMOS settings memory when the system is unpowered or in standby, resulting in time drift, loss of BIOS configurations, and 'CMOS Checksum Error' messages during POST. Replacing the coin-cell battery resolves the issue permanently. PSUs, RAM, and fans do not power the pre-boot RTC chip.", "distractor_analysis": {"1": "The main power supply unit powers the PC while running, but does not provide standby RTC battery backup when AC power is disconnected.", "2": "System RAM is volatile memory holding runtime OS data and does not regulate motherboard hardware RTC clock timing.", "3": "CPU fans provide thermal cooling and have no connection to motherboard BIOS battery power."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "bios", "cmos", "battery", "rtc", "troubleshooting"]}, {"id": "C1-227", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "A conference room PC must be connected to a wall-mounted commercial 4K television to deliver high-definition presentations with both multi-channel digital audio and video over a single cable. Which connection interface is the standard choice?", "options": ["3.5mm analog stereo audio cable", "High-Definition Multimedia Interface (HDMI)", "Legacy 15-pin analog VGA", "Digital Visual Interface (DVI-D)"], "answer": 3, "explanation": "HDMI is the universal consumer and commercial audiovisual standard for televisions and displays, transmitting uncompressed ultra-high-definition digital video (up to 4K/8K) and multi-channel digital audio simultaneously across a single cable. VGA is analog video-only, DVI-D carries video without native TV audio integration, and 3.5mm cables carry audio only.", "distractor_analysis": {"1": "VGA is an obsolete analog video standard that cannot carry audio signals and lacks bandwidth for 4K resolutions.", "2": "DVI-D carries digital video but does not standardly transmit consumer television audio streams.", "3": "A 3.5mm stereo cable transmits analog sound waves only, with no video transmission capability."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "hdmi", "display", "audio", "video"]}, {"id": "C1-228", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user notices that a shared cloud spreadsheet synced locally to their desktop does not contain edits made earlier in the day by a colleague. What is the BEST first action the technician should take to diagnose the synchronization issue?", "options": ["Immediately format the local hard drive and perform a clean OS reinstallation", "Submit a public utility outage ticket to the municipal power company", "Permanently delete the user cloud user profile account", "Open the local cloud storage sync client, check the activity log for reported file sync or conflict errors, and follow the resolution steps"], "answer": 1, "explanation": "Cloud storage synchronization clients (such as OneDrive, Google Drive, or Dropbox) maintain real-time sync status logs and error indicators. Opening the client reveals specific error conditions (e.g., file lock conflicts, authentication expiration, exceeded quotas, or path length violations) and provides automated conflict resolution wizards. Formatting drives, reporting power outages, or deleting user accounts are destructive and irrelevant.", "distractor_analysis": {"1": "Formatting the hard drive destroys local user files without diagnosing the specific cloud synchronization conflict.", "2": "Municipal power outages are unrelated when the user's computer and network are fully powered on and operational.", "3": "Deleting the user account terminates cloud access and destroys permissions, worsening the issue."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "storage", "synchronization", "troubleshooting"]}, {"id": "C1-229", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "easy", "question": "A technician is preparing to replace a user laptop's aging mechanical hard drive (HDD) with a high-speed solid-state drive (SSD). What is the FIRST and most critical action the technician must perform before touching the hardware?", "options": ["Flash the motherboard BIOS with uncertified beta firmware", "Uninstall all anti-malware software from the operating system", "Create a complete verified backup or disk image of the existing hard drive", "Upgrade the laptop DDR4 RAM to maximum capacity"], "answer": 2, "explanation": "According to CompTIA best practices and standard IT procedures, the mandatory first step before performing any drive replacement, storage migration, or major maintenance is to perform a full, verified backup or sector-by-sector disk image of the source drive to prevent catastrophic data loss if the drive fails during cloning. RAM upgrades, firmware flashing, and disabling antivirus are not pre-requisites.", "distractor_analysis": {"1": "Upgrading RAM may be a separate performance improvement, but does not protect existing disk data.", "2": "Flashing beta firmware introduces platform instability and carries no data protection function.", "3": "Uninstalling security software leaves the system vulnerable to malware and is unnecessary for storage upgrades."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["troubleshooting", "storage", "backup", "ssd-upgrade", "best-practices"]}, {"id": "C1-230", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A smartphone user notices that their phone chassis has split open along one seam, the glass screen is lifting, and the device is visibly bulging. What action should the user take FIRST?", "options": ["Fully discharge the battery to 0% and then rapid-charge it to 100%", "Immediately power off the device, stop charging it, place it in a fire-safe location, and contact the manufacturer or qualified service provider", "Place the smartphone into a bowl of dry white rice for 48 hours", "Put the smartphone into a domestic refrigerator freezer overnight"], "answer": 3, "explanation": "A bulging or split smartphone casing is caused by a swollen lithium-ion battery. This indicates internal cell damage and gas accumulation that can lead to hazardous thermal runaway and fire. The user must immediately shut off the device, disconnect the charger, store it in a cool, fire-safe location, and seek authorized warranty replacement/hazardous disposal. Rice, freezers, and charging cycles will not fix chemical gas swelling and increase fire risk.", "distractor_analysis": {"1": "Placing a device in rice is an ineffective folk remedy for water damage, providing zero benefit for a physically swollen battery.", "2": "Freezing causes internal moisture condensation and does not reverse chemical lithium-ion cell swelling.", "3": "Deeply discharging and rapid-charging a compromised battery generates intense heat, triggering catastrophic battery ignition."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "battery", "safety", "swelling"]}, {"id": "C1-231", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "What network classification describes short-range wireless connectivity (typically within 10 meters) connecting personal peripheral devices like wireless mice, keyboards, headsets, and smartwatches?", "options": ["Local Area Network (LAN)", "Wide Area Network (WAN)", "Metropolitan Area Network (MAN)", "Personal Area Network (PAN)"], "answer": 1, "explanation": "A Personal Area Network (PAN / WPAN), commonly utilizing Bluetooth (IEEE 802.15.1) or NFC, provides short-range data communication (within ~10 meters / 30 feet) centered around an individual person and their personal computing accessories. LANs cover buildings, WANs span countries/continents, and MANs span entire cities.", "distractor_analysis": {"1": "A Local Area Network (LAN) spans an entire office, building, or home using Ethernet and Wi-Fi infrastructure.", "2": "A Wide Area Network (WAN) connects geographically separated networks across cities, countries, or the globe (e.g., the Internet).", "3": "A Metropolitan Area Network (MAN) spans a municipal city or large university campus."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "network-types", "pan", "bluetooth", "lan"]}, {"id": "C1-232", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "Among the following WAN and broadband Internet connection technologies, which provides the highest theoretical throughput speeds and lowest transmission latency?", "options": ["Digital Subscriber Line (DSL)", "DOCSIS 3.0 Coaxial Cable broadband", "Fiber-optic broadband (FTTH / 10G-PON)", "Geostationary satellite Internet"], "answer": 2, "explanation": "Fiber-optic broadband (Fiber to the Home / FTTH / 10G-PON) transmits light pulses through glass optical fibers, offering symmetrical gigabit to multi-gigabit speeds (1 to 10 Gbps+) and ultra-low single-digit millisecond latency. Satellite suffers from high propagation delay (500+ ms), DSL is limited by copper phone line attenuation (up to 100 Mbps), and coaxial cable is shared bandwidth with asymmetric upload limits.", "distractor_analysis": {"1": "Satellite internet has high latency (500-700 ms on GEO) and lower throughput due to atmospheric and orbital distance limits.", "2": "DSL relies on legacy twisted-pair copper telephone lines, suffering rapid signal degradation over distance.", "3": "Cable broadband offers high download speeds, but is constrained by asymmetrical upload bandwidth and shared neighborhood coaxial loops."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "internet-connections", "fiber", "broadband", "speed"]}, {"id": "C1-233", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which short-range high-frequency wireless radio technology (operating at 13.56 MHz over distances under 4 cm) is utilized by mobile devices to process contactless point-of-sale payments (e.g., Apple Pay, Google Wallet)?", "options": ["Cellular 5G Ultra-Wideband", "Near Field Communication (NFC)", "Bluetooth Classic", "Wi-Fi Direct (IEEE 802.11)"], "answer": 3, "explanation": "Near Field Communication (NFC) operates at 13.56 MHz using electromagnetic induction over ultra-short distances (typically under 4 cm / 1.5 inches). This extreme proximity provides inherent physical security, making NFC the universal standard for mobile contactless payments, tap-to-pair setup, and transit card passes. Bluetooth, Wi-Fi Direct, and 5G operate over much larger distances.", "distractor_analysis": {"1": "Bluetooth operates over ~10 meters at 2.4 GHz and is not used for point-of-sale tap-to-pay transaction security.", "2": "Wi-Fi Direct allows peer-to-peer file sharing over 802.11 radio, lacking contactless payment terminal integration.", "3": "Cellular 5G provides high-speed wide-area carrier connectivity over cell towers, not short-range payment terminal induction."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "nfc", "contactless-payment", "wireless"]}, {"id": "C1-234", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A technician is troubleshooting a wired desktop computer that experiences intermittent network disconnections. To verify whether the physical Ethernet transceiver and internal circuitry of the network interface card (NIC) are functioning correctly without external cable variables, which tool should the technician plug into the RJ-45 port?", "options": ["Digital multimeter on resistance mode", "Tone generator and probe", "Optical Power Meter", "Hardware RJ-45 Loopback plug"], "answer": 1, "explanation": "An Ethernet loopback plug connects the physical transmit pins (pins 1 and 2 in 10/100) directly to the receive pins (pins 3 and 6) inside a single RJ-45 connector. When plugged into a NIC while running diagnostic software, it tests the adapter's internal MAC/PHY transceiver chips, verifying whether the NIC hardware itself is healthy. Multimeters test continuity, toners trace cables, and optical meters test fiber power.", "distractor_analysis": {"1": "A multimeter measures static electrical resistance or voltage, but cannot emulate network data frames to test NIC transceivers.", "2": "A tone generator and probe injects audio tones to trace cables through walls, but does not test NIC interface hardware.", "3": "An optical power meter measures optical light loss on fiber-optic links, not copper Ethernet NICs."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "tools", "loopback-plug", "nic", "troubleshooting"]}, {"id": "C1-235", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "medium", "question": "A technician is calculating the minimum power supply wattage required for a custom server containing two CPUs (100W each), five SAS hard drives (9W each), a high-end compute GPU (200W), and motherboard/RAM overhead (75W). What is the minimum standard PSU capacity required to safely power this system with recommended headroom?", "options": ["350W, sized on the drive and fan load only", "400W, sized on the GPU rating alone", "650W to 750W, covering the 520W peak with headroom", "250W, sized on the idle draw of the two CPUs"], "answer": 2, "explanation": "Calculating component power consumption: 2 CPUs x 100W = 200W; 5 HDDs x 9W = 45W; GPU = 200W; Motherboard/fans/RAM = ~75W. Total continuous power draw = 520 Watts. Standard engineering best practice requires sizing the PSU with 20% to 30% headroom (520W / 0.8 = 650W) to handle transient load spikes and ensure efficiency within the 50-80% load curve. PSUs rated at 250W, 350W, or 400W would immediately trigger over-current protection (OCP) shutdowns.", "distractor_analysis": {"1": "Idle draw is not the sizing number. Peak concurrent load is roughly 520W, so 250W browns out under load.", "2": "Drives and fans are a small share of the budget. This ignores 400W of CPU and GPU draw.", "3": "The GPU alone is 200W. Adding two CPUs, five SAS drives and board overhead puts peak well past 400W."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "psu", "wattage-calculation", "sizing"]}, {"id": "C1-236", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A technician is troubleshooting a newly assembled desktop computer that shows no signs of life (no fan spin, no LEDs, no POST) when the front power button is pressed. The technician verifies that the AC wall outlet, power cord, and PSU master switch are functional. What is the NEXT logical physical connection to inspect?", "options": ["The monitor DisplayPort cable seating", "The front-panel power switch jumper lead connection on the motherboard front panel header", "The SATA data cable connected to the solid-state drive", "The thermal paste distribution under the CPU cooler"], "answer": 3, "explanation": "If the PSU has power but pressing the power button produces zero response, the most common issue in custom builds is an unseated, loose, or incorrectly oriented front-panel power switch (PWR_SW) jumper lead on the motherboard's front panel header. Inspecting the header pins or momentarily bridging the power switch pins with a flathead screwdriver tests this immediately. SATA cables, thermal paste, and display cables do not prevent power spin-up.", "distractor_analysis": {"1": "A disconnected SATA cable prevents drive detection during boot, but does not prevent the PSU from turning on.", "2": "Thermal paste affects heat dissipation; a computer will still power on and spin fans even with missing thermal paste.", "3": "A loose display cable prevents video output to the monitor, but the PC chassis fans and LEDs will still power on."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "power", "front-panel", "motherboard"]}, {"id": "C1-237", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which operating system power management feature in mobile devices dynamically dims display brightness, limits CPU peak performance, stops background application refreshes, and pauses automatic email polling to maximize remaining battery runtime?", "options": ["Do Not Disturb mode", "High Performance Power Profile", "Airplane mode", "Battery Saver / Low Power Mode"], "answer": 1, "explanation": "Battery Saver (Low Power Mode) is an automated OS power state that extends battery runtime by reducing display brightness, throttling CPU clock speeds, disabling visual effects, pausing background app sync, and suspending push email. Do Not Disturb silences notifications, High Performance consumes maximum power, and Airplane mode disables all radios.", "distractor_analysis": {"1": "Do Not Disturb silences incoming audio rings and banner notifications, but does not throttle CPU power or dim screens.", "2": "High Performance mode maximizes CPU frequencies and display brightness, increasing battery drain.", "3": "Airplane mode disables RF wireless radios (cellular, Wi-Fi, Bluetooth), but does not specifically manage background OS tasks or screen throttling."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "power-management", "battery", "battery-saver"]}, {"id": "C1-238", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which of the following wireless security encryption protocols utilizes CCMP (Counter Mode with Cipher Block Chaining Message Authentication Code Protocol) based on AES-128 to provide strong, standardized protection for Wi-Fi networks?", "options": ["Wi-Fi Protected Setup (WPS)", "Original WPA with TKIP", "Wi-Fi Protected Access 2 (WPA2)", "Wired Equivalent Privacy (WEP)"], "answer": 2, "explanation": "WPA2 (Wi-Fi Protected Access 2, standardized as IEEE 802.11i) mandates the use of AES (Advanced Encryption Standard) encryption via the CCMP protocol, providing robust confidentiality and integrity. WEP is completely obsolete and cryptographically broken, original WPA uses vulnerable TKIP, and WPS has severe PIN brute-force vulnerabilities.", "distractor_analysis": {"1": "Wired Equivalent Privacy (WEP) uses RC4 encryption with 24-bit initialization vectors and can be cracked in seconds.", "2": "Wi-Fi Protected Setup (WPS) is an easy-connection mechanism vulnerable to offline PIN brute-force attacks.", "3": "Original WPA uses Temporal Key Integrity Protocol (TKIP) with RC4, which is deprecated due to security weaknesses."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "security", "wpa2", "aes", "ccmp"]}, {"id": "C1-239", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A workstation experiences system crashes and driver errors immediately following a recent driver update. Which Windows recovery feature allows a technician to revert system files, installed drivers, and registry settings back to an earlier working point in time without deleting personal user documents?", "options": ["Disk Defragmenter", "System Restore (rstrui.exe)", "Disk Cleanup (cleanmgr.exe)", "Format Drive utility"], "answer": 3, "explanation": "Windows System Restore (rstrui.exe) uses Volume Shadow Copy snapshots (Restore Points) to roll back operating system files, Windows updates, installed device drivers, and system registry hives to a previous known-good state, resolving boot errors and driver corruption without deleting personal user documents. Disk Cleanup frees space, formatting erases drives, and defragmentation optimizes spinning disk sectors.", "distractor_analysis": {"1": "Disk Cleanup deletes temporary files and cache data to free storage space, but cannot roll back system drivers.", "2": "Formatting a drive erases all partitions and files, destroying user data.", "3": "Disk Defragmenter consolidates fragmented file clusters on mechanical hard drives, having no recovery rollback function."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "windows", "system-restore", "recovery"]}, {"id": "C1-240", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "easy", "question": "A departmental network printer suddenly stops printing, and all submitted user documents accumulate in the queue. The printer status icon in Windows displays 'Offline'. What is the most probable cause?", "options": ["The printer requires a 220V three-phase electrical upgrade", "The client computer RAM memory is running in single-channel mode", "The printer photosensitive drum has reached its end of life", "The printer is powered off, disconnected from the network cable, or has an unresolvable IP communication failure"], "answer": 1, "explanation": "A printer displays 'Offline' status in Windows when the operating system's print subsystem can no longer communicate with the device across its configured port (e.g., the printer was powered off, the Ethernet cable was unplugged, the Wi-Fi dropped, or its DHCP IP address changed without updating the TCP/IP port). Powering on and restoring network connectivity brings it online. Phase upgrades, single-channel RAM, and drum life do not cause network offline states.", "distractor_analysis": {"1": "Standard office printers run on standard single-phase 120V or 230V AC wall power, not industrial 220V three-phase.", "2": "RAM channel configurations (single vs dual channel) affect PC memory throughput, completely unrelated to printer connectivity.", "3": "An expired drum unit causes poor print quality or maintenance warnings, but does not take the printer's network interface offline."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "offline", "network-printer"]}, {"id": "C1-241", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "Which foundational characteristic of cloud computing allows organizations to dynamically increase compute, storage, and networking capacity on demand to accommodate growing business workloads without purchasing new physical datacenter servers?", "options": ["Static non-routable perimeter networking", "On-premises hardware maintenance requirements", "Scalability (Vertical scaling up and Horizontal scaling out)", "Local Direct-Attached Storage (DAS)"], "answer": 2, "explanation": "Scalability is a core cloud characteristic that enables an organization to seamlessly accommodate growing workloads by increasing capacity: either vertically (scaling up by adding more CPU cores or RAM to an existing virtual machine) or horizontally (scaling out by provisioning additional VM instances in parallel). Direct-Attached Storage, static isolation, and on-premises maintenance represent legacy traditional IT constraints.", "distractor_analysis": {"1": "Direct-Attached Storage (DAS) refers to dedicated local drives attached to a physical server, lacking cloud pooling flexibility.", "2": "Static non-routable networking restricts communication and contradicts cloud broad network access.", "3": "On-premises hardware maintenance is the responsibility of the cloud provider in public cloud models."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "scalability", "characteristics", "elasticity"]}, {"id": "C1-242", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "What is the primary security function of a network firewall deployed at the boundary between an internal corporate LAN and the public Internet?", "options": ["To boost wireless radio signal coverage across building floors", "To inspect and filter incoming and outgoing network traffic, blocking unauthorized access based on defined security rules", "To convert analog dial-up telephone signals into digital Ethernet packets", "To automatically assign IP addresses to client workstations using DHCP"], "answer": 3, "explanation": "A firewall is a network security device that monitors and controls incoming and outgoing network traffic based on predetermined security rules (ACLs, stateful packet inspection, port/protocol filtering), acting as a barrier to block unauthorized external access while allowing legitimate business traffic. Modems convert analog signals, DHCP servers assign IPs, and wireless repeaters extend Wi-Fi coverage.", "distractor_analysis": {"1": "Converting analog telephone waveforms to digital signals is the role of an analog modem (modulator/demodulator).", "2": "Dynamically assigning IP configurations to network hosts is the function of a DHCP server.", "3": "Amplifying wireless radio signal coverage is performed by Wi-Fi repeaters, mesh nodes, and additional access points."}, "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "firewall", "security", "perimeter"]}, {"id": "C1-243", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "medium", "question": "On modern OEM desktop and laptop computers (such as Dell, HP, or Lenovo), where is the factory Windows digital license product key permanently embedded and automatically validated during operating system installation?", "options": ["Printed on a paper card inside the shipping box packing foam", "Stored in the Master Boot Record of the original hard drive", "Stored in the local router DHCP option pool", "Embedded in the motherboard UEFI firmware (MSDM table in ACPI)"], "answer": 1, "explanation": "Modern OEM computers embed the Windows Product Key (Digital License) directly inside the motherboard's UEFI firmware within the Microsoft Data Custom Marker (MSDM) table in ACPI. During Windows installation, setup automatically reads the embedded key from UEFI and activates without prompting the user. Legacy PCs used paper COA stickers on the chassis, but modern systems use firmware-embedded keys.", "distractor_analysis": {"1": "Loose paper cards are no longer used for pre-installed OEM Windows licensing on commercial hardware.", "2": "The MBR contains partition tables and boot code; storing license keys on drives would break licensing if the drive were replaced.", "3": "DHCP option pools distribute IP and DNS parameters, not Microsoft OS product activation keys."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "uefi", "windows", "licensing", "product-key"]}, {"id": "C1-244", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which of the following physical cable types is standardly used to establish a wired Category 6 Ethernet connection between a workstation and a wall jack?", "options": ["HDMI 2.1 High-Speed video cable", "Single-pair analog RJ-11 telephone cord", "Unshielded Twisted Pair (UTP) copper cable with RJ-45 (8P8C) connectors", "USB 3.0 Type-A to Type-B peripheral cable"], "answer": 2, "explanation": "Category 6 Unshielded Twisted Pair (UTP) copper cabling terminated with 8P8C (RJ-45) connectors is the universal standard for wired 1000BASE-T and 10GBASE-T Ethernet network connections. USB connects peripherals, HDMI carries video/audio to displays, and RJ-11 connects legacy analog telephone landlines.", "distractor_analysis": {"1": "USB Type-A to Type-B cables connect peripheral devices like printers and audio interfaces, not Ethernet LANs.", "2": "HDMI cables transmit high-definition digital video and audio to monitors and TVs.", "3": "RJ-11 cables are 4-pin/6-pin telephone cords used for analog POTS telephone lines and DSL modems."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "ethernet", "utp", "rj45"]}, {"id": "C1-245", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "single", "difficulty": "easy", "question": "Which of the following physical components is soldered directly onto the motherboard PCB as an integrated expansion socket to receive system memory modules?", "options": ["External USB flatbed document scanner", "Dual In-line Memory Module (DIMM) RAM slots", "External 3.5-inch mechanical hard drive", "Modular ATX power supply unit"], "answer": 3, "explanation": "DIMM (Dual In-line Memory Module) memory slots are physical multi-pin sockets soldered directly to the motherboard printed circuit board, engineered to receive and lock in DDR4 or DDR5 RAM sticks. Hard drives, power supplies, and external scanners are separate components connected via cables or mounting bays.", "distractor_analysis": {"1": "Hard disk drives are secondary storage devices mounted in chassis drive cages and connected via SATA/SAS cables.", "2": "Power supply units are standalone enclosures mounted in the chassis and connected to the motherboard via power harnesses.", "3": "Flatbed document scanners are external desktop peripherals connected via USB cables."}, "video_reference": {"title": "Motherboards - CompTIA A+ 220-1201 - 3.5", "url": "https://www.youtube.com/watch?v=dbxM_LFMXpw", "duration": "6:18", "objective": "3.5"}, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["hardware", "motherboard", "ram", "dimm", "slots"]}, {"id": "C1-246", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A datacenter technician is configuring a database server that requires real-time memory integrity checking to prevent system crashes caused by alpha particle radiation and electrical noise. Which type of memory technology must be specified?", "options": ["Non-ECC unbuffered desktop DDR4", "Dual-channel consumer dynamic RAM", "High-frequency non-parity SODIMM", "Error-Correcting Code (ECC) RAM"], "answer": 1, "explanation": "Error-Correcting Code (ECC) RAM contains dedicated parity bits and algorithmic logic that detects and automatically corrects single-bit memory errors in real time, while detecting multi-bit errors and halting the system cleanly to prevent silent database corruption and catastrophic crashes. Non-ECC RAM lacks error correction.", "distractor_analysis": {"1": "Non-ECC RAM cannot detect or correct memory bit flips, which can cause silent data corruption and unexpected operating system kernel panics.", "2": "Dual-channel is a memory bus architecture that doubles memory bandwidth, not an error-correction mechanism.", "3": "Non-parity SODIMMs are consumer laptop modules with no error detection or correction capabilities."}, "video_reference": {"title": "An Overview of Memory - CompTIA A+ 220-1201 - 3.3", "url": "https://www.youtube.com/watch?v=JylKt1N6o0I", "duration": "8:38", "objective": "3.3"}, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["hardware", "ram", "ecc", "data-integrity", "server"]}, {"id": "C1-247", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A storage administrator deploys a RAID 5 array consisting of four 4 TB SAS hard disk drives. What is the total usable storage capacity of the volume, and how many concurrent disk failures can the array tolerate without data loss?", "options": ["8 TB usable capacity and tolerance for 2 drive failures", "4 TB usable capacity and tolerance for 3 drive failures", "12 TB usable capacity and tolerance for 1 drive failure", "16 TB usable capacity and tolerance for 0 drive failures"], "answer": 2, "explanation": "In a RAID 5 array, data and distributed parity are striped across all member disks. The usable capacity formula is (N - 1) x Disk Size, where N is the total number of identical drives. For four 4 TB drives: (4 - 1) x 4 TB = 12 TB of usable capacity. The equivalent capacity of one drive is consumed by distributed parity, allowing the array to survive the failure of exactly 1 drive without data loss.", "distractor_analysis": {"1": "16 TB (N x Disk Size) is the raw capacity of RAID 0, which offers 0 drive fault tolerance.", "2": "8 TB is the usable capacity of RAID 6 (N - 2) or RAID 10 (N / 2) with four 4 TB drives.", "3": "4 TB usable represents triple-mirroring, not RAID 5."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "raid5", "capacity-calculation"]}, {"id": "C1-248", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "Which RAID configuration combines disk mirroring and disk striping (a stripe of mirrored pairs) across a minimum of four physical drives, delivering both high I/O performance and redundancy?", "options": ["RAID 5 (Striping with Parity)", "RAID 10 (RAID 1+0)", "RAID 0 (Disk Striping)", "RAID 1 (Disk Mirroring)"], "answer": 3, "explanation": "RAID 10 (or RAID 1+0, Striped Mirrors) stripes data across mirrored pairs of disks. It requires a minimum of four drives and provides both the high read/write performance of RAID 0 and the redundancy of RAID 1 (capable of surviving at least one drive failure in each mirrored pair, and up to two non-paired drive failures). RAID 0 has no redundancy, RAID 1 uses 2 drives, and RAID 5 uses single parity.", "distractor_analysis": {"1": "RAID 0 is pure striping with zero redundancy; the loss of any single disk destroys all volume data.", "2": "RAID 1 is pure mirroring across two disks without striped array performance scaling.", "3": "RAID 5 uses distributed parity across three or more disks, incurring parity calculation write overhead."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "raid", "raid10", "striping", "mirroring"]}, {"id": "C1-249", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "single", "difficulty": "easy", "question": "When installing an M.2 solid-state drive, which bus interface and protocol allows the drive to communicate directly with the processor across high-speed PCIe lanes with minimal latency?", "options": ["SATA Revision 3.0 over AHCI controller", "Universal Serial Bus 3.2 Gen 2 over xHCI", "Legacy Parallel ATA over IDE channel", "Non-Volatile Memory Express (NVMe) over PCI Express (PCIe)"], "answer": 1, "explanation": "NVMe (Non-Volatile Memory Express) M.2 SSDs connect directly to CPU or chipset PCIe lanes (e.g., PCIe 4.0 x4), providing direct register access, thousands of parallel queues, and multi-gigabyte throughput. SATA M.2 drives use legacy AHCI capped at 600 MB/s, USB is an external bus, and PATA is legacy ribbon cable.", "distractor_analysis": {"1": "SATA III M.2 drives use the AHCI protocol limited to 6 Gbps (~600 MB/s) bandwidth over SATA controllers.", "2": "USB 3.2 Gen 2 connects external peripherals up to 10 Gbps, not internal direct PCIe storage buses.", "3": "Parallel ATA is an obsolete legacy storage interface limited to 133 MB/s."}, "video_reference": {"title": "Storage Devices - CompTIA A+ 220-1201 - 3.4", "url": "https://www.youtube.com/watch?v=UfLNl8-c9VM", "duration": "14:54", "objective": "3.4"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hardware", "storage", "nvme", "m2", "pcie"]}, {"id": "C1-250", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "single", "difficulty": "medium", "question": "A server rack power supply unit carries an 80 PLUS Titanium efficiency certification. Compared to 80 PLUS Bronze or Gold ratings, what operational benefit does this high rating provide in a datacenter environment?", "options": ["It generates high-voltage DC power to eliminate AC power feeds entirely", "It doubles the physical memory bandwidth of the CPU memory controller", "It delivers 90% to 96% electrical energy efficiency across all load levels, drastically reducing wasted heat and datacenter cooling power consumption", "It allows the server to operate without any internal cooling fans"], "answer": 2, "explanation": "The 80 PLUS Titanium certification is the highest energy efficiency tier, requiring 90% efficiency at 10% load, 92% at 20% load, 94% at 50% load, and 90% at 100% load on 115V (and up to 96% on 230V datacenter circuits). High efficiency minimizes electrical energy wasted as heat, significantly lowering server room air conditioning load and electrical operational costs.", "distractor_analysis": {"1": "High-efficiency PSUs still require internal cooling fans to dissipate residual heat, especially in dense 1U/2U rack servers.", "2": "80 PLUS Titanium PSUs take standard AC mains power and rectify it to +12V DC, not generating external high-voltage DC.", "3": "Power supply efficiency measures electrical conversion loss; it has no effect on motherboard RAM bus bandwidth."}, "video_reference": {"title": "Computer Power - CompTIA A+ 220-1201 - 3.6", "url": "https://www.youtube.com/watch?v=gK0SYCnWoIM", "duration": "15:31", "objective": "3.6"}, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["hardware", "power", "80-plus", "titanium", "datacenter", "efficiency"]}, {"id": "C1-251", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "single", "difficulty": "medium", "question": "In a laser printer electrophotographic process, what is the correct chronological sequence of the primary printing steps?", "options": ["Charging -> Exposing -> Fusing -> Developing -> Transferring -> Cleaning", "Cleaning -> Charging -> Exposing -> Developing -> Transferring -> Fusing", "Exposing -> Charging -> Developing -> Transferring -> Fusing -> Cleaning", "Developing -> Exposing -> Cleaning -> Charging -> Fusing -> Transferring"], "answer": 3, "explanation": "The standard 6-step electrophotographic laser printing cycle occurs in this exact sequence: (1) Cleaning (cleaning blade scrapes residual toner and discharge lamp neutralizes remaining charges), (2) Charging (primary charge roller applies uniform -600V charge to the drum), (3) Exposing (laser writes electrostatic latent image by discharging specific areas to ~-100V), (4) Developing (toner particles are electrostatically attracted to exposed areas), (5) Transferring (transfer roller applies positive charge to paper, pulling toner from drum), and (6) Fusing (heat and pressure permanently bond toner into paper fibers).", "distractor_analysis": {"1": "Exposing cannot happen before Charging; the drum must have a uniform negative charge before the laser can write the latent image.", "2": "Developing cannot happen before Exposing; the latent electrostatic image must be written by the laser first.", "3": "Fusing occurs after Transferring toner to paper, not before Developing."}, "video_reference": {"title": "Laser Printer Maintenance - CompTIA A+ 220-1201 - 3.8", "url": "https://www.youtube.com/watch?v=hp2DfL6KxwA", "duration": "7:30", "objective": "3.8"}, "notes_reference": "16_Printers.md", "tags": ["hardware", "printers", "laser", "ep-process", "sequence"]}, {"id": "C1-252", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "easy", "question": "A technician notices that printed pages from a departmental laser printer have black toner that smudges and wipes off easily when touched by hand. Which printer assembly has failed?", "options": ["Photosensitive imaging drum", "Primary corona / charge roller wire", "Paper pickup roller", "Fuser assembly (heating element / pressure roller)"], "answer": 1, "explanation": "The fuser assembly uses high heat (~200 C / 392 F) and mechanical pressure rollers to permanently melt and bond plastic toner particles into the fibers of the paper. If the fuser heating lamp fails, the thermal fuse blows, or the pressure roller is defective, toner remains as loose dry powder on top of the paper that wipes off effortlessly. Drum defects cause streaks or repeating marks, and charge rollers regulate drum voltage.", "distractor_analysis": {"1": "The imaging drum transfers the toner image to paper; if toner is already on the page, the drum functioned properly.", "2": "The primary corona wire applies the initial uniform negative charge to the drum; failure results in black or blank pages, not unfused toner.", "3": "The pickup roller feeds paper from the paper tray; failure causes paper feed jams."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "laser", "fuser", "toner-smudge"]}, {"id": "C1-253", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "A network technician needs to securely manage remote datacenter switches and Linux servers over an encrypted terminal connection. Which port and protocol must be open on the management firewall?", "options": ["Remote Desktop Protocol (RDP) over TCP port 3389", "Hypertext Transfer Protocol (HTTP) over TCP port 80", "Secure Shell (SSH) over TCP port 22", "Unencrypted Telnet over TCP port 23"], "answer": 2, "explanation": "Secure Shell (SSH) operates over TCP port 22 to provide strong cryptographic confidentiality, data integrity, and authentication for remote command-line terminal management. It completely replaces insecure legacy Telnet (TCP port 23), which sends passwords and commands in cleartext. RDP provides graphical Windows desktop access over port 3389, and HTTP is unencrypted web traffic over port 80.", "distractor_analysis": {"1": "Telnet operates over TCP port 23 in cleartext without encryption, presenting severe credential-sniffing security risks.", "2": "RDP (TCP 3389) is a proprietary Microsoft protocol for remote graphical desktop access, not lightweight command-line switch management.", "3": "HTTP (TCP 80) is an unencrypted web transport protocol that does not provide secure CLI terminal management."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "ssh", "security", "remote-management"]}, {"id": "C1-254", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which standard transport protocol and destination port does secure HTTPS web communication operate on by default?", "options": ["UDP port 53 (DNS name resolution)", "TCP port 443 (HTTPS)", "TCP port 80 (HTTP plaintext)", "TCP port 8080 (HTTP Alternate Proxy)"], "answer": 3, "explanation": "Hypertext Transfer Protocol Secure (HTTPS) operates over TCP port 443 by default, encrypting HTTP web traffic using Transport Layer Security (TLS) to ensure privacy, integrity, and server authentication. TCP port 80 is unencrypted HTTP, TCP port 8080 is an alternate web caching/proxy port, and UDP port 53 is used for DNS queries.", "distractor_analysis": {"1": "TCP port 80 is the default port for standard unencrypted HTTP web traffic.", "2": "TCP port 8080 is an alternate development and proxy port, typically unencrypted unless configured explicitly.", "3": "UDP port 53 is the primary port for Domain Name System (DNS) queries."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "https", "tls", "web"]}, {"id": "C1-255", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "A technician checks a workstation's IP configuration using ipconfig and sees an address of 169.254.42.100 with a subnet mask of 255.255.0.0. What does this indicate?", "options": ["The client leased a public routable address directly from the ISP", "The DNS server is offline, so the client fell back to a default address", "A static address was entered by hand in the adapter properties", "DHCP was unreachable, so the client self-assigned an APIPA link-local address"], "answer": 1, "explanation": "The IPv4 address block 169.254.0.0/16 is reserved for Automatic Private IP Addressing (APIPA). When a network client configured for dynamic IP addressing sends DHCPDISCOVER broadcasts but receives no DHCPOFFER from a DHCP server, Windows automatically assigns an APIPA link-local address. This allows local peer-to-peer subnet communication but prevents routing across default gateways or accessing the Internet.", "distractor_analysis": {"1": "169.254.0.0/16 is reserved for link-local use and is never routed on the public internet.", "2": "Name resolution failing does not change the address. The client would keep its lease.", "3": "A hand-configured address would not land in the APIPA range with a 255.255.0.0 mask by accident."}, "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "apipa", "dhcp", "ip-addressing", "troubleshooting"]}, {"id": "C1-256", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "Which standard Ethernet cable wiring pinout arranges the 8 color-coded conductors in this exact sequence from Pin 1 to Pin 8: White/Orange, Orange, White/Green, Blue, White/Blue, Green, White/Brown, Brown?", "options": ["Cisco Rollover console pinout", "USOC telephone pinout", "ANSI/TIA-568-B (T568B)", "ANSI/TIA-568-A (T568A)"], "answer": 2, "explanation": "The T568B commercial wiring standard specifies the pinout order: Pin 1: White/Orange, Pin 2: Orange, Pin 3: White/Green, Pin 4: Blue, Pin 5: White/Blue, Pin 6: Green, Pin 7: White/Brown, Pin 8: Brown. In contrast, T568A begins with Pin 1: White/Green, Pin 2: Green, Pin 3: White/Orange, Pin 6: Orange. Rollover reverses all pins for serial consoles.", "distractor_analysis": {"1": "T568A swaps the orange and green pairs, starting with Pin 1: White/Green and Pin 2: Green.", "2": "A Rollover cable inverts all 8 pins (Pin 1 connects to Pin 8) for Cisco RJ-45 serial console management.", "3": "USOC is an older telecommunications pinout for multi-line analog telephone wiring."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "t568b", "pinouts", "color-coding"]}, {"id": "C1-257", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "What is the maximum standard certified segment distance for 10 Gigabit Ethernet (10GBASE-T) transmission over standard Category 6 (Cat 6) unshielded twisted pair copper cable?", "options": ["10 meters (33 feet)", "55 meters (180 feet)", "100 meters (328 feet)", "30 meters (98 feet)"], "answer": 3, "explanation": "Standard Category 6 (Cat 6) cabling is rated up to 250 MHz and can reliably support 10GBASE-T (10 Gbps) up to 55 meters (180 feet) under standard installation conditions (reduced to ~37m in high-crosstalk bundles). To achieve 10 Gbps up to the full 100-meter limit, Category 6a (Augmented Cat 6 rated at 500 MHz) is required.", "distractor_analysis": {"1": "100 meters is the maximum distance for 10GBASE-T on Category 6a (Cat 6a) cabling, but standard Cat 6 cannot reliably reach 100m at 10 Gbps.", "2": "30 meters is the distance limit for Category 8 (Cat 8) 40GBASE-T datacenter top-of-rack links.", "3": "10 meters is a very short length well within Cat 6 capabilities, not the maximum certified distance boundary."}, "video_reference": {"title": "Network Cables - CompTIA A+ 220-1201 - 3.2", "url": "https://www.youtube.com/watch?v=29X5Ho3m2KU", "duration": "12:14", "objective": "3.2"}, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["hardware", "cables", "cat6", "10gbps", "distance-limits"]}, {"id": "C1-258", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which specialized tool pair should a network technician use to trace and identify a specific unlabeled network cable buried deep inside a large datacenter server rack cable bundle?", "options": ["Modular RJ-45 cable crimper", "Hardware Ethernet loopback plug", "Impact punch-down tool", "Tone generator and inductive probe (toner / fox and hound)"], "answer": 1, "explanation": "A tone generator connects to the target cable and injects a continuous audio-frequency RF tone onto the copper wire. The technician sweeps the handheld inductive probe along the bundle or patch panel; the probe's speaker amplifies the signal when brought near the specific wire, allowing quick identification. Crimpers terminate plugs, loopback plugs test NICs, and punch-down tools terminate wires into patch panels.", "distractor_analysis": {"1": "A cable crimper is a mechanical tool for attaching RJ-45 modular plugs to cable ends, offering no tracing function.", "2": "A loopback plug tests internal NIC transceiver circuitry by routing transmit signals back to receive pins.", "3": "A punch-down tool terminates wires into 110/Krone punch blocks, but cannot locate or trace unlabeled cables."}, "video_reference": {"title": "Network Tools - CompTIA A+ 220-1201 - 2.8", "url": "https://www.youtube.com/watch?v=CHQQgjtrhYU", "duration": "11:48", "objective": "2.8"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "tools", "tone-generator", "probe", "troubleshooting"]}, {"id": "C1-259", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which legacy IEEE 802.11 wireless networking standard operates exclusively in the 5 GHz radio frequency band, providing high-throughput multi-gigabit wireless using wide channels and MU-MIMO?", "options": ["IEEE 802.11g", "IEEE 802.11n (Wi-Fi 4)", "IEEE 802.11ac (Wi-Fi 5)", "IEEE 802.11b"], "answer": 2, "explanation": "IEEE 802.11ac (Wi-Fi 5) was standardized to operate exclusively in the 5 GHz band, utilizing 80/160 MHz channel bonding, 256-QAM modulation, and Multi-User Multiple Input Multiple Output (MU-MIMO) downlinks to achieve multi-gigabit throughput. 802.11b/g operate in 2.4 GHz, and 802.11n operates in both 2.4 GHz and 5 GHz.", "distractor_analysis": {"1": "IEEE 802.11b operates exclusively in the 2.4 GHz band with a maximum speed of 11 Mbps.", "2": "IEEE 802.11g operates exclusively in the 2.4 GHz band with a maximum speed of 54 Mbps.", "3": "IEEE 802.11n (Wi-Fi 4) operates in both 2.4 GHz and 5 GHz bands, not exclusively in 5 GHz."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "802.11ac", "5ghz", "mu-mimo"]}, {"id": "C1-260", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which three 20 MHz wireless channels in the 2.4 GHz frequency spectrum do not overlap with each other in North America, allowing interference-free concurrent Wi-Fi deployments?", "options": ["Channels 36, 40, and 44", "Channels 1, 6, and 11", "Channels 1, 2, and 3", "Channels 2, 4, and 8"], "answer": 3, "explanation": "In the 2.4 GHz band, each standard 20 MHz Wi-Fi channel requires 25 MHz of total channel spacing to prevent sideband interference. Across the 11 channels available in North America, only channels 1 (2.412 GHz), 6 (2.437 GHz), and 11 (2.462 GHz) have sufficient frequency separation to operate concurrently without spectral overlap. Channels 36, 40, 44 are 5 GHz channels.", "distractor_analysis": {"1": "Channels 1, 2, and 3 overlap almost entirely, causing extreme packet collisions and co-channel interference.", "2": "Channels 2, 4, and 8 overlap each other heavily and cannot operate concurrently in the same physical area.", "3": "Channels 36, 40, and 44 are non-overlapping channels in the 5 GHz UNII-1 band, not the 2.4 GHz band."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wireless", "2.4ghz", "channels", "interference"]}, {"id": "C1-261", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A datacenter infrastructure administrator installs VMware ESXi or Microsoft Hyper-V Server directly onto bare-metal physical servers with no underlying general-purpose host OS. Which hypervisor category is deployed?", "options": ["Type 2 (Hosted) Hypervisor", "Application containerization runtime engine", "Software instruction emulation layer", "Type 1 (Bare-Metal) Hypervisor"], "answer": 1, "explanation": "A Type 1 (bare-metal) hypervisor runs directly on the physical server hardware, acting as its own lean kernel/operating system to manage CPU, memory, and storage virtualization with maximum I/O performance and low latency. Type 2 hosted hypervisors (like VirtualBox or VMware Workstation) run as applications inside a desktop OS, container runtimes share a host kernel, and emulation layers translate instructions in software.", "distractor_analysis": {"1": "Type 2 hosted hypervisors run on top of an existing host operating system (such as Windows 11 or Linux), introducing host OS latency.", "2": "Application container runtimes (such as Docker) share the underlying host OS kernel rather than virtualizing full bare-metal hardware.", "3": "Emulation engines translate foreign CPU instructions in software, which is significantly slower than bare-metal hypervisor execution."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hypervisor", "type-1", "bare-metal", "datacenter"]}, {"id": "C1-262", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A software development company rents virtual compute instances, virtual private clouds (VPCs), and Elastic Block Storage from a public cloud provider, but manages the installation, security patching, and configuration of its own operating systems and applications. Which cloud service model is this?", "options": ["Platform as a Service (PaaS)", "Desktop as a Service (DaaS)", "Infrastructure as a Service (IaaS)", "Software as a Service (SaaS)"], "answer": 2, "explanation": "Infrastructure as a Service (IaaS) delivers raw virtualized computing infrastructure (VMs, storage, firewalls, subnets) on demand. The cloud provider manages the physical datacenters and hypervisors, while the customer maintains full administrative control and responsibility over the guest operating systems, middleware, and application code. SaaS delivers complete software, PaaS provides managed development stacks, and DaaS delivers virtual desktop workspaces.", "distractor_analysis": {"1": "Software as a Service (SaaS) delivers complete turnkey software applications (e.g., Salesforce, Microsoft 365) where the provider manages all infrastructure and OS.", "2": "Platform as a Service (PaaS) provides development frameworks and managed database runtimes where the provider manages the underlying OS and patching.", "3": "Desktop as a Service (DaaS) provides virtualized desktop operating system sessions to remote client endpoints."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "service-models", "shared-responsibility"]}, {"id": "C1-263", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which cloud computing characteristic describes the automated capability of cloud infrastructure to dynamically provision additional compute instances during sudden traffic surges and deprovision them when demand drops?", "options": ["Resource Pooling", "Rapid Elasticity", "Measured Service", "Broad Network Access"], "answer": 3, "explanation": "Rapid Elasticity allows cloud computing infrastructure to scale resources out (adding instances) and scale in (releasing instances) dynamically and automatically in response to real-time workload demand. Measured service tracks usage metrics for cost billing, broad network access ensures availability across varied clients, and resource pooling shares multi-tenant physical hardware.", "distractor_analysis": {"1": "Measured service refers to resource monitoring and metering for automated usage-based billing.", "2": "Broad network access ensures cloud capabilities are accessible over standard network mechanisms across diverse client platforms.", "3": "Resource pooling describes the provider pooling physical hardware dynamically across multiple client tenants."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "elasticity", "auto-scaling", "characteristics"]}, {"id": "C1-264", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "What hardware processor feature must be enabled in the system's UEFI/BIOS configuration before a hypervisor can execute 64-bit guest virtual machines with direct hardware virtualization acceleration?", "options": ["UEFI Secure Boot certificate validation", "Preboot eXecution Environment (PXE) network boot", "Simultaneous Multi-Threading (SMT / Hyper-Threading)", "Intel VT-x or AMD-V CPU virtualization extensions"], "answer": 1, "explanation": "Intel VT-x (for Intel processors) and AMD-V (for AMD processors) are hardware virtualization instruction set extensions that allow hypervisors to execute privileged CPU instructions directly on the physical processor, achieving near-native performance for guest VMs. Secure Boot verifies digital signatures, PXE enables network booting, and SMT/Hyper-Threading creates logical CPU execution threads.", "distractor_analysis": {"1": "Secure Boot verifies the authenticity of bootloaders during power-on, but does not provide CPU virtualization instructions.", "2": "PXE network boot allows a computer to boot an OS image across a local Ethernet network from a TFTP server.", "3": "Simultaneous Multi-Threading (SMT) divides physical CPU cores into logical threads, but does not enable hardware hypervisor extensions."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "uefi", "vt-x", "amd-v", "hardware"]}, {"id": "C1-265", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "How does application containerization (such as Docker or Podman) fundamentally differ from traditional Type 1 or Type 2 virtual machines?", "options": ["Containers emulate complete x86 PC motherboards and BIOS firmware inside each container", "Containers cannot execute on Linux or Windows server operating systems", "Containers share the underlying host operating system kernel and isolate user-space application processes, starting in milliseconds with minimal resource overhead", "Containers require dedicated physical network switches for every deployed container image"], "answer": 2, "explanation": "Containers utilize host operating system kernel features (such as namespaces and cgroups in Linux) to provide lightweight, isolated user spaces for application binaries and dependencies. Because containers share a single underlying host kernel, they start in milliseconds and consume drastically less RAM and CPU overhead than traditional virtual machines (which must boot complete independent guest operating systems with emulated hardware).", "distractor_analysis": {"1": "Containers use software virtual bridge networks and do not require separate physical hardware switches.", "2": "Containers do not emulate motherboard BIOS or virtual hardware; they run as isolated processes on the host kernel.", "3": "Containers run natively on modern Linux and Windows server operating systems."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "containers", "docker", "microservices"]}, {"id": "C1-266", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A company deploys low-cost, low-power endpoint terminals with no local mass storage. The terminals connect over the network to full Windows 11 desktop sessions hosted on virtual machines in a centralized datacenter. Which deployment model is this?", "options": ["Local Direct-Attached Storage clustering", "Virtual Desktop Infrastructure (VDI) with Thin Clients / DaaS", "Software as a Service (SaaS) with Thick Clients", "Peer-to-peer Workgroup file sharing"], "answer": 3, "explanation": "Virtual Desktop Infrastructure (VDI) or Desktop as a Service (DaaS) hosts complete virtualized desktop environments inside datacenter virtual machines. Users access these central desktops across the network using lightweight 'Thin Client' or 'Zero Client' terminals that handle display rendering and USB input redirection without needing local storage drives. SaaS delivers web apps, peer-to-peer shares files between local PCs, and DAS is direct local storage.", "distractor_analysis": {"1": "SaaS delivers web applications (e.g., Salesforce), whereas VDI delivers complete virtualized desktop operating system sessions.", "2": "Peer-to-peer workgroups connect standalone independent PCs without centralized datacenter virtualization.", "3": "Direct-Attached Storage (DAS) refers to dedicated local drives attached to physical servers, unrelated to thin-client virtual desktop streaming."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "vdi", "daas", "thin-client", "virtualization"]}, {"id": "C1-267", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A smartphone user reports that their mobile screen displays a crisp, clear, and bright image with no visual artifacts, but touching, tapping, or swiping anywhere on the glass produces zero response. Which internal display component has failed?", "options": ["The LCD/OLED display matrix panel", "The LED backlight array", "The graphics processing unit (GPU)", "The capacitive glass digitizer layer"], "answer": 1, "explanation": "A smartphone screen assembly is made of two primary fused layers: the display panel (OLED/LCD) that generates visual pixels and the digitizer (a transparent capacitive touch grid bonded to the glass) that detects finger contact and translates touches into digital coordinates. If the image is clear but touch does not register, the digitizer (or its ribbon cable) has failed. Display matrix failure causes visual artifacts/black screen, backlight failure causes dimness, and GPU failure stops rendering.", "distractor_analysis": {"1": "The LCD/OLED panel renders the visual image; because the image is crisp and clear, the display matrix is functioning properly.", "2": "The LED backlight provides screen brightness; if it failed, the screen would be black, but touch input would still register.", "3": "The GPU renders graphics frames; if it failed, the screen would display corrupted visual artifacts or no video."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "digitizer", "touchscreen", "display"]}, {"id": "C1-268", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A user reports that their corporate laptop trackpad has popped up above the palmrest, the lower casing seam is splitting, and the bottom is bulging outward. What is the root cause and immediate safety procedure?", "options": ["The CPU copper heat pipe has expanded due to heat; run diagnostic stress tests to vent thermal pressure", "The trackpad mounting screws became loose; retighten them firmly from underneath the motherboard", "The internal lithium-ion battery has swollen; immediately power off the laptop, disconnect the AC adapter, avoid puncturing the battery, and replace it following hazardous disposal procedures", "The keyboard ribbon cable is pinched under the chassis; push it back in firmly with a metal screwdriver"], "answer": 2, "explanation": "A swollen lithium-ion battery is a hazardous condition caused by gas buildup from internal cell degradation or thermal runaway. The expanding battery pushes upward against the trackpad and palmrest. The immediate action is to safely shut down the laptop, disconnect external AC power, avoid puncturing the battery, and replace it following hazardous materials disposal procedures. Tightening screws on a swollen battery risks puncturing cells and causing fire. Fan or SSD issues do not create physical chassis bulging.", "distractor_analysis": {"1": "Pushing metal screwdrivers into a bulging chassis risks puncturing the battery pouch, triggering an immediate explosive fire.", "2": "Copper heat pipes do not expand to distort laptop chassis; running stress tests on a computer with a failing battery accelerates fire risk.", "3": "Retightening screws or pressing down on a bulging chassis can puncture the lithium pouch, triggering a violent thermal fire."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["troubleshooting", "mobile", "battery", "safety", "swollen-battery"]}, {"id": "C1-269", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A newly assembled desktop powers on, fans spin, but the screen stays completely black and the motherboard emits a repeating series of short beeps without displaying POST. What is the MOST likely cause?", "options": ["A failed secondary SATA mechanical hard drive", "Unseated, defective, or incompatible system RAM modules", "A defective external HDMI monitor cable", "Corrupted Windows Boot Configuration Data (BCD)"], "answer": 3, "explanation": "POST (Power-On Self-Test) beeps occur before the video display subsystem is initialized. A continuous or repeating short beep code on standard BIOS firmware universally signifies missing, unseated, or defective system RAM. Reseating the RAM in the recommended slots or testing one module at a time isolates the issue. Display cable defects do not generate POST beeps, and BCD/secondary drive errors occur after POST passes.", "distractor_analysis": {"1": "A defective HDMI cable causes a 'No Signal' monitor message, but POST will complete normally with a single short success beep.", "2": "Corrupted BCD files cause operating system bootloader crashes after POST completes and hands off control.", "3": "A failed secondary data drive does not halt motherboard POST or trigger fatal pre-boot memory beep codes."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "post", "beep-codes", "ram"]}, {"id": "C1-270", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A workstation boots normally, but every time the power cord is unplugged from the wall, the system clock resets to 12:00 AM January 1, 2015 and BIOS settings revert to default. How should this be resolved?", "options": ["Run Windows Update to install the latest operating system patches", "Replace the primary 750W ATX power supply unit", "Format the system drive and reinstall Windows from scratch", "Replace the CR2032 lithium coin-cell CMOS battery on the motherboard"], "answer": 1, "explanation": "The CR2032 3V coin-cell battery on the motherboard powers the volatile CMOS RAM and Real-Time Clock (RTC) oscillator when the system is unpowered. When this battery dies, disconnecting mains AC power cuts all electrical current to the RTC, resetting the clock to its firmware epoch date and clearing custom BIOS settings. Replacing the battery permanently fixes the problem. Windows Update, PSUs, and formatting do not restore motherboard coin-cell battery voltage.", "distractor_analysis": {"1": "Windows Update updates operating system software, having no impact on motherboard pre-boot RTC battery power.", "2": "The ATX power supply provides main system power when plugged in, but does not maintain RTC memory when unplugged.", "3": "Formatting the storage drive deletes files without fixing depleted motherboard battery cells."}, "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "hardware", "cmos", "battery", "rtc", "bios"]}, {"id": "C1-271", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "easy", "question": "Users in an office report that a shared network laser printer has completely stopped printing documents, and multiple print jobs are stuck with the status 'Error - Printing'. What service should the technician restart on the print server?", "options": ["Remote Registry service", "Windows Workstation service (lanmanworkstation)", "Windows Print Spooler service (spoolsv.exe)", "DNS Client service (dnscache)"], "answer": 2, "explanation": "The Windows Print Spooler service (spoolsv.exe) manages the spooling, queuing, and transmission of print jobs to local and network printers. When a corrupted job halts the spool queue, stopping the Print Spooler, clearing out stuck spool files from C:\\Windows\\System32\\spool\\PRINTERS, and restarting the service clears the jam and restores printing. DNS Client, Remote Registry, and Workstation services do not manage print queues.", "distractor_analysis": {"1": "The DNS Client service caches DNS domain name resolutions and does not manage local or network printer spool queues.", "2": "The Remote Registry service allows remote users to modify registry settings, having no role in print job processing.", "3": "The Workstation service creates and maintains client network connections to remote servers, not local print queue spooling."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "spooler", "windows", "services"]}, {"id": "C1N-I-001", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "multi", "difficulty": "medium", "question": "A field technician is diagnosing a docking-station laptop that charges slowly over USB-C and loses the external 4K display whenever the user unplugs AC power. Which TWO hardware checks best isolate a USB-C / Thunderbolt path problem before replacing the motherboard? (Select TWO.)", "explanation": "USB-C docking issues usually split into power negotiation and DisplayPort Alt Mode. Confirming PD wattage explains slow charging when the laptop falls back to a low-watt profile, while Alt Mode support explains a 4K display that only stays up when AC keeps the dock fully powered. Random EC flashes, Secure Boot changes, and CMOS swaps do not fix Alt Mode or PD negotiation on a working port.", "video_reference": null, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-c", "dock", "displayport-alt-mode"], "options": ["Verify the dock and laptop both negotiate USB Power Delivery at the expected wattage", "Confirm the cable and dock port support DisplayPort Alternate Mode for the attached monitor", "Flash the laptop EC firmware with a random older vendor package from an unverified mirror", "Disable Secure Boot so the dock can inject unsigned display EDID overrides", "Replace the CMOS coin cell to restore USB-C video handshakes after every suspend"], "answers": [0, 1], "distractor_analysis": {"2": "Unverified older EC packages risk bricking the embedded controller and do not prove a cable or dock capability gap.", "3": "Secure Boot does not control USB-C DisplayPort Alternate Mode link training for an external monitor.", "4": "The CMOS battery preserves UEFI settings clocks; it does not restore USB-C video handshakes after suspend."}}, {"id": "C1N-I-002", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "multi", "difficulty": "medium", "question": "A datacenter NOC is onboarding rugged Android handhelds that must stay inventory-tracked, enforce work-profile isolation, and wipe automatically if lost off-site. Which TWO MDM capabilities should the technician enable in the enrollment profile? (Select TWO.)", "explanation": "Enterprise handheld fleets rely on MDM remote wipe (and container wipe) for lost-device data protection, plus location reporting for asset accountability. Sideloading unsigned APKs and weakening TLS controls expand the attack surface. Resetting Secure Boot keys nightly is unrelated to MDM enrollment and can brick devices.", "video_reference": null, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mdm", "mobile", "wipe", "asset-tracking"], "options": ["Remote wipe and selective corporate-container wipe policies", "GPS / location reporting tied to the device asset tag", "Sideloading of unsigned APKs from a public file share to speed imaging", "Disabling certificate pinning so captive portals inject TLS interception freely", "Factory-resetting Secure Boot keys on every overnight sync"], "answers": [0, 1], "distractor_analysis": {"2": "Sideloading unsigned APKs bypasses store and enterprise signing controls and is not an MDM hardening control.", "3": "Disabling certificate pinning to allow arbitrary TLS interception weakens app integrity rather than securing the fleet.", "4": "Secure Boot key resets are a platform trust operation, not a standard overnight MDM sync action."}}, {"id": "C1N-I-003", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "multi", "difficulty": "medium", "question": "During a pre-cutover firewall review, a technician must allow secure remote shell access to Linux jump hosts and encrypted web management to a SAN array GUI. Which TWO destination ports should remain permitted on the management ACL? (Select TWO.)", "explanation": "SSH on TCP 22 and HTTPS on TCP 443 are the standard encrypted management channels for jump hosts and storage GUIs. Telnet, TFTP, and FTP send credentials or payloads in cleartext and should stay blocked on production management edges unless a tightly controlled exception exists.", "video_reference": null, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["ports", "ssh", "https", "firewall"], "options": ["TCP 22 for SSH administrative sessions", "TCP 443 for HTTPS management interfaces", "TCP 23 for Telnet console access across the WAN", "UDP 69 for TFTP firmware pushes from untrusted VLANs", "TCP 21 for cleartext FTP of configuration backups"], "answers": [0, 1], "distractor_analysis": {"2": "Telnet (TCP 23) transmits credentials in cleartext and is inappropriate for WAN management access.", "3": "TFTP (UDP 69) is unauthenticated and unencrypted, making it unsafe for firmware from untrusted VLANs.", "4": "FTP (TCP 21) moves configuration data without encryption and should not be left open on management ACLs."}}, {"id": "C1N-I-004", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "multi", "difficulty": "hard", "question": "A warehouse AP survey shows sticky clients and frequent roaming drops between two 5 GHz SSIDs on adjacent channels. Which TWO wireless design changes most directly improve roaming stability without abandoning WPA3-Enterprise? (Select TWO.)", "explanation": "Fast BSS transition (802.11r) and neighbor reports (802.11k), combined with disciplined RF power and channel planning, reduce sticky-client behavior while keeping WPA3-Enterprise intact. Collapsing to 2.4 GHz worsens interference. TKIP is obsolete and weaker. Disabling STP on a bridged AP mesh invites broadcast storms.", "video_reference": null, "notes_reference": "10_Wireless_Networking.md", "tags": ["wireless", "roaming", "802.11r", "rf-design"], "options": ["Enable 802.11r / 802.11k assisted roaming features on the controller and SSIDs", "Tune AP power and channel plans so overlapping cells hand off cleanly at intended boundaries", "Force all clients onto 2.4 GHz only to increase co-channel reuse density", "Disable AES-CCMP so older TKIP stations can roam faster", "Bridge every AP into the same unmanaged Layer-2 loop with STP disabled"], "answers": [0, 1], "distractor_analysis": {"2": "Forcing 2.4 GHz concentrates traffic onto a crowded band with only three non-overlapping channels.", "3": "TKIP is deprecated and incompatible with modern WPA3-Enterprise security requirements.", "4": "Disabling STP on a large L2 wireless bridge fabric risks loops and outages, not cleaner roaming."}}, {"id": "C1N-I-005", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "multi", "difficulty": "medium", "question": "A colocation customer needs east-west isolation between production and backup server VLANs plus encrypted remote access for contractors. Which TWO technologies satisfy both requirements on the existing Layer-3 core? (Select TWO.)", "explanation": "VLAN (or VRF) segmentation provides east-west isolation between production and backup, while VPN tunnels give contractors encrypted remote reachability. A flat network with proxy ARP removes isolation. Disabling STP invites loops. Hairpinning every server through one public IP on an access switch is not a sound segmentation design.", "video_reference": null, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["vlan", "vpn", "segmentation", "datacenter"], "options": ["802.1Q VLANs with ACLs or VRFs separating production and backup segments", "Site-to-site or client VPN tunnels for contractor remote access", "A single flat /16 with proxy ARP enabled for every host", "Disabling Spanning Tree so VLAN trunks converge faster after loops", "NAT overload of every server into one public IP on the access switch"], "answers": [0, 1], "distractor_analysis": {"2": "A flat /16 with proxy ARP collapses broadcast domains and removes the isolation the customer requested.", "3": "Disabling Spanning Tree increases loop risk on switched VLAN fabrics instead of improving isolation.", "4": "NAT overload on an access switch does not separate production from backup or replace VPN encryption."}}, {"id": "C1N-I-006", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "multi", "difficulty": "medium", "question": "A rack build needs a device that terminates multiple ISP handoffs and performs dynamic routing, plus a separate device that learns MAC addresses and forwards frames inside the top-of-rack fabric. Which TWO device roles match that design? (Select TWO.)", "explanation": "Routers (or L3 gateways) terminate WAN/ISP links and route between networks. Switches forward Ethernet frames using MAC tables inside the rack. Modems, simple media converters, and print servers are not substitutes for those core roles.", "video_reference": null, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["network-devices", "router", "switch"], "options": ["Router / Layer-3 gateway for ISP handoff and routing between networks", "Ethernet switch for Layer-2 forwarding within the rack VLAN fabric", "Analog modem bank for dial-up console multiplexing of every blade", "Unmanaged media converter that also runs BGP and OSPF adjacencies", "USB print server appliance terminating ISP BGP sessions"], "answers": [0, 1], "distractor_analysis": {"2": "Analog modem banks are obsolete console/WAN tools and do not replace rack switching or ISP routing.", "3": "A basic media converter changes media types; it does not establish BGP/OSPF as a primary function.", "4": "USB print servers share printers; they do not terminate ISP BGP sessions."}}, {"id": "C1N-I-007", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.4", "type": "multi", "difficulty": "hard", "question": "A storage tech is commissioning a four-disk array that must survive a single drive failure with usable capacity better than mirroring, while a second array needs maximum write performance for scratch VMs and can tolerate total data loss. Which TWO RAID choices fit? (Select TWO.)", "explanation": "RAID 5 provides single-disk fault tolerance with better usable capacity than full mirroring on four disks. RAID 0 maximizes striped performance with zero redundancy, matching disposable scratch storage. RAID 1 on four disks is not the performance-first scratch choice described. JBOD is not RAID 10. RAID 2 is obsolete.", "video_reference": null, "notes_reference": "06_Storage_and_RAID.md", "tags": ["raid", "storage", "fault-tolerance"], "options": ["RAID 5 for single-drive fault tolerance with parity striping on four disks", "RAID 0 for maximum striped performance with no redundancy on the scratch array", "RAID 1 across all four disks with no striping for the scratch workload", "JBOD concatenation claiming RAID 10 dual-parity protection", "RAID 2 Hamming-code arrays as the only modern SSD default"], "answers": [0, 1], "distractor_analysis": {"2": "Four-disk RAID 1 (or multi-mirror) prioritizes redundancy over the maximum-write scratch use case.", "3": "JBOD merely concatenates disks; it does not deliver RAID 10 dual-mirror or dual-parity protection.", "4": "RAID 2 Hamming arrays are historical and not a modern SSD default for either requirement."}}, {"id": "C1N-I-008", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.5", "type": "multi", "difficulty": "medium", "question": "A technician upgrading a dual-socket server must add a 100 GbE NIC and a hardware RAID HBA. Which TWO motherboard / expansion considerations must be verified before ordering cards? (Select TWO.)", "explanation": "High-speed NICs and RAID HBAs need matching PCIe electrical/mechanical slots plus firmware that can boot from the HBA and load NIC Option ROM/UEFI drivers. Cosmetic jumper colors, ISA slots, and disabling ECC are irrelevant or harmful.", "video_reference": null, "notes_reference": "04_Motherboards_Expansion_Cards.md", "tags": ["motherboard", "pcie", "hba", "nic"], "options": ["Available PCIe slot generation, lane width, and physical form factor clearance", "BIOS/UEFI support for the HBA boot path and NIC Option ROM / UEFI drivers", "Whether the CMOS jumper color matches the NIC bracket color", "Installing both cards in legacy ISA slots for lower latency", "Disabling all ECC DIMMs so PCIe bifurcation automatically enables"], "answers": [0, 1], "distractor_analysis": {"2": "Jumper or bracket color has no bearing on PCIe signaling or boot compatibility.", "3": "Modern servers do not use ISA slots for 100 GbE or hardware RAID HBAs.", "4": "ECC memory is independent of PCIe bifurcation; disabling ECC reduces reliability without enabling slots."}}, {"id": "C1N-I-009", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.6", "type": "multi", "difficulty": "medium", "question": "After a PDU brownout, several 2U servers reboot into continuous POST loops with intermittent fan-fault LEDs. Which TWO power-subsystem checks should the tech perform first on each chassis? (Select TWO.)", "explanation": "Brownout-driven POST loops and fan-fault LEDs often trace to poorly seated redundant PSUs or overloaded PDU branches delivering unstable voltage. Swapping to non-ECC, clearing CMOS under load, or stopping fans worsens reliability and thermal risk.", "video_reference": null, "notes_reference": "05_Power_Supplies_Cooling.md", "tags": ["psu", "pdu", "power", "cooling"], "options": ["Confirm redundant PSU modules seat fully and share load within rated wattage", "Validate PSU input voltage/current and that the PDU circuit is not overloaded", "Replace every DIMM with non-ECC sticks to reduce power draw during POST", "Short the CMOS clear jumper while both PSUs remain under full load", "Disable all chassis fans so PSUs run cooler with less airflow demand"], "answers": [0, 1], "distractor_analysis": {"2": "Non-ECC memory does not fix PSU seating or PDU overload and removes ECC protection.", "3": "Clearing CMOS under load is unsafe and unrelated to verifying redundant power delivery.", "4": "Disabling chassis fans invites thermal shutdown; it does not stabilize PSU input power."}}, {"id": "C1N-I-010", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "multi", "difficulty": "medium", "question": "A hypervisor cluster must run mixed Windows and Linux guests with strong isolation, while a second platform will host many identical microservices sharing one kernel. Which TWO compute approaches match those goals? (Select TWO.)", "explanation": "Type 1 hypervisors isolate full guest OS instances, which fits mixed Windows/Linux workloads. Containers pack dense identical services that share a kernel. DOS multitasking, browser applets, and disabling CPU virtualization extensions are not appropriate enterprise answers for these requirements.", "video_reference": null, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "containers", "hypervisor"], "options": ["Type 1 hypervisor VMs for mixed OS guests with hardware-level isolation", "Containers for dense identical microservices sharing the host kernel", "MS-DOS real-mode multitasking for both platforms", "Client-side Java applets instead of server virtualization", "Disabling CPU virtualization extensions to force binary translation only"], "answers": [0, 1], "distractor_analysis": {"2": "MS-DOS real-mode multitasking cannot host modern mixed enterprise OS guests or microservice fleets.", "3": "Client-side applets do not provide server-side isolation or orchestration for these workloads.", "4": "Disabling hardware virtualization extensions degrades performance and is opposite of best practice."}}, {"id": "C1N-I-011", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "multi", "difficulty": "hard", "question": "A file server intermittently drops offline. SMART shows rising reallocated sectors on one HDD, and Windows Event Viewer logs delayed write failures. Which TWO actions are the correct next steps before data loss escalates? (Select TWO.)", "explanation": "Rising reallocations plus delayed writes indicate a dying disk. Capture data first, then replace and rebuild/restore. Formatting while live, ignoring SMART, or endless defrag does not restore redundancy and risks further corruption.", "video_reference": null, "notes_reference": "06_Storage_and_RAID.md", "tags": ["storage", "smart", "troubleshooting"], "options": ["Back up critical volumes immediately to known-good storage", "Replace the failing drive and rebuild or restore per the array/backup plan", "Run a continuous full-surface format overnight while users keep writing production data", "Disable write caching globally and ignore SMART until capacity hits 100 percent", "Defragment the failing HDD repeatedly to remap bad sectors in place of replacement"], "answers": [0, 1], "distractor_analysis": {"2": "Formatting a degrading production volume while users write risks catastrophic data loss.", "3": "Ignoring SMART until the disk is full postpones inevitable failure without protecting data.", "4": "Defragmentation cannot substitute for replacing a drive with escalating reallocated sectors."}}, {"id": "C1N-I-012", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "multi", "difficulty": "medium", "question": "Users on one VLAN can ping their gateway but cannot resolve internal hostnames, while IP-literal HTTPS to servers still works. Which TWO checks should the network tech run first? (Select TWO.)", "explanation": "Gateway reachability with working IP-literal access points to DNS configuration or DNS service failure. Confirming assigned DNS servers and testing with nslookup/dig isolates the fault. Coax swaps, killing IPv4, or tiny MTUs are unrelated distractions.", "video_reference": null, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["dns", "troubleshooting", "vlan"], "options": ["Verify client DNS server addresses and that the DNS service is reachable", "Test name resolution with nslookup/dig against the intended DNS servers", "Replace every Cat6 patch with coaxial RG-6 to improve DNS latency", "Disable IPv4 entirely so only APIPA link-locals remain", "Lower the switch MTU to 64 bytes to force DNS through ICMP only"], "answers": [0, 1], "distractor_analysis": {"2": "DNS does not require coaxial cabling; Ethernet patch quality is unrelated to this symptom pattern.", "3": "Disabling IPv4 would break the working IP connectivity the users already have.", "4": "An MTU of 64 bytes would break most traffic and is not a DNS troubleshooting step."}}, {"id": "C1N-I-013", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.7", "type": "order", "difficulty": "medium", "question": "Order the correct steps to safely clear a paper jam on a networked laser printer in a shared office without causing a fuser burn injury or a second jam.", "explanation": "Laser printers store heat in the fuser; powering down and cooling prevents burns. Clearing the path and trays removes the physical obstruction, then a controlled power-on and test page confirms the sensors and path are clear. Skipping cooldown or test verification invites injury or repeat jams.", "video_reference": null, "notes_reference": "16_Printers.md", "tags": ["printers", "safety", "laser"], "sequence": ["Power down the printer and allow the fuser area to cool before opening covers", "Open the indicated access doors and remove loose sheets in the path of the paper sensors", "Check trays and rollers for scraps, then reseat paper stacks within the guide marks", "Close all covers, power on, clear residual error messages, and print a test page"]}, {"id": "C1N-I-014", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "order", "difficulty": "medium", "question": "A new CPU and cooler were installed in a tower workstation that now fails to POST with no video. Order the technician's hardware isolation sequence.", "explanation": "POST failures after CPU work usually come from seating, power, or memory issues. Minimal configuration and beep/LED codes narrow the fault before swapping the PSU, and RMA is last after isolation. Jumping straight to motherboard replacement wastes time and parts.", "video_reference": null, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["post", "cpu", "troubleshooting"], "sequence": ["Disconnect power, ground yourself, and reseat the CPU cooler and power connectors", "Reseat RAM in known-good slots and remove nonessential PCIe cards", "Attempt POST with minimal hardware and listen for beep codes or check diagnostic LEDs", "If still dead, test with a known-good PSU rail set or alternate power supply", "Document findings and escalate to motherboard/CPU RMA only after isolation fails"]}, {"id": "C1N-I-015", "exam": "core1", "domain": "2.0 Networking", "objective": "2.8", "type": "order", "difficulty": "hard", "question": "Order the steps to troubleshoot intermittent packet loss between two datacenter racks that share an LACP uplink pair.", "explanation": "Start with counters to prove which interfaces err, then inspect physical media, isolate members under controlled failover, repair the bad link, and validate. Skipping isolation can leave a flapping member poisoning the aggregate.", "video_reference": null, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["lacp", "optics", "network-troubleshooting"], "sequence": ["Confirm the symptom window and capture interface error counters on both ends of the LACP bundle", "Inspect optics/DAC seating, TX/RX light levels, and physical damage on each member link", "Failover or shut one member at a time to determine whether loss tracks a single link", "Correct the bad member (reseating, replacement, or config mismatch) and re-enable the bundle", "Validate with sustained iperf/RFC2544 style traffic and clear monitoring alerts"]}, {"id": "C1N-I-016", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.3", "type": "order", "difficulty": "medium", "question": "Order the correct procedure to upgrade RAM in a dual-channel desktop that must remain on matched kits after the upgrade.", "explanation": "Safe power removal prevents shorts. Correct slot pairing preserves dual-channel bandwidth. Verification in UEFI/OS confirms the kit trained at the expected speed and capacity. Installing mismatched singles in wrong slots often falls back to single-channel or fails to train.", "video_reference": null, "notes_reference": "07_RAM_and_CPUs.md", "tags": ["ram", "dual-channel", "upgrade"], "sequence": ["Shut down, unplug AC, and discharge residual power by holding the power button", "Open the case, release DIMM latches, and remove the old modules if replacing them", "Install the matched kit in the motherboard's documented dual-channel slot pairs", "Reassemble, boot into UEFI/OS, and verify capacity, speed, and dual-channel status"]}, {"id": "C1N-I-017", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "order", "difficulty": "medium", "question": "Order the high-level steps to stand up a new IaaS workload in a public cloud account for a three-tier web application.", "explanation": "Cloud IaaS builds from network and security boundaries outward, then compute/data, then identity and encryption, then application deploy and observability. Provisioning VMs before network controls often creates overly open defaults that must be reworked.", "video_reference": null, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "deployment"], "sequence": ["Define regions, networking (VPC/VNet), subnets, and security groups/NSGs", "Provision compute, managed database, and load-balanced web tiers", "Configure identity roles, secrets, and encrypted storage for each tier", "Deploy application artifacts and run connectivity health checks", "Enable monitoring/alerts and document the runbook for on-call staff"]}, {"id": "C1N-I-018", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "order", "difficulty": "medium", "question": "A company phone overheats, randomly reboots, and will not join the corporate WLAN after a failed OS update. Order the mobile troubleshooting steps.", "explanation": "Thermal and battery safety come first. Isolating software vs hardware with safe mode, then repairing WLAN identity, then completing the update, and finally reset/replace follows least-destructive order for managed phones.", "video_reference": null, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "troubleshooting", "wlan"], "sequence": ["Remove the case, inspect for swelling, and let the device cool away from direct sun", "Boot to safe/diagnostic mode if available and note whether reboots continue", "Forget/rejoin WLAN and verify date/time, certificates, and VPN profiles", "Install the deferred OS/security update over a known-good network path", "If unstable, back up business data and factory-reset or replace under MDM policy"]}, {"id": "C1N-I-019", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "match", "difficulty": "medium", "question": "You are reviewing the inbound firewall ACL for a new management VLAN before the change window closes. Match each common service to the transport port it listens on.", "explanation": "Learn these cold: TCP 443 HTTPS, TCP 22 SSH, UDP and TCP 53 DNS, TCP 3389 RDP, TCP 25 SMTP relay. When a service will not respond, prove the port before you blame the application. Test-NetConnection or a telnet to the port tells you in seconds whether the ACL or the daemon is at fault. Two traps show up on the exam and on the floor: DNS is not UDP only, it falls back to TCP 53 for zone transfers and oversized responses, and TCP 25 is server-to-server relay, not the TCP 587 client submission port.", "video_reference": null, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["ports", "protocols", "match"], "pairs": [{"left": "HTTPS web management", "right": "TCP 443"}, {"left": "SSH remote shell", "right": "TCP 22"}, {"left": "DNS queries", "right": "UDP/TCP 53"}, {"left": "RDP sessions", "right": "TCP 3389"}, {"left": "SMTP mail submission (legacy cleartext)", "right": "TCP 25"}]}, {"id": "C1N-I-020", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "match", "difficulty": "medium", "question": "You are pulling cable for a new rack row and picking media for each run from the store room. Match each copper cable type to the datacenter or office use case it belongs in.", "explanation": "Cat6A supports 10 GbE at standard horizontal distances, DAC covers short rack interconnects, plenum jackets meet fire codes in air spaces, and STP helps in noisy EMI environments. Matching media to environment prevents intermittent CRC errors and failed inspections.", "video_reference": null, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["cabling", "cat6a", "dac"], "pairs": [{"left": "Cat6A UTP", "right": "10 GbE up to 100 m in structured cabling"}, {"left": "Direct-attach copper (DAC)", "right": "Short twinax links between ToR switch and server NIC"}, {"left": "Plenum-rated jacket", "right": "Cable runs through air-handling spaces meeting fire code"}, {"left": "Shielded twisted pair (STP)", "right": "High-EMI areas near industrial motors or RF sources"}]}, {"id": "C1N-I-021", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.1", "type": "match", "difficulty": "easy", "question": "A new technician is staging a workstation and a switch patch and keeps reaching for the wrong lead. Match each connector or interface to the device class it most often serves.", "explanation": "Technicians must map physical connectors quickly: RJ45 for copper Ethernet, USB-C PD for modern laptops, SATA for internal drives, LC for fiber, and Molex/SATA power for DC feeds. Mis-identifying these slows rack work and causes bent pins.", "video_reference": null, "notes_reference": "03_Cables_Connectors_Peripherals.md", "tags": ["connectors", "peripherals"], "pairs": [{"left": "RJ45", "right": "Twisted-pair Ethernet network drop"}, {"left": "USB-C with PD", "right": "Laptop charging and docking data/video"}, {"left": "SATA data connector", "right": "Internal HDD/SSD attachment to motherboard"}, {"left": "LC duplex", "right": "Fiber patch to switch or transceiver"}, {"left": "Molex / SATA power", "right": "Drive and peripheral DC power from PSU"}]}, {"id": "C1N-I-022", "exam": "core1", "domain": "3.0 Hardware", "objective": "3.8", "type": "match", "difficulty": "medium", "question": "Match each printer technology to the maintenance item a technician most often services.", "explanation": "Laser systems center on toner and fusers, inkjets on ink and head cleaning, thermal printers on special paper and head care, and impact printers on ribbons and tractor feeds. Knowing the consumable map avoids wrong-part truck rolls.", "video_reference": null, "notes_reference": "16_Printers.md", "tags": ["printers", "maintenance"], "pairs": [{"left": "Laser printer", "right": "Toner cartridge and fuser kit replacement"}, {"left": "Inkjet printer", "right": "Ink cartridges and printhead cleaning cycles"}, {"left": "Thermal receipt printer", "right": "Heat-sensitive paper rolls and printhead care"}, {"left": "Impact / dot-matrix", "right": "Ribbon cartridge and tractor-feed alignment"}]}, {"id": "C1N-I-023", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "match", "difficulty": "medium", "question": "Finance wants to know who patches what before signing the hosting contract. Match each cloud service model to the layer the customer is still responsible for managing.", "explanation": "IaaS still leaves OS and apps to the customer, PaaS shifts the runtime to the provider, SaaS delivers the app itself, and shared responsibility always leaves identity and data controls with the customer. These distinctions drive who patches what.", "video_reference": null, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "paas", "saas"], "pairs": [{"left": "IaaS", "right": "Customer manages OS, middleware, and applications on rented VMs"}, {"left": "PaaS", "right": "Customer deploys apps/code while provider manages runtime platform"}, {"left": "SaaS", "right": "Customer uses the application; provider runs the full stack"}, {"left": "Shared responsibility (general)", "right": "Provider secures cloud; customer secures data and access in cloud"}]}, {"id": "C1N-I-024", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "match", "difficulty": "hard", "question": "A batch of workstations came back from a remote site with assorted boot faults and you are triaging them on the bench. Match each motherboard symptom to its most likely hardware cause.", "explanation": "Symptom-to-cause matching is core hardware troubleshooting: silent no-POST points early CPU/power issues, video-only failures implicate the GPU path, memory beeps implicate DIMMs, rapid thermal trips implicate cooling, and settings loss implicates CMOS/NVRAM.", "video_reference": null, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["motherboard", "post", "troubleshooting"], "pairs": [{"left": "No POST, CPU fan spins, no beep codes on speaker-equipped board", "right": "CPU/power delivery or fatal early initialization fault"}, {"left": "POST completes but no local video on a discrete GPU system", "right": "GPU seating, GPU power cables, or display cable path"}, {"left": "Continuous memory beep pattern after a RAM upgrade", "right": "Incompatible or improperly seated DIMMs"}, {"left": "Boots then thermal shutdown under load within minutes", "right": "Cooler mount failure, dried thermal paste, or blocked airflow"}, {"left": "Clock / boot order resets every cold start", "right": "Dead CMOS battery or corrupted UEFI NVRAM settings"}]}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A technician picks up a trouble ticket for a rack server that failed overnight. Following the CompTIA troubleshooting methodology, which action belongs to the very first step after the ticket is opened?", "explanation": "Step one of the CompTIA methodology is to identify the problem: gather information from the people who were present, interrogate logs and monitoring, and form a factual picture before theorizing. Questioning the overnight staff and reading the system logs is exactly that step. Backing up configuration is a change-control safeguard, not the first troubleshooting step. Swapping the most recently changed component skips straight to a fix without a tested theory, which is guessing. Vendor escalation comes after internal diagnosis or when the fault is contractually theirs to fix.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["methodology", "troubleshooting", "best-practices"], "options": ["Interview the overnight staff and review the logs to identify the problem", "Replace the most recently changed component, since it probably failed", "Escalate to the hardware vendor support line immediately", "Back up the server configuration before touching the hardware"], "answer": 0, "distractor_analysis": {"3": "Configuration backups are good change-management hygiene, but they do not identify the fault; that is a pre-change safeguard, not step one.", "1": "Jumping to part replacement without a tested theory violates the methodology; the newest change is a lead worth investigating, not a diagnosis.", "2": "Escalation belongs later in the process, once the problem is identified and internal fixes are exhausted or out of scope."}, "id": "C1N-T-001"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "hard", "question": "A technician is racking a freshly built workstation and hears one long beep followed by two short beeps on an AMI BIOS when it first powers on. The screen never initializes. Which subsystem should the technician inspect first?", "explanation": "On AMI BIOS, one long beep followed by two short beeps is the classic memory-failure POST code: reseat the modules, test them one at a time, and verify they are on the board's qualified-vendor list. Beep codes fire during POST, long before the operating system loads, so the boot drive cannot be the trigger. A PSU rail collapse usually gives no POST at all or a different vendor-specific pattern, and a PXE or NIC fault does not produce this signature.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["post", "beep-codes", "memory", "bios"], "options": ["The network card, because PXE boot failures trigger beep codes", "The power supply, because a single long beep indicates a PSU rail failure", "The RAM seating and compatibility, because this pattern points to a memory failure", "The boot drive, because beeps during POST mean the OS loader is missing"], "answer": 0, "distractor_analysis": {"0": "AMI documents this pattern as a memory error; power rail faults typically give no beeps or a different code entirely.", "2": "Beep codes are emitted during POST, long before the OS loader runs, so the drive is not involved.", "3": "Network boot problems do not raise this beep pattern on AMI boards."}, "id": "C1N-T-002"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A user reports their workstation loses BIOS settings, boots to a wrong date, and shows a CMOS checksum error after every power-down. The machine otherwise runs fine all day. What should the technician do first?", "explanation": "Settings surviving while powered but vanishing after shutdown, plus a clock reset and a checksum complaint, is the textbook weak CMOS battery. The cell only has to hold NVRAM while mains power is off, which matches the symptom pattern exactly. A firmware flash risks bricking the board and does nothing for a cell that can no longer hold a charge. This is not NVRAM silicon failure, because the settings persist fine during runtime. Secure boot has no role in retaining BIOS settings.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["cmos", "bios", "motherboard"], "options": ["RMA the motherboard, since NVRAM is failing", "Disable secure boot so the UEFI can rewrite its settings", "Flash the BIOS to the latest firmware to clear the corruption", "Replace the CMOS battery and re-enter the settings"], "answer": 1, "distractor_analysis": {"1": "Flashing firmware rewrites flash storage, but a dying coin cell cannot hold settings while power is off regardless of the firmware version.", "3": "NVRAM silicon failure would corrupt settings while the machine is running too, not only after power loss.", "0": "Secure boot governs boot trust, not whether settings persist across a power-down."}, "id": "C1N-T-003"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A technician finds a 2U server in rack B12 that powers on but never completes POST, with no beeps and no video. The same server worked yesterday. Following the methodology, which theory should be tested first because it is the cheapest to check?", "explanation": "No POST with no beeps, after a working period, is most often memory: reseat, then test modules singly to confirm quickly and cheaply. A dead CPU is possible but rare and expensive to assume first, and the methodology says test the cheapest, most probable theory first. A RAID controller fault rarely halts POST before video init, and the machine would usually still reach POST and show a controller error. Dirty power that lets fans and lights come up only to hang silently at the same point every time is inconsistent with PDU behavior.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["post", "memory", "methodology"], "options": ["A RAM module has unseated or failed, so reseat and swap modules one at a time", "The RAID controller has corrupted the boot volume", "The rack PDU is providing dirty power and needs a meter test", "The CPU is fried and must be replaced"], "answer": 2, "distractor_analysis": {"2": "CPU failures are statistically much rarer than seating or module faults and cost far more to test; try the cheap theory first.", "0": "Storage controller faults rarely halt POST before video init; the machine would typically still complete POST and report a controller error.", "1": "Unusable PDU power would prevent power-on entirely or cause erratic behavior, not a consistent silent hang at the same point."}, "id": "C1N-T-004"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "easy", "question": "A technician in a datacenter needs to confirm whether a server's power supply is actually delivering clean +12V and +5V rails under load. Which tool and procedure should be used?", "explanation": "Rails are verified by measuring the 24-pin ATX connector with a multimeter or a dedicated PSU tester under load: +12V, +5V, and +3.3V should each hold within roughly five percent of nominal. The wall outlet only tells you mains input, not what the PSU delivers. A POST card reports boot progress codes, not rail health. The wrist strap is a static-safety control, not a measurement instrument, and BIOS sensor pages are a software approximation of what a meter reads directly.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["psu", "multimeter", "power"], "options": ["A multimeter set to AC volts, probing the wall outlet", "A PSU tester or multimeter probing the 24-pin connector rails for stable voltage", "A POST diagnostic card that displays hexadecimal POST codes", "An ESD wrist strap connected to the chassis while reading BIOS sensor pages"], "answer": 3, "distractor_analysis": {"3": "Measuring the wall outlet checks mains supply, not the PSU output rails that actually power the board.", "1": "A POST card shows boot stage codes, not power rail voltages.", "2": "A wrist strap prevents ESD damage; it measures nothing, and BIOS telemetry is not a substitute for probing rails."}, "id": "C1N-T-005"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "order", "difficulty": "medium", "question": "A technician is mentoring a new hire on the help desk and quizzes them on the CompTIA troubleshooting process before they touch live tickets. Arrange the six steps of the methodology in their official order.", "explanation": "The methodology runs from evidence to closure. You cannot theorize before you have identified the problem from users and logs, so information gathering comes first. The theory of probable cause must exist before it can be tested, and testing must confirm the cause before you plan a fix. Implementing the fix comes before verification, because you cannot verify what you have not changed, and preventive measures make sense only once functionality is restored. Documentation is last so the record covers the findings, the fix, and the outcome, giving the next technician a complete trail.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["methodology", "troubleshooting", "procedure"], "sequence": ["Identify the problem by questioning users and reviewing logs and documentation", "Establish a theory of probable cause", "Test the theory to determine the actual cause", "Establish a plan of action to resolve the problem and implement the solution", "Verify full system functionality and implement preventive measures", "Document findings, actions, and outcomes"], "id": "C1N-T-006"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A technician replaces a failed drive in a storage server with an identical model, but the controller still reports the new drive as absent. Seating has been visually confirmed. Which step resolves this when the swap itself was correct?", "explanation": "When a correctly seated drive is still invisible, the fault lies in the path between it and the controller: the carrier, backplane connector, cabling, or the port itself. Cleaning and reseating, then trying a known-good port, isolates a backplane or port fault cheaply. Formatting a drive cannot happen until the controller can see it, so that reasoning is backwards. The OS has no role in low-level drive enumeration on a controller, and an identical model drive draws the same power as the unit it replaced.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["drives", "backplane", "hardware"], "options": ["Reinstall the operating system so Plug and Play can discover the new device", "Upgrade the PSU, because replacement drives draw more power than originals", "Clean and reconnect the drive carrier or backplane connector, or move the drive to a known-good port to isolate a failed port", "Format the drive first, because the controller will not enumerate a blank disk"], "answer": 0, "distractor_analysis": {"2": "Formatting requires the drive to be enumerated first, so it cannot fix an enumeration problem.", "3": "The OS discovers hardware through the controller; reinstalling it does not repair a backplane or port fault.", "0": "An identical replacement drive has the same power draw as the failed unit, so the PSU is not the differentiator."}, "id": "C1N-T-007"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A user reports that a USB headset drops out intermittently when plugged into their docking station. The ticket notes the headset works flawlessly when plugged directly into the laptop. Which theory fits the evidence best?", "explanation": "The headset works when directly attached, so the variable is the dock: its upstream controller, firmware, or the physical port is flaky, and firmware updates plus a port swap are the fix path. Driver updates address the laptop side, which is proven good by the direct test. USB 3.x ports are backwards compatible with USB 2.0 devices by design, so that theory contradicts the standard. A degraded laptop audio board would fail in both scenarios, not just through the dock.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["usb", "docking-station", "peripherals"], "options": ["The user needs a USB 2.0 cable, because USB 3.2 ports are not backwards compatible", "The laptop's audio subsystem is degraded and needs a board replacement", "The headset drivers need updating on the laptop", "The dock's USB controller or firmware is faulty, or the dock port is failing"], "answer": 1, "distractor_analysis": {"1": "The direct-connection test proves the laptop side, including its drivers, works.", "3": "USB 3.x is backwards compatible with 2.0 devices by specification, so the port version is not the issue.", "0": "A failing laptop audio subsystem would fail on both paths, not only via the dock."}, "id": "C1N-T-008"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "medium", "question": "A rack server reports a drive fault LED. The technician reseats the drive, but the LED stays amber and the management console still marks the drive failed. Per the troubleshooting methodology, which step follows a fix attempt that did not work?", "explanation": "When the first theory fails, the methodology says form and test the next most probable one. Swapping in a known-good drive cleanly splits the fault domain: if the replacement also faults, the carrier or backplane is the problem. Escalating before isolating skips your own cheap tests and wastes vendor time. A steady amber LED on a carrier is a fault indicator, not decoration, so closing the ticket leaves a degraded array running. Firmware updates mid-fault risk array stability and do not follow from a confirmed drive failure.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["methodology", "drives", "hardware"], "options": ["Test the next theory: swap in a known-good drive to isolate drive versus carrier or backplane", "Close the ticket, since the amber LED is only informational", "Update the server firmware in place, then power-cycle the entire rack", "Escalate immediately to vendor RMA support without further action"], "answer": 2, "distractor_analysis": {"2": "Escalating before isolating skips the cheap tests the methodology demands and wastes vendor time.", "0": "A steady amber LED on a drive carrier is a fault state; treating it as informational leaves a degraded array in service.", "1": "Firmware changes mid-incident risk destabilizing the array and are not indicated by a single confirmed dead drive."}, "id": "C1N-T-009"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.1", "type": "single", "difficulty": "hard", "question": "A user reports that their newly assembled desktop powers on and the fans spin, but the screen never displays anything and there are no beep codes. A technician has already verified the monitor and video cable work on another machine. What should be checked next?", "explanation": "A fully assembled board with no video and no beeps is a classic no-memory condition: many modern boards stay silent rather than beep when no DIMM is detected, so reseat the modules and test them individually. Keyboards are not required for POST on any mainstream board. POST completes before the OS is ever read, so a blank drive yields a missing-bootloader message later, not silence now. A defective power button would prevent power-on entirely rather than allowing fans to spin with a silent POST.", "video_reference": {"title": "Troubleshooting Hardware - CompTIA A+ 220-1201 - 5.1", "url": "https://www.youtube.com/watch?v=HgeURynWn_w", "duration": "25:15", "objective": "5.1"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["post", "memory", "troubleshooting"], "options": ["Whether the case power button is defective and sending the wrong signal", "Whether the RAM is unseated or a module is dead, since a missing memory population can produce no video and no beeps", "Whether the keyboard and mouse are connected, as some boards refuse to POST without them", "Whether the hard drive is blank, because POST cannot proceed without an OS"], "answer": 3, "distractor_analysis": {"1": "Boards POST happily without input devices attached.", "2": "POST runs before any OS loading; a blank drive gives a missing-bootloader message after POST, not silence during it.", "3": "A faulty power button stops power-on, not POST; the machine is clearly powering up."}, "id": "C1N-T-010"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "hard", "question": "A user reports that the NVMe boot drive on their workstation intermittently drops from the OS with I/O errors in the event log, while a technician confirms a SATA drive in the same chassis stays solid. Which action best isolates an NVMe-specific fault?", "explanation": "Intermittent NVMe dropout with SATA unaffected points at the NVMe link itself: controller or drive firmware bugs and poor M.2 seating or thermal throttling from bad heatsink contact are the common causes, so update firmware and verify the module is seated and cooled. Scanning the healthy SATA drive wastes time on the wrong device. Swapping the SATA drive contradicts which drive is actually erroring. Moving a boot NVMe to a USB enclosure is a downgrade that masks the fault rather than fixing the internal link.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["nvme", "storage", "firmware"], "options": ["Move the NVMe drive into a USB enclosure so it stops using the M.2 slot", "Run a full surface scan of the SATA drive to compare error patterns", "Update the NVMe controller firmware and check M.2 seating and heatsink contact", "Replace the SATA drive, since it is the older interface and probably the culprit"], "answer": 0, "distractor_analysis": {"0": "The SATA drive is not reporting errors; scanning it does nothing to isolate the NVMe fault.", "2": "The erroring device is the NVMe drive, not the SATA one; replacing the wrong drive wastes budget and leaves the fault in place.", "3": "A USB enclosure sidesteps the M.2 link instead of repairing it and cripples boot drive performance."}, "id": "C1N-T-011"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "easy", "question": "A technician reviewing a storage server finds a three-drive RAID 5 array with one disk failed and one disk currently rebuilding, and asks whether the volume is at risk right now. What is the correct assessment?", "explanation": "RAID 5 tolerates exactly one drive failure. With one disk failed and another mid-rebuild, the array is running on degraded parity with zero spare tolerance until the rebuild finishes: any second failure during that window is fatal, and the heavy rebuild I/O actually raises the odds of a survivor failing. Two-drive tolerance describes RAID 6, not RAID 5. Rebuilds on spinning disks run for hours, not moments, and pulling a member mid-rebuild destroys the array.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["raid", "raid-5", "rebuild"], "options": ["RAID 5 rebuilds are instant, so the risk window is negligible", "The rebuilding drive can be pulled and reused in another server while the rebuild runs", "The array is safe, because RAID 5 survives two simultaneous drive failures", "Until the rebuild completes, the array has no spare redundancy, so a second failure loses the volume"], "answer": 1, "distractor_analysis": {"1": "Two-drive tolerance belongs to RAID 6; RAID 5 survives exactly one failure.", "3": "RAID 5 rebuilds run for hours under heavy read stress, so the risk window is real and dangerous.", "0": "Removing a member mid-rebuild destroys the array; drives in an active set are never repurposed."}, "id": "C1N-T-012"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "order", "difficulty": "hard", "question": "A technician has a replacement drive in hand for a degraded RAID 5 volume and must follow a safe rebuild procedure during the maintenance window. Arrange the steps into the safest order.", "explanation": "Safe RAID work starts by confirming exactly which slot and array you are touching, because pulling the wrong drive in a degraded array kills the volume outright. Before touching hardware, confirm a current backup exists so a rebuild gone wrong is still recoverable. Then physically insert the replacement, watch the controller pick it up and begin rebuilding, and only after the array returns to optimal state document the event. Skipping the verification or backup steps turns a routine swap into a potential data-loss incident, and closing out without documentation leaves the next on-call technician blind.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["raid", "raid-5", "rebuild", "procedure"], "sequence": ["Verify the array state and drive slot mapping in the controller software", "Back up critical data or confirm a current backup exists", "Insert the replacement drive into the failed drive's slot", "Confirm the controller starts the rebuild and monitor its progress", "Verify the volume is healthy again and document the event"], "id": "C1N-T-013"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A user reports a hard drive making a rhythmic clicking or grinding sound before the system failed to boot this morning. What does this symptom most strongly indicate, and what is the appropriate response?", "explanation": "Rhythmic clicking or grinding is the head actuator failing to find tracking, the classic sign of imminent mechanical death: continued power accelerates platter and head damage, so shut the machine down and restore from backup or image the drive immediately. Defragmenting a dying drive hammers it with I/O and speeds the failure. chkdsk repairs logical structures, not a failing actuator, and running it risks finishing the drive off. Cables never produce mechanical noise; the sound comes from inside the sealed drive assembly.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["hdd", "mechanical-failure", "data-recovery"], "options": ["Mechanical failure of the drive, so power it down and recover from backup or a drive image", "A corrupted filesystem that a chkdsk run will repair", "A loose SATA cable causing the noise, so reseat the cable", "High fragmentation that a defragment pass will resolve"], "answer": 2, "distractor_analysis": {"2": "Defragmenting a mechanically failing drive multiplies head movement and hastens its death.", "0": "chkdsk fixes filesystem corruption, not a physically failing actuator; running it on dying hardware risks total loss.", "1": "Cable faults cause detection and I/O errors, never rhythmic mechanical noise from inside the drive."}, "id": "C1N-T-014"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "hard", "question": "A user reports that a workstation with an SSD boots slowly and file copies off the SSD stall for seconds at a time. A technician pulls SMART data showing drive health at 95 percent with zero reallocated sectors. Which explanation fits best?", "explanation": "Healthy SMART data with stalled writes on an SSD is the near-full or TRIM-starved pattern: without free blocks and TRIM commands, garbage collection stalls writes for seconds at a time. Freeing space and confirming the OS issues TRIM restores speed. Ninety-five percent health with zero reallocated sectors does not justify replacement. A negotiated-down link shows as a fixed reduced link speed in controller logs, not intermittent stalls alongside healthy attributes. Moving the pagefile is folklore that shrinks usable fast storage and does nothing for garbage collection.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["ssd", "trim", "performance"], "options": ["The SSD is failing and must be replaced immediately", "The drive is nearly full or TRIM is disabled, throttling garbage collection and write performance", "The SATA link negotiated down to 1.5 Gb/s and the cable needs replacing", "The pagefile must be moved to a spinning drive to relieve the SSD"], "answer": 3, "distractor_analysis": {"3": "95 percent health and zero reallocated sectors contradicts imminent failure; replacement wastes money.", "1": "A negotiated-down link gives a constant slow link speed in the logs, not intermittent multi-second stalls with healthy SMART data.", "2": "Moving the pagefile off the SSD does not fix garbage-collection stalls and wastes the fastest storage in the machine."}, "id": "C1N-T-015"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A technician sees that a storage server's SMART monitoring has flagged a rising reallocated sector count on a drive that holds one member of a RAID 1 mirror. What should the technician do about this drive?", "explanation": "Rising reallocated sectors are a leading indicator of drive failure: schedule a proactive swap during the maintenance window and let the mirror rebuild, which is low-risk while redundancy is intact. Waiting for outright failure gambles the mirror on a second failure window. Silencing SMART hides the exact early warning the monitoring exists to provide. Breaking the mirror removes redundancy entirely, converting a warning into exposure.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["smart", "raid-1", "storage"], "options": ["Break the mirror and run the drive solo to avoid resync overhead", "Wait for the drive to fail outright, because the mirror protects the data anyway", "Replace the drive proactively in the next maintenance window and let the mirror resync", "Disable SMART alerts for that drive so the noise stops"], "answer": 0, "distractor_analysis": {"0": "Waiting for hard failure opens a needless window where a second fault loses the volume.", "2": "Muting the alert hides the early-warning signal that SMART monitoring exists to surface.", "3": "Dissolving the mirror trades away redundancy, which is the opposite of a safe response."}, "id": "C1N-T-016"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A technician replaced a failed drive in a RAID 10 array and the controller is rebuilding. Users complain the array feels slower than usual this afternoon. What explains this, and what should be communicated?", "explanation": "A RAID 10 rebuild generates heavy background reads and writes that share spindles and controller bandwidth with production traffic, so slower response during the rebuild is expected and resolves when it completes; communicate the window rather than escalating. The array is not failing: rebuilding is the normal, healthy state after a member swap. Re-initialization would destroy the data for no reason. RAID 10 rebuilds are faster than parity rebuilds but still measurably intrusive.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["raid", "raid-10", "rebuild", "performance"], "options": ["The controller cached the wrong stripe set and needs a full re-initialization", "The users are mistaken, because RAID 10 rebuilds are too fast to notice", "The array is failing and data is at risk, so failover immediately", "Rebuild I/O competes with user traffic, so degraded performance is expected until the rebuild completes"], "answer": 1, "distractor_analysis": {"1": "Rebuilding is the expected post-replacement state, not a sign of array failure.", "3": "Re-initializing wipes the array; nothing about a rebuild corrupts the stripe set.", "0": "Even RAID 10 rebuilds consume I/O for a noticeable period, so the users' reports are legitimate."}, "id": "C1N-T-017"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "multi", "difficulty": "hard", "question": "A technician needs to distinguish between a failing drive and a failing SATA data path back to the controller. Which two checks best split the problem between the drive and the path? (Select TWO.)", "explanation": "Isolation requires varying one side of the path at a time: SMART counters interrogate the drive itself for reallocating sectors and read retries, while moving the drive to a known-good cable and port tests the path. Together they attribute the fault cleanly to drive or link. Defragmentation stresses a possibly failing drive without diagnosing anything. Power supply wattage has no bearing on SATA link integrity. An OS reinstall destroys evidence and is irrelevant to a physical link or drive fault.", "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "06_Storage_and_RAID.md", "tags": ["sata", "smart", "isolation"], "options": ["Run the drive vendor's SMART test and review the error counters", "Defragment the drive while listening for changes in the noise", "Move the suspect drive to a known-good cable and port, then recheck", "Swap the workstation's PSU for a higher wattage unit", "Reinstall the operating system on the same cable and port"], "answers": [0, 2], "distractor_analysis": {"1": "Defragmentation adds I/O stress without isolating drive from path, and it can accelerate a mechanical failure.", "3": "PSU wattage has no bearing on SATA link errors or SMART counters.", "4": "Reinstalling the OS destroys evidence and does nothing to test a physical cable, port, or drive fault."}, "id": "C1N-T-018"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A user reports that their workstation displays fine on a directly attached monitor, but a second monitor at the end of a long VGA run shows ghosting and faint duplicate images. Which cause fits best?", "explanation": "Ghosting and faint duplicates are the signature of analog VGA degradation: long or poorly shielded runs smear and reflect the signal, so shorten the run, use better shielded cable, or move to HDMI or DisplayPort. GPU memory faults corrupt textures and crash drivers; they do not cleanly duplicate whole frames. A weak monitor PSU shows flicker, dimming, or shutdown, not image duplication. Panel driver boards fail with dead rows or a blank screen, not ghost shadows.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["vga", "signal-degradation", "display"], "options": ["Analog signal degradation over the cable run, needing a shorter or better shielded cable or a digital connection", "The monitor's power supply capacitors aging and sagging under load", "A failing panel driver board needing replacement", "Failing GPU video memory producing doubled frames"], "answer": 2, "distractor_analysis": {"2": "Video memory faults show as texture corruption, artifacts, or driver crashes, not clean duplicated images.", "0": "Aging monitor power causes flicker, dimming, or power-off symptoms, not ghost images.", "1": "Panel driver failure produces lines, dead zones, or a dead screen, not faint duplicate images."}, "id": "C1N-T-019"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "easy", "question": "A user's laptop panel is very dim, but a faint image is visible when the technician shines a flashlight at it. The external video output drives a monitor perfectly. Which component is the prime suspect?", "explanation": "A faint image visible under strong light with a working external output means the panel is rendering but the backlight is dead or unpowered: suspect the backlight itself, the inverter or LED driver circuit, or the lid-close sensor. The GPU is proven good by the perfect external output. The battery powers the whole machine, not the backlight specifically. The panel cable carries the image, which is demonstrably arriving, so the missing element is light, not signal.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["backlight", "laptop", "display"], "options": ["The GPU, because it drives both outputs", "The backlight or its power circuitry, since the panel is clearly producing an image", "The laptop battery, because panels run on battery power", "The video cable between the mainboard and the panel, because it carries the image"], "answer": 3, "distractor_analysis": {"3": "The external output working proves the GPU renders correctly.", "1": "The battery powers the entire laptop; selective dimness is not a battery symptom.", "2": "The panel cable carries image data, which is arriving; the fault is in generating light."}, "id": "C1N-T-020"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "hard", "question": "A technician sees horizontal colored streaks and snow-like artifacts on a workstation, and the same corruption appears on the BIOS splash screen as well as in the operating system. Which fault does this pattern most strongly indicate?", "explanation": "Artifacts visible in the BIOS environment are generated before any OS driver loads, so the corruption comes from hardware: the GPU core or its video memory. A driver reinstall cannot affect pre-OS rendering. Digital cables like HDMI or DisplayPort fail as blank screens or sparkles from dropped packets, not colored streaks on firmware screens. Monitors do not carry field-updatable firmware that would distort colors in a GPU-tied pattern.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["gpu", "artifacts", "display"], "options": ["Out-of-date monitor firmware causing color distortion", "A software graphics driver bug that a clean driver install will fix", "A GPU or video memory hardware fault, because the corruption exists before the OS loads", "A failing display cable, because analog interference causes snow"], "answer": 0, "distractor_analysis": {"0": "Driver problems only manifest after the OS loads its driver; BIOS screens bypass it entirely.", "2": "Digital link faults show sparkles, dropouts, or blank screens, not consistent streaks on firmware screens.", "3": "Monitor firmware does not selectively distort color in a pattern tied to GPU output."}, "id": "C1N-T-021"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "easy", "question": "A user reports that after a routine driver update, their dual-monitor workstation suddenly shows the desktop only on the primary display, though both monitors power on. Which setting should a technician check first?", "explanation": "Driver updates commonly reset display configuration, dropping the system back to single-display or duplicated mode, so open display settings and restore Extend. Scaling affects text and icon size, not whether a display activates. Refresh rate mismatches cause blank or flickering secondary screens, not a working single-desktop layout. Power plans manage sleep and battery behavior, not monitor topology.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["drivers", "multi-monitor", "display"], "options": ["The refresh rate on the secondary monitor, to ensure it is set to 60 Hz", "The power plan, which may disable secondary displays on battery", "The display scaling percentage on the primary monitor", "The multi-monitor mode, which may have reverted to single-display after the update"], "answer": 1, "distractor_analysis": {"1": "Scaling governs text and icon size and does not disable a display.", "3": "An unsupported refresh rate blanks or flickers a monitor; it does not collapse the desktop to one screen.", "0": "Power plans control sleep and energy states, not monitor topology."}, "id": "C1N-T-022"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A user reports a new monitor randomly drops signal for two seconds and then returns. The technician confirms the on-screen display menu works even during the blackout. Which action best isolates whether the fault is the source, the cable, or the panel?", "explanation": "The on-screen display working during blackouts proves the panel and its power are fine, leaving source or cable as suspects: swapping the cable is the cheapest test, then feeding the input from a different source splits cable from source faults. Replacing the monitor ignores the two cheaper suspects. Resolution does not cause thermal dropouts, and HDCP renegotiation happens at stream start rather than randomly mid-stream.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["cables", "isolation", "display"], "options": ["Swap in a known-good video cable first, then test a different source on the same input", "Replace the monitor, because intermittent dropouts indicate panel failure", "Lower the resolution, because high resolutions overheat the scaler", "Disable HDCP, because encryption renegotiation causes blackouts"], "answer": 2, "distractor_analysis": {"0": "A working on-screen display during blackout proves the panel and its power supply are healthy, so replacing the monitor skips cheaper tests.", "1": "Lowering resolution is not a fix for intermittent signal loss; scalers do not overheat and drop out this way.", "2": "HDCP handshakes occur at connection establishment, not randomly during playback."}, "id": "C1N-T-023"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "easy", "question": "A trainer reports that the projector mounted high in a training room shows a noticeably keystoned, trapezoid-shaped image. Which adjustment should the technician try first?", "explanation": "A keystoned trapezoid means the projector axis is off-angle to the screen: physically re-aiming the unit is ideal, and keystone correction digitally squares the image when the mount cannot be changed. Aspect ratio governs width versus height proportions, not corner angles. Lamp brightness affects luminance, never geometry. Overscan crops image edges for television viewing and has no projection geometry function.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["projector", "keystone", "display"], "options": ["Set the projector's aspect ratio to 16:9", "Use keystone correction to square the image to the screen", "Increase the lamp brightness to compensate", "Enable overscan on the source device"], "answer": 3, "distractor_analysis": {"3": "Aspect ratio settings change proportional scaling, not corner geometry.", "1": "Brightness changes luminance and cannot alter image shape.", "2": "Overscan crops the image edges; it has no geometry correction function."}, "id": "C1N-T-024"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "match", "difficulty": "hard", "question": "A technician is building a fault-isolation cheat sheet for the display chain and wants each artifact mapped to the layer that produces it. Match each symptom to its most likely failing component.", "explanation": "Each artifact points to one layer of the video chain. A faint image under a flashlight means the panel renders but emits no light, which is a dead backlight or inverter. Sparkles and white flecks are dropped packets on a marginal digital HDMI or DisplayPort link. Whole-image ghosting is analog VGA reflection and crosstalk on a long or poorly shielded run. Colored streaks visible on BIOS screens, before any driver loads, come from failing GPU or video memory, since firmware screens bypass the entire software stack.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["display", "artifacts", "diagnosis"], "pairs": [{"left": "Faint image only visible under a flashlight", "right": "Failed backlight or inverter"}, {"left": "Sparkles and white flecks on a digital link", "right": "Degraded HDMI or DisplayPort cable"}, {"left": "Whole-image ghosting on a VGA run", "right": "Analog signal degradation on a long cable"}, {"left": "Colored streaks visible in BIOS screens", "right": "Failing GPU or video memory"}], "id": "C1N-T-025"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "multi", "difficulty": "hard", "question": "A user at a monitoring station reports that the display shows a burn-in ghost of the static dashboard taskbar after months of continuous use, and asks what can honestly be done about it. Which two responses from a technician are technically sound? (Select TWO.)", "explanation": "Burn-in mitigation on modern panels is real: manufacturer pixel-refresh cycles actively compensate worn cells, and full-screen slowly changing content spreads wear evenly across the panel instead of etching one static region. Raising brightness drives harder wear and deepens the damage. Relocating the static element merely moves the burn pattern to a new location. Burn-in is a panel-layer wear phenomenon, not a backlight defect, so backlight replacement cannot help.", "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["burn-in", "display", "oled"], "options": ["Increase brightness to push stuck pixels back into alignment", "Run built-in pixel refresh or compensation cycles if the monitor offers them", "Freeze the taskbar on the right side to redistribute the wear", "Display full-screen slowly changing content to wear the panel evenly", "Replace the backlight, since burn-in is a backlight defect"], "answers": [1, 3], "distractor_analysis": {"0": "Higher brightness accelerates cell wear and deepens burn-in rather than clearing it.", "2": "Moving the static element only relocates the burn pattern; it does not reduce total wear.", "4": "Burn-in is uneven cell wear in the panel layer itself, not a backlight fault."}, "id": "C1N-T-026"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A user reports that a phone has no cellular service at all: calls go straight to voicemail and SMS will not send. The user flew home this morning, the phone was fine before the flight, and Wi-Fi still works. Which setting should the technician check first?", "explanation": "Airplane mode kills the cellular radios, and a traveler can toggle Wi-Fi back on without ever disabling airplane mode, which matches a phone with working Wi-Fi and zero cellular service exactly. A suspended account blocks service continuously, not from one specific morning. A SIM PIN lock prompts for a code at boot rather than silently removing service. Baseband corruption is a stretch for a single flight and would not leave Wi-Fi untouched so cleanly.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "airplane-mode", "cellular"], "options": ["The SIM card locked with a PIN", "The baseband firmware corrupted by the flight's roaming handoff", "Airplane mode left enabled, since it silences the cellular radio while Wi-Fi can be re-enabled separately", "The carrier account suspended for nonpayment"], "answer": 0, "distractor_analysis": {"2": "A suspended account blocks service continuously and would not start precisely the morning of a flight.", "3": "A SIM PIN lock prompts for entry at startup; it does not silently strip service while Wi-Fi works.", "0": "Baseband corruption is rare and would not appear exactly after a flight with Wi-Fi unaffected."}, "id": "C1N-T-027"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A user reports that a tablet's touchscreen registers every touch about two centimeters to the left of where the user actually presses, in every application. What does this symptom indicate?", "explanation": "A consistent spatial offset across all apps is a digitizer problem: the touch-sensing layer is misregistering coordinates, so try recalibration where the platform supports it and otherwise replace the digitizer. An OS update does not fix hardware coordinate drift. A swollen battery manifests as panel lift or pressure blotches, not a uniform offset. The GPU renders the image, and the rendered UI is exactly where the user expects it; input coordinates are the digitizer's job.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["digitizer", "mobile", "touchscreen"], "options": ["A swollen battery pushing on the panel from behind", "A GPU fault offsetting the rendered interface", "A software calibration issue that an OS update will resolve", "A failing digitizer, which needs recalibration where supported or replacement"], "answer": 1, "distractor_analysis": {"1": "Coordinate offsets come from the touch-sensing layer, not the OS interface stack.", "3": "A swollen battery lifts or distorts the panel; it does not shift touch coordinates uniformly.", "0": "The GPU renders output; the render is correctly placed, and touch registration is the digitizer's domain."}, "id": "C1N-T-028"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "easy", "question": "During a phone repair, a technician notices the battery has swollen and the case back has separated slightly from the frame. What is the correct course of action?", "explanation": "A swollen lithium battery is a fire hazard: remove it promptly without puncturing it, tape the terminals, hand it to an e-waste or hazardous-waste facility, and fit a new pack. Pressing it flat risks rupturing the pouch and triggering thermal runaway. Deliberately draining a swollen cell adds charge-discharge stress, which is exactly the abuse that caused the swelling. Returning the device keeps a fire hazard in service.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["battery", "safety", "mobile", "e-waste"], "options": ["Remove the battery carefully, dispose of it at a proper e-waste facility, and fit a replacement", "Fully discharge the battery first to reduce fire risk before removing it", "Return the phone to the user with a warning not to charge it overnight", "Press the battery flat and seal the case back together"], "answer": 2, "distractor_analysis": {"2": "Pressing a swollen cell can rupture the pouch and trigger thermal runaway.", "0": "Deliberately discharging a swollen cell stresses it further; removal should not wait.", "1": "Returning a device with a known fire-hazard battery leaves the hazard in circulation."}, "id": "C1N-T-029"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "easy", "question": "A user reports that a phone left on a car dashboard all afternoon will not power on and feels hot to the touch. Which sequence is safest for the technician to follow?", "explanation": "Thermal shutdown leaves a phone dead but recoverable: let it cool in shade first, then charge and boot. Force-restarting a hot device stresses silicon that has already thermally protected itself. Refrigerator cooling can condense moisture inside the sealed chassis, trading thermal shutdown for liquid damage. Charging a hot device adds heat to an already overheated battery and can push a stressed cell toward failure.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["overheating", "thermal", "mobile"], "options": ["Force a reboot immediately while the device is still hot to clear the lockup", "Move it to a cool shaded area, let it return to normal temperature, then attempt charging and power-on", "Place it in a refrigerator for 20 minutes to pull the temperature down fast", "Plug it in immediately and start charging to see if it responds"], "answer": 3, "distractor_analysis": {"3": "Forcing a reboot on an overheated device stresses silicon that has already thermally protected itself.", "1": "Rapid refrigeration risks condensation forming inside the device.", "2": "Charging while hot adds battery heat and is discouraged by every manufacturer."}, "id": "C1N-T-030"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "multi", "difficulty": "medium", "question": "A technician reports that their field phone keeps dropping Wi-Fi at the far end of a warehouse, while laptops in the same area hold their connection. Which two actions best address a phone-specific wireless complaint? (Select TWO.)", "explanation": "Only the phone struggles, so the fault is client-side: stale saved profiles cause repeated drops until forgotten and rejoined, and band settings or a case blocking the phone's smaller antennas can handicap it against laptops with bigger radios. Airplane mode toggles the cellular radios, not Wi-Fi association state. The access point is serving other clients fine, so replacing it is overkill. A 5 GHz-only SSID reduces range and would worsen edge-of-warehouse coverage.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "wi-fi", "troubleshooting"], "options": ["Forget and rejoin the network to clear a stale cached profile", "Enable airplane mode briefly to reset the cellular radio", "Verify the Wi-Fi frequency band and check for antenna or case interference", "Replace the warehouse access point with a higher-power model", "Move the user to a 5 GHz-only SSID, since 2.4 GHz is obsolete"], "answers": [0, 2], "distractor_analysis": {"1": "Airplane mode toggles the cellular radios; it does not clear a stale Wi-Fi profile.", "3": "Only the phone is affected, so the shared AP is demonstrably serving other clients fine.", "4": "5 GHz has shorter range than 2.4 GHz, so a 5 GHz-only SSID worsens coverage at the warehouse edge."}, "id": "C1N-T-031"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "multi", "difficulty": "medium", "question": "A user reports a phone battery that drops from 100 percent to 60 percent in an hour of standby with the screen off. Which two checks are the most diagnostic? (Select TWO.)", "explanation": "Rapid standby drain is either software or cell wear: the per-app battery report names a runaway process holding the CPU or radios awake, and heat or swelling alongside fast discharge points at a worn cell. Airplane mode is a diagnostic isolation step, not a solution, and it kills the phone's core function. Brightness affects active-use drain, not standby with the screen off. Charging cables have no role when the device drains unplugged.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["battery", "mobile", "diagnosis"], "options": ["Reduce screen brightness to minimum and retest", "Review battery usage by app in settings to find a runaway process", "Replace the charging cable, since cables cause standby drain", "Check for a swollen battery or heat while charging, indicating cell wear", "Turn on airplane mode permanently to stop all radio drain"], "answers": [1, 3], "distractor_analysis": {"0": "With the screen off in standby, brightness is not a factor.", "2": "The device drains while unplugged, so the charging cable cannot be contributing.", "4": "Airplane mode is a diagnostic toggle, not a fix; leaving it on disables the device's purpose."}, "id": "C1N-T-032"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "hard", "question": "A user reports that a phone that took a brief dunk in water now has no audio from the speaker, but a technician confirms headphones work and Bluetooth audio plays normally. Which component is most likely at fault?", "explanation": "Working headphone and Bluetooth audio proves the codec and the OS audio stack are fine, isolating the fault to the speaker itself or its flex connection, plausibly corroded by the water ingress. A codec fault would degrade every output path. A jack stuck in headphone-detection mode typically shows a headphone icon and mutes the speaker, but the water exposure points squarely at the speaker path, and the icon would be visible on screen. The OS audio service is disproven by the working alternate outputs.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "audio", "water-damage"], "options": ["The operating system's audio service, needing a reset", "The audio codec chip on the mainboard", "The speaker or its flex connection, isolated by the other outputs working", "The headphone jack detection circuit, stuck in headphone mode"], "answer": 0, "distractor_analysis": {"0": "A codec chip fault would break headphone and Bluetooth audio too.", "2": "A jack stuck in headphone mode displays a headphone icon on screen, which the scenario does not report.", "3": "The OS audio service is proven good by the working Bluetooth and headphone outputs."}, "id": "C1N-T-033"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "match", "difficulty": "medium", "question": "A technician is assembling a quick-reference sheet for the service desk covering common mobile device failures. Match each symptom to its most likely cause.", "explanation": "Each symptom maps to one failing subsystem. A touch registering at a fixed offset is digitizer misregistration or failure. A device refusing power after heat exposure is in thermal protection until it cools. A bulging case with a lifting screen is a swollen battery pushing the hardware apart. A silent speaker with working Bluetooth is a speaker or speaker-connection fault, isolated by the other outputs still working.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "diagnosis", "symptoms"], "pairs": [{"left": "Screen responds 2 cm left of every touch", "right": "Failing digitizer"}, {"left": "Device will not power on after a hot car afternoon", "right": "Thermal shutdown protection"}, {"left": "Case back is bulging and the screen is lifting", "right": "Swollen battery"}, {"left": "No audio from speaker but Bluetooth audio works", "right": "Faulty speaker or its connection"}], "id": "C1N-T-034"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "easy", "question": "A user's workstation cannot reach any network resource. The technician runs ipconfig and sees IPv4 address 169.254.10.7 with no default gateway. What does this address indicate?", "explanation": "169.254.x.x is the APIPA link-local range a Windows host self-assigns after the DHCP DORA exchange fails, and such addresses have no gateway and cannot reach other subnets. It is not a documented static, because statics are administratively assigned and route properly. Printers may sit on reserved subnets, but 169.254.0.0/16 is reserved by RFC 3927 specifically for link-local autoconfiguration. The range is not publicly routable at all.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["apipa", "dhcp", "ipconfig", "ipv4"], "options": ["A special subnet the organization reserves for network printers", "A public routable address that needs NAT configuration", "A statically assigned link-local address from the site's IP documentation", "A failed DHCP lease, so APIPA self-assigned a link-local address that cannot route off subnet"], "answer": 1, "distractor_analysis": {"1": "Static site addressing is administratively assigned and routes correctly; APIPA addresses never do.", "3": "169.254.0.0/16 is reserved for link-local autoconfiguration, not for printer subnets.", "0": "169.254.x.x is non-routable link-local space and can never appear as a public address."}, "id": "C1N-T-035"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A user can ping 8.8.8.8 successfully but no hostname resolves in any application. Which tool and command isolates the failing service?", "explanation": "Pinging a raw IP while hostnames fail isolates the fault to DNS: nslookup queries the configured resolver directly and shows whether it answers, times out, or returns the wrong record. tracert shows the Layer 3 path to an IP and never invokes name resolution. netstat lists sockets and connections on the local machine, not resolver health. Releasing the DHCP lease addresses the addressing layer, which the successful numeric ping proves is already working.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["dns", "nslookup", "troubleshooting"], "options": ["nslookup against the configured DNS server to test resolution directly", "tracert to 8.8.8.8 to see where name resolution stops along the path", "netstat -an to list the resolver's listening sockets", "ipconfig /release followed by /renew to obtain a fresh DHCP lease"], "answer": 2, "distractor_analysis": {"0": "tracert traces the routed path to an IP address; it does not query the DNS service.", "1": "netstat enumerates local connections and listeners; it does not probe DNS behavior.", "2": "DHCP renew changes addressing, which the working numeric ping shows is not the problem."}, "id": "C1N-T-036"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "hard", "question": "A technician is diagnosing a dead office network drop: a known-good laptop gets no link at the wall jack, and the patch panel labeling is out of date, so the far end of the run is unknown. Which tool identifies the correct run and reveals whether it is broken or simply mislabeled?", "explanation": "The toner probe is built for exactly this: the tone generator goes on the wall jack and the probe wand locates the matching wire on the patch panel, distinguishing a broken run from a mislabeled one and finding the right port. A cable tester validates pair continuity only once you have both ends in hand, which you do not yet. Crimping new ends is a guess that destroys the existing termination without locating the fault. Punching down the jack is re-termination, not identification.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["toner-probe", "cable-tester", "tools", "cabling"], "options": ["A punchdown tool, to reseat the jack pins in the wall plate", "A toner probe, to place a tone on the jack and find the matching run at the patch panel", "A cable tester, to verify pair continuity once both ends of the run are known", "A crimper, to reterminate both ends and hope for a good link"], "answer": 3, "distractor_analysis": {"1": "A tester validates pair continuity only once both ends are known and connected to the tester; it cannot find which panel port the jack maps to.", "2": "Crimping new ends is a blind guess that destroys the existing termination without locating the fault.", "3": "Punching down the jack re-terminates contacts; it does not locate or identify a run."}, "id": "C1N-T-037"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A technician is working a ticket for a host that cannot reach any resource by name or by IP and wants to follow the standard command-line workflow from the inside out. Which command sequence follows best practice?", "explanation": "The workflow runs from the inside out: ipconfig confirms addressing and the gateway, pinging the gateway tests local subnet reachability, nslookup tests DNS, and tracert shows where the path toward a remote IP breaks. Starting with tracert assumes reachability facts not yet established. Leading with name resolution assumes addressing is good when nothing confirms that. The loopback ping only proves the local TCP/IP stack is alive and tells you nothing about the network path.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["command-line", "methodology", "networking"], "options": ["nslookup first to prove DNS, then netstat, then release and renew the DHCP lease", "netstat first to inventory connections, then ping the loopback address 127.0.0.1", "ipconfig, then ping the default gateway, then nslookup a name, then tracert to a remote IP", "tracert first to find the broken hop, then ping the internet, then ipconfig last"], "answer": 0, "distractor_analysis": {"2": "Running tracert before establishing basic addressing and gateway reachability inverts the logical order.", "3": "Testing DNS first assumes IP connectivity that has not been confirmed yet.", "0": "Loopback only proves the local stack is running; it reveals nothing about the external path."}, "id": "C1N-T-038"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A warehouse supervisor reports that the Wi-Fi network was stable until a new wireless inventory system went live on the production floor, and now several handheld scanners drop their connections near aisle 3, the closest zone to the new hardware. Which cause is most probable?", "explanation": "The tight correlation with the new system going live points to radio interference: the new equipment transmits on or near the channel the scanners use, so survey the channels and move the AP or the interferer. Simultaneous multi-AP failure is implausible. Handset firmware would not degrade several devices in sync in one location. DHCP scopes are not physical-location aware, so exhaustion cannot affect a single aisle.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["wi-fi", "interference", "wireless"], "options": ["The access points have all failed and need replacement", "The handheld scanners need firmware updates to stay connected", "The DHCP scope is exhausted in the aisle 3 area", "The new system's radios interfere with the channel in use near that aisle"], "answer": 1, "distractor_analysis": {"3": "Multiple access points failing simultaneously is far less probable than co-channel interference from new equipment.", "0": "Firmware issues would not appear as geographically clustered drops exactly when new wireless gear went live.", "1": "DHCP scope exhaustion is global to the subnet and cannot be aisle-specific."}, "id": "C1N-T-039"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A technician finds a workstation with a known-good NIC that cannot get a link on one specific switch port, while the same patch cable and laptop link up immediately on the adjacent port. What should the technician conclude and do?", "explanation": "The same cable and laptop achieving link on the neighboring port isolates the fault to the specific port: check whether it is administratively down or err-disabled, re-enable it, and otherwise suspect hardware failure of that port. The NIC is proven good by the adjacent-port test. The cable is equally proven good by the same test. Recreating a VLAN is disruptive to the whole segment and irrelevant when the issue is one port's link state.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["switch-port", "isolation", "networking"], "options": ["The switch port is faulty or administratively shut down, so inspect its configuration and re-enable or replace it", "The laptop NIC drivers are outdated and need reinstalling", "The patch cable is bad and must be replaced", "The VLAN on the switch needs to be deleted and recreated"], "answer": 2, "distractor_analysis": {"0": "The laptop achieved link on the adjacent port, so its drivers and NIC are fine.", "1": "The same cable linked up on the next port over, so the cable is good.", "2": "Deleting and recreating a VLAN disrupts every port in it and has no bearing on a single port's link state."}, "id": "C1N-T-040"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "hard", "question": "A branch office lost internet connectivity during a storm. After power returned, the router, switch, and modem all boot and their link lights look normal, but no client receives a valid address. Which failure scenario best fits?", "explanation": "All local infrastructure booting with normal link lights while clients get no addresses points upstream: the ISP's DHCP or provisioning service did not survive the storm, so the WAN lease never arrives and clients end up with APIPA or nothing. Every client NIC failing simultaneously is statistically absurd. A dead switch would leave link lights dark and kill local traffic too. Storm interference on wireless would not explain wired clients also lacking addresses.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["dhcp", "wan", "outage", "isp"], "options": ["The wireless channel is congested by storm-related interference", "The ISP's upstream DHCP or provisioning service is still down, so no WAN lease is granted", "Every client NIC was damaged by the storm surge", "The internal switch is dead and forwarding nothing"], "answer": 3, "distractor_analysis": {"1": "Simultaneous multi-client NIC failure is implausible compared to an upstream service outage.", "2": "A dead switch shows down link lights and kills all local connectivity, contradicting the normal lights described.", "3": "Wireless channel issues would not affect wired clients, who are also without addresses."}, "id": "C1N-T-041"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "multi", "difficulty": "hard", "question": "A user reports that a laptop connects to the office Wi-Fi, drops after a few minutes, and reconnects on its own. The same laptop is rock solid on Ethernet. Which two steps advance the diagnosis most? (Select TWO.)", "explanation": "Intermittent Wi-Fi drops with solid Ethernet isolate the fault to the wireless path: measuring RSSI at the desk quantifies coverage, and the controller's association and deauthentication logs show why the client gets kicked, together splitting signal weakness from interference or client-side roaming bugs. Replacing the card skips measurement entirely. A static IP affects addressing, not radio stability, and the client reconnects and obtains addresses fine. Band steering changes affect the whole floor and are premature without evidence.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["wi-fi", "logs", "troubleshooting"], "options": ["Check the RSSI and roaming settings, and monitor signal strength at the user's desk", "Replace the user's laptop wireless card immediately", "Review the AP controller for association and deauthentication logs for this client", "Move the user to a static IP to stabilize the session", "Disable band steering on the whole floor"], "answers": [0, 2], "distractor_analysis": {"1": "Replacing hardware without measured evidence contradicts the methodology's test-before-replace discipline.", "3": "Address assignment is unrelated to radio-level drops; the laptop reconnects and gets addresses fine.", "4": "Changing floor-wide configuration without evidence is disproportionate and risky."}, "id": "C1N-T-042"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "order", "difficulty": "medium", "question": "A technician is explaining to a junior colleague why a batch of workstations self-assigned APIPA addresses after a DHCP scope change. Arrange the four DHCP messages in the order a client exchanges them to obtain a lease successfully.", "explanation": "The DORA sequence is strictly ordered because each message depends on the previous one. The client cannot request a specific address before any server has offered one, so the broadcast Discover opens the exchange. Servers answer with Offers, and only then can the client formally Request the address it wants, which also tells other servers their offers are declined. The server's Acknowledge finalizes the lease and delivers the gateway and DNS options; if any step fails, the client falls back to APIPA, which is exactly the symptom the scope change produced.", "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["dhcp", "dora", "networking", "procedure"], "sequence": ["Discover: the client broadcasts a request for DHCP service", "Offer: a server proposes an available address and lease options", "Request: the client formally asks for the offered address", "Acknowledge: the server confirms the lease and delivers the settings"], "id": "C1N-T-043"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A user reports that a shared office laser printer's output smears whenever anyone touches the print immediately after it lands in the tray. Which component is most likely at fault?", "explanation": "The fuser melts toner into the paper fibers during the fusing step; toner that still smears on touch means the fuser is not reaching temperature or its roller is worn, so the powder sits loose on the page. A worn drum leaves repeating marks at drum-circumference intervals, not wet-look smearing. The corona wire conditions the drum charge, and its failure produces blank pages. A weak transfer roller yields faint or patchy images, not toner that rubs off.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["laser-printer", "fuser", "electrophotographic"], "options": ["The corona wire, which is not charging the drum evenly", "The transfer roller, which is not moving the image from drum to page", "The fuser assembly, which is not bonding the toner into the page", "The imaging drum, which is leaving excess residual toner behind"], "answer": 0, "distractor_analysis": {"2": "Drum wear shows as repeating marks or ghosting at fixed intervals, not smear-on-touch output.", "3": "A failed corona wire leaves pages blank because the drum cannot hold the charge pattern for development.", "0": "Transfer roller faults give faint or missing image areas, not toner that smears after printing."}, "id": "C1N-T-044"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "multi", "difficulty": "medium", "question": "The help desk reports that a network laser printer at a remote site stopped printing for all users right after a network re-addressing change. The printer's own display still shows an address. Which two steps diagnose the IP configuration most efficiently? (Select TWO.)", "explanation": "After a re-addressing change, the printer may hold a stale or now-duplicated address: the configuration page reports exactly what the printer believes it has, and pinging it from a client plus checking for a conflict confirms both reachability and duplication. Reinstalling drivers addresses the wrong layer when every client failed at once. Power-cycling is a blind action that can mask the root cause. Replacing the NIC assumes hardware fault with zero evidence, since the display shows a live configured interface.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["network-printer", "ip-conflict", "printers"], "options": ["Print a configuration page to see exactly what address and settings the printer currently holds", "Ping the printer's address from a client and check the subnet for an address conflict", "Reinstall the print driver on every client machine", "Power-cycle the printer and hope the lease refreshes on its own", "Replace the printer's network interface card with a spare"], "answers": [0, 1], "distractor_analysis": {"2": "When every client fails simultaneously, the fault sits at the printer or network layer, not in each client's driver.", "3": "Blind power-cycling can hide the root cause and does not diagnose address duplication.", "4": "Replacing the NIC is a hardware guess; the display shows a configured address, so the interface is alive."}, "id": "C1N-T-045"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "easy", "question": "A user's print jobs sit in the queue with an Error status and nothing prints on a locally connected USB printer. Which remediation sequence is correct?", "explanation": "Errored jobs can wedge the queue and the spooler together: clear the stuck jobs, restart the Print Spooler service to reset the queue pipeline, then verify with a fresh test page. Driver reinstall is heavier and premature before the spooler reset is tried. Power-cycling leaves the poisoned queue intact to fail again on the next job. Re-adding by IP is wrong for a USB printer, which uses a local port, not a network address.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["spooler", "print-queue", "windows"], "options": ["Reinstall the printer driver immediately, then clear the queue", "Power-cycle the printer and leave the queue untouched to preserve the jobs", "Delete the printer object and re-add it by IP address", "Clear the queue, restart the Print Spooler service, and print a test page"], "answer": 1, "distractor_analysis": {"3": "Driver reinstall is heavier than a spooler reset and premature before the simpler fix is tested.", "0": "Restarting only the hardware leaves the wedged queue and spooler state untouched, so the error repeats.", "1": "A USB printer has no IP address; it uses a local USB port, so the re-add method does not apply."}, "id": "C1N-T-046"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "hard", "question": "A user reports that a laser printer produces a clean vertical white stripe down every page, and the technician confirms the toner level is fine. Which component should be suspected?", "explanation": "A crisp vertical white stripe on every page means one fixed track on the drum cannot hold or develop toner, which is classic drum damage along a band. Uneven fuser heat produces poorly bonded or smeared bands, not a missing toner stripe. A slipping pickup roller causes jams, skew, or multi-page feeds, never a developed image defect. Over-charging at the transfer roller gives background scatter or blotches, not a clean missing stripe.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["laser-printer", "drum", "print-quality"], "options": ["The imaging drum, damaged along one track so that band cannot develop toner", "The fuser, which is not heating evenly across its roller", "The pickup roller, which is slipping and misfeeding the paper", "The transfer roller, which is over-charging the page edges"], "answer": 2, "distractor_analysis": {"0": "Fuser problems affect toner bonding after development, so output smears rather than losing a vertical track.", "1": "Pickup roller wear causes feed jams and skewed paper, not image defects.", "2": "Transfer faults add background scatter or faint patches; they do not erase one clean vertical band."}, "id": "C1N-T-047"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "match", "difficulty": "hard", "question": "A technician is coaching a new hire through laser printer faults and wants the defect mapped to the failing step of the electrophotographic process. Match each symptom to the component at fault.", "explanation": "Each defect maps to one stage of the electrophotographic cycle. Smearing on touch means the fuser is not melting toner into the fibers, so the image never bonds. A mark repeating at a fixed interval matches one damaged track on the drum's circumference. Completely blank pages mean the charging corona wire is not conditioning the drum, so no latent image forms for development. Ghosting of the previous job's content means the transfer stage is not fully moving toner off the drum, so leftovers faintly reappear on the next page.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["laser-printer", "electrophotographic", "diagnosis"], "pairs": [{"left": "Toner smears when touched", "right": "Worn or cold fuser assembly"}, {"left": "Repeating ghost image every drum revolution", "right": "Damaged imaging drum"}, {"left": "Completely blank pages", "right": "Failed charging corona wire"}, {"left": "Ghosting of the previous job's content", "right": "Faulty transfer stage"}], "id": "C1N-T-048"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A user reports that an inkjet printer prints with visible horizontal banding and missing colors. A technician runs a nozzle check pattern and sees gaps in the pattern. What is the first maintenance action?", "explanation": "Gaps in a nozzle check mean clogged nozzles, so the first action is a cleaning cycle followed by another check to see whether the pattern fills in. Cartridges still supply ink when the check shows a partial pattern, so replacing them wastes consumables. Higher quality settings compensate for minor dot loss but cannot print through nozzles that fire nothing at all. Printhead replacement is a last resort after multiple cleaning cycles fail.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["inkjet", "nozzles", "maintenance"], "options": ["Replace the printhead, since gaps in the pattern mean it is dead", "Run the printhead cleaning cycle, then reprint the nozzle check", "Replace all the ink cartridges with new ones", "Increase the print quality setting to maximum"], "answer": 3, "distractor_analysis": {"1": "The partial nozzle pattern proves ink reaches the head, so consumables are not the fault.", "2": "Quality settings cannot compensate for nozzles that are fully clogged and fire nothing.", "3": "Printhead replacement is premature before cleaning cycles have been attempted and failed."}, "id": "C1N-T-049"}, {"exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A cashier reports that the thermal receipt printer at the point of sale prints faint, incomplete characters that drop out mid-letter. Which cause and remedy pair is correct?", "explanation": "Incomplete characters that drop out mid-letter indicate uneven heating across the printhead elements: residue on the heating line blocks heat transfer to the paper, so clean the elements with isopropyl alcohol and verify the paper stock is fresh. Old paper fades contrast evenly across the whole receipt rather than eating character strokes. Thermal printers have no fuser assembly at all, since that belongs to laser printing. Thermal printers use no toner; they heat coated paper directly.", "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["thermal-printer", "printhead", "printers"], "options": ["Old thermal paper past its shelf life, so install fresh stock", "A failing fuser, so replace the fuser assembly", "A dirty printhead, so clean the heating elements with isopropyl alcohol", "Low toner, so replace the toner cartridge"], "answer": 0, "distractor_analysis": {"3": "Aging thermal paper reduces contrast uniformly across the receipt; it does not eat individual character strokes.", "0": "Thermal printers contain no fuser assembly; fusing is a laser printer process.", "2": "Thermal printers use no toner; they burn the image directly into heat-sensitive paper."}, "id": "C1N-T-050"}, {"id": "C1N-C-001", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "A developer wants to run Linux inside a window on a Windows laptop for testing, without rebooting. Which software makes this possible?", "options": ["A driver update utility", "A hypervisor that runs a virtual machine", "A disk defragmenter", "A firewall"], "answer": 3, "explanation": "A hypervisor creates virtual machines, each of which behaves like a separate computer with its own virtual processor, memory, disk and network adapter, and can run a different operating system from the host. On a laptop this is a Type 2 hypervisor such as VirtualBox, VMware Workstation or Hyper-V running on top of the host operating system, so the developer works in Windows and Linux at the same time. None of the other tools create an isolated operating environment.", "distractor_analysis": {"1": "Defragmentation reorganises files on disk.", "2": "A firewall filters network traffic.", "3": "Driver utilities update hardware drivers."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hypervisor", "virtual-machine"]}, {"id": "C1N-C-002", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "Which description matches a Type 2 hypervisor?", "options": ["Firmware that boots before any operating system and manages hardware", "Software that installs directly on server hardware with no host operating system", "A container runtime that shares the host kernel", "An application installed on a host operating system that runs virtual machines"], "answer": 1, "explanation": "A Type 2, or hosted, hypervisor is an ordinary program on Windows, macOS or Linux. It asks the host operating system for memory, disk and network access and presents them to the guest as virtual hardware. Because it depends on the host it carries some overhead, but it is convenient for desktops and labs. A Type 1 hypervisor runs on bare metal without a host operating system, and containers are a different isolation technique that does not virtualise hardware at all.", "distractor_analysis": {"1": "Firmware describes UEFI or BIOS, not a hypervisor.", "2": "Bare-metal installation defines a Type 1 hypervisor.", "3": "Containers share the kernel and are not hypervisors."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hypervisor", "type-2"]}, {"id": "C1N-C-003", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician installs a hypervisor on a laptop but virtual machines refuse to start, reporting that hardware-assisted virtualization is unavailable. The processor supports it. What should the technician do?", "options": ["Replace the processor", "Format the hard drive", "Enable the virtualization extension (Intel VT-x or AMD-V) in the firmware setup", "Install more memory"], "answer": 2, "explanation": "Modern hypervisors rely on processor extensions that let guests run most instructions directly on the hardware. Many systems ship with the feature switched off in firmware, so the hypervisor reports that the capability is missing even though the CPU has it. Rebooting into setup, enabling Intel VT-x or AMD-V (and often the related I/O virtualization option), and saving fixes the error. Memory, the processor itself and the disk are not the problem.", "distractor_analysis": {"1": "Insufficient memory produces a different error about allocation.", "2": "The processor already supports the feature.", "3": "Disk state has no bearing on CPU extensions."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "vt-x", "amd-v", "firmware"]}, {"id": "C1N-C-004", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A workstation with 16 GB of RAM runs two virtual machines each assigned 8 GB. The host becomes unusable when both are running. What is the cause?", "options": ["The processor lacks enough cores", "The virtual machines consume all physical memory, leaving the host operating system starved", "The virtual machines are sharing the same virtual disk", "The network adapters are misconfigured"], "answer": 3, "explanation": "Memory assigned to a running virtual machine is reserved from the host's physical RAM. Two guests at 8 GB each take the entire 16 GB, so the host operating system and the hypervisor itself are forced to swap to disk and everything grinds to a halt. The resource requirement for a virtualization host is the sum of every running guest's memory plus headroom for the host, so the fix is fewer or smaller guests or more RAM. Disks, network and cores would produce different symptoms.", "distractor_analysis": {"1": "Sharing a disk file is usually prevented by the hypervisor and would not stall the host.", "2": "Network errors would affect connectivity, not overall responsiveness.", "3": "Too few cores slows guests but does not exhaust host memory."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "resource-requirements", "memory"]}, {"id": "C1N-C-005", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A support team needs to test a suspicious email attachment. Which use of virtualization is most appropriate?", "options": ["Open the attachment on the help desk technician's own workstation", "Forward the attachment to every user for a second opinion", "Open the attachment on the file server", "Open the attachment inside an isolated sandbox virtual machine with no access to the production network"], "answer": 1, "explanation": "A sandbox is a disposable, isolated virtual machine used to observe what software does without risking real systems. The guest should have no connection to the corporate network, and once the test is done the machine is reverted to a clean snapshot or deleted, taking any malware with it. This is one of the classic reasons to use virtualization in support and security work. Every other option exposes real machines or more people to the potential threat.", "distractor_analysis": {"1": "Running unknown code on a real workstation risks infection.", "2": "Spreading a suspicious file multiplies the risk.", "3": "The file server is one of the worst possible places to run unknown code."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "sandbox", "security", "testing"]}, {"id": "C1N-C-006", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A company still needs a program that only runs on an operating system no longer supported by the vendor. What is the safest way to keep using it?", "options": ["Disable antivirus so the old program can run on the current operating system", "Connect the old operating system directly to the internet for updates", "Run the legacy operating system in a virtual machine isolated from the network", "Install the legacy operating system on every new laptop"], "answer": 2, "explanation": "Legacy and cross-platform software support is a core virtualization use case. Keeping the unsupported operating system inside a virtual machine confines its security weaknesses, allows snapshots for quick recovery, and lets the host run a modern, patched operating system. Restricting the guest's network access limits exposure. Installing an unsupported system on new hardware often does not even work and broadens the attack surface, and disabling protection or exposing it to the internet is reckless.", "distractor_analysis": {"1": "Old operating systems often lack drivers for new hardware and are insecure.", "2": "Disabling antivirus does not make an incompatible program run and reduces security.", "3": "No updates exist, and internet exposure invites compromise."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "legacy-software", "isolation"]}, {"id": "C1N-C-007", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "Before installing a risky software update inside a virtual machine, what should the technician do so the change can be undone in seconds?", "options": ["Disable the virtual network adapter", "Take a snapshot of the virtual machine", "Defragment the host disk", "Increase the guest's memory"], "answer": 3, "explanation": "A snapshot records the state of the virtual machine's disk and, optionally, its memory at a point in time. If the update misbehaves, reverting to the snapshot returns the guest to exactly how it was, which is far faster than reinstalling. Snapshots are not backups because they live with the virtual machine, and a long chain of them slows the guest, so they should be deleted or merged once the change is confirmed good.", "distractor_analysis": {"1": "Defragmenting the host has no rollback value.", "2": "More memory does not allow undoing changes.", "3": "Disconnecting the network does not preserve state."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "snapshot", "rollback"]}, {"id": "C1N-C-008", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A virtual machine needs to be reachable from other computers on the office network as if it were a physical machine with its own address. Which virtual network mode should be used?", "options": ["NAT networking", "Host-only networking", "Internal networking", "Bridged networking"], "answer": 1, "explanation": "In bridged mode the virtual machine's network adapter is connected directly to the host's physical network, so the guest obtains its own address from the office DHCP server and other machines can reach it directly. NAT hides the guest behind the host's address and blocks inbound connections by default, host-only creates a private network between the host and its guests, and internal networking connects guests only to each other.", "distractor_analysis": {"1": "NAT shares the host's address and needs port forwarding for inbound access.", "2": "Host-only guests are reachable only from the host.", "3": "Internal networks isolate guests from the physical network entirely."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "networking", "bridged"]}, {"id": "C1N-C-009", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician wants a virtual machine to browse the internet but does not want it to be visible to any other device on the office network. Which network mode fits?", "options": ["No network adapter", "Promiscuous bridged networking", "NAT networking", "Bridged networking"], "answer": 2, "explanation": "NAT mode places the guest on a private network inside the hypervisor and translates its traffic through the host's own address, exactly as a home router does. The guest can reach the internet and the office, but nothing on the office network can initiate a connection to it, so it stays effectively invisible. Bridged mode would give the guest a visible address, no adapter blocks browsing entirely, and promiscuous settings increase visibility rather than reduce it.", "distractor_analysis": {"1": "Bridged mode exposes the guest on the network.", "2": "With no adapter the guest cannot browse at all.", "3": "Promiscuous mode lets the adapter see more traffic; it is the opposite of hiding."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "networking", "nat"]}, {"id": "C1N-C-010", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A hypervisor host with a single physical network port runs ten virtual machines, and they all communicate with each other and the outside world. Which virtual component makes this possible?", "options": ["A modem", "A virtual switch inside the hypervisor", "A physical network card in each virtual machine", "A separate cable for each virtual machine"], "answer": 3, "explanation": "The hypervisor contains a software switch. Each virtual machine's virtual network adapter plugs into a port on that switch, traffic between guests never leaves the host, and one uplink to the physical adapter carries everything to and from the real network. Virtual switches also support VLAN tagging and multiple isolated networks. Virtual machines have no physical cards or cables of their own, and a modem is a WAN device.", "distractor_analysis": {"1": "Virtual machines have virtual, not physical, adapters.", "2": "There is no cabling inside a hypervisor.", "3": "A modem connects to an internet service provider, not guests to each other."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "virtual-switch", "networking"]}, {"id": "C1N-C-011", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A developer creates a virtual machine with a 200 GB virtual disk, but the file on the host is only 12 GB. Why?", "options": ["The hypervisor compressed the guest's operating system", "The guest is using the host's disk directly", "The virtual disk is corrupt", "The disk is thin provisioned and grows only as the guest writes data"], "answer": 1, "explanation": "A dynamically expanding, or thin provisioned, virtual disk presents its full size to the guest but allocates space on the host only as blocks are written, so a fresh installation occupies a fraction of its nominal capacity. Thick provisioning allocates all 200 GB up front and performs slightly better. The support implication is that several thin disks can together promise more space than the host actually has, so free space on the host must be monitored.", "distractor_analysis": {"1": "Compression is not the mechanism; unwritten space is simply not allocated.", "2": "The guest uses a virtual disk file, not the host disk directly.", "3": "A smaller-than-nominal file is normal for a thin disk, not a sign of damage."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "virtual-disk", "thin-provisioning"]}, {"id": "C1N-C-012", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician is asked how a virtual machine differs from a container. Which statement is accurate?", "options": ["Containers can only run Windows applications", "Virtual machines start faster than containers", "A virtual machine includes its own full operating system, while a container shares the host kernel and packages only the application and its dependencies", "A container needs a hypervisor and a virtual machine does not"], "answer": 2, "explanation": "Virtualization emulates hardware, so every virtual machine boots a complete operating system and carries that overhead. Containers isolate processes on a shared kernel using features such as namespaces, so they are much lighter, start in seconds and pack densely, but every container on a host must be compatible with that kernel. Both approaches are common and often combined, with containers running inside virtual machines in cloud environments.", "distractor_analysis": {"1": "It is the virtual machine that relies on a hypervisor.", "2": "Containers originated on Linux and run on several platforms.", "3": "Containers start far faster because no operating system boots."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "containers", "comparison"]}, {"id": "C1N-C-013", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A virtual machine's mouse pointer is sluggish, its screen resolution is stuck at a low setting and copy and paste to the host does not work. What should the technician install?", "options": ["A different antivirus product", "The hypervisor's guest additions or integration tools inside the virtual machine", "A new graphics card in the host", "A second virtual processor"], "answer": 3, "explanation": "Hypervisors provide a package of drivers and services for the guest, called guest additions, VMware Tools, integration services or similar. It supplies an optimised display driver with dynamic resolution, a paravirtualised mouse, clipboard sharing, drag and drop, shared folders and time synchronisation. Installing it is a routine step after building any virtual machine, and its absence produces exactly these symptoms. Hardware and antivirus changes do not address them.", "distractor_analysis": {"1": "The host graphics card is not the limit; the guest lacks a proper display driver.", "2": "More CPU does not add clipboard or display features.", "3": "Antivirus is unrelated to integration features."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "guest-additions", "integration"]}, {"id": "C1N-C-014", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "An organisation wants to run a dozen servers on two physical machines to cut hardware, power and cooling costs. Which virtualization approach is designed for this?", "options": ["A Type 2 hypervisor on a technician's laptop", "Running every service on one operating system without virtualization", "A web browser sandbox", "A Type 1 bare-metal hypervisor on each physical server"], "answer": 1, "explanation": "Server consolidation is the original business case for virtualization. A bare-metal hypervisor such as VMware ESXi, Hyper-V Server or KVM runs directly on the hardware with minimal overhead and hosts many isolated virtual servers, each with its own operating system, on a single physical machine. Two hosts also allow guests to be moved or restarted on the other host during maintenance. A laptop hypervisor is for desktops, and piling services onto one operating system loses isolation.", "distractor_analysis": {"1": "Type 2 hypervisors depend on a desktop host and are unsuitable for production servers.", "2": "Without virtualization the services share one operating system and one failure domain.", "3": "Browser sandboxes isolate web content, not servers."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "type-1", "server-consolidation"]}, {"id": "C1N-C-015", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A security team is concerned about running a customer-facing web server as a virtual machine on the same host as an internal finance database. Which virtualization-specific risk are they describing?", "options": ["Virtual machines cannot run antivirus software", "A virtual machine's password is always shared with the host", "A guest escape or hypervisor vulnerability that lets one virtual machine affect another on the same host", "Virtual machines cannot be patched"], "answer": 2, "explanation": "Virtual machines on one host share the hypervisor, physical processor and memory. A flaw in that shared layer, or a side-channel attack on the hardware, could let a compromised guest read or influence another guest, which is called a virtual machine escape. Good practice separates workloads of different sensitivity onto different hosts or clusters, keeps the hypervisor patched, and isolates their networks. Guests can be patched and protected like any machine, and credentials are not shared with the host.", "distractor_analysis": {"1": "Guests receive updates exactly like physical machines.", "2": "Endpoint protection runs normally inside virtual machines.", "3": "Guest and host accounts are entirely separate."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "security", "vm-escape"]}, {"id": "C1N-C-016", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A finance user needs to open a legacy application that behaves badly on the corporate build. The support team prefers not to touch the user's laptop at all. Which approach uses virtualization to solve this?", "options": ["Emailing the installer to the user", "Application virtualization, streaming the app to the user in an isolated package or from a remote session host", "Installing the app on the user's laptop with administrator rights", "Replacing the laptop with a desktop"], "answer": 3, "explanation": "Application virtualization packages an application with its own registry and file system view so it runs without installing into the operating system, or publishes it from a server so only screen updates reach the endpoint. Either way the corporate build stays untouched and the app can be updated centrally. Installing locally is what the team wants to avoid, a desktop changes nothing about compatibility, and emailing an installer is unmanaged.", "distractor_analysis": {"1": "A local install is exactly the change the team wishes to avoid.", "2": "The hardware form factor is irrelevant to application compatibility.", "3": "Unmanaged installs create inconsistency and support load."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "application-virtualization", "compatibility"]}, {"id": "C1N-C-017", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A hypervisor host has one processor with eight cores. How many virtual CPUs can be assigned across its virtual machines in total?", "options": ["Exactly eight, one per core", "Only one, because a hypervisor supports one virtual CPU", "Sixteen, because each core must be split exactly in two", "More than eight, because virtual CPUs are scheduled onto physical cores as needed"], "answer": 1, "explanation": "Virtual processors are time-sliced onto the physical cores by the hypervisor scheduler, so the total assigned can exceed the physical count, a practice called overcommitting. It works because guests rarely use all their CPU at once. Overcommit too far and guests queue for cores and slow down, so the ratio is a tuning decision. Neither a hard one-to-one limit nor a fixed two-to-one split is how scheduling works.", "distractor_analysis": {"1": "One-to-one is a conservative choice, not a hard limit.", "2": "Hypervisors support many virtual CPUs.", "3": "There is no fixed doubling rule; the ratio is configurable."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "vcpu", "overcommit", "resource-requirements"]}, {"id": "C1N-C-018", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician builds a virtual machine to test an operating system installer downloaded as an ISO file. How is the ISO used?", "options": ["It is burned to a physical disc and inserted into the host", "It is installed as a driver on the host", "It is attached to the virtual machine's virtual optical drive so the guest boots from it", "It is copied into the host's Program Files folder"], "answer": 2, "explanation": "An ISO is a disc image, and hypervisors let you mount it directly on a virtual optical drive. The guest sees a bootable disc, installs from it, and the file can be detached afterwards. No physical media is needed, which is one of the conveniences of virtualization for testing many operating systems quickly. The other options misunderstand what an image file is for.", "distractor_analysis": {"1": "Program Files holds installed software, not disc images.", "2": "Physical media is unnecessary; the image mounts virtually.", "3": "An ISO is not a driver."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "iso", "installation"]}, {"id": "C1N-C-019", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A virtual machine running a database is slow, and the host shows heavy disk activity from many guests sharing one spinning hard drive. Which change addresses the bottleneck most directly?", "options": ["Increase the guest's screen resolution", "Move the virtual disks to solid-state storage or spread them across more drives", "Assign the guest more virtual CPUs", "Change the guest's network adapter to bridged mode"], "answer": 3, "explanation": "Many guests hitting one mechanical disk create random I/O that a spinning drive handles poorly, and every guest waits. Storage is very often the limiting resource on a virtualization host, so moving the virtual disk files to SSD or NVMe storage, or separating guests across several drives, removes the queue. Extra processors do not speed up a disk-bound workload, and network mode and display settings are unrelated.", "distractor_analysis": {"1": "CPU is not the constraint when the host shows disk saturation.", "2": "Network mode does not change disk throughput.", "3": "Display resolution is irrelevant to database performance."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "storage", "performance", "resource-requirements"]}, {"id": "C1N-C-020", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A training company needs thirty identical Windows lab environments that can be reset to a clean state after each class. Which virtualization feature makes this efficient?", "options": ["Reinstalling Windows on thirty laptops each week", "Using a single shared user account on one physical machine", "Disabling updates on the lab machines", "Cloning virtual machines from a master template and reverting to a snapshot after each session"], "answer": 1, "explanation": "Build one virtual machine correctly, convert it to a template, and clone thirty copies in minutes. Taking a snapshot of each clone in its clean state lets the instructor revert every lab in seconds when the class ends. This is the standard model for training rooms, test labs and virtual desktop pools. Reinstalling physical machines is slow, a single shared machine cannot serve a class, and disabling updates solves nothing.", "distractor_analysis": {"1": "Weekly reinstalls are hours of work compared with a snapshot revert.", "2": "One shared machine cannot give thirty students their own environment.", "3": "Update policy is unrelated to resetting environments."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "cloning", "templates", "snapshot"]}, {"id": "C1N-C-021", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A user wants to run a macOS-only application on a Windows laptop by installing macOS in a virtual machine. What should the technician explain?", "options": ["macOS cannot be virtualised at all", "Windows blocks all hypervisors from running other operating systems", "Apple's licence permits macOS to run only on Apple hardware, so this is not a supported or licensed configuration", "It is fully supported by Apple on any hardware"], "answer": 2, "explanation": "Virtualization does not remove licensing obligations. Apple's software licence restricts macOS to Apple-branded hardware, so running it in a virtual machine on a Windows laptop violates the licence even though tools exist to do it, and there is no vendor support. On a Mac, however, macOS may be virtualised in permitted numbers. Technicians should check the licence terms of every guest operating system and application before building a virtual machine.", "distractor_analysis": {"1": "Apple restricts macOS to its own hardware.", "2": "macOS can be virtualised, but only on Apple hardware under the licence.", "3": "Windows hosts run many guest operating systems legally."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "licensing", "macos"]}, {"id": "C1N-C-022", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "An IT department is building a virtualization host to run six Windows Server guests. Which resource must be sized as the sum of every guest's requirement plus headroom for the hypervisor?", "options": ["Optical drive speed", "Physical memory", "Screen resolution", "Keyboard layout"], "answer": 3, "explanation": "Memory is the least shareable resource on a host. Each running guest reserves its allocation, so the host must have the total of all guests plus enough for the hypervisor and any management software, typically several gigabytes. Processor cores can be overcommitted and storage can be thin provisioned, but memory shortfalls cause immediate swapping and instability. Display, keyboard and optical drive settings are irrelevant to capacity planning.", "distractor_analysis": {"1": "Resolution is a per-guest display setting with no bearing on capacity.", "2": "Keyboard layout is a localisation setting.", "3": "Optical drives are virtual and rarely used after installation."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "resource-requirements", "memory", "capacity"]}, {"id": "C1N-C-023", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A virtual machine with an old snapshot has become very slow, and the host is nearly out of disk space even though the guest reports plenty free. What is happening?", "options": ["The guest's antivirus has filled the host disk", "The virtual switch is logging every packet", "The guest's memory has leaked onto the disk", "The snapshot's differencing disk has grown large as changes accumulate, consuming host space and adding read overhead"], "answer": 1, "explanation": "After a snapshot, every write goes to a separate differencing file while the original disk is frozen. Over weeks that file can grow to the size of the base disk, and reads must be checked against every layer in the chain, which slows the guest. Deleting or merging the snapshot writes the changes back into the base disk, reclaims the space and restores performance. Snapshots are for short-term rollback, not long-term retention.", "distractor_analysis": {"1": "Guest antivirus writes inside the guest's disk, which reports plenty free.", "2": "Virtual switches do not capture packets to disk by default.", "3": "Memory does not leak onto disk; the growth is the snapshot chain."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "snapshot", "storage", "troubleshooting"]}, {"id": "C1N-C-024", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "Which statement describes how a virtual machine's disk is typically stored on the host?", "options": ["On a dedicated physical drive that must be installed for each guest", "In the host's system memory only", "As one or more large files such as VHDX, VMDK or QCOW2 that the guest sees as a physical drive", "As millions of individual files mirroring the guest's file system"], "answer": 2, "explanation": "A virtual disk is a container file in a hypervisor-specific format. The guest formats and partitions it exactly like a physical drive while the host simply sees a large file that can be copied, backed up, moved between hosts or converted between formats. This portability is a major advantage of virtualization. Guests do not need dedicated physical drives, their files are not exposed individually on the host, and the disk persists on storage rather than in memory.", "distractor_analysis": {"1": "The guest's files live inside the container; the host does not see them individually.", "2": "Dedicated drives per guest would defeat the purpose of consolidation.", "3": "Memory is volatile; disks must persist across power cycles."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "virtual-disk", "vhdx", "vmdk"]}, {"id": "C1N-C-025", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A company wants staff to log in from any thin client or personal laptop and receive the same Windows desktop, hosted centrally on servers. Which technology delivers this?", "options": ["A network attached storage device", "Virtual desktop infrastructure (VDI)", "A local Type 2 hypervisor on each laptop", "A USB recovery drive"], "answer": 3, "explanation": "VDI runs each user's desktop as a virtual machine in the data centre or cloud and streams only the screen, keyboard and mouse to the endpoint. The endpoint can be a cheap thin client or an unmanaged personal device because no data is stored on it, and IT patches and backs up the desktops centrally. A local hypervisor puts the desktop on the laptop rather than centrally, and recovery drives and storage appliances do not host desktops.", "distractor_analysis": {"1": "A local hypervisor ties the desktop to one device.", "2": "Recovery media repairs a local installation.", "3": "NAS provides file storage, not desktops."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "vdi", "thin-client"]}, {"id": "C1N-C-026", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician needs to move a running virtual machine from one host to another for maintenance without users noticing. Which feature does this?", "options": ["Copying the virtual disk file with the guest powered off", "Taking a snapshot", "Exporting the guest to an ISO file", "Live migration between hosts sharing storage or replicating memory state"], "answer": 1, "explanation": "Live migration copies a running guest's memory to another host while it keeps running, then switches execution across in a fraction of a second, so sessions and connections survive. It is how administrators empty a host for patching without downtime and is a standard feature of enterprise hypervisors. Cold copying requires shutdown, snapshots preserve state on the same host, and an ISO is an optical disc image rather than a virtual machine format.", "distractor_analysis": {"1": "A powered-off copy means downtime for users.", "2": "Snapshots do not move a guest anywhere.", "3": "Virtual machines are exported as OVF or similar packages, not ISOs."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "live-migration", "maintenance"]}, {"id": "C1N-C-027", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A student's laptop shows Hyper-V as an installed feature, but a third-party hypervisor now runs virtual machines extremely slowly or refuses to start them. What is the most likely reason?", "options": ["The screen is too small", "The third-party hypervisor needs an internet connection", "Two hypervisors are competing for the processor's virtualization extensions, and the built-in one has claimed them", "The laptop battery is low"], "answer": 2, "explanation": "Only one hypervisor can own the processor's hardware virtualization features at a time. When Hyper-V or related Windows security features such as virtualization-based security are active, other hypervisors either fall back to slow software emulation or fail to launch. Disabling the Windows hypervisor platform features, or using a hypervisor that can coexist with Hyper-V, resolves the conflict. Battery, display size and connectivity are unrelated.", "distractor_analysis": {"1": "Power state does not stop virtual machines starting.", "2": "Display size is cosmetic.", "3": "Local virtual machines run without internet."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hyper-v", "conflict", "troubleshooting"]}, {"id": "C1N-C-028", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A network engineer wants to build a lab of several routers and firewalls to practise configuration without buying hardware. Which approach is most practical?", "options": ["Use a spreadsheet to simulate routing tables", "Run virtual network appliances as virtual machines connected by internal virtual switches", "Buy one physical router and reconfigure it repeatedly", "Draw the topology on paper"], "answer": 3, "explanation": "Vendors provide virtual editions of routers, switches and firewalls that run as virtual machines. Connecting them through internal virtual networks reproduces a multi-device topology on a single host, with snapshots to reset any device and no risk to production. Test and development labs of this kind are one of the most common uses of desktop virtualization in networking. One physical device cannot represent a topology, and paper and spreadsheets do not run the actual software.", "distractor_analysis": {"1": "A single device cannot demonstrate multi-hop behaviour.", "2": "Diagrams do not let you configure or test anything.", "3": "A spreadsheet does not run the real operating system."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "lab", "virtual-appliances", "networking"]}, {"id": "C1N-C-029", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A hypervisor host runs guests for several different departments. Which practice reduces the risk of a compromised guest affecting the others?", "options": ["Giving every guest the same administrator password for convenience", "Disabling all guest firewalls to simplify troubleshooting", "Sharing one virtual disk file among all the guests", "Keeping the hypervisor patched and placing guests on separate isolated virtual networks"], "answer": 1, "explanation": "Virtualization security rests on two things: the shared hypervisor must be kept current because a flaw there affects every guest, and guests should be segmented on separate virtual networks or VLANs so a breach of one cannot spread laterally. Adding guest firewalls, least-privilege accounts and monitoring on the host completes the picture. Shared credentials, disabled firewalls and a shared disk each make lateral movement easier rather than harder.", "distractor_analysis": {"1": "Shared passwords mean one compromise opens every guest.", "2": "Firewalls are a key layer of guest isolation.", "3": "Sharing a disk between guests corrupts data and removes isolation."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "security", "segmentation"]}, {"id": "C1N-C-030", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "In virtualization terminology, what is the host?", "options": ["The network switch connecting the office", "The user who owns the virtual machine", "The physical computer and its hypervisor that run the virtual machines", "The operating system installed inside a virtual machine"], "answer": 2, "explanation": "The host is the real machine, together with the hypervisor running on it, that provides processor, memory, storage and network to the virtual machines. Each operating system running inside a virtual machine is called a guest. Keeping the terms straight matters when reading documentation and error messages: a warning about host memory refers to the physical server, while guest memory is what was assigned to a particular virtual machine.", "distractor_analysis": {"1": "The operating system inside a virtual machine is the guest.", "2": "Physical network equipment is outside the virtualization stack.", "3": "People are administrators or users, not hosts."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "terminology", "host", "guest"]}, {"id": "C1N-C-031", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A virtual machine's clock drifts several minutes a day, which breaks authentication to the domain. What is the recommended fix?", "options": ["Switch the guest to bridged networking", "Install the hypervisor's integration tools and enable time synchronisation with the host, or point the guest at an NTP source", "Replace the host's CMOS battery", "Assign the guest more storage"], "answer": 3, "explanation": "Virtual machines do not have a real hardware clock; they count time from interrupts the hypervisor delivers, and when a guest is paused or starved of CPU it falls behind. Integration tools keep the guest clock synchronised with the host, and domain-joined guests should also take time from the domain's NTP hierarchy. Kerberos tolerates only a few minutes of skew, so this is a real cause of login failures. The host battery, guest storage and network mode do not affect guest timekeeping.", "distractor_analysis": {"1": "The host clock is fine; the drift is inside the guest.", "2": "Storage capacity has nothing to do with time.", "3": "Network mode does not change clock behaviour."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "time-sync", "troubleshooting", "integration"]}, {"id": "C1N-C-032", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A developer needs a virtual machine to talk only to a second virtual machine on the same host, with no access to the host or to any external network. Which mode should both adapters use?", "options": ["Bridged networking", "NAT networking", "Host-only networking", "Internal or private networking"], "answer": 1, "explanation": "An internal network, sometimes called private, exists only inside the hypervisor. Guests attached to it can reach each other but not the host, not the office and not the internet, which is ideal for testing malware behaviour between machines or rehearsing a server migration in isolation. Host-only would let the host join the conversation, and bridged and NAT both provide a path to external networks.", "distractor_analysis": {"1": "Bridged mode exposes guests to the real network.", "2": "NAT allows outbound access to the internet.", "3": "Host-only includes the host as a participant."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "networking", "internal-network", "isolation"]}, {"id": "C1N-C-033", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A backup administrator asks whether taking snapshots of the file server virtual machine every night is an adequate backup strategy. What is the correct advice?", "options": ["Yes, provided the snapshots are named clearly", "No, because snapshots cannot be taken of file servers", "No, because snapshots are stored with the virtual machine on the same host and storage, so a host or storage failure loses both", "Yes, snapshots are a complete backup"], "answer": 2, "explanation": "A snapshot is a rollback point, not a backup. It depends on the base disk and lives on the same storage; if the host fails, the storage array dies or ransomware encrypts the datastore, the snapshot goes with it. Accumulating nightly snapshots also degrades performance. A proper strategy uses backup software that copies the virtual machine, often using a temporary snapshot to get a consistent image, to separate storage and ideally off site.", "distractor_analysis": {"1": "A snapshot shares the fate of the virtual machine it belongs to.", "2": "Naming does not change where the data is stored.", "3": "Any virtual machine can be snapshotted; the issue is what a snapshot protects against."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "snapshot", "backup"]}, {"id": "C1N-C-034", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A guest operating system inside a virtual machine reports that it has a network adapter, a graphics adapter and a disk controller from a vendor the physical host does not contain. Why?", "options": ["The guest is reading the wrong driver database", "The hypervisor presents standardised virtual devices to every guest regardless of the underlying physical hardware", "The guest is misreporting because it is infected", "The host has hidden hardware that only guests can see"], "answer": 3, "explanation": "Hypervisors emulate or paravirtualise a small set of well-known devices so that any guest operating system can boot with built-in drivers. The virtual network card, display adapter and storage controller are therefore the same on every host running that hypervisor, which is what makes virtual machines portable between physical servers of different makes. It is normal, not a sign of infection or hidden components.", "distractor_analysis": {"1": "Standard virtual hardware is expected behaviour, not malware.", "2": "There is no hidden physical hardware; the devices are software constructs.", "3": "The guest correctly identifies the virtual devices it is given."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "virtual-hardware", "portability"]}, {"id": "C1N-C-035", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A small office wants a single powerful desktop to act as a file server, a print server and a web development server for a small team, with each role isolated. Which is the most sensible plan?", "options": ["Install all three roles on the desktop's single operating system", "Buy three separate desktops", "Run all three roles on a laptop", "Install a hypervisor and run each role in its own virtual machine"], "answer": 1, "explanation": "Virtualization lets one well-specified machine host several isolated servers, so a fault or reboot in the development environment does not take down file sharing. Each guest can be snapshotted and backed up independently and moved to new hardware later by copying files. Stacking roles on one operating system loses that isolation, three machines waste money and power for a small team, and a laptop lacks the resources and reliability for always-on services.", "distractor_analysis": {"1": "One operating system means one failure affects every role.", "2": "Three machines cost more in hardware, power and maintenance.", "3": "Laptops are not designed to run continuously as servers."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "small-office", "consolidation"]}, {"id": "C1N-C-036", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "multi", "difficulty": "medium", "question": "A technician is specifying a desktop to run several virtual machines for a test lab. Which TWO hardware characteristics matter most? (Select TWO.)", "options": ["A processor with hardware virtualization support and plenty of cores", "A large amount of RAM, since each running guest reserves its allocation", "A high-refresh-rate gaming monitor", "A mechanical keyboard", "A Blu-ray optical drive"], "answers": [0, 1], "explanation": "Virtualization hosts are sized on processor, memory and storage. Hardware virtualization extensions are mandatory for modern hypervisors and more cores let more guests run concurrently without contention. Memory is the hard limit because it cannot be meaningfully overcommitted. Fast solid-state storage is the third factor. Display refresh rate, keyboard type and optical media have no effect on how many virtual machines the system can run or how well they perform.", "distractor_analysis": {"2": "Monitor refresh rate affects gaming, not virtual machine capacity.", "3": "Keyboard type is a personal preference.", "4": "Installation media is mounted as ISO files; an optical drive is unnecessary."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "resource-requirements", "hardware"]}, {"id": "C1N-C-037", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "multi", "difficulty": "medium", "question": "Which TWO are legitimate reasons an IT team would use virtualization on end-user workstations rather than on servers? (Select TWO.)", "options": ["Running a legacy application that requires an older operating system", "Testing software or suspicious files in a disposable sandbox", "Increasing the physical speed of the workstation's processor", "Extending the laptop's battery life", "Replacing the need for antivirus software"], "answers": [0, 1], "explanation": "Client-side virtualization earns its place through compatibility and safety. A virtual machine keeps an old operating system alive for one stubborn application without compromising the modern host, and a sandbox lets technicians open unknown files or trial software and then discard the machine. Virtualization costs performance and battery rather than adding them, and it complements rather than replaces endpoint protection.", "distractor_analysis": {"2": "A hypervisor adds overhead; it cannot make the processor faster.", "3": "Running extra operating systems consumes more power.", "4": "Guests and hosts still need protection; isolation is a layer, not a substitute."}, "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "client-side", "use-cases"]}, {"id": "C1N-C-038", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "match", "difficulty": "medium", "question": "Match each virtual machine network mode to its behaviour.", "pairs": [{"left": "Bridged", "right": "Guest gets its own address on the physical network and is reachable by other devices"}, {"left": "NAT", "right": "Guest shares the host's address; outbound works but inbound is blocked by default"}, {"left": "Host-only", "right": "Guest can talk to the host and other guests but not to the outside world"}, {"left": "Internal", "right": "Guests talk only to each other, with no host or external access"}], "explanation": "Choosing the network mode is the most common decision when creating a virtual machine, and getting it wrong is the most common reason a guest cannot be reached or cannot browse. Bridged makes the guest a peer on the LAN, NAT hides it behind the host like a home router, host-only builds a private lab that includes the host, and internal isolates guests completely from everything except each other.", "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "networking", "match"]}, {"id": "C1N-C-039", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "order", "difficulty": "easy", "question": "Order the steps to create and start a new virtual machine for testing an operating system on a desktop hypervisor.", "sequence": ["Confirm hardware virtualization is enabled in the host firmware and the hypervisor is installed", "Create a new virtual machine and assign processor cores, memory and a virtual disk", "Attach the operating system ISO to the virtual optical drive and choose a network mode", "Start the virtual machine and complete the operating system installation", "Install the hypervisor's guest additions and take a clean snapshot"], "explanation": "The sequence follows dependencies. Virtualization extensions must be on before anything will run. Resources are allocated when the machine is defined. Installation media and networking are attached before first boot so the installer can run and reach updates. Guest additions come after the operating system exists, and a snapshot of the fresh, working state gives a clean point to return to after every experiment.", "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "procedure", "setup"]}, {"id": "C1N-C-040", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A virtual machine cannot reach the internet although the host can, and the guest shows an address beginning 169.254. Which is the most likely cause?", "options": ["The host's screen saver is active", "The guest's snapshot is too old", "The guest did not receive a DHCP lease from the virtual network it is attached to", "The guest has too little memory"], "answer": 2, "explanation": "An address in the 169.254 range is an automatic private address that a client assigns itself when no DHCP server answers. In a virtual machine this usually means the adapter is attached to a network with no DHCP service, such as an internal network, or the hypervisor's built-in DHCP for NAT or host-only mode is disabled, or the virtual adapter is disconnected. Checking the adapter's mode and connection state and renewing the lease fixes it.", "distractor_analysis": {"1": "Memory shortage causes slowness, not a self-assigned address.", "2": "The host display state has no effect on guest networking.", "3": "Snapshot age does not alter DHCP behaviour."}, "video_reference": {"title": "Virtualization Services - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=wPB_C7hOY-8", "duration": "11:23", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "networking", "dhcp", "troubleshooting"]}, {"id": "C1N-C-041", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A company rents virtual servers, storage and networking from a provider and installs and manages its own operating systems and applications on them. Which cloud service model is this?", "options": ["Desktop as a Service (DaaS)", "Infrastructure as a Service (IaaS)", "Software as a Service (SaaS)", "Platform as a Service (PaaS)"], "answer": 3, "explanation": "IaaS provides the raw building blocks: compute instances, block and object storage, and virtual networks. The customer chooses the operating system, patches it, installs software and is responsible for everything above the hypervisor, while the provider owns the physical data centre. It is the most flexible model and the closest to running your own servers. SaaS delivers finished applications, PaaS delivers a managed runtime, and DaaS delivers hosted desktops.", "distractor_analysis": {"1": "SaaS customers use an application; they never see servers.", "2": "PaaS hides the operating system and gives developers a runtime.", "3": "DaaS streams a managed desktop, not raw infrastructure."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "service-models"]}, {"id": "C1N-C-042", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "Staff use web-based email, calendars and document editing through a browser, and the company pays a monthly fee per user. Which cloud service model is this?", "options": ["Infrastructure as a Service (IaaS)", "Platform as a Service (PaaS)", "Network as a Service", "Software as a Service (SaaS)"], "answer": 1, "explanation": "SaaS is a complete application delivered over the internet and paid for by subscription. The provider runs the servers, the database and the code, applies updates and keeps the service available, and the customer manages only users and data. Microsoft 365 and Google Workspace are the everyday examples. IaaS and PaaS both leave the customer responsible for building or running software, which SaaS customers never touch.", "distractor_analysis": {"1": "IaaS customers manage operating systems and applications themselves.", "2": "PaaS is for developers deploying their own code.", "3": "Network as a Service provides connectivity, not productivity applications."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "saas", "service-models"]}, {"id": "C1N-C-043", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A development team wants to deploy a web application by uploading code, with the provider managing the operating system, web server, database engine and scaling. Which service model fits?", "options": ["Software as a Service (SaaS)", "Hardware as a Service", "Platform as a Service (PaaS)", "Infrastructure as a Service (IaaS)"], "answer": 2, "explanation": "PaaS sits between infrastructure and finished software. Developers get a managed runtime, database services, build pipelines and automatic scaling, and they focus on code rather than patching servers. The trade-off is less control over the underlying stack and some dependence on the provider's supported languages and frameworks. IaaS would leave them patching operating systems, and SaaS would give them someone else's application rather than a place to run their own.", "distractor_analysis": {"1": "IaaS requires the team to manage operating systems and middleware.", "2": "SaaS is a finished application, not a place to deploy code.", "3": "Hardware as a Service leases physical equipment."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "paas", "service-models"]}, {"id": "C1N-C-044", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "Cloud resources that are owned and operated by a provider and shared among many unrelated customers over the internet describe which deployment model?", "options": ["On-premises data centre", "Public cloud", "Private cloud", "Community cloud"], "answer": 3, "explanation": "In a public cloud the provider owns the hardware and offers services to anyone on a pay-as-you-go basis. Customers share the physical infrastructure but are logically isolated from each other, a property called multitenancy. The main providers are Amazon Web Services, Microsoft Azure and Google Cloud. A private cloud is dedicated to one organisation, a community cloud is shared by organisations with common needs, and an on-premises data centre is not a cloud at all.", "distractor_analysis": {"1": "Private clouds serve a single organisation.", "2": "Community clouds are shared by a defined group with common requirements.", "3": "Traditional on-premises infrastructure lacks the self-service, elastic model of cloud."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "public-cloud", "deployment-models"]}, {"id": "C1N-C-045", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A bank builds cloud-style self-service infrastructure in its own data centre, used only by its own departments, because regulations forbid customer data leaving its premises. Which deployment model is this?", "options": ["Public cloud", "Hybrid cloud", "Community cloud", "Private cloud"], "answer": 1, "explanation": "A private cloud delivers the cloud characteristics of self-service, pooling and elasticity, but the infrastructure is dedicated to one organisation, either in its own facility or hosted by a third party for its exclusive use. Organisations choose it for regulatory, data sovereignty or performance reasons and accept higher cost and a fixed capacity ceiling in return. It is not public because nothing is shared with other customers, and not hybrid because there is no public component.", "distractor_analysis": {"1": "Public cloud shares infrastructure with other customers.", "2": "Hybrid requires a public cloud component, which the regulation rules out here.", "3": "Community cloud is shared among several organisations."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "private-cloud", "deployment-models", "compliance"]}, {"id": "C1N-C-046", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A retailer keeps its core database on servers in its own data centre but bursts its website onto a public cloud during holiday sales, with the two connected by a private link. Which deployment model is this?", "options": ["Private cloud", "Community cloud", "Hybrid cloud", "Public cloud"], "answer": 2, "explanation": "A hybrid cloud combines private infrastructure with public cloud services and connects them so workloads and data can move between them. It lets an organisation keep sensitive or steady-state systems in-house while renting public capacity for peaks, which is called cloud bursting. The integration is what makes it hybrid rather than simply using two separate environments. Each of the other models describes a single environment.", "distractor_analysis": {"1": "Public alone would put the database in the provider's cloud too.", "2": "Private alone has no public burst capacity.", "3": "Community cloud is about shared ownership among peer organisations."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "hybrid-cloud", "deployment-models", "cloud-bursting"]}, {"id": "C1N-C-047", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Several hospitals in a region jointly fund and share a cloud platform that meets healthcare privacy requirements and is not open to other customers. Which deployment model is this?", "options": ["Private cloud", "Community cloud", "Public cloud", "Hybrid cloud"], "answer": 3, "explanation": "A community cloud is shared by a specific group of organisations with common concerns such as regulation, security or mission, and is closed to outsiders. It spreads cost across the members while keeping the compliance posture they all need. It differs from a private cloud, which belongs to one organisation, and from a public cloud, which anyone can use. Government and healthcare consortia are the typical examples.", "distractor_analysis": {"1": "Public cloud is open to all customers.", "2": "Hybrid describes a mix of private and public, not shared ownership.", "3": "Private cloud serves a single organisation."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "community-cloud", "deployment-models"]}, {"id": "C1N-C-048", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A web application automatically adds servers when traffic rises and removes them when it falls, and the company pays only for what ran. Which cloud characteristic is being described?", "options": ["High availability", "File synchronisation", "Shared resources", "Rapid elasticity with metered, pay-as-you-go billing"], "answer": 1, "explanation": "Elasticity is the ability to grow and shrink capacity quickly, ideally automatically, in response to demand. Combined with metered billing it means the organisation stops paying for idle capacity, which is one of the strongest financial arguments for cloud. High availability is about surviving failures rather than matching demand, file sync is a consumer feature, and shared resources describe how the provider pools hardware rather than how the customer's capacity changes.", "distractor_analysis": {"1": "High availability keeps a service running through failures; it does not resize it.", "2": "File synchronisation is a storage feature.", "3": "Resource pooling is the provider-side mechanism, not the scaling behaviour."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "elasticity", "metered-billing", "characteristics"]}, {"id": "C1N-C-049", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A cloud provider states that a service is designed to keep running even if an entire data centre fails, by spreading it across several sites in a region. Which cloud characteristic does this describe?", "options": ["Metered utilisation", "Measured service", "High availability", "Rapid elasticity"], "answer": 2, "explanation": "High availability means a service stays reachable through hardware, network or site failures, usually expressed as an uptime percentage in a service level agreement. Providers achieve it by running redundant copies across availability zones and failing over automatically. Customers must still design their own applications to use those zones. Elasticity is about capacity, and metering and measured service are about tracking and billing consumption.", "distractor_analysis": {"1": "Elasticity scales capacity; it does not by itself survive a site failure.", "2": "Metered utilisation is billing by consumption.", "3": "Measured service is the monitoring that underpins metering."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "high-availability", "availability-zones", "characteristics"]}, {"id": "C1N-C-050", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A department's cloud bill was far higher than expected because a developer left several large test servers running over a weekend. Which cloud characteristic explains the surprise?", "options": ["Desktop virtualisation", "Metered utilisation, where every hour of running resources is charged", "High availability", "Shared resources"], "answer": 3, "explanation": "Cloud services meter consumption continuously: compute by the second or hour, storage by the gigabyte-month, data transfer by the gigabyte. Resources that are left running cost money whether or not anyone uses them, which is the opposite of owned hardware where the cost is fixed. Budgets, automatic shutdown schedules and billing alerts are the standard controls. The other options do not relate to how charges accrue.", "distractor_analysis": {"1": "High availability is about uptime, not billing.", "2": "Shared resources describe the provider's pooling.", "3": "Desktop virtualisation is a workload type, not a billing characteristic."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "metered-utilisation", "cost", "characteristics"]}, {"id": "C1N-C-051", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A company's laptops each hold a local copy of the shared documents folder, and edits made on one laptop appear on the others and in the web portal within seconds. Which cloud feature is this?", "options": ["Infrastructure as a Service", "Cloud bursting", "Multitenancy", "File synchronisation"], "answer": 1, "explanation": "File synchronisation services such as OneDrive, Google Drive and Dropbox keep a local copy of files on each device and push changes through the cloud to every other device and to the web interface. Technicians support these constantly: version conflicts when two people edit offline, selective sync to save disk space, and files on demand that download only when opened. The other terms describe infrastructure models rather than a file-level feature.", "distractor_analysis": {"1": "IaaS provides servers and storage, not a desktop sync client.", "2": "Cloud bursting is overflow of compute into a public cloud.", "3": "Multitenancy describes shared infrastructure between customers."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "storage"]}, {"id": "C1N-C-052", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user edited a spreadsheet on a laptop while offline on a flight while a colleague edited the same file in the office. On landing the sync client created a second copy with the user's name appended. What happened?", "options": ["The colleague deleted the file", "The laptop's disk was full", "A sync conflict occurred and the client preserved both versions rather than overwrite either", "The file was corrupted by the flight"], "answer": 2, "explanation": "When two devices change the same file before either syncs, the service cannot merge them automatically, so it keeps the server copy and saves the second as a conflicted copy named for the device or user. Someone then merges the changes by hand. Working in the web editor, or using file types that support real-time co-authoring, avoids this. The other explanations do not produce a second named copy.", "distractor_analysis": {"1": "Corruption produces an unreadable file, not a renamed duplicate.", "2": "A deletion would remove the file rather than duplicate it.", "3": "A full disk stops sync entirely instead of creating copies."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "conflict", "troubleshooting"]}, {"id": "C1N-C-053", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A cloud provider runs virtual machines for thousands of customers on the same physical servers, isolated from one another. Which term describes this arrangement?", "options": ["Rapid elasticity", "Multitenancy, built on shared pooled resources", "Private cloud", "Hybrid cloud"], "answer": 3, "explanation": "Resource pooling lets the provider treat thousands of servers as one pool, and multitenancy places many customers' workloads on that shared pool while keeping them logically separated by the hypervisor, networking and access controls. It is what makes public cloud economical. Customers who need dedicated hardware can pay for it, but the default is shared. Private and hybrid describe deployment models, and elasticity describes scaling.", "distractor_analysis": {"1": "Private cloud serves one organisation and is not shared.", "2": "Hybrid is a combination of environments.", "3": "Elasticity is about changing capacity, not sharing hardware."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "multitenancy", "shared-resources", "characteristics"]}, {"id": "C1N-C-054", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A company replaces its physical call-centre PCs with thin clients that connect to Windows desktops hosted and managed by a cloud provider on a per-user monthly fee. Which service model is this?", "options": ["Infrastructure as a Service (IaaS)", "Platform as a Service (PaaS)", "Storage as a Service", "Desktop as a Service (DaaS)"], "answer": 1, "explanation": "DaaS is virtual desktop infrastructure delivered as a cloud subscription. The provider hosts the desktop virtual machines, handles the platform, availability and often the patching, and users connect from thin clients, laptops or tablets. It suits seasonal staffing, contractors and remote workers because desktops can be added and removed quickly. IaaS would require the company to build the desktop platform itself, and the other models do not deliver desktops.", "distractor_analysis": {"1": "IaaS provides servers on which the company would have to build VDI itself.", "2": "PaaS is a developer runtime.", "3": "Storage as a Service provides capacity, not desktops."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "daas", "vdi", "service-models"]}, {"id": "C1N-C-055", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A start-up wants to avoid buying servers and prefers to rent capacity that can shrink if the business does not grow. Which advantage of cloud computing does this reflect?", "options": ["Elimination of the need for backups", "Immunity from outages", "Converting capital expenditure into operating expenditure with elastic capacity", "Guaranteed lower cost than owning hardware in every case"], "answer": 2, "explanation": "Buying servers is a large up-front capital cost for capacity you hope to use. Renting cloud resources spreads cost as a monthly operating expense that tracks actual use, and capacity can be released if plans change. That does not make cloud cheaper in all cases; steady, predictable workloads can be cheaper on owned hardware. Cloud customers still need backups of their own data, and providers do suffer outages, so those claims are wrong.", "distractor_analysis": {"1": "Cloud can cost more than owned hardware for constant, predictable loads.", "2": "Providers protect their infrastructure, not the customer's data from deletion or ransomware.", "3": "Cloud regions and services have well-publicised outages."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "capex-opex", "cost", "characteristics"]}, {"id": "C1N-C-056", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which statement correctly describes the shared responsibility model in cloud computing?", "options": ["Neither party is responsible for security in a public cloud", "The provider secures the underlying infrastructure while the customer secures their data, identities and configuration", "The provider is responsible for everything including the customer's passwords", "The customer must secure the provider's physical data centres"], "answer": 3, "explanation": "Cloud security is split. The provider protects the physical facilities, hardware, hypervisors and, depending on the service model, more of the stack; the customer is always responsible for their own data, user accounts, access permissions and how services are configured. Most cloud breaches trace to customer-side misconfiguration such as public storage buckets and weak identity controls, not to provider failures. Neither extreme position is correct.", "distractor_analysis": {"1": "Identity and access are always the customer's job.", "2": "Customers have no access to provider facilities.", "3": "Both parties carry defined responsibilities."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "shared-responsibility", "security"]}, {"id": "C1N-C-057", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "In which cloud service model does the customer carry the most responsibility for patching operating systems?", "options": ["Software as a Service", "Platform as a Service", "Desktop as a Service with a fully managed image", "Infrastructure as a Service"], "answer": 1, "explanation": "Responsibility shifts toward the provider as you move up the service models. In IaaS the customer installs and patches the guest operating system exactly as on a physical server; only the hypervisor and below belong to the provider. In PaaS the provider maintains the operating system and runtime, and in SaaS the customer touches no infrastructure at all. Managed DaaS offerings also patch the desktop image for the customer.", "distractor_analysis": {"1": "SaaS customers never see an operating system.", "2": "PaaS providers patch the platform beneath the customer's code.", "3": "Fully managed DaaS includes image maintenance."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "shared-responsibility", "patching"]}, {"id": "C1N-C-058", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user cannot open a document in the cloud file portal and sees a message that the file is currently being edited by another person. What does this indicate?", "options": ["The user's account has been suspended", "The internet connection has failed", "The service is enforcing a lock or co-authoring session to prevent conflicting edits", "The file has been deleted"], "answer": 2, "explanation": "Cloud document services either allow real-time co-authoring, where several people edit simultaneously and see each other's cursors, or place a lock on the file while one person has it open in a desktop application. The message tells the user which situation applies and usually offers to open a read-only copy or notify when the file is free. It is normal collaboration behaviour rather than a fault. The other options produce different, unrelated messages.", "distractor_analysis": {"1": "A deleted file reports not found, not in use.", "2": "A suspended account cannot sign in at all.", "3": "A failed connection cannot report who is editing."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "collaboration", "file-lock", "co-authoring"]}, {"id": "C1N-C-059", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A company migrates its email to a SaaS provider. Which support task remains the company's responsibility?", "options": ["Upgrading the mail server software to the next version", "Managing user accounts, licences, mailbox permissions and retention policies", "Replacing failed hard drives in the mail servers", "Patching the mail server operating system"], "answer": 3, "explanation": "With SaaS the provider owns the entire technology stack, so hardware, operating system and application upgrades disappear from the customer's task list. What remains is administration of the tenant: creating and removing users, assigning licences, setting sharing and retention policies, configuring security features such as multi-factor authentication, and supporting end users. Understanding this division helps technicians know which problems to fix and which to escalate to the provider.", "distractor_analysis": {"1": "Hardware belongs entirely to the provider.", "2": "The provider patches the platform.", "3": "Software versions are managed by the provider for all tenants."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "saas", "administration", "shared-responsibility"]}, {"id": "C1N-C-060", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "hard", "question": "An organisation moves an application to a public cloud and later finds that moving it to a different provider would require rewriting large parts of it. Which risk did it encounter?", "options": ["Rapid elasticity", "Multitenancy", "High availability", "Vendor lock-in through use of provider-specific services"], "answer": 1, "explanation": "Each provider offers proprietary managed services for databases, messaging, identity and serverless computing. Building on them speeds development but ties the application to that provider's interfaces, so leaving later is costly. Mitigations include using open standards and containers, keeping data in portable formats and negotiating exit terms. Elasticity, multitenancy and high availability are characteristics of cloud rather than risks of dependence.", "distractor_analysis": {"1": "Elasticity is a benefit, not a switching cost.", "2": "Multitenancy is how providers share hardware.", "3": "High availability is a resilience property."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "vendor-lock-in", "risk"]}, {"id": "C1N-C-061", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user reports that the cloud sync client shows a red cross on a folder and files are not uploading. What is the most useful first step?", "options": ["Delete the folder", "Turn off the firewall permanently", "Open the sync client's status view to read the specific error, such as a file name that is too long or a lack of storage quota", "Reinstall the operating system"], "answer": 2, "explanation": "Sync clients report why an item failed: path or file name too long, unsupported characters, a file locked by another program, quota exceeded or a sign-in that has expired. Reading that message directs the fix, which is usually renaming, shortening a path, freeing quota or re-authenticating. Reinstalling the operating system is wildly disproportionate, deleting the folder risks data, and disabling security is never the answer to a sync error.", "distractor_analysis": {"1": "A reinstall is unnecessary for a client-side sync error.", "2": "Deleting the folder may lose unsynced work.", "3": "Sync clients work through firewalls; disabling protection is unjustified."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "troubleshooting"]}, {"id": "C1N-C-062", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A company needs to keep its data within its own country for legal reasons while using a public cloud provider. Which capability should it look for?", "options": ["Free egress", "The ability to select a region so data is stored and processed in a specific geographic location", "Rapid elasticity", "A larger monthly bandwidth allowance"], "answer": 3, "explanation": "Public cloud providers operate regions around the world, and customers choose where each resource lives. Data residency or data sovereignty requirements are met by selecting regions inside the required jurisdiction and confirming that backups and support access follow the same rule. Elasticity, bandwidth and egress pricing are unrelated to where data resides. Technicians should know that choosing a region is a deliberate configuration decision, not a default.", "distractor_analysis": {"1": "Elasticity concerns capacity, not location.", "2": "Bandwidth allowances do not govern data location.", "3": "Egress pricing is about the cost of moving data out, not where it sits."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "data-residency", "regions", "compliance"]}, {"id": "C1N-C-063", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A cloud file service offers a feature where files show in the local folder but only download when opened. What is the main benefit and the main caution?", "options": ["It doubles the file's security and has no drawbacks", "It speeds up the processor and disables sync", "It compresses every file and prevents editing", "It saves local disk space, but files are unavailable when the device is offline unless marked to keep locally"], "answer": 1, "explanation": "Files on demand shows placeholder entries for the whole cloud library while storing only the files the user actually opens, which lets a laptop with a small SSD see terabytes of shared data. The caution is connectivity: a file that was never opened is not on the disk, so a user heading onto a plane must mark the folders they need as always available. It does not alter security, performance or the ability to edit.", "distractor_analysis": {"1": "Placeholders do not change security and do have the offline drawback.", "2": "The feature is about storage, not processor speed, and sync stays on.", "3": "Files are not compressed and remain fully editable."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "files-on-demand", "file-synchronisation", "offline"]}, {"id": "C1N-C-064", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A small business asks whether it should choose a public cloud or build a private cloud for a new customer-facing app with unpredictable growth. Which recommendation is most appropriate?", "options": ["Neither, because small businesses cannot use cloud services", "Private cloud, because public clouds cannot host web applications", "Public cloud, because it needs no capital investment and scales elastically with demand", "Private cloud, because it is always cheaper"], "answer": 2, "explanation": "A private cloud requires buying and running enough hardware for the peak you expect, which is exactly the wrong fit for a small company facing unknown demand. Public cloud lets it start small, pay by use and grow or shrink as the app's popularity dictates, with the provider handling the infrastructure. Private cloud makes sense where regulation or a steady, well-understood load justifies the investment, neither of which applies here.", "distractor_analysis": {"1": "Private cloud carries fixed capital and staffing costs.", "2": "Cloud services are widely used by businesses of every size.", "3": "Public clouds host a large share of the world's web applications."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "public-cloud", "decision", "small-business"]}, {"id": "C1N-C-065", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "hard", "question": "An organisation adopts a strategy of running workloads across two public cloud providers at the same time. What is this called and what is its main operational cost?", "options": ["Private cloud, which requires buying servers", "Multicloud, which increases complexity because staff must master two sets of tools and manage two bills", "Hybrid cloud, which requires an on-premises data centre", "Community cloud, which requires other organisations to join"], "answer": 3, "explanation": "Multicloud means deliberately using more than one public provider, typically to avoid lock-in, meet regional requirements or pick best-of-breed services. The price is operational: two consoles, two identity systems, two billing models and the network cost of moving data between them. It differs from hybrid, which pairs private infrastructure with public cloud; community and private clouds are ownership models unrelated to using several public vendors.", "distractor_analysis": {"1": "Hybrid involves private infrastructure; two public providers is multicloud.", "2": "Community cloud is shared among peer organisations.", "3": "Private cloud is single-organisation infrastructure."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "multicloud", "deployment-models"]}, {"id": "C1N-C-066", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A provider's service level agreement promises 99.9 percent monthly availability. Roughly how much downtime per month does that permit?", "options": ["About 7 hours", "About 3 days", "About 4 minutes", "About 44 minutes"], "answer": 1, "explanation": "A 30-day month has 43,200 minutes. One tenth of one percent of that is 43.2 minutes, so a 99.9 percent commitment allows roughly three quarters of an hour of downtime before the provider owes service credits. Each extra nine cuts the allowance by ten: 99.99 percent is about 4 minutes and 99 percent is about 7 hours. Technicians should be able to translate these figures when setting user expectations.", "distractor_analysis": {"1": "Seven hours corresponds to about 99 percent.", "2": "Three days would be roughly 90 percent availability.", "3": "Four minutes corresponds to 99.99 percent."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "sla", "availability", "uptime"]}, {"id": "C1N-C-067", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A company uses a cloud provider's storage to keep nightly backups of its on-premises servers. Which term best describes this use?", "options": ["Desktop as a Service", "Community cloud", "Storage as a Service used as an off-site backup target in a hybrid arrangement", "Software as a Service"], "answer": 2, "explanation": "Renting cloud storage as a destination for backups is one of the earliest and most common cloud uses. It gives geographic separation from the primary site at low cost, often with tiering to cheaper archive classes for older copies. Because the servers stay on premises and the backups go to a public cloud, the overall arrangement is hybrid. It is not SaaS, since no application is being consumed, nor DaaS, and the ownership model is public rather than community.", "distractor_analysis": {"1": "SaaS delivers applications, not raw backup capacity.", "2": "DaaS delivers hosted desktops.", "3": "Community cloud is a shared-ownership model."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "storage", "backup", "hybrid-cloud"]}, {"id": "C1N-C-068", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which cloud characteristic allows an administrator to create a new server in minutes through a web portal without contacting the provider?", "options": ["Vendor lock-in", "On-demand self-service", "Metered billing", "File synchronisation"], "answer": 3, "explanation": "On-demand self-service is a defining feature of cloud computing: resources are provisioned through a portal, command line or programming interface immediately, without a purchase order or a ticket to the provider. It is what allows the elasticity and speed that cloud is valued for, and also what makes cost control and governance necessary, because anyone with rights can create billable resources. The other options describe billing, a storage feature and a risk.", "distractor_analysis": {"1": "Metering is how usage is charged, not how it is requested.", "2": "File synchronisation is a data feature.", "3": "Lock-in is a risk of dependence, not a provisioning capability."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "self-service", "characteristics"]}, {"id": "C1N-C-069", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user complains that the company's cloud-based application is slow from the branch office but fast at headquarters. Which factor is the most likely cause?", "options": ["The cloud provider only supports one office per customer", "The application must be reinstalled at the branch", "The branch office lacks a local file server", "The branch office's internet connection has less bandwidth or higher latency to the provider"], "answer": 1, "explanation": "Cloud services depend entirely on the path between the user and the provider. A branch with a slower or congested link, or one that backhauls traffic through headquarters before it reaches the internet, will feel every extra millisecond. Measuring latency and throughput from the branch and considering a direct local internet breakout or a better circuit is the fix. Providers serve users from anywhere, SaaS applications are not installed, and a file server is unrelated.", "distractor_analysis": {"1": "Cloud services are reachable from any location.", "2": "Browser-based cloud applications are not installed per site.", "3": "A local file server does not affect access to a cloud application."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "performance", "latency", "troubleshooting"]}, {"id": "C1N-C-070", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A finance team wants a fixed, predictable monthly cost for a cloud server that runs constantly. Which purchasing option should the technician suggest?", "options": ["Spot or preemptible instances", "A free trial account", "A reserved or committed-use instance purchased for one or three years at a discount", "On-demand pricing billed by the second"], "answer": 2, "explanation": "Cloud providers offer several pricing models. On-demand is flexible but the most expensive per hour and varies with use. Reserved or committed-use pricing trades flexibility for a large discount and a predictable bill, which fits a server that runs all the time. Spot instances are cheap but can be reclaimed by the provider at short notice, so they suit interruptible batch work only, and trial accounts are for evaluation rather than production.", "distractor_analysis": {"1": "On-demand is the least predictable and most expensive for a constant workload.", "2": "Spot capacity can be taken away, unsuitable for an always-on server.", "3": "Trials expire and have usage limits."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "pricing", "reserved-instances", "cost"]}, {"id": "C1N-C-071", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A photographer wants every photo taken on a phone to appear automatically on a tablet and a laptop. Which cloud capability provides this?", "options": ["Cloud bursting", "Cloud file synchronisation across devices signed in to the same account", "Infrastructure as a Service", "A private cloud"], "answer": 3, "explanation": "Consumer cloud services synchronise a library across every device signed in to the account. The phone uploads each photo, and the tablet and laptop download it or show a placeholder that fetches on demand. Support issues include upload restricted to Wi-Fi, a full storage quota and a device signed in to a different account. Infrastructure services, private clouds and bursting are business infrastructure concepts that do not describe this feature.", "distractor_analysis": {"1": "IaaS is rented servers and storage for building systems.", "2": "A private cloud is single-organisation infrastructure.", "3": "Cloud bursting is overflow of compute capacity."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "photos", "consumer"]}, {"id": "C1N-C-072", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "hard", "question": "A company deletes a large amount of data from its cloud storage and is surprised that the bill for that month barely changed. Which billing characteristic explains this?", "options": ["Cloud storage is free after the first upload", "Deleted data continues to be charged forever", "The provider bills only on data uploaded, never on data stored", "Storage is billed per gigabyte-month, so data that existed for most of the month is still charged, and deleting it lowers the next bill instead"], "answer": 1, "explanation": "Metered storage pricing accumulates hour by hour or day by day. Data that sat in storage for three weeks is charged for those three weeks even if it is deleted on day twenty-two, so the saving shows up in the following month. Some archive tiers also charge early-deletion fees for data removed before a minimum period. Understanding the metering model prevents disputes with finance and helps plan clean-ups.", "distractor_analysis": {"1": "Storage is charged continuously, not just at upload.", "2": "Charges stop once the data is gone, apart from any early-deletion fee.", "3": "Providers bill for capacity held over time, not only for ingestion."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "metered-utilisation", "storage", "billing"]}, {"id": "C1N-C-073", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A retailer's website is hosted on IaaS virtual machines. During a sale the site becomes slow. Which cloud capability should the technician recommend to prevent this in future?", "options": ["Ask customers to shop at quieter times", "Disable HTTPS to reduce processing load", "Configure autoscaling so additional instances start automatically when load rises", "Move the site to a single larger server permanently"], "answer": 2, "explanation": "Autoscaling ties rapid elasticity to measured load: when CPU or request rates cross a threshold, the platform launches more instances behind a load balancer and removes them when demand falls, so the retailer pays for peak capacity only during the peak. A permanently larger server wastes money for most of the year and still has a ceiling, telling customers to wait loses sales, and removing encryption is a security failure that saves almost nothing.", "distractor_analysis": {"1": "Fixed oversizing is expensive and still has a hard limit.", "2": "Restricting customers defeats the purpose of the sale.", "3": "HTTPS is essential for a shop and its cost is negligible."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "autoscaling", "elasticity", "iaas"]}, {"id": "C1N-C-074", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A user's laptop was stolen. The user's documents were all in a synchronised cloud folder. What should the technician do first regarding that data?", "options": ["Nothing, because cloud files cannot be accessed from a stolen laptop", "Sign the stolen device out of the cloud account remotely and confirm the files are intact in the web portal", "Assume the files are gone and start recreating them", "Delete the files from the cloud so the thief cannot see them"], "answer": 3, "explanation": "Synchronised files exist in the cloud as well as on the laptop, so the data is recoverable to any new device. The immediate risk is the thief using the still-signed-in laptop, so the account's device list should be used to revoke that device's access and the password changed. The files themselves stay safe in the portal. Deleting them would destroy the good copy, and a signed-in laptop can absolutely reach cloud data until access is revoked.", "distractor_analysis": {"1": "The cloud copy makes recreation unnecessary.", "2": "Deletion removes the legitimate copy; revoking access is the right control.", "3": "A stolen laptop that stays signed in remains a live access path."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "security", "lost-device"]}, {"id": "C1N-C-075", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which of these is an example of Platform as a Service rather than Infrastructure as a Service?", "options": ["A virtual machine on which the customer installs a database engine", "A block storage volume attached to a virtual machine", "A virtual private network the customer configures", "A managed database service where the provider handles the operating system, patching and backups and the customer only creates tables"], "answer": 1, "explanation": "The dividing line is who manages the operating system and middleware. A managed database exposes only the database itself, with the provider running everything beneath it, which is a platform service. A virtual machine, an attached disk and a virtual network are infrastructure components the customer must configure and maintain. Recognising the model tells a technician what they can fix themselves and what only the provider can touch.", "distractor_analysis": {"1": "Installing software on a virtual machine is classic IaaS.", "2": "Block storage is raw infrastructure.", "3": "Customer-configured networking is infrastructure."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "paas", "iaas", "service-models"]}, {"id": "C1N-C-076", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "multi", "difficulty": "medium", "question": "Which TWO are essential characteristics of cloud computing as generally defined? (Select TWO.)", "options": ["Rapid elasticity, so capacity can grow and shrink quickly with demand", "Measured service, so usage is monitored and billed by consumption", "A requirement that all data be stored on the customer's premises", "Fixed capacity purchased years in advance", "Manual provisioning through a paper request to the provider"], "answers": [0, 1], "explanation": "The widely used definition of cloud computing lists on-demand self-service, broad network access, resource pooling, rapid elasticity and measured service. Elasticity and metering are two of those five and together explain why cloud costs track usage. Storing data on premises, buying fixed capacity in advance and requesting resources on paper are characteristics of traditional infrastructure procurement, the very things cloud replaces.", "distractor_analysis": {"2": "Cloud data is stored in the provider's facilities, not the customer's.", "3": "Fixed advance capacity is the opposite of elasticity.", "4": "Self-service provisioning is a defining cloud trait."}, "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "characteristics", "elasticity", "measured-service"]}, {"id": "C1N-C-077", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "multi", "difficulty": "medium", "question": "A company is deciding whether to move a legacy application to a public cloud. Which TWO considerations argue for keeping it on premises? (Select TWO.)", "options": ["The application handles data that regulation requires to stay within the company's own facilities", "The application runs at a constant, predictable load around the clock and existing hardware is already paid for", "The application's demand spikes unpredictably several times a year", "The company has no data centre staff", "The company wants to stop paying for hardware refreshes"], "answers": [0, 1], "explanation": "Cloud is not automatically the right answer. Strict data-location rules can make a public cloud unusable for a workload, and a steady, always-on load on hardware that is already owned can be cheaper to keep than to rent, because cloud's advantage is paying for variable use. The other three points, unpredictable spikes, lack of staff and wanting to avoid hardware refreshes, are classic reasons to move to the cloud rather than to stay.", "distractor_analysis": {"2": "Unpredictable spikes are exactly what elastic cloud capacity handles well.", "3": "Lack of staff favours letting a provider run the infrastructure.", "4": "Avoiding hardware refreshes is a reason to rent rather than own."}, "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "decision", "on-premises", "compliance"]}, {"id": "C1N-C-078", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "match", "difficulty": "medium", "question": "Match each cloud service model to the example that fits it.", "pairs": [{"left": "IaaS", "right": "Renting virtual machines and installing your own operating system"}, {"left": "PaaS", "right": "Deploying application code to a managed runtime with a managed database"}, {"left": "SaaS", "right": "Using web-based email and office applications by subscription"}, {"left": "DaaS", "right": "Streaming a hosted Windows desktop to a thin client"}], "explanation": "The service models describe how much of the stack the provider manages. IaaS stops at the hypervisor, PaaS extends through the operating system and runtime, SaaS covers the whole application, and DaaS delivers a complete desktop. A technician who can place a service in the right model knows immediately whether an issue is theirs to fix or belongs with the provider.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "service-models", "match"]}, {"id": "C1N-C-079", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "match", "difficulty": "medium", "question": "Match each cloud deployment model to its description.", "pairs": [{"left": "Public", "right": "Provider-owned infrastructure shared by many unrelated customers"}, {"left": "Private", "right": "Infrastructure dedicated to a single organisation"}, {"left": "Hybrid", "right": "Private infrastructure connected to public cloud services"}, {"left": "Community", "right": "Infrastructure shared by a defined group with common requirements"}], "explanation": "Deployment models describe who owns and shares the infrastructure. Public is the shared utility model, private is dedicated to one organisation, hybrid links the two so workloads can move between them, and community is a club of like-minded organisations pooling a platform that meets their shared rules. Ownership drives cost, compliance and control, so it is usually the first decision in a cloud strategy.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "deployment-models", "match"]}, {"id": "C1N-C-080", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "order", "difficulty": "medium", "question": "Order the steps a technician should follow to help a user recover a document that was accidentally deleted from a synchronised cloud folder.", "sequence": ["Confirm the file is missing from the local folder and from the web portal", "Check the cloud service's recycle bin or deleted items and restore the file from there", "If the file is not in the recycle bin, use version history or the administrator's restore tools within the retention window", "Verify the restored file has synchronised back to the user's devices", "Explain to the user how deletion propagates across synced devices to prevent a repeat"], "explanation": "Synchronisation propagates a deletion everywhere, which alarms users, but cloud services keep deleted items for a retention period and maintain version histories. Checking the portal confirms the scope, the recycle bin recovers most cases in seconds, and administrator tools cover the rest within the retention window. Confirming the file has returned to the devices closes the loop, and a short explanation reduces the chance of the same call next week.", "video_reference": {"title": "Cloud Characteristics - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=XzNnFbY0dMQ", "duration": "6:50", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "file-synchronisation", "recovery", "procedure"]}, {"id": "C1N-V-001", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A datacenter infrastructure engineer is deploying a cluster of high-density blade servers to host hundreds of production virtual machines. The design requires minimal hypervisor overhead and direct control of the underlying physical hardware without an intermediate operating system. Which virtualization architecture meets these requirements?", "explanation": "A Type 1 bare-metal hypervisor (such as VMware ESXi, Microsoft Hyper-V Server, or KVM) installs directly on the host server hardware without requiring a underlying host operating system. This provides maximum I/O performance, lower latency, and reduced resource overhead for enterprise datacenter workloads. A Type 2 hypervisor relies on a host OS, introducing latency and resource contention. Container engines share the host kernel rather than provisioning full hardware-isolated VMs. Software instruction emulation incurs heavy translation overhead.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "hypervisor", "type-1", "datacenter"], "options": ["Type 1 bare-metal hypervisor installed directly on the physical host hardware", "Type 2 hosted hypervisor running as an application on a general-purpose host OS", "Kernel-based application virtualization container engine with user-mode drivers", "Software-emulated instruction translation layer executing within a guest workspace"], "answer": 0, "distractor_analysis": {"1": "Type 2 hosted hypervisors execute on top of a general-purpose host OS, introducing additional latency, security surface, and memory overhead unsuitable for high-density production blades.", "2": "Container engines provide OS-level isolation sharing a single kernel, but do not provide direct hardware hypervisor abstraction for varied guest operating systems.", "3": "Software instruction translation emulates CPU architectures via software routines, causing severe performance degradation compared to bare-metal execution."}}, {"id": "C1N-V-002", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A systems administrator is configuring a virtual switch on a production hypervisor host that connects to dual 25GbE physical uplinks. The host must isolate management traffic, live VM migration traffic, and tenant production networks while utilizing the same physical interfaces. Which networking technology should the administrator configure on the virtual switch port groups?", "explanation": "IEEE 802.1Q VLAN tagging allows multiple logical networks (management, vMotion/live migration, storage, and tenant VLANs) to share trunked physical network adapters on the hypervisor host while maintaining complete Layer 2 traffic isolation. Static NAT provides Layer 3 address translation rather than Layer 2 network segmentation. Proxy ARP allows a router to answer ARP requests for remote networks but does not segment hypervisor traffic. Port mirroring copies packets for traffic analysis and does not isolate networks.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "vswitch", "vlan", "802.1q"], "options": ["IEEE 802.1Q VLAN tagging on distinct port groups", "Static NAT rules for every tenant virtual machine interface", "Proxy ARP forwarding across the physical NIC team", "Port mirroring on the hypervisor uplink switch ports"], "answer": 0, "distractor_analysis": {"1": "Static NAT operates at Layer 3 to translate IP addresses and does not provide hypervisor-level broadcast isolation or multi-network trunking.", "2": "Proxy ARP resolves MAC addresses on behalf of remote subnets and does not create segregated traffic planes for management or migration.", "3": "Port mirroring duplicates packets to a monitoring probe or sniffer and does not logically isolate VM traffic streams."}}, {"id": "C1N-V-003", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "A technician is setting up a new multi-socket physical server to run hardware-accelerated 64-bit guest virtual machines. When launching the hypervisor installation, the setup wizard halts with an error stating hardware virtualization extensions are unavailable. Which system firmware setting must the technician enable?", "explanation": "Intel VT-x and AMD-V are hardware virtualization extensions implemented in the CPU and exposed through UEFI/BIOS firmware settings. Enabling them provides hardware support for hypervisors to run guest operating systems with near-native execution efficiency. Secure Boot validates signed bootloader binaries but does not provide CPU virtualization extensions. PCIe power management regulates bus link power states. TPM 2.0 provides cryptographic measurement and key storage.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "cpu", "uefi", "vt-x"], "options": ["Intel VT-x or AMD-V in the system UEFI firmware", "Secure Boot custom certificate revocation list", "PCIe Active State Power Management in power profiles", "TPM 2.0 platform hierarchy authentication keys"], "answer": 0, "distractor_analysis": {"1": "Secure Boot verifies digital signatures of boot components during startup and does not enable CPU virtualization extensions.", "2": "PCIe power management controls link power states and has no bearing on processor virtualization features.", "3": "TPM 2.0 provides hardware-based security keys and measured boot capabilities, but is not responsible for CPU hypervisor instruction sets."}}, {"id": "C1N-V-004", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A software development team wants to deploy lightweight, microservice-based applications that start in milliseconds and share the host operating system kernel without running a full guest OS for each instance. Which technology should the infrastructure team implement?", "explanation": "Application containerization (such as Docker or Podman) isolates applications using host OS kernel features like control groups (cgroups) and namespaces. Containers share the underlying host operating system kernel, making them extremely lightweight, fast to instantiate, and resource-efficient compared to full virtual machines. Type 1 virtualization runs separate guest operating systems with dedicated kernels and memory spaces. Hardware emulation creates simulated hardware through software routines. VDI provides complete desktop environments to end users.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "containers", "docker", "microservices"], "options": ["Application containerization using cgroups and namespaces", "Type 1 bare-metal virtualization with thick-provisioned disks", "Hardware emulation via an instruction set translation engine", "Virtual Desktop Infrastructure with persistent user profiles"], "answer": 0, "distractor_analysis": {"1": "Type 1 hypervisors boot complete independent guest operating systems, each requiring its own kernel, memory footprint, and storage allocations.", "2": "Hardware emulation translates CPU instructions between architectures in software, which is significantly slower than kernel containerization.", "3": "Virtual Desktop Infrastructure delivers full interactive desktop operating system sessions to remote clients, which does not fit lightweight microservices."}}, {"id": "C1N-V-005", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A datacenter lab technician needs to configure a test environment where a virtualized Hyper-V or ESXi hypervisor runs inside a parent virtual machine to validate cluster failover scripts without purchasing additional hardware. What feature must be enabled on the parent VM's CPU configuration?", "explanation": "Nested virtualization exposes hardware-assisted virtualization extensions (Intel VT-x / AMD-V) from the physical CPU through the parent hypervisor into the guest virtual machine. This allows the guest VM to install and run its own hypervisor layer to spawn child virtual machines. Memory ballooning reclaims idle RAM across VMs but does not expose CPU virtualization instructions. SR-IOV bypasses the virtual switch for physical NIC performance. NUMA spanning balances memory access across CPU sockets.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "nested-virtualization", "hypervisor"], "options": ["Nested virtualization hardware extension pass-through", "Dynamic memory ballooning with unreserved swap space", "SR-IOV direct physical adapter device assignment", "NUMA node spanning across multiple socket domains"], "answer": 0, "distractor_analysis": {"1": "Memory ballooning allows the hypervisor to reclaim unused memory from guest OSes, but does not provide nested CPU instruction pass-through.", "2": "Single Root I/O Virtualization (SR-IOV) enables direct PCIe access for network adapters to reduce packet latency, not nested hypervisor execution.", "3": "NUMA node spanning controls how virtual memory maps across physical CPU memory controllers and does not enable hypervisors inside VMs."}}, {"id": "C1N-V-006", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "multi", "difficulty": "medium", "question": "A storage architect is designing the backend SAN connectivity for a production hypervisor cluster to support high-availability VM shared storage and live migration. Which TWO block-level storage protocol options are commonly used to attach shared LUNs across the hypervisor cluster? (Select TWO.)", "explanation": "iSCSI and Fibre Channel (FC) are standard enterprise block-level storage protocols used to connect hypervisor hosts to Storage Area Networks (SANs). iSCSI encapsulates SCSI commands in IP packets over standard Ethernet, while Fibre Channel uses dedicated optical switches and host bus adapters (HBAs) to present block LUNs for clustered VM datastores. SMB 1.0 is an obsolete and insecure file-level protocol. SNMPv3 is a network monitoring protocol. NTP is a network time synchronization protocol.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "san", "iscsi", "fibre-channel"], "options": ["iSCSI over standard Gigabit or 10GbE IP networks", "Fibre Channel over dedicated optical storage fabrics", "Server Message Block (SMB 1.0) over legacy NetBIOS", "Simple Network Management Protocol (SNMPv3)", "Network Time Protocol (NTP) over UDP port 123"], "answers": [0, 1], "distractor_analysis": {"2": "SMB 1.0 is a legacy, insecure file-sharing protocol that is deprecated and does not provide enterprise SAN block-level storage access.", "3": "SNMPv3 is a management protocol used to query device health, metrics, and trap alerts, not a storage protocol.", "4": "NTP synchronizes clock time across network nodes using UDP port 123 and does not transmit storage commands or data blocks."}}, {"id": "C1N-V-007", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "match", "difficulty": "hard", "question": "You are writing the onboarding notes for a new datacenter technician who has never worked with hypervisors. Match each virtualization component to its correct operational description.", "explanation": "A Type 1 hypervisor runs directly on the bare-metal physical host. A Type 2 hypervisor runs as an application atop a standard host operating system. A Virtual Switch provides Layer 2 forwarding and VLAN isolation inside the hypervisor. A Container Engine utilizes kernel namespaces and control groups to run lightweight isolated processes sharing one kernel. A Virtual Disk Image (such as VHDX or VMDK) encapsulates the complete guest OS storage subsystem into a portable file.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "components", "hypervisor", "architecture"], "pairs": [{"left": "Type 1 Hypervisor", "right": "Executes directly on bare-metal server hardware with no intermediary host OS"}, {"left": "Type 2 Hypervisor", "right": "Runs as an application inside an existing host operating system"}, {"left": "Virtual Switch", "right": "Provides Layer 2 packet forwarding and VLAN segmentation between VMs on a host"}, {"left": "Container Engine", "right": "Shares the host OS kernel to run isolated user-space application processes"}, {"left": "Virtual Disk Image", "right": "Encapsulates the guest VM file system and partitions into a VHDX or VMDK file"}]}, {"id": "C1N-V-008", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "An administrator notices that the total provisioned virtual RAM allocated to all active VMs on a hypervisor host exceeds the physical RAM installed in the host chassis, yet the VMs continue operating normally without paging to disk. Which hypervisor resource management technique makes this possible?", "explanation": "Memory overcommitment (supported by techniques like transparent page sharing, memory ballooning, and deduplication) allows a hypervisor to allocate more virtual memory to guest machines than the physical RAM installed in the server. Because VMs rarely consume 100 percent of their allocated memory simultaneously, identical pages are shared and unused pages remain unbacked by physical memory. DMA multiplexing is a bus protocol. NVRAM caching accelerates storage writes. Asymmetric multiprocessing assigns specific tasks to different CPUs.", "video_reference": {"title": "Virtualization Concepts - CompTIA A+ 220-1201 - 4.1", "url": "https://www.youtube.com/watch?v=xXOIdDWUNGU", "duration": "5:45", "objective": "4.1"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["virtualization", "memory", "resource-management"], "options": ["Memory overcommitment and transparent page sharing", "Direct Memory Access hardware channel multiplexing", "Static non-volatile RAM cache write-back flushing", "Asymmetric multiprocessing task offloading"], "answer": 0, "distractor_analysis": {"1": "Direct Memory Access (DMA) allows peripherals to communicate directly with memory and does not handle virtual memory overcommit allocations.", "2": "Non-volatile RAM write caching preserves unwritten disk blocks during power outages and does not manage hypervisor host RAM oversubscription.", "3": "Asymmetric multiprocessing is an OS scheduling model distributing tasks unevenly across processors, unrelated to memory overcommitment."}}, {"id": "C1N-V-009", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A company migrates its on-premises customer relationship management software to Salesforce. The cloud service provider manages the physical infrastructure, operating systems, database servers, and application updates, while the company only configures user accounts and business data. Which cloud service model is being utilized?", "explanation": "Software as a Service (SaaS) delivers complete end-user applications over the internet where the cloud provider manages all underlying hardware, networking, operating systems, patches, and middleware. The client is only responsible for managing their application data and user access. IaaS provides raw compute, storage, and networking where the client installs and manages the OS. PaaS provides a runtime environment and database tools for developers. DaaS delivers virtualized desktop operating systems.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "saas", "service-models"], "options": ["Software as a Service (SaaS)", "Infrastructure as a Service (IaaS)", "Platform as a Service (PaaS)", "Desktop as a Service (DaaS)"], "answer": 0, "distractor_analysis": {"1": "IaaS provides bare compute instances, block storage, and virtual networking, leaving the customer responsible for installing and patching the OS and applications.", "2": "PaaS provides a framework and runtime engine for developers to build applications without managing OS patching, but does not provide turnkey business applications.", "3": "DaaS delivers full virtualized desktop workspaces to end-user client devices, not a specialized browser-accessible web application."}}, {"id": "C1N-V-010", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A financial institution maintains strict compliance policies requiring customer transactional records to remain in an on-premises air-gapped datacenter. However, the bank uses a public cloud provider to run resource-intensive AI analytics on anonymized data models. Which cloud deployment model describes this environment?", "explanation": "A hybrid cloud combines private (on-premises datacenter) infrastructure with public cloud resources, linked by secure networking (such as IPsec VPN or dedicated Direct Connect circuits) to enable data and application portability while meeting compliance and elasticity requirements. A private cloud is dedicated entirely to a single organization. A public cloud provides shared resources open to the public. A community cloud shares infrastructure among multiple organizations with common regulatory or mission objectives.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "hybrid-cloud", "deployment-models"], "options": ["Hybrid cloud", "Community cloud", "Private cloud", "Public cloud"], "answer": 0, "distractor_analysis": {"1": "Community cloud refers to shared infrastructure pooled across distinct organizations with shared compliance or security mandates (e.g., government agencies).", "2": "Private cloud exists solely for a single organization behind their own firewall or dedicated facility, without public cloud resource integration.", "3": "Public cloud infrastructure is owned and operated entirely off-premises by a third-party multi-tenant provider."}}, {"id": "C1N-V-011", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "hard", "question": "An e-commerce website experiences massive traffic spikes during annual holiday flash sales. The operations team configures auto-scaling groups to automatically spin up additional virtual server instances when CPU utilization exceeds 75% and terminate them when traffic subsides. Which cloud computing characteristic is demonstrated?", "explanation": "Rapid elasticity is the ability of cloud computing systems to automatically scale resources out (adding instances) and scale in (removing instances) dynamically in response to real-time workload demand. Measured service refers to tracking resource consumption for billing and metering. Resource pooling describes the provider dynamically assigning multi-tenant physical resources to multiple consumers. Broad network access means services are accessible over standard network mechanisms from diverse client devices.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "elasticity", "auto-scaling", "characteristics"], "options": ["Rapid elasticity", "Measured service", "Resource pooling", "Broad network access"], "answer": 0, "distractor_analysis": {"1": "Measured service refers to tracking metrics (bandwidth, compute hours, storage) for metering and cost accounting, not dynamic capacity scaling.", "2": "Resource pooling describes how the cloud provider pools physical compute and storage across multiple tenants using virtualization abstraction.", "3": "Broad network access ensures services are available across the network via standard protocols and thin/thick client platforms."}}, {"id": "C1N-V-012", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "In the cloud shared responsibility model for an Infrastructure as a Service (IaaS) deployment, which task remains the sole responsibility of the customer rather than the cloud service provider?", "explanation": "In an IaaS deployment, the cloud service provider is responsible for the security 'of' the cloud (physical datacenter security, power, environmental controls, physical servers, hypervisors, and core networking). The customer is responsible for security 'in' the cloud, including the guest operating system installation, OS security patches, network firewall rules, middleware, and application data. Physical drive replacement, router firmware, and facility security are all provider responsibilities.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "iaas", "shared-responsibility", "security"], "options": ["Applying security patches to the guest operating system", "Replacing failed physical hard drives in storage arrays", "Upgrading the firmware on the physical datacenter core routers", "Maintaining physical access security and biometric controls at the facility"], "answer": 0, "distractor_analysis": {"1": "The cloud provider owns and maintains all physical hardware, including replacing failed storage drives in SAN arrays.", "2": "Physical network infrastructure, switches, and edge router firmware are managed exclusively by the cloud provider.", "3": "Physical datacenter perimeter security, guards, and biometric controls are solely the responsibility of the cloud facility operator."}}, {"id": "C1N-V-013", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "multi", "difficulty": "hard", "question": "A company is planning a migration to public cloud infrastructure and wants to ensure their financial governance model aligns with cloud economics. Which TWO essential cloud characteristics define how resource consumption is tracked and automatically billed? (Select TWO.)", "explanation": "Measured service and On-demand self-service are two NIST-defined essential characteristics of cloud computing. Measured service allows cloud systems to automatically control, monitor, and optimize resource usage through metering (compute hours, storage gigabytes, bandwidth) providing transparent pay-as-you-go billing. On-demand self-service empowers consumers to unilaterally provision computing capabilities as needed without human interaction from the service provider. Fixed Capex, static air-gapping, and multi-week manual ticketing contradict cloud elasticity and operational agility.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "characteristics", "nist", "measured-service"], "options": ["Measured service where resource usage is monitored and billed on actual consumption", "On-demand self-service allowing users to provision resources without human provider interaction", "Fixed-rate capital expenditure licensing requiring five-year hardware amortization", "Static perimeter network air-gapping preventing internet connectivity", "Manual ticketing provisioning with mandatory multi-week lead times"], "answers": [0, 1], "distractor_analysis": {"2": "Cloud shifts IT spending from Capital Expenditure (CapEx) to Operational Expenditure (OpEx), avoiding long-term physical hardware amortization.", "3": "Air-gapping isolates networks completely, whereas cloud relies on broad network access and defined security boundary controls.", "4": "Manual multi-week provisioning queues represent legacy IT operational bottlenecks that cloud on-demand automation eliminates."}}, {"id": "C1N-V-014", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "easy", "question": "A medical clinic deploys low-power thin client terminals at examination rooms. The terminals do not run local operating systems or store patient files locally; instead, each terminal connects to a virtual desktop running Windows 11 in a centralized datacenter. Which cloud solution is implemented?", "explanation": "Virtual Desktop Infrastructure (VDI) or Desktop as a Service (DaaS) hosts desktop operating system environments inside virtual machines on centralized datacenter servers. End users interact with their desktops via thin clients or remote display protocols (such as RDP, Citrix HDX, or VMware Blast). Storage as a Service provides object or file storage. PaaS provides application runtimes for developers. FaaS executes serverless code in response to events.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "vdi", "daas", "thin-client"], "options": ["Virtual Desktop Infrastructure (VDI) / Desktop as a Service (DaaS)", "Storage as a Service (STaaS) object bucket repository", "Platform as a Service (PaaS) web application container", "Function as a Service (FaaS) serverless event trigger"], "answer": 0, "distractor_analysis": {"1": "Storage as a Service provides raw file or object repositories (e.g., S3 buckets) and does not host interactive user desktop operating systems.", "2": "PaaS provides development stacks, database runtimes, and APIs for building software, not end-user desktop interfaces.", "3": "Function as a Service runs ephemeral code blocks upon specific triggers (serverless compute) without persistent user interface sessions."}}, {"id": "C1N-V-015", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A datacenter administrator is establishing an off-site cloud backup repository for historical database snapshots that must be retained for seven years for regulatory audits. The files will rarely be accessed, but low storage cost per terabyte is critical. Which cloud storage tier should the administrator select?", "explanation": "Archive (or Glacier/Cold) storage tiers offer the lowest storage cost per terabyte for rarely accessed data, making them ideal for long-term compliance and historical backup retention. In exchange for low storage pricing, data retrieval takes minutes to hours and carries egress/retrieval fees. Hot storage is designed for frequently accessed data with higher per-gigabyte costs. High-IOPS instance store is volatile, high-performance local storage. In-memory caching uses RAM for ultra-fast transient queries.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "storage-tiers", "archive", "backup"], "options": ["Archive / Glacier cold storage tier", "Hot / standard low-latency block storage tier", "High-IOPS solid-state drive instance store", "In-memory caching cluster repository"], "answer": 0, "distractor_analysis": {"1": "Hot standard storage is optimized for frequent read/write access with low retrieval latency, carrying significantly higher monthly storage costs.", "2": "High-IOPS SSD instance storage is high-cost, high-speed local ephemeral storage attached directly to a compute node, not suitable for long-term archiving.", "3": "In-memory caching stores active data in volatile RAM for sub-millisecond application responses and is cost-prohibitive for 7-year retention."}}, {"id": "C1N-V-016", "exam": "core1", "domain": "4.0 Virtualization and Cloud Computing", "objective": "4.2", "type": "order", "difficulty": "medium", "question": "Order the standard phases for migrating an on-premises line-of-business application to a public cloud infrastructure.", "explanation": "A structured cloud migration follows a phased lifecycle: (1) Discovery and dependency mapping to understand application requirements, (2) Architectural network and security design (VPCs, subnets, firewall rules), (3) Initial data and VM replication to cloud storage, (4) Pilot testing and validation drills to ensure operational stability, and (5) Final delta synchronization followed by DNS cutover to redirect live users to the cloud environment.", "video_reference": {"title": "Cloud Models - CompTIA A+ 220-1201 - 4.2", "url": "https://www.youtube.com/watch?v=KZxAY5ssUxc", "duration": "9:48", "objective": "4.2"}, "notes_reference": "14_Virtualization_and_Cloud.md", "tags": ["cloud", "migration", "lifecycle", "planning"], "sequence": ["Perform asset discovery and map on-premises application dependencies and resource requirements", "Design cloud network topology, VPC subnets, routing tables, and security groups", "Replicate database data and server images to cloud storage endpoints", "Execute pilot test validation and perform non-disruptive failover drills in the cloud environment", "Perform final delta synchronization, update public DNS records, and cut over production traffic"]}, {"id": "C1N-V-017", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A mobile field engineer reports that their company laptop trackpad has lifted above the palmrest, the lower chassis is bulging, and the device clicks inconsistently. What is the root cause and immediate safety procedure?", "explanation": "A swollen lithium-ion battery is a hazardous condition caused by gas buildup from internal cell degradation or thermal runaway. The expanding battery pushes upward against the trackpad and palmrest. The immediate action is to safely shut down the laptop, disconnect external AC power, avoid puncturing the battery, and replace it following hazardous materials disposal procedures. Tightening screws on a swollen battery risks puncturing cells and causing fire. Fan or SSD issues do not create physical chassis bulging.", "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "battery", "safety"], "options": ["The lithium-ion battery has swollen; immediately power down the laptop, disconnect AC power, and replace the battery safely", "The trackpad mounting screws have backed out; tighten the Phillips screws from underneath the motherboard", "The cooling fan has seized; clean the exhaust fins with compressed air to relieve thermal pressure", "The NVMe SSD is overheating; install a thermal pad between the drive and the bottom casing"], "answer": 0, "distractor_analysis": {"1": "Tightening screws or pressing down on a bulging chassis can puncture the lithium pouch, triggering a violent thermal fire.", "2": "A seized cooling fan causes thermal throttling and system shutdowns, but does not physically deform the trackpad or chassis.", "3": "An overheating NVMe SSD causes read/write throttling or storage errors, not mechanical chassis swelling."}}, {"id": "C1N-V-018", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "A technician is replacing a broken 15.6-inch IPS display panel on a modern corporate laptop. After securing the new panel to the display hinges, the technician must reconnect the delicate cable running from the motherboard into the LCD panel. What standard internal connector type is used for this display connection?", "explanation": "Modern laptop display panels connect to the system motherboard using an embedded DisplayPort (eDP) or LVDS micro-coaxial cable connector. eDP is the industry standard for internal laptop displays, supporting high refresh rates, high color depth, and integrated backlight power in a compact latching connector. Mini-DVI is a legacy external video port. SATA connects storage drives. Molex 4-pin is a desktop power connector.", "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "laptop", "display", "edp"], "options": ["Embedded DisplayPort (eDP) micro-coaxial connector", "Mini-DVI ribbon connector with analog RGB pins", "Serial ATA 7-pin data latching header", "Molex 4-pin peripheral power harness"], "answer": 0, "distractor_analysis": {"1": "Mini-DVI is an obsolete external video connector from older Apple laptops and is never used internally between a laptop motherboard and LCD panel.", "2": "SATA 7-pin data cables connect storage drives and lack the pins and signaling required for raw digital video panels.", "3": "Molex 4-pin connectors are large legacy desktop PSU power cables, completely absent in compact laptop display assemblies."}}, {"id": "C1N-V-019", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A workstation refresh requires a single-cable docking solution for laptops that can deliver 100W USB Power Delivery (USB PD), drive two external 4K monitors at 60Hz, carry Gigabit Ethernet, and connect high-speed NVMe external storage up to 40 Gbps. Which connection standard meets these requirements?", "explanation": "Thunderbolt 4 (and USB4) utilizes the reversible USB Type-C connector to deliver up to 40 Gbps bidirectional bandwidth, support dual 4K/60Hz video streams (DisplayPort Alternate Mode), tunnel PCIe data for high-speed NVMe storage, provide Gigabit Ethernet connectivity, and deliver up to 100W (or 240W in Extended Power Range) USB Power Delivery over a single cable. USB 2.0 maxes out at 480 Mbps without native video. eSATA only carries storage data. Micro-USB 3.0 maxes at 5 Gbps without power delivery or display alt-modes.", "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "usb-c", "thunderbolt"], "options": ["Thunderbolt 4 / USB4 over a Type-C connector", "USB 2.0 HighSpeed over a Type-A connector", "eSATA with external DC power transformer", "Micro-USB 3.0 Type-B SuperSpeed connector"], "answer": 0, "distractor_analysis": {"1": "USB 2.0 Type-A provides a maximum bandwidth of 480 Mbps and 2.5W power, lacking the bandwidth or alternate modes for dual 4K monitors or docking.", "2": "eSATA is an external SATA storage interface that does not carry native video signals, Ethernet, or laptop charging power.", "3": "Micro-USB 3.0 is a legacy mobile device connector limited to 5 Gbps data and basic 5V charging without display tunneling."}}, {"id": "C1N-V-020", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "An IT security department implements a Bring Your Own Device (BYOD) policy for mobile phones. The policy requires enforcing PIN complexity, encrypting corporate email, and permitting IT to wipe corporate data upon employee termination without deleting personal family photos or personal applications. Which solution must be deployed?", "explanation": "Mobile Application Management (MAM) and enterprise containerization (such as Android Enterprise Work Profile or Apple User Enrollment) isolate corporate applications and encrypted data in a secure container separate from the personal space. This enables IT to selectively wipe corporate data, enforce passcodes, and control email sync without affecting personal photos, texts, or personal apps. Full firmware flashing or full factory wipes delete all personal data. MAC filtering only restricts Wi-Fi network association.", "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "mam", "byod", "security"], "options": ["Mobile Application Management (MAM) with containerized work profiles", "Full device firmware flashing using an OEM recovery tool", "Factory reset wipe command sent via GSM SMS command code", "MAC address filtering on the corporate guest wireless SSID"], "answer": 0, "distractor_analysis": {"1": "Full firmware flashing wipes the entire device storage partition, destroying personal data and violating BYOD privacy standards.", "2": "A full factory reset via SMS completely erases all personal user data, photos, and personal accounts on the mobile device.", "3": "MAC address filtering controls local wireless network access and provides zero management over mobile device data encryption or selective wiping."}}, {"id": "C1N-V-021", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "multi", "difficulty": "hard", "question": "A mobile device administrator is configuring profile policies for corporate iOS and Android smartphones. To ensure maximum transport security and reliable calendar and contact sync with Microsoft 365, which TWO protocols and authentication standards should the administrator configure? (Select TWO.)", "explanation": "Exchange ActiveSync (EAS) over TLS is the standard mobile protocol for synchronizing corporate email, calendar events, contacts, and tasks with Microsoft 365 / Exchange servers while supporting remote security policy enforcement. WPA3-Enterprise with 802.1X EAP-TLS utilizes digital certificates installed on mobile devices to authenticate to enterprise Wi-Fi networks securely without transmitting cleartext credentials. POP3 port 110 is unencrypted and does not sync contacts/calendars. WEP is completely broken. TFTP is an unauthenticated, unencrypted file transfer protocol.", "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronization", "activesync", "eap-tls"], "options": ["Exchange ActiveSync (EAS) over TLS encryption", "WPA3-Enterprise using 802.1X EAP-TLS certificate authentication", "Unencrypted POP3 over TCP port 110", "Wired Equivalent Privacy (WEP) with 64-bit static keys", "Trivial File Transfer Protocol (TFTP) over UDP port 69"], "answers": [0, 1], "distractor_analysis": {"2": "POP3 on port 110 transmits credentials in cleartext and only downloads emails without synchronizing calendars, contacts, or server folders.", "3": "WEP is an obsolete, highly insecure wireless encryption standard that is vulnerable to key recovery attacks within seconds.", "4": "TFTP on UDP port 69 lacks authentication and encryption, used primarily for network bootloaders rather than mobile device sync."}}, {"id": "C1N-V-022", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A network security engineer is auditing firewall access control lists between a server VLAN and an Active Directory domain controller. An application needs to perform encrypted directory queries and user authentication over LDAP over SSL. Which port must be permitted through the firewall?", "explanation": "TCP port 636 is the standard port for LDAP over SSL/TLS (LDAPS), which encrypts directory queries and credential validations between clients and directory servers. TCP port 389 is unencrypted LDAP. UDP port 53 is used for DNS name resolution. TCP port 445 is used for Server Message Block (SMB) file sharing.", "video_reference": {"title": "Common Ports - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=_qGlbfZ44hg", "duration": "12:52", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "ldaps", "security"], "options": ["TCP port 636 (LDAPS)", "TCP port 389 (LDAP cleartext)", "UDP port 53 (DNS query)", "TCP port 445 (SMB over IP)"], "answer": 0, "distractor_analysis": {"1": "TCP port 389 is the default port for unencrypted LDAP communication, which transmits directory queries and potential credentials in cleartext.", "2": "UDP port 53 handles Domain Name System (DNS) address resolution queries, not directory services.", "3": "TCP port 445 is used for Microsoft SMB file sharing and Named Pipes, not secure directory queries."}}, {"id": "C1N-V-023", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "hard", "question": "A network engineer creates a new client VLAN 50 on a core datacenter switch. Endpoints in VLAN 50 cannot obtain IP addresses from the central DHCP server located in management VLAN 10. The engineer verifies that trunk links and VLAN tags are functional. What configuration must be applied to the VLAN 50 default gateway interface on the switch?", "explanation": "DHCP discover messages are sent as Layer 2 local broadcasts (255.255.255.255), which routers and Layer 3 switches drop by default at VLAN boundaries. To allow clients in VLAN 50 to receive IP leases from a DHCP server in VLAN 10, the Layer 3 switch interface for VLAN 50 must be configured with a DHCP Relay agent (configured in Cisco IOS as 'ip helper-address <DHCP_Server_IP>'). This converts the client's broadcast into a unicast packet forwarded to the DHCP server. DDNS updates records after obtaining an IP. ISL is a legacy proprietary trunking protocol. Static broadcast ARP is invalid.", "video_reference": {"title": "VLANs and VPNs - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=Z1wPgxsx4GI", "duration": "7:32", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dhcp", "relay", "vlan", "helper-address"], "options": ["Configure a DHCP relay agent (ip helper-address) pointing to the DHCP server IP", "Enable dynamic DNS forwarding on the VLAN 50 switch access ports", "Change the switch port encapsulation mode from 802.1Q to ISL", "Configure a static ARP mapping between the client broadcast MAC and the DHCP server"], "answer": 0, "distractor_analysis": {"1": "Dynamic DNS registers hostnames to IP addresses after leases are granted, but does not forward broadcast DHCP discovery frames across subnets.", "2": "Inter-Switch Link (ISL) is an obsolete Cisco-proprietary trunking protocol that does not solve Layer 3 broadcast routing for DHCP.", "3": "Static ARP mappings bind IP addresses to unicast MACs and cannot route Layer 2 discovery broadcasts across router interfaces."}}, {"id": "C1N-V-024", "exam": "core1", "domain": "2.0 Networking", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A datacenter administrator needs to deploy a dedicated hardware appliance in front of a web server farm that distributes incoming HTTPS client requests across multiple backend application nodes, performs SSL/TLS offloading, and conducts active health checks. Which network device should be installed?", "explanation": "A hardware Load Balancer (or Application Delivery Controller) terminates client SSL/TLS connections, balances traffic across multiple backend servers using algorithms like round-robin or least connections, and continuously monitors server health to reroute traffic away from failed nodes. A Layer 2 switch forwards frames based on MAC addresses and does not perform application-layer SSL offloading or HTTP health checks. A TDR tests cable physical continuity. An HSM securely generates and stores cryptographic keys.", "video_reference": {"title": "Network Devices - CompTIA A+ 220-1201 - 2.5", "url": "https://www.youtube.com/watch?v=0hd6_bx0ydo", "duration": "18:01", "objective": "2.5"}, "notes_reference": "09_Network_Types_Hardware_Cabling.md", "tags": ["networking", "load-balancer", "devices", "datacenter"], "options": ["Hardware Load Balancer / Application Delivery Controller", "Layer 2 Managed Ethernet Switch with 802.3ad LACP", "Time-Domain Reflectometer with optical splitters", "Hardware Security Module (HSM) key storage blade"], "answer": 0, "distractor_analysis": {"1": "Layer 2 managed switches forward Ethernet frames based on MAC addresses and cannot parse HTTP payloads or perform TLS offloading.", "2": "A Time-Domain Reflectometer (TDR) is a diagnostic test instrument used to detect physical copper/fiber cable faults.", "3": "A Hardware Security Module (HSM) is a dedicated crypto processor for safeguarding digital keys, not a traffic distribution appliance."}}, {"id": "C1N-V-025", "exam": "core1", "domain": "2.0 Networking", "objective": "2.6", "type": "single", "difficulty": "hard", "question": "An administrator is deploying IPv6 on a corporate subnet with prefix 2001:db8:acad:10::/64. Client workstations automatically configure their own 128-bit IPv6 global unicast addresses by combining the /64 prefix received in Router Advertisement (RA) packets with an interface identifier derived from their 48-bit MAC address. Which IPv6 address autoconfiguration mechanism is being used?", "explanation": "Stateless Address Autoconfiguration (SLAAC) allows an IPv6 host to configure its own global unicast address without a DHCPv6 server. The host learns the network prefix from ICMPv6 Router Advertisement messages and generates the 64-bit host identifier using modified EUI-64 (inserting 0xFFFE into the middle of the 48-bit MAC address and flipping the universal/local bit) or randomized privacy extensions. Stateful DHCPv6 tracks leases from a central server. APIPA is IPv4 link-local (169.254.x.x). NAT64 translates between IPv6 and IPv4 protocols.", "video_reference": {"title": "IPv4 and IPv6 - CompTIA A+ 220-1201 - 2.6", "url": "https://www.youtube.com/watch?v=yubEz-ZEVwY", "duration": "8:45", "objective": "2.6"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "ipv6", "slaac", "eui-64", "addressing"], "options": ["Stateless Address Autoconfiguration (SLAAC) using modified EUI-64", "Stateful DHCPv6 address reservation pool assignment", "Static APIPA address generation within the fe80::/10 link-local space", "Dual-stack NAT64 address translation mapping"], "answer": 0, "distractor_analysis": {"1": "Stateful DHCPv6 relies on a dedicated DHCPv6 server maintaining a database of assigned IPv6 addresses and options, rather than autonomous client generation.", "2": "APIPA (169.254.0.0/16) is strictly an IPv4 fallback mechanism; IPv6 uses native link-local addresses (fe80::/10).", "3": "NAT64 is an address translation transition mechanism that converts IPv6 packets to IPv4 packets at a border router."}}, {"id": "C1N-M-001", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "A user reports that a three-year-old business laptop now runs for only twenty minutes on battery even though Windows shows the battery as fully charged. The laptop otherwise performs normally when plugged in. Which component should the technician replace first?", "options": ["The system board", "The M.2 SSD", "The battery pack", "The DC-in jack"], "answer": 2, "explanation": "Lithium-ion cells lose capacity with charge cycles and age. A full-charge reading that drains in minutes is the classic signature of a worn battery whose chemistry can no longer hold its rated capacity, and the battery is the cheapest and least invasive part to replace. The DC-in jack only matters while charging on AC, the system board is not implicated when the machine works on mains power, and storage has no effect on runtime.", "distractor_analysis": {"1": "A faulty DC jack would stop the laptop charging or running on AC; here AC operation is normal.", "2": "Replacing the system board is expensive and unjustified when every symptom points at the battery.", "3": "An SSD failure causes boot or file errors, not a short runtime."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "battery", "power"]}, {"id": "C1N-M-002", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A technician needs to add memory to a thin business ultrabook. On opening the case there are no memory slots visible, and the service manual describes the RAM as LPDDR5. What does this tell the technician about the upgrade?", "options": ["The laptop accepts SO-DIMMs only in a docking station", "The memory is soldered to the board and cannot be upgraded", "The memory is under the keyboard and requires a full teardown", "The laptop uses full-size DIMMs behind the display panel"], "answer": 3, "explanation": "LPDDR (low-power DDR) memory is manufactured as packages soldered directly onto the system board. It is chosen for thin, light designs because it saves space and power, but the trade-off is that the amount of RAM is fixed at the factory. A technician should check the memory type before promising an upgrade, because a soldered configuration means replacing the whole board or buying a higher-spec unit.", "distractor_analysis": {"1": "Soldered memory is not hidden under the keyboard; there are no modules to remove at all.", "2": "Laptops never use full-size desktop DIMMs and nothing is mounted behind the display.", "3": "Docking stations add ports, not memory."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "memory", "lpddr", "upgrade"]}, {"id": "C1N-M-003", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which memory form factor is installed in a laptop that has user-serviceable memory slots?", "options": ["DIMM", "RIMM", "SIMM", "SO-DIMM"], "answer": 1, "explanation": "Laptops with upgradeable memory use SO-DIMM (small outline DIMM) modules, which are roughly half the length of the DIMMs found in desktops so they fit in the thin chassis. Current models are DDR4 and DDR5 SO-DIMMs, and the two generations are not interchangeable because the key notch and pin count differ. Desktop DIMMs are physically too large, and RIMM and SIMM are obsolete formats not found in modern portable systems.", "distractor_analysis": {"1": "Full-size DIMMs are for desktops and servers.", "2": "RIMM was the Rambus format used briefly around 2000 and is obsolete.", "3": "SIMM modules predate DDR entirely."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "memory", "so-dimm"]}, {"id": "C1N-M-004", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A user wants the fastest possible storage upgrade for a laptop that has one M.2 slot marked with both B and M keys and support for PCIe. Which drive should the technician recommend?", "options": ["A 2.5-inch SATA SSD with an adapter", "An mSATA SSD", "An M.2 NVMe SSD", "An M.2 SATA SSD"], "answer": 2, "explanation": "An M.2 slot that supports PCIe can take an NVMe SSD, which talks directly to the PCIe bus and delivers several times the throughput of any SATA device. M.2 SATA drives fit the same slot but are limited to the 6 Gbps SATA ceiling. A 2.5-inch drive would need a bay the laptop may not have, and mSATA is an older, physically different card that will not fit an M.2 slot at all.", "distractor_analysis": {"1": "M.2 SATA uses the same connector but is capped at SATA speeds.", "2": "A 2.5-inch drive needs a drive bay and would still be SATA speed.", "3": "mSATA is a different form factor and connector."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "storage", "m.2", "nvme"]}, {"id": "C1N-M-005", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A field engineer's laptop has a 2.5-inch spinning hard drive and the user complains about slow boot times and noise. The laptop has no M.2 slot. Which upgrade gives the largest improvement while keeping the existing bay?", "options": ["Replace the optical drive with a second hard drive", "Replace the hard drive with a 2.5-inch SATA SSD", "Replace the hard drive with a 7200 rpm hard drive", "Add more system memory"], "answer": 3, "explanation": "A 2.5-inch SATA SSD is a drop-in replacement for a laptop hard drive: same physical size, same SATA data and power connector. It removes the seek latency and spin-up delay that make boot and application launches slow, and it has no moving parts, which also solves the noise complaint and improves shock tolerance. A faster spinning disk is a marginal gain, more RAM does not fix disk-bound boot times, and a second hard drive adds capacity, not speed.", "distractor_analysis": {"1": "A 7200 rpm disk is only slightly faster and still has moving parts.", "2": "Memory helps multitasking but not a slow disk on boot.", "3": "A second spinning drive adds space and more noise."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "storage", "ssd", "upgrade"]}, {"id": "C1N-M-006", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop boots and displays the vendor logo, but Windows reports that the internal wireless adapter is missing. The adapter is a replaceable M.2 card. What should the technician check first?", "options": ["That the Wi-Fi network password has not changed", "That the laptop is within range of an access point", "That the display cable is routed away from the card", "That the wireless card is fully seated and both antenna leads are attached"], "answer": 1, "explanation": "A wireless card that Windows cannot see at all is a hardware-level fault rather than a connection problem. Replaceable wireless cards sit in an M.2 E-key slot and can work loose after a drop or a repair, and the two tiny antenna connectors are easily left off during reassembly. Reseating the card and confirming both antenna leads restores detection; only once the adapter appears in Device Manager do network settings or signal range become relevant.", "distractor_analysis": {"1": "A wrong password produces an authentication failure, not a missing adapter.", "2": "Range affects signal strength; the adapter would still be listed.", "3": "Display cable routing has nothing to do with adapter detection."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "wireless", "m.2", "antenna"]}, {"id": "C1N-M-007", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which laptop component converts the wall outlet's alternating current into the low-voltage direct current the laptop uses?", "options": ["The inverter", "The docking station", "The external AC adapter", "The CMOS battery"], "answer": 2, "explanation": "The external power brick is the laptop's power supply. It steps mains AC down and rectifies it to a fixed DC output, typically 19 to 20 volts for barrel connectors or a negotiated USB-C Power Delivery voltage. Always match the voltage exactly and meet or exceed the wattage rating; an under-rated adapter will run the laptop but fail to charge under load. The CMOS battery keeps firmware settings, an inverter powered older CCFL backlights, and a dock passes power through rather than creating it.", "distractor_analysis": {"1": "The CMOS battery is a coin cell for the real-time clock and firmware settings.", "2": "An inverter changes DC to AC for old CCFL backlights, the reverse direction.", "3": "A docking station may forward power but relies on its own adapter."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "power", "ac-adapter"]}, {"id": "C1N-M-008", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A user replaced a lost 65 W USB-C charger with a 30 W phone charger. The laptop shows a charging icon but the battery percentage falls during video calls. What is the cause?", "options": ["The battery has reached its cycle limit", "The charger cannot supply enough wattage, so the laptop draws more than it receives under load", "The charger is the wrong voltage and is damaging the battery", "USB-C phone chargers cannot charge laptops at all"], "answer": 3, "explanation": "USB-C Power Delivery negotiates the highest power profile both ends support. A 30 W source will charge the laptop, but a laptop under heavy load such as a video call can draw more than 30 W, so the battery makes up the difference and slowly drains despite the charging icon. The fix is a charger rated at or above the laptop's requirement. PD negotiation prevents wrong-voltage damage, phone chargers do charge laptops slowly, and a worn battery would drain fast even at idle.", "distractor_analysis": {"1": "PD negotiates voltage safely; a low-watt source is not a wrong-voltage source.", "2": "Any PD-compliant USB-C charger will charge, just slowly.", "3": "Battery wear would show at idle, not only under load."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "usb-c", "power-delivery", "charging"]}, {"id": "C1N-M-009", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "Several keys on a laptop keyboard stopped working after a coffee spill. The touchpad and the rest of the system are fine. What is the most cost-effective repair?", "options": ["Replace the system board", "Reinstall the operating system", "Replace the touchpad", "Replace the keyboard assembly"], "answer": 1, "explanation": "A laptop keyboard is a discrete module connected to the board by a ribbon cable, and on most business models it can be swapped in minutes after removing the palm rest or the top cover. Liquid that shorts individual key traces damages only the keyboard membrane, so replacing the assembly restores full function at low cost. The board is not implicated when everything else works, an OS reinstall cannot fix a hardware fault, and the touchpad is not affected.", "distractor_analysis": {"1": "The system board is working; replacing it would be wasteful.", "2": "Software cannot repair physically damaged key traces.", "3": "The touchpad is a separate part and is working."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "keyboard", "repair"]}, {"id": "C1N-M-010", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "A user says the laptop keyboard types numbers when the letter keys on the right side are pressed. What should the technician do?", "options": ["Update the chipset driver", "Reset the firmware to defaults", "Turn off Num Lock, which has enabled the embedded numeric keypad", "Replace the keyboard because the key matrix has failed"], "answer": 2, "explanation": "Compact laptop keyboards overlay a numeric keypad on the U, I, O, J, K, L and M keys. When Num Lock is on, those keys produce digits. Turning Num Lock off, often with an Fn key combination, restores normal typing immediately. This is a configuration state rather than a fault, so no hardware, driver or firmware change is needed, and a technician who recognises it saves an unnecessary repair.", "distractor_analysis": {"1": "A failed matrix produces dead or stuck keys, not consistent digit output.", "2": "Chipset drivers do not control key mapping.", "3": "Firmware defaults do not toggle Num Lock behaviour."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "keyboard", "num-lock", "function-keys"]}, {"id": "C1N-M-011", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A technician is replacing a laptop display. The old panel is described as an LCD with LED backlighting. The replacement listed by the vendor is an OLED panel of the same size. Which statement is true about the OLED replacement?", "options": ["OLED panels are always thicker than LCD panels", "Each OLED pixel emits its own light, so no separate backlight layer is needed", "OLED panels require a higher-voltage inverter for the backlight", "OLED panels cannot display true black"], "answer": 3, "explanation": "In an OLED display every pixel is an organic light-emitting diode that produces its own light. Because there is no backlight, black pixels are simply off, giving very deep blacks and a thinner panel. The trade-offs technicians should know are higher cost, potential burn-in from static images, and the need for a compatible display cable and firmware. LCDs, by contrast, always need a backlight, which today is LED rather than the CCFL tubes that once required an inverter.", "distractor_analysis": {"1": "OLED has no backlight and therefore no inverter.", "2": "True black is the main strength of OLED.", "3": "Without a backlight layer OLED panels are typically thinner."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "display", "oled", "lcd"]}, {"id": "C1N-M-012", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "A laptop display shows a very faint image that is only visible when a flashlight is shone on the screen. An external monitor works normally. Which component has most likely failed?", "options": ["The graphics processor", "The LCD pixel layer", "The display data cable", "The panel backlight or its power circuit"], "answer": 1, "explanation": "The flashlight test is the definitive check for a dead backlight: the LCD is still forming an image, which you can see when external light passes through it, but nothing is illuminating it from behind. On modern panels this means the LED backlight strip or the power circuit that drives it, sometimes a fuse on the board. Because the external monitor is fine, the GPU is ruled out, the pixel layer is proven working by the faint image, and a broken data cable would produce no image, flicker or artefacts rather than a correct but dark picture.", "distractor_analysis": {"1": "A working external display proves the GPU is fine.", "2": "The faint image shows the pixel layer is producing a picture.", "3": "A data cable fault corrupts or removes the image rather than dimming it."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "display", "backlight", "troubleshooting"]}, {"id": "C1N-M-013", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop's Wi-Fi signal is strong when the lid is open but drops to one bar when the lid is nearly closed. What explains this behaviour?", "options": ["The operating system disables Wi-Fi when the lid closes", "The hinge contains a magnet that blocks radio signals", "The wireless antennas are routed through the display bezel", "The wireless card overheats when the lid is closed"], "answer": 2, "explanation": "Laptop wireless antennas are almost always placed along the top edge of the display assembly behind the bezel, connected to the card by thin coaxial leads that run through the hinge. This gives them height and clearance from the metal base. When the lid is nearly closed the antennas point down toward the desk and are shielded by the chassis, so signal falls. It also explains why a lid or hinge repair can leave Wi-Fi weak if a lead is pinched or left disconnected.", "distractor_analysis": {"1": "The card is in the base and its temperature does not change with lid angle.", "2": "Windows changes power state on lid close, but the user is seeing signal bars while the lid is still open.", "3": "The lid sensor magnet is tiny and does not block radio waves."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "wireless", "antenna", "display"]}, {"id": "C1N-M-014", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop has a built-in webcam that Windows no longer detects after a display hinge repair. The camera worked before the repair. What is the most likely cause?", "options": ["The webcam needs a firmware update after any hardware change", "The webcam cable running through the hinge was not reconnected or was damaged", "The webcam driver was uninstalled during the repair", "The camera privacy setting was turned off in the operating system"], "answer": 3, "explanation": "The webcam, microphone and wireless antennas all live in the display assembly, and their cables pass through the hinge alongside the display cable. A hinge repair means every one of those cables is disturbed. A camera that disappears from Device Manager after such work is almost always a connector left unseated or a cable pinched during reassembly. The technician should reopen the display and inspect the camera cable and its board-side connector before considering software.", "distractor_analysis": {"1": "Mechanical repairs do not remove drivers, and a missing driver still shows an unknown device.", "2": "A privacy toggle blocks apps from using the camera but Windows still lists the hardware.", "3": "Webcams do not require firmware updates after mechanical work."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "webcam", "display-assembly", "repair"]}, {"id": "C1N-M-015", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which laptop component is most commonly used to unlock the device with a fingertip?", "options": ["A near-field communication tag in the touchpad", "The ambient light sensor", "A smart card reader", "A fingerprint reader integrated into the power button or palm rest"], "answer": 1, "explanation": "Business laptops typically integrate a capacitive fingerprint reader either in the power button or as a small pad on the palm rest, and Windows Hello uses it for sign-in. When troubleshooting, confirm the reader appears under Biometric devices in Device Manager, that the user has enrolled a fingerprint, and that the sensor surface is clean. NFC readers, when present, read cards and phones rather than fingerprints, the ambient light sensor adjusts brightness, and a smart card reader authenticates with a physical card.", "distractor_analysis": {"1": "NFC reads tags and cards, not fingerprints.", "2": "The ambient light sensor controls screen brightness.", "3": "Smart card readers use a card, not biometrics."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "biometrics", "fingerprint", "windows-hello"]}, {"id": "C1N-M-016", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A user's laptop face-recognition sign-in stopped working after the office moved to a room with large windows behind the desk. The camera still works for video calls. What is the most likely fix?", "options": ["Disable the infrared emitter to save power", "Turn off the ambient light sensor in firmware", "Reposition the user so strong backlight is not behind them, then re-enrol the face if needed", "Replace the webcam with a higher-resolution model"], "answer": 2, "explanation": "Windows Hello face recognition uses an infrared camera and emitter rather than the colour webcam, and strong sunlight from behind the user floods the infrared sensor and washes out the depth image. Video calls keep working because they use the standard colour camera. Changing the seating position or adding a blind, followed by re-enrolling under the new lighting, resolves it. A higher-resolution colour camera does not help, and the infrared emitter is exactly the part that needs to keep working.", "distractor_analysis": {"1": "Face sign-in relies on the IR camera, so colour resolution is irrelevant.", "2": "Disabling the IR emitter would break face recognition entirely.", "3": "The ambient light sensor only affects screen brightness."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "biometrics", "infrared", "windows-hello"]}, {"id": "C1N-M-017", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "During a laptop memory upgrade the technician notices the new DDR5 SO-DIMM will not seat in the slot even though it is the same length as the old DDR4 module. What is the reason?", "options": ["DDR5 SO-DIMMs are only used in desktop systems", "DDR4 and DDR5 SO-DIMMs have different key notch positions and are not interchangeable", "DDR5 modules must be installed with the laptop powered on", "The slot needs a firmware update before accepting DDR5"], "answer": 3, "explanation": "Every DDR generation moves the key notch so that a module can only be inserted into a slot designed for its voltage and signalling. DDR4 and DDR5 SO-DIMMs both have 262 pins and are the same length, but the notch is offset, so a DDR5 module physically cannot seat in a DDR4 slot. A board is built for one generation only; no firmware update changes that. Memory is never installed with power applied, and DDR5 SO-DIMMs are a laptop format.", "distractor_analysis": {"1": "Memory must never be installed with power on; the notch mismatch is the real barrier.", "2": "Slot compatibility is fixed by the hardware, not firmware.", "3": "SO-DIMM is by definition the laptop form factor."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "memory", "ddr5", "so-dimm"]}, {"id": "C1N-M-018", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Before opening a laptop to replace the SSD, what should a technician do to protect both the technician and the hardware?", "options": ["Leave the battery connected so the CMOS settings are preserved", "Ground the chassis by touching the display panel", "Place the laptop on a carpeted surface to prevent it sliding", "Disconnect the AC adapter, disconnect or disable the internal battery, and use an ESD strap"], "answer": 1, "explanation": "Internal laptop batteries keep the board live even when the machine is off, so the safe sequence is to unplug the adapter, then disconnect the battery connector or use the firmware battery-disconnect option, then wear an ESD strap on a grounded mat. This prevents shorting a powered board while inserting the drive and protects the SSD's controller from static. CMOS settings are held by a separate coin cell, the display is not a ground, and carpet is a static generator.", "distractor_analysis": {"1": "The main battery does not preserve CMOS; the coin cell does, and a live battery is a shock and short risk.", "2": "Touching the display panel does not ground anything.", "3": "Carpet generates static and is the worst possible work surface."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "safety", "esd", "battery"]}, {"id": "C1N-M-019", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop shuts down without warning after about ten minutes of heavy use and the underside is very hot. The fan is heard spinning at full speed. What is the most likely cause?", "options": ["An incorrect display driver", "A loose memory module", "Dust-clogged heat sink fins or degraded thermal paste causing thermal shutdown", "A failing battery cell"], "answer": 2, "explanation": "A fan running flat out while the case still overheats means air is moving but heat is not leaving the CPU or GPU. Laptop heat sinks collect a dense mat of dust behind the fan, and thermal paste dries out over years, both of which raise die temperature until firmware forces a protective shutdown. Cleaning the fins and re-pasting is the fix. A weak battery causes shutdowns at low charge rather than with heat, a display driver cannot cause thermal events, and loose memory causes crashes or no-boot rather than heat.", "distractor_analysis": {"1": "Battery faults correlate with charge level, not with heat and load.", "2": "Driver problems produce visual glitches or blue screens, not hot chassis.", "3": "Loose memory causes boot failures or memory errors."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "cooling", "thermal", "troubleshooting"]}, {"id": "C1N-M-020", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "A laptop's clock resets to a default date every time the machine is left unplugged for a few days, and the firmware prompts to press F1 on boot. The main battery holds charge normally. Which component should be replaced?", "options": ["The AC adapter", "The CMOS coin-cell battery", "The main battery pack", "The real-time clock chip"], "answer": 3, "explanation": "Firmware settings and the real-time clock are kept alive by a small coin cell (often a CR2032 or a wired equivalent) when the system has no other power. Some laptops trickle-charge it from the main battery, which is why the fault only shows after days without power. A dead coin cell produces exactly this pattern: lost time, reset firmware settings and a setup prompt on boot. The main battery is proven good, the clock chip itself rarely fails, and the adapter charges the pack normally.", "distractor_analysis": {"1": "The main pack holds charge normally, so it is not the failing part.", "2": "RTC silicon failures are rare and would not depend on power being removed.", "3": "The adapter is irrelevant while the laptop is unplugged."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "cmos", "battery", "firmware"]}, {"id": "C1N-M-021", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A user wants to know whether a new laptop can be upgraded later. The specification sheet lists 16 GB LPDDR5X memory and a 512 GB M.2 2280 NVMe SSD. Which statement is accurate?", "options": ["Both the memory and the storage can be upgraded", "Neither the memory nor the storage can be upgraded", "The memory can be upgraded but the storage cannot", "The storage can be upgraded but the memory cannot"], "answer": 1, "explanation": "LPDDR memory of any generation is soldered to the board, so the 16 GB is fixed for the life of the laptop. An M.2 2280 NVMe drive, on the other hand, is a standard removable card 22 mm wide and 80 mm long that can be swapped for a larger capacity. Reading these two specification lines is how a technician sets expectations before purchase: buy the memory you will need on day one, and treat storage as the upgradeable part.", "distractor_analysis": {"1": "LPDDR5X is soldered and cannot be upgraded.", "2": "A standard M.2 2280 slot accepts replacement drives.", "3": "This reverses the truth: the SSD is the replaceable part."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "memory", "storage", "upgrade"]}, {"id": "C1N-M-022", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop's touchpad cursor jumps and clicks randomly while the user types. The external mouse works correctly. Which action is the most appropriate first step?", "options": ["Replace the system board", "Disable the keyboard", "Adjust the touchpad palm-rejection or sensitivity settings and check for a driver update", "Replace the touchpad assembly"], "answer": 2, "explanation": "Random cursor movement while typing is usually the palm brushing the touchpad, and modern precision touchpad drivers include a palm-rejection delay and sensitivity control for exactly this. Adjusting those settings, or installing the vendor's current driver, resolves most cases at zero cost. Hardware replacement is only justified if the pad misbehaves when nothing touches it and the driver is current. The board is not involved, and disabling the keyboard defeats the purpose of the laptop.", "distractor_analysis": {"1": "Hardware replacement comes after settings and drivers are ruled out.", "2": "The system board is not implicated by a touchpad sensitivity issue.", "3": "Disabling the keyboard is not a solution to touchpad behaviour."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "touchpad", "driver", "settings"]}, {"id": "C1N-M-023", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which laptop feature lets a user rotate the screen 360 degrees and use the device as a tablet?", "options": ["A detachable keyboard cover", "A convertible two-in-one hinge design with a touchscreen", "A docking station", "A digitizer-only display"], "answer": 3, "explanation": "Convertible two-in-one laptops use a hinge that folds the display all the way back so the keyboard faces down and the touchscreen faces the user. Sensors detect the orientation and the operating system switches to tablet mode. Technicians should know these hinges carry the display, camera and antenna cables through a wide range of motion and are a common failure point, and that a touchscreen digitizer must be present for tablet use to be practical.", "distractor_analysis": {"1": "A dock adds ports and does not change the form factor.", "2": "A digitizer is part of a touchscreen, not a hinge design.", "3": "A detachable keyboard describes a different two-in-one style where the screen separates rather than rotates."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "two-in-one", "hinge", "touchscreen"]}, {"id": "C1N-M-024", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A touchscreen laptop registers touches a centimetre away from where the user actually presses, across the whole screen. What is the appropriate fix?", "options": ["Replace the display panel", "Increase the display resolution", "Clean the fan intake", "Run the operating system's touch calibration tool"], "answer": 1, "explanation": "A consistent offset between the touch point and the cursor across the entire screen is a calibration problem: the digitizer is working but its coordinate map no longer matches the display. Windows includes a calibration tool under Tablet PC Settings that has the user tap a series of targets and rewrites the mapping. Only if touches are missing in a region, or the offset varies randomly, is the digitizer itself suspect. Resolution and cooling have no bearing on touch accuracy.", "distractor_analysis": {"1": "A uniform offset means the digitizer works; replacing it is premature.", "2": "Resolution changes scale the picture, not the touch map.", "3": "Cooling is unrelated to digitizer accuracy."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "touchscreen", "digitizer", "calibration"]}, {"id": "C1N-M-025", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A technician is asked why a laptop's internal speakers are quiet and tinny compared with a desktop's external speakers. What is the accurate explanation?", "options": ["Laptops lack a digital-to-analogue converter", "Windows caps laptop volume at 50 percent for hearing safety", "Laptop speakers are physically small drivers with little enclosure volume, which limits bass and loudness", "Laptop audio codecs are limited to mono output"], "answer": 2, "explanation": "Sound quality is governed by physics. A speaker needs a driver large enough to move air and an enclosure with volume behind it to reproduce low frequencies at reasonable loudness. Laptop speakers are tiny and mounted in a shallow chassis, so they cannot produce deep bass or high volume regardless of the electronics. The audio codec on the board is stereo, includes a DAC, and Windows imposes no volume cap; the solution for better sound is external speakers or headphones.", "distractor_analysis": {"1": "Laptop codecs are stereo and often support multichannel over HDMI.", "2": "Every sound card, including a laptop's, has a DAC.", "3": "There is no such operating-system volume cap."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "audio", "speakers"]}, {"id": "C1N-M-026", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop microphone picks up nothing during calls, but a USB headset works. The device appears in Sound settings. What should the technician check first?", "options": ["The Wi-Fi antenna leads", "The microphone privacy setting and the vendor function key that mutes the internal microphone", "The webcam cable", "The speaker driver"], "answer": 3, "explanation": "Because the microphone is listed in Sound settings the hardware is detected, so the fault is almost certainly a software or firmware mute. Windows has a per-app microphone privacy switch, and most business laptops add a dedicated function key that mutes the internal microphone at the firmware level with an indicator LED. Checking both takes seconds. The webcam cable would matter if the mic were absent from the device list, the speaker driver is a separate output path, and antennas carry radio, not audio.", "distractor_analysis": {"1": "A disconnected cable would remove the device from the list entirely.", "2": "Speaker output has nothing to do with microphone capture.", "3": "Antenna leads are for wireless radios."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "microphone", "privacy", "function-keys"]}, {"id": "C1N-M-027", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "A user presses F5 in a spreadsheet expecting it to refresh, but the laptop's screen brightness changes instead. What should the technician recommend?", "options": ["Replace the keyboard", "Install a third-party keyboard remapping utility", "Disable the display driver", "Hold the Fn key with F5, or change the function key behaviour in firmware settings"], "answer": 1, "explanation": "Laptop makers print media controls on the function row and, by default, many models trigger those actions on a plain press while requiring Fn to send the standard F-key code. Holding Fn with F5 sends the true F5, and the firmware setup usually has an option, often called Function Key Behaviour or Action Keys Mode, to swap the default permanently. Hardware replacement and third-party utilities are unnecessary, and the display driver is not the cause.", "distractor_analysis": {"1": "The keyboard is behaving as designed; nothing is broken.", "2": "A remapping tool adds complexity when firmware already offers the toggle.", "3": "The display driver does not decide key behaviour."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "keyboard", "function-keys", "firmware"]}, {"id": "C1N-M-028", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop's screen has a permanently bright green dot in the same position on every image, including the firmware setup screen. What is this and what is the remedy?", "options": ["A backlight failure; replace the backlight", "Dust on the screen; clean the surface", "A stuck pixel in the panel; if it does not clear, the panel must be replaced", "A graphics driver fault; reinstall the driver"], "answer": 2, "explanation": "A single dot of a fixed colour that appears even before the operating system loads is a panel defect, specifically a stuck sub-pixel that is permanently on. Because it shows in firmware setup, no driver can be responsible. Pixel-exercising tools occasionally free a stuck pixel, but a persistent one needs a panel replacement, and many vendors publish a threshold number of defective pixels before they will replace under warranty. A backlight fault dims the whole screen and dust wipes off.", "distractor_analysis": {"1": "Anything visible in firmware setup is not a driver issue.", "2": "Backlight faults affect the whole display, not one dot.", "3": "Dust sits on the glass and moves when wiped; a stuck pixel does not."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "display", "stuck-pixel"]}, {"id": "C1N-M-029", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop's screen brightness rises and falls on its own as the user moves between rooms, which the user finds distracting. Which component causes this and how is it addressed?", "options": ["The graphics processor; update the driver", "The ambient light sensor; disable adaptive brightness in power or display settings", "The webcam; cover the lens", "The backlight inverter; replace it"], "answer": 3, "explanation": "Many laptops include an ambient light sensor near the webcam that feeds an adaptive brightness feature, raising the backlight in bright rooms and lowering it in dark ones to save battery. Users who prefer a fixed level can turn adaptive brightness off in the display or power settings, or in the vendor utility. Covering the webcam does not cover the separate sensor, inverters belong to old CCFL panels, and the graphics driver is only the messenger for the sensor's reading.", "distractor_analysis": {"1": "The light sensor is a separate component from the camera lens.", "2": "Modern LED backlights have no inverter and the behaviour is intentional.", "3": "A driver update does not disable adaptive brightness."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "display", "ambient-light-sensor", "brightness"]}, {"id": "C1N-M-030", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "A technician replaced a laptop system board. Afterwards the laptop boots, but the fingerprint reader is missing from Device Manager and the Wi-Fi shows limited speed. Which oversight most likely explains both symptoms?", "options": ["The wrong operating system edition was installed", "The replacement board has a slower processor", "The battery was not fully charged before first boot", "Cables and connectors were not all reattached during reassembly, including the reader's ribbon and one antenna lead"], "answer": 1, "explanation": "A system board swap means every internal connector is disconnected and reconnected: display, camera, antennas, keyboard, touchpad, fingerprint reader, speakers and battery. Two unrelated-looking faults after such a repair almost always share one cause, an incomplete reassembly. A reader that is missing entirely has no data connection, and Wi-Fi that works but slowly is the signature of only one of two antenna leads being attached. Reopen and audit every connector against the service manual.", "distractor_analysis": {"1": "The OS edition does not remove hardware from Device Manager.", "2": "Processor speed does not affect device detection or Wi-Fi link rate.", "3": "Charge level has no bearing on peripherals being detected."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "repair", "reassembly", "troubleshooting"]}, {"id": "C1N-M-031", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop's battery health utility reports 480 charge cycles and 78 percent of design capacity. The user asks whether the battery is faulty. What is the correct assessment?", "options": ["The utility is wrong because capacity cannot fall below 100 percent", "The battery needs to be fully discharged to recalibrate its memory effect", "The battery is showing normal age-related wear and is not faulty, though replacement will restore runtime", "The battery is faulty and could be dangerous"], "answer": 2, "explanation": "Lithium-ion batteries lose capacity gradually; manufacturers typically rate them to retain around 80 percent after 300 to 500 cycles. A reading of 78 percent at 480 cycles is exactly the expected wear curve, not a defect. The battery is safe and works, it simply holds less energy, so replacement is a runtime decision rather than a repair. Lithium-ion has no memory effect, so deep-discharge conditioning is unnecessary and slightly harmful.", "distractor_analysis": {"1": "Gradual capacity loss is normal; swelling or overheating would be the danger signs.", "2": "Design capacity is the baseline and real capacity falls below it with age.", "3": "Memory effect belonged to nickel-cadmium cells, not lithium-ion."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "battery", "lithium-ion", "cycles"]}, {"id": "C1N-M-032", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "A laptop's touchpad no longer clicks and the palm rest around it is slightly raised. The battery sits directly under the touchpad. What should the technician do immediately?", "options": ["Continue using it with an external mouse until a convenient time", "Stop using the laptop, power it down and replace the swollen battery before any further use", "Press the palm rest down firmly to reseat the touchpad", "Update the touchpad driver"], "answer": 3, "explanation": "A raised palm rest or a touchpad that has stopped clicking on a laptop whose battery sits beneath it is the classic sign of a swollen lithium-ion battery. Swelling means the cells are degrading and producing gas; the pack is a fire risk and must be removed and disposed of through a proper recycling channel. Pressing on it or continuing to use the machine risks puncturing the cell. This is one of the few laptop faults that is a safety issue first and a repair second.", "distractor_analysis": {"1": "Pressing on a swollen cell can rupture it.", "2": "The click failure is mechanical, caused by the battery pushing up on the pad.", "3": "Continued use of a swollen battery risks fire."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "battery", "safety", "swelling"]}, {"id": "C1N-M-033", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A company standardises on laptops whose specification lists a physical webcam shutter and a Kensington-style lock slot. Which business requirement do these two features address?", "options": ["Faster wireless throughput in open-plan offices", "Compliance with the USB Power Delivery standard", "Support for external graphics over Thunderbolt", "Physical privacy and theft deterrence for devices used in shared spaces"], "answer": 1, "explanation": "A sliding webcam shutter guarantees the camera cannot capture anything when closed, independent of software, which matters for privacy in shared or client-facing spaces. A lock slot accepts a cable lock so the laptop can be tethered to a desk in hot-desking offices and public areas. Both are physical controls that technicians should be able to identify and recommend when a user's concern is privacy or theft rather than performance.", "distractor_analysis": {"1": "Neither feature affects wireless performance.", "2": "Power Delivery is a charging standard unrelated to these parts.", "3": "External graphics depend on the port specification, not a shutter or lock slot."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "physical-security", "webcam", "lock-slot"]}, {"id": "C1N-M-034", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A laptop has two SO-DIMM slots, one holding an 8 GB DDR4-3200 module. The technician adds a second 8 GB DDR4-2666 module. What is the result?", "options": ["The faster module runs at 3200 and the slower at 2666 simultaneously", "Only the original module is recognised", "Both modules run at 2666 MT/s, the speed of the slower module, in dual-channel mode", "The laptop will not boot because mixed speeds are not permitted"], "answer": 2, "explanation": "The memory controller drives all installed modules with one clock, so it selects the fastest speed every module supports, which here is 2666 MT/s. The system boots and, because the modules match in capacity, it runs in dual-channel mode for better bandwidth. The best practice for an upgrade is to match speed as well as capacity so the existing module is not slowed, but a mismatch is a performance compromise rather than a failure.", "distractor_analysis": {"1": "Mixed speeds work; the controller simply picks the common speed.", "2": "A single controller clock cannot run two speeds at once.", "3": "Both modules are recognised when seated correctly."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "memory", "dual-channel", "speed"]}, {"id": "C1N-M-035", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "After a laptop SSD is cloned to a larger NVMe drive and installed, the firmware reports no bootable device. The old drive booted normally. What is the most likely cause?", "options": ["The clone copied the operating system but a clone can never copy the boot loader", "The new drive is not seated fully in the M.2 slot or the retaining screw is missing", "The new drive has too much capacity for the laptop", "NVMe drives cannot be bootable"], "answer": 3, "explanation": "M.2 drives insert at an angle and must be pressed flat and secured with the retaining screw; a drive left angled makes intermittent or no contact and the firmware sees no device at all. Reseating and screwing it down is the first check. Capacity limits are not a factor on any modern firmware, NVMe drives are the standard boot device, and a proper disk clone copies the EFI system partition and boot loader along with the operating system.", "distractor_analysis": {"1": "UEFI firmware handles drives of any current capacity.", "2": "NVMe is the normal boot device in modern laptops.", "3": "Sector-level clones include the EFI partition and boot loader."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "storage", "m.2", "boot"]}, {"id": "C1N-M-036", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "multi", "difficulty": "medium", "question": "A technician is preparing a parts order for a laptop whose display assembly was cracked in a fall. Which TWO components are typically housed inside the display assembly and may also need inspection? (Select TWO.)", "options": ["The webcam and its cable", "The wireless antennas", "The SO-DIMM memory modules", "The M.2 SSD", "The cooling fan"], "answers": [0, 1], "explanation": "The display assembly is more than a panel. It carries the webcam and microphone array on a small board with a cable through the hinge, and the wireless and often the cellular antennas run along the top edge behind the bezel. Any impact hard enough to crack the panel can damage these parts or their cables, so a technician should test camera and wireless after the repair. Memory, storage and the fan all live in the base of the laptop.", "distractor_analysis": {"2": "Memory modules are in the base under the bottom cover.", "3": "The SSD is mounted on the system board in the base.", "4": "Cooling components sit over the processor in the base."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "display-assembly", "webcam", "antenna"]}, {"id": "C1N-M-037", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "multi", "difficulty": "medium", "question": "A user complains a laptop battery drains quickly even when the lid is closed in a bag overnight. Which TWO settings are the most likely causes? (Select TWO.)", "options": ["The lid-close action is set to do nothing rather than sleep or hibernate", "Wake timers or connected standby are allowed to wake the system while it is unattended", "Num Lock is left on", "The display resolution is set too high", "The keyboard backlight colour is set to white"], "answers": [0, 1], "explanation": "A laptop that runs down in a bag was never really asleep. Two power settings explain almost every case: the lid-close action is set to do nothing so the machine stays fully on, or the system is allowed to wake for scheduled tasks and network activity while unattended. Setting lid close to sleep or hibernate and disabling wake timers fixes it. Num Lock, resolution and backlight colour have no meaningful effect once the lid is closed.", "distractor_analysis": {"2": "Num Lock is a keyboard state with no power impact.", "3": "Resolution does not matter when the display is off.", "4": "Backlight colour is cosmetic and the keyboard is off when the lid is closed."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "power", "sleep", "battery"]}, {"id": "C1N-M-038", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "order", "difficulty": "medium", "question": "Place the steps for safely replacing a laptop's M.2 NVMe SSD in the correct order.", "sequence": ["Back up the user's data and confirm the backup is readable", "Power down, unplug the AC adapter, disconnect the internal battery and put on an ESD strap", "Remove the bottom cover and unscrew the retaining screw at the end of the drive", "Lift the drive at an angle and slide it out, then insert the new drive at the same angle and secure it", "Reconnect the battery, replace the cover and confirm the drive is detected in firmware setup"], "explanation": "Data protection comes first because a drive swap is irreversible for the old data if the drive is later reused. Power isolation and ESD protection prevent a short or static damage to a board that stays live from the internal battery. The M.2 drive is held by a single screw and inserts at roughly a 30-degree angle before being pressed flat. Verifying detection in firmware before reinstalling the operating system saves a wasted reinstall if the drive is not seated.", "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "storage", "procedure", "esd"]}, {"id": "C1N-M-039", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "match", "difficulty": "medium", "question": "Match each laptop symptom to the component most likely responsible.", "pairs": [{"left": "Faint image visible only with a flashlight", "right": "Backlight"}, {"left": "Clock resets after days unplugged", "right": "CMOS coin cell"}, {"left": "Full charge reading drains in minutes", "right": "Main battery pack"}, {"left": "Wireless works only with the lid open", "right": "Antenna leads in the display"}, {"left": "Sudden shutdown under load with a hot base", "right": "Clogged heat sink"}], "explanation": "Each of these is a signature fault. A dark but present image means the panel works and the backlight does not. Lost time and firmware settings point at the coin cell that keeps the real-time clock alive. A battery that reads full but empties fast has lost capacity. Signal that depends on lid angle implicates the antennas routed through the display. Heat-related shutdowns with a loud fan mean the heat sink cannot shed heat. Recognising these patterns lets a technician go straight to the right part.", "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "troubleshooting", "match"]}, {"id": "C1N-M-040", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A remote worker's laptop needs a replacement power adapter. The label on the laptop's DC-in area reads 20 V, 3.25 A. Which replacement is acceptable?", "options": ["A 19 V adapter rated 45 W with the matching connector", "A 24 V adapter rated 90 W with an adapter tip", "Any adapter whose connector fits", "A 20 V adapter rated 65 W or higher with the matching connector"], "answer": 1, "explanation": "Power equals voltage times current, so 20 V at 3.25 A is 65 W. A replacement must match the voltage exactly, must supply at least the required wattage (more is fine because the laptop only draws what it needs), and must have the correct connector polarity and size. A lower-wattage unit will fail to charge under load, a higher voltage can damage the charging circuit, and a connector fitting is no guarantee of correct voltage or polarity.", "distractor_analysis": {"1": "A 45 W adapter is under the 65 W requirement and the voltage is off by a volt.", "2": "24 V exceeds the 20 V rating and risks damaging the laptop.", "3": "Connector fit says nothing about voltage or polarity."}, "video_reference": {"title": "Laptop Hardware - CompTIA A+ 220-1201 - 1.1", "url": "https://www.youtube.com/watch?v=zODZ0i-Iark", "duration": "16:42", "objective": "1.1"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["laptop", "power", "ac-adapter", "wattage"]}, {"id": "C1N-M-041", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user has a current Android phone and a recent iPhone and wants one cable that charges both. Which connector do both devices use?", "options": ["Micro-USB", "Mini-USB", "USB-C", "Lightning"], "answer": 2, "explanation": "USB-C is now the common charging and data connector across Android phones, tablets, laptops and, since the iPhone 15 generation, Apple's phones as well. It is reversible, carries USB data, Power Delivery for charging and can carry DisplayPort video on devices that support alternate mode. Lightning is Apple's proprietary connector on older iPhones, Micro-USB was the previous Android standard and Mini-USB is obsolete.", "distractor_analysis": {"1": "Lightning is Apple-only and being phased out.", "2": "Micro-USB was replaced by USB-C on Android around 2016 to 2018.", "3": "Mini-USB predates Micro-USB and is found only on old cameras and accessories."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-c", "connectors"]}, {"id": "C1N-M-042", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user with an older iPhone asks why the charging cable is flat with exposed contacts on both faces and fits either way up. Which connector is this?", "options": ["30-pin dock connector", "Lightning", "USB-C", "Micro-USB"], "answer": 3, "explanation": "Lightning is Apple's proprietary eight-pin connector introduced in 2012. It is a flat reversible plug with contacts exposed on both faces rather than shrouded inside a shell. It carries power and USB 2.0 data and needs an authentication chip, which is why uncertified cables sometimes display a warning. USB-C is also reversible but its contacts are inside an oval shell, Micro-USB is one-way only, and the 30-pin connector is the wide plug Lightning replaced.", "distractor_analysis": {"1": "USB-C contacts are hidden inside an oval metal shell.", "2": "Micro-USB is trapezoidal and inserts one way only.", "3": "The 30-pin connector is much wider and predates Lightning."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "lightning", "connectors", "apple"]}, {"id": "C1N-M-043", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A technician needs a cable to connect a legacy barcode scanner with a Micro-USB port to a modern laptop that has only USB-C ports. Which cable is correct?", "options": ["USB-C to Lightning", "USB-A to USB-C", "Micro-USB to Mini-USB", "USB-C to Micro-USB"], "answer": 1, "explanation": "The cable must match the port on each end: USB-C on the laptop and Micro-USB on the scanner. Such cables exist and carry USB 2.0 data and power, which is all a Micro-USB device can use. A Lightning cable is for Apple devices, a USB-A to USB-C cable has no Micro-USB end, and a Micro to Mini cable connects two legacy devices with nothing to plug into the laptop. Reading the connector on both ends is the whole task.", "distractor_analysis": {"1": "Lightning does not fit a Micro-USB port.", "2": "The laptop has no USB-A ports, and the scanner is not USB-C.", "3": "Neither end of that cable fits the laptop."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "micro-usb", "usb-c", "cables"]}, {"id": "C1N-M-044", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user connects a USB-C phone to a USB-C monitor expecting the phone's screen to appear, but nothing displays. Charging works. What is the most likely reason?", "options": ["USB-C can never carry video", "The phone battery is too low to output video", "The phone or the cable does not support DisplayPort Alternate Mode over USB-C", "The monitor needs a Lightning input for phones"], "answer": 2, "explanation": "USB-C is a connector, not a guarantee of features. Video over USB-C requires DisplayPort Alternate Mode to be supported by the device, and the cable must be a full-featured one rather than a charge-only cable. Many phones charge over USB-C but do not implement Alt Mode at all, and some cheap cables carry only power and USB 2.0 data. Checking the phone's specification and using a cable rated for video resolves the confusion.", "distractor_analysis": {"1": "Lightning is an input on nothing; monitors do not have Lightning ports.", "2": "USB-C can carry DisplayPort and HDMI via alternate modes when supported.", "3": "Battery level does not disable video output."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-c", "displayport", "alt-mode"]}, {"id": "C1N-M-045", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A field technician wants to transfer photos from a phone to a laptop as fast as possible. The phone supports USB 3.2 over USB-C. Which cable choice matters most?", "options": ["A cable with a right-angle plug", "A cable rated for USB 3.x data rather than a charge-only or USB 2.0 cable", "A cable that is at least three metres long", "A cable with a braided jacket"], "answer": 3, "explanation": "USB-C cables vary widely in what they carry. Charge-only cables have no data wires, and many bundled cables carry only USB 2.0 at 480 Mbps. To reach USB 3.x speeds of 5 to 20 Gbps the cable itself must include the SuperSpeed wire pairs, which is usually marked on the packaging or the plug. Length, jacket and plug shape are convenience features that do not change the data rate, and very long cables can actually reduce reliable speed.", "distractor_analysis": {"1": "Longer cables lower signal integrity; length is not a speed feature.", "2": "Braiding improves durability, not bandwidth.", "3": "Plug angle is ergonomics only."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb", "data-transfer", "cables"]}, {"id": "C1N-M-046", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user places a phone on a charging pad and it charges without any cable. Which standard is most commonly used for this?", "options": ["Bluetooth", "Near-field communication", "USB Power Delivery", "Qi wireless charging"], "answer": 1, "explanation": "Qi is the industry standard for inductive wireless charging in phones and earbuds. A coil in the pad induces current in a coil inside the phone when the two are aligned within a few millimetres. Charging is slower than a cable and generates more heat, and a thick metal case or a misaligned phone stops it working, which are the usual support questions. Bluetooth and NFC are data radios, and USB Power Delivery is a wired charging negotiation.", "distractor_analysis": {"1": "Bluetooth carries data and audio, not power.", "2": "NFC is used for taps and payments; the power it transfers is negligible.", "3": "Power Delivery works only over a USB-C cable."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wireless-charging", "qi"]}, {"id": "C1N-M-047", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A phone will not charge on a Qi pad but charges normally from a cable. The user recently added a thick case with a metal plate for a car mount. What should the technician recommend?", "options": ["Switch the pad to a faster power adapter", "Enable Bluetooth so the pad can pair with the phone", "Remove the metal plate or case, because metal between the coils blocks inductive charging", "Replace the phone's charging port"], "answer": 2, "explanation": "Inductive charging relies on a magnetic field coupling the pad's coil to the phone's coil. A metal plate in the path absorbs the field, heats up and prevents the phone charging, and even a thick non-metal case can push the coils too far apart. Cable charging works because it bypasses the coil entirely, which rules out a port fault. Adapter wattage and Bluetooth have no role in whether the inductive link forms.", "distractor_analysis": {"1": "The port is proven working by the successful cable charge.", "2": "A stronger adapter cannot push a field through metal.", "3": "Qi pads do not pair over Bluetooth."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wireless-charging", "qi", "troubleshooting"]}, {"id": "C1N-M-048", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user wants to pay for coffee by holding a phone near the card terminal. Which short-range technology makes this possible?", "options": ["Wi-Fi Direct", "Near-field communication", "Bluetooth Low Energy", "Infrared"], "answer": 3, "explanation": "NFC operates over a few centimetres at 13.56 MHz and is what contactless payment systems such as Apple Pay and Google Wallet use to exchange a tokenised card credential with the terminal. The very short range is a security feature. NFC is also used to pair Bluetooth accessories with a tap and to read tags. Bluetooth reaches metres and needs pairing, infrared was an old line-of-sight link for early PDAs, and Wi-Fi Direct is for file transfer between devices.", "distractor_analysis": {"1": "Bluetooth's range and pairing model are unsuitable for tap-to-pay.", "2": "Infrared beaming is obsolete and needs line of sight.", "3": "Wi-Fi Direct is peer-to-peer file transfer, not payment."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "nfc", "payments"]}, {"id": "C1N-M-049", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user's contactless payments stopped working after they put the phone in a new wallet case with several cards inside. Payments work when the phone is taken out of the case. What is the cause?", "options": ["The case has disabled the phone's Bluetooth radio", "The phone's battery is too low for NFC", "The payment app needs to be reinstalled", "The other contactless cards in the case interfere with the phone's NFC field"], "answer": 1, "explanation": "NFC terminals read one credential at a time. When a wallet case places bank cards directly over the phone's NFC antenna, the terminal sees multiple contactless targets and either rejects the read or the cards absorb the field so the phone cannot respond. Removing the cards, or using a case with a shielding layer, fixes it. The successful payments outside the case prove the radio, battery and app are all fine.", "distractor_analysis": {"1": "Contactless payment uses NFC, and a case cannot switch off a radio.", "2": "Payments work outside the case at the same battery level.", "3": "The app works as soon as the phone leaves the case."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "nfc", "payments", "troubleshooting"]}, {"id": "C1N-M-050", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which wireless technology is used to connect a phone to a car's hands-free system and to wireless earbuds?", "options": ["Cellular", "GPS", "Bluetooth", "NFC"], "answer": 2, "explanation": "Bluetooth is the short-range personal area network radio used for audio accessories, keyboards, wearables and car hands-free systems. Devices are paired once, after which they reconnect automatically when in range of roughly ten metres. Modern devices use Bluetooth Low Energy for wearables and sensors and classic Bluetooth profiles for audio. NFC only reaches a few centimetres, cellular is the wide-area voice and data network, and GPS is receive-only positioning.", "distractor_analysis": {"1": "NFC is sometimes used to trigger the pairing, but the audio link is Bluetooth.", "2": "Cellular connects to the carrier network, not to local accessories.", "3": "GPS receives satellite signals and cannot connect to accessories."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "accessories"]}, {"id": "C1N-M-051", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "Wireless earbuds that paired to a phone yesterday will not connect today. They appear in the paired list but show as disconnected. The earbuds are charged. What should the user try first?", "options": ["Enable Airplane mode permanently", "Turn Bluetooth off and on, or forget the earbuds and pair them again", "Factory reset the phone", "Replace the earbuds"], "answer": 3, "explanation": "Stale pairing state is the most common Bluetooth complaint. Toggling the radio forces a reconnection attempt, and if that fails, removing the device from the paired list and pairing fresh rebuilds the link keys on both ends. Also check the earbuds are not still connected to another device such as a laptop, because most earbuds hold one active connection. A phone reset or new hardware is disproportionate, and Airplane mode disables the radio you need.", "distractor_analysis": {"1": "A full reset destroys user data to fix a pairing key.", "2": "The hardware is not shown to be faulty.", "3": "Airplane mode turns Bluetooth off by default."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "pairing", "troubleshooting"]}, {"id": "C1N-M-052", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user wants to pair a new Bluetooth keyboard but the phone never lists it. The keyboard's light is on. What is the most likely reason?", "options": ["The phone needs an NFC tag to discover keyboards", "Bluetooth keyboards only work with laptops", "The phone's Wi-Fi is turned off", "The keyboard is not in pairing mode, so it is not advertising itself"], "answer": 1, "explanation": "A Bluetooth accessory only becomes discoverable when it is put into pairing mode, usually by holding a dedicated button until an LED blinks in a distinctive pattern. A power light alone means it is on, possibly still bound to a previous device. Once in pairing mode it appears in the phone's list within seconds and a PIN or confirmation completes the process. NFC is optional, keyboards work with any Bluetooth host, and Wi-Fi is a separate radio.", "distractor_analysis": {"1": "NFC tap-to-pair is a convenience on some accessories, never a requirement.", "2": "Phones and tablets support Bluetooth HID keyboards.", "3": "Bluetooth discovery does not depend on Wi-Fi."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "pairing", "keyboard"]}, {"id": "C1N-M-053", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A photographer wants to move a stack of raw images from a phone to a laptop in a location with no Wi-Fi and no cable. Both devices support Bluetooth. Why might the technician still advise against Bluetooth for this task?", "options": ["Bluetooth requires an internet connection", "Bluetooth transfers are not encrypted", "Bluetooth's data rate is low, so a large transfer takes a very long time", "Bluetooth cannot transfer image files"], "answer": 2, "explanation": "Bluetooth is designed for low power and modest bandwidth. Even Bluetooth 5 tops out at around 2 Mbps in practice, so several gigabytes of raw photos would take hours. Wi-Fi Direct, a phone hotspot or a USB cable are all far faster. Bluetooth can transfer any file type, needs no internet and does encrypt its links; its only real limitation for this job is speed, which is why it is used for audio and small data rather than bulk transfer.", "distractor_analysis": {"1": "Bluetooth file transfer supports any file type.", "2": "Bluetooth is a direct device-to-device link with no internet dependency.", "3": "Bluetooth links are encrypted after pairing."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "data-transfer", "bandwidth"]}, {"id": "C1N-M-054", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A laptop with a single USB-C port needs to connect to a wired network, an HDMI projector, a USB-A mouse and a charger at the same time. Which accessory meets the requirement?", "options": ["A Qi charging pad", "A USB-C docking station or multiport hub with Power Delivery pass-through", "A USB-A to Ethernet adapter", "A Lightning to HDMI adapter"], "answer": 3, "explanation": "A docking station or multiport hub expands one USB-C connection into several interfaces: Ethernet, HDMI or DisplayPort, USB-A ports and a USB-C power input that passes charging through to the laptop. This is the standard accessory for thin laptops with few ports. A single-purpose USB-A Ethernet adapter does not fit a USB-C port and covers only one need, Lightning belongs to older Apple phones, and a Qi pad charges phones, not laptops.", "distractor_analysis": {"1": "It has the wrong plug for the laptop and solves only the network need.", "2": "Lightning is not a laptop connector.", "3": "Qi is inductive phone charging and provides no ports."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "docking-station", "usb-c", "hub"]}, {"id": "C1N-M-055", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user reports that the laptop does not charge while connected to a new USB-C hub, although the monitor and keyboard attached to the hub work. What is the most likely explanation?", "options": ["USB-C hubs are not capable of charging laptops", "The keyboard is drawing all the available power", "The monitor cable is too long", "The hub lacks a Power Delivery pass-through port or the charger is plugged into the laptop's port on the hub rather than the hub's power input"], "answer": 1, "explanation": "Many inexpensive hubs have a data-only USB-C port and no power input, so the laptop must be charged separately. Hubs that do support charging have a clearly marked PD input port; plugging the charger into an ordinary downstream port does nothing for the laptop. Checking the hub's specification for a PD pass-through rating at or above the laptop's wattage is the fix. Hubs certainly can charge laptops when built for it, a keyboard draws a few milliamps, and cable length does not affect charging.", "distractor_analysis": {"1": "Docking stations charge laptops routinely through PD pass-through.", "2": "A keyboard's draw is negligible.", "3": "Video cable length has no bearing on the power path."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "hub", "power-delivery", "troubleshooting"]}, {"id": "C1N-M-056", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "Which accessory is designed to hold a tablet steady while an artist draws on it with a stylus?", "options": ["A screen protector", "A USB-C hub", "An adjustable stand or drawing tripod", "A wireless charging pad"], "answer": 2, "explanation": "Stands and mounts are simple accessories that matter a great deal to usability: an adjustable stand tilts a tablet to a comfortable drawing angle and keeps it stable under stylus pressure. Technicians are often asked to recommend mounts for point-of-sale tablets, kiosks and vehicles as well. A charging pad supplies power, a screen protector guards the glass and a hub adds ports; none of them positions the device.", "distractor_analysis": {"1": "Charging pads power the device but do not hold it at an angle.", "2": "Screen protectors protect the glass but provide no support.", "3": "Hubs add connectivity, not positioning."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "stand", "tablet"]}, {"id": "C1N-M-057", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user applied a tempered glass screen protector and now the phone's fingerprint sensor under the display fails most of the time. What is the correct advice?", "options": ["Fingerprint sensors never work with any protector", "Use a protector certified for in-display fingerprint sensors, then re-enrol the fingerprint through the protector", "The sensor is broken and the phone needs repair", "Disable the screen protector in settings"], "answer": 3, "explanation": "Optical and ultrasonic in-display sensors read the finger through the glass. A thick or air-gapped protector scatters the light or dampens the ultrasound and the stored template no longer matches. Protectors made for that phone model are thin and optically clear over the sensor area, and re-enrolling with the protector fitted gives the sensor a template that matches what it now sees. The hardware is fine, protectors are not software, and correctly chosen protectors work well.", "distractor_analysis": {"1": "The sensor worked before the protector; the glass is the variable.", "2": "A protector is a physical film; there is nothing to disable.", "3": "Compatible protectors are sold specifically for these sensors."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "screen-protector", "fingerprint", "accessories"]}, {"id": "C1N-M-058", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A delivery company needs to attach phones to delivery bikes in all weather and still charge them during the shift. Which combination of accessories fits the requirement?", "options": ["A leather wallet case and a desktop charging pad", "A clear silicone case and a Bluetooth keyboard", "A tempered glass protector and a USB hub", "A rugged waterproof case with a handlebar mount and a weather-sealed charging solution"], "answer": 1, "explanation": "The requirement is protection from impact and water, secure attachment to a vehicle, and power on the move. A rugged, ingress-rated case, a locking handlebar mount and a sealed charging path such as a covered USB port or a wireless charging mount meet all three. Wallet cases and desk pads suit an office, a keyboard is irrelevant on a bike, and a hub and protector solve neither mounting nor weather.", "distractor_analysis": {"1": "Leather and a desk pad do not survive rain or stay on a bike.", "2": "A keyboard is unusable on a moving vehicle.", "3": "Neither item mounts or protects the phone."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "accessories", "rugged-case", "mount"]}, {"id": "C1N-M-059", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user's phone battery does not last a full day of travel. Which accessory gives the simplest fix without any repair?", "options": ["A screen protector", "A car mount", "A portable battery pack (power bank)", "A Bluetooth headset"], "answer": 2, "explanation": "A power bank is a portable battery with USB outputs that recharges a phone anywhere. Technicians should advise on capacity in milliamp-hours relative to the phone's battery, on output wattage if fast charging is wanted, and on airline rules that limit lithium batteries in carry-on to roughly 100 Wh. The other accessories change how the phone is used or protected but do nothing for runtime.", "distractor_analysis": {"1": "A headset consumes power rather than supplying it.", "2": "A protector guards the glass only.", "3": "A mount holds the phone but does not charge it unless it is a charging mount."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "power-bank", "battery", "accessories"]}, {"id": "C1N-M-060", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user's phone charges very slowly from a power bank that is rated 10,000 mAh with a 5 V 1 A output. The phone supports 25 W fast charging. Why is charging slow?", "options": ["Power banks cannot fast charge any phone", "The power bank's output is only 5 W, far below what the phone can accept", "The power bank's capacity is too small to fast charge", "The phone is set to low power mode"], "answer": 3, "explanation": "Charging speed is set by the output power, which is voltage times current. A 5 V 1 A output is 5 W regardless of the bank's capacity in milliamp-hours, which only describes how much energy is stored. To fast charge, the bank must support USB Power Delivery or the phone's proprietary protocol at 18 to 25 W or more. Capacity is unrelated to rate, low power mode does not throttle charging, and PD-capable power banks fast charge normally.", "distractor_analysis": {"1": "Capacity is how much energy is stored, not how fast it is delivered.", "2": "Low power mode reduces consumption; it does not slow charging.", "3": "Many power banks support PD fast charging at 20 W or more."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "power-bank", "charging", "wattage"]}, {"id": "C1N-M-061", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "Which type of USB-C cable is required to connect a laptop to a 40 Gbps Thunderbolt 4 dock and use its full bandwidth?", "options": ["Any USB-C charging cable", "A USB 2.0 rated USB-C cable", "A Lightning cable with a USB-C end", "A Thunderbolt-certified cable, marked with the lightning-bolt symbol"], "answer": 1, "explanation": "Thunderbolt uses the USB-C connector but demands a cable built to its specification, identified by the lightning-bolt logo and, for longer runs, active electronics in the plug. A generic USB-C cable may negotiate only USB 3 or even USB 2 speeds, so the dock's displays and drives underperform or fail to appear. Charging-grade and USB 2.0 cables lack the high-speed pairs, and a Lightning cable is for older Apple phones.", "distractor_analysis": {"1": "Charging cables often omit high-speed data lines entirely.", "2": "USB 2.0 cables cap at 480 Mbps.", "3": "Lightning cables connect old iPhones and carry USB 2.0 only."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "thunderbolt", "usb-c", "docking-station"]}, {"id": "C1N-M-062", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user complains that a phone connected to a laptop over USB-C only offers charging, and the laptop cannot see the phone's files. Which step on the phone fixes this?", "options": ["Turn on the mobile hotspot", "Insert a memory card", "Change the USB connection mode from charging only to file transfer", "Enable Bluetooth"], "answer": 2, "explanation": "Phones default to charge-only when connected to a computer as a privacy protection. A notification appears offering USB options, and selecting file transfer (MTP) or photo transfer (PTP) exposes the storage to the computer. On some phones the device must also be unlocked and a trust prompt accepted. Bluetooth and hotspot are unrelated radios, and a memory card adds storage without changing the USB mode.", "distractor_analysis": {"1": "Bluetooth is a separate wireless link and does not change the USB mode.", "2": "Hotspot shares the phone's internet connection.", "3": "Storage is present; the phone is simply not exposing it."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb", "mtp", "file-transfer"]}, {"id": "C1N-M-063", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "hard", "question": "A phone charges only when the cable is held at an angle, and lint is visible inside the port. What should the technician do first?", "options": ["Apply contact cleaner spray into the port while the phone is on", "Power the phone off and carefully remove debris from the port with a non-conductive tool", "Replace the phone's battery", "Push the cable in harder to compress the debris"], "answer": 3, "explanation": "Pocket lint packs into the bottom of charging ports and stops the plug seating fully, producing exactly this angle-dependent charging. With the phone off, a wooden or plastic pick lifts the debris out without shorting or scratching the contacts, and a quick check with a light confirms the port is clear. Only if a clean port still charges intermittently is the port or its flex cable suspect. Forcing the cable damages the port, and spraying liquid into a powered device risks a short.", "distractor_analysis": {"1": "The battery is not implicated by a mechanical seating problem.", "2": "Force bends the port's contacts and worsens the fault.", "3": "Liquids and a powered device are a short-circuit risk."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "charging-port", "troubleshooting", "maintenance"]}, {"id": "C1N-M-064", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user has a tablet with a proprietary magnetic connector on its edge. Which accessory is this connector most likely designed for?", "options": ["A detachable keyboard cover that draws power and data from the tablet", "A Qi wireless charging pad", "A pair of Bluetooth earbuds", "An NFC payment terminal"], "answer": 0, "explanation": "Tablet makers add a magnetic pogo-pin connector along one edge so a keyboard cover can attach without pairing or charging: the tablet supplies power and the keys send data over the pins. Because it is proprietary, only the vendor's or licensed keyboards fit. Wireless charging uses a coil behind the back glass, earbuds connect over Bluetooth, and payments use the NFC antenna; none of them use an edge connector.", "distractor_analysis": {"1": "Qi charging is coil-based and needs no physical connector.", "2": "Earbuds pair over Bluetooth.", "3": "NFC is contactless."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "tablet", "keyboard", "proprietary-connector"]}, {"id": "C1N-M-065", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user wants to use a stylus for handwritten notes on a tablet, but a cheap capacitive stylus gives thick imprecise lines. What should the technician recommend?", "options": ["An active stylus supported by the tablet, which offers a fine tip, pressure sensitivity and palm rejection", "A larger capacitive stylus", "A screen protector to make the surface smoother", "Increasing the display brightness"], "answer": 0, "explanation": "A passive capacitive stylus is simply a conductive rubber tip that imitates a fingertip, so the tablet sees a large blunt contact. An active stylus communicates with the digitizer, often over Bluetooth or a vendor protocol, to report a precise tip position, pressure and tilt, and lets the tablet ignore the resting palm. It must be a model the tablet supports. Bigger passive tips make lines coarser, and protectors and brightness do not change the input precision.", "distractor_analysis": {"1": "A larger passive tip is even less precise.", "2": "A protector changes feel, not digitizer resolution.", "3": "Brightness affects visibility only."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "stylus", "tablet", "accessories"]}, {"id": "C1N-M-066", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "An office wants to connect an older Lightning iPhone to a conference room display with HDMI input for a presentation. Which accessory is needed?", "options": ["A Lightning to HDMI digital adapter", "A USB-C to HDMI cable", "A Micro-USB to HDMI MHL adapter", "A DisplayPort cable"], "answer": 0, "explanation": "Lightning iPhones output video through an Apple-certified Lightning digital AV adapter that provides an HDMI port and a Lightning pass-through for charging. Uncertified adapters frequently fail or stop working after updates. USB-C to HDMI suits newer iPhones and Android phones with Alt Mode, MHL was a Micro-USB era Android standard, and a DisplayPort cable has no end that fits the phone.", "distractor_analysis": {"1": "The phone has a Lightning port, not USB-C.", "2": "MHL adapters are for Micro-USB Android phones and are largely obsolete.", "3": "Neither end of a DisplayPort cable fits a phone."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "lightning", "hdmi", "adapters"]}, {"id": "C1N-M-067", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user complains that a Bluetooth headset connected to a phone has audio that lags noticeably behind video. Which factor is the most likely cause?", "options": ["The audio codec and buffering used over Bluetooth introduce latency", "The phone's Wi-Fi is turned off", "The headset is in pairing mode", "The phone has no SIM card"], "answer": 0, "explanation": "Bluetooth audio is compressed and buffered before transmission, which adds tens to hundreds of milliseconds of delay depending on the codec. Basic SBC has the most lag; codecs such as aptX Low Latency or AAC with a well-matched headset reduce it, and many video apps compensate automatically. The delay is inherent to the wireless link, not a fault. Wi-Fi, pairing state and cellular service have no bearing on the timing of audio already playing.", "distractor_analysis": {"1": "Wi-Fi is not involved in a local Bluetooth stream.", "2": "A headset in pairing mode would not be playing audio.", "3": "Cellular service has nothing to do with local audio playback."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "audio", "latency"]}, {"id": "C1N-M-068", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A field technician wants a USB-C phone to read files from a USB-A flash drive. Which single accessory makes this possible?", "options": ["A USB-C on-the-go adapter or hub that provides a USB-A host port", "A Lightning to USB camera adapter", "A Qi receiver coil", "An NFC tag"], "answer": 0, "explanation": "Phones and tablets can act as a USB host, a capability called USB On-The-Go. A small USB-C to USB-A OTG adapter lets the phone power and mount a flash drive, and a hub does the same for several devices at once. Once attached, the files app shows the drive. The Lightning camera adapter does this job for older iPhones only, and a Qi coil or an NFC tag has nothing to do with USB storage.", "distractor_analysis": {"1": "The camera adapter has a Lightning plug and will not fit USB-C.", "2": "Qi receivers are for wireless charging.", "3": "NFC tags store a few hundred bytes and cannot host a drive."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-otg", "adapter", "storage"]}, {"id": "C1N-M-069", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A phone's NFC payment works, but tapping it against an NFC-equipped speaker does not start Bluetooth pairing as advertised. Which setting is most likely the cause?", "options": ["NFC tag reading or the tap-to-pair feature is disabled on the phone, or the phone is an iPhone that does not support NFC pairing this way", "The speaker needs Wi-Fi", "The phone's SIM is locked", "The speaker battery is too full"], "answer": 0, "explanation": "NFC pairing works by reading a tag in the accessory that carries the Bluetooth address and then completing the pairing automatically. Android phones must have NFC enabled and often have a separate toggle for reading tags; iPhones restrict background NFC use so this convenience does not work with most speakers. Payment working shows the NFC radio is fine, so the issue is the feature or platform, not the hardware. Wi-Fi, SIM state and battery level are irrelevant.", "distractor_analysis": {"1": "Bluetooth speakers do not need Wi-Fi.", "2": "SIM lock affects cellular service only.", "3": "A full battery does not disable pairing."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "nfc", "bluetooth", "pairing"]}, {"id": "C1N-M-070", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "hard", "question": "A user reports that a laptop connected through a USB-C dock loses its external monitors whenever a large file copies to a dock-attached SSD. What is the most likely cause?", "options": ["The dock is sharing limited USB-C bandwidth between DisplayPort and USB data, and the link renegotiates under load", "The monitors are too bright", "The SSD is formatted with the wrong file system", "The laptop's Bluetooth is interfering with the dock"], "answer": 0, "explanation": "A single USB-C link has a fixed number of high-speed lanes. When the dock is not Thunderbolt, DisplayPort video and USB 3 data must share those lanes, and heavy storage traffic can force a renegotiation that briefly drops the displays. Solutions include a Thunderbolt dock and cable, lowering monitor resolution or refresh rate, or moving the SSD to a port on the laptop itself. Brightness, file system and Bluetooth do not affect lane allocation.", "distractor_analysis": {"1": "Brightness is a monitor setting with no link impact.", "2": "File system affects compatibility, not the physical link.", "3": "Bluetooth is a separate radio and does not touch the USB-C link."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "docking-station", "bandwidth", "displayport"]}, {"id": "C1N-M-071", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A user has connected a USB-C laptop charger to a phone. What happens?", "options": ["The phone negotiates a safe power level with the charger and charges normally", "The phone is damaged by the higher voltage", "The phone will not charge because laptop chargers are incompatible", "The charger switches off permanently"], "answer": 0, "explanation": "USB-C Power Delivery is a negotiation. The charger advertises the voltages and currents it can provide and the phone requests only the profile it can accept, typically 9 V at 2 to 3 A. A 65 W or 100 W laptop charger therefore charges a phone safely and often faster than the phone's own small adapter. This is the interoperability benefit of USB-C, and technicians can reassure users that PD-compliant chargers are safe across device classes.", "distractor_analysis": {"1": "PD starts at 5 V and only raises voltage on request, so no damage occurs.", "2": "PD-compliant chargers work across phones, tablets and laptops.", "3": "Chargers do not disable themselves when a smaller device is attached."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-c", "power-delivery", "charging"]}, {"id": "C1N-M-072", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "Which statement about hotspot capability is correct when a user wants a laptop to get online through a phone in a location with no Wi-Fi?", "options": ["The phone can share its cellular connection over Wi-Fi, Bluetooth or USB tethering", "Tethering requires a Lightning cable", "Only tablets can create hotspots", "Hotspots work only when the phone is on Wi-Fi"], "answer": 0, "explanation": "Phones can share their mobile data three ways. A Wi-Fi hotspot is the most common and supports several clients, USB tethering charges the phone while offering a stable wired link to one laptop, and Bluetooth tethering is low power but slow. The carrier plan must allow tethering. The phone's connector type is irrelevant to the feature, phones and tablets both offer it, and a hotspot specifically shares the cellular link rather than Wi-Fi.", "distractor_analysis": {"1": "USB tethering works over whatever USB cable the phone uses.", "2": "Phones are the most common hotspot devices.", "3": "A hotspot shares cellular data; it is not dependent on Wi-Fi."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "hotspot", "tethering", "connectivity"]}, {"id": "C1N-M-073", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A user wants a wireless keyboard and mouse for a tablet but does not want to pair or charge anything. Which option is not viable and why?", "options": ["A 2.4 GHz keyboard with a USB receiver is impractical because the tablet may lack a USB-A port and the receiver still needs one", "Bluetooth is not viable because tablets cannot use keyboards", "A wired keyboard is not viable because tablets have no input capability", "An NFC keyboard is the only working option"], "answer": 0, "explanation": "Proprietary 2.4 GHz peripherals avoid Bluetooth pairing but need their small USB receiver plugged in, which a tablet with only USB-C can accommodate only through an OTG adapter, and the receiver protrudes from the device. Bluetooth is the natural fit for tablets and pairs once. A wired keyboard also works through an adapter. There is no such thing as an NFC keyboard; NFC carries too little data for continuous input.", "distractor_analysis": {"1": "Tablets support Bluetooth keyboards natively.", "2": "Wired keyboards work through a USB-C OTG adapter.", "3": "NFC has no role in continuous keyboard input."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "keyboard", "bluetooth", "accessories"]}, {"id": "C1N-M-074", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A phone's screen has fine scratches after months in a pocket with keys. The user asks how to prevent this on the replacement phone. What is the best advice?", "options": ["Fit a tempered glass or film screen protector and a case as soon as the phone is unboxed", "Increase the display brightness so scratches are less visible", "Store the phone with the screen facing the keys so the back takes the damage", "Apply furniture polish to the glass weekly"], "answer": 0, "explanation": "Screen protectors exist for exactly this reason: a sacrificial layer of tempered glass or film takes the scratches and can be replaced for a few pounds, while a case protects the edges and back from drops. Applying them before the first day of use avoids trapping dust or fitting over existing damage. Brightness does not remove scratches, deliberately facing the keys guarantees damage, and polish contains abrasives and oils that harm oleophobic coatings.", "distractor_analysis": {"1": "Brightness cannot hide physical scratches.", "2": "Facing the keys is the cause of the problem, not the solution.", "3": "Polishes can strip the coating and add micro-scratches."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "screen-protector", "case", "accessories"]}, {"id": "C1N-M-075", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "hard", "question": "A car's USB port charges a phone but the car's infotainment system does not recognise the phone for wired screen projection. The same phone and cable work in another car. What is the most likely explanation?", "options": ["The car's port is a charge-only port; the data-capable port is elsewhere", "The phone needs a new SIM card", "The cable is too short", "Screen projection requires NFC"], "answer": 0, "explanation": "Vehicles often have several USB ports, and only one or two are wired to the head unit for data; the rest are charging outlets with no data lines. Because the phone and cable are proven in another car, the variable is the port. Moving to the port marked with the data or projection symbol, or consulting the vehicle manual, resolves it. A SIM affects cellular service, cable length does not stop enumeration, and wired projection needs USB data rather than NFC.", "distractor_analysis": {"1": "Cellular service is not required for wired projection.", "2": "A short cable still carries data.", "3": "NFC is not part of wired screen projection."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb", "vehicle", "troubleshooting"]}, {"id": "C1N-M-076", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "multi", "difficulty": "medium", "question": "A technician is asked which two features of USB-C make it different from the Micro-USB it replaced on phones. Which TWO are correct? (Select TWO.)", "options": ["The plug is reversible and inserts either way up", "It can negotiate much higher charging power through Power Delivery", "It is limited to USB 2.0 speeds", "It only works with Apple devices", "It requires a separate power connector for charging"], "answers": [0, 1], "explanation": "USB-C brought two everyday improvements: a symmetrical plug that cannot be inserted the wrong way, and the Power Delivery protocol that raises charging from the 7.5 W or so of Micro-USB to 100 W and beyond, enough for laptops. Depending on the device it can also carry USB 3.x or Thunderbolt data and DisplayPort video. It is an open standard used across every platform and carries power and data in the one connector.", "distractor_analysis": {"2": "USB-C can carry USB 3.x, USB4 and Thunderbolt; only the cheapest cables are limited to USB 2.0.", "3": "USB-C is an industry standard used by Android, Windows, Apple and others.", "4": "Power and data share the single connector."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "usb-c", "micro-usb", "power-delivery"]}, {"id": "C1N-M-077", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "multi", "difficulty": "medium", "question": "A user's phone will not wirelessly charge on a Qi pad that works for a colleague's phone. Which TWO checks should the technician make first? (Select TWO.)", "options": ["Confirm the phone model actually supports wireless charging", "Remove the case and re-centre the phone on the pad", "Update the phone's Bluetooth firmware", "Insert a higher-capacity SIM card", "Enable the phone's mobile hotspot"], "answers": [0, 1], "explanation": "Two things account for almost every wireless charging complaint. Not every phone has a receiving coil, especially budget models, so the specification must be checked. When the phone does support it, a thick or metallic case or a phone lying off-centre breaks the coupling between coils, and simply removing the case and aligning the phone over the pad's marked area restores charging. Bluetooth, SIM and hotspot are unrelated to inductive charging.", "distractor_analysis": {"2": "Bluetooth has no role in wireless charging.", "3": "SIM cards carry subscriber identity and have no effect on charging.", "4": "Hotspot shares data and, if anything, drains the battery."}, "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wireless-charging", "qi", "troubleshooting"]}, {"id": "C1N-M-078", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "match", "difficulty": "medium", "question": "Match each mobile connection technology to its typical use.", "pairs": [{"left": "NFC", "right": "Contactless payment within a few centimetres"}, {"left": "Bluetooth", "right": "Wireless earbuds and car hands-free within about ten metres"}, {"left": "USB-C with Power Delivery", "right": "Fast wired charging and data for phones and laptops"}, {"left": "Qi", "right": "Cable-free inductive charging on a pad"}, {"left": "Lightning", "right": "Proprietary connector on older Apple phones"}], "explanation": "Each technology has a distinct job. NFC is deliberately short range for secure taps. Bluetooth is the personal area network for accessories. USB-C with Power Delivery is the universal wired connection that negotiates charging power. Qi is the inductive charging standard. Lightning was Apple's proprietary plug before its move to USB-C. Knowing which one is in play tells the technician where to look when a connection fails.", "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "connectivity", "match"]}, {"id": "C1N-M-079", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "order", "difficulty": "easy", "question": "Put the steps for pairing a new Bluetooth headset with a phone in the correct order.", "sequence": ["Charge the headset and confirm the phone's Bluetooth is turned on", "Hold the headset's pairing button until its light blinks in pairing mode", "Open the phone's Bluetooth settings and select the headset from the list of available devices", "Confirm any PIN or pairing prompt and wait for the status to show connected", "Play audio to verify the headset is the active output"], "explanation": "Pairing fails most often because a step is skipped: the headset is not actually in pairing mode, or the phone's radio is off. Putting the accessory into pairing mode makes it discoverable, the phone then lists it, and confirming the prompt exchanges the link keys that let the two reconnect automatically in future. Testing audio confirms the phone has actually routed sound to the new device rather than to its own speaker.", "video_reference": {"title": "Connecting Mobile Devices - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=Iis2-_89YvQ", "duration": "6:08", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "pairing", "procedure"]}, {"id": "C1N-M-080", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A company buys a mixed fleet of USB-C phones and laptops and wants one type of desk charger for every desk. Which specification should the technician require?", "options": ["USB-C Power Delivery chargers rated at or above the highest laptop wattage in the fleet", "Micro-USB chargers rated 10 W", "Lightning chargers rated 20 W", "Any USB-A charger with an adapter cable"], "answer": 0, "explanation": "Because Power Delivery negotiates downward, a single charger rated for the most demanding laptop, commonly 65 W or 100 W, will also charge every phone and tablet safely. Standardising on it simplifies procurement and support. Micro-USB and Lightning are the wrong connectors for a USB-C fleet, and USB-A chargers cannot supply the voltages laptops need, so an adapter cable would leave the laptops uncharged.", "distractor_analysis": {"1": "Micro-USB is the wrong connector and far too little power.", "2": "Lightning is Apple-specific and not a laptop connector.", "3": "USB-A ports top out around 12 to 18 W and cannot run laptops."}, "video_reference": {"title": "Mobile Device Accessories - CompTIA A+ 220-1201 - 1.2", "url": "https://www.youtube.com/watch?v=14iM8lLBS0c", "duration": "7:18", "objective": "1.2"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "power-delivery", "charger", "standardisation"]}, {"id": "C1N-M-081", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "A user's phone shows 5G in the status bar at home but only LTE in a rural area. Both allow calls and browsing. What does the change indicate?", "options": ["The phone has fallen back to the older cellular network generation available in that location", "The phone's SIM card has been deactivated", "The phone has switched to Wi-Fi calling", "The phone's cellular radio has failed"], "answer": 0, "explanation": "Cellular phones hold radios for several generations and use the fastest one the nearest tower offers. 5G coverage is concentrated in cities, so a phone that shows 5G at home and LTE (4G) in the countryside is behaving correctly and will still make calls and pass data, just at lower peak speeds. A deactivated SIM would show no service, Wi-Fi calling shows its own indicator, and a failed radio would leave the phone with no cellular signal at all.", "distractor_analysis": {"1": "A deactivated SIM produces no service rather than a slower generation.", "2": "Wi-Fi calling has its own status indicator and needs a Wi-Fi network.", "3": "A failed radio shows no signal, not LTE."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "5g", "lte"]}, {"id": "C1N-M-082", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone has a strong Wi-Fi signal but web pages will not load, while the same pages load fine on cellular data. What should the technician check first?", "options": ["Whether the Wi-Fi network has internet access or requires a captive portal sign-in", "Whether the phone's SIM card is seated", "Whether Bluetooth is enabled", "Whether the phone needs a new battery"], "answer": 0, "explanation": "Signal strength only shows that the phone is associated with the access point. A hotel, airport or guest network usually demands a captive-portal login before it forwards traffic, and a home router can lose its upstream connection while still broadcasting a strong Wi-Fi signal. Opening a browser to trigger the portal, or checking the router's internet light, resolves most cases. The SIM is proven fine by working cellular data, and Bluetooth and the battery are unrelated.", "distractor_analysis": {"1": "Cellular data works, so the SIM is seated and active.", "2": "Bluetooth has no role in Wi-Fi internet access.", "3": "Battery state does not block web traffic."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wi-fi", "captive-portal", "troubleshooting"]}, {"id": "C1N-M-083", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "A traveller wants to stop a phone using any radio during a flight but still listen to downloaded music with wired headphones. Which setting achieves this?", "options": ["Airplane mode", "Do Not Disturb", "Low power mode", "Data roaming off"], "answer": 0, "explanation": "Airplane mode disables the cellular, Wi-Fi and Bluetooth radios in one switch while leaving the rest of the phone usable, so offline music, downloaded films and local apps continue to work. On most phones Wi-Fi and Bluetooth can be re-enabled individually while airplane mode stays on, which is how in-flight Wi-Fi and wireless earbuds are used. Do Not Disturb only silences notifications, low power mode throttles performance, and data roaming controls only cellular data abroad.", "distractor_analysis": {"1": "Do Not Disturb leaves every radio on.", "2": "Low power mode saves battery but does not disable radios.", "3": "Data roaming is a cellular billing control, not a radio switch."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "airplane-mode", "radios"]}, {"id": "C1N-M-084", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user returns from abroad to a very large phone bill. The phone was used for maps and email throughout the trip. Which setting would have prevented the charges?", "options": ["Turning off data roaming, or buying a travel data plan before departure", "Turning off Bluetooth", "Enabling Do Not Disturb", "Lowering the screen brightness"], "answer": 0, "explanation": "Roaming means the phone attaches to a foreign carrier's network, and data used there is billed at that carrier's rates unless the home plan includes roaming. Disabling data roaming makes the phone use only Wi-Fi for data abroad, and a travel plan or local SIM caps the cost. Technicians supporting travelling staff should set expectations before the trip. Bluetooth, notification settings and brightness have no effect on cellular data charges.", "distractor_analysis": {"1": "Bluetooth uses no cellular data.", "2": "Do Not Disturb hides alerts but apps still sync in the background.", "3": "Brightness affects battery, not billing."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "roaming", "cellular", "data"]}, {"id": "C1N-M-085", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user needs to work on a laptop in a park with no Wi-Fi. The phone has a good cellular signal. What is the quickest way to get the laptop online?", "options": ["Enable the phone's Wi-Fi hotspot and join the laptop to it", "Pair the laptop and phone over NFC", "Plug the phone into the laptop's HDMI port", "Enable airplane mode on the phone"], "answer": 0, "explanation": "A hotspot turns the phone into a small Wi-Fi access point that shares its cellular data connection. The laptop joins it like any other network, using the password shown on the phone. Technicians should remind users that hotspot use counts against the phone plan's data allowance, drains the battery quickly, and that USB tethering is an alternative that charges the phone at the same time. NFC and HDMI do not carry internet, and airplane mode would switch the cellular radio off.", "distractor_analysis": {"1": "NFC exchanges tiny amounts of data at very short range.", "2": "HDMI carries video, not network traffic.", "3": "Airplane mode disables the very radio that provides the data."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "hotspot", "tethering", "cellular"]}, {"id": "C1N-M-086", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone's location in a mapping app is accurate outdoors but jumps around or is unavailable inside a large building. Why?", "options": ["GPS needs a clear view of satellites, and indoors the phone falls back to less precise Wi-Fi and cellular positioning", "The phone's SIM card cannot be read indoors", "Mapping apps only work over Wi-Fi", "The phone's compass is broken"], "answer": 0, "explanation": "Satellite positioning depends on receiving weak signals from several satellites at once, and roofs and floors block them. Indoors the phone estimates location from known Wi-Fi access points and cell towers, which is accurate to tens or hundreds of metres rather than a few metres, hence the jumping. This is normal behaviour, not a fault. The SIM is unaffected by buildings, mapping works over any data connection, and the compass gives heading rather than position.", "distractor_analysis": {"1": "SIM operation does not depend on the phone's surroundings.", "2": "Maps work over cellular data as well as Wi-Fi.", "3": "A compass fault would affect the direction arrow, not the position."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "gps", "location", "positioning"]}, {"id": "C1N-M-087", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "Which technology allows a phone to determine its position using signals from orbiting satellites?", "options": ["GPS and other global navigation satellite systems", "NFC", "Bluetooth", "Cellular triangulation"], "answer": 0, "explanation": "Phones include a receiver for GPS and usually for other constellations such as Galileo, GLONASS and BeiDou, which are collectively called global navigation satellite systems. The receiver measures the time of arrival of signals from at least four satellites to compute a position, typically within a few metres outdoors. The receiver is passive and works without a data plan, although maps need data to download. Cellular triangulation is a fallback estimate, and NFC and Bluetooth are short-range links.", "distractor_analysis": {"1": "NFC operates over centimetres and has no positioning role.", "2": "Bluetooth beacons can assist indoors but do not provide global positioning.", "3": "Cell triangulation is a coarse fallback, not the satellite technology asked about."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "gps", "gnss", "location"]}, {"id": "C1N-M-088", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A company issues phones and wants to enforce a passcode, push corporate Wi-Fi settings and remotely wipe a lost device. Which type of system provides these controls?", "options": ["Mobile device management (MDM)", "A mobile hotspot", "A cloud photo backup service", "A Bluetooth beacon network"], "answer": 0, "explanation": "MDM platforms enrol phones and tablets so an administrator can push configuration profiles, require a passcode and encryption, install or block apps, and wipe or lock a device that is lost. Devices are enrolled either automatically through the vendor's business programme or manually with an enrolment app or profile. MDM is the foundation of corporate mobile support. Hotspots, photo backup and beacons solve entirely different problems.", "distractor_analysis": {"1": "A hotspot shares a data connection.", "2": "Photo backup protects pictures, not device policy.", "3": "Beacons provide indoor location, not management."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "management", "security"]}, {"id": "C1N-M-089", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "An employee wants to use a personal phone for work email. The company requires that corporate data can be removed without touching personal photos and messages. Which MDM approach satisfies this?", "options": ["A bring-your-own-device policy using a managed work profile or container with selective wipe", "Full device enrolment with mandatory factory reset on departure", "Disabling the phone's camera", "Requiring the phone to stay on the office Wi-Fi"], "answer": 0, "explanation": "Modern MDM separates work and personal data on a personal device. Android creates a work profile and iOS uses managed apps and accounts, so corporate email, contacts and files live in a container that the administrator controls. When the employee leaves, a selective wipe removes only that container and leaves personal content untouched. A full factory reset would violate the requirement, and camera or network restrictions do not address data separation.", "distractor_analysis": {"1": "A factory reset destroys the employee's personal data.", "2": "Disabling the camera is a policy control unrelated to data separation.", "3": "Network restrictions do not partition data on the device."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "byod", "work-profile"]}, {"id": "C1N-M-090", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A sales team's phones must sign in to corporate email with a certificate instead of a password, and the certificate must be installed on every phone without user involvement. Which mechanism does this?", "options": ["A configuration profile pushed by the MDM containing the account settings and certificate", "Emailing each user a PDF with instructions", "Enabling Bluetooth file sharing", "Setting the phones to airplane mode during setup"], "answer": 0, "explanation": "MDM configuration profiles are signed bundles of settings: mail accounts, Wi-Fi networks, VPN definitions, certificates and restrictions. When pushed to an enrolled phone, the settings apply silently, so every device gets the same account and certificate with no user typing. This is how enterprises deploy certificate-based authentication at scale. Manual instructions do not scale and invite errors, Bluetooth sharing is insecure for credentials, and airplane mode blocks the push.", "distractor_analysis": {"1": "Manual steps on hundreds of phones are slow and error-prone.", "2": "Bluetooth sharing is not a management channel.", "3": "Airplane mode disconnects the phone from the MDM server."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "configuration-profile", "certificates"]}, {"id": "C1N-M-091", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "A user configures a corporate email account on a phone using only an email address and password, and the phone finds the server settings automatically. Which feature made this possible?", "options": ["Autodiscover, which looks up the mail server configuration from the domain", "Bluetooth pairing with the mail server", "A hotspot connection", "GPS location services"], "answer": 0, "explanation": "Modern mail systems such as Microsoft 365 and Google Workspace publish their server details so a client can look them up from the domain part of the address. The phone queries the autodiscover record, retrieves the server names, ports and security settings, and completes the account with just the credentials. If autodiscover is missing the user must enter incoming and outgoing server settings manually, which is where support calls come from.", "distractor_analysis": {"1": "Bluetooth has no role in email configuration.", "2": "A hotspot provides connectivity but not server settings.", "3": "Location services do not discover mail servers."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "email", "autodiscover", "configuration"]}, {"id": "C1N-M-092", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user sets up a personal email account on a phone and finds that deleting a message on the phone does not remove it from the webmail inbox. Which protocol is the phone most likely using?", "options": ["POP3, which downloads messages and does not keep the mailbox in sync", "IMAP, which keeps every client synchronised with the server", "Exchange ActiveSync", "SMTP"], "answer": 0, "explanation": "POP3 pulls copies of messages to the device and, depending on settings, leaves the originals on the server, so actions on one device are not reflected anywhere else. IMAP and Exchange ActiveSync keep the mailbox on the server and synchronise every folder and read or delete state to all clients, which is the behaviour users expect today. Switching the account to IMAP fixes the complaint. SMTP only sends mail and never affects the inbox.", "distractor_analysis": {"1": "IMAP would have deleted the message everywhere.", "2": "ActiveSync synchronises state across devices in the same way as IMAP.", "3": "SMTP is the outgoing protocol and does not manage the inbox."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "email", "pop3", "imap"]}, {"id": "C1N-M-093", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user must manually configure a mail account on a phone. The provider says incoming mail uses IMAP over SSL and outgoing uses SMTP with STARTTLS. Which port pair is correct?", "options": ["Incoming 993, outgoing 587", "Incoming 110, outgoing 25", "Incoming 143, outgoing 465", "Incoming 995, outgoing 80"], "answer": 0, "explanation": "IMAP over an implicit SSL/TLS connection listens on TCP 993, and the modern client submission port for SMTP, which starts unencrypted and upgrades with STARTTLS, is TCP 587. Port 110 is plain POP3 and 25 is server-to-server relay that most providers block for clients. Port 143 is unencrypted IMAP, 465 is SMTP over implicit TLS rather than STARTTLS, and 995 is POP3 over SSL with 80 being HTTP. Matching the port to the encryption method is what makes the account connect.", "distractor_analysis": {"1": "110 and 25 are unencrypted POP3 and relay SMTP.", "2": "143 is IMAP without encryption and 465 is implicit TLS rather than STARTTLS.", "3": "995 is secure POP3 and 80 is web traffic."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "email", "ports", "imap", "smtp"]}, {"id": "C1N-M-094", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "A user replaced a lost phone and, after signing in to the same account, found contacts, calendar and photos restored automatically. Which feature made this happen?", "options": ["Cloud synchronisation and backup tied to the user's account", "Bluetooth transfer from the old phone", "A SIM card swap", "An MDM remote wipe"], "answer": 0, "explanation": "Both major platforms continuously synchronise contacts, calendars, notes and settings to the account in the cloud, and take periodic full backups over Wi-Fi. Signing in on a new device pulls that data back down. Technicians should confirm backup is enabled and has run recently before any repair or replacement. The old phone was lost, so no local transfer was possible; a SIM only carries the subscriber identity, and a wipe removes data rather than restoring it.", "distractor_analysis": {"1": "The old phone was lost, so it could not be the source.", "2": "A SIM does not store contacts or photos in modern use.", "3": "A remote wipe erases a device."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronisation", "backup", "cloud"]}, {"id": "C1N-M-095", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user complains that photos taken on the phone do not appear on the laptop even though both use the same cloud account. The phone has been on cellular data all day. What is the most likely reason?", "options": ["Photo synchronisation is set to upload over Wi-Fi only and the phone has not been on Wi-Fi", "The laptop needs a SIM card", "The photos are too high resolution to sync", "Bluetooth is disabled on the laptop"], "answer": 0, "explanation": "Cloud photo services default to uploading over Wi-Fi to protect the user's cellular allowance, so pictures taken away from Wi-Fi queue up until the phone returns to a wireless network. The user can either join Wi-Fi or enable cellular upload in the app settings. Laptops do not need SIMs to reach cloud services, resolution does not block sync, and Bluetooth plays no part in cloud synchronisation.", "distractor_analysis": {"1": "The laptop reaches the cloud over its own internet connection.", "2": "Cloud services accept full-resolution photos.", "3": "Cloud sync runs over the internet, not Bluetooth."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronisation", "photos", "cellular"]}, {"id": "C1N-M-096", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone's storage is full and the user is told that enabling cloud photo storage will help. How does that feature typically free space?", "options": ["Full-resolution originals are kept in the cloud and the phone keeps smaller optimised versions", "Photos are compressed to black and white", "Photos are moved to the SIM card", "The phone deletes all photos older than a week"], "answer": 0, "explanation": "Optimised storage keeps the original files safely in the account and replaces local copies with device-sized versions, downloading the original on demand when the user opens or edits a picture. This can free many gigabytes without losing anything. Users should understand that the originals now depend on the account and that a full-resolution download needs connectivity. Colour is unchanged, SIMs hold no photos, and nothing is deleted from the account.", "distractor_analysis": {"1": "Optimised versions are full colour, just smaller.", "2": "SIM cards hold kilobytes of subscriber data, not photos.", "3": "Photos remain in the cloud indefinitely."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cloud", "storage", "photos"]}, {"id": "C1N-M-097", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "An administrator needs to locate a company tablet that was left in a taxi and then erase it if it cannot be recovered. Which capability of the management platform does this rely on?", "options": ["Remote locate and remote wipe on an enrolled device", "Bluetooth tethering", "Configuration profile for Wi-Fi", "App store restrictions"], "answer": 0, "explanation": "MDM and the platform vendors' own services can report an enrolled device's last known location, play a sound, lock it with a message, and finally wipe it. The wipe command executes as soon as the device next connects to any network, which is why the device should be locked first rather than wiped immediately if there is a chance of recovery. Tethering, Wi-Fi profiles and app restrictions are unrelated to finding or erasing a lost device.", "distractor_analysis": {"1": "Tethering shares data; it does not locate anything.", "2": "A Wi-Fi profile configures networks, not device recovery.", "3": "App restrictions control what can be installed."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "remote-wipe", "lost-device"]}, {"id": "C1N-M-098", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A company wants every corporate phone to require two-factor authentication for its email app and to block the app from copying text into personal apps. Which category of MDM control handles the copy restriction?", "options": ["Mobile application management (MAM) or app protection policies", "Wi-Fi configuration profiles", "Remote wipe", "Location services"], "answer": 0, "explanation": "Application-level management applies policy inside managed apps: requiring a PIN or biometric to open the app, blocking cut and paste to unmanaged apps, preventing saving to personal storage and encrypting app data. It works alongside device enrolment and is the only way to enforce these controls on a personal device. Wi-Fi profiles, remote wipe and location are device-level features that do not govern data movement between apps.", "distractor_analysis": {"1": "Wi-Fi profiles push network settings.", "2": "Remote wipe erases; it does not govern day-to-day data flow.", "3": "Location services report position and do not control clipboard use."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "mam", "app-protection"]}, {"id": "C1N-M-099", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user cannot enrol a new phone in the company's MDM. The enrolment app reports that the device is not eligible. The phone was bought second-hand. What is the most likely cause?", "options": ["The device is still registered to the previous owner's account or management, an activation lock", "The phone's Bluetooth is off", "The phone has too much free storage", "The user has not set a wallpaper"], "answer": 0, "explanation": "Both platforms tie a device to the account or organisation that last activated it. A second-hand phone whose previous owner did not sign out and remove it stays locked to that owner, and a phone previously enrolled by another company stays in that company's management programme. Enrolment is refused until the previous party releases it. This is also why corporate procurement prefers devices bought through channels that register them directly to the company.", "distractor_analysis": {"1": "Enrolment works over Wi-Fi or cellular and does not need Bluetooth.", "2": "Free storage is never a barrier to enrolment.", "3": "Wallpaper is cosmetic."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "activation-lock", "enrolment"]}, {"id": "C1N-M-100", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "A user asks what the tiny removable card in the phone's side tray is for. What is the correct answer?", "options": ["It is the SIM, which identifies the subscriber to the carrier's network", "It stores all the user's photos", "It holds the phone's operating system", "It is the Bluetooth antenna"], "answer": 0, "explanation": "The subscriber identity module carries the account identity and authentication key that let the carrier recognise the phone on its network. Moving the SIM to another unlocked phone moves the number and plan with it. Many current phones also or only support an eSIM, a built-in chip provisioned electronically by the carrier, which is why some models have no tray. Photos and the operating system live in the phone's own flash storage, and the antennas are internal to the chassis.", "distractor_analysis": {"1": "Photos are stored in the phone's internal storage or the cloud.", "2": "The operating system is on internal flash, not a removable card.", "3": "Antennas are built into the frame or display assembly."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "sim", "cellular"]}, {"id": "C1N-M-101", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A traveller wants to use a local carrier's data plan abroad without removing the home SIM. The phone supports eSIM. What should the technician recommend?", "options": ["Add the local carrier's eSIM profile alongside the physical SIM and select it for data", "Cut the home SIM down to fit a second tray", "Enable Bluetooth tethering to a local phone", "Use airplane mode for the whole trip"], "answer": 0, "explanation": "An eSIM is a programmable chip in the phone that stores one or more carrier profiles. A traveller can buy a local or travel data plan online, scan a QR code to add the profile, and set that line for data while keeping the home number active for calls and texts. This avoids roaming charges and the risk of losing a tiny plastic card. Cutting SIMs risks damage, tethering depends on someone else's phone, and airplane mode disconnects everything.", "distractor_analysis": {"1": "Cutting a SIM can destroy it and most phones have one tray.", "2": "Tethering to another person's phone is not a plan of one's own.", "3": "Airplane mode removes connectivity rather than adding a plan."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "esim", "roaming", "travel"]}, {"id": "C1N-M-102", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone shows full cellular bars but calls fail and data is very slow in a packed stadium. What is the most likely cause?", "options": ["The local cell is congested by the number of users, so capacity rather than signal is the limit", "The SIM has expired", "The phone's antenna is damaged", "Airplane mode is on"], "answer": 0, "explanation": "Signal bars measure how strongly the phone hears the tower, not how much capacity the tower has left. In a crowd tens of thousands of phones share one cell, and the radio channels and backhaul saturate, so calls fail to set up and data crawls despite excellent signal. Carriers add temporary cells at big events for this reason. An expired SIM shows no service everywhere, a damaged antenna shows weak bars, and airplane mode shows no bars at all.", "distractor_analysis": {"1": "An expired SIM fails everywhere, not only in the stadium.", "2": "Antenna damage reduces signal strength rather than leaving full bars.", "3": "Airplane mode removes the signal indicator entirely."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "congestion", "troubleshooting"]}, {"id": "C1N-M-103", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user in a building with poor cellular coverage still receives calls on the phone over the office Wi-Fi. Which feature is in use?", "options": ["Wi-Fi calling", "Bluetooth calling", "NFC calling", "Satellite calling"], "answer": 0, "explanation": "Wi-Fi calling routes voice calls and texts over any internet connection to the carrier's core network, so the phone behaves as though it has cellular coverage even in a basement or a rural house. It must be enabled in the phone settings and supported by the carrier, and an emergency address is registered so emergency services can locate the caller. Bluetooth carries audio to a headset but not calls to the network, NFC is for taps, and satellite messaging on some phones is emergency text only.", "distractor_analysis": {"1": "Bluetooth links the phone to accessories, not to the carrier.", "2": "NFC cannot carry a voice call.", "3": "Satellite features are for emergency messaging, not everyday calls."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wi-fi-calling", "cellular"]}, {"id": "C1N-M-104", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone's battery drains far faster than usual after the user moved to an office at the edge of cellular coverage. Which explanation is most likely?", "options": ["The cellular radio is transmitting at maximum power to hold a weak signal", "The phone's storage is nearly full", "The screen protector is too thick", "The user's contacts list is too long"], "answer": 0, "explanation": "A phone continuously adjusts its transmit power to reach the tower. At the edge of coverage it runs the radio near full power and repeatedly searches for a better cell, and that is one of the biggest battery drains on any handset. Enabling Wi-Fi calling, so the phone can prefer the office Wi-Fi for voice and data, usually restores normal battery life. Storage, protectors and contacts have no effect on power consumption.", "distractor_analysis": {"1": "Full storage slows the phone but does not drain the battery.", "2": "A protector is passive glass or film.", "3": "Contact list size is trivial data with no power cost."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "battery", "signal"]}, {"id": "C1N-M-105", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A company wants to allow only approved apps on its warehouse scanners and prevent staff from opening anything else. Which MDM feature provides this?", "options": ["Kiosk or single-app mode with an allow list of applications", "Remote wipe", "Wi-Fi calling", "Cloud photo backup"], "answer": 0, "explanation": "Dedicated-device or kiosk mode locks a handset to one app or a small allow list, hides the home screen and settings, and can prevent the device leaving the app even after a reboot. It is the standard configuration for scanners, point-of-sale tablets and public displays. Remote wipe is for lost devices, Wi-Fi calling is a voice feature, and photo backup is a consumer service; none of them restricts which apps run.", "distractor_analysis": {"1": "Remote wipe erases a device and does not control app use.", "2": "Wi-Fi calling is about voice over wireless networks.", "3": "Photo backup does not restrict applications."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "kiosk-mode", "allow-list"]}, {"id": "C1N-M-106", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "hard", "question": "After enrolling in MDM, a user's phone shows a corporate Wi-Fi network as connected but a corporate intranet site is unreachable while public sites load. Which is the most likely cause?", "options": ["The VPN profile pushed by the MDM has not connected or was not included, so internal resources are unreachable", "The phone's SIM card is missing", "The screen brightness is too low", "The phone's storage is full"], "answer": 0, "explanation": "Internal sites normally sit behind the corporate firewall and require a VPN or a per-app VPN tunnel that the MDM configures. If the VPN profile is missing, the certificate has not arrived, or the user has not authenticated to it, public internet works but intranet names fail. Checking the VPN status in settings and confirming the profile installed is the fix. SIM, brightness and storage have no bearing on reaching internal sites.", "distractor_analysis": {"1": "The phone is on Wi-Fi; cellular identity is irrelevant.", "2": "Brightness is a display setting.", "3": "Full storage does not block network destinations."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "vpn", "troubleshooting"]}, {"id": "C1N-M-107", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user's phone contacts are duplicated after adding a second account. What is the recommended first step?", "options": ["Check which accounts are set to sync contacts and disable contact sync on the redundant account", "Factory reset the phone", "Remove the SIM card", "Turn off Wi-Fi"], "answer": 0, "explanation": "Each account on a phone can sync its own contacts, calendar and mail. When two accounts hold copies of the same people, the phone shows both sets. Turning off contact sync for one account, or using the contacts app's merge duplicates feature, cleans the list without losing data. A factory reset is far out of proportion, the SIM rarely stores contacts on modern phones, and Wi-Fi has nothing to do with which accounts sync.", "distractor_analysis": {"1": "A reset wipes the device for a settings problem.", "2": "Modern contacts live in accounts, not on the SIM.", "3": "Wi-Fi state does not change account sync settings."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronisation", "contacts", "accounts"]}, {"id": "C1N-M-108", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Before sending a phone for a screen repair, what should a technician ask the user to do to protect their data?", "options": ["Confirm a current cloud or computer backup exists, then sign out of accounts or enable a passcode as policy requires", "Remove the screen protector", "Turn off Bluetooth", "Delete all photos to save space"], "answer": 0, "explanation": "A repair can end in a replaced or wiped device, so the essential protection is a verified backup taken to the cloud or a computer immediately beforehand. Many repair shops also require the activation lock to be disabled, which means signing out of the platform account, and corporate policy may instead require the passcode to stay on. Protectors and Bluetooth are irrelevant, and deleting photos destroys exactly what the backup is meant to preserve.", "distractor_analysis": {"1": "The protector has no bearing on data safety.", "2": "Bluetooth state does not protect data.", "3": "Deleting photos is data loss, not protection."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "backup", "repair", "data-protection"]}, {"id": "C1N-M-109", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user complains that a phone connects to a public Wi-Fi hotspot at a cafe automatically every visit, which the company security team has told staff to avoid. What setting resolves this?", "options": ["Forget the network or disable auto-join for that network", "Enable airplane mode permanently", "Remove the SIM card", "Increase the screen timeout"], "answer": 0, "explanation": "Phones remember networks they have joined and rejoin them automatically. Forgetting the network removes the saved profile, and most phones also offer a per-network auto-join toggle so the network can be used deliberately but not automatically. MDM can go further and block unmanaged networks. Airplane mode would remove all connectivity, the SIM is unrelated to Wi-Fi, and screen timeout is a display setting.", "distractor_analysis": {"1": "Airplane mode disables cellular too, which is not wanted.", "2": "Wi-Fi does not depend on the SIM.", "3": "Screen timeout affects the display only."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wi-fi", "auto-join", "security"]}, {"id": "C1N-M-110", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "hard", "question": "A corporate phone's email stopped syncing after the user changed their domain password on a laptop. Other apps work. What is the most likely fix?", "options": ["Update the stored password for the mail account on the phone", "Replace the SIM", "Reset network settings", "Turn off location services"], "answer": 0, "explanation": "Mail clients store the account credential and present it on every sync. When the password changes elsewhere, the phone keeps offering the old one, the server rejects it and sync stops, sometimes silently or with a re-enter password prompt. Entering the new password in the account settings restores sync; repeated failures can also lock the account, so acting quickly matters. Network reset, SIM and location services are unrelated to a credential mismatch.", "distractor_analysis": {"1": "The SIM has nothing to do with email authentication.", "2": "Network settings are fine because other apps work.", "3": "Location services do not affect mail sync."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "email", "password", "troubleshooting"]}, {"id": "C1N-M-111", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user has Bluetooth enabled and a Wi-Fi hotspot running on the phone at the same time and notices the hotspot is slow. Both radios share the same band. Which band is that?", "options": ["2.4 GHz", "5 GHz", "6 GHz", "900 MHz"], "answer": 0, "explanation": "Bluetooth operates in the 2.4 GHz band, the same band used by 2.4 GHz Wi-Fi, so a phone acting as a hotspot on 2.4 GHz while streaming to Bluetooth earbuds is competing with itself, and microwave ovens and neighbours' networks add more interference. Switching the hotspot to 5 GHz, where the phone supports it, moves the Wi-Fi traffic out of the crowded band. 6 GHz is Wi-Fi 6E and 7 only, and 900 MHz is used by cellular and some IoT radios, not Bluetooth.", "distractor_analysis": {"1": "Bluetooth does not use 5 GHz.", "2": "6 GHz is reserved for newer Wi-Fi standards.", "3": "900 MHz is a cellular and IoT band, not Bluetooth."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "bluetooth", "wi-fi", "2.4ghz", "interference"]}, {"id": "C1N-M-112", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A phone is enrolled in MDM and the administrator has enforced a six-digit passcode and encryption. The user asks why encryption matters if there is already a passcode. What is the accurate answer?", "options": ["Encryption protects the stored data if the storage is read directly, while the passcode only guards the normal user interface", "Encryption makes the phone charge faster", "Encryption is required for Bluetooth to work", "Encryption removes the need for backups"], "answer": 0, "explanation": "A passcode stops someone using the phone through its screen, but without encryption the flash storage could be read with forensic tools. Device encryption scrambles the storage with a key derived in part from the passcode and stored in secure hardware, so the data is unreadable without both. Modern phones encrypt by default, and MDM enforces it so the setting cannot be turned off. Encryption has no effect on charging or Bluetooth and does not replace backups.", "distractor_analysis": {"1": "Encryption is a security control with no effect on charging.", "2": "Bluetooth operates independently of storage encryption.", "3": "Encrypted data can still be lost; backups remain essential."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "encryption", "passcode"]}, {"id": "C1N-M-113", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A small business owner asks whether staff phones need MDM if they only use web email. Which benefit of MDM is still relevant?", "options": ["Enforcing screen lock and encryption and being able to wipe a lost phone that holds cached company data", "Making the phones charge faster", "Providing GPS satellites", "Increasing cellular signal strength"], "answer": 0, "explanation": "Even a browser caches credentials, cookies and downloaded attachments, and staff inevitably store contacts and messages. MDM ensures every phone has a lock screen and encryption and gives the business a way to wipe a device that goes missing, which is the minimum most data protection rules expect. The other options are not things any management platform can do; charging, satellites and radio signal are physical matters.", "distractor_analysis": {"1": "Charging speed is hardware and charger dependent.", "2": "GPS satellites are operated by governments, not MDM vendors.", "3": "Signal strength depends on the carrier network."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "security", "small-business"]}, {"id": "C1N-M-114", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user's phone shows a Wi-Fi symbol with an exclamation mark and apps report no connection, but the laptop on the same network is fine. Which step is most likely to resolve it?", "options": ["Forget and rejoin the Wi-Fi network, or toggle Wi-Fi off and on, to obtain a fresh network address", "Replace the phone's battery", "Remove the screen protector", "Change the ringtone"], "answer": 0, "explanation": "The exclamation indicator means the phone is associated but has no working route to the internet, commonly because its DHCP lease failed or a stale address is in use. Rejoining the network forces a new address and DNS settings from the router. If every device were affected the router would be the suspect, but a working laptop points at the phone's own connection state. Battery, protector and ringtone have nothing to do with networking.", "distractor_analysis": {"1": "Battery condition does not affect IP addressing.", "2": "A protector is passive.", "3": "Ringtones are unrelated to connectivity."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "wi-fi", "dhcp", "troubleshooting"]}, {"id": "C1N-M-115", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A technician is asked to explain the difference between synchronising a phone to the cloud and backing it up. Which statement is accurate?", "options": ["Sync keeps live data such as contacts identical across devices, while a backup is a point-in-time copy used to restore a device", "Sync and backup are the same operation", "Backups only include photos", "Sync only works over a cable"], "answer": 0, "explanation": "Synchronisation continuously mirrors changing data, so deleting a contact on one device deletes it everywhere, which means sync alone cannot recover from a mistake. A backup captures the whole device at a moment, including app data and settings, and is what a replacement phone is restored from. Both are needed. Backups include far more than photos, and both sync and backup normally run over Wi-Fi.", "distractor_analysis": {"1": "They serve different purposes and behave differently on deletion.", "2": "Backups cover settings, app data, messages and more.", "3": "Sync is wireless by default."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "synchronisation", "backup"]}, {"id": "C1N-M-116", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "multi", "difficulty": "medium", "question": "A company is deciding between issuing corporate phones and allowing personal phones for work. Which TWO statements about MDM are accurate? (Select TWO.)", "options": ["Corporate-owned devices can be fully managed, including complete wipe and strict restrictions", "Personal devices are typically managed with a work profile or managed apps so only corporate data is controlled", "MDM can only manage devices from one manufacturer", "MDM requires every phone to be connected by USB to the administrator's computer", "MDM cannot enforce a passcode"], "answers": [0, 1], "explanation": "Ownership determines the management model. A company-owned device can be supervised or fully managed, with every setting under administrative control and a full wipe available. A personal device is enrolled with a work profile or managed apps so the company controls only its own data and can remove just that. MDM platforms manage iOS, Android and often Windows and macOS together, they work entirely over the network, and enforcing passcodes is one of their basic functions.", "distractor_analysis": {"2": "Major MDM platforms manage several vendors' devices.", "3": "Enrolment and policy are delivered over the air.", "4": "Passcode enforcement is a core MDM capability."}, "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "byod", "corporate-owned"]}, {"id": "C1N-M-117", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "multi", "difficulty": "medium", "question": "A user is about to travel internationally with a corporate phone. Which TWO actions should the technician recommend before departure? (Select TWO.)", "options": ["Confirm the plan includes roaming or add a travel plan or local eSIM", "Verify that a current backup has completed", "Remove the passcode so border staff can use the phone", "Disable encryption to improve battery life abroad", "Delete the MDM enrolment to avoid foreign network conflicts"], "answers": [0, 1], "explanation": "Travel preparation is about cost and recovery. Sorting out roaming or a local data plan avoids bill shock, and a fresh backup means a lost or damaged phone can be replaced abroad with minimal disruption. Security controls stay in place: the passcode and encryption protect the device if it is lost, and MDM enrolment is what allows the company to locate and wipe it, so none of those should be removed.", "distractor_analysis": {"2": "Removing the passcode leaves company data exposed if the phone is lost.", "3": "Encryption has no meaningful battery cost and protects the data.", "4": "Enrolment is what enables remote help and wipe while travelling."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "roaming", "backup", "travel"]}, {"id": "C1N-M-118", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "match", "difficulty": "medium", "question": "Match each mobile network or management term to its description.", "pairs": [{"left": "Hotspot", "right": "Shares the phone's cellular data as a Wi-Fi network"}, {"left": "Airplane mode", "right": "Turns off all wireless radios with one switch"}, {"left": "eSIM", "right": "Carrier profile stored on a chip inside the phone"}, {"left": "MDM", "right": "Central platform that enforces policy on enrolled devices"}, {"left": "Wi-Fi calling", "right": "Routes voice calls through an internet connection"}], "explanation": "These terms come up constantly in mobile support. A hotspot shares connectivity outward, airplane mode is the master radio switch, an eSIM replaces the plastic card with a programmable profile, MDM is how organisations control fleets of phones, and Wi-Fi calling rescues voice service where the cellular signal is poor. Being able to name the right feature for a user's situation is most of the job.", "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "connectivity", "mdm", "match"]}, {"id": "C1N-M-119", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "order", "difficulty": "medium", "question": "Order the steps an administrator should take when an enrolled corporate phone is reported lost.", "sequence": ["Confirm the report and identify the device record in the management console", "Use remote locate to see the last known position and try to contact the finder if appropriate", "Lock the device remotely with a message and contact number displayed on the screen", "If the device is not recovered within the agreed time, issue a remote wipe", "Record the incident, retire the device record and provision a replacement from backup"], "explanation": "The order protects data without destroying recovery chances. Verifying the report avoids wiping a phone that is in a desk drawer. Locating and locking come before wiping because a locked, encrypted phone is already safe from casual access and may still be returned. A wipe is the final step because it is irreversible. Closing the record and restoring the user from backup completes the process and keeps the asset register accurate.", "video_reference": {"title": "Mobile Device Management - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=NhGi9M4JP7g", "duration": "8:31", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "mdm", "lost-device", "procedure"]}, {"id": "C1N-M-120", "exam": "core1", "domain": "1.0 Mobile Devices", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user says the phone's mobile data works but only very slowly on the last day of every month, then recovers. What is the most likely explanation?", "options": ["The plan's high-speed data allowance is used up and the carrier throttles speed until the cycle resets", "The SIM card wears out toward the end of the month", "The phone's battery is weaker at month end", "Cellular towers shut down for maintenance monthly"], "answer": 0, "explanation": "Most plans include a monthly allowance of full-speed data. Once it is consumed the carrier reduces the connection to a low speed rather than cutting it off, and the pattern of slowness that resets on the billing date is the tell-tale sign. The fix is a larger plan, using Wi-Fi more, or checking which apps consume the most data in the phone's usage screen. SIMs do not wear, battery state does not throttle data, and towers do not have a monthly outage.", "distractor_analysis": {"1": "A SIM is a passive chip with no monthly cycle.", "2": "Battery level does not affect data speed.", "3": "Carriers do not take networks down on a monthly schedule."}, "video_reference": {"title": "Mobile Device Networks - CompTIA A+ 220-1201 - 1.3", "url": "https://www.youtube.com/watch?v=1LADZLBV3vo", "duration": "10:14", "objective": "1.3"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["mobile", "cellular", "data-plan", "throttling"]}, {"id": "C1N-N-001", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "easy", "question": "A small office wants every workstation to receive an IP address, subnet mask, default gateway and DNS servers automatically when it boots. Which network service provides this?", "options": ["DHCP", "DNS", "SMTP", "SNMP"], "answer": 0, "explanation": "Dynamic Host Configuration Protocol hands out IP configuration from a pool when a client broadcasts a request, saving manual configuration and preventing duplicate addresses. The lease includes the address, mask, gateway, DNS servers and often the domain name, and expires after a set time unless renewed. DNS translates names to addresses but does not assign them, SMTP carries email, and SNMP is used to monitor network devices.", "distractor_analysis": {"1": "DNS resolves names; it does not hand out addresses.", "2": "SMTP is the mail transfer protocol.", "3": "SNMP collects statistics and alerts from network equipment."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "dhcp", "network-services"]}, {"id": "C1N-N-002", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "Users can reach websites by IP address but not by name after a server room change. Which network service is most likely down?", "options": ["DNS", "DHCP", "File server", "Print server"], "answer": 0, "explanation": "Reaching a destination by address proves that IP routing, the gateway and the client's own configuration are working. What is failing is the translation of names into addresses, which is the job of the Domain Name System. Checking that the DNS server the clients are configured to use is online and reachable, or that its forwarders still work, is the fix. DHCP would produce address problems, and file and print services are unrelated to web name resolution.", "distractor_analysis": {"1": "A DHCP failure would leave clients without addresses, so even IP browsing would fail.", "2": "File sharing does not affect name lookups for websites.", "3": "Printing is a separate service."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "dns", "troubleshooting", "network-services"]}, {"id": "C1N-N-003", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A company wants a single server to store documents that staff open from mapped drives on their Windows PCs. Which type of server and protocol fit this need?", "options": ["A file server sharing folders over SMB", "A web server using HTTP", "A mail server using IMAP", "A DHCP server using UDP 67"], "answer": 0, "explanation": "A file server centralises documents so they can be backed up, permissioned and shared. Windows clients access shared folders over Server Message Block, which is what a mapped drive letter uses underneath, and access is controlled by share and NTFS permissions. Web servers serve pages to browsers, mail servers hold mailboxes, and DHCP assigns addresses; none of them provide the drive-letter file access the requirement describes.", "distractor_analysis": {"1": "HTTP serves web content, not mapped drives.", "2": "IMAP is for reading email.", "3": "DHCP assigns IP configuration and stores no documents."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "file-server", "smb", "network-services"]}, {"id": "C1N-N-004", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A network administrator wants to be alerted when a switch's uplink goes down and to graph the bandwidth on each port over time. Which service should be deployed?", "options": ["A monitoring system using SNMP to poll and receive traps from the switch", "A DHCP server", "A print server", "A proxy server"], "answer": 0, "explanation": "Simple Network Management Protocol lets a monitoring server read counters such as port traffic and status from devices, and lets devices send unsolicited trap messages when something changes, such as a link failure. Version 3 adds authentication and encryption and should be used over the older community-string versions. Address assignment, printing and web proxying are entirely different services that provide no device telemetry.", "distractor_analysis": {"1": "DHCP assigns addresses and has no monitoring role.", "2": "Print servers queue print jobs.", "3": "A proxy relays and filters web traffic."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "snmp", "monitoring", "network-services"]}, {"id": "C1N-N-005", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A school wants to block access to certain website categories and cache frequently visited pages to save bandwidth. Which server performs both functions?", "options": ["A proxy server", "A DNS server", "A syslog server", "An authentication server"], "answer": 0, "explanation": "A proxy sits between clients and the internet, making web requests on their behalf. Because every request passes through it, the proxy can enforce content filtering policies, log activity and keep a cache of pages so repeated requests are served locally. Clients are pointed at it through browser settings, group policy or a transparent redirect at the gateway. DNS resolves names, syslog collects log messages and an authentication server verifies identities.", "distractor_analysis": {"1": "DNS can be used for some filtering but does not cache web pages.", "2": "Syslog stores log entries from devices.", "3": "Authentication servers check credentials, not web content."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "proxy", "content-filtering", "network-services"]}, {"id": "C1N-N-006", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "Every network device and server in a data centre must send its event messages to one central location for review and retention. Which service collects them?", "options": ["A syslog server", "A DHCP relay", "A web server", "A file server"], "answer": 0, "explanation": "Syslog is the standard protocol by which routers, switches, firewalls and Unix-like servers send timestamped event messages to a central collector, typically over UDP 514 or TLS on 6514. Centralising logs makes correlation, alerting and retention for compliance possible and preserves evidence if a device is compromised or fails. The collector is often part of a security information and event management platform. The other services do not receive device event streams.", "distractor_analysis": {"1": "A DHCP relay forwards address requests across subnets.", "2": "Web servers serve pages and do not aggregate device logs.", "3": "A file server stores documents rather than receiving syslog streams."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "syslog", "logging", "network-services"]}, {"id": "C1N-N-007", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A company wants users to log in once with a single username and password that is checked by a central server for every workstation and application. Which service provides this?", "options": ["An authentication, authorisation and accounting (AAA) server such as a domain controller or RADIUS server", "A DHCP server", "A print server", "A web cache"], "answer": 0, "explanation": "Central authentication stores identities in one directory and verifies credentials for every login. In Windows networks this is Active Directory on domain controllers; for network equipment and Wi-Fi it is often a RADIUS server that itself queries the directory. Authorisation decides what the verified user may do and accounting records what they did. Address assignment, printing and caching have no part in identity.", "distractor_analysis": {"1": "DHCP assigns addresses without regard to identity.", "2": "Print servers manage queues.", "3": "A web cache stores pages."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "aaa", "authentication", "network-services"]}, {"id": "C1N-N-008", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A retailer wants a device at the network edge that inspects traffic for known attack patterns and can block malicious connections automatically. Which appliance is described?", "options": ["An intrusion prevention system, usually built into a unified threat management firewall", "A load balancer", "A DHCP server", "A file server"], "answer": 0, "explanation": "An intrusion detection system watches traffic and raises alerts, while an intrusion prevention system sits inline and can drop or reset connections that match attack signatures or behave abnormally. Small and mid-sized organisations usually get this as one function of a unified threat management appliance alongside firewalling, content filtering and antivirus scanning. Load balancers distribute traffic among servers, and the other two are ordinary servers.", "distractor_analysis": {"1": "A load balancer spreads requests across servers for capacity, not security inspection.", "2": "DHCP assigns addresses.", "3": "File servers store documents."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ips", "utm", "security-appliance", "network-services"]}, {"id": "C1N-N-009", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A busy website is hosted on four identical servers. Which device ensures user requests are shared among them and that a failed server stops receiving traffic?", "options": ["A load balancer", "A DHCP server", "A syslog collector", "A print server"], "answer": 0, "explanation": "A load balancer presents one address to the world and distributes incoming connections across a pool of back-end servers using round robin, least connections or similar methods. It performs health checks and removes a failed server from the pool automatically, so users are unaware of the failure. It can also terminate TLS and keep sessions on the same server. Address assignment, log collection and printing are unrelated to distributing web load.", "distractor_analysis": {"1": "DHCP has no role in distributing web traffic.", "2": "Syslog collects logs.", "3": "Print servers manage printers."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "load-balancer", "high-availability", "network-services"]}, {"id": "C1N-N-010", "exam": "core1", "domain": "2.0 Networking", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A factory has sensors and controllers that speak industrial protocols over the network and must never be exposed to the office LAN or the internet. Which term describes these devices and how should they be handled?", "options": ["Supervisory control and data acquisition or operational technology devices, isolated on their own segment behind strict firewall rules", "Print servers, placed on the guest Wi-Fi", "Load balancers, exposed publicly", "DHCP relays, left on the office LAN"], "answer": 0, "explanation": "SCADA and other industrial control systems run legacy protocols with little built-in security and often cannot be patched, so they are among the most sensitive devices an organisation owns. Best practice places them on a dedicated network segment with a firewall permitting only the specific management traffic required, and monitors that segment closely. Treating them like ordinary office devices, or exposing them publicly, is how factories end up in security incidents.", "distractor_analysis": {"1": "They are not print servers, and guest Wi-Fi is the least trusted network.", "2": "Control systems must never be publicly exposed.", "3": "Sharing the office LAN gives every workstation a path to the controllers."}, "video_reference": {"title": "Network Services - CompTIA A+ 220-1201 - 2.3", "url": "https://www.youtube.com/watch?v=Z-9mkqi2ELI", "duration": "17:03", "objective": "2.3"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "scada", "operational-technology", "segmentation", "network-services"]}, {"id": "C1N-N-011", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "A home user in a rural area with no cable or fibre service and a poor mobile signal wants broadband internet. Which connection type is the most likely option?", "options": ["Satellite internet", "Fibre to the premises", "Cable broadband", "A leased line"], "answer": 0, "explanation": "Satellite service needs only a clear view of the sky, so it reaches places that no cable, fibre or strong cellular signal covers. Traditional geostationary satellites impose high latency of around 600 milliseconds, which hurts video calls and gaming, while newer low-earth-orbit constellations reduce that to tens of milliseconds. Weather can degrade the link. Fibre and cable require physical infrastructure in the street, and a leased line is an expensive business circuit.", "distractor_analysis": {"1": "Fibre requires a provider to have run cable to the property.", "2": "Cable broadband depends on the cable television network reaching the area.", "3": "Leased lines are costly dedicated business circuits."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "satellite", "internet-connection", "rural"]}, {"id": "C1N-N-012", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "A user's internet speed test shows fast downloads but very slow uploads, and the connection uses the existing telephone line. Which connection type is this and why is upload slower?", "options": ["DSL, which is asymmetric by design and allocates more frequency bandwidth to downstream", "Fibre, because light travels one way", "Satellite, because of weather", "Ethernet, because of cable length"], "answer": 0, "explanation": "Digital subscriber line service runs over copper telephone wiring and most residential variants are asymmetric, giving download far more capacity than upload because that matches typical consumer traffic. Speed also falls with distance from the exchange or street cabinet. Fibre is inherently symmetric-capable, satellite slowness is latency and weather rather than asymmetry over a phone line, and Ethernet is a local network technology, not an internet service.", "distractor_analysis": {"1": "Fibre carries light in both directions and is often symmetric.", "2": "Satellite does not use a telephone line.", "3": "Ethernet is the LAN cabling standard, not the internet connection type."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "dsl", "asymmetric", "internet-connection"]}, {"id": "C1N-N-013", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "A company opens a temporary site for three months and needs internet on day one without waiting for a wired installation. Which option best fits?", "options": ["A cellular router using 4G or 5G with a business data plan", "Fibre to the premises", "A satellite dish installed on the roof with a two-year contract", "A dial-up modem"], "answer": 0, "explanation": "Cellular wide area network routers turn a mobile data connection into a wired and wireless LAN for a site, can be running the day the equipment arrives and are easily returned when the site closes. Providers offer business plans with fixed pricing and external antennas improve signal. Fibre installation takes weeks and a long contract, satellite contracts are also lengthy, and dial-up cannot support a modern office.", "distractor_analysis": {"1": "Fibre requires a survey, installation and a long commitment.", "2": "A two-year satellite contract does not suit a three-month site.", "3": "Dial-up speeds are unusable for business applications."}, "video_reference": {"title": "Internet Connection Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=iN2QnGFl06E", "duration": "7:33", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "cellular", "wwan", "internet-connection"]}, {"id": "C1N-N-014", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "Which term describes the network within a single office building where all devices connect to the same switches?", "options": ["Local area network (LAN)", "Wide area network (WAN)", "Personal area network (PAN)", "Metropolitan area network (MAN)"], "answer": 0, "explanation": "A LAN covers a limited area such as a building or campus, is owned by the organisation and uses Ethernet and Wi-Fi at high speed and low latency. A WAN connects sites across cities or countries using carrier links, a MAN spans a city, and a PAN is the few-metre bubble around one person, typically Bluetooth. Knowing the scope helps a technician decide whether a problem is local or belongs to a service provider.", "distractor_analysis": {"1": "A WAN connects geographically separate sites.", "2": "A PAN is a personal, short-range network such as Bluetooth.", "3": "A MAN spans a metropolitan area."}, "video_reference": {"title": "Network Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=PBEXIMeqRNY", "duration": "4:46", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "lan", "network-types"]}, {"id": "C1N-N-015", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "A company connects its head office in one city to a branch in another using a service from a telecoms provider. Which network type is formed?", "options": ["A wide area network (WAN)", "A local area network (LAN)", "A personal area network (PAN)", "A storage area network (SAN)"], "answer": 0, "explanation": "Any network that links sites across distances beyond a single campus is a WAN, and it almost always runs over circuits or VPN tunnels provided by a carrier because the organisation cannot run its own cable between cities. WAN links are slower and higher latency than LAN links and are a common bottleneck. A LAN is confined to one site, a PAN is personal short-range, and a SAN is a dedicated storage network inside a data centre.", "distractor_analysis": {"1": "A LAN cannot span cities.", "2": "A PAN is a personal Bluetooth-scale network.", "3": "A SAN carries block storage traffic within a data centre."}, "video_reference": {"title": "Network Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=PBEXIMeqRNY", "duration": "4:46", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "wan", "network-types"]}, {"id": "C1N-N-016", "exam": "core1", "domain": "2.0 Networking", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "A data centre team refers to the dedicated high-speed network that connects servers to shared disk arrays. Which network type is this?", "options": ["A storage area network (SAN)", "A wireless local area network (WLAN)", "A personal area network (PAN)", "A metropolitan area network (MAN)"], "answer": 0, "explanation": "A SAN provides block-level storage to servers over a dedicated fabric, traditionally Fibre Channel and increasingly iSCSI or NVMe over Ethernet. Servers see SAN volumes as local disks, which is what allows virtual machines to move between hosts and clusters to share data. It is kept separate from the general LAN for performance and reliability. WLANs are Wi-Fi, PANs are personal short-range, and MANs are city-scale networks.", "distractor_analysis": {"1": "Wi-Fi is far too slow and unreliable for shared storage.", "2": "A PAN is a personal device network.", "3": "A MAN links sites across a city."}, "video_reference": {"title": "Network Types - CompTIA A+ 220-1201 - 2.7", "url": "https://www.youtube.com/watch?v=PBEXIMeqRNY", "duration": "4:46", "objective": "2.7"}, "notes_reference": "11_Internet_Connections_TCPIP_Addressing.md", "tags": ["networking", "san", "storage", "network-types"]}, {"id": "C1N-N-017", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "An administrator wants two groups of devices plugged into the same physical switch to be on separate networks that cannot talk to each other without passing through a router. Which feature should be configured?", "options": ["VLANs, assigning the ports of each group to a different VLAN", "A second DHCP scope on the same subnet", "Port mirroring", "Link aggregation"], "answer": 0, "explanation": "Virtual LANs split one physical switch into several logical broadcast domains. Ports assigned to VLAN 10 cannot reach ports in VLAN 20 at layer 2; traffic between them must go through a router or a layer 3 switch where access rules can be applied. VLANs are the standard way to separate staff, guests, voice and management traffic without buying separate switches. Mirroring copies traffic for analysis and aggregation bundles links for bandwidth.", "distractor_analysis": {"1": "Two scopes on one subnet do not separate devices.", "2": "Port mirroring duplicates traffic to a monitoring port.", "3": "Link aggregation combines ports for throughput and redundancy."}, "video_reference": {"title": "VLANs and VPNs - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=Z1wPgxsx4GI", "duration": "7:32", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "vlan", "segmentation"]}, {"id": "C1N-N-018", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A remote employee needs to reach internal file servers from home as though they were in the office, with the traffic encrypted across the internet. Which technology provides this?", "options": ["A VPN", "A VLAN", "A DHCP reservation", "A DNS forwarder"], "answer": 0, "explanation": "A virtual private network creates an encrypted tunnel between the remote device and a gateway at the office, giving the client an internal address and routing its traffic into the corporate network. Protocols include IPsec, SSL/TLS-based VPNs and WireGuard. Split tunnelling decides whether all traffic or only corporate traffic uses the tunnel. VLANs segment a local switch, DHCP reservations fix an address to a device, and DNS forwarders pass queries to another resolver.", "distractor_analysis": {"1": "A VLAN is a local segmentation feature and provides no remote access.", "2": "A DHCP reservation only pins an address.", "3": "A forwarder is a DNS configuration."}, "video_reference": {"title": "VLANs and VPNs - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=Z1wPgxsx4GI", "duration": "7:32", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "vpn", "remote-access"]}, {"id": "C1N-N-019", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A network printer must always have the same IP address, but the administrator wants it to remain a DHCP client so the settings are managed centrally. Which DHCP feature is used?", "options": ["A reservation that binds the printer's MAC address to a fixed IP address", "A shorter lease time", "An exclusion range", "A relay agent"], "answer": 0, "explanation": "A DHCP reservation tells the server to always give a specific address to a specific hardware address, so the printer keeps a predictable address without anyone typing static settings on the device, and any change to gateway or DNS still flows from the server. Shorter leases make addresses change more often, exclusions remove addresses from the pool for statically configured devices, and a relay forwards requests between subnets.", "distractor_analysis": {"1": "Shorter leases increase the chance of the address changing.", "2": "Exclusions prevent the server assigning those addresses at all.", "3": "A relay agent passes DHCP traffic across routers."}, "video_reference": {"title": "DHCP - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=HwUqCZFx6wk", "duration": "10:45", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dhcp", "reservation"]}, {"id": "C1N-N-020", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A company's email is being rejected by recipients as suspected spam. The administrator is told to publish records that identify which servers are allowed to send mail for the domain. Which DNS record type is needed?", "options": ["A TXT record containing an SPF policy, and ideally DKIM and DMARC records", "An A record", "A PTR record for the web server", "A CNAME record"], "answer": 0, "explanation": "Sender Policy Framework is published as a TXT record listing the hosts authorised to send email for the domain. Receiving servers check the sending address against it and treat mismatches as spam or forgery. DKIM adds a cryptographic signature published in DNS, and DMARC tells receivers how to handle failures and where to send reports. A records map names to addresses, PTR records give reverse lookups, and CNAME records create aliases.", "distractor_analysis": {"1": "A records resolve a hostname to an IPv4 address.", "2": "PTR records provide reverse lookup, and a web server's PTR is irrelevant to mail policy.", "3": "CNAME records alias one name to another."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "spf", "email-security"]}, {"id": "C1N-N-021", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A technician adds a mail server and must tell the internet which host receives email for the company's domain. Which DNS record is created?", "options": ["An MX record pointing to the mail server's hostname", "An AAAA record for the web server", "A TXT record containing the company address", "A CNAME for the intranet"], "answer": 0, "explanation": "Mail exchanger records name the servers that accept email for a domain, each with a priority so that backup servers are used only when the primary fails. The MX record points to a hostname which must itself have an A or AAAA record. Without a correct MX record, mail sent to the domain has nowhere to go. IPv6 address records, arbitrary text and aliases do not direct mail delivery.", "distractor_analysis": {"1": "AAAA records map a name to an IPv6 address.", "2": "TXT records hold policy text such as SPF, not mail routing.", "3": "A CNAME creates an alias and is not used for mail exchange."}, "video_reference": {"title": "DNS Configuration - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=lAHqO9sDVy4", "duration": "18:18", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dns", "mx-record", "email"]}, {"id": "C1N-N-022", "exam": "core1", "domain": "2.0 Networking", "objective": "2.4", "type": "single", "difficulty": "hard", "question": "Devices on a new subnet cannot obtain addresses even though the DHCP server on the main subnet works fine. What is the most likely cause?", "options": ["The router between the subnets is not configured as a DHCP relay, so the clients' broadcasts never reach the server", "The clients need static DNS servers", "The switch ports are the wrong colour", "The DHCP server's lease time is too long"], "answer": 0, "explanation": "DHCP discovery is a broadcast, and routers do not forward broadcasts. A server on another subnet can only serve clients if the router on the clients' subnet is configured as a relay agent, sometimes called an IP helper, that converts the broadcast into a unicast to the server's address. The server must also have a scope for the new subnet. DNS settings, port cosmetics and lease length have nothing to do with the discovery reaching the server.", "distractor_analysis": {"1": "DNS is irrelevant until an address is obtained.", "2": "Cosmetics do not affect traffic.", "3": "Lease time affects renewal timing, not initial discovery."}, "video_reference": {"title": "DHCP - CompTIA A+ 220-1201 - 2.4", "url": "https://www.youtube.com/watch?v=HwUqCZFx6wk", "duration": "10:45", "objective": "2.4"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["networking", "dhcp", "relay", "troubleshooting"]}, {"id": "C1N-N-023", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "An office has heavy Wi-Fi interference on the 2.4 GHz band from neighbouring businesses. Which change gives clients the most relief?", "options": ["Move client devices to the 5 GHz or 6 GHz band, which has many more non-overlapping channels", "Increase the transmit power on 2.4 GHz to overpower the neighbours", "Switch every access point to channel 6", "Disable encryption to reduce overhead"], "answer": 0, "explanation": "The 2.4 GHz band has only three non-overlapping channels and is shared with Bluetooth, microwave ovens and every nearby network, so congestion is inevitable in dense areas. The 5 GHz band offers over twenty channels and 6 GHz, used by Wi-Fi 6E and 7, adds far more with almost no legacy interference. Steering capable clients to those bands is the effective fix. Raising power adds to everyone's interference, stacking access points on one channel causes self-interference, and encryption is essential.", "distractor_analysis": {"1": "Higher power worsens the shared-channel problem for all parties.", "2": "Putting every access point on one channel makes them interfere with each other.", "3": "Encryption overhead is negligible and disabling it is a security failure."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wi-fi", "5ghz", "interference"]}, {"id": "C1N-N-024", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "A user's laptop supports Wi-Fi 6 but connects at Wi-Fi 4 speeds in a meeting room far from the access point. What is the most likely explanation?", "options": ["Distance and obstructions reduce signal quality, so the link negotiates a lower data rate", "Wi-Fi 6 only works within one metre of the access point", "The laptop's Bluetooth is off", "The access point has run out of IP addresses"], "answer": 0, "explanation": "Wireless data rates adapt to signal conditions. As a client moves further away or behind walls, signal-to-noise ratio falls and the radio steps down to slower, more robust modulation, so a Wi-Fi 6 link may run at legacy speeds. The remedies are a closer access point, fewer obstructions or moving to a band with better propagation for that spot. Wi-Fi 6 works at normal ranges, Bluetooth does not govern Wi-Fi speed, and address exhaustion prevents connection rather than slowing it.", "distractor_analysis": {"1": "Wi-Fi 6 has normal indoor range comparable to earlier standards.", "2": "Bluetooth state does not set the Wi-Fi data rate.", "3": "Address exhaustion would stop the client getting online entirely."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wi-fi", "signal", "data-rate"]}, {"id": "C1N-N-025", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which wireless standard introduced the 6 GHz band for Wi-Fi?", "options": ["Wi-Fi 6E (802.11ax extended)", "Wi-Fi 4 (802.11n)", "Wi-Fi 5 (802.11ac)", "802.11g"], "answer": 0, "explanation": "Wi-Fi 6E extended the 802.11ax standard into the 6 GHz band, adding up to 1,200 MHz of new spectrum with wide channels and almost no legacy devices to contend with. Wi-Fi 7 continues to use it. Wi-Fi 4 introduced 2.4 and 5 GHz operation with multiple antennas, Wi-Fi 5 is 5 GHz only, and 802.11g was a 2.4 GHz standard from 2003. Clients and access points both need 6E or later hardware to use the new band.", "distractor_analysis": {"1": "Wi-Fi 4 operates on 2.4 and 5 GHz.", "2": "Wi-Fi 5 is 5 GHz only.", "3": "802.11g is a 2.4 GHz legacy standard."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wi-fi-6e", "6ghz", "standards"]}, {"id": "C1N-N-026", "exam": "core1", "domain": "2.0 Networking", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "A warehouse uses handheld scanners that only support 2.4 GHz. The network team wants to use wide 80 MHz channels for laptops. How should the wireless network be designed?", "options": ["Run the scanners on 2.4 GHz with 20 MHz channels 1, 6 and 11, and put laptops on 5 GHz with wide channels", "Use 80 MHz channels on 2.4 GHz for everything", "Disable 2.4 GHz entirely", "Put everything on channel 1"], "answer": 0, "explanation": "The 2.4 GHz band only has room for three non-overlapping 20 MHz channels, so wide channels there cause overlap and interference and must be avoided. Legacy devices stay on 2.4 GHz with the standard channel plan, while dual-band clients are steered to 5 GHz where 80 MHz channels are practical. Disabling 2.4 GHz would strand the scanners, and putting all access points on one channel creates co-channel interference throughout the warehouse.", "distractor_analysis": {"1": "The 2.4 GHz band cannot accommodate 80 MHz channels without heavy overlap.", "2": "The scanners would lose connectivity.", "3": "One channel everywhere maximises interference between access points."}, "video_reference": {"title": "Wireless Network Technologies - CompTIA A+ 220-1201 - 2.2", "url": "https://www.youtube.com/watch?v=aTuaEk5hnAs", "duration": "7:16", "objective": "2.2"}, "notes_reference": "10_Wireless_Networking.md", "tags": ["networking", "wi-fi", "channels", "design"]}, {"id": "C1N-N-027", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A firewall administrator must allow technicians to manage Linux servers with an encrypted command-line session. Which port should be opened?", "options": ["TCP 22", "TCP 23", "TCP 3389", "UDP 161"], "answer": 0, "explanation": "Secure Shell on TCP 22 provides encrypted terminal access, file transfer with SFTP and SCP, and tunnelling. It replaced Telnet on TCP 23, which sends everything including passwords in clear text and should be blocked. TCP 3389 is Remote Desktop Protocol for Windows graphical sessions, and UDP 161 is SNMP for monitoring. Opening only the ports required, and restricting the source addresses that may use them, is standard firewall practice.", "distractor_analysis": {"1": "Telnet on 23 is unencrypted and obsolete for management.", "2": "RDP on 3389 is for Windows desktops.", "3": "SNMP on 161 is a monitoring protocol."}, "video_reference": {"title": "Common Ports - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=_qGlbfZ44hg", "duration": "12:52", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "ssh", "firewall"]}, {"id": "C1N-N-028", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A Windows technician needs to connect to a remote Windows server's graphical desktop through a firewall. Which port must be permitted?", "options": ["TCP 3389", "TCP 22", "TCP 445", "UDP 53"], "answer": 0, "explanation": "Remote Desktop Protocol listens on TCP 3389 and carries the full Windows desktop, keyboard and mouse. Because it is a frequent target of brute-force attacks, it should never be exposed directly to the internet; access should be through a VPN or a remote desktop gateway with multi-factor authentication. TCP 22 is SSH, TCP 445 is SMB file sharing and UDP 53 is DNS. Knowing these ports lets a technician write firewall rules correctly.", "distractor_analysis": {"1": "SSH on 22 gives a command line, not the Windows desktop.", "2": "SMB on 445 is file and printer sharing.", "3": "DNS on 53 resolves names."}, "video_reference": {"title": "Common Ports - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=_qGlbfZ44hg", "duration": "12:52", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "rdp", "firewall"]}, {"id": "C1N-N-029", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A video conferencing application performs poorly when the network drops a few packets, but a file download on the same link is unaffected. Which transport protocol difference explains this?", "options": ["The video stream uses UDP, which does not retransmit lost packets, while the download uses TCP, which retransmits and delivers everything in order", "The video uses TCP and the download uses UDP", "Both use TCP but video is lower priority", "The video uses ICMP"], "answer": 0, "explanation": "Real-time media favours UDP because waiting for a retransmission would arrive too late to be useful, so lost packets simply cause a glitch. TCP, used for downloads and web pages, acknowledges every segment and resends anything lost, so the file arrives complete even on a lossy link, just more slowly. Understanding this distinction explains why voice and video are sensitive to loss and jitter while bulk transfers are sensitive only to throughput. ICMP is for diagnostics such as ping.", "distractor_analysis": {"1": "This reverses the usual choice of transports.", "2": "Priority would not explain glitches versus a complete file.", "3": "ICMP is a control protocol, not a media transport."}, "video_reference": {"title": "Introduction to IP - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=RRFjKXxYJdM", "duration": "19:04", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "tcp", "udp", "transport"]}, {"id": "C1N-N-030", "exam": "core1", "domain": "2.0 Networking", "objective": "2.1", "type": "match", "difficulty": "medium", "question": "Match each network service to the port it commonly uses.", "pairs": [{"left": "HTTPS", "right": "TCP 443"}, {"left": "DNS", "right": "UDP 53"}, {"left": "DHCP server", "right": "UDP 67"}, {"left": "SMB file sharing", "right": "TCP 445"}, {"left": "IMAP over TLS", "right": "TCP 993"}], "explanation": "Ports are how a technician reads a firewall rule or a port scan. HTTPS on 443 is secure web, DNS queries use UDP 53 with TCP for large responses, DHCP servers listen on UDP 67 while clients use 68, SMB on TCP 445 is Windows file and printer sharing, and IMAP over an encrypted connection uses TCP 993. When a service does not respond, confirming its port is open between client and server is the fastest way to separate a network block from an application fault.", "video_reference": {"title": "Common Ports - CompTIA A+ 220-1201 - 2.1", "url": "https://www.youtube.com/watch?v=_qGlbfZ44hg", "duration": "12:52", "objective": "2.1"}, "notes_reference": "12_Ports_Protocols_Network_Services.md", "tags": ["networking", "ports", "match"]}, {"id": "C1N-T2-001", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A desktop makes a repeated clicking sound from inside the case and Windows freezes for seconds at a time when opening files. Which component is most likely failing and what should be done first?", "options": ["The power supply fan; replace the fan", "The graphics card; update the driver", "The memory; run a memory test", "The mechanical hard drive; back up the data immediately and replace the drive"], "answer": 1, "explanation": "A rhythmic clicking from a spinning hard drive is the read head repeatedly failing to find data and reseeking, and the pauses are the operating system waiting on those retries. It is a drive in the process of dying. Data must be copied off before anything else, because each attempt may be the last, and then the drive replaced and the system restored. Fans whir rather than click, graphics faults show on screen, and memory errors cause crashes rather than file-access pauses.", "distractor_analysis": {"1": "A failing fan grinds or rattles and does not cause file-open stalls.", "2": "Driver problems produce artefacts or crashes, not clicking.", "3": "Memory faults produce blue screens and random errors."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "hard-drive", "clicking"]}, {"id": "C1N-T2-002", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "During boot a PC displays a message that the SMART status of the drive is bad and advises backing up. The system still boots. What does this mean?", "options": ["The drive's self-monitoring has detected error rates that predict failure; back up now and replace the drive", "The drive is simply full", "The drive needs defragmenting", "The message can be ignored because the system booted"], "answer": 0, "explanation": "Self-Monitoring, Analysis and Reporting Technology tracks internal counters such as reallocated sectors, pending sectors and spin retries. When thresholds are crossed the firmware flags a predicted failure and the system firmware displays the warning. The drive may run for hours or months, but it is untrustworthy, so the correct response is immediate backup and replacement. A full or fragmented drive produces no SMART warning, and ignoring the message risks losing everything.", "distractor_analysis": {"1": "Capacity is not monitored by SMART thresholds.", "2": "Fragmentation is a file layout matter, not a health failure.", "3": "Booting once does not mean the drive is safe."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "smart", "predictive-failure"]}, {"id": "C1N-T2-003", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A server with a RAID 5 array shows an amber light on one drive bay and the array status is degraded, but users can still access files. What should the technician do?", "options": ["Replace the failed drive promptly so the array can rebuild, because a second failure before the rebuild finishes would lose all data", "Nothing, because RAID 5 means no data can ever be lost", "Delete the array and recreate it", "Remove a working drive to balance the array"], "answer": 0, "explanation": "RAID 5 survives the loss of exactly one drive by reconstructing data from parity, which is why users notice nothing. In that degraded state there is no redundancy left, and the rebuild that follows a drive swap stresses the remaining drives for hours. Replacing the failed drive quickly, and having a spare on the shelf, minimises the window of risk. RAID is not a backup, recreating the array destroys the data, and pulling another drive would collapse it.", "distractor_analysis": {"1": "A degraded array has zero tolerance for a further failure.", "2": "Recreating the array erases everything on it.", "3": "Removing a second drive fails the array entirely."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "raid", "degraded"]}, {"id": "C1N-T2-004", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A PC reports that no bootable device was found after a technician moved it to a new desk. Before the move it booted normally. What is the most likely cause?", "options": ["A data or power cable to the drive was dislodged during the move", "The operating system licence expired", "The monitor cable is loose", "The keyboard is not detected"], "answer": 0, "explanation": "Physical handling is the most common reason a previously working drive disappears from the firmware's device list. SATA data and power connectors, and M.2 cards that are not screwed down, can work loose when a case is tilted or bumped. Reseating the cables or the drive usually restores the boot. If the drive is firmly connected and still absent, the drive itself or the controller port has failed. Licensing, monitor cabling and keyboards do not cause a missing boot device.", "distractor_analysis": {"1": "Licence status is checked after Windows loads, not by the firmware.", "2": "A loose monitor cable gives no display, not a no-boot-device message.", "3": "A missing keyboard does not remove the boot drive."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "boot", "cables"]}, {"id": "C1N-T2-005", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A user's SSD-based laptop has become slow at writing large files, though reads remain fast. The drive is 96 percent full. What is the most likely explanation?", "options": ["The SSD has little free space, leaving few empty blocks for writes and forcing the controller to erase and rewrite constantly", "The SSD needs defragmenting", "The drive's spindle motor is wearing out", "The SATA cable is too long"], "answer": 0, "explanation": "Solid-state drives write quickly only when they have free, pre-erased blocks available. When the drive is nearly full the controller must find, consolidate and erase partially used blocks before every write, which slows writes dramatically while reads are unaffected. Keeping 10 to 20 percent free and ensuring TRIM is enabled maintains performance. Defragmenting an SSD wears it without benefit, SSDs have no spindle, and internal cabling has no bearing on write speed.", "distractor_analysis": {"1": "Defragmentation is for spinning disks and adds wear to an SSD.", "2": "SSDs have no moving parts.", "3": "Cable length does not degrade write performance in a laptop."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "ssd", "performance"]}, {"id": "C1N-T2-006", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "An external USB drive is not shown in File Explorer but appears in Disk Management as a healthy volume with no drive letter. What is the fix?", "options": ["Assign a drive letter to the volume in Disk Management", "Format the drive", "Replace the USB cable", "Reinstall Windows"], "answer": 0, "explanation": "File Explorer only shows volumes that have a drive letter or mount point. Disk Management proves the drive is detected and its file system is intact, so the only thing missing is the letter, which can be lost when a letter is already taken by a network drive or another device. Assigning one makes the drive appear immediately with its data untouched. Formatting would erase it, the cable is fine because the disk is detected, and reinstalling Windows is unrelated.", "distractor_analysis": {"1": "Formatting destroys the data on a drive that is healthy.", "2": "The disk is detected, so the cable is working.", "3": "The operating system is functioning; only the letter is missing."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "drive-letter", "disk-management"]}, {"id": "C1N-T2-007", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "hard", "question": "A server's RAID controller reports that a rebuild has been running for two days and the array is now extremely slow. What is the most likely reason for the rebuild time?", "options": ["Very large drives take many hours to rebuild, and heavy production I/O during the rebuild slows both the rebuild and user access", "The controller battery is flat", "The array is too small", "The network switch is congested"], "answer": 0, "explanation": "Rebuilding a multi-terabyte drive means reading every other drive in the array and writing the reconstructed data, which can take a day or more even with no other activity. Production reads and writes compete for the same drives, so both slow down and the rebuild stretches further. Administrators often schedule rebuilds for low-activity periods or accept the slowdown to shorten the vulnerable window. Cache battery, array size and network load do not govern rebuild duration.", "distractor_analysis": {"1": "A flat cache battery disables write caching but does not create multi-day rebuilds.", "2": "Small arrays rebuild faster, not slower.", "3": "Rebuilds happen inside the storage subsystem, not across the network."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "raid", "rebuild"]}, {"id": "C1N-T2-008", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A user cannot save files to a network drive and receives a message that the disk is full, but their local drive has plenty of space. What should the technician check?", "options": ["The free space and the user's quota on the file server share", "The local drive's free space", "The user's monitor settings", "The mouse driver"], "answer": 0, "explanation": "A mapped network drive reports the capacity and free space of the volume on the server, or of the user's quota if quotas are enforced, not the local disk. A full server volume or an exhausted quota produces exactly this message. The fix is on the server: free space, expand the volume or raise the quota. The local drive is irrelevant because the save target is remote, and display and input settings have nothing to do with storage.", "distractor_analysis": {"1": "The file is being saved to the server, not the local disk.", "2": "Monitor settings do not affect saving.", "3": "Mouse drivers are unrelated to storage."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "network-drive", "quota"]}, {"id": "C1N-T2-009", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.2", "type": "single", "difficulty": "medium", "question": "A PC intermittently loses its second SATA hard drive, which reappears after a reboot. Event logs show controller reset errors. What is the most likely cause?", "options": ["A faulty or poorly seated SATA cable or connector causing intermittent contact", "The operating system is too old", "The drive letter is wrong", "The screen resolution is too high"], "answer": 0, "explanation": "Controller resets and a drive that comes and goes are the signature of a marginal physical connection: a SATA cable with a loose latch, a bent pin, or a connector damaged by repeated handling. Swapping the cable and using a different port on the board is quick and usually decisive; if the fault follows the drive to a new cable and port, the drive's own connector or electronics are failing. Software age, letter assignment and display settings cannot make a drive vanish from the bus.", "distractor_analysis": {"1": "Operating system version does not cause bus-level disconnects.", "2": "A wrong letter would hide the volume, not reset the controller.", "3": "Display settings are unrelated to storage."}, "video_reference": {"title": "Troubleshooting Storage Devices - CompTIA A+ 220-1201 - 5.2", "url": "https://www.youtube.com/watch?v=aVIuyHCNPCE", "duration": "17:04", "objective": "5.2"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "storage", "sata", "intermittent"]}, {"id": "C1N-T2-010", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A monitor shows an image that is stretched horizontally and text looks blurry, but the display worked properly yesterday. What is the most likely cause?", "options": ["The display resolution has been changed to one that does not match the panel's native resolution", "The monitor's backlight has failed", "The video cable is too short", "The monitor is overheating"], "answer": 0, "explanation": "Flat panels have a fixed grid of pixels and look sharp only at their native resolution. If Windows falls back to a lower or differently proportioned resolution, often after a driver update or an accidental settings change, the panel scales the image and text becomes soft and shapes stretch. Setting the recommended resolution in display settings restores a crisp picture. A failed backlight gives a dark screen, cable length does not distort geometry, and overheating causes shutdowns.", "distractor_analysis": {"1": "A dead backlight produces a dark image, not a stretched one.", "2": "Cable length affects signal integrity, not aspect ratio.", "3": "Thermal problems switch the display off rather than stretching it."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "resolution", "scaling"]}, {"id": "C1N-T2-011", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A projector displays the presenter's laptop but the image has a strong pink tint. The same laptop looks normal on its own screen. What should the technician check first?", "options": ["The video cable and its connector pins, because a damaged or partially seated cable can drop one colour channel", "The laptop's battery", "The projector's lamp hours", "The presenter's slides"], "answer": 0, "explanation": "A colour cast affecting the whole picture over an analogue or damaged digital connection usually means one colour signal is weak or missing, which is a cable or connector fault: a bent pin on a VGA plug or a badly seated HDMI connector. Reseating or replacing the cable is the first step, and trying a different input on the projector isolates the projector's port. Because the laptop's own display is correct, the graphics output itself is fine. Battery, lamp life and content do not tint an image.", "distractor_analysis": {"1": "Battery state does not alter colour output.", "2": "An ageing lamp dims the image; it does not turn it pink.", "3": "The tint affects everything on screen, not just the slides."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "colour", "cable"]}, {"id": "C1N-T2-012", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A gaming PC shows coloured blocks and torn textures on screen during games, and the problem grows worse the longer it plays. What is the most likely cause?", "options": ["The graphics card is overheating or its memory is failing, producing artefacts under load", "The monitor's refresh rate is too low", "The keyboard is faulty", "The hard drive is fragmented"], "answer": 0, "explanation": "Artefacts that appear under graphical load and worsen with time are produced by the graphics processor or its memory operating outside safe limits, most often because its cooler is clogged with dust or the fan has failed, or because the video memory is degrading. Checking GPU temperature with a monitoring tool, cleaning the cooler and testing at stock clocks isolates it. Refresh rate causes flicker or tearing at a steady level, and keyboards and disk layout have nothing to do with rendering.", "distractor_analysis": {"1": "A low refresh rate does not create coloured blocks.", "2": "Keyboards do not affect the image.", "3": "Disk fragmentation slows loading, not rendering."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "artefacts", "gpu", "overheating"]}, {"id": "C1N-T2-013", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "easy", "question": "A desktop PC powers on with fans spinning but the monitor stays black and shows a no-signal message. The monitor works with a laptop. What should be checked first?", "options": ["That the video cable is connected to the correct output, the dedicated graphics card rather than the disabled onboard port", "The monitor's colour calibration", "The PC's hard drive capacity", "The speaker volume"], "answer": 0, "explanation": "When a PC has a dedicated graphics card, the motherboard's onboard video outputs are usually disabled, so a cable plugged into the wrong port gives no signal even though everything is working. Moving the cable to the graphics card's output, and confirming the card is seated and powered, resolves the majority of no-signal calls. The monitor is proven good with the laptop. Calibration, storage and audio are irrelevant to a missing signal.", "distractor_analysis": {"1": "Calibration only matters once an image is present.", "2": "Disk capacity does not affect display output.", "3": "Audio settings are unrelated to video."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "no-signal", "cabling"]}, {"id": "C1N-T2-014", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A conference room display shows a ghost of a previous image that remains faintly visible when the picture changes. What is this and what typically causes it?", "options": ["Image persistence or burn-in caused by a static image being displayed for long periods", "A loose HDMI cable", "The wrong resolution", "A failing power supply"], "answer": 0, "explanation": "Displays that show the same static content for hours, such as a logo, a dashboard or a taskbar, can retain a faint impression of it. On LCDs this is usually temporary image persistence that fades with varied content or a pixel-refresh routine; on OLED and older plasma panels it can become permanent burn-in. Prevention means screen savers, content rotation and lower brightness. Loose cables cause flicker or dropouts, resolution affects sharpness, and power faults switch the display off.", "distractor_analysis": {"1": "A loose cable produces flicker or no signal, not a retained image.", "2": "Wrong resolution blurs the whole image.", "3": "Power supply problems cause shutdowns rather than ghosting."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "burn-in", "image-persistence"]}, {"id": "C1N-T2-015", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A user's second monitor is detected but shows only a black screen with a cursor when the mouse is moved onto it. What is the most likely cause?", "options": ["The display is set to extend and the desktop on that screen is simply empty; nothing is wrong", "The monitor's backlight has failed", "The graphics card has no memory", "The cable is too long"], "answer": 0, "explanation": "In extended desktop mode the second screen shows only the wallpaper and any windows moved onto it, and with a black wallpaper it can look faulty. The cursor appearing proves the monitor, cable, and output are all working. Setting a visible wallpaper or dragging a window across confirms it. If the user wanted the same image on both screens they need duplicate mode instead. Backlight, memory and cable faults would not let the cursor render correctly.", "distractor_analysis": {"1": "A dead backlight would make the cursor invisible too.", "2": "A card with no memory would not drive any display.", "3": "Cable problems cause signal loss, not an empty desktop with a working cursor."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "multiple-monitors", "extend"]}, {"id": "C1N-T2-016", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.3", "type": "single", "difficulty": "medium", "question": "A monitor flickers and the image briefly cuts out several times a minute. Swapping the cable does not help, but the flicker stops when a nearby desk fan is turned off. What is the cause?", "options": ["Electromagnetic interference from the fan's motor affecting the display signal or the monitor's electronics", "The monitor is too bright", "The graphics driver needs a licence", "The desk is too high"], "answer": 0, "explanation": "Motors, fluorescent ballasts and poorly shielded power adapters emit electromagnetic interference that can corrupt a marginal video signal or upset a monitor's power circuitry. The correlation with the fan running is the diagnosis. Moving the fan or the monitor, using a well-shielded cable and routing it away from the interference source, or plugging the monitor into a different circuit fixes it. Brightness, licensing and furniture height are irrelevant.", "distractor_analysis": {"1": "Brightness does not cause intermittent signal loss.", "2": "Drivers are not licensed and would not correlate with the fan.", "3": "Desk height has no electrical effect."}, "video_reference": {"title": "Troubleshooting Display Issues - CompTIA A+ 220-1201 - 5.3", "url": "https://www.youtube.com/watch?v=KXZu72i1eX8", "duration": "18:52", "objective": "5.3"}, "notes_reference": "08_BIOS_UEFI_Hardware_Troubleshooting.md", "tags": ["troubleshooting", "display", "emi", "flicker"]}, {"id": "C1N-T2-017", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A workstation has an IP address of 169.254.10.7 and cannot reach any server. Other workstations on the same switch work normally. What does the address indicate?", "options": ["The workstation failed to obtain a DHCP lease and assigned itself an automatic private address", "The workstation has been assigned a public address", "The workstation is connected to the wrong VLAN", "The workstation's DNS is misconfigured"], "answer": 0, "explanation": "Addresses in the 169.254.0.0/16 range are Automatic Private IP Addressing, which Windows uses when no DHCP server responds. Because other machines on the same switch work, the server is up, so the fault is local: a bad patch cable, a disabled port, a faulty network adapter or a stale lease. Releasing and renewing the lease, checking the link light and swapping the cable isolate it. The address is not public, VLAN problems produce a different pattern, and DNS is irrelevant without an address.", "distractor_analysis": {"1": "169.254 is a reserved link-local range, not public space.", "2": "A wrong VLAN could also block DHCP, but other devices on the same port group working makes the local link more likely.", "3": "DNS only matters once a valid address exists."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "apipa", "dhcp"]}, {"id": "C1N-T2-018", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A user's PC can ping its default gateway and other internal servers but cannot reach any website by name or by address. What is the most likely cause?", "options": ["The gateway's connection to the internet or its routing is down; the problem is beyond the local network", "The PC's network cable is unplugged", "The PC has an APIPA address", "The PC's DNS server is wrong"], "answer": 0, "explanation": "Successful pings to the gateway and internal servers prove the cable, adapter, address and local routing are fine. Failing to reach the internet even by IP address rules out DNS, because no name lookup is involved. That leaves the path from the gateway outward: the router's WAN link, the provider, or the firewall. Checking the router's status page and whether other users are affected confirms it and points to the provider or the edge device.", "distractor_analysis": {"1": "An unplugged cable would prevent pinging the gateway.", "2": "An APIPA address cannot ping internal servers on a routed network.", "3": "DNS is not involved when browsing by IP address fails too."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "connectivity", "gateway"]}, {"id": "C1N-T2-019", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A wired desktop connects at 100 Mbps although the switch and adapter both support gigabit. The link was gigabit last week. What is the most likely cause?", "options": ["A damaged cable or connector, since gigabit needs all four pairs and a single broken pair falls back to 100 Mbps", "The switch has been downgraded by firmware", "The PC has too many browser tabs open", "The monitor is drawing too much power"], "answer": 0, "explanation": "Fast Ethernet uses two of the four wire pairs in a twisted-pair cable, but gigabit requires all four. If one pair is broken by a crushed cable, a bent pin or a poor termination, the link auto-negotiates down to 100 Mbps and appears to work. Replacing the patch cable or re-terminating the wall jack restores gigabit. Switch firmware does not silently downgrade one port, and applications and monitors have no effect on link speed negotiation.", "distractor_analysis": {"1": "Firmware changes do not selectively lower one port's speed.", "2": "Application load does not change the physical link rate.", "3": "Monitor power is unrelated to Ethernet."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "link-speed", "cabling"]}, {"id": "C1N-T2-020", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "Users in one corner of an office complain of slow Wi-Fi and frequent disconnections, while the rest of the floor is fine. A site survey shows a weak signal there. What is the best fix?", "options": ["Add or reposition an access point to cover the weak area", "Tell users to move desks", "Disable the 5 GHz band", "Change every user's password"], "answer": 0, "explanation": "A localised weak signal is a coverage problem. Adding an access point, or moving an existing one closer to the affected area, raises signal strength so clients negotiate faster rates and stop roaming or dropping. A heat map from a survey tool shows where the dead zone is and confirms the fix. Relocating staff treats the symptom, disabling 5 GHz pushes everyone to the slower band, and passwords have no bearing on signal.", "distractor_analysis": {"1": "Moving people avoids the problem instead of fixing it.", "2": "Removing 5 GHz reduces capacity everywhere.", "3": "Credentials do not affect radio coverage."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "wi-fi", "coverage"]}, {"id": "C1N-T2-021", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "hard", "question": "Two PCs on the same network intermittently lose connectivity, and the event logs on both report an IP address conflict. What is the most likely cause and fix?", "options": ["A device has a static address inside the DHCP pool; move the static device outside the pool or create an exclusion", "The switch is too old; replace it", "The PCs need new monitors", "The cable is the wrong colour"], "answer": 0, "explanation": "An address conflict means two devices claim the same IP. The usual cause is a printer, camera or server that was given a static address inside the range the DHCP server hands out, so eventually the server leases the same address to a PC. Both then drop off intermittently as they fight over it. Finding the static device by its MAC address, moving it to an address outside the pool or excluding that address in the DHCP scope resolves it permanently.", "distractor_analysis": {"1": "Switch age does not create duplicate addresses.", "2": "Monitors are irrelevant to addressing.", "3": "Cable colour has no technical meaning."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "ip-conflict", "dhcp"]}, {"id": "C1N-T2-022", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A user reports that video calls stutter and voices break up although a speed test shows plenty of bandwidth. Which network characteristics should the technician measure?", "options": ["Latency, jitter and packet loss, which affect real-time traffic more than raw bandwidth", "Hard drive free space", "Screen resolution", "The number of installed fonts"], "answer": 0, "explanation": "Voice and video are sensitive to delay, to variation in delay called jitter, and to lost packets, none of which a bandwidth test reveals. A congested Wi-Fi link, a saturated uplink or a misbehaving switch can have high throughput and still break up calls. Continuous ping tests and the call application's own statistics show the problem, and quality of service, a wired connection or fixing the congested link resolve it. The other options have nothing to do with network quality.", "distractor_analysis": {"1": "Disk space does not affect call quality.", "2": "Resolution is a display setting.", "3": "Fonts are irrelevant to networking."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "latency", "jitter", "voip"]}, {"id": "C1N-T2-023", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "A PC can browse the internet but cannot open a shared folder on a server by its name, although the server responds to ping by IP address. What should be checked?", "options": ["Internal DNS name resolution for the server, for example with nslookup, and the PC's configured DNS servers", "The PC's power supply", "The monitor cable", "The keyboard layout"], "answer": 0, "explanation": "Reaching the server by IP address proves connectivity; failing by name means the name is not resolving to that address. Common causes are a PC pointed at a public DNS server that knows nothing about internal names, a missing internal record or a stale cache. Running nslookup against the server name shows which resolver answered and what it returned, and correcting the DNS settings or flushing the cache fixes it. Hardware and input settings are unrelated to name resolution.", "distractor_analysis": {"1": "The PC is running and browsing; power is fine.", "2": "Display cabling does not affect name lookups.", "3": "Keyboard layout does not change how names resolve."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "dns", "name-resolution"]}, {"id": "C1N-T2-024", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.5", "type": "single", "difficulty": "medium", "question": "After a switch port was moved to a new patch panel, the connected PC has no link light at all. Which tool confirms whether the cable run between the wall jack and the patch panel is good?", "options": ["A cable tester or a toner and probe", "A multimeter set to AC voltage", "A loopback plug on the monitor", "A screwdriver"], "answer": 0, "explanation": "No link light means no electrical connection between the two ends. A cable tester checks every pair for continuity, shorts and miswires, and a toner and probe traces which patch panel port a wall jack actually terminates on, which is often the problem after a move. Once the run is proven and correctly patched, the link light returns. A multimeter can check continuity but not wiring order, loopback plugs test ports rather than runs, and a screwdriver diagnoses nothing.", "distractor_analysis": {"1": "Voltage measurement is for power, not network wiring.", "2": "Loopback plugs are for network ports, not monitors, and do not test cable runs.", "3": "A screwdriver is not a diagnostic tool."}, "video_reference": {"title": "Troubleshooting Networks - CompTIA A+ 220-1201 - 5.5", "url": "https://www.youtube.com/watch?v=VBDS_kOHhVk", "duration": "15:15", "objective": "5.5"}, "notes_reference": "13_DHCP_DNS_VLAN_VPN_Network_Troubleshooting.md", "tags": ["troubleshooting", "networking", "cable-tester", "no-link"]}, {"id": "C1N-T2-025", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A laser printer produces pages with a repeating smudge every few centimetres down the page. Which component is most likely responsible?", "options": ["A damaged or dirty roller or drum, because a defect on a rotating part repeats once per rotation", "Low toner", "The wrong paper size setting", "A network cable fault"], "answer": 0, "explanation": "A mark that repeats at a regular interval down the page is produced by something rotating: the imaging drum, a transfer roller or the fuser. The spacing matches the circumference of the faulty part, and manufacturers publish repetition distances to identify which one it is. Cleaning or replacing that consumable fixes the defect. Low toner causes faint or patchy print, a paper size mismatch causes cropped or misaligned output, and network faults stop printing entirely.", "distractor_analysis": {"1": "Low toner produces fading, not a repeating mark.", "2": "Paper settings affect layout, not marks.", "3": "Network problems prevent jobs arriving rather than marking pages."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "laser", "repeating-defect"]}, {"id": "C1N-T2-026", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "Printed pages from a laser printer smear when touched and the toner rubs off easily. Which component has failed?", "options": ["The fuser, which is not reaching the temperature needed to bond toner to the paper", "The pickup roller", "The paper tray sensor", "The network card"], "answer": 0, "explanation": "Toner is a fine plastic powder that is melted onto the page by the fuser's heated roller. If the fuser lamp or its thermistor fails, or the fuser is worn, toner sits loose on the surface and wipes away. Fusers are user-replaceable maintenance items on most office printers. Pickup rollers cause feed problems, tray sensors cause paper errors, and the network card affects connectivity rather than print quality.", "distractor_analysis": {"1": "Pickup roller faults cause jams or no feed.", "2": "Tray sensors report paper presence.", "3": "Network faults stop jobs, they do not affect fusing."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "laser", "fuser"]}, {"id": "C1N-T2-027", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "An inkjet printer prints pages with horizontal white lines through text and images. What is the first thing to try?", "options": ["Run the printer's head cleaning routine and print a nozzle check", "Replace the paper tray", "Reinstall the operating system", "Change the network cable"], "answer": 0, "explanation": "Fine horizontal gaps in inkjet output are clogged or dried nozzles in the print head, especially if the printer has sat unused. The built-in cleaning cycle forces ink through the nozzles and the nozzle check page shows which colours still have gaps; repeating the cycle two or three times usually clears it, and a head replacement is the last resort. The tray, the operating system and the cable have nothing to do with nozzle output.", "distractor_analysis": {"1": "The tray feeds paper and does not affect ink.", "2": "Operating system state does not clog nozzles.", "3": "The job is arriving and printing, so connectivity is fine."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "inkjet", "nozzle"]}, {"id": "C1N-T2-028", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "Users send print jobs to a shared printer and nothing prints, but the jobs remain listed in the queue on their PCs. The printer's display shows Ready. What should the technician check first?", "options": ["The print spooler service on the print server, restarting it and clearing any stuck job at the head of the queue", "The paper type in the tray", "The colour of the toner cartridge", "The monitor on the print server"], "answer": 0, "explanation": "A printer that reports Ready while every job sits in the queue points at the software between the users and the device. A corrupt job at the front of the spooler blocks everything behind it, and the spooler service can hang. Restarting the spooler and deleting the stuck job on the print server releases the queue. If jobs still do not flow, the port configuration or the printer's network address should be checked. Paper type, cartridge colour and the server's monitor are irrelevant.", "distractor_analysis": {"1": "Paper settings affect output, not whether jobs leave the queue.", "2": "Cartridge colour is meaningless here.", "3": "The server's display has no effect on printing."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "spooler", "queue"]}, {"id": "C1N-T2-029", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A laser printer repeatedly pulls two or three sheets at once from the tray, causing jams. Which component is most likely worn?", "options": ["The separation pad or pickup rollers", "The fuser", "The toner cartridge", "The network interface"], "answer": 0, "explanation": "Multi-sheet feeds happen when the separation pad, which holds back all but the top sheet, is worn smooth, or when pickup rollers have lost their grip and grab several sheets together. Both are inexpensive maintenance parts. Fanning the paper and checking for humidity also helps, since damp sheets stick together. The fuser fixes toner after feeding, the cartridge supplies toner, and the network interface delivers jobs; none of them touch the paper stack.", "distractor_analysis": {"1": "The fuser is downstream of the feed mechanism.", "2": "Toner supply does not affect paper pickup.", "3": "Network components have no mechanical role."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "multi-feed", "separation-pad"]}, {"id": "C1N-T2-030", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.6", "type": "single", "difficulty": "medium", "question": "A user prints a document and receives pages of random characters and symbols instead of the text. What is the most likely cause?", "options": ["The wrong or a corrupted printer driver, so the printer receives a page description language it does not understand", "The paper is the wrong size", "The toner is low", "The printer is out of warranty"], "answer": 0, "explanation": "Garbage output means the printer is interpreting the data stream in the wrong language, for example PostScript sent to a printer expecting PCL, or a driver mismatch after a model change or a corrupted driver update. Reinstalling the correct manufacturer driver for the exact model, or switching the port's language setting, fixes it. Paper size causes cropping, low toner causes fading, and warranty status has no technical effect.", "distractor_analysis": {"1": "Wrong paper size crops or shifts the page.", "2": "Low toner fades output rather than corrupting it.", "3": "Warranty does not change how the printer functions."}, "video_reference": {"title": "Troubleshooting Printers - CompTIA A+ 220-1201 - 5.6", "url": "https://www.youtube.com/watch?v=_BhO_nYod0o", "duration": "11:55", "objective": "5.6"}, "notes_reference": "16_Printers.md", "tags": ["troubleshooting", "printers", "garbled-output", "driver"]}, {"id": "C1N-T2-031", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A laptop's battery no longer charges above 80 percent although the machine is plugged in all day. The battery health tool shows normal capacity. What is the most likely explanation?", "options": ["A battery conservation or charge threshold setting is limiting the charge to prolong battery life", "The battery has failed", "The AC adapter is faulty", "The laptop is overheating"], "answer": 0, "explanation": "Most business laptops include a setting, in the vendor utility or firmware, that caps charging at around 80 percent when the machine lives on mains power, because holding lithium cells at full charge accelerates wear. A battery that stops at exactly the same percentage every time, with healthy capacity, is being managed rather than failing. The user can disable the setting before travel. A failed battery shows reduced capacity, a bad adapter would not charge at all, and overheating pauses charging inconsistently.", "distractor_analysis": {"1": "The health tool reports normal capacity.", "2": "A faulty adapter would fail to charge to 80 percent either.", "3": "Thermal limits do not stop at a fixed percentage."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "laptop", "battery", "charge-threshold"]}, {"id": "C1N-T2-032", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A tablet's screen does not respond in one horizontal band across the middle, but works above and below it. What is the most likely cause?", "options": ["A digitizer fault, often from a crack or delamination, affecting one set of sensor lines", "The tablet needs a software update", "The battery is low", "The Wi-Fi is disconnected"], "answer": 0, "explanation": "The touch digitizer is a grid of conductive lines. Damage to the flex cable or the glass, or moisture ingress, can kill a group of adjacent lines, producing a dead strip while the rest of the screen works. Because it is a fixed region, a restart or software update will not restore it; the digitizer or display assembly must be replaced. Battery level and connectivity have no effect on which part of the screen senses touch.", "distractor_analysis": {"1": "A geographically fixed dead zone is hardware, not software.", "2": "Low battery does not disable a section of the digitizer.", "3": "Wi-Fi is unrelated to touch input."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "tablet", "digitizer", "touchscreen"]}, {"id": "C1N-T2-033", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A laptop shuts down the moment the AC adapter is unplugged even though the battery indicator showed 60 percent. What does this indicate?", "options": ["The battery can no longer deliver current under load and needs replacing, despite the reported charge", "The adapter is the wrong wattage", "The laptop's fan is failing", "The display cable is loose"], "answer": 0, "explanation": "A battery's reported percentage comes from its own gauge, which can drift as cells age. When the internal resistance of worn cells rises, the pack cannot supply the current the laptop needs and voltage collapses the instant the adapter is removed, causing an immediate shutdown. Recalibration rarely helps at this stage; the battery is at end of life. Adapter wattage matters only while plugged in, and fans and display cabling are unrelated to power delivery.", "distractor_analysis": {"1": "The adapter is not in use once unplugged.", "2": "A failing fan causes overheating, not instant power loss.", "3": "Display cabling does not cut power."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "laptop", "battery", "shutdown"]}, {"id": "C1N-T2-034", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A laptop's keyboard types the wrong characters, for example a pound sign when the hash key is pressed and swapped quote marks. What is the most likely cause?", "options": ["The keyboard layout or input language is set to a different region than the physical keyboard", "The keyboard has liquid damage", "The touchpad driver is corrupt", "The screen needs recalibrating"], "answer": 0, "explanation": "Swapped symbols on otherwise working keys are a layout mismatch: the operating system believes a US keyboard is attached when the hardware is UK, or vice versa, often because a second input language was added and a shortcut switched between them. Correcting the keyboard layout in language settings and removing the unused one fixes it instantly. Liquid damage produces dead or repeating keys, and touchpad and display settings have no effect on character mapping.", "distractor_analysis": {"1": "Liquid damage kills keys rather than remapping them.", "2": "The touchpad has no role in keyboard mapping.", "3": "Screen calibration affects touch, not typed characters."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "laptop", "keyboard", "layout"]}, {"id": "C1N-T2-035", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "single", "difficulty": "medium", "question": "A laptop connects to Wi-Fi but the signal indicator shows one bar even when sitting next to the access point, and a phone in the same spot shows full strength. What is the most likely cause?", "options": ["A disconnected or damaged antenna lead to the laptop's wireless card, often after a screen or hinge repair", "The access point is faulty", "The laptop's hard drive is full", "The Wi-Fi password is wrong"], "answer": 0, "explanation": "The phone proves the access point is transmitting strongly at that spot, so the laptop is receiving poorly. A wireless card with one or both antenna leads detached or pinched, or a broken lead running through the hinge, hears almost nothing even at close range. Reattaching the leads, or replacing a damaged one, restores normal strength. Storage and credentials have nothing to do with received signal, and a wrong password prevents connection entirely.", "distractor_analysis": {"1": "The phone shows full strength from the same access point.", "2": "Disk space does not affect radio reception.", "3": "A wrong password would block the connection, not weaken the signal."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "laptop", "wi-fi", "antenna"]}, {"id": "C1N-T2-036", "exam": "core1", "domain": "5.0 Hardware and Network Troubleshooting", "objective": "5.4", "type": "match", "difficulty": "medium", "question": "Match each mobile device symptom to the most likely cause.", "pairs": [{"left": "Charges to exactly 80 percent every time", "right": "Charge threshold setting"}, {"left": "Shuts down instantly when unplugged at 60 percent", "right": "Worn battery unable to supply current"}, {"left": "Dead strip across the touchscreen", "right": "Damaged digitizer"}, {"left": "One signal bar next to the access point", "right": "Detached antenna lead"}, {"left": "Hash key prints a pound sign", "right": "Wrong keyboard layout"}], "explanation": "Mobile hardware faults tend to have distinctive signatures. Fixed charge ceilings are deliberate settings. Instant shutdown under load is a battery that reports charge it cannot deliver. A fixed dead zone in touch is physical digitizer damage. Poor reception with a strong nearby signal is the laptop's own antenna path. Swapped symbols are a layout mismatch in software. Recognising each pattern avoids replacing the wrong part.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1201 - 5.4", "url": "https://www.youtube.com/watch?v=huQwiY4kiko", "duration": "17:52", "objective": "5.4"}, "notes_reference": "15_Mobile_Devices_and_Laptops.md", "tags": ["troubleshooting", "mobile", "match"]}], "core2": [{"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A technician is setting up a new workstation for an employee who needs to join the corporate Active Directory domain. Which Windows edition CANNOT join a Windows Server domain?", "options": ["Windows Education", "Windows Home", "Windows Pro", "Windows Enterprise"], "answer": 3, "explanation": "Windows Home edition is designed strictly for consumers and small home users; it lacks the network architecture, Group Policy management, and security subsystems required to join an Active Directory domain. Windows Pro, Enterprise, and Education all support native domain joining, BitLocker, and centralized management. Pro provides business networking features, Enterprise provides advanced corporate virtualization and DirectAccess, and Education provides academic licensing controls.", "distractor_analysis": {"1": "Windows Pro includes full Active Directory domain join capabilities, BitLocker, and Group Policy client support.", "2": "Windows Enterprise is the premier corporate edition with full domain join, DirectAccess, and AppLocker features.", "3": "Windows Education includes all Enterprise-level capabilities, including native domain join for academic networks."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-editions", "domain-join", "active-directory", "licensing"], "id": "C2-001"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "An IT department is building a high-performance CAD engineering desktop running 64-bit Windows 10/11 Pro. What is the maximum physical RAM capacity supported by the Pro edition?", "options": ["6 TB", "512 GB", "128 GB", "2 TB"], "answer": 3, "explanation": "64-bit Windows 10/11 Pro supports a maximum physical memory capacity of 2 TB (terabytes) of RAM. Windows 10/11 Home is capped at 128 GB of RAM. Windows Pro for Workstations and Enterprise support up to 6 TB of RAM and up to 4 physical CPU sockets. 512 GB is an arbitrary limit not aligned with standard Windows SKU boundaries.", "distractor_analysis": {"0": "128 GB is the physical RAM ceiling for Windows 10/11 Home edition, not Windows Pro.", "2": "6 TB is the maximum memory limit supported by Windows Pro for Workstations and Windows Enterprise editions.", "3": "512 GB is a distractor figure and does not represent the architectural RAM cap for standard Windows Pro."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-editions", "ram-limits", "64-bit", "hardware-specs"], "id": "C2-002"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A procurement manager needs to license operating systems for 1,000 corporate laptops using a central Volume Licensing agreement (KMS/MAK). Which Windows editions are available exclusively through volume licensing channels?", "options": ["Pro", "Enterprise and Education", "Pro for Workstations", "Home"], "answer": 3, "explanation": "Windows Enterprise and Education editions are not sold as retail standalone boxed products; they are available exclusively through Microsoft Volume Licensing agreements or academic licensing contracts. Windows Home and Pro are available as retail and OEM licenses. Pro for Workstations can be purchased via retail OEM channels and volume licensing.", "distractor_analysis": {"0": "Windows Home is sold directly to consumers through retail channels and OEM pre-installs.", "1": "Windows Pro is widely available as standalone retail packaged product and pre-installed OEM software.", "3": "Windows Pro for Workstations can be obtained pre-installed on high-end OEM hardware without enterprise volume agreements."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-editions", "volume-licensing", "enterprise", "procurement"], "id": "C2-003"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A technician is assessing whether an existing fleet of desktop computers can be upgraded to Windows 11. Which core security hardware requirement is MANDATORY for Windows 11 installation?", "options": ["Legacy BIOS with Master Boot Record (MBR)", "A minimum of 2 GB RAM", "32-bit single-core CPU", "TPM 2.0 and UEFI with Secure Boot capability"], "answer": 3, "explanation": "Windows 11 requires a compatible 64-bit processor (1 GHz or faster with 2 or more cores), 4 GB of RAM, 64 GB of storage, UEFI firmware with Secure Boot enabled, and a Trusted Platform Module (TPM) version 2.0 chip. 32-bit CPUs and Legacy BIOS/MBR are completely unsupported on Windows 11, and 2 GB of RAM is below the minimum 4 GB RAM requirement.", "distractor_analysis": {"0": "Windows 11 is strictly a 64-bit operating system and does not run on 32-bit processors.", "2": "Legacy BIOS and MBR partition tables are deprecated for Windows 11; UEFI with GPT is required.", "3": "Windows 11 requires a minimum of 4 GB RAM; 2 GB is insufficient."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-11", "system-requirements", "tpm", "uefi"], "id": "C2-004"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A storage administrator is partitioning a 10 TB drive using the GUID Partition Table (GPT) scheme. What is the maximum number of primary partitions natively supported by Windows on a GPT disk?", "options": ["26 primary partitions", "128 primary partitions", "256 primary partitions", "4 primary partitions"], "answer": 3, "explanation": "The GUID Partition Table (GPT) standard natively supports up to 128 primary partitions in Windows without requiring extended partitions or logical drives. In contrast, the legacy MBR partition scheme supports a maximum of 4 primary partitions (or 3 primary partitions plus 1 extended partition). 26 corresponds to drive letters A-Z, and 256 is an arbitrary number.", "distractor_analysis": {"0": "4 primary partitions is the architectural limit for legacy Master Boot Record (MBR) disks.", "1": "26 is the maximum number of assigned drive letters (A through Z) in Windows, not the GPT partition table limit.", "3": "256 is an incorrect value; Microsoft Windows allocates 128 partition entries in GPT headers."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["file-systems", "gpt", "partitioning", "disk-management"], "id": "C2-005"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A technician installs a new 4 TB hard drive formatted with the legacy Master Boot Record (MBR) scheme. Why does Windows only display 2 TB of usable capacity?", "options": ["Windows requires a third-party driver to format drives larger than 1 TB", "MBR has an architectural 32-bit sector addressing limit that caps maximum disk size at 2 TB", "The motherboard power supply is failing to deliver 12V rail power", "The SATA data cable is defective and dropping communication packets"], "answer": 3, "explanation": "The Master Boot Record (MBR) partition scheme uses 32-bit sector addressing with standard 512-byte sectors, resulting in a maximum addressable storage capacity of 2.19 TB (2 TB). Any drive space beyond 2 TB on an MBR disk remains unusable unallocated space. Supporting drives larger than 2 TB requires converting the disk to GUID Partition Table (GPT). Power supplies, cables, and third-party drivers do not change the mathematical limits of 32-bit MBR addressing.", "distractor_analysis": {"1": "Power rail voltage issues cause complete disk detection failure or intermittent spin-down, not a clean 2 TB capacity limit.", "2": "A bad SATA data cable causes CRC errors and bus timeouts, not a structural 2 TB partition boundary.", "3": "Windows natively supports large storage drives using GPT without requiring third-party formatting drivers."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["file-systems", "mbr", "disk-size", "partitioning"], "id": "C2-006"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A technician boots 50 bare-metal workstations over the local network using DHCP and TFTP to load a Windows deployment image from a WDS server. What network boot technology is being utilized?", "options": ["Retail ISO boot", "Windows Autopilot cloud provisioning", "USB boot", "Preboot Execution Environment (PXE)"], "answer": 3, "explanation": "Preboot Execution Environment (PXE, pronounced 'pixie') is an industry standard client-server environment that allows a workstation's network interface card (NIC) to boot an operating system from a network server via DHCP and TFTP before any local OS is loaded. USB and ISO boots rely on local physical media, and Windows Autopilot configures pre-installed Windows over internet cloud services.", "distractor_analysis": {"0": "USB boot requires physical flash drives inserted into each computer rather than booting over the network.", "2": "Retail ISO boot requires optical media or mounted local image files rather than network NIC PXE ROMs.", "3": "Windows Autopilot provisions devices from the cloud after an initial factory image boots, rather than executing bare-metal TFTP network boots."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["os-installation", "pxe", "network-boot", "wds"], "id": "C2-007"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A systems administrator performs an in-place upgrade from Windows 10 Pro to Windows 11 Pro on a corporate laptop. What user assets are preserved by default during a successful in-place upgrade?", "options": ["Only installed applications while all personal files are deleted", "Only desktop background settings while user directories are wiped", "Nothing is preserved (the drive is formatted)", "User personal files, applications, and system settings"], "answer": 3, "explanation": "An in-place upgrade updates the core operating system files to a newer version while preserving all existing user personal files, installed desktop applications, user profiles, and configuration settings in place without reformatting the drive. A clean installation wipes the drive, and there is no upgrade mode that preserves only applications while wiping documents.", "distractor_analysis": {"0": "A clean install / wipe-and-load formats the drive; an in-place upgrade specifically preserves data and programs.", "2": "Windows in-place upgrades do not selectively delete personal user files while retaining software binaries.", "3": "In-place upgrades preserve full user directory structures and personal files along with profile settings."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["os-upgrade", "in-place-upgrade", "migration", "data-retention"], "id": "C2-008"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "A workstation experiences intermittent crashes and corrupted DLL errors. Which command-line utility scans all protected Windows system files and replaces corrupted files with a cached copy from the component store?", "options": ["`diskpart`", "`format C:`", "`chkdsk /f`", "`sfc /scannow`"], "answer": 3, "explanation": "The System File Checker (`sfc /scannow`) inspects all protected operating system binaries, DLLs, and drivers against cryptographic manifests, replacing missing or corrupted files with pristine copies cached in `%WinDir%\\System32\\dllcache` or the WinSxS component store. `chkdsk` checks disk volume sectors and NTFS tables, `diskpart` manages disk partitions, and `format` wipes volumes.", "distractor_analysis": {"0": "`chkdsk` scans file system metadata and hard drive sectors for physical/logical disk errors, not operating system DLL integrity.", "2": "`diskpart` is a command-line partitioning tool used to create, delete, and resize volume partitions.", "3": "`format` initializes or wipes a volume with a specified file system, destroying all existing files."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "sfc", "system-integrity", "windows-tools"], "id": "C2-009"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A help desk technician needs to verify which specific Group Policy Objects (GPOs) and user rights are currently applied to a domain-joined computer and logged-in user. Which command displays the Resultant Set of Policy?", "options": ["`secpol.msc`", "`gpedit.msc`", "`gpupdate /force`", "`gpresult /r`"], "answer": 3, "explanation": "The `gpresult /r` command generates a summary report in Command Prompt showing the Resultant Set of Policy (RSoP), including applied GPOs, security group memberships, and policy priority for both the computer account and user account. `gpupdate /force` reapplies policy immediately, `secpol.msc` opens local security policy, and `gpedit.msc` edits local policy templates.", "distractor_analysis": {"0": "`gpupdate /force` forces an immediate refresh of Group Policy settings from Active Directory, but does not display an RSoP audit report.", "2": "`secpol.msc` opens the Local Security Policy GUI snap-in for the local machine rather than generating domain RSoP command output.", "3": "`gpedit.msc` opens the Local Group Policy Editor GUI to configure local policy templates."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "gpresult", "group-policy", "troubleshooting"], "id": "C2-010"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "A technician enters the command `shutdown /r /t 60` into an elevated Windows Command Prompt. What action will the operating system perform?", "options": ["Put the system into Hibernate mode", "Log off the current user session immediately", "Perform an immediate power off of the computer", "Restart the computer after a 60-second delay"], "answer": 3, "explanation": "In the Windows `shutdown` command, the `/r` switch instructs the system to reboot (restart) rather than shut down (`/s`), and the `/t 60` switch specifies a countdown timer delay of 60 seconds before initiating the restart. Immediate shutdown uses `/s /t 0`, hibernate uses `/h`, and logoff uses `/l`.", "distractor_analysis": {"0": "Immediate shutdown is accomplished using `shutdown /s /t 0`.", "2": "Hibernation is invoked using `shutdown /h`.", "3": "Logging off the current interactive user session is executed with `shutdown /l`."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "shutdown", "command-line", "automation"], "id": "C2-011"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A system administrator needs to copy 500 GB of files across a network link, ensuring all NTFS permissions and timestamps are preserved, and that interrupted transfers resume automatically. Which built-in command-line tool is BEST suited for this task?", "options": ["`xcopy`", "`robocopy`", "`move`", "`copy`"], "answer": 3, "explanation": "`robocopy` (Robust File Copy) is a powerful Windows command-line replication utility designed for large-scale and network file transfers. It supports multi-threading, automatic retry and resumption of interrupted network transfers, directory mirroring (`/mir`), and preservation of NTFS permissions, attributes, and timestamps. `copy` and `move` are basic single-file utilities lacking resumption, and `xcopy` is a legacy tool superseded by robocopy.", "distractor_analysis": {"0": "`copy` is a basic Command Prompt tool that cannot resume interrupted network copies or mirror folder trees.", "1": "`xcopy` can copy directories but lacks modern multi-threaded transfer resilience and robust network retry capabilities.", "3": "`move` relocates files from one directory to another without providing network resumption or mirroring."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "robocopy", "file-migration", "command-line"], "id": "C2-012"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "When using the `xcopy` command to replicate a directory structure, which command switch MUST be appended to copy all subdirectories, including any empty subdirectories?", "options": ["`/E`", "`/H`", "`/Y`", "`/S`"], "answer": 2, "explanation": "In `xcopy`, the `/E` switch copies directories and subdirectories, including empty ones. The `/S` switch copies subdirectories but excludes empty ones. The `/H` switch copies hidden and system files, and the `/Y` switch suppresses prompting to confirm overwriting existing destination files.", "distractor_analysis": {"0": "`/S` copies folders and subfolders containing data, but deliberately skips empty subdirectories.", "2": "`/H` includes hidden and system files in the copy operation, regardless of directory emptiness.", "3": "`/Y` suppresses interactive prompts asking whether to overwrite existing destination files."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "xcopy", "command-line", "switches"], "id": "C2-013"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "A technician needs to delete a folder named 'OldLogs' and all of its files and nested subfolders using the Windows command line. Which command accomplishes this?", "options": ["`del OldLogs`", "`del /q OldLogs`", "`rd OldLogs`", "`rd /s OldLogs`"], "answer": 3, "explanation": "The Remove Directory command (`rd` or `rmdir`) with the `/s` switch removes the specified directory and all its subdirectories and files (a recursive tree deletion). Running `rd` without `/s` fails if the directory is not empty. The `del` command deletes individual files within a directory but does not remove the directory structure itself.", "distractor_analysis": {"0": "`rd` without switches fails with an error ('The directory is not empty') if any files exist inside.", "2": "`del` deletes files inside the folder but leaves the folder directory structure intact.", "3": "`del /q` performs quiet deletion of files without prompts, but still cannot delete the parent folder."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "rd", "rmdir", "directory-management"], "id": "C2-014"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "Which Microsoft Management Console (MMC) snap-in command directly launches the Local Users and Groups management console on Windows Pro?", "options": ["`gpedit.msc`", "`certmgr.msc`", "`lusrmgr.msc`", "`secpol.msc`"], "answer": 2, "explanation": "`lusrmgr.msc` opens the Local Users and Groups snap-in, allowing administrators to create, delete, modify, and manage local user accounts and local security groups on non-Home Windows editions. `secpol.msc` opens Local Security Policy, `gpedit.msc` opens Local Group Policy Editor, and `certmgr.msc` opens User Certificates.", "distractor_analysis": {"1": "`secpol.msc` manages password complexity, account lockout, and audit policies on the local machine.", "2": "`gpedit.msc` configures local computer and user Group Policy templates.", "3": "`certmgr.msc` manages X.509 digital certificates and certificate trust stores for the current user."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["mmc", "lusrmgr", "user-management", "windows-tools"], "id": "C2-015"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "medium", "question": "A systems administrator needs to manage digital certificates for the current logged-on user account versus the local computer machine store. Which MMC snap-ins correspond to user certificates and computer certificates respectively?", "options": ["`gpedit.msc` for User and `secpol.msc` for Computer", "`certmgr.msc` for Current User and `certlm.msc` for Local Computer", "`certlm.msc` for Current User and `certmgr.msc` for Local Computer", "`mmc.exe` for User and `regedit.exe` for Computer"], "answer": 3, "explanation": "In Windows, `certmgr.msc` opens the Certificate Manager for the Current User (`HKCU\\Software\\Microsoft\\SystemCertificates`), while `certlm.msc` opens the Local Computer certificate store (`HKLM\\Software\\Microsoft\\SystemCertificates`). Reversing them is incorrect, `regedit` is the raw registry editor, and `gpedit`/`secpol` manage policy templates.", "distractor_analysis": {"1": "`certlm.msc` specifically manages Local Machine certificates, not the current interactive user store.", "2": "`mmc.exe` launches an empty console shell, and `regedit` edits raw registry hives.", "3": "`gpedit.msc` and `secpol.msc` configure Group Policy and security templates, not certificate stores."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["mmc", "certificates", "certmgr", "certlm", "windows-tools"], "id": "C2-016"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which Windows Registry root key stores desktop wallpaper settings, user environment variables, and application preferences specific to the currently logged-in user session?", "options": ["`HKEY_CURRENT_USER (HKCU)`", "`HKEY_CLASSES_ROOT (HKCR)`", "`HKEY_CURRENT_CONFIG (HKCC)`", "`HKEY_LOCAL_MACHINE (HKLM)`"], "answer": 2, "explanation": "`HKEY_CURRENT_USER (HKCU)` links to the current user's profile subkey in `HKEY_USERS` (loaded from `NTUSER.DAT`) and stores settings specific to the active user, including display themes, mapped printers, personal environment variables, and user software preferences. `HKLM` stores system-wide hardware and OS settings, `HKCR` stores file associations and COM classes, and `HKCC` points to current hardware profile information.", "distractor_analysis": {"0": "`HKLM` stores machine-wide configuration data common to all users on the computer (hardware, drivers, installed software).", "2": "`HKCR` manages file type associations, OLE data, and COM object class registrations.", "3": "`HKCC` contains runtime hardware configuration pointers linked from `HKLM\\SYSTEM`."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["registry", "hkcu", "hklm", "user-profile"], "id": "C2-017"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "medium", "question": "A technician needs to adjust the CPU execution priority (e.g., Realtime, High, Normal, Low) or CPU affinity for a misbehaving background process. Which tab in Task Manager provides these controls?", "options": ["Performance tab", "Users tab", "Processes tab", "Details tab"], "answer": 3, "explanation": "In Windows Task Manager, the `Details` tab provides low-level process controls, including Process ID (PID), memory commit charge, User Name, and right-click options to 'Set priority' (Realtime, High, Above normal, Normal, Below normal, Low) and 'Set affinity' (assigning specific CPU cores). The Processes tab groups applications by category, Performance graphs overall utilization, and Users shows logged-on sessions.", "distractor_analysis": {"0": "The Processes tab displays friendly names and resource consumption percentages, but does not provide Set Priority / Affinity menus.", "2": "The Performance tab graphs live CPU, Memory, Disk, and Network hardware metrics without process-specific tuning menus.", "3": "The Users tab shows active user sessions and aggregate resource draw per account."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["task-manager", "process-priority", "details-tab", "performance"], "id": "C2-018"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "medium", "question": "A systems engineer needs to record historical CPU, disk I/O, and memory performance metrics over a four-week period to establish a capacity baseline for a file server. Which Windows tool should be configured with User Defined Data Collector Sets?", "options": ["Task Manager, watching the Performance tab", "Resource Monitor, watching live handles", "Performance Monitor with a data collector set", "Event Viewer, filtered on the System log"], "answer": 2, "explanation": "Performance Monitor (`perfmon.msc` / `perfmon.exe`) is designed for long-term historical telemetry and performance auditing. It allows administrators to create Data Collector Sets that record selected performance counters (such as % Processor Time, Available MBytes, Disk Queue Length) into log files (.blg/.csv) over days, weeks, or months. Task Manager and Resource Monitor display live runtime data without long-term scheduled logging, and Event Viewer captures discrete system events rather than continuous numerical counter streams.", "distractor_analysis": {"0": "Task Manager shows the current moment only and keeps no history across four weeks.", "1": "Resource Monitor is also live. It logs nothing you can trend later.", "3": "Event Viewer records events, not sampled performance counters."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["performance-monitor", "perfmon", "counter-logs", "telemetry"], "id": "C2-019"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "hard", "question": "During a legacy BIOS boot sequence on a Windows workstation, the system BIOS executes POST and passes control to the MBR boot code, which executes BOOTMGR. Which operating system loader binary is executed NEXT by BOOTMGR to load the Windows kernel?", "options": ["`WINLOAD.EXE`", "`NTOSKRNL.EXE`", "`BOOTMGFW.EFI`", "`HAL.DLL`"], "answer": 2, "explanation": "In the legacy BIOS boot architecture, the Master Boot Record loads `BOOTMGR` (Windows Boot Manager), which reads the BCD store and launches `WINLOAD.EXE` (Windows OS Loader). `WINLOAD.EXE` then loads the Hardware Abstraction Layer (`HAL.DLL`), system registry hive, and the core Windows kernel (`NTOSKRNL.EXE`). On UEFI systems, `BOOTMGFW.EFI` and `WINLOAD.EFI` are used instead.", "distractor_analysis": {"0": "`HAL.DLL` is loaded by `WINLOAD.EXE` after `WINLOAD.EXE` starts executing, not directly by `BOOTMGR`.", "2": "`NTOSKRNL.EXE` (the Windows NT kernel) is initialized by `WINLOAD.EXE` after essential drivers are placed in memory.", "3": "`BOOTMGFW.EFI` is the UEFI EFI system partition boot manager binary, not a legacy BIOS loader."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["boot-process", "bootmgr", "winload", "bios-boot"], "id": "C2-020"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "A user needs to reboot their functional Windows 11 desktop directly into the Windows Recovery Environment (WinRE) to perform a System Image Recovery. How can this be initiated from the Windows Start menu?", "options": ["Pressing Ctrl + Alt + Delete twice in rapid succession", "Pressing the Windows Key + X and selecting Device Manager", "Pressing the F8 key rapidly during the vendor logo", "Holding down the Shift key while clicking 'Restart' in the Power menu"], "answer": 3, "explanation": "Holding down the Shift key while clicking 'Restart' from the Windows Start Power menu (or lock screen Power icon) bypasses standard restart and boots the machine directly into the Advanced Startup / Windows Recovery Environment (WinRE) menu. F8 is disabled by default on modern UEFI systems due to fast boot times, Ctrl+Alt+Del opens the security screen, and Win+X opens the Power User menu.", "distractor_analysis": {"0": "F8 legacy boot menu invocation is disabled by default in modern Windows 10/11 UEFI configurations.", "2": "Pressing Ctrl+Alt+Del opens the lock/sign-out security screen without entering WinRE.", "3": "Win+X opens the Quick Link administrative context menu to access tools like Disk Management and Device Manager."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["winre", "recovery", "windows-tools", "startup-options"], "id": "C2-021"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows workstation displays a blue recovery screen with error code 0xc000000f indicating the Boot Configuration Data (BCD) file is missing. In the WinRE Command Prompt, which `bootrec` command switch searches for Windows installations and prompts to add them to the BCD store?", "options": ["`bootrec /fixmbr`", "`bootrec /fixboot`", "`bootrec /rebuildbcd`", "`bootrec /scanos`"], "answer": 2, "explanation": "The `bootrec /rebuildbcd` command scans all attached storage drives for compatible Windows installations and interactively prompts the administrator to add them to the Boot Configuration Data (BCD) store. `/fixmbr` rewrites the master boot record, `/fixboot` writes a new partition boot sector, and `/scanos` lists installations without offering an interactive rebuild.", "distractor_analysis": {"0": "`/fixmbr` writes a standard MBR code to the system partition without touching the BCD database entries.", "1": "`/fixboot` writes a new boot sector to the system partition to fix damaged PBRs.", "3": "`/scanos` lists Windows installations not currently in the BCD, but does not rebuild or update the database."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["bootrec", "bcd", "command-line", "troubleshooting"], "id": "C2-022"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A developer needs to enable Windows Hyper-V and Windows Subsystem for Linux (WSL) on a Windows 11 Pro desktop. Where in Windows Settings can built-in optional components be turned on or off?", "options": ["Settings -> Network and Internet -> Proxy", "Settings -> Accounts -> Sign-in options", "Settings -> Apps -> Optional features -> More Windows features", "Settings -> Personalization -> Taskbar"], "answer": 2, "explanation": "Built-in Windows components and subsystems (such as Hyper-V, WSL, Windows Sandbox, Telnet Client, and IIS) are managed via Settings -> Apps -> Optional features -> 'More Windows features' (or `optionalfeatures.exe` in Control Panel). Taskbar settings customize the taskbar, Proxy configures network routing, and Sign-in options manages passwords and Windows Hello.", "distractor_analysis": {"1": "Taskbar personalization customizes taskbar alignment, corner icons, and search behavior.", "2": "Proxy settings manage web traffic routing and PAC script configuration for internet connectivity.", "3": "Sign-in options configures authentication mechanisms such as PINs, biometrics, and security keys."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-features", "features-on-demand", "optional-features", "hyper-v"], "id": "C2-023"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "easy", "question": "Which executable command opens the Microsoft Remote Desktop Connection client on Windows?", "options": ["`perfmon.exe`", "`mstsc.exe`", "`msra.exe`", "`resmon.exe`"], "answer": 3, "explanation": "`mstsc.exe` (Microsoft Terminal Services Client) launches the Remote Desktop Connection application, allowing users to initiate an RDP connection to remote servers and workstations. `msra.exe` launches Windows Remote Assistance, `resmon.exe` launches Resource Monitor, and `perfmon.exe` launches Performance Monitor.", "distractor_analysis": {"1": "`msra.exe` launches Windows Remote Assistance for interactive screen sharing and support sessions.", "2": "`resmon.exe` opens Resource Monitor to inspect real-time CPU, memory, disk, and network process utilization.", "3": "`perfmon.exe` opens Performance Monitor for performance counter graphing and data collector logging."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "rdp", "mstsc", "windows-tools"], "id": "C2-024"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "Which default file manager application in macOS is equivalent to File Explorer in Windows, allowing users to browse directories, manage files, and access mounted storage volumes?", "options": ["Time Machine", "Terminal", "Finder", "Spotlight"], "answer": 2, "explanation": "Finder is the default desktop graphical file manager and shell in Apple macOS, functioning identically to Windows File Explorer by providing file navigation, folder creation, search integration, and volume management. Spotlight is the system-wide search indexer, Time Machine is the automated backup utility, and Terminal is the CLI shell.", "distractor_analysis": {"1": "Spotlight (Command + Space) is the desktop search tool used to index and launch files, contacts, and calculations.", "2": "Time Machine is the native incremental backup utility for macOS that creates hourly/daily snapshots to external drives.", "3": "Terminal is the command-line interface application used to access the Zsh/Bash shell."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "finder", "file-management", "apple"], "id": "C2-025"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "easy", "question": "Which command in a Linux terminal displays the absolute path of the current working directory?", "options": ["`cd`", "`cat`", "`ls`", "`pwd`"], "answer": 3, "explanation": "The `pwd` (print working directory) command prints the complete absolute pathname of the current working directory to the terminal stdout. `ls` lists directory contents, `cd` changes the active directory, and `cat` concatenates and displays file contents.", "distractor_analysis": {"0": "`ls` lists files and subdirectories contained within the current directory.", "2": "`cd` navigates between directories in the filesystem hierarchy.", "3": "`cat` displays the text content of specified files on the screen."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "cli", "pwd", "navigation"], "id": "C2-026"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "A Linux administrator executes the command `chmod 755 script.sh`. What specific permission set is granted to the file's GROUP owner?", "options": ["Read and Execute (r-x)", "Read-only (r--)", "Read and Write (rw-)", "Read, Write, and Execute (rwx)"], "answer": 2, "explanation": "In standard Linux octal permissions, the three digits represent Owner (User), Group, and Others. The octal values are Read=4, Write=2, Execute=1. The second digit '5' represents the Group permissions: 4 + 1 = 5, which corresponds to Read and Execute (`r-x`). The owner receives 7 (`rwx`), and others receive 5 (`r-x`).", "distractor_analysis": {"0": "`rwx` corresponds to octal 7 (4+2+1), which is assigned to the file Owner.", "2": "`r--` corresponds to octal 4 (Read-only).", "3": "`rw-` corresponds to octal 6 (4+2), which lacks the execute bit."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "chmod", "permissions", "octal"], "id": "C2-027"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "hard", "question": "In a Linux operating system, which protected system file stores the encrypted password hashes for user accounts and is readable only by the root superuser?", "options": ["`/etc/group`", "`/etc/sudoers`", "`/etc/passwd`", "`/etc/shadow`"], "answer": 3, "explanation": "The `/etc/shadow` file contains encrypted password hashes (e.g., SHA-512) and password expiration parameters; it has strict permissions (`640` or `600`) and is readable exclusively by root. Historically, hashes were stored in `/etc/passwd`, but `/etc/passwd` must remain world-readable (`644`) for user ID to username mapping, so hashes were moved to `/etc/shadow` for security. `/etc/group` defines groups, and `/etc/sudoers` manages sudo privileges.", "distractor_analysis": {"0": "`/etc/passwd` is world-readable and stores account metadata (UID, GID, home directory, shell) with an 'x' placeholder for passwords.", "2": "`/etc/group` maps group names to group IDs and lists group memberships.", "3": "`/etc/sudoers` defines administrative privilege escalation rules for the `sudo` command."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "security", "shadow", "passwords"], "id": "C2-028"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "What is the correct two-step command sequence on Debian/Ubuntu Linux systems to refresh the local package repository index and then install available software updates?", "options": ["`sudo apt update` followed by `sudo apt upgrade`", "`dnf check-update` followed by `dnf upgrade`", "`yum check` followed by `yum clean`", "`apt install` followed by `apt upgrade`"], "answer": 2, "explanation": "On Debian/Ubuntu systems using Advanced Package Tool (APT), `sudo apt update` downloads the latest package lists and metadata from configured repositories, and `sudo apt upgrade` installs available newer versions of packages currently installed on the system. `dnf` and `yum` are used in Red Hat/Fedora/CentOS distributions.", "distractor_analysis": {"0": "`apt install` installs a specified package name; it does not refresh the repository index.", "2": "`dnf` is the package manager for Fedora and Red Hat Enterprise Linux, not Debian/Ubuntu.", "3": "`yum` is the legacy package manager for RHEL/CentOS systems."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "apt", "package-management", "debian"], "id": "C2-029"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "When a Linux system resolves a hostname to an IP address, which local static file is evaluated by default BEFORE querying upstream DNS servers?", "options": ["`/etc/fstab`", "`/etc/hostname`", "`/etc/resolv.conf`", "`/etc/hosts`"], "answer": 3, "explanation": "In Linux (and Unix/Windows systems), the `/etc/hosts` file contains static hostname-to-IP address mappings that are queried first by default according to the Name Service Switch configuration (`/etc/nsswitch.conf`). `/etc/resolv.conf` specifies upstream DNS nameserver IP addresses, `/etc/fstab` lists filesystem mount points, and `/etc/hostname` defines the machine's own system hostname.", "distractor_analysis": {"0": "`/etc/resolv.conf` defines upstream DNS server addresses used when local static `/etc/hosts` resolution fails.", "2": "`/etc/fstab` defines storage drive mount configurations and filesystem mount options.", "3": "`/etc/hostname` contains the system's assigned hostname string."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "hosts", "dns", "networking"], "id": "C2-030"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "hard", "question": "What is the correct field order for a standard five-field Linux `crontab` schedule entry from left to right?", "options": ["Minute, Hour, Day of Month, Month, Day of Week", "Day of Week, Minute, Hour, Day of Month, Month", "Month, Day of Month, Hour, Minute, Day of Week", "Hour, Minute, Day of Month, Month, Day of Week"], "answer": 2, "explanation": "A standard Linux crontab timing expression consists of 5 fields: 1. Minute (0-59), 2. Hour (0-23), 3. Day of Month (1-31), 4. Month (1-12), and 5. Day of Week (0-7, where 0 and 7 represent Sunday), followed by the command to execute. For example, `30 2 * * 1` runs at 02:30 AM every Monday.", "distractor_analysis": {"0": "Starting with Hour is incorrect; the first field is always Minute.", "2": "Starting with Day of Week is incorrect; Day of Week is the 5th and final timing field.", "3": "Month is the 4th field, not the first field."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "cron", "crontab", "scheduling"], "id": "C2-031"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "Which native backup and recovery utility built into Apple macOS automatically creates hourly, daily, and weekly snapshots to an external storage drive or network volume?", "options": ["Backup and Restore (Windows 7)", "Migration Assistant", "File History", "Time Machine"], "answer": 3, "explanation": "Time Machine is Apple's native automated backup solution included in macOS. It automatically maintains hourly backups for the past 24 hours, daily backups for the past month, and weekly backups for all previous months until storage space is full. File History and Backup & Restore are Windows backup utilities, and Migration Assistant transfers user accounts between computers.", "distractor_analysis": {"0": "File History is a Microsoft Windows continuous backup utility for user libraries.", "2": "Backup and Restore (Windows 7) is a legacy Windows imaging utility.", "3": "Migration Assistant is an Apple utility used to transfer accounts and data from an old Mac or PC to a new Mac."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "time-machine", "backup", "apple"], "id": "C2-032"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "Which file extension represents a mountable Apple Disk Image file commonly used to distribute macOS software packages?", "options": [".dmg", ".app", ".iso", ".pkg"], "answer": 2, "explanation": "In macOS, `.dmg` stands for Apple Disk Image, a mountable volume file format used to distribute applications and files over the internet. When opened, it mounts like a physical disk on the desktop. `.pkg` is an installer package containing installation scripts, `.app` is an executable application bundle, and `.iso` is an optical disk image standard.", "distractor_analysis": {"0": "`.pkg` is an Apple installer flat package file executed by the macOS Installer utility.", "2": "`.app` is a directory bundle containing executable binaries and application assets.", "3": "`.iso` is a cross-platform CD/DVD/Blu-ray optical disc image format."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "dmg", "disk-image", "apple"], "id": "C2-033"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "What is the default global keyboard shortcut to open the Spotlight search bar in macOS?", "options": ["Function + F3", "Command + R", "Command + Tab", "Command + Space"], "answer": 3, "explanation": "In macOS, pressing `Command + Space` (Cmd + Space) immediately invokes Spotlight search, allowing users to search local files, launch applications, perform calculations, and query Siri knowledge. Command + Tab switches active applications, F3 activates Mission Control, and Command + R reboots into macOS Recovery Mode.", "distractor_analysis": {"0": "Command + Tab opens the macOS Application Switcher to cycle between running apps.", "2": "F3 (or Mission Control key) displays an overview of all open desktop windows and spaces.", "3": "Command + R is held during Mac startup to boot into macOS Recovery Mode."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "spotlight", "shortcuts", "keyboard"], "id": "C2-034"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A threat actor crafts a sophisticated spear-phishing email targeting the Chief Technology Officer (CTO) to gain access to proprietary intellectual property. What specific term describes phishing directed at high-ranking corporate executives?", "options": ["Whaling", "Vishing", "Smishing", "Broad phishing"], "answer": 2, "explanation": "Whaling is a specialized, highly customized form of spear phishing that targets high-profile corporate executives (such as CEOs, CFOs, CTOs, and board members). Broad phishing casts a wide net with generic templates, vishing is voice phishing over the phone, and smishing is SMS-based mobile text phishing.", "distractor_analysis": {"0": "Broad phishing sends generic mass emails to thousands of indiscriminate recipients.", "2": "Vishing involves social engineering conducted via voice telephone calls.", "3": "Smishing uses mobile SMS text messages containing malicious links."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "whaling", "spear-phishing", "executives"], "id": "C2-035"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "An attacker pastes malicious adhesive QR codes over legitimate parking meter payment codes, redirecting scanning smartphone users to a fraudulent credit card payment portal. What attack vector is this?", "options": ["Pharming, DNS redirection to a lookalike site", "Vishing, phishing delivered over a voice call", "Smishing, phishing delivered over SMS text", "Quishing, phishing delivered through a QR code"], "answer": 3, "explanation": "Quishing (QR code phishing) uses malicious Quick Response (QR) codes in physical or digital locations that redirect mobile device users who scan the code to malicious phishing landing pages or malware download sites. Smishing uses SMS messages, pharming redirects DNS traffic, and vishing uses phone calls.", "distractor_analysis": {"0": "Smishing arrives as a text message. Here the lure is a printed code on the meter itself.", "2": "Pharming poisons name resolution so a correct address lands on a fake site. No DNS record was touched.", "3": "Vishing is a phone call using voice pressure, not a scanned image."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "quishing", "qr-code", "phishing"], "id": "C2-036"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "An employee holding a security badge openly allows an unbadged contractor to enter a secured facility door with them after the contractor asks them to hold the door. What term specifically describes entering WITH the employee's explicit consent?", "options": ["Piggybacking", "Shoulder surfing", "Pretexting", "Tailgating"], "answer": 2, "explanation": "In CompTIA physical security terminology, Piggybacking occurs when an unauthorized person enters a secure door with the explicit knowledge and consent of the authorized person (e.g., asking someone to hold the door). Tailgating occurs when the attacker slips in behind an authorized user WITHOUT their knowledge or consent. Shoulder surfing is visual eavesdropping, and pretexting is creating an invented scenario.", "distractor_analysis": {"0": "Tailgating involves following an authorized person through an open door covertly without their permission or consent.", "2": "Shoulder surfing is the act of looking over someone's shoulder to capture passwords or sensitive screen data.", "3": "Pretexting is crafting an elaborate fake backstory to manipulate a target into disclosing information."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "piggybacking", "tailgating", "physical-security"], "id": "C2-037"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which physical security barrier features two interlocking doors where the second door cannot be opened until the first door has completely closed and the occupant is authenticated?", "options": ["Crash-rated bollard", "Magnetometer", "Turnstile", "Access control vestibule (mantrap)"], "answer": 3, "explanation": "An access control vestibule (traditionally called a mantrap) consists of a secure enclosed space with two interlocking sets of doors. One door must close and lock before the opposite door will unlock upon validation, physically preventing tailgating and unauthorized multi-person entry. Turnstiles permit rotational single passage, bollards stop vehicle ramming, and magnetometers detect metal weapons.", "distractor_analysis": {"0": "Turnstiles are mechanical or optical barriers that rotate for one person but do not physically enclose the occupant between two interlocking doors.", "2": "Bollards are heavy vertical concrete or steel posts designed to prevent vehicles from ramming into building entrances.", "3": "Magnetometers are walk-through metal detection portals that detect ferromagnetic objects."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["physical-security", "mantrap", "access-control-vestibule", "datacenter"], "id": "C2-038"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "hard", "question": "Which cryptographic key exchange protocol is introduced in WPA3-Personal to replace the vulnerable WPA2 Pre-Shared Key (PSK) 4-way handshake?", "options": ["Simultaneous Authentication of Equals (SAE)", "Temporal Key Integrity Protocol (TKIP)", "Wired Equivalent Privacy (WEP)", "Pre-Shared Key (PSK)"], "answer": 2, "explanation": "WPA3-Personal mandates Simultaneous Authentication of Equals (SAE), a dragonfly key exchange protocol based on zero-knowledge proofs. SAE prevents offline dictionary and brute-force password-guessing attacks and provides forward secrecy. PSK is the older WPA2 method, and TKIP and WEP are broken legacy algorithms.", "distractor_analysis": {"0": "PSK (Pre-Shared Key) is the legacy WPA/WPA2 authentication scheme vulnerable to offline capture and dictionary cracking.", "2": "TKIP is an obsolete RC4-based wrapper protocol used in original WPA.", "3": "WEP is an insecure legacy 802.11 encryption standard broken by static key reuse."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa3", "sae", "authentication"], "id": "C2-039"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "What encryption standard and cipher mode was introduced in WPA2 to completely replace the vulnerable RC4-based TKIP encryption used in original WPA?", "options": ["DES-CBC", "Wi-Fi Protected Setup (WPS)", "RC4 stream cipher", "AES-CCMP"], "answer": 3, "explanation": "WPA2 introduced CCMP (Counter Mode Cipher Block Chaining Message Authentication Code Protocol), which utilizes the robust Advanced Encryption Standard (AES) cipher with 128-bit keys to replace the vulnerable RC4-based TKIP protocol. RC4 is cryptographically broken, DES is an obsolete 56-bit cipher, and WPS is a vulnerable PIN-based pairing feature.", "distractor_analysis": {"0": "RC4 is the underlying stream cipher in WEP and TKIP that AES-CCMP was designed to replace.", "2": "DES is an outdated symmetric encryption standard vulnerable to modern brute-force attacks.", "3": "WPS is an automated device connection protocol, not a symmetric encryption cipher suite."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa2", "aes-ccmp", "encryption"], "id": "C2-040"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "hard", "question": "A network engineer is configuring an 802.1X wireless authentication server. Which transport protocol and default UDP port are used for RADIUS authentication?", "options": ["UDP port 1812", "UDP port 88", "TCP port 389", "TCP port 49"], "answer": 2, "explanation": "RADIUS (Remote Authentication Dial-In User Service) uses UDP port 1812 for authentication and authorization and UDP port 1813 for accounting (legacy deployments use UDP 1645/1646). TCP port 49 is TACACS+, UDP port 88 is Kerberos, and TCP port 389 is LDAP.", "distractor_analysis": {"0": "TCP port 49 is used by TACACS+ for centralized network device administration.", "2": "UDP port 88 is used by the Kerberos authentication service in Active Directory.", "3": "TCP port 389 is used by the Lightweight Directory Access Protocol (LDAP)."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["authentication", "radius", "ports", "protocols"], "id": "C2-041"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "Which SOHO router feature allows IoT devices and game consoles to automatically configure port forwarding rules on the router firewall without administrative authorization, and should be DISABLED for security?", "options": ["Dynamic Host Configuration Protocol (DHCP)", "Network Address Translation (NAT)", "Quality of Service (QoS)", "Universal Plug and Play (UPnP)"], "answer": 3, "explanation": "Universal Plug and Play (UPnP) is designed to let networked devices (media players, cameras, game consoles) automatically open inbound ports on the router's firewall without requiring user intervention. Because malware can exploit UPnP to silently expose internal endpoints to the internet, security best practices mandate disabling UPnP on SOHO routers. QoS prioritizes bandwidth, DHCP assigns IP addresses, and NAT translates private IP addresses.", "distractor_analysis": {"0": "QoS prioritizes voice and video network packets to prevent latency, representing a safe traffic management feature.", "2": "DHCP automatically leases IP configurations to clients and is essential on LANs.", "3": "NAT allows multiple private IP devices to share a single public IP address at the router WAN boundary."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "upnp", "router-hardening", "port-forwarding"], "id": "C2-042"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "hard", "question": "A network share is configured with Share Permission: Read. The underlying NTFS permission on the target folder is set to: Full Control. When an authorized domain user accesses the folder remotely across the network, what is their effective permission?", "options": ["Read", "Modify", "No Access", "Full Control"], "answer": 2, "explanation": "When accessing files over the network, Windows evaluates both Share Permissions and NTFS Permissions. The effective permission is always the MOST RESTRICTIVE combination of the two. Between Share Permission (Read) and NTFS Permission (Full Control), the more restrictive permission is Read. Therefore, the user can only read files and cannot write, modify, or delete files across the network.", "distractor_analysis": {"0": "Full Control is blocked because the network share layer restricts the connection to Read-only access.", "2": "Modify requires write and delete permissions, which are denied by the Read share permission.", "3": "No Access (Deny) is not configured; the user has valid Read permissions."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["windows-permissions", "ntfs", "share-permissions", "effective-permissions"], "id": "C2-043"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "Which native Windows encryption technology provides granular, file-level and folder-level encryption tied to individual user account certificates on NTFS volumes?", "options": ["FileVault 2", "BitLocker To Go", "BitLocker Drive Encryption", "Encrypting File System (EFS)"], "answer": 3, "explanation": "Encrypting File System (EFS) is a feature of the NTFS file system that enables granular, transparent encryption of individual files and folders tied to the specific user's public key certificate. BitLocker encrypts entire disk volumes (block-level), BitLocker To Go encrypts removable USB drives, and FileVault 2 is the full-disk encryption system for Apple macOS.", "distractor_analysis": {"0": "BitLocker operates at the full volume level, encrypting entire disk partitions rather than individual user files.", "2": "FileVault 2 is Apple's full-disk volume encryption technology for macOS.", "3": "BitLocker To Go is used to encrypt entire removable USB flash drives and external hard drives."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["encryption", "efs", "bitlocker", "ntfs"], "id": "C2-044"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "Following the CompTIA 7-step malware removal process, what is the VERY FIRST action a technician must take immediately after investigating and verifying malware symptoms?", "options": ["Quarantine the infected system (disconnect from network)", "Update anti-malware signatures and scan", "Educate the end user", "Disable System Restore"], "answer": 2, "explanation": "Step 2 of the CompTIA 7-step malware removal methodology (immediately following Step 1: Identify and research malware symptoms) is to Quarantine the infected system by disconnecting all network cables, turning off Wi-Fi/Bluetooth, and isolating the device to prevent lateral malware propagation across the LAN. Disabling System Restore is Step 3, updating and scanning is Step 4, and educating the user is Step 7.", "distractor_analysis": {"0": "Disabling System Restore is Step 3 of the process and must only be performed after the host is safely isolated from the network.", "2": "Updating signatures and running remediation scans is Step 4 of the methodology.", "3": "Educating the end user is the 7th and final step performed after the system is fully cleansed and restored."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "methodology", "quarantine", "comptia-7-step"], "id": "C2-045"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "Why does the CompTIA malware removal methodology mandate disabling Windows System Restore BEFORE initiating remediation and anti-malware scans?", "options": ["To bypass User Account Control (UAC) prompts during scanning", "To increase physical RAM available to the antivirus engine", "To prevent the firewall from blocking outgoing updates", "To prevent infected files and registry keys from being saved into restore point snapshots that could reinfect the PC later"], "answer": 3, "explanation": "System Restore continuously archives system files, registry hives, and executables into Volume Shadow Copy snapshots. If an active malware infection is present, infected binaries can be saved into these snapshots. Disabling System Restore deletes all prior restore points, ensuring that reverting the system at a later date will not reintroduce the malware. It does not affect firewalls, UAC elevation, or RAM capacity.", "distractor_analysis": {"0": "System Restore operates on disk volume snapshots and has no interaction with Windows Defender Firewall rules.", "2": "UAC security elevation prompts are independent of the System Restore / Volume Shadow Copy service state.", "3": "Disabling System Restore purges disk snapshots and does not alter physical system RAM capacity."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "system-restore", "methodology", "remediation"], "id": "C2-046"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "hard", "question": "Which backup method copies all files that have been created or modified since the last FULL backup and does NOT clear the archive bit?", "options": ["Full backup", "Incremental backup", "Differential backup", "Synthetic full backup"], "answer": 2, "explanation": "A Differential backup copies all files that have changed since the last FULL backup and leaves the archive bit set (does NOT clear it). Because the archive bit remains untouched, each subsequent differential backup grows larger, capturing cumulative changes since the full backup. Full and Incremental backups clear the archive bit upon completion.", "distractor_analysis": {"0": "A Full backup copies all selected data regardless of status and CLEARS the archive bit.", "1": "An Incremental backup copies files changed since the last backup of any type and CLEARS the archive bit.", "3": "A Synthetic full merges incrementals into an existing full backup on the storage server."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-methods", "differential", "archive-bit", "backup-types"], "id": "C2-047"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "easy", "question": "The foundational 3-2-1 backup strategy mandates maintaining 3 total copies of data, stored on 2 different media types, with at least 1 copy stored where?", "options": ["Offsite (or in the cloud)", "On a legacy magnetic floppy disk", "Inside the same server room rack", "In an unencrypted local partition"], "answer": 2, "explanation": "The 3-2-1 backup rule requires: 3 copies of data (production copy + 2 backup copies), on 2 different storage media types (e.g., local disk SAN and tape or cloud), with 1 copy kept Offsite (or in an isolated cloud region) to ensure data survival against localized physical disasters (fire, flood, theft). Keeping copies in the same room or unencrypted partitions leaves data vulnerable to site destruction.", "distractor_analysis": {"0": "Storing backups on local unencrypted partitions offers zero disaster recovery protection if the physical machine is destroyed.", "2": "Floppy disks have minuscule storage capacity (1.44 MB) and are obsolete for enterprise backup.", "3": "Keeping all backup copies in the same room fails completely if the facility experiences a fire or flood."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-best-practices", "3-2-1-rule", "disaster-recovery", "offsite"], "id": "C2-048"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "medium", "question": "A technician is preparing decommissioned storage drives for data destruction. On which storage technology is magnetic degaussing COMPLETELY INEFFECTIVE?", "options": ["Magnetic LTO Tape Cartridges", "Solid-State Drives (SSDs and NVMe flash drives)", "Magnetic Floppy Disks", "Traditional Magnetic Hard Disk Drives (HDDs)"], "answer": 3, "explanation": "Degaussing uses a powerful magnetic field to erase magnetic domains on magnetic media (HDDs, tapes, floppy disks). Solid-State Drives (SSDs, NVMe drives, USB flash drives) store data as electrical charges trapped in silicon NAND flash memory cells, which are completely unaffected by magnetic fields. SSDs must be sanitized using cryptographic erase (Secure Erase) or physical shredding.", "distractor_analysis": {"0": "HDDs store data magnetically on platter coatings and are effectively sanitized and destroyed by degaussing.", "1": "Magnetic tapes rely on magnetic iron oxide/barium ferrite particles that are wiped completely by degaussers.", "3": "Floppy disks are magnetic media that are instantly erased when exposed to a degausser."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "degaussing", "ssd", "magnetic-media"], "id": "C2-049"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "medium", "question": "Which class of fire extinguisher is specifically designated for fighting fires involving energized electrical equipment such as servers, wiring, and circuit breakers?", "options": ["Class A (water-based)", "Class B (flammable liquids)", "Class C (energized electrical equipment)", "Class K (commercial cooking grease)"], "answer": 2, "explanation": "Class C fire extinguishers use non-conductive extinguishing agents (such as Carbon Dioxide [CO2], Halon alternatives, or dry chemical powder) specifically rated to safely extinguish fires on energized electrical equipment without shocking the operator. Class A is for ordinary combustibles (wood/paper), Class B is for flammable liquids, and Class K is for cooking oils.", "distractor_analysis": {"0": "Class A extinguishers use pressurized water, which conducts electricity and causes fatal shocks on live server equipment.", "1": "Class B extinguishers are rated for flammable liquids like gasoline, oil, and paint.", "3": "Class K extinguishers are wet chemical systems formulated for commercial kitchen deep fryers."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["fire-safety", "class-c", "extinguisher", "co2"], "id": "C2-050"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "A technician is tidying the automation share on a file server and has to sort scripts by interpreter before handing the folder to the automation team. Which file extension identifies a Microsoft PowerShell script?", "options": [".bat", ".cmd", ".ps1", ".vbs"], "answer": 2, "explanation": "PowerShell script files use the `.ps1` file extension. Windows Command Prompt batch files use `.bat` or `.cmd`, and VBScript files use `.vbs`. Python scripts use `.py`, and Bash shell scripts use `.sh`.", "distractor_analysis": {"0": "`.bat` is the legacy file extension for MS-DOS / Windows Command Prompt batch files.", "1": "`.cmd` is used for Windows NT Command Prompt scripts.", "3": "`.vbs` is the file extension for Microsoft Visual Basic Scripting Edition (VBScript) files."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "powershell", "file-extensions", "automation"], "id": "C2-051"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "Which file extension is used for traditional Windows Command Prompt batch scripts that execute command sequences in `cmd.exe`?", "options": [".sh", ".py", ".bat", ".ps1"], "answer": 2, "explanation": "Windows batch files executed by the Command Prompt (`cmd.exe`) use the `.bat` (or `.cmd`) file extension. `.ps1` is for PowerShell scripts, `.sh` is for Linux/Unix shell scripts, and `.py` is for Python source code.", "distractor_analysis": {"1": "`.ps1` is the file extension for Microsoft PowerShell scripts.", "2": "`.sh` is the file extension for Unix/Linux Bourne/Bash shell scripts.", "3": "`.py` is the file extension for Python script files."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "batch", "file-extensions", "cmd"], "id": "C2-052"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "Which file extension is universally used for Unix/Linux Bourne-Again Shell (Bash) script files?", "options": [".bat", ".ps1", ".sh", ".js"], "answer": 2, "explanation": "Linux and Unix shell scripts typically use the `.sh` file extension and begin with a shebang line (e.g., `#!/bin/bash`). `.bat` is for Windows batch scripts, `.ps1` is for PowerShell, and `.js` is for JavaScript files.", "distractor_analysis": {"0": "`.bat` is a Windows batch file extension.", "1": "`.ps1` is a Microsoft PowerShell script extension.", "3": "`.js` is a JavaScript source file extension."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "bash", "linux", "file-extensions"], "id": "C2-053"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "Which file extension identifies source code files written for the Python programming language?", "options": [".sh", ".vbs", ".py", ".ps1"], "answer": 2, "explanation": "Python source code scripts use the `.py` file extension and are executed by the Python interpreter runtime (`python script.py`). `.ps1` is for PowerShell, `.sh` is for Linux shell scripts, and `.vbs` is for VBScript.", "distractor_analysis": {"1": "`.ps1` is the file extension for PowerShell scripts.", "2": "`.sh` is the file extension for Unix/Linux Bash scripts.", "3": "`.vbs` is the file extension for Microsoft VBScript files."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "python", "file-extensions", "interpreted"], "id": "C2-054"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "Which file extension is used for legacy Microsoft Visual Basic Scripting Edition (VBScript) files executed by Windows Script Host (`wscript.exe` / `cscript.exe`)?", "options": [".py", ".vbs", ".ps1", ".bat"], "answer": 3, "explanation": "VBScript (Visual Basic Scripting Edition) files use the `.vbs` extension and are executed natively in Windows via the Windows Script Host engines (`cscript.exe` for console output or `wscript.exe` for GUI dialogs). `.ps1` is for modern PowerShell, `.bat` is for batch scripts, and `.py` is for Python.", "distractor_analysis": {"1": "`.ps1` is the file extension for Microsoft PowerShell.", "2": "`.bat` is the file extension for Command Prompt batch scripts.", "3": "`.py` is the file extension for Python scripts."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "vbscript", "file-extensions", "legacy"], "id": "C2-055"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A technician is troubleshooting video stuttering and 3D graphics rendering errors on a CAD workstation. Which Windows diagnostic tool tests DirectX display and sound acceleration and generates a detailed hardware report?", "options": ["`cleanmgr.exe`", "`eventvwr.msc`", "`dxdiag.exe`", "`msinfo32.exe`"], "answer": 2, "explanation": "The DirectX Diagnostic Tool (`dxdiag.exe`) tests video graphics display adapters, DirectDraw/Direct3D acceleration, audio sound devices, and game controllers, providing driver version details and diagnostic reporting. `msinfo32` provides broad system hardware summaries, `cleanmgr` runs Disk Cleanup, and `eventvwr` views Event Viewer logs.", "distractor_analysis": {"1": "`msinfo32.exe` provides system summaries and driver lists without executing interactive DirectX 3D graphics diagnostic tests.", "2": "`cleanmgr.exe` is the Windows Disk Cleanup utility used to delete temporary files and cached installer files.", "3": "`eventvwr.msc` displays Windows operating system and application event logs."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "dxdiag", "directx", "diagnostics"], "id": "C2-056"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "According to password security best practices and NIST guidelines, which policy combination creates the strongest protection against dictionary and brute-force password cracking attacks?", "options": ["Using the employee's username reversed as the password", "Enforcing long passphrases (15+ characters) with multifactor authentication (MFA)", "Requiring 6-character passwords changed every 7 days", "Allowing blank passwords for local administrator accounts"], "answer": 3, "explanation": "Modern password security guidelines (including NIST SP 800-63B) recommend long passphrases (15+ characters consisting of multiple words) combined with mandatory Multifactor Authentication (MFA). Length exponentially increases entropy, making offline cracking infeasible. Short passwords changed weekly cause user fatigue and predictable substitution patterns, blank passwords eliminate security entirely, and username-derived passwords are trivial to guess.", "distractor_analysis": {"1": "Short 6-character passwords have minuscule entropy and can be cracked in seconds regardless of weekly rotation schedules.", "2": "Blank passwords provide zero authentication protection and allow unauthenticated administrative logon.", "3": "Using reversed usernames is easily cracked by standard dictionary attack tools."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "password-complexity", "authentication", "gpo"], "id": "C2-057"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A small business deploys a Wi-Fi network using WPA2-Personal. What authentication method is used to authenticate client devices to the access point?", "options": ["An unencrypted open captive portal", "A TACACS+ authentication server", "A Pre-Shared Key (PSK) passphrase entered on each client", "A central RADIUS 802.1X server with digital certificates"], "answer": 2, "explanation": "WPA2-Personal (also called WPA2-PSK) uses a Pre-Shared Key (passphrase between 8 and 63 characters) entered into the router and shared with all connecting client devices to derive pairwise encryption keys. WPA2-Enterprise uses 802.1X with a RADIUS server, captive portals are used on public open networks, and TACACS+ is for network device administration.", "distractor_analysis": {"1": "RADIUS servers and digital certificates are utilized in WPA2/WPA3-Enterprise, not WPA2-Personal.", "2": "Captive portals on open networks authenticate web sessions without WPA2-Personal pre-shared keys.", "3": "TACACS+ is an administration protocol for switches and routers, not client WPA2-Personal Wi-Fi."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa2-personal", "pre-shared-key", "psk"], "id": "C2-058"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which control panel applet executable directly opens the System Properties dialog, allowing an administrator to change the computer name, workgroup, or domain membership?", "options": ["`firewall.cpl`", "`sysdm.cpl`", "`ncpa.cpl`", "`appwiz.cpl`"], "answer": 3, "explanation": "`sysdm.cpl` directly opens the System Properties dialog (Computer Name, Hardware, Advanced, System Protection, and Remote tabs), allowing administrators to rename the machine, join domains, or configure environment variables. `ncpa.cpl` opens Network Connections, `appwiz.cpl` opens Programs and Features, and `firewall.cpl` opens Windows Defender Firewall.", "distractor_analysis": {"1": "`ncpa.cpl` opens the Network Connections control panel applet to configure adapter IP addresses.", "2": "`appwiz.cpl` opens Programs and Features to uninstall or repair desktop applications.", "3": "`firewall.cpl` opens the Windows Defender Firewall configuration applet."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "system-properties", "sysdm", "computer-name"], "id": "C2-059"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "A network administrator needs to remotely manage a Linux server over an unencrypted public network. Which protocol provides an encrypted command-line interface session using TCP port 22?", "options": ["HTTP, unencrypted web transport on TCP 80", "FTP, cleartext file transfer on TCP 20 and 21", "SSH, an encrypted shell on TCP 22", "Telnet, a cleartext shell on TCP 23"], "answer": 2, "explanation": "Secure Shell (SSH) operates over TCP port 22 and provides strong cryptographic authentication (passwords or public/private key pairs) and end-to-end symmetric encryption for remote command-line sessions. Telnet (port 23) transmits credentials in cleartext plaintext, HTTP (port 80) is unencrypted web traffic, and FTP (port 21) is unencrypted file transfer.", "distractor_analysis": {"1": "Telnet gives a shell but sends the password in the clear, which is exactly what the public network rules out.", "2": "HTTP is a web protocol and is unencrypted. It provides no command-line session.", "3": "FTP transfers files in the clear and offers no interactive shell."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "ssh", "port-22", "security"], "id": "C2-060"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which Control Panel command launches the Programs and Features applet to uninstall or repair desktop applications in Windows?", "options": ["`powercfg.cpl`", "`appwiz.cpl`", "`sysdm.cpl`", "`ncpa.cpl`"], "answer": 3, "explanation": "`appwiz.cpl` opens the Programs and Features (Add/Remove Programs) applet, which lists all installed software, allows uninstalling or repairing applications, and links to 'Turn Windows features on or off'. `sysdm.cpl` is System Properties, `ncpa.cpl` is Network Connections, and `powercfg.cpl` is Power Options.", "distractor_analysis": {"1": "`sysdm.cpl` opens System Properties to manage computer name, domain join, and paging files.", "2": "`ncpa.cpl` opens Network Connections to view and configure network interface adapters.", "3": "`powercfg.cpl` opens Power Options to configure sleep timers and battery plans."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "appwiz", "programs-and-features", "uninstall"], "id": "C2-061"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "hard", "question": "An intelligence agency mandates the permanent physical destruction of magnetic hard drives containing top-secret data. Which method guarantees complete physical destruction of the storage media platters?", "options": ["Deleting all partitions in Disk Management", "Overwriting the drive with a single pass of zeroes", "Industrial mechanical shredding / incineration", "Performing a standard NTFS Full Format"], "answer": 2, "explanation": "For top-secret and highly classified data, physical destruction (industrial cross-cut shredding, disintegration, degaussing followed by crushing, or incineration in a certified smelting furnace) physically destroys the drive platters, making data recovery mathematically and physically impossible. Formatting, partition deletion, and single-pass overwriting leave data vulnerable to specialized laboratory recovery techniques.", "distractor_analysis": {"1": "A Full Format overwrites sectors with zeroes on a functioning drive but does not destroy the physical hardware or protect bad sectors.", "2": "Deleting partitions merely removes partition table records from sector 0, leaving all raw data blocks intact.", "3": "Single-pass zero fills do not meet high-security classified data destruction standards."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "shredding", "incineration", "physical-destruction"], "id": "C2-062"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which command-line shortcut directly opens the Network Connections control panel window displaying all physical and virtual network adapters in Windows?", "options": ["`desk.cpl`", "`ncpa.cpl`", "`sysdm.cpl`", "`appwiz.cpl`"], "answer": 3, "explanation": "`ncpa.cpl` (Network Control Panel Applet) opens the Network Connections window, where technicians can view, enable, disable, rename, and configure properties (IP addresses, DNS, subnet masks, gateway) for all Ethernet, Wi-Fi, and virtual adapters. `sysdm.cpl` opens System Properties, `appwiz.cpl` opens Programs and Features, and `desk.cpl` opens Display Settings.", "distractor_analysis": {"1": "`sysdm.cpl` opens the System Properties dialog for computer naming and domain joins.", "2": "`appwiz.cpl` opens the Programs and Features window to manage application installations.", "3": "`desk.cpl` opens the legacy Display properties configuration window."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "ncpa", "network-connections", "cpl"], "id": "C2-063"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which Control Panel command launches the Power Options management applet to configure sleep timers, screen turn-off intervals, and power button behaviors?", "options": ["`sysdm.cpl`", "`inetcpl.cpl`", "`powercfg.cpl`", "`ncpa.cpl`"], "answer": 2, "explanation": "`powercfg.cpl` opens the Power Options control panel applet, allowing users and technicians to select power plans (Balanced, High Performance, Power Saver), configure display sleep timeouts, and define power button actions. `ncpa.cpl` is Network Connections, `sysdm.cpl` is System Properties, and `inetcpl.cpl` is Internet Options.", "distractor_analysis": {"1": "`ncpa.cpl` opens Network Connections to configure network interface adapters.", "2": "`sysdm.cpl` opens System Properties for domain membership and hardware settings.", "3": "`inetcpl.cpl` opens Internet Properties to configure proxy settings and browser security zones."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "powercfg", "power-options", "energy"], "id": "C2-064"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which command launches the Internet Properties applet, used to configure browser security zones, proxy server settings, and SSL/TLS cipher suites in Windows?", "options": ["`appwiz.cpl`", "`inetcpl.cpl`", "`ncpa.cpl`", "`sysdm.cpl`"], "answer": 3, "explanation": "`inetcpl.cpl` launches the Internet Properties configuration dialog. Technicians use this applet to configure LAN proxy servers, manage browser security zones (Internet, Local Intranet, Trusted Sites, Restricted Sites), manage saved certificates, and enable/disable TLS 1.2/1.3 protocol versions. `ncpa.cpl` is Network Connections, `sysdm.cpl` is System Properties, and `appwiz.cpl` is Programs and Features.", "distractor_analysis": {"1": "`ncpa.cpl` manages network interface card adapter settings and IPv4/IPv6 addresses.", "2": "`sysdm.cpl` manages computer name, domain join, and system properties.", "3": "`appwiz.cpl` manages desktop application installations and uninstalls."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-tools", "inetcpl", "internet-options", "proxy"], "id": "C2-065"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician updates a company's internal DNS record, but a client workstation continues attempting to connect to the obsolete IP address. Which command purges the local Windows DNS client resolver cache?", "options": ["`ipconfig /renew`", "`ipconfig /registerdns`", "`ipconfig /flushdns`", "`ipconfig /release`"], "answer": 2, "explanation": "The `ipconfig /flushdns` command immediately clears and purges the local DNS client resolver cache in Windows. This forces the operating system to send fresh DNS queries to the configured DNS server rather than relying on stale cached name-to-IP mappings. `/release` drops the DHCP lease, `/renew` requests a new DHCP lease, and `/registerdns` refreshes DNS registrations for the local host.", "distractor_analysis": {"1": "`ipconfig /release` releases the current DHCP IP address lease from the network interface.", "2": "`ipconfig /renew` requests a renewed DHCP lease from the local DHCP server.", "3": "`ipconfig /registerdns` initiates manual dynamic registration for the DNS names and IP addresses configured on the computer."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "ipconfig", "dns", "flushdns"], "id": "C2-066"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "Which command-line diagnostic tool sends ICMP Echo Request packets to a remote host to test basic network connectivity and measure round-trip latency?", "options": ["`netstat`", "`ping`", "`tracert`", "`nslookup`"], "answer": 3, "explanation": "`ping` sends ICMP Echo Request messages to an IP address or hostname and listens for ICMP Echo Reply packets, testing layer 3 connectivity and measuring packet loss and round-trip delay time in milliseconds. `tracert` maps the hop-by-hop path, `nslookup` queries DNS servers, and `netstat` displays active network socket connections.", "distractor_analysis": {"1": "`tracert` traces the route that packets take across intermediary routers to reach a destination host.", "2": "`nslookup` queries DNS name servers to resolve domain names to IP addresses.", "3": "`netstat` displays active TCP connections, listening ports, and protocol statistics."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "ping", "icmp", "connectivity"], "id": "C2-067"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to identify which specific router along a wide area network (WAN) path is dropping packets and causing connection failures. Which diagnostic utility displays the route and transit delay of each hop across the network?", "options": ["`ipconfig`", "`netstat`", "`tracert`", "`ping`"], "answer": 2, "explanation": "`tracert` (Trace Route) uses ICMP Echo Requests with incrementally increasing Time-to-Live (TTL) values to map the path taken by packets across all intermediate routers (hops) to a destination, displaying each router's IP address and latency. `ping` only tests end-to-end reachability, `ipconfig` displays local network adapter settings, and `netstat` shows active sockets.", "distractor_analysis": {"1": "`ping` verifies basic connectivity to a destination but cannot identify which intermediate router hop along the path is failing.", "2": "`ipconfig` shows local IP address, subnet mask, default gateway, and DNS configuration on the local machine.", "3": "`netstat` lists active inbound and outbound network connections and listening ports on the local host."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "tracert", "routing", "hops"], "id": "C2-068"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "Which command-line utility is used by systems administrators to query Domain Name System (DNS) servers to resolve hostnames, verify MX records, and troubleshoot DNS delegation?", "options": ["`netstat`", "`nslookup`", "`ipconfig`", "`ping`"], "answer": 3, "explanation": "`nslookup` (Name Server Lookup) queries DNS servers directly to inspect DNS records (A, AAAA, MX, CNAME, PTR, TXT) and verify that the nameserver is resolving names accurately. `ipconfig` manages local IP leases, `ping` tests ICMP reachability, and `netstat` monitors local network sockets.", "distractor_analysis": {"1": "`ipconfig` displays local network interface configuration and manages DHCP leases.", "2": "`ping` sends ICMP Echo requests to test layer 3 reachability.", "3": "`netstat` displays active TCP/UDP ports, connection states, and Ethernet interface statistics."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "nslookup", "dns", "records"], "id": "C2-069"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A security analyst needs to list all active TCP connections, listening ports, and the numerical IP addresses and port numbers on a Windows server. Which command should be executed?", "options": ["`tracert -d`", "`route print`", "`netstat -an`", "`ipconfig /all`"], "answer": 2, "explanation": "The `netstat -an` command displays all active network connections and listening ports (`-a`) in numerical format without attempting to resolve hostnames or well-known port names (`-n`), providing a clear snapshot of open network sockets. `ipconfig /all` shows full adapter settings, `tracert -d` traces hops without DNS resolution, and `route print` displays the local routing table.", "distractor_analysis": {"1": "`ipconfig /all` lists detailed local network adapter parameters (MAC address, DHCP server, lease dates) but not active socket connections.", "2": "`tracert -d` traces router hops to a remote destination without resolving router IP addresses to names.", "3": "`route print` displays the local IP routing table and active route entries."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "netstat", "listening-ports", "sockets"], "id": "C2-070"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "In a multifactor authentication (MFA) scheme, which item belongs strictly to the 'Something You Have' (possession) category?", "options": ["The user's physical geographic GPS location", "A hardware smart card (PIV card) or hardware OTP token", "A complex 16-character alphanumeric password", "A biometric retina scan"], "answer": 3, "explanation": "In authentication factor classification: 'Something you have' represents physical possession items (smart cards, hardware tokens, smartphone authenticator app keys, USB FIDO security keys). Passwords and PINs are 'Something you know', retina scans and fingerprints are 'Something you are', and GPS coordinates represent 'Somewhere you are'.", "distractor_analysis": {"1": "Passwords and PINs belong to the 'Something you know' (knowledge) factor.", "2": "Retina scans, facial recognition, and fingerprints belong to the 'Something you are' (biometric) factor.", "3": "GPS coordinates and IP subnet geolocation belong to the 'Somewhere you are' (location) factor."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "mfa", "something-you-have", "authentication"], "id": "C2-071"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which authentication factor category encompasses physiological and behavioral characteristics such as fingerprints, facial geometry, and iris scans?", "options": ["Something you have", "Somewhere you are", "Something you are", "Something you know"], "answer": 2, "explanation": "'Something you are' refers to biometric authentication factors based on unique human biological or behavioral traits, including fingerprints, facial recognition, iris/retina patterns, voiceprints, and keystroke dynamics. 'Something you know' is knowledge (passwords), 'Something you have' is possession (smart cards), and 'Somewhere you are' is location.", "distractor_analysis": {"1": "'Something you know' involves memorized knowledge such as passwords, passphrases, and security PINs.", "2": "'Something you have' involves physical possession of smart cards, tokens, or security keys.", "3": "'Somewhere you are' involves physical geographic or network location verification."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["authentication", "biometrics", "something-you-are", "security"], "id": "C2-072"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "Which authentication credential represents a 'Something You Know' factor in access control security?", "options": ["A smart badge with RFID chip", "A memorized PIN code or password", "A hardware USB security key", "A fingerprint scan"], "answer": 3, "explanation": "'Something you know' consists of information that the user memorizes and enters during authentication, such as passwords, passphrases, PINs, and answers to secret security questions. Hardware keys and RFID badges are 'Something you have', and fingerprints are 'Something you are'.", "distractor_analysis": {"1": "A hardware USB security key is a physical possession factor ('Something you have').", "2": "A fingerprint scan is a biometric factor ('Something you are').", "3": "An RFID smart badge is a physical possession factor ('Something you have')."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "authentication", "something-you-know", "pin"], "id": "C2-073"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A scammer calls an employee pretending to be a bank fraud investigator and attempts to trick the employee into reading a one-time verification code over the telephone. What specific social engineering attack is taking place?", "options": ["Shoulder surfing", "Dumpster diving", "Vishing (Voice phishing)", "Smishing"], "answer": 2, "explanation": "Vishing (Voice phishing) is the fraudulent practice of conducting social engineering attacks over voice telephone calls or VoIP systems to deceive victims into revealing sensitive financial data, passwords, or MFA codes. Smishing uses SMS text messages, shoulder surfing is visual eavesdropping, and dumpster diving searches physical trash.", "distractor_analysis": {"1": "Smishing is social engineering conducted via cellular SMS text messaging.", "2": "Shoulder surfing involves looking at a user's screen or keyboard to steal passwords.", "3": "Dumpster diving searches waste bins for discarded documents or hardware."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "vishing", "voice-phishing", "attacks"], "id": "C2-074"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "An employee receives a mobile text message claiming a package delivery failed and providing a link to 'reschedule delivery' that prompts for personal credit card information. What attack type is this?", "options": ["Watering hole attack", "Smishing (SMS phishing)", "Vishing", "Tailgating"], "answer": 3, "explanation": "Smishing (SMS phishing) is social engineering delivered through mobile SMS/MMS text messages containing deceptive links designed to harvest credentials or steal credit card data. Vishing takes place over voice telephone calls, tailgating is physical door following, and watering hole attacks compromise legitimate industry websites.", "distractor_analysis": {"1": "Vishing involves voice phone calls rather than text messages.", "2": "Tailgating is an unauthorized physical entry tactic through building doors.", "3": "A watering hole attack compromises industry websites frequented by targeted organizations."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "smishing", "sms-phishing", "mobile-threats"], "id": "C2-075"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A system administrator needs to partition a new 6 TB storage volume on a Windows Server. Which partition style must be chosen to utilize the full 6 TB capacity as a single contiguous volume?", "options": ["GPT (GUID Partition Table)", "FAT32 partition scheme", "Dynamic Extended Volume (DEV)", "MBR (Master Boot Record)"], "answer": 2, "explanation": "GUID Partition Table (GPT) uses 64-bit logical block addressing and supports disk capacities up to 9.4 ZB (zettabytes) and up to 128 primary partitions in Windows. In contrast, legacy MBR is capped at 2.2 TB due to 32-bit sector addressing. FAT32 has a 4 GB file size limit, and DEV is a non-standard acronym.", "distractor_analysis": {"0": "MBR uses 32-bit sector addressing and cannot address storage capacity beyond 2.2 TB.", "2": "FAT32 is a legacy file system with a 32 GB volume creation limit in Windows and 4 GB file size ceiling.", "3": "Dynamic Extended Volume is a distractor term; GPT is the required modern partition style."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["partitioning", "gpt", "large-drives", "storage"], "id": "C2-076"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "An IT technician is preparing to install Windows 11 Pro on newly assembled desktop hardware. What firmware mode and security hardware must be enabled in the BIOS/UEFI configuration?", "options": ["Legacy MBR boot mode with BitLocker bypass", "AHCI mode with CSM active and Secure Boot disabled", "Legacy BIOS mode with CSM enabled", "UEFI mode with Secure Boot enabled and TPM 2.0 active"], "answer": 3, "explanation": "Windows 11 mandates UEFI firmware with Secure Boot capability enabled and an active Trusted Platform Module (TPM) version 2.0 for hardware-rooted security features like BitLocker, Credential Guard, and Windows Hello. Legacy BIOS and CSM (Compatibility Support Module) are obsolete and unsupported for Windows 11.", "distractor_analysis": {"0": "Legacy BIOS and CSM bypass UEFI security checks and are incompatible with Windows 11 system requirements.", "2": "Windows 11 requires UEFI and GPT partitioning; MBR boot is not supported.", "3": "Disabling Secure Boot and enabling CSM prevents Windows 11 from passing pre-installation hardware verification."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-11", "system-requirements", "uefi", "tpm"], "id": "C2-077"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "easy", "question": "A technician needs to deploy Windows across 50 workstations simultaneously over the local datacenter subnet without inserting physical USB media into each system. Which technology allows systems to boot an OS installer from the network?", "options": ["Windows To Go", "Internal DVD-ROM drive", "PXE (Preboot Execution Environment)", "FAT32 USB installer"], "answer": 2, "explanation": "Preboot Execution Environment (PXE) allows network interface cards (NICs) to retrieve an IP address via DHCP and download boot files via TFTP from a network deployment server (such as WDS or MECM/SCCM). This enables bare-metal automated OS imaging without local physical installation media.", "distractor_analysis": {"1": "FAT32 USB installers require physical technician touch on every individual machine.", "2": "Windows To Go runs a portable Windows workspace from a certified USB drive, rather than performing network OS imaging.", "3": "Optical DVD-ROMs require local disc loading and are too slow for mass workstation deployments."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["deployment", "pxe", "network-boot", "wds"], "id": "C2-078"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "Which Windows command-line utility scans the integrity of all protected system files and replaces damaged or missing operating system DLLs with correct Microsoft versions?", "options": ["`diskpart /clean`", "`bootrec /fixboot`", "`chkdsk /f`", "`sfc /scannow`"], "answer": 3, "explanation": "The System File Checker (`sfc /scannow`) scans all protected Windows system files and verifies their digital signatures against cached backups in the component store, automatically repairing missing or corrupted operating system files. `chkdsk` repairs disk sectors, `diskpart` manages partitions, and `bootrec` repairs boot records.", "distractor_analysis": {"0": "`chkdsk /f` fixes file system metadata and directory structures on disk volumes, not corrupted operating system DLLs.", "2": "`diskpart /clean` wipes partition configuration from a target drive.", "3": "`bootrec /fixboot` writes a new partition boot sector to the system partition."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "sfc", "system-integrity", "command-line"], "id": "C2-079"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to verify which Group Policy Objects (GPOs) are currently applied to a domain-joined computer and logged-in user to diagnose an access issue. Which command displays this information?", "options": ["`gpresult /r`", "`secpol.msc`", "`net user /domain`", "`gpupdate /force`"], "answer": 2, "explanation": "The `gpresult /r` command outputs a detailed Resultant Set of Policy (RSoP) summary in the console, listing applied GPOs, security group memberships, and filtering status for both the computer and user. `gpupdate /force` reapplies policy, `secpol.msc` manages local policy, and `net user` inspects user account properties.", "distractor_analysis": {"0": "`gpupdate /force` refreshes Group Policy from domain controllers but does not display an RSoP report.", "2": "`secpol.msc` opens the GUI Local Security Policy editor on the local machine.", "3": "`net user /domain` displays account properties from Active Directory rather than applied GPO hierarchies."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "gpresult", "group-policy", "rsop"], "id": "C2-080"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to schedule an automated daily file copy that mirrors an entire source directory to a backup drive, resumes interrupted transfers, and preserves NTFS permissions. Which command should be used?", "options": ["`xcopy C:\\Data D:\\Backup /s`", "`robocopy C:\\Data D:\\Backup /mir /z`", "`move C:\\Data D:\\Backup`", "`copy /y *.* D:\\Backup`"], "answer": 3, "explanation": "`robocopy` with the `/mir` switch mirrors a directory tree (equivalent to `/e` plus deleting destination files no longer in source) and `/z` enables restartable mode across network interruptions. Standard `copy`, `xcopy`, and `move` lack robust network resumption and complete directory mirroring logic.", "distractor_analysis": {"0": "`copy` lacks subdirectory recursion and cannot resume interrupted large network file transfers.", "1": "`xcopy /s` copies directories but skips empty folders and does not purge deleted files like `/mir`.", "3": "`move` deletes source files after transfer instead of creating an ongoing backup replica."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "robocopy", "mir", "replication"], "id": "C2-081"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "Which Microsoft Management Console (.msc) snap-in is used on Windows Pro to create local user accounts, reset local passwords, and manage local security groups?", "options": ["`lusrmgr.msc`", "`services.msc`", "`compmgmt.msc`", "`dsa.msc`"], "answer": 2, "explanation": "`lusrmgr.msc` directly opens the Local Users and Groups console. `dsa.msc` is Active Directory Users and Computers (for domain controllers), `services.msc` manages background services, and `compmgmt.msc` opens Computer Management (which contains lusrmgr along with other tools).", "distractor_analysis": {"0": "`dsa.msc` manages Active Directory domain objects and is not installed on standard standalone clients.", "2": "`services.msc` manages background Windows system services and startup types.", "3": "`compmgmt.msc` is the container console that hosts multiple snap-ins, whereas `lusrmgr.msc` is the dedicated local user tool."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["mmc", "lusrmgr", "user-management", "snap-in"], "id": "C2-082"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "Which Windows Registry root key stores configuration settings, desktop appearance options, and software preferences specific to the currently logged-on user?", "options": ["`HKEY_LOCAL_MACHINE (HKLM)`", "`HKEY_CLASSES_ROOT (HKCR)`", "`HKEY_CURRENT_USER (HKCU)`", "`HKEY_CURRENT_CONFIG (HKCC)`"], "answer": 2, "explanation": "`HKEY_CURRENT_USER (HKCU)` stores configuration settings for the currently logged-on user, dynamically loaded from the user's `NTUSER.DAT` file. `HKLM` stores system-wide settings applicable to all users, `HKCR` handles file associations and COM classes, and `HKCC` points to runtime hardware profiles.", "distractor_analysis": {"0": "`HKLM` contains machine-wide settings and hardware configurations shared across all user profiles.", "1": "`HKCR` manages file type extensions, OLE registrations, and COM object mappings.", "3": "`HKCC` contains runtime hardware configuration pointers linked from `HKLM\\SYSTEM`."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["registry", "hkcu", "hklm", "user-hive"], "id": "C2-083"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "A Linux administrator needs to change the ownership of a file named `report.txt` so that the user `datacenter_admin` is the owner and the group `sysadmins` is the group owner. Which command executes this?", "options": ["`chown datacenter_admin:sysadmins report.txt`", "`chgrp root report.txt`", "`passwd datacenter_admin report.txt`", "`chmod 777 report.txt`"], "answer": 2, "explanation": "The `chown` (change owner) command with the syntax `user:group filename` changes both the user owner and group owner simultaneously. `chmod` alters file permission bits (read/write/execute), `chgrp` changes only the group, and `passwd` updates user account passwords.", "distractor_analysis": {"0": "`chmod 777` grants full read, write, and execute permissions to all users without changing file ownership.", "2": "`chgrp root` only modifies the group owner to root without setting the user owner.", "3": "`passwd` modifies user account passwords, not file ownership metadata."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "chown", "ownership", "cli"], "id": "C2-084"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "In Linux, what permissions are granted to the file owner, group owner, and others when a file has permissions set to `chmod 754 data.csv`?", "options": ["Owner: rw-, Group: r--, Others: ---", "Owner: rwx, Group: r-x, Others: r--", "Owner: r-x, Group: rwx, Others: --x", "Owner: rwx, Group: rw-, Others: r--"], "answer": 3, "explanation": "Octal permissions in Linux calculate Read=4, Write=2, Execute=1. The first digit '7' (4+2+1) grants the Owner Read, Write, and Execute (`rwx`). The second digit '5' (4+1) grants the Group Read and Execute (`r-x`). The third digit '4' (4) grants Others Read-only (`r--`).", "distractor_analysis": {"1": "This reverses owner and group values and misinterprets the octal digits 7, 5, and 4.", "2": "Group 'rw-' corresponds to octal 6 (4+2), not 5 (4+1).", "3": "Owner 'rw-' corresponds to octal 6 (4+2), not 7 (4+2+1)."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "permissions", "chmod", "octal"], "id": "C2-085"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "A technician needs to search through a 500 MB Apache server log file (`/var/log/apache2/access.log`) in Linux and output only lines containing the IP address `192.168.1.105`. Which command is BEST?", "options": ["`grep '192.168.1.105' /var/log/apache2/access.log`", "`cat /var/log/apache2/access.log`", "`ls -la /var/log/apache2/access.log`", "`find /var/log/apache2/access.log -name '192.168.1.105'`"], "answer": 2, "explanation": "`grep` (Global Regular Expression Print) searches inside text files line by line and displays matching patterns (such as IP addresses). `find` searches directory structures for filenames/metadata, `cat` dumps the entire 500 MB file to the screen without filtering, and `ls` only lists file directory attributes.", "distractor_analysis": {"0": "`find` locates files in the directory tree based on filenames or attributes, rather than searching file contents.", "2": "`cat` dumps the entire 500 MB file to terminal output without performing pattern matching.", "3": "`ls -la` displays file permissions, size, and date metadata without reading file content."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "grep", "log-analysis", "cli"], "id": "C2-086"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "Which native macOS utility is used to perform automated incremental backups to an external Thunderbolt drive or network share, allowing users to restore previous versions of files?", "options": ["Boot Camp Assistant", "Mission Control", "Disk Utility", "Time Machine"], "answer": 3, "explanation": "Time Machine is the built-in backup mechanism in macOS that creates hourly snapshots of modified files to external or network storage. Disk Utility manages formatting and partitions, Boot Camp Assistant partitions drives for dual-booting Windows on Intel Macs, and Mission Control provides window management.", "distractor_analysis": {"0": "Disk Utility performs disk partitioning, formatting, and First Aid filesystem repairs.", "2": "Boot Camp Assistant is used on Intel-based Macs to configure dual-boot Windows installations.", "3": "Mission Control provides a visual overview of open windows, desktop spaces, and full-screen apps."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "time-machine", "backup", "apple"], "id": "C2-087"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "medium", "question": "Which macOS management utility is used to securely store and manage user passwords, private encryption keys, Wi-Fi network credentials, and digital certificates?", "options": ["Activity Monitor", "Console", "Keychain Access", "Terminal"], "answer": 2, "explanation": "Keychain Access is Apple's built-in password and credential management subsystem in macOS. It encrypts passwords, digital certificates, private keys, and secure notes. Terminal provides CLI shell access, Activity Monitor tracks CPU/RAM usage, and Console views system logs.", "distractor_analysis": {"1": "Terminal opens the command-line interface for running Zsh/Bash shell commands.", "2": "Activity Monitor is the macOS equivalent of Windows Task Manager for monitoring processes and resource usage.", "3": "Console is the macOS log viewer used to inspect system diagnostic messages and crash reports."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "keychain", "passwords", "security"], "id": "C2-088"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A user on Windows 11 Pro wants to connect to their office workstation from home using Microsoft Remote Desktop. Which configuration setting must be enabled on the office workstation?", "options": ["Telnet Client must be turned on in Windows Features", "The computer must be demoted to a Workgroup", "Remote Assistance must be requested via email", "Remote Desktop must be enabled in Settings -> System -> Remote Desktop"], "answer": 3, "explanation": "In Windows Pro/Enterprise, inbound RDP connections require explicitly turning on 'Remote Desktop' under Settings -> System -> Remote Desktop (or System Properties -> Remote tab). This starts the Remote Desktop Service and automatically configures inbound firewall rules on TCP port 3389. Remote Assistance requires user invitation, Telnet is an unencrypted CLI, and domain membership supports RDP.", "distractor_analysis": {"0": "Remote Assistance is an interactive screen-sharing tool requiring an active user invitation, not unattended RDP.", "2": "Telnet is an insecure plaintext CLI protocol and is not used by Microsoft Remote Desktop.", "3": "Active Directory domain membership fully supports RDP authentication and does not need to be removed."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["remote-desktop", "rdp", "windows-pro", "system-settings"], "id": "C2-089"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to forcibly terminate a frozen background process with Process ID (PID) 4820 and all of its child processes from Command Prompt. Which command achieves this?", "options": ["`taskkill /PID 4820 /F /T`", "`tasklist /PID 4820 /close`", "`shutdown /p /f 4820`", "`kill -9 4820`"], "answer": 2, "explanation": "In Windows, `taskkill /PID 4820 /F /T` terminates the process with PID 4820. The `/F` switch specifies forceful termination, and `/T` terminates the process along with any child processes it spawned (process tree termination). `kill` is a Linux command, `tasklist` only lists processes, and `shutdown` restarts or powers off the computer.", "distractor_analysis": {"0": "`kill -9` is the Unix/Linux command to send a SIGKILL signal to a PID, not a native Windows command.", "2": "`tasklist` displays running processes and PIDs but cannot terminate them.", "3": "`shutdown` is used for operating system reboot and power control, not individual process termination."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "taskkill", "process-management", "troubleshooting"], "id": "C2-090"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to view active network connections, listening ports, process IDs (PIDs), AND the executable binary name responsible for each connection. Which command should be executed?", "options": ["`ping -t 127.0.0.1`", "`netstat -b -ano`", "`ipconfig /all`", "`tracert -h 30`"], "answer": 3, "explanation": "In Windows, `netstat -b -ano` displays all active connections and listening ports (`-a`), numerical addresses/ports (`-n`), owning Process ID (`-o`), and the executable component name (`-b`, requires administrative elevation). `ipconfig` displays adapter settings, `tracert` traces router hops, and `ping -t` performs continuous reachability tests.", "distractor_analysis": {"1": "`ipconfig /all` lists MAC addresses, DHCP lease dates, and DNS servers, but not active socket connections.", "2": "`tracert -h 30` traces router hops up to a maximum of 30 hops.", "3": "`ping -t 127.0.0.1` pings the local loopback adapter continuously until interrupted."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "netstat", "listening-ports", "network-troubleshooting"], "id": "C2-091"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "medium", "question": "Which Windows tool allows a technician to configure diagnostic startup modes, perform a clean boot by disabling non-Microsoft services, and edit boot parameter flags?", "options": ["`regedit` (Registry Editor)", "`cleanmgr` (Disk Cleanup)", "`msconfig` (System Configuration)", "`dxdiag` (DirectX Diagnostic Tool)"], "answer": 2, "explanation": "System Configuration (`msconfig.exe`) allows technicians to configure boot options (Safe Boot, Minimal, Network), manage boot parameters, and perform clean boots by selectively disabling non-Microsoft background services. `dxdiag` tests DirectX, `regedit` edits raw registry hives, and `cleanmgr` removes temporary files.", "distractor_analysis": {"1": "`dxdiag` tests video and sound DirectX acceleration components.", "2": "`regedit` provides raw registry key editing without automated clean-boot management workflows.", "3": "`cleanmgr` is the Disk Cleanup tool used to reclaim storage space."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["msconfig", "clean-boot", "startup", "system-configuration"], "id": "C2-092"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "easy", "question": "In Linux, which command displays information about available and used disk space on all mounted filesystems in human-readable format (e.g., GB, MB)?", "options": ["`top`", "`df -h`", "`du -sh`", "`free -m`"], "answer": 3, "explanation": "`df -h` (disk free, human-readable) displays filesystem disk usage, mount points, total capacity, used space, and available space in KB, MB, or GB. `du -sh` estimates disk usage of a specific directory tree, `free -m` displays physical and swap memory utilization, and `top` displays active process CPU usage.", "distractor_analysis": {"1": "`du -sh` summarizes the disk space consumed by a specific folder and its contents, not overall filesystem capacity.", "2": "`free -m` reports available and used physical RAM and swap space in megabytes.", "3": "`top` displays real-time CPU and memory utilization per running process."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "df", "disk-space", "cli"], "id": "C2-093"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "Which command-line tool in Windows checks the file system metadata of a volume for logical errors, locates bad physical sectors, and attempts to recover readable data?", "options": ["`format /q`", "`diskpart`", "`chkdsk /r`", "`sfc /scannow`"], "answer": 2, "explanation": "The `chkdsk /r` command locates bad physical sectors on the storage drive, recovers readable information from them, and fixes volume file system errors (implying `/f`). `sfc` checks core Windows OS files, `format /q` performs a quick format that erases file tables, and `diskpart` manages volume layout.", "distractor_analysis": {"1": "`sfc /scannow` verifies the cryptographic integrity of Windows OS system files, not physical drive sectors.", "2": "`format /q` initializes file tables without scanning for bad disk sectors.", "3": "`diskpart` creates and formats volume partitions without executing sector recovery diagnostics."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["chkdsk", "bad-sectors", "file-system", "disk-repair"], "id": "C2-094"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A finance director receives a targeted, personalized email claiming to be from corporate legal counsel demanding an urgent wire transfer to settle a pending acquisition lawsuit. What type of social engineering attack is this?", "options": ["Shoulder Surfing", "Watering Hole Attack", "Vishing", "Whaling"], "answer": 3, "explanation": "Whaling is a highly targeted form of spear phishing directed specifically at senior executives, board members, or high-value financial officers. Vishing uses voice phone calls, shoulder surfing is visual screen snooping, and watering hole attacks compromise industry websites.", "distractor_analysis": {"0": "Vishing is social engineering conducted via voice telephone conversations.", "2": "Shoulder surfing involves physically looking at a user's screen or keyboard input.", "3": "A watering hole attack infects a third-party website commonly visited by target company employees."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "whaling", "spear-phishing", "cfo"], "id": "C2-095"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "An unauthorized person follows closely behind an authorized employee entering a secure datacenter facility without scanning a badge. What security violation has occurred?", "options": ["Quishing", "Brute Force", "Tailgating", "Dumpster Diving"], "answer": 2, "explanation": "Tailgating (or piggybacking) is a physical security breach where an unauthorized individual follows an authorized person through a secure door or barrier without presenting valid authentication credentials. Dumpster diving searches trash, quishing uses QR codes, and brute force is password guessing.", "distractor_analysis": {"1": "Dumpster diving is searching discarded trash for passwords and confidential paperwork.", "2": "Quishing is a phishing attack delivered through deceptive QR codes.", "3": "Brute force is an automated cryptographic attack that systematically guesses passwords."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "tailgating", "physical-security", "door-access"], "id": "C2-096"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which physical security control uses a two-door airlock system where the first door must close and lock before the second door can open, strictly enforcing single-person authentication?", "options": ["Bollard", "Biometric Retina Scanner", "Turnstile", "Access control vestibule (Mantrap)"], "answer": 3, "explanation": "An access control vestibule (mantrap) consists of an enclosed entry chamber with two interlocking doors designed so that only one door can be open at a time, physically preventing tailgating and unauthorized access. Turnstiles allow rotational passage, bollards stop vehicles, and retina scanners are authentication sensors.", "distractor_analysis": {"0": "Turnstiles are mechanical gates that rotate for one person but do not physically enclose the occupant between two interlocking doors.", "2": "Bollards are heavy vertical concrete/steel posts that protect building perimeters from vehicle impacts.", "3": "A retina scanner is a biometric authentication device that verifies identity but does not physically trap followers on standard swing doors."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["physical-security", "mantrap", "access-control-vestibule", "datacenter"], "id": "C2-097"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "hard", "question": "A shared folder on an NTFS volume has Share permissions set to Read for Domain Users and NTFS permissions set to Modify for Domain Users. What is the effective permission when a domain user accesses the folder across the network?", "options": ["Read", "Full Control", "Write Only", "Modify"], "answer": 2, "explanation": "When accessing files over the network, Windows combines Share permissions and NTFS permissions, and the MOST RESTRICTIVE permission takes precedence. Between Share: Read and NTFS: Modify, the more restrictive permission is Read. The user will have Read-only access over the network.", "distractor_analysis": {"0": "Modify is granted at the NTFS level, but is blocked across the network by the more restrictive Share: Read setting.", "2": "Full Control is not assigned in either Share or NTFS permission tables.", "3": "Write Only is not a standard Windows permission and write access is denied by Share: Read."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["windows-permissions", "ntfs", "share-permissions", "security"], "id": "C2-098"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "What is the primary difference between Microsoft BitLocker and Encrypting File System (EFS)?", "options": ["BitLocker only works on FAT32, while EFS only works on exFAT", "BitLocker requires a cloud subscription, while EFS is hardware-based", "EFS encrypts entire drive volumes, while BitLocker encrypts individual files", "BitLocker encrypts entire disk volumes, while EFS encrypts individual files and folders"], "answer": 3, "explanation": "BitLocker provides full-volume encryption (FVE), protecting entire storage volumes (OS, system files, free space) and relying on TPM hardware. In contrast, EFS (Encrypting File System) operates at the file system layer on NTFS, encrypting individual files and folders tied to specific user certificates.", "distractor_analysis": {"0": "This reverses the definitions; BitLocker operates on whole volumes, whereas EFS operates on individual files/folders.", "2": "BitLocker and EFS both require NTFS volumes on internal storage drives.", "3": "BitLocker is a native feature of Windows Pro/Enterprise and does not require cloud subscriptions."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["encryption", "bitlocker", "efs", "windows-security"], "id": "C2-099"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "Which wireless security protocol replaces Pre-Shared Key (PSK) with Simultaneous Authentication of Equals (SAE) to protect against offline dictionary attacks?", "options": ["WPA2-Personal", "WPA3-Personal", "WEP", "WPA-Enterprise"], "answer": 1, "explanation": "WPA3-Personal introduces Simultaneous Authentication of Equals (SAE), a dragonfly handshake that provides forward secrecy and resistance to offline dictionary and brute-force password-guessing attacks. WEP, WPA, and WPA2-Personal use vulnerable legacy key exchanges.", "distractor_analysis": {"0": "WEP is an insecure legacy protocol broken by static 64/128-bit RC4 keys.", "1": "WPA-Enterprise uses 802.1X with a RADIUS server, not SAE.", "2": "WPA2-Personal uses the 4-way PSK handshake vulnerable to offline dictionary cracking if captured."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa3", "sae", "encryption"], "id": "C2-100"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "hard", "question": "In a corporate network using 802.1X wireless authentication, client devices authenticate against a centralized authentication server. Which protocol and default UDP ports are commonly used for this service?", "options": ["LDAP over TCP 389", "Kerberos over TCP 88", "TACACS+ over TCP 49", "RADIUS over UDP 1812 and 1813"], "answer": 3, "explanation": "RADIUS (Remote Authentication Dial-In User Service) is the standard protocol for enterprise 802.1X wireless authentication, using UDP port 1812 for authentication and authorization, and UDP port 1813 for accounting. TACACS+ uses TCP 49, LDAP uses TCP 389, and Kerberos uses port 88.", "distractor_analysis": {"0": "TACACS+ operates on TCP port 49 and is used primarily for router/switch administrative command authorization.", "2": "LDAP operates on TCP port 389 for directory queries, not direct 802.1X EAP frame encapsulation.", "3": "Kerberos operates on port 88 for ticket granting in Active Directory."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["radius", "802.1x", "ports", "protocols"], "id": "C2-101"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "easy", "question": "When hardening a new SOHO wireless router in a small branch office, which feature should be disabled IMMEDIATELY due to well-known 8-digit PIN brute-force vulnerabilities?", "options": ["WPA3 encryption", "WPS (Wi-Fi Protected Setup)", "WPA2-AES encryption", "MAC address filtering"], "answer": 1, "explanation": "Wi-Fi Protected Setup (WPS) uses an 8-digit PIN designed for easy device pairing. Due to a design flaw, the PIN is validated in two halves, allowing attackers to brute-force the PIN in hours using tools like Reaver. Security best practices mandate disabling WPS on all routers. WPA2/WPA3 provide essential security, and MAC filtering is harmless.", "distractor_analysis": {"0": "WPA3 encryption is the most secure wireless standard available and should be enabled, not disabled.", "2": "WPA2-AES is robust and secure; disabling it degrades wireless security.", "3": "MAC filtering restricts access by hardware address; while not strong security alone, it is not a high-risk vulnerability like WPS."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "wps", "router-hardening", "pin-attack"], "id": "C2-102"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "What type of attack occurs when an attacker intercepts network communication between two systems, secretly eavesdropping on or altering packets without either party knowing?", "options": ["A distributed denial of service flood", "An on-path, or man-in-the-middle, attack", "A brute-force password guessing run", "A logic bomb triggered by a date"], "answer": 1, "explanation": "A Man-in-the-Middle (MitM) attack, also known as an On-Path attack, occurs when an attacker intercepts, inspects, or modifies data flowing between two endpoints (often achieved via ARP poisoning or rogue Wi-Fi APs). DDoS floods bandwidth, brute force guesses passwords, and logic bombs execute malicious code on a trigger.", "distractor_analysis": {"0": "A flood exhausts capacity so the service stops. It does not read or alter a conversation.", "2": "Brute force guesses credentials against a login. It does not sit between two hosts.", "3": "A logic bomb is dormant code on a host, unrelated to traffic interception."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["network-attacks", "mitm", "on-path", "arp-spoofing"], "id": "C2-103"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A user authenticates to their corporate account by entering a password, inserting a smart card, and scanning their fingerprint. How many distinct authentication factors are being used?", "options": ["Four factors", "One factor", "Two factors", "Three factors"], "answer": 1, "explanation": "This scenario utilizes three distinct authentication factor categories: 1. Password ('Something you know'), 2. Smart Card ('Something you have'), and 3. Fingerprint ('Something you are'). Because three distinct categories are present, this is true three-factor authentication (3FA).", "distractor_analysis": {"0": "One factor would only include elements from a single category (e.g., password and PIN).", "1": "Two factors would include credentials from only two distinct categories.", "3": "Four factors would require an additional distinct factor category (such as 'Somewhere you are' or 'Something you do')."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["mfa", "authentication-factors", "smart-card", "biometrics"], "id": "C2-104"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A user connects to a public Wi-Fi access point at an airport that has the exact same SSID as the official airport network but is operated by an attacker to intercept traffic. What type of rogue wireless device is this?", "options": ["Bluejacking", "MAC spoofing", "Evil Twin", "WPS attack"], "answer": 2, "explanation": "An Evil Twin is a rogue wireless access point configured with the identical SSID, channel, and visual appearance of a legitimate network to fool unsuspecting users into connecting so the attacker can intercept credentials and data. Bluejacking is sending unsolicited Bluetooth messages, and MAC spoofing alters hardware addresses.", "distractor_analysis": {"1": "WPS attacks exploit PIN vulnerabilities on routers rather than broadcasting deceptive clone SSIDs.", "2": "Bluejacking sends unsolicited text or vCard messages over short-range Bluetooth.", "3": "MAC spoofing modifies the layer 2 hardware address of a network interface card."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-attacks", "evil-twin", "rogue-ap", "public-wifi"], "id": "C2-105"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which security concept states that users and system accounts should only be granted the minimum level of access and permissions necessary to perform their assigned job duties?", "options": ["Principle of Least Privilege", "Defense in Depth", "Single Sign-On", "Separation of Duties"], "answer": 2, "explanation": "The Principle of Least Privilege dictates that accounts, processes, and programs are given only the bare minimum rights and access permissions required to execute their specific job functions, minimizing the potential blast radius of a compromised account. Separation of duties divides critical tasks among multiple people, and defense in depth uses layered controls.", "distractor_analysis": {"0": "Separation of Duties splits a single critical business process across multiple individuals to prevent fraud.", "2": "Defense in Depth implements multiple overlapping layers of security controls (firewalls, AV, encryption).", "3": "Single Sign-On (SSO) allows a user to authenticate once and access multiple independent applications."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["access-control", "least-privilege", "security-principles", "rbac"], "id": "C2-106"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A technician is deploying corporate smartphones. Management wants to secure corporate emails and documents inside an encrypted sandbox without tracking or wiping employees' personal photos and apps. Which mobile management approach is BEST?", "options": ["Full Mobile Device Management (MDM) with complete factory wipe policy", "Geofencing with permanent GPS tracking", "Rooting all devices before deployment", "Mobile Application Management (MAM) with containerization"], "answer": 1, "explanation": "Mobile Application Management (MAM) uses containerization to isolate and encrypt corporate applications and data into a secure sandbox on the device. This allows administrators to manage, secure, or wipe corporate data without accessing, viewing, or wiping the employee's personal files and photos. Full MDM manages the entire physical device, and rooting destroys device security.", "distractor_analysis": {"1": "Full MDM with device-wide factory wipes will erase all personal data, which violates the requirement to preserve personal photos.", "2": "Geofencing restricts device functionality based on physical location but does not create app-level encrypted containers.", "3": "Rooting removes OS kernel sandboxing and introduces catastrophic security vulnerabilities."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "mam", "mdm", "byod", "containerization"], "id": "C2-107"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "What type of attack involves an attacker placing malicious flash drives labeled 'Confidential Payroll Q3' in a company parking lot, hoping an employee will pick one up and plug it into a corporate workstation?", "options": ["Vishing", "Baiting", "Tailgating", "Shoulder surfing"], "answer": 3, "explanation": "Baiting is a social engineering attack that relies on human curiosity or greed by leaving malware-infected physical media (USB drives, CD/DVDs) in public or corporate areas where victims will find them and insert them into computers. Tailgating is physical door following, shoulder surfing is visual spying, and vishing is phone phishing.", "distractor_analysis": {"1": "Tailgating is following an authorized person through a secured door without badging in.", "2": "Shoulder surfing is the physical act of looking at another person's screen or keyboard.", "3": "Vishing is social engineering executed over voice telephone calls."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "baiting", "usb-drop", "physical-security"], "id": "C2-108"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "hard", "question": "A security analyst discovers malicious software that has modified kernel-level system binaries and replaced core operating system API hooks to conceal its active processes and files from Task Manager. What malware type is this?", "options": ["Adware", "Macro virus", "Spyware", "Rootkit"], "answer": 1, "explanation": "A Rootkit is a stealthy type of malware designed to gain administrative/root access and modify low-level operating system code (kernel, bootloader, system drivers) to hide its presence, files, and processes from standard diagnostic tools like Task Manager and antivirus software. Adware displays ads, macro viruses run in documents, and spyware tracks user activity.", "distractor_analysis": {"1": "Adware generates unwanted advertising banners and pop-up windows in user space.", "2": "Macro viruses are embedded in office application files and execute via scripting macros.", "3": "Spyware monitors user keystrokes and browsing habits without replacing core kernel API hooks."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "rootkit", "kernel", "stealth"], "id": "C2-109"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "Which protocol provides secure, encrypted directory queries to Active Directory Domain Services using TLS over TCP port 636?", "options": ["Kerberos ticket exchange on TCP and UDP 88", "RADIUS authentication on UDP 1812", "LDAPS, LDAP wrapped in TLS on TCP 636", "LDAP in the clear on TCP 389"], "answer": 2, "explanation": "LDAPS (LDAP over SSL/TLS) encrypts directory queries and communications with Active Directory Domain Controllers over TCP port 636. Standard LDAP transmits queries in cleartext on TCP port 389. Kerberos uses UDP/TCP port 88, and RADIUS uses UDP 1812.", "distractor_analysis": {"1": "Plain LDAP on 389 carries binds and queries in cleartext, which is the problem being solved.", "2": "Kerberos issues tickets for authentication. It does not carry directory queries.", "3": "RADIUS handles network access authentication, not directory lookups against AD DS."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["directory-services", "ldaps", "tls", "ports"], "id": "C2-110"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "hard", "question": "A security technician needs to prevent datacenter staff laptops from copying classified design documents onto unauthorized USB flash drives or emailing sensitive PII to external domains. Which technology enforces this?", "options": ["Dynamic DNS record updates", "Data Loss Prevention (DLP) software", "WPA3-Enterprise wireless authentication", "EFS file-level encryption"], "answer": 3, "explanation": "Data Loss Prevention (DLP) software monitors endpoint activity, inspects file contents for sensitive patterns (PII, PCI, classified markers), and blocks unauthorized transmission via email, cloud uploads, or copying to external USB removable storage devices. WPA3 secures Wi-Fi, EFS encrypts local NTFS files, and Dynamic DNS updates host records.", "distractor_analysis": {"1": "Wireless authentication controls who joins the network, not what leaves on a USB stick.", "2": "EFS protects a file at rest. An authorized user can still copy it out.", "3": "Dynamic DNS keeps records current and has no data handling role."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["dlp", "data-loss-prevention", "exfiltration", "endpoint-security"], "id": "C2-111"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "hard", "question": "In biometric authentication systems, what metric measures the percentage of times legitimate, authorized users are incorrectly denied access by the biometric reader?", "options": ["FAR (False Acceptance Rate / Type II Error)", "CER (Crossover Error Rate)", "MTBF (Mean Time Between Failures)", "FRR (False Rejection Rate / Type I Error)"], "answer": 1, "explanation": "False Rejection Rate (FRR), also known as a Type I Error, measures the rate at which authorized legitimate users are incorrectly rejected by a biometric system. False Acceptance Rate (FAR, Type II Error) measures unauthorized users incorrectly admitted. Crossover Error Rate (CER) is the balance point where FAR equals FRR, and MTBF measures hardware reliability.", "distractor_analysis": {"1": "FAR (False Acceptance Rate) measures the percentage of times an impostor is incorrectly authenticated as a valid user.", "2": "CER (Crossover Error Rate) is the benchmark point where the False Acceptance Rate equals the False Rejection Rate.", "3": "MTBF (Mean Time Between Failures) is a hardware reliability metric measuring operational uptime between breakdowns."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["biometrics", "frr", "far", "cer"], "id": "C2-112"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "According to the official CompTIA 7-step malware removal process, what must a technician do IMMEDIATELY after identifying and researching malware symptoms?", "options": ["Quarantine the infected system", "Disable System Restore", "Educate the end user", "Update anti-malware signatures"], "answer": 2, "explanation": "Step 2 of the CompTIA 7-step malware removal process is 'Quarantine infected system' (isolating the machine from the network). Step 1 is Identify and research symptoms, Step 3 is Disable System Restore, Step 4 is Remediate, Step 5 is Schedule scans/updates, Step 6 is Enable System Restore, and Step 7 is Educate end user.", "distractor_analysis": {"0": "Updating anti-malware software is part of Step 4 (Remediate infected systems).", "2": "Disabling System Restore is Step 3, performed immediately after quarantining the machine.", "3": "Educating the end user is the final Step 7 of the removal methodology."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "comptia-7-step", "quarantine", "containment"], "id": "C2-113"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "Why is it critical to disable System Restore on a Windows workstation during the malware remediation process?", "options": ["To speed up the network interface card", "To prevent malware from being archived in System Restore points and restoring itself later", "To allow standard users to execute administrative tools", "To free up RAM for the antivirus scanner"], "answer": 1, "explanation": "Disabling System Restore purges all existing Volume Shadow Copy snapshots. If an active infection exists, malware binaries could be saved into restore points. If System Restore is left enabled and the user rolls back the system later, the malware would be restored. It does not affect network speed, user rights, or RAM.", "distractor_analysis": {"0": "System Restore manages disk volume snapshots and has zero influence over network card throughput.", "2": "Standard user security permissions are governed by UAC and NTFS ACLs, not System Restore.", "3": "Disabling System Restore clears disk storage, not physical RAM memory."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "system-restore", "remediation", "snapshots"], "id": "C2-114"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A Windows workstation crashes immediately during the initial boot phase with a BSOD stop code `INACCESSIBLE_BOOT_DEVICE`. What is the MOST likely cause?", "options": ["The monitor cable is loose, so POST output never reaches the panel", "The storage controller driver is missing, or SATA mode changed between RAID and AHCI", "The USB keyboard driver is corrupt and blocks the logon path", "The system clock drifted, so the boot certificate reads as expired"], "answer": 1, "explanation": "The `INACCESSIBLE_BOOT_DEVICE` stop error occurs when the Windows bootloader cannot initialize communication with the storage controller (due to missing/corrupt NVMe/RAID drivers or switching the SATA controller mode between AHCI and RAID in BIOS/UEFI). Disconnected display cables, keyboard drivers, and clock offsets do not trigger storage device kernel panics.", "distractor_analysis": {"0": "A loose display cable gives a blank screen, not a stop code naming the boot device.", "2": "A keyboard driver fault would still let Windows boot to a logon screen.", "3": "Clock drift affects certificate and domain authentication, not access to the boot volume."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-setup", "storage-drivers", "bsod", "ahci"], "id": "C2-115"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows computer fails to boot, displaying 'The Boot Configuration Data file is missing or contains errors.' In the WinRE Command Prompt, which command scans for Windows installations and rebuilds the BCD?", "options": ["`bootrec /fixmbr`", "`bootrec /rebuildbcd`", "`sfc /scannow`", "`chkdsk /f`"], "answer": 1, "explanation": "`bootrec /rebuildbcd` scans all attached disks for installed Windows operating systems and interactively prompts to add them to the BCD store. `/fixmbr` writes the MBR, `sfc` checks system files, and `chkdsk` checks disk sectors.", "distractor_analysis": {"0": "`bootrec /fixmbr` writes a standard Master Boot Record to the system partition without repairing BCD entries.", "2": "`sfc /scannow` checks operating system core binaries against cached manifests, not boot database configuration.", "3": "`chkdsk /f` repairs filesystem structure errors on the target drive volume."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["bootrec", "rebuildbcd", "windows-recovery", "troubleshooting"], "id": "C2-116"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "After an automatic graphics driver update, a designer's dual monitors flicker violently and drop to low resolution. What is the fastest way to restore stability?", "options": ["Format the drive and reinstall Windows from installation media", "Open Device Manager, display adapter properties, and Roll Back Driver", "Replace the two LCD panels and the video cables", "Delete the SystemRoot directory and repair from WinRE"], "answer": 1, "explanation": "Selecting 'Roll Back Driver' on the Driver tab of the display adapter's properties in Device Manager immediately reinstates the previously working graphics driver package and registry settings. Reformatting is destructive, monitor replacement is unnecessary, and deleting SystemRoot bricks the machine.", "distractor_analysis": {"0": "A rebuild costs hours for a fault a two-minute driver rollback fixes.", "2": "Two panels failing at the same moment as a driver update is not a hardware coincidence.", "3": "Deleting the Windows directory destroys the installation."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["device-manager", "driver-rollback", "graphics", "troubleshooting"], "id": "C2-117"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user complains that their computer takes over 10 minutes to reach a usable desktop after logging in. Which tool allows a technician to inspect and disable high-impact startup applications?", "options": ["Disk Management", "Event Viewer (Setup log)", "Windows Memory Diagnostic", "Task Manager (Startup tab)"], "answer": 1, "explanation": "The Startup tab in Task Manager (or Settings -> Apps -> Startup) displays all applications configured to launch at user logon and rates their performance impact (High, Medium, Low). Disabling non-essential high-impact programs dramatically shortens boot and login times. Disk Management manages partitions, Setup logs track OS installs, and Memory Diagnostic tests RAM chips.", "distractor_analysis": {"1": "Disk Management is used for partition layout and drive letter assignment, not startup app management.", "2": "The Setup log records OS installation and servicing events, having no startup program controls.", "3": "Windows Memory Diagnostic tests physical RAM modules for hardware faults."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["task-manager", "startup-apps", "slow-boot", "performance"], "id": "C2-118"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A user cannot browse any websites by domain name (e.g., www.datacenter.com) but can connect directly using numerical IP addresses (e.g., 93.184.216.34). Which command-line diagnostic tool should the technician use to test DNS resolution?", "options": ["`netstat`", "`route`", "`ping`", "`nslookup`"], "answer": 3, "explanation": "`nslookup` queries configured DNS servers directly to test whether hostnames resolve to IP addresses, isolating DNS failures from general IP routing issues. `ping` tests ICMP reachability, `netstat` displays open sockets, and `route` manages the IP routing table.", "distractor_analysis": {"0": "`ping` tests basic packet reachability; while pinging a domain name triggers DNS lookup, it does not provide detailed DNS record query diagnostics.", "2": "`netstat` displays active network socket connections and protocol statistics.", "3": "`route` displays and modifies the local IP routing table."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "nslookup", "dns", "troubleshooting"], "id": "C2-119"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A user logs into Windows and receives the message: 'You have been logged on with a temporary profile.' All customized desktop files are missing. What is the root cause?", "options": ["The motherboard has failed and the CMOS is no longer holding settings", "The NTUSER.DAT profile hive is corrupt, so Windows loads a temporary profile", "The workstation lost its domain trust relationship during boot", "The profile folder was redirected to a UNC path that is offline"], "answer": 1, "explanation": "When Windows cannot read, load, or access a user's `NTUSER.DAT` registry hive (due to disk corruption, improper shutdown, or permission locks), it prevents logon failure by creating a temporary, volatile profile (`TEMP`) that discards all changes upon logout. Motherboards, cables, and refresh rates do not cause profile loading faults.", "distractor_analysis": {"0": "A failed board does not boot to a logon screen at all, let alone reach a profile load.", "2": "A broken trust relationship refuses the logon outright with a trust error, not a temporary profile.", "3": "An unreachable redirect target gives a folder redirection error and usually names the path."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["profile-corruption", "temporary-profile", "user-profile", "registry"], "id": "C2-120"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A system file corruption issue cannot be repaired by `sfc /scannow` because the local component store is damaged. Which command repairs the Windows Component Store (WinSxS) using Windows Update as a source?", "options": ["chkdsk C: /f /r to repair the file system", "bootrec /rebuildbcd to rebuild the BCD store", "sfc /scannow /offbootdir to rerun the same scan", "DISM /Online /Cleanup-Image /RestoreHealth"], "answer": 1, "explanation": "The Deployment Image Servicing and Management tool (`DISM /Online /Cleanup-Image /RestoreHealth`) repairs the Windows component store (WinSxS) by downloading healthy replacements from Microsoft Windows Update servers. Once DISM completes, `sfc /scannow` can successfully repair damaged system files. `chkdsk` checks disk sectors, `bootrec` repairs boot records, and `defrag` optimizes disk clusters.", "distractor_analysis": {"1": "chkdsk repairs file system metadata and bad sectors. It does not restore protected system files.", "2": "bootrec repairs the boot configuration. The machine already boots, so this is the wrong layer.", "3": "Rerunning SFC fails the same way, because the component store it copies from is the damaged part."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["dism", "sfc", "system-integrity", "restorehealth"], "id": "C2-121"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user reports that web browser search queries are repeatedly redirected to suspicious advertising portals and new tabs open unprompted. What should the technician check and clean FIRST?", "options": ["The system power supply unit", "The RAM sticks in motherboard slots", "The physical network patch cable", "Installed browser extensions, add-ons, and search engine settings"], "answer": 1, "explanation": "Browser search redirection is typically caused by malicious or unwanted browser extensions, adware toolbars, or modified default search provider settings. Technicians should inspect and remove unauthorized extensions, reset the default search engine, clear cached browser data, and run an anti-malware scan. Power supplies, RAM, and cables are unrelated hardware.", "distractor_analysis": {"1": "Power supply hardware faults cause sudden system shutdowns, not browser search redirections.", "2": "RAM memory errors cause system blue screens and memory parity crashes.", "3": "Network patch cables transmit data packets and cannot selectively redirect browser search queries."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser-security", "extensions", "hijacking", "adware"], "id": "C2-122"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A workstation crashes with a stop code error (BSOD) and reboots automatically. Where does Windows store the crash dump files for post-incident kernel analysis?", "options": ["`C:\\Users\\Public\\Downloads`", "`%SystemRoot%\\Temp`", "`%SystemRoot%\\MEMORY.DMP` and `%SystemRoot%\\Minidump`", "`C:\\Program Files\\Common Files`"], "answer": 2, "explanation": "Windows writes memory dump files to `%SystemRoot%\\MEMORY.DMP` (for complete/kernel dumps) and `%SystemRoot%\\Minidump` (for small memory dumps). These crash dump files can be analyzed using diagnostic tools like WinDbg or BlueScreenView to identify the faulting driver or module. Program Files, Public Downloads, and Temp are standard storage locations not used for kernel crash dumps.", "distractor_analysis": {"1": "`C:\\Program Files\\Common Files` contains shared application libraries, not OS crash dumps.", "2": "`C:\\Users\\Public\\Downloads` is a shared user download directory.", "3": "`%SystemRoot%\\Temp` contains temporary operating system scratch files."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["bsod", "crash-dump", "minidump", "troubleshooting"], "id": "C2-123"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "An application fails to launch, displaying the error message 'VCRUNTIME140.dll was not found.' What is the proper remediation?", "options": ["Disable the Windows Defender Firewall", "Reinstall or repair the matching Microsoft Visual C++ Redistributable package", "Replace the computer power supply", "Run `diskpart clean` on the C: drive"], "answer": 3, "explanation": "`VCRUNTIME140.dll` is a core dynamic link library provided by the Microsoft Visual C++ Redistributable runtime package. When missing or corrupted, downloading and installing or repairing the Visual C++ Redistributable from Microsoft resolves the dependency error. Hardware replacements, disk wiping, and firewall changes do not fix missing runtime DLLs.", "distractor_analysis": {"1": "The power supply is functioning normally and has no connection to missing application runtime libraries.", "2": "`diskpart clean` wipes all partition data from the drive, causing total data loss.", "3": "Disabling the firewall removes network security without providing the missing C++ runtime DLL."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["dll-missing", "vcredist", "runtime", "troubleshooting"], "id": "C2-124"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A Windows critical service fails to start during boot with Error 1068: 'The dependency service or group failed to start.' How should the technician troubleshoot this?", "options": ["Rebuild the performance counter registry hive with lodctr /R", "Set the service to automatic delayed start and reboot twice", "Reregister the service DLL with regsvr32 and clear the event log", "Open services.msc, read the Dependencies tab, and start the prerequisite services"], "answer": 1, "explanation": "Error 1068 indicates that a service cannot initialize because one or more services listed on its 'Dependencies' tab in `services.msc` are stopped, disabled, or failed to start. Reviewing the Dependencies tab identifies the required services so the technician can ensure they are enabled and running. Reformatting is premature, screen resolution is irrelevant, and disabling passwords weakens security.", "distractor_analysis": {"1": "Counter rebuilds fix perfmon, not a dependency chain. Error 1068 names a dependency explicitly.", "2": "Delayed start changes timing but the dependency is still stopped, so the service fails again.", "3": "Reregistering a DLL treats a component fault, and clearing the event log destroys the evidence you need."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["services", "dependencies", "services-msc", "troubleshooting"], "id": "C2-125"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A mobile smartphone user reports that the corporate inventory app crashes immediately upon opening. What is the recommended first-line troubleshooting step on the device?", "options": ["Factory reset the phone without backing up data", "Turn off all cellular radios permanently", "Force stop the application and clear the app cache/data in Settings -> Apps", "Replace the smartphone motherboard"], "answer": 2, "explanation": "When an isolated mobile application crashes, the best initial troubleshooting step is to Force Stop the app and clear its temporary Cache and Data in Settings -> Apps. This removes corrupted local session data and resets the app state. Hardware replacement and unbacked-up factory resets are destructive, and disabling cellular radios does not fix application bugs.", "distractor_analysis": {"1": "Motherboard replacement is an extreme hardware repair for an isolated application-level cache fault.", "2": "Factory resetting without prior backup destroys user data unnecessarily.", "3": "Disabling cellular radios cuts off mobile connectivity without resolving application cache corruption."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "app-crash", "cache", "android"], "id": "C2-126"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "What is the FIRST step in the official CompTIA 6-step troubleshooting methodology?", "options": ["Test the theory to determine cause", "Document findings, actions, and outcomes", "Establish a theory of probable cause", "Identify the problem"], "answer": 3, "explanation": "Step 1 of the CompTIA 6-step troubleshooting methodology is 'Identify the problem' (gather information, question users, identify symptoms, determine if anything changed, review logs). Step 2 is Establish a theory, Step 3 is Test the theory, Step 4 is Establish a plan of action, Step 5 is Verify full system functionality, and Step 6 is Document findings.", "distractor_analysis": {"0": "Establishing a theory of probable cause is Step 2 of the methodology.", "2": "Testing the theory to determine cause is Step 3 of the methodology.", "3": "Documenting findings, actions, and outcomes is Step 6 (the final step) of the methodology."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["troubleshooting-methodology", "identify-problem", "comptia-6-step", "helpdesk"], "id": "C2-127"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "After successfully testing and confirming the theory of probable cause for a system outage, what is the NEXT step in the CompTIA troubleshooting methodology?", "options": ["Verify full system functionality", "Establish a plan of action to resolve the problem and identify potential effects", "Document findings and close the ticket", "Question the user about recent changes"], "answer": 1, "explanation": "Following Step 3 (Test the theory to determine cause), Step 4 is 'Establish a plan of action to resolve the problem and identify potential effects' (including obtaining change approvals and preparing a rollback plan), followed by implementing the plan. Step 5 is Verify system functionality, and Step 6 is Document findings.", "distractor_analysis": {"0": "Verifying full system functionality is Step 5, performed AFTER implementing the plan of action.", "2": "Documenting findings is Step 6, performed after verification is complete.", "3": "Questioning users about changes is part of Step 1 (Identify the problem)."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["troubleshooting-methodology", "plan-of-action", "comptia-6-step", "implementation"], "id": "C2-128"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "In a corporate datacenter change management process, what is the primary role of the Change Advisory Board (CAB)?", "options": ["To write all software code for the development team", "To evaluate proposed changes, assess business and technical risks, and grant formal approval", "To manually deploy operating system patches on client laptops", "To conduct performance reviews for IT staff members"], "answer": 1, "explanation": "The Change Advisory Board (CAB) is a governance committee of IT and business representatives responsible for reviewing Requests for Change (RFCs), evaluating operational risks, assessing scheduling and business impact, and granting formal approval for major infrastructure changes. The CAB does not write software, patch laptops manually, or conduct HR performance reviews.", "distractor_analysis": {"0": "Software code is written by software developers, not the Change Advisory Board.", "2": "Patch deployments are executed by system administrators during scheduled maintenance windows.", "3": "Staff performance reviews are managed by Human Resources and department managers."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "cab", "risk-assessment", "approval"], "id": "C2-129"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "easy", "question": "Which document must be consulted by datacenter personnel for proper handling procedures, personal protective equipment (PPE), and emergency first-aid protocols regarding hazardous chemicals (such as cleaning solvents or battery acid)?", "options": ["SLA (Service Level Agreement)", "SDS (Safety Data Sheet)", "AUP (Acceptable Use Policy)", "EULA (End-User License Agreement)"], "answer": 1, "explanation": "Safety Data Sheets (SDS), formerly known as Material Safety Data Sheets (MSDS), are mandatory safety documents detailing chemical product hazards, safe handling procedures, required PPE, storage guidelines, and emergency first-aid instructions. SLAs define service uptime, AUPs define acceptable user conduct, and EULAs define software licensing terms.", "distractor_analysis": {"0": "An SLA defines contractual service availability and performance commitments between a vendor and customer.", "2": "An Acceptable Use Policy specifies permissible employee conduct when using company technology assets.", "3": "A EULA defines legal software licensing permissions and restrictions."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "sds", "msds", "safety"], "id": "C2-130"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "easy", "question": "A company backup policy adheres to the '3-2-1' backup strategy. What does this rule mandate?", "options": ["3 backup servers, 2 administrators, 1 cloud subscription", "3 copies of data, across 2 different media types, with at least 1 copy kept offsite", "3 daily backups, 2 weekly backups, and 1 monthly backup", "3 network connections, 2 firewalls, and 1 router"], "answer": 1, "explanation": "The 3-2-1 backup rule specifies maintaining: 3 total copies of data (1 primary copy + 2 backup copies), on 2 different storage media types (e.g., local disk array + tape or cloud), with 1 copy stored Offsite (or in an isolated cloud region) for disaster recovery. It does not refer to staff counts, network routers, or schedule frequencies.", "distractor_analysis": {"0": "The 3-2-1 rule defines data copy counts and storage locations, not personnel counts or subscriptions.", "2": "Backup schedules (e.g., GFS grandfather-father-son) define retention frequencies, which differs from the 3-2-1 media rule.", "3": "Network router and firewall redundancies represent network design, not backup data redundancy."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-best-practices", "3-2-1-rule", "offsite", "media-types"], "id": "C2-131"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "medium", "question": "A datacenter decommission requires permanent sanitization of 100 magnetic hard disk drives (HDDs). Which method uses a powerful electromagnetic pulse to neutralize magnetic domains on the platters?", "options": ["Low-level formatting", "Degaussing", "Disk Cleanup", "Partition deletion"], "answer": 1, "explanation": "Degaussing subjects magnetic storage media (HDDs, magnetic tapes) to an intense electromagnetic field that scrambles the magnetic domains and destroys factory servo tracks, permanently erasing data and rendering the drive unusable. Low-level formatting rewrites tracks, Disk Cleanup deletes temporary files, and partition deletion only removes partition table headers.", "distractor_analysis": {"0": "Low-level formatting initializes tracks and sectors on a disk but does not magnetically destroy platters with EMP pulses.", "2": "Disk Cleanup removes temporary files in user space without sanitizing raw storage sectors.", "3": "Partition deletion removes partition table entries while leaving all raw sector data fully recoverable."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "degaussing", "magnetic-media", "sanitization"], "id": "C2-132"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "medium", "question": "Which type of fire extinguisher is specifically rated and required for extinguishing fires involving energized electrical equipment in a server room?", "options": ["Class K (Kitchen cooking oils)", "Class A (Water)", "Class B (Flammable liquids)", "Class C (Electrical Equipment)"], "answer": 1, "explanation": "Class C fire extinguishers use non-conductive extinguishing agents (such as CO2, Halon replacements like FM-200/Novec 1230, or dry chemical) to extinguish fires on energized electrical equipment without conducting electrical shock to the operator. Class A uses water (which conducts electricity), Class B is for flammable liquids, and Class K is for cooking oils.", "distractor_analysis": {"0": "Class A water extinguishers conduct electrical current directly back through the stream, posing a fatal electrocution hazard.", "1": "Class B extinguishers are formulated for flammable liquids like fuels and paints.", "3": "Class K extinguishers are designed for commercial kitchen grease and deep fryers."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["fire-safety", "class-c", "electrical-fire", "extinguisher"], "id": "C2-133"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "A technician is creating a Task Scheduler action that runs a nightly maintenance routine through powershell.exe on a Windows file server. Which file extension will the script argument point at?", "options": [".bat", ".sh", ".ps1", ".vbs"], "answer": 2, "explanation": "PowerShell scripts carry the .ps1 extension, so the scheduled task action runs powershell.exe with -File pointing at a .ps1 file. Expect to set the execution policy or sign the script before it will run under a service account. The .bat extension is legacy Command Prompt batch, still common in old logon scripts but with no access to the .NET object pipeline. The .sh extension is a Bourne or Bash script for Linux and macOS hosts and means nothing to the Windows scheduler. The .vbs extension is VBScript, which is deprecated and disabled in hardened builds.", "distractor_analysis": {"0": "`.bat` is the legacy file extension for MS-DOS and Windows Command Prompt batch scripts.", "1": "`.sh` is the file extension for Unix/Linux Bourne/Bash shell scripts.", "3": "`.vbs` is the file extension for Visual Basic Scripting Edition files."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "powershell", "file-extensions", "automation"], "id": "C2-134"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "hard", "question": "During an incident response investigation where a corporate laptop is seized as digital evidence, why is maintaining a strict 'Chain of Custody' form essential?", "options": ["To document everyone who handled and stored the evidence, keeping it admissible", "To record the imaging tool and hash used during acquisition", "To set the date the seized laptop may be reimaged and returned", "To speed up hardware warranty claims with the manufacturer"], "answer": 2, "explanation": "In digital forensics and incident response, a Chain of Custody form records the chronological custody, transfer, analysis, and secure storage of physical and digital evidence. Without a documented, unbroken chain of custody, evidence can be challenged and ruled inadmissible in legal proceedings. It has no role in warranties, payroll, or imaging.", "distractor_analysis": {"0": "Warranty handling is an asset process and has nothing to do with evidence integrity.", "2": "Tool version and hash values belong on the acquisition record that accompanies the image.", "3": "Disposal and return timing come from the evidence retention policy after the case closes."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["incident-response", "chain-of-custody", "evidence", "forensics"], "id": "C2-135"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "easy", "question": "When communicating with a frustrated customer whose computer crashed during a critical deadline, what professional technique should a technician use FIRST?", "options": ["Interrupt the user to explain that software crashes are normal", "Actively listen without interruption, acknowledge the urgency with empathy, and clarify the issue calmly", "Place the customer on hold immediately for 10 minutes", "Blame the software vendor for poor programming"], "answer": 1, "explanation": "Professional IT communication standards emphasize active listening and de-escalation: remain calm, do not interrupt the customer while they explain the issue, acknowledge their urgency with professional empathy, and ask clarifying diagnostic questions. Interrupting, long unannounced holds, and deflecting blame worsen customer frustration and violate service standards.", "distractor_analysis": {"0": "Interrupting the customer dismisses their concern and increases hostility.", "2": "Placing an agitated customer on hold without explanation escalates frustration.", "3": "Blaming external vendors is unprofessional and does not resolve the customer's problem."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "communication", "active-listening", "customer-service"], "id": "C2-136"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "medium", "question": "What is the recommended relative humidity range maintained in server rooms to prevent both electrostatic discharge (ESD) and moisture condensation?", "options": ["10% to 20%", "40% to 60%", "85% to 95%", "0% to 5%"], "answer": 1, "explanation": "Datacenter environmental standards (such as ASHRAE guidelines) recommend maintaining relative humidity between 40% and 60%. Humidity below 30-40% creates dry air that dramatically increases the risk of destructive electrostatic discharge (ESD). Humidity above 60-70% promotes moisture condensation on components, leading to corrosion and short circuits.", "distractor_analysis": {"0": "Humidity levels below 20% create extremely dry air, causing severe electrostatic discharge (ESD) hazards.", "2": "Humidity levels above 85% cause moisture condensation on cold electronics, leading to catastrophic short circuits.", "3": "0% to 5% humidity causes massive static electricity buildup and is hazardous to sensitive semiconductors."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "humidity", "datacenter", "esd"], "id": "C2-137"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "easy", "question": "When attaching an electrostatic discharge (ESD) wrist strap while servicing a disconnected desktop computer, where should the alligator clip be attached?", "options": ["Directly to the motherboard CPU socket pins", "To an active electrical wall outlet", "To the technician's plastic tool handle", "To an unpainted metal portion of the computer chassis"], "answer": 1, "explanation": "An ESD wrist strap should be clipped to an unpainted metal surface on the computer chassis (with the power cable unplugged). This equalizes the electrical potential between the technician's body and the equipment chassis, safely draining static electricity. Clipping to CPU pins damages hardware, live outlets cause electrocution, and plastic does not conduct static.", "distractor_analysis": {"1": "Clipping to CPU socket pins bends delicate pins and destroys semiconductor traces.", "2": "Attaching to a live electrical wall receptacle creates an immediate risk of fatal electrical shock.", "3": "Plastic tool handles are electrical insulators and cannot conduct or drain static charges."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["esd", "safety", "grounding", "wrist-strap"], "id": "C2-138"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "Which software licensing model is bundled with brand-new computer hardware, tied permanently to the original motherboard, and cannot be transferred to a different PC?", "options": ["Open Source GPL license", "OEM (Original Equipment Manufacturer) license", "Retail (FPP) license", "Enterprise Volume License (VL)"], "answer": 1, "explanation": "An OEM (Original Equipment Manufacturer) license is sold at a discount to computer builders and tied permanently to the original motherboard of the hardware on which it was first installed; it cannot be legally transferred to another PC. Retail (Full Packaged Product) licenses can be transferred to new hardware, and Volume Licenses cover corporate fleets.", "distractor_analysis": {"0": "Open source GPL software is freely redistributable and not tied to physical hardware motherboards.", "2": "Retail (FPP) licenses allow transferring the software license from an old PC to a newly purchased PC.", "3": "Enterprise Volume Licenses allow flexible reassignment and centralized KMS/MAK activation across corporate devices."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["licensing", "oem", "eula", "compliance"], "id": "C2-139"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "easy", "question": "When lifting a 4U rack server weighing 75 pounds (34 kg), what physical safety practice must technicians follow to prevent back injury?", "options": ["Bend at the waist and lift quickly using back muscles", "Perform a two-person team lift or use a specialized mechanical server lift, bending at the knees", "Carry the server with one hand while walking briskly", "Twist the torso while lifting the server"], "answer": 1, "explanation": "Lifting heavy datacenter equipment (generally any item exceeding 40-50 pounds) requires a two-person team lift or mechanical equipment lift. Technicians must bend at the knees (not the waist), keep the load close to the body, keep the back straight, and lift with the leg muscles without twisting the torso.", "distractor_analysis": {"0": "Bending at the waist and lifting with back muscles places severe strain on the spinal column, risking herniated discs.", "2": "Carrying a 75-pound server single-handedly is physically unsafe and risks dropping expensive hardware.", "3": "Twisting the torso while lifting creates asymmetrical spinal torque and is a leading cause of workplace back injuries."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["physical-safety", "lifting", "team-lift", "ergonomics"], "id": "C2-140"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "medium", "question": "In datacenter rack airflow management, why are blanking panels installed across empty rack unit (U) spaces?", "options": ["To provide extra storage shelves for technician tools", "To prevent hot exhaust air from recirculating back into the cold aisle server intakes", "To ground the rack against lightning strikes", "To increase optical fiber network speeds"], "answer": 1, "explanation": "Blanking panels (filler panels) cover unused rack spaces in server cabinets. In hot-aisle/cold-aisle datacenter designs, empty rack gaps allow hot exhaust air from the rear of the rack to loop back through the front intakes, causing servers to overheat. Blanking panels enforce proper front-to-back airflow containment. They are not tool shelves, lightning grounds, or network accelerators.", "distractor_analysis": {"0": "Blanking panels are lightweight airflow barriers, not load-bearing storage shelves.", "2": "Rack grounding is accomplished via heavy copper busbars and bonding straps, not plastic/sheet-metal blanking panels.", "3": "Airflow blanking panels have zero interaction with optical fiber transceivers or data propagation speeds."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["datacenter", "blanking-panels", "airflow", "hvac"], "id": "C2-141"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "A datacenter engineer must image 200 identical Windows 11 Enterprise workstations overnight with zero local technician touch. Which deployment method BEST meets this requirement?", "options": ["Manual USB media install on each unit", "Zero-touch / Autopilot or MDT-WDS PXE deployment with answer files", "Windows To Go USB drives left at each desk", "Clean install from retail ISO with local product keys"], "answer": 1, "explanation": "Zero-touch deployment (using Microsoft Deployment Toolkit [MDT], Windows Deployment Services [WDS] with PXE boot and unattended answer files [unattend.xml], or cloud-based Windows Autopilot with Intune) automates the entire installation, driver injection, domain joining, and software staging without requiring manual technician intervention at each machine. Manual USB and retail ISO installs require hands-on technician time for every machine.", "distractor_analysis": {"0": "Manual USB installation requires visiting every single machine physically, which is impossible overnight for 200 units with zero touch.", "2": "Windows To Go runs Windows from a portable USB drive rather than imaging the local workstation storage.", "3": "Retail ISO installations require manual interactive setup and typing individual product keys on each PC."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["deployment", "autopilot", "zero-touch", "wds"], "id": "C2-142"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "single", "difficulty": "medium", "question": "Which Windows edition is required to join an Active Directory domain for corporate workstations in a datacenter operations team?", "options": ["Windows 11 Home", "Windows 11 Pro or Enterprise", "Windows 11 S Mode only", "Windows 10 IoT Core"], "answer": 1, "explanation": "Joining a Windows Server Active Directory domain requires Windows Pro, Enterprise, or Education editions. Windows Home and consumer editions lack the networking architecture and security components to join a domain. S Mode restricts execution to Microsoft Store apps, and IoT Core is an embedded OS for single-board computers.", "distractor_analysis": {"0": "Windows 11 Home lacks Active Directory domain joining capabilities and Group Policy client processing.", "2": "Windows 11 S Mode is a locked-down mode restricted to Microsoft Store apps and does not provide enterprise domain management on its own.", "3": "Windows 10 IoT Core is designed for headless smart devices and embedded appliances, not interactive enterprise desktop workstations."}, "video_reference": {"title": "Installing Operating Systems - CompTIA A+ 220-1202 - 1.2", "url": "https://www.youtube.com/watch?v=SoDrALxWWTg", "duration": "16:50", "objective": "1.2"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-editions", "domain-join", "active-directory", "pro"], "id": "C2-143"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "A technician needs to view real-time CPU, memory, disk, and network utilization while investigating a sluggish file server. Which built-in tool is BEST?", "options": ["Event Viewer, filtered on the System log", "Task Manager, then Resource Monitor for detail", "Disk Cleanup, run against the system drive", "Device Manager, checking adapter status"], "answer": 1, "explanation": "Task Manager and Resource Monitor (`resmon.exe`) provide live, real-time telemetry, graphs, and per-process breakdowns of CPU, RAM, Disk I/O, and Network utilization. Notepad is a text editor, Disk Cleanup removes cached files, and Character Map inserts special typographic symbols.", "distractor_analysis": {"0": "Event Viewer shows recorded events after the fact. It gives no live utilization figures.", "2": "Disk Cleanup frees space. It reports nothing about CPU, memory or network load.", "3": "Device Manager shows device state and drivers, not resource consumption."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["task-manager", "resource-monitor", "performance", "real-time"], "id": "C2-144"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "Which MMC snap-in opens Event Viewer to review Application, System, and Security logs on a Windows server?", "options": ["`devmgmt.msc`", "`diskmgmt.msc`", "`services.msc`", "`eventvwr.msc`"], "answer": 1, "explanation": "`eventvwr.msc` launches Windows Event Viewer, the central console for viewing system event logs, application crash reports, and security audit entries. `devmgmt.msc` opens Device Manager, `diskmgmt.msc` opens Disk Management, and `services.msc` manages background services.", "distractor_analysis": {"1": "`devmgmt.msc` opens Device Manager to inspect, update, and troubleshoot hardware device drivers.", "2": "`diskmgmt.msc` opens Disk Management to partition, format, and assign drive letters to storage volumes.", "3": "`services.msc` opens the Services console to start, stop, and configure Windows background system services."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["mmc", "eventvwr", "event-viewer", "logs"], "id": "C2-145"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A help desk technician must force an immediate Group Policy refresh on a domain-joined laptop after a GPO change. Which command is correct?", "options": ["`gpupdate /force`", "`net start spooler`", "`chkdsk C:`", "`ipconfig /renew`"], "answer": 2, "explanation": "The `gpupdate /force` command instructs the Windows client to contact the domain controller and immediately reapply all user and computer Group Policy settings, bypassing standard background refresh intervals (90 minutes by default). `ipconfig /renew` renews DHCP leases, `net start` starts services, and `chkdsk` checks disk volumes.", "distractor_analysis": {"0": "`ipconfig /renew` requests a renewed IPv4/IPv6 lease from the DHCP server without refreshing Group Policy.", "2": "`net start spooler` starts the Windows Print Spooler service.", "3": "`chkdsk C:` scans the C: drive volume for file system metadata corruption."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "gpupdate", "group-policy", "force"], "id": "C2-146"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "Which command displays detailed TCP/UDP listening ports and active sockets along with their associated Process IDs (PIDs) on a Windows computer?", "options": ["`tracert -d`", "`netstat -ano`", "`nslookup -type=mx`", "`route print`"], "answer": 1, "explanation": "`netstat -ano` displays all active network connections and listening ports (`-a`), numeric IP and port addresses (`-n`), and the owning Process ID (`-o`) for each socket. `tracert` traces router hops, `nslookup` queries DNS records, and `route print` displays the local routing table.", "distractor_analysis": {"0": "`tracert -d` traces intermediate router hops without performing reverse DNS resolution on IP addresses.", "2": "`nslookup -type=mx` queries DNS servers specifically for Mail Exchange (MX) records.", "3": "`route print` displays the system IP routing table and active network interface gateway routes."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "netstat", "listening-ports", "pids"], "id": "C2-147"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "easy", "question": "A Linux rack server must show which process is consuming the most CPU in real time. Which interactive command provides this live performance dashboard?", "options": ["`cat /proc/cpuinfo`", "`top` or `htop`", "`uname -a`", "`grep cpu /var/log/messages`"], "answer": 1, "explanation": "`top` (and the enhanced `htop`) provides a dynamic, real-time interactive process viewer displaying CPU, memory, load average, and active process PIDs sorted by resource utilization. `cat /proc/cpuinfo` displays static CPU hardware model specs, `uname -a` shows kernel versions, and `grep` searches log text files.", "distractor_analysis": {"0": "`cat /proc/cpuinfo` outputs static hardware processor specifications (model, cores, cache), not live process CPU consumption.", "2": "`uname -a` displays operating system kernel architecture, hostname, and build release information.", "3": "`grep cpu /var/log/messages` searches system log files for historical text strings matching 'cpu'."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "top", "htop", "performance"], "id": "C2-148"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "Which Linux permission command allows the file owner full read, write, and execute control, the group read and execute access, and denies all permissions to others?", "options": ["`chmod 640`", "`chmod 750`", "`chmod 777`", "`chmod 600`"], "answer": 1, "explanation": "Octal permissions evaluate Read=4, Write=2, Execute=1. Owner full control (`rwx`) equals 4+2+1=7. Group read and execute (`r-x`) equals 4+1=5. Others no permissions (`---`) equals 0. Combining these gives `chmod 750`. `chmod 640` is rw-/r--/---, `chmod 777` gives full access to everyone, and `chmod 600` is owner rw- only.", "distractor_analysis": {"0": "`chmod 640` grants Owner read/write (6), Group read-only (4), and Others none (0), lacking execute bits.", "2": "`chmod 777` grants full read, write, and execute permissions to all users (Owner, Group, and Others).", "3": "`chmod 600` grants Owner read/write only, with zero permissions for Group and Others."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "chmod", "permissions", "octal"], "id": "C2-149"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "A macOS administrator needs to enable encrypted full-disk volume protection for a company MacBook using XTS-AES 128-bit encryption. Which built-in macOS feature provides this?", "options": ["Time Machine", "FileVault", "Gatekeeper", "Keychain Access"], "answer": 1, "explanation": "FileVault is Apple's native full-disk volume encryption technology in macOS. It uses XTS-AES-128 encryption with a 256-bit key to protect the entire startup disk and prevent unauthorized access if the device is lost or stolen. Time Machine handles backups, Gatekeeper verifies application code signatures, and Keychain Access stores passwords.", "distractor_analysis": {"0": "Time Machine is Apple's automated backup utility for creating incremental volume snapshots.", "2": "Gatekeeper is a macOS security feature that enforces code-signing requirements to prevent untrusted software execution.", "3": "Keychain Access is a credential manager for storing website passwords and digital certificates."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "filevault", "encryption", "apple"], "id": "C2-150"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "medium", "question": "Which Windows command-line utility can securely overwrite and wipe unallocated free space on an NTFS volume without destroying existing active files?", "options": ["`format /q`", "`cipher /w:C:`", "`sfc /scannow`", "`gpupdate /force`"], "answer": 1, "explanation": "The `cipher /w:directory` command removes residual data from deallocated disk sectors by overwriting all unallocated free space with zeroes, ones, and random numbers across three passes, preventing forensic file recovery while leaving existing valid files untouched. `format /q` wipes volume tables, `sfc` checks system files, and `gpupdate` refreshes Group Policy.", "distractor_analysis": {"0": "`format /q` initializes file allocation tables on the entire drive, destroying pointers to existing active files.", "2": "`sfc /scannow` checks and repairs corrupted Windows operating system binaries.", "3": "`gpupdate /force` updates Group Policy settings from domain controllers."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "cipher", "diskpart", "free-space"], "id": "C2-151"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "A technician needs to map a persistent network drive letter Z: to a shared folder `\\\\filesrv01\\backups` from the command line. Which command is correct?", "options": ["`net share Z:=\\\\filesrv01\\backups`", "`ipconfig /map Z: \\\\filesrv01\\backups`", "`robocopy Z: \\\\filesrv01\\backups`", "`net use Z: \\\\filesrv01\\backups /persistent:yes`"], "answer": 1, "explanation": "The `net use` command connects computers to shared network resources and maps drive letters. Specifying `net use Z: \\\\filesrv01\\backups /persistent:yes` maps the share to drive Z: and configures Windows to reconnect the share automatically upon subsequent logons. `net share` creates local network shares, `ipconfig` manages IP leases, and `robocopy` copies files.", "distractor_analysis": {"1": "`net share` is used on the host server to publish and export a local folder as a network share.", "2": "`ipconfig` manages network interface IP configuration and has no command switches to map network drives.", "3": "`robocopy` is a file replication tool, not a drive mapping utility."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "net-use", "mapping", "network-drives"], "id": "C2-152"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "easy", "question": "Which Windows Settings menu location is used to manage and toggle startup applications to improve boot performance?", "options": ["Settings -> Time & Language -> Region", "Settings -> Gaming -> Captures", "Settings -> Personalization -> Colors", "Settings -> Apps -> Startup"], "answer": 3, "explanation": "In Windows 10 and 11, startup applications are managed under Settings -> Apps -> Startup (or in Task Manager on the Startup apps tab). This interface allows users to toggle applications on or off to optimize boot time. Colors customizes window themes, Region sets regional formatting, and Captures configures game clip recording.", "distractor_analysis": {"0": "Personalization Colors manages light/dark mode and accent color themes.", "2": "Time & Language Region configures date formatting, currency symbols, and regional localization.", "3": "Gaming Captures configures screenshot shortcuts and game video recording parameters."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-settings", "startup-apps", "performance", "optimization"], "id": "C2-153"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A Windows workstation displays an IPv4 address of `169.254.88.14` and cannot reach the internet or local file servers. What does this address indicate?", "options": ["The computer successfully leased an enterprise static IP address", "The client failed to contact a DHCP server and self-assigned an Automatic Private IP Addressing (APIPA) address", "The computer is configured in an isolated DMZ subnet", "The default gateway assigned a public class B address"], "answer": 1, "explanation": "The `169.254.0.1` to `169.254.255.254` address block with a `/16` subnet mask is reserved for Automatic Private IP Addressing (APIPA). When a Windows client configured for DHCP fails to receive a response from a DHCP server (due to cable disconnection, server outage, or VLAN misconfiguration), it automatically self-assigns an APIPA address, allowing local link-local communication but preventing routing across gateways.", "distractor_analysis": {"0": "Static IP addresses are configured manually by administrators and do not fall in the link-local APIPA range.", "2": "DMZ subnets utilize routable private or public IP blocks assigned via DHCP or static configuration.", "3": "169.254.x.x is a non-routable link-local address range and is never assigned by a default gateway."}, "video_reference": {"title": "Windows Network Technologies - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=1OlbYiS-xHY", "duration": "8:37", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["networking", "apipa", "dhcp-failure", "ip-addressing"], "id": "C2-154"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which file system is the standard default for modern Windows operating system volumes, supporting file-level security permissions, encryption, compression, and disk quotas?", "options": ["ext4", "FAT32", "exFAT", "NTFS"], "answer": 1, "explanation": "NTFS (New Technology File System) is the proprietary default file system for Windows system boot drives and internal storage. It provides essential enterprise features including NTFS Access Control Lists (ACLs), Encrypting File System (EFS), volume shadow copies, file compression, and disk quotas. FAT32 and exFAT lack ACL permissions, and ext4 is a Linux file system.", "distractor_analysis": {"0": "FAT32 lacks support for security permissions, encryption, and files larger than 4 GB.", "1": "exFAT is designed for flash drives and external storage to support large files, but lacks granular NTFS permissions and quotas.", "3": "ext4 is the default journaling file system for Linux distributions, not native Windows boot volumes."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["file-systems", "ntfs", "windows-default", "security"], "id": "C2-155"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "A Linux administrator must recursively change the group ownership of `/opt/apps` and all files inside it to the group `opsgroup`. Which command is correct?", "options": ["`chown root /opt/apps`", "`ls -R /opt/apps`", "`chgrp -R opsgroup /opt/apps`", "`chmod -R 777 /opt/apps`"], "answer": 2, "explanation": "The `chgrp` (change group) command with the `-R` (recursive) flag updates the group ownership across the specified parent directory and all nested subdirectories and files. `chmod -R 777` alters permission bits, `chown root` modifies user owner only on the top folder, and `ls -R` lists directories recursively.", "distractor_analysis": {"1": "`chmod -R 777` grants universal read/write/execute permissions to all users, creating severe security risks without changing the group owner.", "2": "`chown root` changes only the user owner of the top folder without modifying group ownership or recursing.", "3": "`ls -R` lists directory contents recursively without modifying filesystem ownership metadata."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "chgrp", "recursive", "permissions"], "id": "C2-156"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "easy", "question": "Which Windows diagnostic boot option loads a minimal set of core device drivers and services with standard low-resolution display drivers to isolate software faults?", "options": ["Normal Startup", "Safe Mode (or Safe Mode with Networking)", "Selective Startup with All Services", "Fast Boot Mode"], "answer": 1, "explanation": "Safe Mode boots Windows with an absolute minimum set of trusted Microsoft drivers and essential system services, bypassing third-party startup applications, rogue drivers, and display accelerators. This clean environment is ideal for troubleshooting driver conflicts, resolving BSODs, and removing persistent malware. Normal Startup loads all drivers.", "distractor_analysis": {"0": "Normal Startup loads all installed third-party drivers, background services, and startup software.", "2": "Selective Startup with All Services enables third-party services and does not isolate system conflicts.", "3": "Fast Boot (Fast Startup) uses hybrid hibernation to speed up standard boots without loading diagnostic minimal drivers."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["safe-mode", "troubleshooting", "minimal-drivers", "windows-boot"], "id": "C2-157"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "A technician needs to view the system hostname, exact OS build version, installed Windows hotfixes/patches, and physical memory configuration from Command Prompt. Which command produces this report?", "options": ["`hostname`", "`systeminfo`", "`ver`", "`whoami`"], "answer": 1, "explanation": "`systeminfo` displays a comprehensive configuration summary of the local or remote computer, including OS name and version, product ID, BIOS version, physical memory, network cards, domain membership, and a complete list of installed hotfixes/patches. `hostname` displays only the computer name, `ver` shows simple OS version string, and `whoami` shows the active username.", "distractor_analysis": {"0": "`hostname` outputs only the netbios computer name of the local system.", "2": "`ver` outputs a single line showing the Windows kernel version string.", "3": "`whoami` displays the current logged-on domain and username."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "systeminfo", "hardware-specs", "hotfixes"], "id": "C2-158"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "medium", "question": "Which Windows administrative management utility is used to schedule a nightly automated robocopy backup script to execute every morning at 02:00 AM without user intervention?", "options": ["Task Manager", "Services console (`services.msc`)", "Resource Monitor", "Task Scheduler (`taskschd.msc`)"], "answer": 1, "explanation": "Task Scheduler (`taskschd.msc`) is the native Windows automation utility used to schedule tasks, scripts, and executables based on predefined time triggers (e.g., daily at 02:00 AM) or system event triggers. Task Manager monitors active processes, Services manages persistent background daemons, and Resource Monitor tracks live resource utilization.", "distractor_analysis": {"1": "Task Manager monitors active running applications and processes but cannot schedule future recurring batch tasks.", "2": "Services console configures persistent background system services, not time-triggered scheduled batch jobs.", "3": "Resource Monitor graphs real-time CPU, RAM, disk, and network counters without providing task automation."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["task-scheduler", "automation", "robocopy", "scheduled-tasks"], "id": "C2-159"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "easy", "question": "In Linux, which command prints the current working directory path to the terminal?", "options": ["`ls`", "`whereis`", "`pwd`", "`cd`"], "answer": 2, "explanation": "`pwd` (print working directory) outputs the full absolute path of the directory currently active in the shell session. `cd` changes directories, `ls` lists files, and `whereis` locates binary executables.", "distractor_analysis": {"1": "`cd` changes the current working directory to a specified target directory path.", "2": "`ls` lists files and subdirectories located inside the current directory.", "3": "`whereis` searches standard system directories to find the binary, source, and manual page files for a command."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "pwd", "cli", "navigation"], "id": "C2-160"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A Windows workstation can successfully ping the public IP address `8.8.8.8` but fails to load web pages when navigating to `www.google.com`. What network configuration component is misconfigured?", "options": ["Physical Ethernet cable", "DNS server configuration", "Subnet mask", "Default gateway IP address"], "answer": 3, "explanation": "Because the workstation can successfully ping an external public IP address (`8.8.8.8`), the physical network cable, local IP address, subnet mask, and default gateway routing are fully functional. The failure to resolve domain names (`www.google.com`) isolates the fault directly to an invalid, unreachable, or misconfigured DNS server address. Subnet masks and gateways affect all layer 3 IP traffic.", "distractor_analysis": {"1": "If the subnet mask was invalid, local and default gateway routing would fail, preventing pings to 8.8.8.8.", "2": "If the default gateway was unreachable, packets could not leave the local subnet to reach 8.8.8.8.", "3": "If the Ethernet cable was broken, all physical link communication and IP traffic would drop completely."}, "video_reference": {"title": "Windows Network Technologies - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=1OlbYiS-xHY", "duration": "8:37", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["networking", "dns", "hostname-resolution", "troubleshooting"], "id": "C2-161"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "Which macOS feature provides instant system-wide desktop search across files, emails, contacts, installed applications, and web results?", "options": ["Finder", "Spotlight", "Siri Remote", "Mission Control"], "answer": 1, "explanation": "Spotlight is Apple's built-in desktop search indexer in macOS, invoked via `Command + Space` or the magnifying glass icon in the menu bar. It provides fast search across files, metadata, apps, dictionaries, and web knowledge. Finder is the file manager, Siri Remote is an Apple TV peripheral, and Mission Control manages open application windows.", "distractor_analysis": {"0": "Finder is the macOS graphical file system browser, not the global indexing search bar.", "2": "Siri Remote is a physical hardware remote control used with Apple TV hardware.", "3": "Mission Control provides a visual overview of open application windows and virtual desktop spaces."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "spotlight", "search", "apple"], "id": "C2-162"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "hard", "question": "A datacenter jump box requires PowerShell remoting (`Enter-PSSession`) enabled across 50 Windows servers. Which Windows service and management protocol underpins PowerShell remoting?", "options": ["Telnet Service", "Windows Remote Management (WinRM / WS-Management)", "Simple Network Management Protocol (SNMP)", "Network File System (NFS)"], "answer": 1, "explanation": "PowerShell Remoting relies on the Windows Remote Management (WinRM) service, Microsoft's implementation of the standard WS-Management SOAP-based protocol. WinRM communicates over HTTP (port 5985) or HTTPS (port 5986) using Kerberos or certificate authentication. Telnet is unencrypted CLI, SNMP monitors device metrics, and NFS is a file-sharing protocol.", "distractor_analysis": {"0": "Telnet is an insecure plaintext terminal protocol that is disabled by default and unrelated to PowerShell Remoting.", "2": "SNMP queries hardware metrics and network interface counters, lacking remote interactive shell capabilities.", "3": "NFS is a network file sharing protocol used to mount remote storage volumes."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["powershell", "winrm", "remote-management", "wsman"], "id": "C2-163"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "Which system initialization and service manager is the modern standard on major Linux distributions (such as Ubuntu, RHEL, and Debian) and is managed via the `systemctl` command?", "options": ["`SysVinit`", "`Upstart`", "`GRUB2`", "`systemd`"], "answer": 1, "explanation": "`systemd` is the standard init system and service manager on modern Linux distributions. It initializes user space, manages daemons, controls logging (`journald`), and is controlled using `systemctl` (e.g., `systemctl start apache2`). `SysVinit` is the legacy init script system, `Upstart` is an older event-driven init system, and `GRUB2` is a bootloader.", "distractor_analysis": {"1": "`SysVinit` is the legacy Unix init system that relied on sequential shell scripts in `/etc/init.d/`.", "2": "`Upstart` was an interim event-based init daemon developed by Canonical, since superseded by `systemd`.", "3": "`GRUB2` is the Grand Unified Bootloader responsible for loading the Linux kernel into RAM at boot."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "systemd", "systemctl", "init"], "id": "C2-164"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "In accordance with standard network defense-in-depth principles, how are Windows Defender Firewall default inbound and outbound traffic rules configured on corporate endpoints?", "options": ["Block all inbound connections unless explicitly allowed, and allow all outbound connections unless explicitly blocked", "Block all outbound connections and allow all inbound connections", "Disable all firewall filtering across public profiles", "Allow all inbound and allow all outbound"], "answer": 2, "explanation": "Standard host firewall architecture enforces a default-deny inbound policy (blocking all incoming unsolicited connections unless an explicit rule allows them, e.g., RDP port 3389) and a default-allow outbound policy (permitting workstations to initiate outbound web and DNS connections unless specifically restricted). Allowing all inbound traffic exposes the host to remote exploits.", "distractor_analysis": {"0": "Allowing all inbound connections leaves all network ports wide open to scanning and remote exploitation.", "2": "Blocking all outbound traffic prevents normal web browsing and DNS resolution while allowing dangerous inbound attacks.", "3": "Disabling firewall filtering eliminates perimeter host packet inspection completely."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["firewall", "windows-defender", "inbound-rules", "default-deny"], "id": "C2-165"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "single", "difficulty": "easy", "question": "A user needs an automated offline incremental backup solution on macOS to an external USB drive. Which built-in macOS application should be configured?", "options": ["Boot Camp", "Finder", "Terminal", "Time Machine"], "answer": 1, "explanation": "Time Machine is Apple's built-in backup application for macOS that automatically creates hourly, daily, and weekly snapshots to external storage drives or network volumes. Boot Camp configures Windows dual-booting, Finder manages files, and Terminal provides shell access.", "distractor_analysis": {"1": "Boot Camp is used on Intel Macs to partition storage and install Microsoft Windows.", "2": "Finder is the desktop graphical file browser for macOS.", "3": "Terminal is the command-line interface for running shell commands."}, "video_reference": {"title": "macOS Overview - CompTIA A+ 220-1202 - 1.8", "url": "https://www.youtube.com/watch?v=6Xg4VbEfx88", "duration": "11:24", "objective": "1.8"}, "notes_reference": "25_macOS.md", "tags": ["macos", "time-machine", "backup", "apple"], "id": "C2-166"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "easy", "question": "Which command clears the local DNS resolver cache on Windows to force the workstation to query nameservers for updated IP records?", "options": ["`netstat -r`", "`ipconfig /flushdns`", "`ipconfig /release`", "`nslookup /clear`"], "answer": 3, "explanation": "`ipconfig /flushdns` clears and flushes the local DNS client resolver cache in Windows. `/release` drops the DHCP lease, `nslookup /clear` is invalid syntax, and `netstat -r` displays the routing table.", "distractor_analysis": {"1": "`ipconfig /release` releases the active DHCP IP lease from the network adapter.", "2": "`nslookup /clear` is non-existent command syntax.", "3": "`netstat -r` displays the contents of the IP routing table."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "ipconfig", "flushdns", "dns"], "id": "C2-167"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "A line-of-business software installer fails with an error stating that the Microsoft .NET Desktop Runtime is missing. What deployment step was omitted?", "options": ["The boot volume was formatted FAT32 instead of NTFS", "The power supply is undersized for the workstation", "Windows Update was left disabled on the workstation", "The vendor prerequisites and runtime dependencies were not verified first"], "answer": 1, "explanation": "Enterprise software applications often depend on prerequisite framework packages (such as .NET Runtime, Java JRE, Visual C++ Redistributables, or DirectX runtimes). Verifying and staging vendor prerequisite packages is an essential step in software installation planning. Hardware power supplies, FAT32 formatting, and disabling updates are unrelated.", "distractor_analysis": {"1": "Windows will not install to FAT32 in the first place, and the error names a missing runtime.", "2": "Power sizing has no bearing on whether a runtime is present.", "3": "Update policy can delay a runtime, but the omitted step was checking the prerequisite before deployment."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["software-installation", "prerequisites", "runtime", "compatibility"], "id": "C2-168"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "single", "difficulty": "easy", "question": "Which Windows administrative console consolidates Device Manager, Disk Management, Event Viewer, Task Scheduler, and Local Users and Groups into a single unified interface?", "options": ["Task Manager", "Registry Editor (`regedit.exe`)", "Computer Management (`compmgmt.msc`)", "Control Panel"], "answer": 2, "explanation": "Computer Management (`compmgmt.msc`) is a unified Microsoft Management Console containing three major sections: System Tools (Event Viewer, Task Scheduler, Shared Folders, Local Users and Groups, Performance, Device Manager), Storage (Disk Management), and Services and Applications. Task Manager monitors live processes, and Registry Editor edits raw keys.", "distractor_analysis": {"1": "Control Panel provides links to individual applets but lacks the hierarchical tree structure of Computer Management MMC.", "2": "Task Manager monitors live running applications, process CPU utilization, and startup items.", "3": "Registry Editor is dedicated to editing low-level registry keys and values."}, "video_reference": {"title": "Task Manager - CompTIA A+ 220-1202 - 1.4", "url": "https://www.youtube.com/watch?v=iyUyHTelPeQ", "duration": "4:52", "objective": "1.4"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["mmc", "compmgmt", "computer-management", "console"], "id": "C2-169"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "A Linux technician needs to monitor a system log file (`/var/log/syslog`) in real time, displaying newly appended log entries as they occur. Which command should be used?", "options": ["`grep error /var/log/syslog`", "`tail -f /var/log/syslog`", "`head -n 20 /var/log/syslog`", "`cat /var/log/syslog`"], "answer": 3, "explanation": "The `tail -f` (follow) command outputs the last lines of a file and keeps the stream open, actively displaying new data appended to the file in real time. `head` displays the beginning of a file, `cat` dumps the static contents once, and `grep` searches for matching text patterns statically.", "distractor_analysis": {"1": "`head -n 20` outputs the first 20 lines from the top of the file and terminates immediately.", "2": "`cat` displays the entire contents of the file from start to finish without following live updates.", "3": "`grep error` searches for the static string 'error' in the file and exits."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "tail", "logs", "cli"], "id": "C2-170"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "easy", "question": "Which partition table standard supports disk capacities larger than 2 TB and natively supports up to 128 primary partitions in Windows?", "options": ["MBR (Master Boot Record)", "GPT (GUID Partition Table)", "Dynamic Extended Partition", "FAT32"], "answer": 1, "explanation": "GUID Partition Table (GPT) supports storage capacities well beyond 2 TB (up to 9.4 ZB) and up to 128 primary partitions in Windows. MBR is limited to 2.2 TB and 4 primary partitions. FAT32 is a file system format, not a partition table standard.", "distractor_analysis": {"0": "MBR is capped at 2.2 TB and 4 primary partitions due to 32-bit sector addressing.", "2": "Dynamic Extended Partition is a legacy term for logical drive containers inside MBR extended partitions.", "3": "FAT32 is a file allocation table file system format with a 32 GB volume limit in Windows."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["partitioning", "gpt", "large-drives", "uefi"], "id": "C2-171"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "single", "difficulty": "medium", "question": "Which Windows command-line tool manages disks, partitions, and volumes, allowing technicians to create, delete, format, and assign drive letters via scripts or an interactive prompt?", "options": ["`chkdsk`", "`defrag`", "`sfc`", "`diskpart`"], "answer": 1, "explanation": "`diskpart` is the powerful command-line disk management utility in Windows used to manage storage objects (disks, partitions, volumes, virtual hard disks). It supports scripting and interactive commands like `clean`, `create partition primary`, `format fs=ntfs quick`, and `assign letter=X`. `chkdsk` checks volume health, `defrag` optimizes clusters, and `sfc` checks system files.", "distractor_analysis": {"1": "`chkdsk` scans file systems and disk sectors for corruption and bad blocks.", "2": "`defrag` reorganizes fragmented file pieces on magnetic hard drives.", "3": "`sfc` inspects protected Windows operating system DLLs and binaries."}, "video_reference": {"title": "Windows Command Line Tools - CompTIA A+ 220-1202 - 1.5", "url": "https://www.youtube.com/watch?v=iLgAwxmTSzI", "duration": "31:07", "objective": "1.5"}, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "diskpart", "partitioning", "disk-management"], "id": "C2-172"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "single", "difficulty": "medium", "question": "A technician is enabling Hyper-V on a Windows 11 Pro workstation to host test virtual machines. Which hardware CPU feature must be supported by the processor and enabled in UEFI?", "options": ["An integrated GPU for the console session", "An XMP memory profile enabled in UEFI", "Hardware virtualization, Intel VT-x or AMD-V, together with SLAT", "Hyper-Threading enabled in UEFI setup"], "answer": 2, "explanation": "Client Hyper-V requires a 64-bit processor with Second Level Address Translation (SLAT) and hardware virtualization extensions (Intel VT-x or AMD-V) enabled in the system UEFI/BIOS. Hyper-Threading, integrated graphics, and XMP memory overclocking are not mandatory virtualization prerequisites.", "distractor_analysis": {"1": "Hyper-Threading adds logical cores. It is not required for the hypervisor to run.", "2": "Hyper-V renders guest video in software. No integrated GPU is required.", "3": "XMP sets memory timings. It has no bearing on virtualization support."}, "video_reference": {"title": "An Overview of Windows - CompTIA A+ 220-1202 - 1.3", "url": "https://www.youtube.com/watch?v=B7JZ6rfH06Q", "duration": "9:09", "objective": "1.3"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["hyper-v", "virtualization", "slat", "hardware-requirements"], "id": "C2-173"}, {"exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "single", "difficulty": "medium", "question": "Which Linux command-line tool transfers data to or from a network server using protocols like HTTP, HTTPS, and FTP, making it ideal for API testing and file downloads?", "options": ["`kill`", "`curl`", "`ls`", "`chmod`"], "answer": 3, "explanation": "`curl` (Client URL) is a versatile command-line utility used to send and receive data over network protocols (HTTP, HTTPS, FTP, SFTP), widely used for testing REST APIs, downloading files, and inspecting HTTP headers. `ls` lists files, `chmod` changes permissions, and `kill` terminates processes.", "distractor_analysis": {"1": "`ls` lists directory contents in the file system.", "2": "`chmod` modifies file read, write, and execute permissions.", "3": "`kill` sends process signals to terminate running application PIDs."}, "video_reference": {"title": "Linux - CompTIA A+ 220-1202 - 1.9", "url": "https://www.youtube.com/watch?v=cpc3bHzWKG4", "duration": "11:11", "objective": "1.9"}, "notes_reference": "24_Linux.md", "tags": ["linux", "curl", "api", "networking"], "id": "C2-174"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "A visitor follows closely behind an employee through a badge-controlled datacenter security door without scanning an authorized credential. What physical security breach is this?", "options": ["Shoulder surfing", "Tailgating / Piggybacking", "Quishing", "Dumpster diving"], "answer": 1, "explanation": "Tailgating (or piggybacking) is a physical social engineering breach where an unauthorized individual slips through an electronic badge-controlled door by closely following an authorized employee. Shoulder surfing is looking at screens, quishing uses QR codes, and dumpster diving searches trash.", "distractor_analysis": {"0": "Shoulder surfing involves visually spying on passwords or screens in close proximity.", "2": "Quishing delivers malicious phishing links via QR code images.", "3": "Dumpster diving searches waste containers for sensitive documents."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "tailgating", "piggybacking", "physical-security"], "id": "C2-175"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which access control method BEST implements the principle of least privilege for a junior operator who only needs to reset domain user passwords?", "options": ["Add the operator to the Domain Admins group", "Delegate password-reset rights on the target OU using role-based access control", "Grant the operator Account Operators group membership", "Grant Full Control on all Active Directory partitions"], "answer": 1, "explanation": "Delegating specific administrative permissions (such as password resets) within a designated Organizational Unit (OU) using Role-Based Access Control (RBAC) grants the junior operator only the exact privileges required for their job duties, strictly enforcing least privilege. Domain Admins, Enterprise Admins, and root Full Control grant excessive domain-wide authority.", "distractor_analysis": {"0": "Domain Admins grants control of the whole forest for a task that needs one permission.", "2": "Account Operators is close but still allows creating and deleting accounts across the domain.", "3": "Full Control on every partition is the widest grant available and fails least privilege outright."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["access-control", "least-privilege", "rbac", "security-principles"], "id": "C2-176"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "Corporate Wi-Fi for staff laptops should use which modern wireless encryption and authentication standard combining AES encryption and 802.1X RADIUS authentication?", "options": ["WEP-Open", "WPA3-Enterprise or WPA2-Enterprise", "WPA-Personal (TKIP)", "WPS with static PIN"], "answer": 1, "explanation": "WPA2-Enterprise and WPA3-Enterprise utilize IEEE 802.1X port-based authentication connected to a backend RADIUS server with AES encryption, ensuring that every user authenticates with unique individual credentials or certificates. WEP is broken, WPA-Personal uses a shared passphrase, and WPS is vulnerable to PIN brute-forcing.", "distractor_analysis": {"0": "WEP is an obsolete, insecure protocol broken by static RC4 key reuse.", "2": "WPA-Personal relies on a shared passphrase and uses deprecated TKIP encryption.", "3": "WPS is an insecure automated pairing feature vulnerable to brute-force PIN attacks."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa3-enterprise", "802.1x", "radius"], "id": "C2-177"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "easy", "question": "Malware that encrypts files on local and network drives and demands cryptocurrency payment in exchange for a private decryption key is classified as what?", "options": ["Adware, unwanted advertising injected into the browser", "Ransomware, files encrypted pending a crypto payment", "Spyware, silent collection of user activity", "Keylogger, capture of every keystroke typed"], "answer": 1, "explanation": "Ransomware (specifically crypto-malware) locks or encrypts user files using strong cryptographic algorithms and demands an extortion payment (usually Bitcoin or other cryptocurrency) to obtain the decryption key. Adware displays ads, spyware tracks browsing, and keyloggers record keystrokes.", "distractor_analysis": {"0": "Adware is a nuisance that monetises impressions. It does not encrypt data or demand payment.", "2": "Spyware exfiltrates information quietly and wants to stay unnoticed, so it does not announce itself.", "3": "A keylogger captures typing to steal credentials. It leaves files readable."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "ransomware", "crypto-malware", "threats"], "id": "C2-178"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A CFO receives an email appearing to come from the CEO directing an urgent, confidential wire transfer to a foreign supplier account to close an acquisition. What social engineering attack is this?", "options": ["Shoulder surfing in the executive suite", "Dumpster diving for discarded documents", "A watering hole attack on a supplier site", "Business email compromise, also called whaling"], "answer": 1, "explanation": "Business Email Compromise (BEC) and Whaling are targeted social engineering attacks that impersonate senior executives or business partners to manipulate financial personnel into authorizing fraudulent wire transfers or disclosing confidential data. Shoulder surfing is visual spying, dumpster diving is rummaging through trash, and watering hole attacks compromise websites.", "distractor_analysis": {"1": "Shoulder surfing requires physical line of sight to a screen or keypad.", "2": "Dumpster diving recovers discarded paper or media, not an inbound email.", "3": "A watering hole compromises a site the target visits, rather than impersonating an executive."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "bec", "whaling", "financial-fraud"], "id": "C2-179"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which Windows security feature encrypts entire storage volumes (including the operating system and system files) to protect data at rest against offline physical theft?", "options": ["Windows Defender SmartScreen", "Disk Defragmenter", "BitLocker Drive Encryption", "User Account Control (UAC)"], "answer": 2, "explanation": "BitLocker Drive Encryption provides full volume encryption (FVE) on Windows Pro and Enterprise editions. It encrypts the entire volume using AES and integrates with the motherboard TPM chip to protect data against offline attacks if the drive is physically removed. UAC manages elevation prompts, SmartScreen blocks malicious URLs, and Defragmenter optimizes disks.", "distractor_analysis": {"1": "UAC enforces privilege boundaries during an active Windows session but does not encrypt storage blocks.", "2": "SmartScreen warns users about untrusted download files and phishing websites.", "3": "Disk Defragmenter reorganizes file clusters on spinning magnetic disks."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["encryption", "bitlocker", "tpm", "full-disk-encryption"], "id": "C2-180"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "easy", "question": "After verifying that a workstation is infected with active malware, what is the FIRST action the technician must take according to the CompTIA malware removal methodology?", "options": ["Disable the local firewall so the scanner can update", "Enable System Restore and take a fresh checkpoint", "Educate the end user on safe browsing habits", "Quarantine the host from wired and wireless networks"], "answer": 3, "explanation": "Step 2 of the CompTIA 7-step malware removal process is to Quarantine the infected system by disconnecting Ethernet cables and disabling Wi-Fi/Bluetooth, isolating the host to prevent lateral malware movement. Educating users is Step 7, firewalls should not be disabled, and enabling System Restore is Step 6.", "distractor_analysis": {"0": "User education is the final step in the methodology, once the machine is clean.", "2": "Dropping the firewall widens the attack surface while the host is still infected.", "3": "System Restore is disabled during remediation so malware cannot survive in a restore point."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "quarantine", "comptia-7-step", "containment"], "id": "C2-181"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "easy", "question": "Which authentication approach requires presenting credentials from at least two different factor categories (e.g., 'Something you know' combined with 'Something you have')?", "options": ["Single-factor authentication", "Multifactor authentication (MFA)", "Anonymous authentication", "Password complexity policy"], "answer": 1, "explanation": "Multifactor Authentication (MFA) requires presenting two or more independent credentials from different authentication categories: Something you know (password/PIN), Something you have (smart card/hardware token), or Something you are (biometrics). Single-factor uses one category, anonymous uses no credentials, and password complexity is a password policy.", "distractor_analysis": {"0": "Single-factor authentication relies on credentials from only one category (e.g., password only).", "2": "Anonymous authentication permits unauthenticated access without verifying identity.", "3": "Password complexity policies govern password length and characters within a single knowledge factor."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["mfa", "authentication", "smart-card", "security"], "id": "C2-182"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "easy", "question": "Degaussing or industrial physical shredding of decommissioned hard disk drives is an example of which security procedure?", "options": ["Logical data recovery", "Physical data destruction / media sanitization", "In-place OS upgrade", "Volume defragmentation"], "answer": 1, "explanation": "Degaussing and physical shredding are physical data destruction and media sanitization methods designed to permanently destroy data stored on magnetic or solid-state media so it can never be recovered. Data recovery retrieves lost files, OS upgrades update software, and defragmentation reorganizes clusters.", "distractor_analysis": {"0": "Data recovery is the process of restoring lost files from damaged drives, the opposite of intentional destruction.", "2": "In-place OS upgrades update the operating system while preserving existing user files.", "3": "Volume defragmentation reorganizes file fragments on spinning disks to optimize read speeds."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "degaussing", "shredding", "sanitization"], "id": "C2-183"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user encounters a red browser warning stating 'Your connection is not private' when visiting an internal company portal. What is the MOST common root cause?", "options": ["The computer display monitor is unplugged", "The mouse DPI setting is too high", "The workstation power supply is failing", "Expired, untrusted, or mismatched SSL/TLS digital certificate"], "answer": 1, "explanation": "Browser TLS/HTTPS security warnings occur when the website's SSL/TLS digital certificate has expired, was issued by an untrusted Certificate Authority (CA) whose root certificate is missing from the client trust store, or does not match the domain name in the URL (Common Name mismatch). Hardware monitors, mice, and power supplies do not cause TLS cryptographic warnings.", "distractor_analysis": {"1": "An unplugged display monitor results in a black screen, not a browser software certificate error.", "2": "Mouse DPI settings adjust pointer tracking sensitivity on the desktop.", "3": "Power supply hardware faults cause sudden system shutdowns, not web browser cryptographic errors."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser-security", "certificates", "https", "tls-warning"], "id": "C2-184"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "Which Active Directory component applies password policies, account lockouts, software restrictions, and desktop settings centrally across thousands of domain workstations?", "options": ["Local HOSTS file", "Static DNS MX record", "DHCP Reservation", "Group Policy Object (GPO)"], "answer": 1, "explanation": "Group Policy Objects (GPOs) in Active Directory allow administrators to centrally manage, configure, and enforce security policies, password complexity rules, software restrictions, and system settings across domain-joined computers and users. HOSTS files map local IPs, MX records route email, and DHCP reservations assign static IP addresses.", "distractor_analysis": {"1": "The local HOSTS file maps static IP addresses to hostnames on a single individual computer.", "2": "A DNS MX record specifies the mail exchange servers responsible for accepting incoming email.", "3": "A DHCP reservation assigns a fixed IP address to a specific network MAC address."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["active-directory", "gpo", "group-policy", "windows-security"], "id": "C2-185"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "Evil Twin rogue wireless access points primarily enable which class of cyberattack by tricking victims into connecting?", "options": ["Physical hard drive degaussing", "RAM chip soldering degradation", "On-path / wireless eavesdropping and credential harvesting", "Hardware CPU destruction"], "answer": 2, "explanation": "An Evil Twin access point mimics a legitimate Wi-Fi network's SSID to trick clients into connecting. Once connected, all client traffic routes through the attacker's rogue AP, enabling on-path (Man-in-the-Middle) eavesdropping, packet sniffing, SSL stripping, and credential harvesting. It cannot physically alter CPU silicon, degauss drives, or damage RAM soldering.", "distractor_analysis": {"1": "Wireless network connections cannot cause physical silicon destruction of the client computer processor.", "2": "Degaussing requires powerful physical electromagnetic fields applied directly to magnetic storage platters.", "3": "Connecting to a rogue Wi-Fi access point has no physical impact on motherboard RAM solder joints."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "evil-twin", "mitm", "on-path"], "id": "C2-186"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "easy", "question": "Which mobile security control allows an IT administrator to securely erase all data from a lost or stolen corporate smartphone over the cellular network?", "options": ["NFC pairing", "Remote wipe via MDM", "Local biometric lock", "Bluetooth tethering"], "answer": 3, "explanation": "Mobile Device Management (MDM) platforms provide remote wipe functionality, allowing administrators to send a cryptographic erase command over cellular or Wi-Fi networks to sanitize all data on a lost or stolen device. Biometric locks require physical presence, tethering shares internet, and NFC is short-range tap communication.", "distractor_analysis": {"1": "Biometric locks (fingerprint/face) authenticate physical users at the lock screen but cannot initiate network wipe commands.", "2": "Bluetooth tethering shares a cellular internet connection with nearby paired devices.", "3": "NFC pairing establishes short-range (under 4 cm) communication for mobile payments and device pairing."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "mdm", "remote-wipe", "lost-device"], "id": "C2-187"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "easy", "question": "When deploying a brand-new SOHO router and firewall, what should the administrator do with the factory default administrator password?", "options": ["Leave it set to the factory default for easier remote tech support", "Change it immediately to a strong, unique administrative password and store it securely", "Disable all passwords on the router", "Write the password on a public whiteboard"], "answer": 1, "explanation": "Leaving factory default credentials (e.g., admin/admin, admin/password) on a router is a severe security vulnerability that automated bots and attackers exploit within minutes. The administrator must immediately change default credentials to a strong, unique passphrase. Leaving defaults, disabling passwords, or posting them publicly invites compromise.", "distractor_analysis": {"0": "Leaving default credentials allows automated internet worms and attackers to easily seize control of the router.", "2": "Disabling administrative passwords removes all authentication protection from the management console.", "3": "Displaying administrative credentials on a public whiteboard violates physical and operational security standards."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "router-hardening", "default-passwords", "firewall"], "id": "C2-188"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A vendor advisory lands in the ticket queue warning that attacks are already being seen in the wild and no fix is available yet. A zero-day vulnerability is characterized by which condition?", "options": ["The vulnerability was patched ten years ago", "The vulnerability only affects legacy dial-up modems", "The vulnerability occurs only on the first day of every month", "The vulnerability is actively exploited before the software vendor has developed and released an official security patch"], "answer": 1, "explanation": "A zero-day vulnerability refers to a software security flaw that is known to attackers or actively exploited in the wild before the software developer has created and distributed an official security patch (leaving zero days of protection). It does not refer to calendar dates, patched legacy bugs, or dial-up modems.", "distractor_analysis": {"1": "Patched vulnerabilities are known, historical flaws for which remediation updates already exist.", "2": "Zero-day vulnerabilities can affect any software, operating system, or firmware application.", "3": "The term 'zero-day' reflects the absence of patch lead time, not calendar days of the month."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["vulnerabilities", "zero-day", "threats", "patches"], "id": "C2-189"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "hard", "question": "In Windows NTFS permissions, what specific capability does Full Control grant that Modify permission does NOT grant?", "options": ["Changing file permissions and taking file ownership", "Deleting files and folders", "Executing executable programs", "Reading file contents"], "answer": 2, "explanation": "In NTFS permissions, the Modify permission allows reading, writing, executing, and deleting files and subfolders. However, only Full Control grants the special rights to Change Permissions (modify ACLs) and Take Ownership of the file or folder. Read, delete, and execute are included in Modify.", "distractor_analysis": {"0": "Reading file contents is granted by standard Read permissions as well as Modify.", "2": "Deleting files and subdirectories is explicitly included in the NTFS Modify permission.", "3": "Executing application binaries is included in the Read & Execute and Modify permissions."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["ntfs-permissions", "modify", "full-control", "ownership"], "id": "C2-190"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "Which protocol is standard for providing centralized Authentication, Authorization, and Accounting (AAA) for 802.1X wireless networks and VPNs over UDP?", "options": ["FTP", "Telnet", "SMTP", "RADIUS"], "answer": 1, "explanation": "RADIUS (Remote Authentication Dial-In User Service) provides centralized AAA management for network access clients, VPNs, and 802.1X wireless networks over UDP. FTP transfers files, Telnet is unencrypted CLI, and SMTP transfers email.", "distractor_analysis": {"1": "FTP (File Transfer Protocol) transfers files over TCP ports 20/21 and does not provide network AAA services.", "2": "Telnet operates on TCP port 23 for unencrypted command-line sessions.", "3": "SMTP (Simple Mail Transfer Protocol) routes electronic mail messages between mail servers."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["radius", "aaa", "authentication", "network-access"], "id": "C2-191"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "easy", "question": "A hardware or software keylogger installed on an employee workstation is designed primarily to steal what type of information?", "options": ["Motherboard fan speeds", "Keystrokes, passwords, and sensitive typed text", "Physical CPU clock speeds", "Monitor display refresh rates"], "answer": 3, "explanation": "Keyloggers (software spyware or hardware inline USB devices) covertly record every keystroke pressed on the physical keyboard, capturing user account credentials, credit card numbers, confidential messages, and search queries. They do not monitor CPU clock frequencies, refresh rates, or fan speeds.", "distractor_analysis": {"1": "CPU clock speeds are hardware telemetry metrics managed by motherboard firmware, not targets of keyloggers.", "2": "Monitor refresh rates are video display settings, not sensitive typed user input.", "3": "Fan speeds are managed by thermal hardware controllers, having zero relationship with typed keystrokes."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "keylogger", "spyware", "credential-theft"], "id": "C2-192"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A supply chain attack compromises an organization's security by targeting which vector?", "options": ["The building's janitorial cleaning supplies", "Local coffee shop menu boards", "Workstation mouse pads", "Trusted third-party vendors, software update pipelines, or hardware suppliers"], "answer": 1, "explanation": "A supply chain attack compromises a target organization indirectly by infiltrating trusted third-party suppliers, upstream software development repositories, code-signing certificates, or hardware vendors (e.g., injecting malicious backdoors into legitimate vendor software updates). Janitorial supplies, menus, and mouse pads are not IT supply chain attack vectors.", "distractor_analysis": {"1": "Janitorial cleaning supplies are physical facility maintenance items and do not compromise IT software supply chains.", "2": "Coffee shop menu boards are external public displays unrelated to enterprise software delivery pipelines.", "3": "Mouse pads are passive physical desk accessories without computational logic."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["supply-chain", "third-party", "vendor-risk", "security-threats"], "id": "C2-193"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "Which security practice BEST hardens a web browser used by datacenter engineers to manage cloud infrastructure administrative consoles?", "options": ["Keep the browser updated to the latest patched version, limit extensions to verified tools, and enforce MFA", "Disable all browser certificate validation warnings", "Save all administrative passwords in plaintext on the desktop", "Install dozens of unverified third-party shopping extensions"], "answer": 2, "explanation": "Securing web browsers used for administrative consoles requires applying regular browser updates and patches, disabling or removing unnecessary third-party extensions, using dedicated administrative browser profiles, enforcing MFA, and respecting HTTPS certificate warnings. Unverified extensions, ignoring certificate alerts, and plaintext passwords create massive vulnerabilities.", "distractor_analysis": {"0": "Installing unverified browser add-ons dramatically increases the attack surface and risks credential theft via malicious extensions.", "2": "Disabling certificate validation warnings exposes administrative sessions to on-path (MitM) eavesdropping.", "3": "Storing administrative passwords in plaintext files on the desktop violates basic credential management security."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser-security", "cloud-admin", "hardening", "extensions"], "id": "C2-194"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "easy", "question": "What is the MOST effective physical countermeasure against shoulder surfing when an employee is working on sensitive documents in an airport lounge?", "options": ["Disabling the laptop Wi-Fi card", "Increasing the display brightness to maximum", "Changing the desktop wallpaper to bright yellow", "Installing an anti-glare physical privacy filter screen over the laptop display"], "answer": 1, "explanation": "Physical privacy filters (privacy screens) fit over laptop displays and use micro-louver technology to restrict the viewing angle, making the screen appear completely black from side angles and preventing nearby people from viewing sensitive text (shoulder surfing). Disabling Wi-Fi, increasing brightness, and changing wallpapers do not restrict side viewing angles.", "distractor_analysis": {"1": "Disabling Wi-Fi disconnects network access but leaves open local documents completely visible to anyone standing nearby.", "2": "Increasing screen brightness makes text easier for nearby bystanders to read from a distance.", "3": "Changing desktop wallpaper colors does not obscure active application windows containing confidential data."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["shoulder-surfing", "privacy-filter", "physical-security", "awareness"], "id": "C2-195"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "easy", "question": "Which native Windows security component provides real-time signature-based and behavioral anti-malware scanning for all installed applications and downloaded files?", "options": ["Character Map", "Microsoft Defender Antivirus", "Windows Media Player", "Disk Defragmenter"], "answer": 3, "explanation": "Microsoft Defender Antivirus is the built-in anti-malware solution integrated into Windows 10 and 11, providing continuous real-time scanning, cloud-delivered behavioral protection, and signature updates. Media Player plays video/audio, Defragmenter optimizes hard drives, and Character Map displays font symbols.", "distractor_analysis": {"1": "Windows Media Player is an entertainment application for multimedia playback.", "2": "Disk Defragmenter optimizes file cluster placement on magnetic hard drives.", "3": "Character Map is a utility used to locate and copy special typographic font characters."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["defender", "antivirus", "real-time-protection", "windows-security"], "id": "C2-196"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "Why is a Rootkit considered one of the most dangerous forms of malware on a corporate workstation?", "options": ["It encrypts user documents and demands payment for the decryption key", "It floods the local segment with broadcast traffic until the network stalls", "It replaces the browser home page and injects advertising", "It runs with kernel privileges and hides its processes and files from security tools"], "answer": 1, "explanation": "Rootkits are exceptionally dangerous because they execute at Ring 0 (kernel space) or bootloader level, subverting the operating system itself to intercept API calls and hide their files, network connections, and processes from antivirus scanners and Task Manager. They do not merely delete wallpapers, display benign ads, or improve performance.", "distractor_analysis": {"1": "That is ransomware. It is destructive but visible, which makes it easier to detect than a rootkit.", "2": "Broadcast flooding is a denial of service symptom, not a stealth persistence technique.", "3": "Browser hijacking is adware behaviour and is removed with standard cleanup tools."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "rootkit", "kernel", "stealth"], "id": "C2-197"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "medium", "question": "Why is obtaining a formal Certificate of Destruction essential when an organization contracts a third-party vendor to shred decommissioned hard disk drives?", "options": ["It provides a 100% discount on future hardware purchases", "It allows the company to reuse the shredded drive platters", "It provides legally recognized proof of proper media sanitization for regulatory compliance audits (e.g., HIPAA, PCI-DSS, GDPR)", "It automatically updates the Windows registry on all client PCs"], "answer": 2, "explanation": "A Certificate of Destruction provides legally binding documentation detailing the serial numbers, destruction method (shredding/incineration), date/time, and authorized witness signatures for destroyed media. This document is required to prove compliance during regulatory audits (HIPAA, PCI-DSS, GDPR, SOX). It does not update registries, grant discounts, or allow reusing shredded scrap metal.", "distractor_analysis": {"1": "A physical paper certificate of destruction has no interaction with operating system registry hives.", "2": "Certificates of destruction are compliance records, not commercial discount coupons for hardware vendors.", "3": "Shredded hard drive platters are destroyed into tiny metal fragments and cannot be reconstructed or reused."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "certificate-of-destruction", "compliance", "audit"], "id": "C2-198"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "hard", "question": "How does an attacker successfully execute a SQL Injection (SQLi) attack against a web application database?", "options": ["By sending standard ICMP ping packets to port 80", "By inputting unfiltered SQL query statements into vulnerable web form input fields to manipulate backend database commands", "By cutting the physical fiber optic cable connecting to the web server", "By setting the browser zoom level to 200%"], "answer": 3, "explanation": "SQL Injection (SQLi) occurs when a web application fails to properly sanitize or parameterize user input, allowing an attacker to inject malicious SQL commands (e.g., `' OR '1'='1`) into input fields or URL parameters to bypass authentication, dump database contents, or modify records. Cutting cables is physical sabotage, zoom levels change display size, and ICMP pings test network reachability.", "distractor_analysis": {"1": "Cutting physical network cabling causes a denial of service at the physical layer, not a software SQL injection vulnerability.", "2": "Adjusting browser zoom modifies visual magnification on the client display without altering web server query syntax.", "3": "ICMP ping packets operate at layer 3 and do not interact with application layer database query parameters."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["web-security", "sql-injection", "input-validation", "attacks"], "id": "C2-199"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "hard", "question": "What is the primary objective of a Cross-Site Scripting (XSS) attack against a web application?", "options": ["To inject SQL into a form field so the database returns extra rows", "To flood the server with half-open TCP connections until it stops responding", "To make the browser submit an authenticated request the user did not intend", "To inject client-side script into a trusted site so it runs in other users' browsers"], "answer": 1, "explanation": "Cross-Site Scripting (XSS) attacks exploit improper input sanitization in web applications to inject malicious client-side JavaScript into web pages viewed by other users. When victims view the page, their browser executes the script, allowing the attacker to steal session cookies, hijack account tokens, or redirect users to phishing sites. XSS does not overheat CPUs, alter magnetic storage, or flash router firmware.", "distractor_analysis": {"1": "That is SQL injection. It targets the database tier, not the visitor's browser.", "2": "That is a SYN flood, a denial of service technique with no script execution.", "3": "That is cross-site request forgery. It abuses an existing session rather than running attacker script."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["web-security", "xss", "cross-site-scripting", "javascript"], "id": "C2-200"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "For SOHO router hardening, applying regular firmware updates primarily addresses which operational requirement?", "options": ["Extending the DHCP scope so more clients can lease an address", "Adding new QoS queues for voice traffic on the WAN interface", "Patching known vulnerabilities such as buffer overflows and remote execution bugs", "Raising the wireless throughput available to older client radios"], "answer": 2, "explanation": "Router firmware updates patch discovered software vulnerabilities, fix routing bugs, close known remote code execution holes, and update wireless security protocols (e.g., adding WPA3). Firmware has no interaction with monitor colors, keyboard polling, or audio bitrates.", "distractor_analysis": {"1": "Throughput is set by the radio standard the client supports, not by patch level.", "2": "Scope size is a configuration change you make yourself; it is not what a firmware update delivers.", "3": "QoS may appear as a feature, but hardening is about closing known vulnerabilities."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "router-hardening", "firmware", "vulnerabilities"], "id": "C2-201"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "hard", "question": "How does implementing Just-In-Time (JIT) privileged access management reduce operational cybersecurity risk?", "options": ["By exempting administrative portals from multifactor authentication", "By granting elevated rights only when approved, and revoking them straight afterwards", "By making every administrator a permanent member of Domain Admins", "By sharing one root password among the technicians on shift"], "answer": 3, "explanation": "Just-In-Time (JIT) access reduces the attack surface by eliminating standing administrative privileges. Users operate with standard privileges until an elevated task is required, at which point elevated rights are granted for a restricted duration (e.g., 2 hours) with full auditing and automatic revocation upon task completion. Permanent domain rights and shared root passwords create massive vulnerabilities.", "distractor_analysis": {"1": "Standing membership is exactly the always-on privilege that JIT exists to remove.", "2": "A shared credential destroys attribution, so nobody can say who made a change.", "3": "Removing MFA weakens the most valuable accounts on the estate."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["access-control", "jit", "least-privilege", "privileged-access"], "id": "C2-202"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "A security lead is briefing the help desk on threat categories after a data leak traced back to an internal account. Which characteristic defines an insider threat?", "options": ["External nation-state groups that rely on zero-day exploits for entry", "Automated botnets brute forcing exposed remote desktop services", "Supply chain compromise of a vendor update pushed to customers", "Current or former staff, contractors or partners who misuse legitimate access"], "answer": 1, "explanation": "An Insider Threat originates from an individual who has authorized, legitimate access to an organization's network, facilities, or data (such as employees, contractors, or vendors) and misuses that access maliciously or inadvertently to cause harm, exfiltrate IP, or disrupt operations. Nation-states are external threats, and power/rodent events are physical/environmental hazards.", "distractor_analysis": {"1": "Nation-state actors are an external advanced threat. The defining trait of an insider is authorized access.", "2": "Botnet brute force is external and unauthenticated by definition.", "3": "Supply chain compromise abuses vendor trust, not the access rights of a person inside the organization."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["insider-threat", "threat-actors", "security", "auditing"], "id": "C2-203"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "What security risk is directly mitigated by configuring an automatic screen lock policy after five minutes of inactivity across corporate workstations?", "options": ["Brute force attempts against the domain account lockout policy", "Malware persistence through a scheduled task that runs at logon", "Unauthorized access to an unattended session that is still logged in", "Credential replay from a Kerberos ticket captured on the wire"], "answer": 2, "explanation": "Enforcing automatic screen locking after a brief period of inactivity ensures that if a user walks away from their desk, the workstation locks itself and requires re-authentication, preventing unauthorized personnel from accessing open confidential data or impersonating the user. It has no effect on RAID rebuilds, Wi-Fi interference, or UPS power.", "distractor_analysis": {"1": "Ticket replay is countered by Kerberos timestamps and encryption, not by a screen timeout.", "2": "Lockout thresholds and password policy handle brute force. A locked screen does not change that.", "3": "Persistence is removed by remediation and autorun review, not by locking the console."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "screen-lock", "inactivity-timeout", "gpo"], "id": "C2-204"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "hard", "question": "How does a 'Password Spraying' attack differ from a traditional brute-force password attack?", "options": ["Password spraying only attacks WEP initialization vectors", "Password spraying attempts a few common passwords across many user accounts to avoid triggering account lockout thresholds", "Password spraying attempts millions of passwords against a single user account as quickly as possible", "Password spraying exclusively uses rainbow tables offline"], "answer": 3, "explanation": "Password spraying is a horizontal attack where the adversary tests a small number of commonly used passwords (e.g., 'Winter2026!') across hundreds or thousands of different user accounts. This avoids exceeding individual account lockout thresholds (e.g., locking after 5 failed attempts on a single account). Traditional brute-force attacks test many passwords against a single targeted account.", "distractor_analysis": {"1": "Testing millions of passwords against a single account is a classic vertical brute-force attack, which quickly triggers account lockouts.", "2": "Rainbow tables are precomputed hash lookup tables used for offline password cracking, not online spraying.", "3": "Attacking WEP IVs is an obsolete wireless packet-injection attack."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["password-spraying", "brute-force", "attacks", "account-lockout"], "id": "C2-205"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "easy", "question": "Disabling the built-in Guest account, disabling unused local accounts, and renaming the default Administrator account are examples of which cybersecurity process?", "options": ["Hardware overclocking", "Network cable certification", "Monitor color calibration", "Operating system security hardening best practices"], "answer": 1, "explanation": "System hardening involves configuring operating system and service settings to minimize the attack surface by eliminating default vulnerabilities, such as disabling unnecessary guest accounts, renaming known default administrative accounts, closing unused ports, and applying strict security policies. Overclocking boosts clock speeds, cable certification tests wiring, and calibration adjusts display colors.", "distractor_analysis": {"1": "Hardware overclocking increases CPU/GPU clock frequencies beyond factory ratings to boost raw compute throughput.", "2": "Network cable certification uses specialized TDR/fluke testers to verify Cat6/6A wire map and attenuation standards.", "3": "Color calibration aligns display RGB profiles for professional graphic print accuracy."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["hardening", "default-accounts", "security-best-practices", "administrator"], "id": "C2-206"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "When does Full Device Encryption (FDE) on corporate smartphones and tablets protect stored corporate data from extraction?", "options": ["When developer USB debugging is enabled and connected to untrusted computers", "When third-party app sideloading is permitted without restriction", "When the device is powered off or locked with a strong passcode/biometric authentication", "When the device is left unlocked on a public table"], "answer": 2, "explanation": "Full Device Encryption (FDE) protects data at rest by securing cryptographic keys inside hardware security modules (Secure Enclave / Titan chip). When the device is powered off or locked, the keys are locked in memory, rendering flash storage unreadable without the user's passcode or biometric validation. Leaving screens unlocked, enabling unauthenticated USB debugging, and unvetted sideloading compromise this protection.", "distractor_analysis": {"1": "If the screen is left unlocked, the cryptographic keys reside in active RAM and data is freely readable by anyone holding the device.", "2": "Unrestricted USB debugging permits extraction of application data via command-line ADB bridge tools.", "3": "Sideloading unverified applications introduces malware that can execute within user space while the device is unlocked."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "full-device-encryption", "data-at-rest", "screen-lock"], "id": "C2-207"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows workstation frequently crashes with a Blue Screen stop code `MEMORY_MANAGEMENT`. Which physical hardware subsystem should the technician test FIRST?", "options": ["Mouse optical sensor DPI", "System RAM modules using Windows Memory Diagnostic or MemTest86", "USB headset audio equalization profiles", "Display monitor color profile"], "answer": 3, "explanation": "The `MEMORY_MANAGEMENT` stop error (bugcheck `0x0000001A`) indicates that the Windows memory manager detected a severe memory corruption or parity fault, almost always caused by defective, overheating, or mismatched physical RAM modules. Running memory diagnostics (e.g., `mdsched.exe`) and testing individual DIMMs isolates bad RAM. Headsets, monitors, and mice do not cause kernel memory management stop codes.", "distractor_analysis": {"1": "Headset EQ presets operate at user-level audio software layers and cannot cause kernel memory manager stop errors.", "2": "Monitor color profiles manage RGB lookup tables in display software and do not cause physical memory errors.", "3": "Mouse DPI settings govern optical tracking speed and have zero relation to RAM silicon hardware integrity."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["bsod", "memory-management", "ram", "troubleshooting"], "id": "C2-208"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Following a recent software update, a corporate CRM application crashes immediately upon launch. What is the MOST appropriate initial software troubleshooting procedure?", "options": ["Reimage every workstation in the entire company", "Inspect the Event Viewer Application log for crash details and repair the application or roll back the update", "Replace the core datacenter Top-of-Rack network switch", "Add two additional batteries to the facility UPS"], "answer": 1, "explanation": "When an application crashes post-update, checking Event Viewer (Application log for Event ID 1000) reveals the faulting module, exception code, and DLL. Technicians can then perform an in-place software repair via Settings/Control Panel or uninstall/roll back the problematic update. Reimaging all PCs, replacing network switches, and adding UPS batteries are completely unnecessary and disruptive.", "distractor_analysis": {"0": "Reimaging the entire enterprise company fleet is an extreme, unwarranted overreaction for a single software update glitch.", "2": "Top-of-Rack switches handle datacenter Ethernet packet switching and have no connection to local client application crashes.", "3": "UPS batteries provide emergency backup power during AC outages and do not resolve software update bugs."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["troubleshooting", "application-crash", "event-viewer", "rollback"], "id": "C2-209"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "A corporate mobile application freezes and force-closes repeatedly on an Android tablet. What is the recommended first-level user troubleshooting step?", "options": ["Replace the datacenter power distribution unit (PDU)", "Reflash network switch ASICs", "Degauss the tablet with an industrial electromagnet", "Force stop the application and clear the app cache/data in Settings -> Apps"], "answer": 1, "explanation": "When an isolated mobile app misbehaves or crashes, the first step is force-closing the application and clearing its cached temporary files in Settings -> Apps. If that fails, uninstalling and reinstalling the app resolves corrupted data. PDU replacement, switch flashing, and degaussing are absurd and destructive.", "distractor_analysis": {"1": "Datacenter PDUs distribute AC power to server racks and have zero connection to local mobile app memory crashes.", "2": "Reflashing switch ASICs is a network infrastructure maintenance task unrelated to mobile application software.", "3": "Applying a degausser to a mobile tablet will permanently destroy the display, inductive coils, and internal electronics."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "app-crash", "cache-clear", "force-stop"], "id": "C2-210"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Windows Update fails repeatedly on a client workstation with error code `0x80070002`. Which built-in recovery steps should the technician execute first?", "options": ["Physically remove half the RAM from the motherboard", "Set the motherboard BIOS date back thirty years", "Run the Windows Update Troubleshooter and reset the SoftwareDistribution cache folder", "Disable the network adapter permanently"], "answer": 2, "explanation": "Windows Update errors often stem from corrupted cached download files in `%WinDir%\\SoftwareDistribution` or stopped background services (BITS, wuauserv, cryptsvc). Running the Windows Update Troubleshooter (Settings -> Troubleshoot) and resetting update components clears stuck states. Disabling NICs, pulling RAM, and falsifying system dates break system functionality.", "distractor_analysis": {"1": "Disabling the network adapter cuts off all internet connectivity, preventing Windows Update from downloading any updates.", "2": "Removing functional RAM reduces system memory without addressing corrupted Windows Update temporary download files.", "3": "Falsifying the system date breaks TLS/SSL certificate validation and prevents all secure HTTPS updates."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-update", "troubleshooting", "update-troubleshooter", "software-distribution"], "id": "C2-211"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user reports extreme system sluggishness, with Task Manager showing 100% active disk utilization on a mechanical HDD. What is the BEST immediate software mitigation while planning a hardware SSD upgrade?", "options": ["Disconnect power while the system is writing data", "Inspect Task Manager for high-I/O processes, disable unnecessary startup applications, and scan for malware", "Unplug the CPU cooling fan", "Disable virtual memory paging entirely without performance analysis"], "answer": 3, "explanation": "100% disk utilization on spinning HDDs is commonly caused by startup application bloat, background Windows Search indexing storms, SysMain/Superfetch thrashing, or background malware activity. Disabling non-essential startup apps in Task Manager and running anti-malware scans frees up disk bandwidth. Unplugging fans causes thermal shutdown, disabling paging causes out-of-memory crashes, and pulling power corrupts data.", "distractor_analysis": {"1": "Unplugging the CPU fan causes immediate thermal throttling and emergency CPU shutdown due to overheating.", "2": "Disabling the paging file completely causes memory exhaustion crashes when RAM-intensive applications allocate memory.", "3": "Disconnecting power during active disk writes causes severe NTFS file system corruption and data loss."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["disk-performance", "100-percent-disk", "task-manager", "startup-apps"], "id": "C2-212"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "A mobile device cannot download or install a required OS security update due to an 'Insufficient Storage Available' error. What is the BEST first action?", "options": ["Replace the handset, since the storage chip has worn out", "Point the Wi-Fi DNS at 127.0.0.1 to force a local update cache", "Turn on Airplane Mode so the update downloads over cellular later", "Offload unused apps, clear caches, and move old photos and video off the device"], "answer": 1, "explanation": "Mobile operating system updates require several gigabytes of free scratch space to download and unpack installation packages. Freeing storage by removing unused apps, clearing media caches, and offloading photos to cloud storage provides the required capacity. Chipset replacement is impossible on mobile devices, loopback DNS breaks internet, and Airplane Mode stops updates.", "distractor_analysis": {"1": "A full volume is not a worn volume, and the internal flash is not a serviceable part.", "2": "127.0.0.1 is the device itself, so name resolution stops working entirely.", "3": "Airplane Mode disables the radios, so nothing downloads at all."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "insufficient-storage", "os-updates", "space"], "id": "C2-213"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "When opening a web browser, a user is immediately redirected to a deceptive website flashing red banners claiming 'System Heavily Infected - Call Tech Support Now'. What is the root cause?", "options": ["A successful HSTS web certificate negotiation", "The Ethernet switch port is configured for full duplex", "Adware, browser hijacking, or a malicious browser extension displaying scareware", "The motherboard TPM 2.0 chip is functioning properly"], "answer": 2, "explanation": "Fake virus warnings in web browsers accompanied by emergency phone numbers are scareware / social engineering scams delivered via adware or compromised browser extensions (browser hijacking). TPM chips, HSTS security headers, and full-duplex switch ports are legitimate, healthy system components.", "distractor_analysis": {"1": "TPM 2.0 provides hardware cryptographic storage and does not generate web browser scareware pop-ups.", "2": "HSTS (HTTP Strict Transport Security) enforces HTTPS encryption and prevents unencrypted downgrades.", "3": "Full-duplex switch ports allow simultaneous bidirectional network transmission without generating browser pop-ups."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["scareware", "browser-redirects", "adware", "malware"], "id": "C2-214"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A domain user's profile fails to load in Windows, displaying a temporary profile notification. Where should the technician investigate to identify the root cause and repair the profile?", "options": ["Reset the display adapter driver and set the refresh rate back to 60 Hz", "Check the User Profile Service log in Event Viewer, then the ProfileList registry subkey", "Rebuild the search index from Indexing Options in Control Panel", "Clear the print spooler cache and restart the Print Spooler service"], "answer": 3, "explanation": "Temporary profiles occur when Windows cannot load a user's `NTUSER.DAT` hive. Investigating the Application event log (User Profile Service events) and checking `HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\ProfileList` for a SID ending with `.bak` reveals the profile corruption so it can be cleared and rebuilt. Monitor refresh rates, printer spoolers, and fan curves have no relation to user profile hives.", "distractor_analysis": {"1": "A broken search index slows Explorer searches. It has no bearing on whether the profile hive loads.", "2": "Spooler faults break printing only. The temporary profile message comes from the User Profile Service.", "3": "Display driver work fixes rendering faults, not profile load failures."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["user-profile", "temporary-profile", "corruption", "event-viewer"], "id": "C2-215"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows workstation continuously reboots before reaching the logon screen. Which recovery environment should the technician boot into to run Startup Repair or access System Restore?", "options": ["Printer diagnostic utility", "macOS Recovery Assistant on another PC", "BIOS monitor color calibration tool", "Windows Recovery Environment (WinRE)"], "answer": 1, "explanation": "The Windows Recovery Environment (WinRE) is the dedicated diagnostic and repair platform for Windows, accessible via boot media or after three consecutive failed boots. WinRE provides Startup Repair, System Restore, Command Prompt, and Safe Mode options. Printer tools, macOS recovery, and BIOS color tools cannot repair Windows boot loaders.", "distractor_analysis": {"1": "Printer diagnostic utilities test ink nozzles and paper feeds, lacking operating system bootloader repair capabilities.", "2": "macOS Recovery is designed exclusively for Apple Macintosh hardware and operating systems.", "3": "BIOS color calibration adjusts display panel contrast without repairing Windows boot loader binaries."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["winre", "boot-loop", "startup-repair", "troubleshooting"], "id": "C2-216"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A corporate smartphone battery drains completely within four hours while the phone feels warm in standby mode. Which software diagnostic step should be taken first?", "options": ["Enable mobile hotspot while streaming 4K video", "Ignore thermal warnings and charge with an uncertified fast charger", "Review Settings -> Battery to identify runaway background apps and inspect background refresh permissions", "Increase screen brightness to maximum permanently"], "answer": 2, "explanation": "Rapid battery drain accompanied by thermal heat on an idle mobile device points to a rogue background process, runaway app synchronization loop, location tracking abuse, or crypto-mining malware. Checking Settings -> Battery displays detailed power consumption per app, allowing the technician to restrict background activity or uninstall the misbehaving app. Max brightness, hotspots, and uncertified chargers worsen heat and drain.", "distractor_analysis": {"1": "Setting screen brightness to 100% places maximum power draw on the display backlight, accelerating battery discharge.", "2": "Running mobile hotspots while streaming video stresses CPU and cellular radios, generating extreme heat.", "3": "Using uncertified fast chargers on an overheating phone risks triggering battery thermal runaway and combustion."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "battery-drain", "hot-chassis", "background-activity"], "id": "C2-217"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A legacy business application fails with 'Access Denied' errors for standard non-administrative users because it attempts to write user configuration logs directly into `C:\\Program Files`. What is the BEST long-term remediation?", "options": ["Grant Everyone Modify on the whole Program Files tree", "Redirect the application to write under %LocalAppData%, or grant granular folder rights", "Add every standard user to the local Administrators group", "Turn off User Account Control on all workstations by policy"], "answer": 3, "explanation": "Windows security architecture protects `C:\\Program Files` from standard user write operations. Applications should write user logs and settings to `%LocalAppData%` or `%AppData%`. If the software cannot be reconfigured, granting granular Write/Modify NTFS permissions strictly to the application's specific subfolder maintains least privilege. Granting admin rights, disabling UAC, or using FAT32 destroys enterprise security.", "distractor_analysis": {"1": "Making users administrators fixes one app by removing protection from the entire machine.", "2": "Disabling UAC removes elevation prompts estate-wide and still leaves the file rights wrong.", "3": "Opening the whole Program Files tree lets any process rewrite installed binaries."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["least-privilege", "uac", "appdata", "program-files"], "id": "C2-218"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "Why do Mobile Device Management (MDM) systems flag jailbroken (iOS) or rooted (Android) smartphones as non-compliant and block corporate access?", "options": ["Rooting raises radio power beyond the regulatory limit for the region", "Jailbreaking disables the SIM slot, so the device cannot be traced", "Rooted devices cannot render encrypted attachments in the mail client", "Rooting removes kernel sandboxing, so platform controls no longer protect data"], "answer": 1, "explanation": "Rooting and jailbreaking bypass operating system privilege boundaries and disable kernel security controls (such as application sandboxing, code signing enforcement, and secure boot checks). This allows malicious apps to access corporate data, capture keystrokes, and intercept communications, creating unacceptable risk that causes MDM policies to revoke access. It does not alter Wi-Fi limits, SIM hardware, or PDF rendering.", "distractor_analysis": {"1": "Transmit power is fixed by the radio firmware and regulatory tables, not by root access.", "2": "Jailbreaking is a software change. The SIM slot keeps working.", "3": "Rendering still works. The concern is that nothing stops a malicious app reading that data."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "jailbreak", "rooting", "mdm-compliance"], "id": "C2-219"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's workstation displays persistent pop-up alerts from 'Antivirus Clean Master Pro' demanding payment to clean 50 infected files, even though Windows Defender is healthy. How should the technician remediate this?", "options": ["Turn off Defender so the two scanning engines stop conflicting", "Reimage the workstation before collecting any evidence", "Treat it as scareware, scan with trusted tools, remove the rogue extension, and brief the user", "Pay the fee so the pop-ups stop, then reclaim it on expenses"], "answer": 2, "explanation": "Fake antivirus alerts that demand payment are scareware designed to defraud users. Technicians should treat them as malware: isolate the system, remove suspicious programs and browser add-ons, run full scans with legitimate enterprise antimalware, and educate the user (Step 7 of CompTIA methodology). Paying extortion funds crime, disabling Defender leaves machines defenseless, and reformatting SANs causes massive collateral downtime.", "distractor_analysis": {"1": "Paying funds the operation and buys nothing. The product is fake.", "2": "Defender is the healthy engine here. Disabling it removes the only real protection on the box.", "3": "Reimaging is disproportionate for scareware and destroys the evidence of how it arrived."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-remediation", "scareware", "fake-antivirus", "pups"], "id": "C2-220"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows background service configured with an 'Automatic' startup type fails to start upon system boot, causing dependent applications to crash. Where should the technician look to diagnose the specific service failure reason?", "options": ["Open Resource Monitor and watch the handle count for the service", "Open services.msc for dependencies, then read the System log in Event Viewer", "Open Reliability Monitor and export the stability index history", "Open Task Scheduler and check the triggers on the logon tasks"], "answer": 3, "explanation": "When an Automatic service fails to start, opening `services.msc` allows technicians to verify the service account credentials, startup parameters, and prerequisites on the Dependencies tab. Concurrently, checking the Windows `System` log in Event Viewer (filtering for Service Control Manager Event IDs 7000, 7001, 7009) provides exact error codes (e.g., logon failure, timeout, missing binary). Display calibration, mouse trails, and emoji settings are irrelevant.", "distractor_analysis": {"1": "Reliability Monitor summarises stability trends. It does not give the service error code.", "2": "Task Scheduler runs tasks, not services, so the failing item will not appear there.", "3": "Resource Monitor needs a running process. The service never started."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["services", "services-msc", "event-viewer", "service-failure"], "id": "C2-221"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "Domain users cannot authenticate to network shares or log into workstations, receiving Kerberos authentication errors. The technician discovers the workstation clock is 12 minutes ahead of the Domain Controller. What is the root cause and remediation?", "options": ["The workstation has lost its computer account password with the domain", "The DNS suffix search order no longer lists the internal domain", "The site link cost is forcing authentication to a distant domain controller", "Kerberos allows only five minutes of clock skew; sync the workstation to the DC time source"], "answer": 1, "explanation": "Kerberos authentication uses timestamps inside tickets to prevent replay attacks and enforces a strict maximum clock skew threshold (default: 5 minutes) between clients and Domain Controllers. If the client clock drifts beyond 5 minutes, Kerberos ticket validation fails completely. Resynchronizing system time via NTP (`w32tm /resync`) resolves the issue. Link speed, desoldering TPMs, and FAT32 are destructive or irrelevant.", "distractor_analysis": {"1": "A broken machine account gives a trust relationship error, and the clock skew here is the stated fact.", "2": "A suffix problem shows as a name that cannot be found, not as a Kerberos time error.", "3": "A distant DC adds latency. It does not produce a skew error when the clock itself is wrong."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["kerberos", "ntp", "time-sync", "authentication-failure"], "id": "C2-222"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user's corporate smartphone connects to Wi-Fi normally, but cellular mobile data fails completely after traveling overseas. What basic checks should the technician perform FIRST?", "options": ["Check the VPN profile, since a stale tunnel blocks all mobile data", "Check that Airplane Mode is off and Bluetooth tethering is disabled", "Check Cellular Data, Data Roaming, SIM or eSIM status, and the carrier APN", "Check Wi-Fi Assist and the DNS servers set on the Wi-Fi profile"], "answer": 2, "explanation": "Cellular data failures after international travel typically stem from: 1. Data Roaming being disabled in Settings, 2. Cellular Data toggle turned off, 3. Inactive or invalid carrier roaming profile, or 4. Misconfigured Access Point Name (APN) settings. RAID cache, GPU VRAM, and POST LEDs are server/desktop hardware components not found on smartphones.", "distractor_analysis": {"1": "Wi-Fi already works, so the Wi-Fi profile is not the fault domain. The cellular path is.", "2": "A stale tunnel would break Wi-Fi traffic as well. Wi-Fi is healthy, so the VPN is not the blocker.", "3": "Airplane Mode would kill Wi-Fi too, and tethering does not gate the device's own data path."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "cellular-data", "apn", "sim"], "id": "C2-223"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Following an incomplete application uninstallation, multiple desktop programs fail to launch with errors stating that required DLL files are missing. What is the proper resolution?", "options": ["Copy the DLL from another workstation into the System32 directory", "Repair or reinstall the application and its Visual C++ runtime packages", "Register the missing DLL manually with regsvr32 from any download site", "Roll the machine back to a restore point from before Windows was installed"], "answer": 3, "explanation": "Missing DLL errors occur when shared libraries are deleted or unlinked during incomplete software removals. Repairing the application, reinstalling the software, or running the official Microsoft Visual C++ Redistributable / .NET installers restores the missing shared DLL binaries in `%SystemRoot%\\System32` or application folders. Patch cables, DHCP leases, and exFAT formatting do not replace software DLLs.", "distractor_analysis": {"1": "Pulling a system library off a random download site is a malware delivery route, not a fix.", "2": "Restore points only exist after installation. There is no point earlier than the build itself.", "3": "Hand-copying a DLL leaves the registration and version dependencies wrong, so the fault returns."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["dll-missing", "redistributables", "runtime", "application-errors"], "id": "C2-224"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "A traveling executive working on an airplane without internet access cannot open a Rights-Managed (IRM) encrypted email attachment on their laptop. What is the technical requirement causing this limitation?", "options": ["The attachment uses a compression codec the offline mail client cannot unpack", "Cached Exchange mode strips attachments over 25 MB while the client is offline", "The laptop clock has drifted, so the message signing certificate reads as expired", "IRM content needs the licensing server to issue a use license, unless credentials were cached offline"], "answer": 1, "explanation": "Information Rights Management (IRM) and encrypted messaging protect data by requiring client software to communicate with a centralized rights management server (e.g., Azure Information Protection) to validate permissions and acquire decryption keys. Without internet connectivity, opening encrypted files fails unless rights and licenses were pre-cached for offline access. Heatsinks, Cat 3 cables, and ISA slots are unrelated.", "distractor_analysis": {"1": "IRM failures are a licensing problem, not a compression problem. The client can unpack the container; it cannot get a use license.", "2": "Cached mode does not strip attachments by size. The file is present on disk and still will not open.", "3": "Clock drift breaks certificate validation and would show a signature warning, not a rights management prompt."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["encryption", "irm", "email-security", "keys"], "id": "C2-225"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A shared network printer queue becomes unresponsive, with ten print jobs displaying 'Error - Printing' that cannot be canceled. What software troubleshooting procedure clears the stuck queue?", "options": ["Restart the Remote Procedure Call service so the queue re-registers", "Flush the local DNS cache so the print server name resolves again", "Stop the Print Spooler service, clear the PRINTERS spool folder, then start the service", "Delete and re-add the printer using the vendor v4 driver package"], "answer": 2, "explanation": "When print jobs lock up in Windows, stopping the Print Spooler service (`net stop spooler`), deleting the corrupt spool files (`.shd` and `.spl`) from `C:\\Windows\\System32\\spool\\PRINTERS`, and restarting the service (`net start spooler`) purges the stuck print queue and restores printing. Thermal paste, BIOS splash screens, and NX bits have no relationship with printer spoolers.", "distractor_analysis": {"1": "Reinstalling the queue may help a driver fault, but the stuck spool files stay on disk and jam the new queue too.", "2": "RPC is a system service other components depend on. Restarting it is disruptive and does not clear spool files.", "3": "Name resolution is fine, since the jobs reached the queue. The spool folder is the blockage."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["print-spooler", "services", "troubleshooting", "stuck-jobs"], "id": "C2-226"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "easy", "question": "Windows displays a 'Your computer is low on memory' alert when a user opens multiple memory-intensive CAD models and browser tabs. What is the BEST immediate software action?", "options": ["Uninstall the network adapter driver to free kernel pool memory", "Close unused applications, check commit charge in Task Manager, and plan a RAM upgrade", "Delete the System32 directory to reclaim space on the C: drive", "Turn off the paging file so Windows stops swapping to disk"], "answer": 3, "explanation": "Low memory warnings occur when combined physical RAM and paging file commit limits are reached. The immediate resolution is closing high-memory applications and background processes via Task Manager. For chronic workloads, installing additional physical RAM modules provides a permanent solution. Deleting System32, disabling paging, and deleting NIC drivers cause system destruction or outages.", "distractor_analysis": {"1": "Deleting System32 destroys the installation. The warning is about memory, not disk space.", "2": "Removing the paging file makes low-memory conditions worse and forces hard application failures.", "3": "A network driver holds a trivial amount of pool memory and removing it drops the machine off the network."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["memory-pressure", "low-memory", "task-manager", "ram"], "id": "C2-227"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "An employee flashes an unsupported older operating system version onto their corporate smartphone. The MDM console immediately marks the device non-compliant. What is the expected MDM policy response?", "options": ["The employee is automatically granted Domain Administrator privileges", "The enterprise Active Directory database is permanently deleted", "Corporate network firewalls are disabled automatically", "Corporate email, VPN, and resource access are automatically revoked until the device is updated to an approved, patched OS version"], "answer": 1, "explanation": "MDM compliance policies mandate minimum operating system versions and security patch levels to ensure known vulnerabilities are closed. When a device runs an unsupported or downgraded OS build, the MDM posture engine flags it as non-compliant and revokes corporate data access (email, Microsoft 365, internal VPN) via conditional access. It does not grant domain admin rights or disable firewalls.", "distractor_analysis": {"1": "Non-compliant devices are restricted from corporate access, never granted elevated Domain Admin rights.", "2": "MDM compliance evaluations affect individual endpoints and never delete central Active Directory databases.", "3": "Enterprise network perimeter firewalls are completely unaffected by individual mobile device compliance states."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mdm", "compliance", "mobile-security", "os-version"], "id": "C2-228"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "In which scenario is using Windows System Restore (`rstrui.exe`) the MOST appropriate recovery solution?", "options": ["When the disk reports SMART errors and the volume will not mount", "When the machine is being rebuilt for a different user and department", "When a recent install or driver update caused instability and a restore point exists", "When user documents were deleted and need to be recovered from disk"], "answer": 2, "explanation": "Windows System Restore is designed to revert system files, registry keys, installed drivers, and software packages to a previously created snapshot (restore point) without altering user personal documents, making it ideal for rolling back unstable software or bad driver installations. It does not configure router BGP protocols, test fiber optics, or repair cracked screens.", "distractor_analysis": {"1": "System Restore does not roll back user documents. Use file history or the backup for that.", "2": "Failing media is a hardware problem. A restore point on that disk cannot be trusted or read.", "3": "A rebuild for a new owner calls for a clean image, not a rollback of the old state."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["system-restore", "restore-point", "recovery", "troubleshooting"], "id": "C2-229"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "An application displays garbled text, missing glyphs, and overlapping UI characters after a user manually installed unverified third-party font packages. How should the technician resolve this?", "options": ["Flash the motherboard Baseboard Management Controller (BMC) firmware", "Restore default Windows system fonts and remove corrupted third-party font packages in Settings -> Personalization -> Fonts", "Replace all power supply cables inside the computer chassis", "Change the RAID controller stripe size"], "answer": 3, "explanation": "Corrupted or incompatible third-party font packages can break application UI rendering and text display. Navigating to Settings -> Personalization -> Fonts and restoring default system fonts or removing corrupt font files resolves the rendering glitches. Power cables, RAID stripe sizes, and BMC firmware have no role in application typography rendering.", "distractor_analysis": {"1": "Power supply internal modular cables deliver DC electricity and cannot cause application font rendering glitches.", "2": "Modifying RAID stripe size requires reformatting the storage array and has zero connection to font rendering.", "3": "BMC firmware manages out-of-band server hardware telemetry, completely unrelated to desktop typography."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["fonts", "ui-glitches", "troubleshooting", "display"], "id": "C2-230"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "A corporate workstation suddenly fails to connect to the secure 802.1X corporate Wi-Fi network, while other devices connect normally. Event logs show certificate validation failure because the client digital certificate expired yesterday. What is the proper remediation?", "options": ["Disable the wireless network adapter permanently", "Configure a static APIPA address (169.254.1.1) on the Wi-Fi adapter", "Disable all wireless encryption on corporate access points", "Renew and re-enroll the client digital certificate through the enterprise Public Key Infrastructure (PKI) / MDM portal"], "answer": 1, "explanation": "802.1X enterprise wireless with EAP-TLS requires valid, unexpired X.509 client certificates to authenticate endpoints to the RADIUS server. When a client certificate passes its expiration date, authentication is rejected. Renewing or re-enrolling the certificate via the corporate PKI/MDM resolves the failure. Disabling Wi-Fi, using APIPA, or removing encryption on enterprise APs is wrong.", "distractor_analysis": {"1": "Disabling the network adapter cuts off wireless capability permanently rather than solving the expired certificate.", "2": "APIPA addresses are non-routable link-local IPs that do not authenticate to 802.1X enterprise networks.", "3": "Disabling encryption across corporate access points exposes all company network traffic to cleartext interception."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["certificates", "802.1x", "pki", "network-access"], "id": "C2-231"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "After entering credentials at the Windows login screen, the desktop appears completely black with only a visible, moving mouse cursor. What is the FASTEST recovery action?", "options": ["Replace the external monitor cable and power strip", "Permanently disable the keyboard in Device Manager", "Press `Ctrl + Shift + Esc` to open Task Manager, click 'Run new task', and launch `explorer.exe`", "Immediately shred the physical SSD in an industrial grinder"], "answer": 2, "explanation": "A black screen with a functional mouse cursor after login indicates that the user profile loaded but the Windows graphical shell process (`explorer.exe`) hung or failed to initialize. Pressing `Ctrl + Shift + Esc` launches Task Manager directly, where selecting 'Run new task' and typing `explorer.exe` manually restarts the desktop interface, taskbar, and icons. Shredding SSDs, replacing cables, and disabling keyboards are incorrect.", "distractor_analysis": {"1": "Shredding the storage drive destroys the hardware and user data when a simple process restart resolves the issue.", "2": "The monitor cable is working perfectly because the mouse cursor is clearly visible on screen.", "3": "Disabling the keyboard prevents all user input and does not initialize the Windows desktop shell."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["black-screen", "explorer", "task-manager", "shell-recovery"], "id": "C2-232"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A technician runs `sfc /scannow` on a crashing Windows machine, but it reports: 'Windows Resource Protection found corrupt files but was unable to fix some of them.' Why is executing `DISM /Online /Cleanup-Image /RestoreHealth` the proper next step?", "options": ["It clears the SoftwareDistribution download cache and nothing else", "It rebuilds the WinSxS component store from Windows Update sources so the next SFC pass succeeds", "It rewrites the boot configuration data store so Windows can find the system partition", "It runs a full chkdsk pass that relocates bad clusters before SFC retries"], "answer": 3, "explanation": "The System File Checker (`sfc`) relies on the local Windows Component Store (`WinSxS`) to obtain replacement files. If the Component Store itself is corrupted, SFC cannot repair damaged files. Running `DISM /Online /Cleanup-Image /RestoreHealth` connects to Windows Update to download healthy replacement component packages, repairing the source repository so a subsequent `sfc /scannow` can successfully complete. DISM does not repair hardware, RAID, or BGP.", "distractor_analysis": {"1": "Rewriting the BCD is bootrec work. The machine already boots; the component store is what is damaged.", "2": "chkdsk fixes file system metadata and bad sectors. It does not replace corrupt protected system files.", "3": "Clearing SoftwareDistribution resets the update client. It supplies no replacement component store payload."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["dism", "sfc", "restorehealth", "system-integrity"], "id": "C2-233"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A datacenter engineer needs to modify inbound firewall rules on production database clusters. Which formalized operational process mandates submitting an RFC, assessing risk, obtaining Change Advisory Board (CAB) approval, and documenting a rollback plan?", "options": ["Shadow IT unapproved implementation", "Uncoordinated weekend maintenance", "Bypassing tickets to speed up delivery", "Formal Change Management process"], "answer": 1, "explanation": "Change Management is the formal governance framework designed to minimize outages and business disruption caused by changes. It requires submitting a Request for Change (RFC), performing risk analysis, testing in a sandbox, scheduling within a maintenance window, obtaining CAB approval, and preparing a validated rollback plan. Shadow IT and skipping approvals cause enterprise outages.", "distractor_analysis": {"1": "Shadow IT refers to unauthorized, undocumented hardware or software deployments that bypass corporate IT oversight.", "2": "Uncoordinated changes without documented plans or CAB approval lead to unexpected production downtime.", "3": "Bypassing ticketing systems eliminates audit trails and violates compliance and governance policies."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "cab", "firewall-change", "rollback-plan"], "id": "C2-234"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "easy", "question": "Which backup rule specifies maintaining three copies of data, stored across two different media types, with at least one copy kept in an offsite or cloud location?", "options": ["A single USB thumb drive left plugged into the server", "Taking desktop screenshots of critical files", "The 3-2-1 backup rule", "RAID 0 storage striping alone"], "answer": 2, "explanation": "The 3-2-1 backup rule is the foundational standard for enterprise data protection: 3 copies of data (production + 2 backups), stored on 2 different media types (e.g., disk array + tape or cloud), with 1 copy stored Offsite. RAID 0 provides zero redundancy, single USB drives lack offsite protection, and screenshots are not database backups.", "distractor_analysis": {"1": "RAID 0 stripes data across drives with zero fault tolerance; if one drive fails, all data on the array is lost.", "2": "Leaving a single USB flash drive connected to the server provides zero media diversity and fails if the server room burns down.", "3": "Taking screenshots is not a viable or restorable enterprise database backup strategy."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["3-2-1-rule", "backup-strategy", "disaster-recovery", "offsite"], "id": "C2-235"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "easy", "question": "Before opening a server chassis to install additional DDR5 RAM modules, what electrostatic discharge (ESD) safety precautions should a technician take?", "options": ["Spray liquid glass cleaner directly onto the RAM golden edge contacts", "Wear an antistatic ESD wrist strap connected to unpainted chassis metal and work on a grounded ESD mat", "Wear a heavy wool sweater and shuffle feet on carpet", "Place open electronic circuit boards directly on conductive aluminum foil while powered"], "answer": 3, "explanation": "Electrostatic discharge (ESD) can destroy delicate semiconductor circuitry with voltages far below human perception. Technicians must wear a properly grounded ESD wrist strap, work on an ESD-safe dissipative mat, handle memory modules by their non-conductive edges, and store components in antistatic bags. Wool clothes generate static, foil shorts live circuits, and liquids corrode contacts.", "distractor_analysis": {"1": "Wool clothing and walking across carpet generate thousands of volts of static electricity, drastically increasing ESD risk.", "2": "Placing powered circuit boards on conductive foil creates immediate short circuits and destroys electronics.", "3": "Spraying liquid cleaners onto gold contacts causes corrosion, liquid ingress, and electrical shorts."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["esd", "safety", "wrist-strap", "hardware-handling"], "id": "C2-236"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "easy", "question": "Which safety document must be consulted to review handling, storage, and emergency spill response protocols for hazardous datacenter substances such as printer toner, isopropyl alcohol, or UPS battery acid?", "options": ["GPU overclocking profile", "DNS zone transfer record", "VLAN trunking protocol configuration", "Safety Data Sheet (SDS / MSDS)"], "answer": 1, "explanation": "Safety Data Sheets (SDS), formerly known as MSDS, are federally mandated documents detailing the chemical composition, health hazards, personal protective equipment (PPE), safe handling procedures, and emergency spill/first-aid instructions for hazardous substances. GPU profiles, DNS records, and VLAN configs have no safety information.", "distractor_analysis": {"1": "GPU overclocking profiles configure graphics clock speeds and voltages, providing zero chemical safety guidance.", "2": "DNS zone transfer records manage domain name replication between nameservers.", "3": "VLAN trunking protocols manage layer 2 virtual network tags across network switches."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["sds", "msds", "chemical-safety", "spill-response"], "id": "C2-237"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "During an incident response investigation where a corporate laptop is seized for legal evidence, why is maintaining a strict 'Chain of Custody' form critical?", "options": ["It authorizes the technician to open and read the user's personal files", "It sets the retention period before the laptop can be reimaged", "It documents everyone who handled the media, which keeps the evidence admissible", "It records the exact imaging tool version used during acquisition"], "answer": 2, "explanation": "Chain of Custody is the formal chronological documentation recording the seizure, custody, transfer, analysis, and disposition of physical and electronic evidence. Maintaining an unbroken chain of custody ensures that evidence has not been tampered with and remains legally admissible in a court of law. Wallpapers, fan curves, and cable colors are unrelated.", "distractor_analysis": {"1": "Tool and hash detail belong on the acquisition record. Chain of custody tracks possession over time.", "2": "Custody paperwork does not grant a technician permission to browse content. Legal counsel scopes that.", "3": "Retention and disposal come from the evidence handling policy, after the case closes."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["chain-of-custody", "incident-response", "evidence", "forensics"], "id": "C2-238"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "How does a ticketing system primarily assist IT operations teams in daily service delivery?", "options": ["By assigning public IPv4 blocks to each branch office", "By logging, prioritizing, assigning and tracking requests so SLA targets are met", "By replacing the hardware monitoring platform used in the NOC", "By removing the need for a separate knowledge base"], "answer": 3, "explanation": "Ticketing systems (such as ServiceNow or Jira Service Desk) provide a centralized platform to record, categorize, prioritize, assign, track, and document customer incidents and requests, ensuring accountability, historical knowledge capture, and compliance with contractual SLAs. They do not replace hardware monitoring, eliminate documentation, or allocate IPv4 space.", "distractor_analysis": {"1": "Monitoring detects faults. Ticketing tracks the work that follows and does not replace it.", "2": "A knowledge base holds the how. The ticket queue holds the what and the when.", "3": "Address allocation is an IPAM function and has no relationship to service delivery tracking."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["ticketing-systems", "incident-management", "sla", "documentation"], "id": "C2-239"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "What is the primary operational purpose of affixing barcode asset tags to company hardware and maintaining Configuration Management Database (CMDB) records?", "options": ["To give the service desk a warranty lookup for each monitor model", "To let finance depreciate assets on a fixed annual schedule", "To keep firmware revisions aligned across a switch stack", "To track configuration items across their whole lifecycle, from procurement to disposal"], "answer": 1, "explanation": "Asset management and CMDB tracking record detailed information about physical and logical Configuration Items (CIs)-including serial numbers, location, assigned user, warranty dates, purchase costs, and relationships-throughout their entire lifecycle from procurement to disposal. Asset tags have no effect on monitor pixels, beep code volume, or printer fusers.", "distractor_analysis": {"1": "Warranty lookup is one report the CMDB can feed. It is not why the database exists.", "2": "Depreciation is a finance use of the same data, downstream of the asset record itself.", "3": "Firmware alignment is handled by configuration management tooling on the devices."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["asset-management", "cmdb", "lifecycle", "hardware-tracking"], "id": "C2-240"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "easy", "question": "When communicating with an upset, frustrated customer whose workstation crashed during a payroll run, how should the technician conduct the interaction?", "options": ["Transfer the call to another queue so the user can cool down first", "Talk through the stack trace in detail so the user sees the complexity", "Stay calm, listen without interrupting, avoid jargon, and set clear expectations", "Explain that payroll should not have been run so close to the deadline"], "answer": 2, "explanation": "CompTIA professional customer service guidelines dictate that technicians remain calm, patient, and empathetic, listen actively without interrupting, avoid confusing jargon, clarify the problem, and communicate realistic timelines. Mocking users, hanging up, or arguing damages customer relationships and violates professional ethics.", "distractor_analysis": {"1": "Assigning blame during an outage escalates the call and solves nothing.", "2": "Passing the call along abandons the customer and loses the context you already have.", "3": "Technical depth the customer did not ask for reads as deflection. Give them status and a timeline."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "communication", "active-listening", "customer-service"], "id": "C2-241"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "easy", "question": "In datacenter operations, what is the primary purpose of writing PowerShell (`.ps1`) and Bash (`.sh`) scripts?", "options": ["To physically clean optical fiber transceivers", "To automate repetitive administrative tasks, bulk user provisioning, and scheduled maintenance workflows", "To replace physical deadbolt server room door locks", "To passively cool the server rack cold aisle"], "answer": 3, "explanation": "Scripting languages (PowerShell, Bash, Python) allow system administrators to automate repetitive operational tasks-such as batch account creation, log rotation, automated backups, patch deployments, and system health audits-increasing efficiency and reducing human error. Scripts cannot replace physical door locks, cool aisles, or clean fiber connectors.", "distractor_analysis": {"1": "Physical facility security requires mechanical deadbolts and electronic badge locks, not software scripts.", "2": "Datacenter cold aisle cooling is delivered by HVAC precision air conditioning units.", "3": "Cleaning optical fiber transceivers requires physical lint-free swabs and isopropyl cleaning tools."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "powershell", "bash", "automation"], "id": "C2-242"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "What core functionality do Remote Monitoring and Management (RMM) platforms provide for Managed Service Providers (MSPs)?", "options": ["Out-of-band console access to server hardware through a dedicated IPMI network", "Automated ordering of consumables such as toner for managed printers", "Power and cooling efficiency reporting for the facilities team", "Central monitoring, patch management, alerting and remote access across many endpoints"], "answer": 1, "explanation": "RMM (Remote Monitoring and Management) platforms deploy lightweight agent software to client computers and servers, enabling MSPs to centrally monitor system health, deploy software patches, execute remote scripts, receive alert notifications, and establish remote management sessions across distributed customer networks. They are not limited to local keyboards, toner deliveries, or PUE math.", "distractor_analysis": {"1": "Out-of-band console work is what iDRAC or iLO does on individual servers, not what an RMM platform is for.", "2": "Consumable ordering is a managed print service feature, a small slice of what an RMM covers.", "3": "Efficiency reporting belongs to DCIM tooling on the facilities side."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["rmm", "remote-management", "msp", "monitoring"], "id": "C2-243"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "medium", "question": "You are documenting the nightly backup schedule for a small office file server so the next technician can size the retention window. Which data does an incremental backup job capture?", "options": ["The whole volume on every run, regardless of modification time", "Only the system state and registry hives, not user data", "Everything changed since the last backup of any type, clearing the archive bit", "Everything changed since the last full backup, leaving the archive bit set"], "answer": 2, "explanation": "An Incremental backup captures only the files that have changed since the last backup of any kind (Full or Incremental) and clears the archive bit. This produces the fastest daily backup jobs and smallest storage footprint, but requires restoring the Full backup plus all subsequent incrementals in chronological order. Full backups copy everything, and DNS/BIOS are specific subsystems.", "distractor_analysis": {"1": "That is a differential. It grows against the last full and does not clear the archive bit.", "2": "Copying everything every run is a full backup. Incrementals exist to avoid that window.", "3": "System state is a separate backup selection, not the definition of an incremental job."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["incremental-backup", "backup-types", "archive-bit", "storage"], "id": "C2-244"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "medium", "question": "You are documenting the nightly backup schedule for a small office file server and comparing job types for restore speed. Which data does a differential backup job capture?", "options": ["Only open files, captured through a volume shadow copy", "Everything changed since the last full backup, leaving the archive bit set", "Everything changed since the last backup of any type, clearing the archive bit", "The whole volume on every run, regardless of the archive bit"], "answer": 3, "explanation": "A Differential backup copies all files that have changed since the last FULL backup without clearing the archive bit. Each daily differential grows in size, capturing cumulative changes since Sunday's full backup. Restoring requires only two backup sets: the last Full backup and the latest Differential backup. Memory dumps, ARP tables, and syslog rotation are specific subcomponents.", "distractor_analysis": {"1": "That describes an incremental. Clearing the archive bit is what makes each incremental depend on the one before it.", "2": "Copying the whole volume every run is a full backup, which is the job type the differential is meant to shorten.", "3": "Shadow copy is the mechanism that lets open files be read. It is not what selects the file set."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["differential-backup", "backup-types", "archive-bit", "restore"], "id": "C2-245"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "easy", "question": "What is the proper ergonomic lifting technique when moving heavy datacenter UPS batteries or rackmount servers?", "options": ["Bend at the waist and lift with the lower back while turning", "Lift with the arms extended to keep the load away from the body", "Drag the unit by its power cords to the edge of the rack", "Team lift or use a mechanical lift, bend at the knees, keep the back straight"], "answer": 1, "explanation": "Safe lifting procedures require bending at the knees (not the waist), keeping the load close to the body, keeping the back straight, lifting with the strong leg muscles, and avoiding twisting the torso under load. Heavy equipment (>40-50 lbs) mandates a team lift or mechanical server lift. Bending at the waist, lifting far from the chest, and pulling cords cause severe injury and damage.", "distractor_analysis": {"1": "Bending at the waist and twisting under load is the classic way to injure the lumbar spine.", "2": "Holding the load away from the body multiplies the leverage on the back.", "3": "Cords are not handles. This damages the equipment and risks dropping it on your feet."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["safety", "ergonomics", "lifting", "physical-safety"], "id": "C2-246"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "Why is maintaining strict software license compliance and tracking End-User License Agreements (EULAs) critical for an organization?", "options": ["EULA tracking sets the support window for firmware updates on network switches", "Seat counts decide how many concurrent RDP sessions the kernel will schedule", "Deploying past the licensed seat count breaches copyright and contract, exposing the company to penalties and audit", "License records decide which PCIe generation the vendor will certify for the platform"], "answer": 2, "explanation": "Software licensing compliance ensures that an organization does not install more software instances than it legally owns. Under-licensing exposes the enterprise to copyright infringement lawsuits, substantial financial penalties, and mandatory third-party software audits (e.g., BSA). Licensing has no effect on physical fan noise, PCIe bus speeds, or optical fiber wavelengths.", "distractor_analysis": {"1": "PCIe generation is a hardware specification. No licence document changes what the slot negotiates.", "2": "Firmware support windows come from the hardware support contract, not the software EULA.", "3": "Concurrent RDP sessions are capped by RDS licensing configuration, not by an application seat count."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["licensing", "compliance", "eula", "legal"], "id": "C2-247"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "hard", "question": "In digital forensics and incident response, what is the correct prioritization dictated by the 'Order of Volatility' when collecting digital evidence?", "options": ["Collect physical chassis barcode stickers before memory dumps", "Capture the most volatile data first (CPU registers/cache, routing tables, active RAM) before less volatile data (hard disks, backup media, printouts)", "Collect offline backup tapes first, then physical printouts, and finally active RAM", "Format all storage drives before capturing memory"], "answer": 3, "explanation": "The Order of Volatility dictates that evidence must be captured in order from most volatile (data that disappears immediately when power is cut) to least volatile. The standard order is: 1. CPU registers and cache, 2. Routing tables, ARP cache, process table, kernel statistics, 3. System RAM, 4. Temporary file systems, 5. Disk storage, 6. Remote logs, 7. Physical media/archives.", "distractor_analysis": {"1": "Offline backup tapes are non-volatile and will persist for years; capturing them first allows volatile RAM evidence to be lost.", "2": "Formatting drives destroys data and constitutes spoliation of forensic evidence.", "3": "Chassis stickers are permanent physical labels and should not be prioritized over volatile memory."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["order-of-volatility", "incident-response", "forensics", "evidence"], "id": "C2-248"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Under what circumstance is a documented rollback (backout) plan executed during a change management deployment?", "options": ["When the deployment finishes ahead of schedule with no errors logged", "When users report that the new behaviour is working as designed", "When the change advisory board reschedules the maintenance window", "When the change fails, hits unforeseen errors, or causes unacceptable downtime"], "answer": 1, "explanation": "A rollback (backout) plan is an essential risk mitigation procedure designed to be executed when an infrastructure change fails, encounters severe bugs, or causes unplanned outages during implementation, providing clear steps to restore the system to its pre-change operational baseline. It is not executed when changes succeed.", "distractor_analysis": {"1": "A clean, early finish is the success path. You verify and close, you do not roll back.", "2": "Working as designed is the acceptance criterion, not a rollback trigger.", "3": "A rescheduled window means the change has not run yet, so there is nothing to back out."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "rollback-plan", "backout", "risk-mitigation"], "id": "C2-249"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "Which statement accurately describes the operational difference and synergy between a Virtual Private Network (VPN) and Remote Desktop Protocol (RDP) for remote workers?", "options": ["A VPN removes resident malware from the client before the session is allowed", "Neither one needs auditing, because both are already encrypted", "A VPN builds the encrypted tunnel to the corporate LAN, and RDP runs the desktop session over it", "RDP builds the encrypted tunnel and the VPN supplies the graphical session"], "answer": 2, "explanation": "A Virtual Private Network (VPN) operates at the network layer to encapsulate and encrypt all IP traffic between a remote client and the corporate network, placing the client logically on the corporate LAN. Remote Desktop Protocol (RDP) operates at the application layer to stream graphical desktop video, keyboard, and mouse control. In enterprise environments, RDP is commonly routed through a secure VPN tunnel. VPNs do not delete malware, and all sessions should be logged.", "distractor_analysis": {"1": "The roles are reversed. RDP is the presentation protocol; the VPN is the transport.", "2": "A VPN moves packets. Posture and malware checks come from endpoint security, not from the tunnel.", "3": "Encryption protects the traffic in transit. It does not remove the need to log who connected."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "vpn", "rdp", "secure-access"], "id": "C2-250"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.10", "type": "single", "difficulty": "medium", "question": "What is an appropriate and secure operational practice when using Artificial Intelligence (AI) copilots and assistants in IT workflows?", "options": ["Allowing AI models to approve production change requests automatically without human CAB oversight", "Using AI to assist with drafting scripts, documentation, and troubleshooting analysis while strictly verifying all outputs and never inputting confidential credentials or proprietary data", "Pasting production database passwords and customer PII into public AI chatbots", "Blindly executing destructive AI-generated terminal commands without human review"], "answer": 3, "explanation": "Responsible and secure AI utilization in enterprise IT requires treating AI outputs as unverified drafts: human engineers must review and test all generated scripts in sandboxes, verify command syntax against documentation, and strictly protect data privacy by never submitting credentials, API keys, intellectual property, or PII into public AI tools. Pasting secrets into AI and blindly running unverified code creates massive risk.", "distractor_analysis": {"1": "Pasting production credentials and PII into public AI platforms causes severe data privacy breaches and leaks secrets.", "2": "Blindly executing AI commands without human verification risks catastrophic data loss due to AI hallucinations.", "3": "Change management governance requires human accountability; AI cannot replace CAB risk evaluation."}, "video_reference": {"title": "Managing AI - CompTIA A+ 220-1202 - 4.10", "url": "https://www.youtube.com/watch?v=oofb6ROU7LM", "duration": "10:38", "objective": "4.10"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["artificial-intelligence", "data-privacy", "verification", "copilot"], "id": "C2-251"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "Which set of operational documentation and procedures should be completed when onboarding a new employee into a corporate IT environment?", "options": ["Only a signed asset receipt and a desk allocation from facilities", "Only the security awareness training record kept by HR", "Only the change ticket that created the mailbox in Exchange", "Account provisioning, role-based access requests, asset assignment, and AUP sign-off"], "answer": 1, "explanation": "IT employee onboarding procedures include creating directory user accounts, provisioning mailbox and role-based permissions, issuing and tracking tagged hardware assets in the CMDB, configuring MFA tokens, and having the employee read and sign the corporate Acceptable Use Policy (AUP). Cafeteria menus, GPU specs, and paint colors are not IT identity onboarding procedures.", "distractor_analysis": {"1": "The hardware receipt is one item on the list. It leaves identity, access and policy untouched.", "2": "Training is required but proves nothing about what the account can reach.", "3": "A mailbox ticket is one provisioning task inside a wider onboarding record."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["onboarding", "documentation", "aup", "identity"], "id": "C2-252"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "In an IT support contract or managed service agreement, what is the primary purpose of a Service Level Agreement (SLA)?", "options": ["To set the hourly rate charged for out-of-hours callout work", "To record which technicians hold vendor certification for the platform", "To define measurable commitments such as uptime, response time, and time to resolve", "To list the hardware models the vendor will support on site"], "answer": 2, "explanation": "A Service Level Agreement (SLA) is a formal contract between a service provider (internal IT or external vendor) and a customer that establishes measurable performance metrics, such as guaranteed system availability/uptime percentages (e.g., 99.9%), maximum initial response times, and resolution targets. SLAs do not configure CPU microcode, RAM timings, or monitor gamma.", "distractor_analysis": {"1": "Supported models belong in the scope or coverage schedule, not the service level targets.", "2": "Rates sit in the commercial terms. An SLA measures performance, not price.", "3": "Certification lists are a staffing matter and are not the performance commitment."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["sla", "service-level-agreement", "metrics", "support"], "id": "C2-253"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "medium", "question": "How does structured horizontal and vertical cable management inside server racks improve datacenter operational efficiency?", "options": ["It extends the life of the TLS certificates on the switch stack", "It keeps airflow paths clear, removes trip hazards, and makes tracing a run quick", "It raises link speed past the Cat6 rating by controlling bend radius", "It lets the RAID controller recalculate parity across shelves faster"], "answer": 3, "explanation": "Structured cable management (using horizontal cable managers, vertical D-rings, and velcro ties) organizes power and data cabling away from exhaust fans, preventing heat buildup and maintaining front-to-back cold-aisle/hot-aisle airflow. It also eliminates physical snag hazards and allows technicians to trace and replace cables quickly during outages. It does not alter link speeds, RAID parity, or certificates.", "distractor_analysis": {"1": "Bend radius protects the cable from damage. It cannot raise a link above its rated category.", "2": "Parity work happens inside the controller and is unaffected by how cables are dressed.", "3": "Certificate lifetime is set by the issuing authority, not by cable management."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["cable-management", "datacenter", "airflow", "safety"], "id": "C2-254"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "easy", "question": "What is the proper environmental procedure for disposing of spent laser printer toner cartridges and depleted UPS lead-acid batteries?", "options": ["Put them in the general waste stream once the toner reservoir is empty", "Rinse the cartridge and battery casings before placing them in recycling", "Store them in the plant room until the annual facilities clear-out", "Follow local regulations, check the Safety Data Sheet, and use certified recycling"], "answer": 1, "explanation": "Laser toner (fine plastic polymer/iron oxide powder) and UPS batteries (lead and sulfuric acid) contain hazardous chemicals and heavy metals that pose severe environmental and fire risks. Organizations must follow local environmental e-waste regulations, consult SDS sheets, and return spent items through vendor recycling programs. Dumping in trash, flushing down drains, or burning causes severe pollution and violates environmental laws.", "distractor_analysis": {"1": "Residual toner and lead are both regulated. Empty does not mean safe for general waste.", "2": "Rinsing washes toner particulate and electrolyte into the drain, which is itself a violation.", "3": "Accumulating hazardous waste on site without a disposal route creates a compliance and fire risk."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "e-waste", "battery-disposal", "toner"], "id": "C2-255"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "easy", "question": "Why are professional appearance, punctuality, and respectful conduct critical soft skills for IT support technicians?", "options": ["They reduce the number of change approvals a technician must request", "They lower the licence cost of the remote support platform", "They build trust, project competence, and represent the organization well", "They shorten the mean time to repair recorded against each ticket"], "answer": 2, "explanation": "CompTIA Core 2 emphasizes professional soft skills: arriving on time, dressing appropriately, maintaining a tidy workspace, using respectful language, and actively listening build customer trust and confidence in the IT department. Soft skills do not physically alter network speeds, power supply wattage, or QoS packet headers.", "distractor_analysis": {"1": "Repair time is driven by diagnosis and parts, not by how the technician is dressed.", "2": "Change approval is governed by risk and policy, not by conduct.", "3": "Licence cost is a commercial term and is unaffected by soft skills."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "punctuality", "soft-skills", "communication"], "id": "C2-256"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "easy", "question": "What is the primary operational value of creating and maintaining Standard Operating Procedures (SOPs) in an IT knowledge base?", "options": ["They define the escalation path and on-call rota for major incidents", "They give repeatable step-by-step instructions, so work is consistent and onboarding is faster", "They replace the change approval board for routine maintenance work", "They record every asset serial number for the annual audit"], "answer": 3, "explanation": "A Standard Operating Procedure (SOP) is a formal, documented set of step-by-step instructions compiled by an organization to guide technicians in performing routine and complex operations consistently. SOPs ensure quality control, reduce errors, streamline troubleshooting, and accelerate onboarding. They do not promote guessing, bypass security controls, or eliminate backup requirements.", "distractor_analysis": {"1": "An SOP describes how to do the work. It does not remove the requirement for change approval.", "2": "Serial numbers live in the asset register or CMDB, not in a procedure document.", "3": "Escalation and rota belong to the incident management plan, which an SOP may reference but does not replace."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["documentation", "sop", "standard-operating-procedure", "knowledge-base"], "id": "C2-257"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "medium", "question": "Why do backup architectures commonly execute a Full backup once weekly followed by nightly Incremental backups, rather than running a Full backup every single night?", "options": ["To eliminate the need to ever perform test restores", "To avoid having to maintain offsite backup copies", "To bypass the need for backup encryption", "To drastically reduce the nightly backup window duration and save network bandwidth and storage capacity"], "answer": 1, "explanation": "Running a full backup of multi-terabyte datasets every night consumes massive network bandwidth, overloads production storage I/O, and requires immense storage capacity. Performing a weekly Full backup combined with nightly Incremental backups captures only changed blocks each night, dramatically shortening the backup window and saving storage space. Test restores, offsite copies, and encryption remain mandatory.", "distractor_analysis": {"1": "Test restores remain essential regardless of backup strategy to verify that the backup chain can be successfully reconstructed.", "2": "Maintaining offsite backup copies is required by the 3-2-1 rule regardless of whether fulls or incrementals are used.", "3": "Backup encryption is mandatory to protect sensitive company data at rest across all backup tiers."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-strategy", "full-backup", "incremental", "backup-window"], "id": "C2-258"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "When a major database infrastructure change is scheduled to execute during an approved 02:00 AM maintenance window, what responsibilities must the systems engineer fulfill?", "options": ["Skip the notification because the window was already approved in the ticket", "Close the change ticket at the start so the overnight queue stays clean", "Notify stakeholders, follow the approved plan, watch post-change telemetry, and roll back if needed", "Silence monitoring for the window so alerts do not page the on-call engineer"], "answer": 2, "explanation": "During a scheduled maintenance window, the implementing engineer must follow the approved RFC plan step by step, communicate status milestones to stakeholders, monitor system health, verify functionality, and be prepared to execute the rollback plan before the window expires if critical faults occur. Shifting times unannounced, disabling monitoring, and deleting tickets violate change management governance.", "distractor_analysis": {"1": "Suppressing alerts blinds you at the exact moment you most need to see the effect of the change.", "2": "Approval and notification are separate obligations. Stakeholders still need to know the work has started.", "3": "The ticket closes after verification, with the outcome recorded, not before the work begins."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "maintenance-window", "communication", "rollback"], "id": "C2-259"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "What is the primary objective of corporate Privacy Policies and data classification frameworks (such as GDPR, HIPAA, and CCPA guidelines)?", "options": ["To set the encryption cipher suites allowed on public web services", "To govern how personal and confidential data may be collected, stored and shared", "To define the retention period for firewall and switch configuration backups", "To standardize how server rooms number rack units for asset tagging"], "answer": 3, "explanation": "Privacy policies and regulatory compliance frameworks (GDPR, HIPAA, CCPA, PCI-DSS) establish legal rules and organizational standards governing the ethical and secure collection, processing, retention, encryption, and sharing of Personally Identifiable Information (PII) and sensitive customer records. They have no relation to fan direction, rack numbering, or cable colors.", "distractor_analysis": {"1": "Device configuration retention is an operational standard, not a privacy framework.", "2": "Rack numbering is a facilities convention with no personal data in scope.", "3": "Cipher suite policy is one technical control that supports privacy rules but does not define them."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["privacy-policies", "pii", "data-protection", "gdpr"], "id": "C2-260"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "medium", "question": "Why is proper electrical grounding (earth bonding) mandatory for all datacenter server racks and high-voltage equipment?", "options": ["It equalizes neutral and line voltage so the PDU reports accurate amperage", "It suppresses electromagnetic interference on copper runs sharing the rack", "It lets the UPS transfer to battery without a gap in the output waveform", "It gives fault current a low-resistance path to earth, protecting people from shock and gear from damage"], "answer": 1, "explanation": "Equipment grounding connects metal chassis and server racks to the building's electrical earth grounding system. In the event of a short circuit or insulation failure, grounding provides a safe, low-resistance path for fault current to trip circuit breakers immediately, preventing the chassis from carrying lethal voltages that could electrocute technicians. Grounding does not affect DNS, ARP, or printer toner.", "distractor_analysis": {"1": "PDU metering reads current on the line conductor. Bonding does not calibrate it.", "2": "Bonding reduces some noise as a side effect, but the reason it is mandatory is life safety.", "3": "Transfer time is a function of the UPS topology, online or line-interactive, not of rack bonding."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["electrical-safety", "grounding", "fault-current", "safety"], "id": "C2-261"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "Why do remote support procedures require obtaining explicit user consent and recording remote assistance sessions?", "options": ["To satisfy the licence terms of the remote access product itself", "To measure link latency so the session quality can be tuned", "To protect privacy, keep accountability, and leave an audit trail for compliance", "To let the support tool cache the session so it reconnects faster"], "answer": 2, "explanation": "Obtaining user consent before connecting and recording remote support sessions protects user privacy, ensures transparency, establishes a verified audit trail of all technician actions for security compliance, and provides objective records for dispute resolution and staff training. It has no physical effect on PCIe buses, refresh rates, or ping latency.", "distractor_analysis": {"1": "Session caching is a product feature. Consent and recording exist for the user, not the tool.", "2": "Product licensing does not require consent from the person being supported.", "3": "Latency measurement is telemetry. It has nothing to do with permission to view a desktop."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-support", "session-recording", "consent", "compliance"], "id": "C2-262"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "hard", "question": "What is the operational advantage of utilizing 'Synthetic Full Backups' in modern backup systems?", "options": ["It removes the need for an offsite copy of the backup data", "The server merges the last full with its incrementals into a new full, without re-reading clients", "It deletes the prior incremental chains so only one restore point remains", "It turns off encryption during the merge to raise throughput"], "answer": 3, "explanation": "A Synthetic Full backup constructs a fresh, consolidated full backup image directly on the backup storage server by taking the previous full backup and applying all subsequent incremental changes to it. This provides the fast restore benefits of a Full backup without placing heavy read I/O or network transfer loads on production client servers. It does not delete restore paths, disable encryption, or eliminate offsite copies.", "distractor_analysis": {"1": "Synthesis creates a new full; it does not force the loss of earlier recovery points.", "2": "Encryption stays in force. Repository merges are not a reason to weaken protection.", "3": "An offsite or immutable copy is still required. Synthesis only changes how the full is produced."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["synthetic-full", "backup-methods", "storage", "optimization"], "id": "C2-263"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "How does an incident severity and priority matrix (evaluating Impact vs. Urgency) assist IT service desks during major outage events?", "options": ["It defines the escalation path from tier one through to tier three support", "It records the root cause once the outage has been resolved", "It calculates the service credit owed to the customer under the SLA", "It sets objective criteria to rank response so the biggest business impact is handled first"], "answer": 1, "explanation": "An incident priority matrix evaluates the breadth of business impact (how many users/critical services are down) and urgency (financial or time sensitivity) to calculate a clear priority level (e.g., Critical, High, Medium, Low). This ensures IT teams deploy emergency resources to major enterprise outages first before working on minor single-user requests. Cable types, fan curves, and chair heights are unrelated.", "distractor_analysis": {"1": "Escalation paths sit in the support model. The matrix decides what gets worked first.", "2": "Root cause analysis happens after restoration, in the problem record.", "3": "Service credits are a commercial consequence, calculated after the fact."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["incident-management", "severity-matrix", "priority", "sla"], "id": "C2-264"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "When an employee or systems administrator leaves the organization, what mandatory IT offboarding procedures must be executed immediately?", "options": ["Share the former employee's password with the remaining department staff", "Delete the employee's trouble tickets without logging", "Disable directory user accounts, revoke active SSO tokens/MFA credentials, recover company-owned hardware assets, and document access removal", "Leave VPN certificates active indefinitely for former employee convenience"], "answer": 2, "explanation": "IT offboarding procedures require immediate de-provisioning: disabling Active Directory and cloud accounts, revoking active session tokens and MFA registrations, removing group memberships, collecting all company-owned laptops/smartphones, and documenting the deactivation in ticketing/audit logs. Leaving accounts open, sharing passwords, and deleting audit logs create severe security breaches.", "distractor_analysis": {"1": "Leaving VPN certificates active allows former employees unauthorized remote access to the corporate network.", "2": "Sharing passwords violates individual accountability and creates unauthorized access pathways.", "3": "Deleting trouble tickets destroys historical records and violates compliance documentation policies."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["offboarding", "access-revocation", "deprovisioning", "security"], "id": "C2-265"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "What is the primary purpose of conducting a Post-Change Review (PCR) or post-implementation review meeting following a major infrastructure change?", "options": ["To reassign the change ticket to the operations backlog queue", "To review outcomes, record unexpected issues, and capture lessons learned", "To decide which storage vendor wins the next hardware refresh", "To pause infrastructure monitoring until the next change window"], "answer": 3, "explanation": "A Post-Change Review (PCR) is the final phase of formal change management. The engineering team and CAB review the implementation outcome (whether objectives were met on time and within budget), document any unforeseen complications or rollback triggers, and capture lessons learned to continuously refine future change procedures. It is not an excuse to replace hardware blindly, disable monitoring, or pull RAM.", "distractor_analysis": {"1": "Vendor selection is a procurement activity, not a review of the change just made.", "2": "Monitoring must stay on after a change, which is when regressions surface.", "3": "A completed change is closed with its outcome recorded, not pushed into a backlog."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "post-change-review", "lessons-learned", "pcr"], "id": "C2-266"}, {"id": "C2N-I-001", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "multi", "difficulty": "medium", "question": "A technician is imaging new Windows 11 Pro workstations that must join Active Directory, BitLocker-encrypt the OS volume, and support Remote Desktop for help-desk. Which TWO edition/feature choices are required versus Home? (Select TWO.)", "explanation": "Domain join and BitLocker for OS volumes are Pro/Enterprise capabilities that Home lacks in normal business deployments. Home does not unlock domain join, FAT32 is wrong for modern OS volumes, and disabling Workstation breaks SMB client behavior rather than enabling domain membership.", "video_reference": null, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows", "editions", "bitlocker", "domain"], "options": ["Windows 11 Pro (or Enterprise) for domain join support", "BitLocker drive encryption available on Pro/Enterprise SKUs", "Windows 11 Home because it includes Hyper-V Server Manager by default", "Replacing NTFS with FAT32 so BitLocker keys store in the MBR", "Disabling the Workstation service to force domain join"], "answers": [0, 1], "distractor_analysis": {"2": "Windows 11 Home does not provide business domain join the way Pro/Enterprise does.", "3": "FAT32 is unsuitable for modern Windows system volumes and is not how BitLocker stores keys.", "4": "The Workstation service supports SMB client access; disabling it does not force domain join."}}, {"id": "C2N-I-002", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.4", "type": "multi", "difficulty": "medium", "question": "A help-desk engineer must collect a failing service's dependencies and export a filtered Event Viewer log for escalation. Which TWO Windows tools should they use? (Select TWO.)", "explanation": "Service dependencies are visible in services.msc/sc.exe, and Event Viewer is the standard path to filter and export logs for escalation. Disk Cleanup, Character Map, and Paint 3D do not replace those admin consoles.", "video_reference": null, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["windows", "services", "event-viewer"], "options": ["Services console (services.msc or sc.exe) to inspect service state and dependencies", "Event Viewer to filter and export Application/System log entries", "Disk Cleanup solely to rebuild the service dependency graph", "Character Map to encode event XML into clipboard glyphs", "Paint 3D to screenshot registry hives instead of exporting logs"], "answers": [0, 1], "distractor_analysis": {"2": "Disk Cleanup frees temporary files; it does not map or repair service dependency trees.", "3": "Character Map inserts glyphs; it is not an event log export tool.", "4": "Screenshots of hives are not a substitute for proper Event Viewer exports."}}, {"id": "C2N-I-003", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.5", "type": "multi", "difficulty": "hard", "question": "On a Server Core style admin jump box, a technician must map a drive, test TCP 445 to a file server, and force a Group Policy refresh. Which TWO CLI utilities fit? (Select TWO.)", "explanation": "net use maps and authenticates the drive, and gpupdate /force pulls both computer and user policy on demand instead of waiting out the 90 minute refresh cycle. To prove TCP 445 is open before you blame policy, use Test-NetConnection -Port 445 rather than a ping, because ICMP is often blocked while SMB is fine. chkdsk repairs local volumes and has nothing to do with remote SMB paths. format targets a local volume and would destroy data if aimed at production storage. winver only prints the Windows build banner and changes no firewall or share configuration.", "video_reference": null, "notes_reference": "19_Windows_Management_Consoles_and_CLI.md", "tags": ["cli", "net-use", "gpupdate"], "options": ["net use to map/authenticate a network drive", "gpupdate /force to refresh computer and user policy", "chkdsk /r as the only way to map SMB shares", "format.com to reinitialize the remote file server volume over the WAN", "winver to open inbound firewall ports for SMB"], "answers": [0, 1], "distractor_analysis": {"2": "chkdsk checks local disks; it does not map remote SMB paths.", "3": "format targets local volumes and would be destructive if misused against production storage.", "4": "winver displays version information and does not configure firewall or SMB access."}}, {"id": "C2N-I-004", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.9", "type": "multi", "difficulty": "medium", "question": "A Linux admin on an Ubuntu jump host needs to install packages from the distribution repos and inspect listening TCP sockets after a change. Which TWO commands are appropriate? (Select TWO.)", "explanation": "apt (or apt-get) installs from the repositories configured under /etc/apt, and ss -tuln lists listening TCP and UDP sockets so you can confirm the service actually bound to the interface you expected. netstat -tuln does the same job on older builds. The other three are destructive, not diagnostic. chmod 777 /etc/shadow exposes every password hash on the box and is not an install prerequisite. Writing zeros to /boot with dd wipes the bootloader area and leaves an unbootable host. Deleting the root password with passwd -d removes authentication entirely and is never required by apt update.", "video_reference": null, "notes_reference": "24_Linux.md", "tags": ["linux", "apt", "ss"], "options": ["apt (or apt-get) to install packages from configured repositories", "ss -tuln (or netstat -tuln) to list listening sockets", "chmod 777 /etc/shadow to unlock package installs", "dd if=/dev/zero of=/boot to refresh APT indexes", "passwd -d root as a required step before apt update"], "answers": [0, 1], "distractor_analysis": {"2": "chmod 777 on /etc/shadow destroys credential confidentiality and is not an install step.", "3": "Writing zeros to /boot destroys the bootloader area instead of refreshing package indexes.", "4": "Removing the root password weakens security and is not required for apt update."}}, {"id": "C2N-I-005", "exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "multi", "difficulty": "medium", "question": "A colocation cage upgrade requires stronger physical access control for contractors who only need escorted daytime entry. Which TWO controls best fit that requirement? (Select TWO.)", "explanation": "Contractors who only need escorted daytime entry get badge credentials scoped by time of day on the cage door controller, plus a written escort and sign-in policy logged at the NOC desk. That pairing gives you both prevention and an audit trail when someone asks who was in the cage at 02:00. Publishing a photo of the master mechanical key defeats key control, because a usable copy can be cut from a clear image. Turning off CCTV removes the deterrent and the only recording of who touched what. Leaving an emergency exit unlatched creates an uncontrolled door that bypasses the badge reader entirely.", "video_reference": null, "notes_reference": "28_Physical_Security.md", "tags": ["physical-security", "badge", "escort"], "options": ["Badge access with time-of-day restrictions on the cage door controller", "Visitor escort policy logged at the NOC desk for contractor visits", "Posting the master mechanical key photo on a public SharePoint site", "Disabling all CCTV to protect contractor privacy inside the cage", "Leaving the emergency exit permanently unlatched for convenience"], "answers": [0, 1], "distractor_analysis": {"2": "Publishing key photos defeats physical key control and invites unauthorized copies.", "3": "CCTV is a standard deterrent and audit control; disabling it reduces accountability.", "4": "Unlatching emergency exits for convenience creates an uncontrolled entry path."}}, {"id": "C2N-I-006", "exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "multi", "difficulty": "hard", "question": "Auditors find a shared Windows folder where Authenticated Users have Modify on the share and Full control on NTFS. Which TWO changes restore least privilege for a read-only finance report drop? (Select TWO.)", "explanation": "Effective access is the more restrictive of share and NTFS permissions. Restrict NTFS for readers and remove overly broad share Modify for Authenticated Users. Broad Everyone Full control, ignoring NTFS, or USB drops increase exposure.", "video_reference": null, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["ntfs", "share-permissions", "least-privilege"], "options": ["Tighten NTFS ACLs so the finance readers group has Read & execute only", "Reduce share permissions so Authenticated Users are not granted Modify", "Grant Everyone Full control on both share and NTFS to simplify access", "Disable the entire NTFS ACL and rely only on share permissions", "Store the reports on a world-writable USB stick in the lobby"], "answers": [0, 1], "distractor_analysis": {"2": "Everyone Full control is the opposite of least privilege for financial data.", "3": "NTFS ACLs are required for file-level least privilege; share permissions alone are insufficient.", "4": "A lobby USB stick has no authentication boundary suitable for finance reports."}}, {"id": "C2N-I-007", "exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "multi", "difficulty": "medium", "question": "Users receive emails that urge immediate password changes via a link that spoofs the company SSO portal. Which TWO security awareness or technical controls help most? (Select TWO.)", "explanation": "Phishing that targets the SSO portal is beaten by two layers: users trained to check the address bar before typing credentials, and MFA on SSO so a stolen password alone does not open a session. Prefer number matching or a hardware key over SMS, since SIM swap defeats SMS codes. Disabling TLS puts every credential and message body in cleartext on the wire and helps the attacker, not the user. A shared break-glass password on a sticky note destroys accountability, because every action maps to one anonymous login. Whitelisting external .exe attachments hands malware a delivery path.", "video_reference": null, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["phishing", "mfa", "social-engineering"], "options": ["User training to recognize phishing and verify URLs before entering credentials", "MFA on SSO so stolen passwords alone are less useful to attackers", "Disabling all TLS so users can see plaintext email headers more easily", "Sharing one break-glass password in a sticky note on each monitor", "Whitelist every external .exe attachment to speed help-desk resets"], "answers": [0, 1], "distractor_analysis": {"2": "Disabling TLS exposes credentials and content in transit rather than helping users.", "3": "Shared break-glass passwords on monitors defeat authentication controls.", "4": "Whitelisting external executables invites malware delivery alongside phishing."}}, {"id": "C2N-I-008", "exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "multi", "difficulty": "medium", "question": "A workstation shows unexpected browser redirects and a new toolbar the user did not install. Which TWO actions are appropriate early malware response steps? (Select TWO.)", "explanation": "Containment plus a full scan, along with removing rogue extensions, are standard early steps for browser hijacks. Spreading the sample, freezing updates, or opening the firewall for C2 worsens the incident.", "video_reference": null, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware", "browser", "incident-response"], "options": ["Isolate the host from the network if policy allows, then run a full antimalware scan", "Review installed programs/extensions and remove unknown browser add-ons", "Email the suspicious executable to all staff so they can inspect it locally", "Disable Windows Update permanently to keep the malware signature frozen", "Turn off the host firewall to let the C2 callback complete for easier capture on the LAN"], "answers": [0, 1], "distractor_analysis": {"2": "Emailing malware samples to staff multiplies exposure instead of containing it.", "3": "Disabling Windows Update prevents security patches and signature improvements.", "4": "Disabling the firewall to allow C2 callbacks increases lateral movement risk."}}, {"id": "C2N-I-009", "exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "multi", "difficulty": "hard", "question": "A SOHO router still uses the factory admin password and broadcasts an open guest SSID bridged into the LAN. Which TWO hardening changes should be applied first? (Select TWO.)", "explanation": "Default passwords and open SSIDs bridged to the LAN are critical SOHO flaws. Unique admin credentials plus encrypted, isolated guest wireless are the first fixes. Killing DHCP, exposing Telnet, or weak location-based passphrases remain insecure.", "video_reference": null, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho", "wireless", "hardening"], "options": ["Change the default administrator password to a unique strong secret", "Segment or isolate guest Wi-Fi from the LAN and require WPA2/WPA3 encryption", "Disable all DHCP so every IoT device uses public RFC1918 conflicts intentionally", "Forward WAN TCP 23 to the router UI for easier remote Telnet admin", "Set the Wi-Fi passphrase to the company street address for memorability"], "answers": [0, 1], "distractor_analysis": {"2": "Disabling DHCP does not isolate guest traffic and creates addressing chaos.", "3": "WAN Telnet to the admin UI exposes cleartext remote control of the router.", "4": "Address-based passphrases are easily guessed and fail wireless hardening guidance."}}, {"id": "C2N-I-010", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "multi", "difficulty": "medium", "question": "A Windows laptop is slow after login: disk queue length spikes, and Task Manager shows constant Antimalware Service Executable CPU. Which TWO troubleshooting actions are reasonable first moves? (Select TWO.)", "explanation": "Heavy Defender scanning during peak hours plus a stressed or nearly full disk commonly explain post-login slowness. Deleting System32, removing the pagefile on low-RAM systems, or removing the battery are harmful or irrelevant.", "video_reference": null, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["performance", "defender", "disk"], "options": ["Confirm whether a full scan is running and reschedule it off business peak hours", "Check for disk health issues and ensure adequate free space on the system volume", "Delete System32 to stop the antimalware service from scanning", "Disable the paging file permanently on a 4 GB RAM laptop to speed boot", "Set the power plan to High Performance by removing the battery permanently"], "answers": [0, 1], "distractor_analysis": {"2": "Deleting System32 destroys the OS rather than tuning scans.", "3": "Disabling the pagefile on a low-RAM laptop often increases failures under memory pressure.", "4": "Removing the battery does not fix scan scheduling or disk health."}}, {"id": "C2N-I-011", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "multi", "difficulty": "medium", "question": "Chrome on a shared kiosk keeps restoring a hijacked homepage and blocked-plugin prompts after every reboot. Which TWO fixes target common software causes? (Select TWO.)", "explanation": "Persistent homepage hijacks usually come from extensions, shortcuts, or PUP policies. Resetting the browser and scanning for PUPs address those causes. Random VBIOS flashes, partial EFI formats, or zeroing DNS break the device without removing the hijack.", "video_reference": null, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser", "pup", "kiosk"], "options": ["Reset browser settings and remove unauthorized extensions", "Scan for PUPs/malware that rewrite shortcuts and policies", "Flash the GPU VBIOS from an unrelated laptop model", "Format only the EFI partition while leaving malware on C:", "Set the kiosk DNS to 0.0.0.0 to stop homepage redirects"], "answers": [0, 1], "distractor_analysis": {"2": "Cross-flashing GPU firmware risks a brick and does not remove browser hijacks.", "3": "Formatting EFI while leaving malware on the OS volume will not clear the infection.", "4": "Pointing DNS at 0.0.0.0 breaks name resolution rather than removing hijack components."}}, {"id": "C2N-I-012", "exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "multi", "difficulty": "medium", "question": "Before changing a production firewall rule set during business hours, which TWO change-management practices should the technician follow? (Select TWO.)", "explanation": "Formal change requests, risk/rollback notes, and approvals/windows are core operational procedure controls. Silent mass changes, skipping config backup, and shared unlogged accounts break auditability and recovery.", "video_reference": null, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "firewall", "operations"], "options": ["Submit a change request with risk assessment and rollback plan", "Obtain required approvals and schedule a maintenance window when mandated", "Apply the change silently on all sites first, then write documentation later", "Skip backup of the current config because rules are easy to remember", "Use the same unlogged shared admin account for every engineer on the change"], "answers": [0, 1], "distractor_analysis": {"2": "Undocumented silent changes prevent review and complicate rollback when traffic breaks.", "3": "Without a saved prior config, rollback becomes guesswork during an outage.", "4": "Shared admin accounts destroy individual accountability required by change audits."}}, {"id": "C2N-I-013", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.2", "type": "order", "difficulty": "medium", "question": "Order the steps to perform a clean Windows 11 installation on a new NVMe workstation that must boot in UEFI mode.", "explanation": "UEFI/GPT must be correct before partitioning. Only after the OS is installed do domain join, baselines, and BitLocker make sense. Installing in legacy CSM mode often creates MBR layouts that fight modern security features.", "video_reference": null, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["windows-install", "uefi", "gpt"], "sequence": ["Enter UEFI setup, enable UEFI boot, and set the install media first in the boot order", "Boot the Windows installer and delete/create a GPT partition layout on the NVMe drive", "Complete setup, install drivers/updates, and join the device to the required domain or Azure AD", "Apply baseline security policies, BitLocker if required, and verify activation"]}, {"id": "C2N-I-014", "exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "order", "difficulty": "hard", "question": "Order the preferred response when a receptionist reports a convincing urgent call from \"the CEO\" demanding gift-card codes.", "explanation": "Vishing works on urgency and authority, so the first move is to not comply: buy nothing, read nothing back, and stay off the caller's script. Verify out of band next, using the published internal number from the directory rather than any callback number the caller supplied. Then document the call detail and escalate to security so the pattern gets tracked across the site. Finally warn nearby staff per policy and preserve the voicemail or email, because that recording is the evidence the incident responder needs. Arguing on the same call or paying first gives the attacker exactly what they want.", "video_reference": null, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["vishing", "social-engineering", "incident"], "sequence": ["Remain calm, do not purchase cards, and avoid sharing secrets or codes", "Verify the request through a known-good channel using published contact procedures", "Document the call details and escalate to security/help desk immediately", "Warn nearby staff per policy and preserve any related voicemail or email evidence"]}, {"id": "C2N-I-015", "exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "order", "difficulty": "medium", "question": "Order the steps to enroll a corporate iPhone into MDM after a device wipe for a new hire.", "explanation": "Enrollment runs in a fixed order because each step depends on the last. Basic setup and a trusted network path come first, since the device cannot reach the MDM endpoint without connectivity. Authenticating the enrollment profile against corporate identity ties the hardware to a real user, so the device shows up under the right owner in the console. Only then can MDM push management profiles, certificates and required apps. Confirm the compliance posture last: passcode policy, encryption and VPN profile. Handing over an unverified device is how unmanaged endpoints get onto the network.", "video_reference": null, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mdm", "ios", "enrollment"], "sequence": ["Power on, choose language/region, and connect to a trusted network or cellular path", "Authenticate the enrollment profile with corporate identity credentials or QR/token", "Allow MDM to install management profiles, certificates, and required apps", "Confirm compliance policies (passcode, encryption, VPN) before handing the device to the user"]}, {"id": "C2N-I-016", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "order", "difficulty": "medium", "question": "Order the steps to recover a Windows workstation that fails to boot after a bad driver update, using least-destructive options first.", "explanation": "Work least destructive to most. Boot into the Windows Recovery Environment and try Startup Repair or Safe Mode first, because Safe Mode loads a minimal driver set and usually gets you a desktop. From there roll the driver back in Device Manager or use System Restore to return to the pre-update checkpoint. If the system boots but files remain damaged, run DISM /Online /Cleanup-Image /RestoreHealth then sfc /scannow to repair the component store and protected files. Reimaging or rebuilding and rejoining the domain is the last resort, because it costs the user their local state.", "video_reference": null, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["startup-repair", "drivers", "winre"], "sequence": ["Attempt Startup Repair / Safe Mode from Windows Recovery Environment", "Uninstall the recent driver or roll back via Device Manager / System Restore in Safe Mode", "Run SFC/DISM offline or from recovery if system files remain corrupted", "If still unbootable, restore from image backup or rebuild and rejoin per procedure"]}, {"id": "C2N-I-017", "exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "order", "difficulty": "medium", "question": "Order the safety steps for replacing a hot-swap PSU in a live rack under LOTO-aware datacenter policy for that chassis type.", "explanation": "Confirm the chassis is rated for hot swap and identify the failed module and its circuit before you touch anything. iDRAC, iLO or the front panel LED will name the failed supply, so you are not going by guesswork. Wear ESD protection, tell the NOC the redundancy is about to drop, and follow site lockout and tagout rules for that chassis. Then pull the failed module and seat the replacement until it latches and the status LED goes healthy. Verify load sharing across both supplies on the PDU and the management controller, clear the alert, and log the swap. Pulling the wrong module drops the host.", "video_reference": null, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["safety", "psu", "datacenter"], "sequence": ["Confirm the chassis supports hot-swap and identify the failed PSU module and circuit", "Wear ESD protection, communicate with NOC, and follow site LOTO/energy isolation rules as required", "Remove the failed module and insert the replacement until latched with status LEDs healthy", "Verify redundant load sharing, clear alerts, and update the maintenance log"]}, {"id": "C2N-I-018", "exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "order", "difficulty": "medium", "question": "Order the steps to implement a 3-2-1 style backup plan for a small office file server before a major application upgrade.", "explanation": "Start with the business, not the tooling. Agree the critical data sets and the recovery point and recovery time objectives with the owner, because those numbers decide job frequency and retention. Then configure a local backup to separate media plus a second distinct target, which gives you the three copies on two media that the rule calls for. Send the third copy offsite or to immutable cloud storage so ransomware cannot reach it from the same credentials. Finally restore sample files and a test VM and record the result. A backup job that has never been restored is a report, not a recovery plan.", "video_reference": null, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup", "3-2-1", "restore-test"], "sequence": ["Identify critical data sets and recovery point/time objectives with the business owner", "Configure local backups to a separate medium and a second distinct storage target", "Replicate or vault a third copy offsite or to immutable cloud storage", "Run a restore test of sample files/VMs and document the results before the upgrade"]}, {"id": "C2N-I-019", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.3", "type": "match", "difficulty": "medium", "question": "Match each Windows Settings area to the task a technician most often performs there.", "explanation": "Technicians navigate Settings constantly: About for edition/activation, Network for connectivity, Accounts for identity, Windows Update for patching, and Apps for uninstalls. Knowing the map reduces time on remote sessions.", "video_reference": null, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows-settings", "match"], "pairs": [{"left": "System > About / Activation", "right": "Verify Windows edition and activation state"}, {"left": "Network & internet", "right": "Configure IP, VPN, and proxy connectivity"}, {"left": "Accounts", "right": "Manage local/Microsoft account sign-in options"}, {"left": "Update & security / Windows Update", "right": "Check for OS patches and pause updates"}, {"left": "Apps", "right": "Uninstall or modify installed desktop applications"}]}, {"id": "C2N-I-020", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.8", "type": "match", "difficulty": "medium", "question": "A designer on a Mac calls the help desk and you have to talk them through the built-in tools over the phone. Match each macOS tool or feature to its purpose.", "explanation": "These four cover most of what you talk a Mac user through over the phone. Finder is the file manager for local volumes and network shares, and Go to Folder is how you reach a path a Windows technician would type in Explorer. Time Machine takes incremental snapshots to an external or network target and restores individual files or a whole system. Keychain Access stores passwords and certificates for the user, and a corrupt login keychain is a common cause of repeated credential prompts. Mission Control manages Spaces, full-screen apps and the window overview, so it is a display question, not a storage one.", "video_reference": null, "notes_reference": "25_macOS.md", "tags": ["macos", "time-machine", "keychain"], "pairs": [{"left": "Finder", "right": "Browse files, volumes, and network shares"}, {"left": "Time Machine", "right": "Local/external incremental backups and restores"}, {"left": "Keychain Access", "right": "Store passwords and certificates for the user"}, {"left": "Mission Control", "right": "Manage Spaces, full-screen apps, and window overview"}]}, {"id": "C2N-I-021", "exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "match", "difficulty": "hard", "question": "You are rebuilding a branch office wireless network and have to justify the security mode in the change record. Match each wireless security mode to its defining characteristic.", "explanation": "WPA3-Personal replaces the WPA2 four-way handshake with SAE, which kills the offline dictionary attack against a captured handshake. WPA2-Enterprise uses 802.1X with a RADIUS server, so every user authenticates with their own credential or certificate and you can revoke one person without changing a shared key. An open network applies no link-layer encryption at all, so anything not wrapped in TLS is readable by anyone in range. WEP uses RC4 with a weak IV scheme and is recovered in minutes with off-the-shelf tools, so treat it as a finding to remediate whenever you meet it on a survey.", "video_reference": null, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa3", "802.1x"], "pairs": [{"left": "WPA3-Personal", "right": "SAE-based passphrase authentication for modern SOHO Wi-Fi"}, {"left": "WPA2-Enterprise", "right": "802.1X with RADIUS-backed per-user credentials"}, {"left": "Open network", "right": "No encryption; traffic readable by local eavesdroppers"}, {"left": "WEP", "right": "Obsolete RC4 scheme that must not be used on production WLANs"}]}, {"id": "C2N-I-022", "exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "match", "difficulty": "medium", "question": "A user reports they can open a share but cannot delete anything in it, and you are working the permission stack. Match each Windows permission concept to its meaning.", "explanation": "Permission problems get solved by walking the stack in order. NTFS Modify grants read, write and delete inside a folder but not the right to change the ACL, which is Full control. Share Read caps what comes across the wire, and the effective access is the more restrictive of the share and NTFS permissions, which is why a user with NTFS Modify still cannot write through a read-only share. An explicit Deny beats a conflicting Allow at the same level. Inheritance passes ACEs from parent to child. C$ is the hidden administrative share on a volume root, available to local administrators only.", "video_reference": null, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["ntfs", "shares", "acl"], "pairs": [{"left": "NTFS Modify", "right": "Read, write, and delete files within a folder"}, {"left": "Share Read", "right": "Connect to the share with read-only share-level rights"}, {"left": "Explicit Deny", "right": "Overrides conflicting Allow entries for that permission"}, {"left": "Inheritance", "right": "Child objects receive ACEs from a parent folder"}, {"left": "Administrative share (C$)", "right": "Hidden default share for admins on a volume root"}]}, {"id": "C2N-I-023", "exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "match", "difficulty": "medium", "question": "Match each scripting or automation artifact to its typical use on Windows support desks.", "explanation": "PowerShell dominates modern Windows automation, batch files remain for legacy needs, shell scripts serve Unix hosts, and Scheduled Tasks time the runs. Matching the artifact prevents picking the wrong runtime.", "video_reference": null, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "powershell", "scheduled-tasks"], "pairs": [{"left": ".ps1 PowerShell script", "right": "Automate admin tasks with rich Windows APIs"}, {"left": ".bat / .cmd", "right": "Legacy Command Prompt batch automation"}, {"left": ".sh shell script", "right": "Bash automation on Linux/macOS jump hosts"}, {"left": "Scheduled Task", "right": "Run scripts at logon/time triggers under a service account"}]}, {"id": "C2N-I-024", "exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "match", "difficulty": "easy", "question": "You are coaching a new technician through their first week on the service desk floor. Match each professionalism scenario to the appropriate technician response.", "explanation": "These behaviors are graded on the exam and watched on the floor. Take an angry user out of the lobby and away from an audience, stay calm and stick to facts. An unclear ticket gets clarifying questions and a restatement of the problem before you change anything, because guessing generates rework and a second outage. Personal data on screen is not yours to read; access only what the job requires. If you have to escalate mid-change, stop at a safe point, document the exact state and hand off cleanly. With a language barrier, speak plainly, confirm understanding and never talk down to the customer.", "video_reference": null, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "communication"], "pairs": [{"left": "Angry user in a public lobby", "right": "Stay calm, move to a private area if possible, and focus on facts"}, {"left": "Unclear ticket description", "right": "Ask clarifying questions and restate the problem before changing systems"}, {"left": "Personal data visible on screen", "right": "Avoid snooping; access only what the job requires"}, {"left": "Escalation needed mid-change", "right": "Stop at a safe point, document state, and hand off cleanly"}, {"left": "Cultural or language barrier", "right": "Speak plainly, confirm understanding, and avoid condescension"}]}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "An IT department is deploying 300 new laptops. Which operational process involves physically affixing scannable barcode/RFID tags and recording serial numbers, purchase dates, warranty terms, and assigned users in a Configuration Management Database (CMDB)?", "options": ["Change management risk analysis", "Disaster recovery tabletop testing", "Software license harvesting", "Asset management / Hardware inventory tracking"], "answer": 1, "explanation": "Asset management is the lifecycle process of identifying, tracking, and managing physical and virtual IT assets from procurement to disposal. Affixing barcode/RFID asset tags and entering hardware specifications, serial numbers, warranty timelines, and assigned personnel into a CMDB ensures accurate hardware accountability and auditing. Change management evaluates system modifications, disaster recovery plans for outages, and license harvesting recovers unused software.", "distractor_analysis": {"1": "Change management governs the formal approval and rollout of infrastructure changes, not physical device inventory tagging.", "2": "Disaster recovery tabletop exercises simulate emergency operational responses to critical outages without managing hardware tag inventories.", "3": "License harvesting reclaims unused software allocations across workstations rather than cataloging physical laptop hardware assets."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["operational-procedures", "asset-management", "cmdb", "lifecycle"], "id": "C2N-O-001"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "medium", "question": "A technician spends two hours diagnosing an uncommon VPN configuration error and successfully resolves the issue. According to standard operating procedures, what documentation step should the technician complete before closing the ticket?", "options": ["Email the company CEO detailing the technician's overtime hours", "Change the ticket priority to Critical and leave it open for 30 days", "Document the root cause, symptoms, and step-by-step resolution in the ticketing work log and create a Knowledge Base (KB) article if applicable", "Delete the ticket history to save database storage on the ticketing server"], "answer": 2, "explanation": "Professional IT operational procedures require thorough incident documentation. Recording the detailed problem description, root cause analysis, and exact resolution steps in the ticketing system ensures organizational knowledge capture, aids future troubleshooting, and allows creating or updating internal Knowledge Base (KB) articles. Deleting tickets destroys audit history, emailing executive leadership is inappropriate, and falsely escalating closed tickets violates ticketing procedures.", "distractor_analysis": {"1": "Deleting ticket history destroys institutional memory, compliance audit trails, and troubleshooting references.", "2": "Escalating routine ticket resolution notes to the Chief Executive Officer violates communication hierarchy and operational protocols.", "3": "Leaving closed tickets open under a Critical status skews SLA metrics and misrepresents active incident queues."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["operational-procedures", "ticketing", "documentation", "kb"], "id": "C2N-O-002"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.1", "type": "single", "difficulty": "hard", "question": "A network technician needs to understand both the physical cable runs connecting patch panels to datacenter rack switches AND the logical IP addressing, VLAN segmentation, and routing boundaries. Which documentation resources are required?", "options": ["The acceptable use policy signed by every network user", "Physical cabling diagrams and logical topology diagrams together", "Software end-user licence agreements for the switch operating system", "Safety data sheets for the solvents used to clean rack surfaces"], "answer": 3, "explanation": "Network documentation comprises two distinct types: Physical network diagrams illustrate actual hardware locations, rack elevations, patch panel ports, and physical cable pathways. Logical network diagrams illustrate data flow, IP addressing schemes, subnet masks, VLAN IDs, router gateways, and firewall security zones. EULAs govern software licensing, SDS covers chemical safety, and AUP governs employee computer behavior.", "distractor_analysis": {"1": "Licence documents cover entitlement, not cable paths or VLAN boundaries.", "2": "Safety data sheets cover chemical handling and belong in the safety file.", "3": "The acceptable use policy governs user behaviour and carries no network detail."}, "video_reference": {"title": "Ticketing Systems - CompTIA A+ 220-1202 - 4.1", "url": "https://www.youtube.com/watch?v=EzjHn6vvrsI", "duration": "13:48", "objective": "4.1"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["operational-procedures", "network-diagrams", "topology", "documentation"], "id": "C2N-O-003"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "hard", "question": "A senior systems engineer submits a Request for Change (RFC) to upgrade the core datacenter hypervisor cluster. Why is a documented rollback (backout) plan a MANDATORY prerequisite for change approval?", "options": ["It automatically executes the hypervisor installation script without administrative supervision", "It eliminates the need to perform risk analysis or test in a staging environment", "It guarantees that no software bugs exist in the new hypervisor build", "It provides step-by-step instructions and verified backups to restore systems to their previous working state if the change fails or causes unexpected downtime"], "answer": 1, "explanation": "A rollback (backout) plan is a critical risk mitigation requirement in formal change management. If an infrastructure change encounters unforeseen failures, performance degradation, or database corruption during execution, the rollback plan provides clear, tested steps (including restoring pre-change backups and reverting configuration states) to return the environment to a known good operational baseline within the maintenance window. Rollback plans do not automate installations, replace sandbox testing, or guarantee zero vendor bugs.", "distractor_analysis": {"1": "A rollback plan is a recovery procedure used upon failure, not an automated deployment script for primary installations.", "2": "Having a backout plan does not excuse the engineering team from conducting rigorous risk analyses and sandbox staging tests.", "3": "No documentation can guarantee that third-party vendor software is completely free of bugs or regressions."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "rollback-plan", "backout", "rfc"], "id": "C2N-O-004"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Which organizational governing body is responsible for reviewing proposed RFCs, evaluating business risk, assessing scheduling conflicts with other projects, and granting formal approval for major infrastructure changes?", "options": ["Software Quality Assurance Beta Testers", "Local Emergency Response Team", "Change Advisory Board (CAB)", "Human Resources Disciplinary Panel"], "answer": 2, "explanation": "The Change Advisory Board (CAB) is a multidisciplinary committee composed of IT managers, systems architects, security officers, and business stakeholders that convenes periodically to review Requests for Change (RFCs). The CAB evaluates technical risk, business impact, rollback viability, and scheduling conflicts before officially approving or rejecting changes. HR handles employee relations, QA conducts code testing, and emergency teams handle physical crises.", "distractor_analysis": {"1": "Human Resources panels govern personnel management, employment policy, and workplace conduct, not technical infrastructure RFCs.", "2": "QA beta testers evaluate software usability and defect reporting prior to production release, lacking governance authority over enterprise change approvals.", "3": "Emergency response teams address physical building evacuations and hazards, not IT change management governance."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "cab", "approval", "rfc"], "id": "C2N-O-005"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "Before deploying a new security patch to 2,000 production database servers, the systems team validates the patch in an isolated replica environment that mirrors production hardware and application stacks. What is this environment called?", "options": ["Client endpoint demilitarized zone (DMZ)", "Sandbox / Staging (Test) environment", "Live Production cluster", "Public cloud archive repository"], "answer": 3, "explanation": "A Sandbox or Staging environment is an isolated non-production network segment that closely duplicates the production configuration. Testing patches, scripts, and software upgrades in a sandbox allows engineers to detect software conflicts, application crashes, and performance regressions without impacting live business operations or real user data. Testing on live production risks immediate company-wide outages.", "distractor_analysis": {"1": "Testing unverified security patches directly on live production clusters risks catastrophic enterprise downtime and customer data corruption.", "2": "Public cloud archives are cold storage tiers for long-term retention of historical data, not execution testbeds.", "3": "A DMZ is a perimeter network exposed to the internet hosting external services (e.g., web servers), not an isolated patch staging environment."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "sandbox", "test-environment", "staging"], "id": "C2N-O-006"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.2", "type": "single", "difficulty": "medium", "question": "A systems engineer must migrate an email server to a new storage array. Why should this change be scheduled strictly during a predefined 'maintenance window'?", "options": ["To ensure that server hardware runs at cooler operating temperatures", "To bypass the need for Change Advisory Board (CAB) approval", "To prevent the server from generating Windows Event Viewer logs", "To minimize business disruption and user impact by executing changes during low-traffic off-peak hours"], "answer": 1, "explanation": "A maintenance window is a pre-scheduled timeframe (typically during overnight hours or weekends) agreed upon by IT and business stakeholders during which planned service interruptions, reboots, and high-risk changes are permitted. Executing changes during off-peak hours minimizes the impact of potential downtime on employee productivity and customer operations. Maintenance windows do not alter hardware cooling, bypass CAB approval, or suppress event logging.", "distractor_analysis": {"1": "Hardware operating temperatures are governed by server room HVAC cooling, not calendar scheduling windows.", "2": "Scheduling within a maintenance window is a requirement of the CAB process, never a loophole to bypass formal approval.", "3": "Windows Event Viewer continues logging all driver, application, and system events normally regardless of the time of day."}, "video_reference": {"title": "Change Management - CompTIA A+ 220-1202 - 4.2", "url": "https://www.youtube.com/watch?v=AhcQlR73Bo4", "duration": "21:42", "objective": "4.2"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["change-management", "maintenance-window", "stakeholders", "communication"], "id": "C2N-O-007"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "hard", "question": "A company executes a Full backup every Sunday night at 23:00. From Monday through Saturday, the backup software is configured to back up only files that have changed since the previous day's backup and then clear the archive bit. Which backup type is running on weeknights, and what is required for a complete restore on Thursday?", "options": ["Synthetic full backup; restoring Thursday requires only Monday's backup", "Full backup; restoring Thursday requires only Wednesday's backup", "Incremental backup; restoring Thursday requires Sunday's Full backup plus Monday, Tuesday, and Wednesday Incremental backups in sequential order", "Differential backup; restoring Thursday requires Sunday's Full backup plus only Wednesday's Differential backup"], "answer": 2, "explanation": "An Incremental backup backs up all files modified since the last backup of ANY type (full or incremental) and CLEARS the archive bit (sets it to 0). Consequently, each daily incremental captures only that single day's changes. To restore data as of Thursday morning, the administrator must restore the last Full backup (Sunday) followed by each daily incremental backup in exact chronological order (Monday, Tuesday, Wednesday). Differential backups do not clear the archive bit and require only the Full plus the latest Differential.", "distractor_analysis": {"1": "Differential backups do not clear the archive bit and back up all changes since Sunday's Full, which does not match the question's daily clear behavior.", "2": "A synthetic full creates an assembled full backup on the backup server without needing individual client incremental chain playback.", "3": "Daily full backups would back up all enterprise data every single night, which is not the described incremental workflow."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-and-recovery", "incremental", "differential", "archive-bit"], "id": "C2N-O-008"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "medium", "question": "An IT manager enforces the industry standard '3-2-1 backup rule' for corporate financial databases. Which configuration exemplifies strict adherence to the 3-2-1 rule?", "options": ["3 daily full backups kept on 2 optical DVDs stored in the server room desk", "3 total copies of the data, on 2 different storage media types (e.g., local NVMe SAN and LTO tape), with 1 copy stored offsite/in the cloud", "3 copies of the data stored on 2 different partitions of the same physical hard drive", "3 backups taken every 2 hours using 1 single USB flash drive"], "answer": 3, "explanation": "The 3-2-1 backup rule is the benchmark for data protection: Maintain at least 3 total copies of your data (1 primary production copy + 2 backup copies), stored on at least 2 different storage media technologies (e.g., disk SAN + magnetic tape or cloud object storage), with at least 1 copy kept offsite (or in an immutable cloud repository) to survive localized physical disasters (fire, flood, theft). Storing copies on the same drive or room violates media diversity and offsite requirements.", "distractor_analysis": {"1": "Multiple partitions on the same physical drive all fail simultaneously if the underlying spindle motor or drive controller fails.", "2": "Relying on a single USB thumb drive provides zero media redundancy, zero drive diversity, and zero offsite disaster protection.", "3": "Keeping all DVD media inside the same server room offers zero protection against building fires, water leaks, or physical burglary."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-and-recovery", "3-2-1-rule", "best-practices", "offsite"], "id": "C2N-O-009"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "hard", "question": "A financial transaction system defines a Recovery Point Objective (RPO) of 15 minutes and a Recovery Time Objective (RTO) of 2 hours. What do these metrics mandate from a backup and operational recovery perspective?", "options": ["Backups take 15 minutes to run and systems must run without maintenance for 2 hours", "Data must be retained for 15 months and restored in 2 days", "The disaster recovery site must be located 15 miles away and have 2 internet connections", "Maximum allowable data loss is 15 minutes of transactions (requiring frequent snapshots/replication), and systems must be fully restored and operational within 2 hours of an outage"], "answer": 1, "explanation": "Recovery Point Objective (RPO) is the maximum acceptable amount of data loss measured in time (e.g., losing at most 15 minutes of committed transactions, necessitating continuous replication or 15-minute transactional logs). Recovery Time Objective (RTO) is the maximum acceptable duration of system downtime before service must be fully restored to normal operations following an outage (e.g., recovering within 2 hours). These are core business continuity metrics.", "distractor_analysis": {"1": "RPO and RTO measure business risk and downtime limits, not the computational runtime speed of backup software agents.", "2": "Data retention timelines are governed by legal compliance policies, not the operational definition of RPO and RTO.", "3": "Geographic distance between hot sites is dictated by disaster zone guidelines, not RPO/RTO time-based loss metrics."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-and-recovery", "rto", "rpo", "disaster-recovery"], "id": "C2N-O-010"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.3", "type": "single", "difficulty": "medium", "question": "A backup administrator configures automated nightly image backups for 50 virtual servers. The backup dashboard displays green checkmarks indicating all backup jobs completed successfully. What CRITICAL operational procedure must the administrator conduct periodically to ensure data recoverability?", "options": ["Disable encryption on backup volumes to speed up dashboard reporting", "Reboot the production database server every hour", "Perform periodic test restores to an isolated sandbox network to verify data integrity and bootability", "Delete the previous week's backups to make room for newer checkmarks"], "answer": 2, "explanation": "A backup is only as good as its restore. Automated backup job success checkmarks only confirm that data blocks were written to media; they do not guarantee that the resulting files, databases, or VM images are uncorrupted and capable of booting cleanly. Conducting periodic test restores in an isolated sandbox environment is the only way to validate true recoverability and measure realistic RTO timelines. Deleting backups, disabling encryption, and hourly reboots are harmful practices.", "distractor_analysis": {"1": "Deleting historical backups destroys version history and violates mandatory retention compliance guidelines.", "2": "Disabling backup encryption exposes sensitive company data to theft if backup tapes or cloud buckets are compromised.", "3": "Rebooting live production servers hourly causes severe business interruption without testing the backup restore pipeline."}, "video_reference": {"title": "Managing Backups - CompTIA A+ 220-1202 - 4.3", "url": "https://www.youtube.com/watch?v=xJc7-KM-Fsk", "duration": "15:01", "objective": "4.3"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["backup-and-recovery", "test-restores", "validation", "audit"], "id": "C2N-O-011"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "medium", "question": "A technician is preparing to open a desktop chassis to replace the motherboard and RAM. What is the PROPER use of an electrostatic discharge (ESD) antistatic wrist strap?", "options": ["Clip the lead directly to the CPU heat spreader before removing the cooler", "Fit the strap snugly on the wrist and clip it to unpainted chassis metal with the PC unplugged", "Clip the lead to the earth pin of a live wall outlet before opening the case", "Wear the strap loosely over a sleeve so it does not restrict movement"], "answer": 3, "explanation": "An ESD antistatic wrist strap equalizes the electrical potential between the technician's body and the computer equipment, safely draining static charges through a built-in 1-megaohm resistor. The strap must be worn tightly against bare skin, and the alligator clip must be attached to an unpainted metal section of the computer chassis with the power cord disconnected. Attaching clips to live outlets is life-threatening, wearing over clothes prevents skin contact, and clipping to silicon destroys the CPU.", "distractor_analysis": {"1": "Never bond yourself to a live outlet. Use the chassis, which is already at a common potential.", "2": "A loose strap over fabric breaks skin contact, so there is no path to bleed off charge.", "3": "The processor is the component you are protecting. The clip belongs on bare chassis metal."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["safety-procedures", "esd", "antistatic-wrist-strap", "hardware"], "id": "C2N-O-012"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "hard", "question": "Which computer components contain high-voltage internal capacitors capable of storing lethal electrical charges even after being disconnected from wall power for days, and should NEVER be disassembled by standard field technicians?", "options": ["Solid-State Drives (SSDs) and NVMe cards", "DDR4 and DDR5 RAM memory modules", "Standard USB mice and keyboards", "Power Supply Units (PSUs) and legacy CRT display monitors"], "answer": 1, "explanation": "Power Supply Units (PSUs) and legacy Cathode Ray Tube (CRT) monitors contain large high-voltage filter capacitors capable of storing thousands of volts of electrical charge long after mains power has been disconnected. Disassembling a PSU housing or CRT chassis can deliver a fatal electric shock. Standard technicians must treat PSUs as non-field-serviceable sealed Field Replaceable Units (FRUs) and replace the entire unit. SSDs, RAM, and USB mice operate on low-voltage DC (3.3V-5V) and carry no lethal capacitor charges.", "distractor_analysis": {"1": "Solid-state drives operate on low-voltage 3.3V / 5V DC power and do not contain lethal high-voltage energy storage capacitors.", "2": "DDR RAM modules operate at 1.1V - 1.35V DC and present zero high-voltage electrocution danger to technicians.", "3": "USB peripherals utilize standard 5V low-power circuits that carry no capacitor shock hazards."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["safety-procedures", "high-voltage", "psu", "crt", "capacitors"], "id": "C2N-O-013"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.4", "type": "single", "difficulty": "medium", "question": "A server power supply in a datacenter rack sparks violently and begins emitting dense smoke and flames. Which type of fire extinguisher is rated specifically for energized electrical equipment fires?", "options": ["Class K wet chemical kitchen extinguisher", "A standard bucket of tap water", "Class C (or multipurpose ABC dry chemical / clean agent clean gas like CO2 or FM-200)", "Class A pressurized water extinguisher"], "answer": 2, "explanation": "Fires involving energized electrical equipment (such as servers, wiring, and breaker panels) are designated as Class C fires. Class C extinguishers use non-conductive extinguishing agents such as Carbon Dioxide (CO2), Halon alternatives (FM-200/Novec 1230), or dry chemicals that do not conduct electricity back to the operator. Pressurized water extinguishers (Class A) and buckets of water conduct electricity and cause fatal shocks when applied to energized equipment. Class K is for commercial cooking oils.", "distractor_analysis": {"1": "Water-based Class A extinguishers conduct electrical current directly back through the stream, posing severe electrocution danger.", "2": "Class K wet chemical extinguishers are specifically formulated to saponify commercial cooking fats and grease in restaurant kitchens.", "3": "Throwing liquid tap water on energized server racks causes immediate short-circuit electrocution and explosive arcing."}, "video_reference": {"title": "Managing Electrostatic Discharge - CompTIA A+ 220-1202 - 4.4", "url": "https://www.youtube.com/watch?v=sDlVVU3oAlA", "duration": "5:28", "objective": "4.4"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["safety-procedures", "fire-safety", "class-c", "extinguisher"], "id": "C2N-O-014"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "medium", "question": "A cleaning solvent is accidentally splashed into a technician's eyes while servicing a shared laser printer. Which safety documentation must be immediately referenced to find emergency first-aid and eye flushing instructions?", "options": ["Building Architectural Floorplan Diagram", "Safety Data Sheet (SDS / MSDS) for the specific chemical product", "Printer Service User Manual troubleshooting appendix", "Company Acceptable Use Policy (AUP)"], "answer": 3, "explanation": "Safety Data Sheets (SDS), formerly known as Material Safety Data Sheets (MSDS), are federally mandated safety documents provided by chemical manufacturers. Section 4 of an SDS specifically outlines emergency first-aid measures, eye and skin exposure procedures, toxicity hazards, handling precautions, and required PPE. Hardware service manuals cover mechanical gears, AUP covers computer usage policies, and floorplans show physical architectural layouts.", "distractor_analysis": {"1": "Printer hardware manuals document mechanical disassembly and paper jam clearing, lacking detailed chemical toxicology and first-aid protocols.", "2": "Acceptable Use Policies dictate acceptable employee network conduct and provide zero chemical emergency response guidance.", "3": "Building floorplans show architectural layouts and fire exits without detailing chemical first-aid treatments."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "sds", "msds", "chemical-safety"], "id": "C2N-O-015"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "medium", "question": "A datacenter technician replaces twelve failed Lead-Acid batteries from an Uninterruptible Power Supply (UPS) system. How should these hazardous heavy-metal batteries be disposed of?", "options": ["Place them in the general waste dumpster once fully discharged", "Return them to the UPS vendor only if the units are still in warranty", "Store them indefinitely in the loading bay until the site closes", "Recycle through a licensed hazardous waste and battery recycling facility"], "answer": 1, "explanation": "Lead-acid and lithium-ion batteries contain toxic heavy metals (lead, cadmium, lithium) and corrosive sulfuric acid electrolyte that contaminate groundwater and cause landfill fires. Environmental protection regulations (e.g., EPA/RCRA) strictly prohibit disposing of batteries in municipal trash. They must be collected, stored in acid-resistant containers, and handed over to certified environmental recycling facilities. Throwing in dumpsters, burning, or crushing causes severe chemical contamination and toxic fires.", "distractor_analysis": {"1": "Lead-acid cells are regulated waste whether charged or flat. General waste is not a legal route.", "2": "Warranty status does not change the disposal obligation for the old cells.", "3": "Indefinite storage of leaking cells creates an environmental and safety hazard on site."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "battery-disposal", "e-waste", "lead-acid"], "id": "C2N-O-016"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.5", "type": "single", "difficulty": "hard", "question": "Why is it critical for datacenter HVAC climate control systems to maintain relative humidity within an optimal range of approximately 40% to 60%?", "options": ["High humidity speeds up server CPU clock frequencies", "Relative humidity controls the optical wavelength of fiber optic transceivers", "Low humidity (<30%) drastically increases the risk of Electrostatic Discharge (ESD), while high humidity (>60%) promotes condensation and metal corrosion", "Low humidity causes network packets to travel slower over copper cables"], "answer": 2, "explanation": "Datacenter environmental guidelines (such as ASHRAE TC 9.9) specify keeping relative humidity between 40% and 60% (with controlled dew point). If humidity drops below ~30%, the dry air significantly increases static charge generation, causing destructive ESD events on sensitive server electronics. If humidity rises above ~60-70%, moisture can condense onto cold metal components, causing electrical short circuits and terminal corrosion. Humidity has no effect on packet velocity, CPU clocks, or fiber wavelengths.", "distractor_analysis": {"1": "Relative humidity has zero effect on the propagation velocity of electromagnetic signals inside copper conductor wires.", "2": "Humidity levels do not alter processor silicon clock frequencies or multiplier ratios.", "3": "Optical wavelengths in fiber optic transceivers are governed by solid-state laser diodes, completely independent of ambient air humidity."}, "video_reference": {"title": "Environmental Impacts - CompTIA A+ 220-1202 - 4.5", "url": "https://www.youtube.com/watch?v=FqWHM4Sws1M", "duration": "6:28", "objective": "4.5"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["environmental-controls", "hvac", "humidity", "datacenter-environment"], "id": "C2N-O-017"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "hard", "question": "A technician acting as a first responder on a compromised workstation secures the physical machine for forensic investigation. Which document MUST be meticulously maintained to track every individual who handled, analyzed, or transferred the physical storage drive?", "options": ["Safety Data Sheet (SDS)", "Chain of Custody form", "Request for Change (RFC) document", "End-User License Agreement (EULA)"], "answer": 3, "explanation": "In computer forensics and incident response, a Chain of Custody form is the legal documentation that accounts for the possession, transfer, analysis, and storage of physical or digital evidence from the moment of collection until trial. It records exact dates/times, names, badge numbers, serial numbers, and reasons for evidence custody transfer. Without an unbroken chain of custody, evidence is rendered inadmissible in a court of law. RFCs govern changes, EULAs govern software, and SDS covers chemical safety.", "distractor_analysis": {"1": "RFC documents are used in change management to request infrastructure modifications, not to track legal evidence possession.", "2": "EULAs define software licensing terms and conditions between vendors and customers.", "3": "Safety Data Sheets provide chemical hazard and first-aid instructions, having zero forensic evidence tracking utility."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["incident-response", "chain-of-custody", "forensics", "evidence"], "id": "C2N-O-018"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "While replacing a broken hard drive on an employee's computer, a technician discovers folders containing explicit illegal content. Following standard incident response procedures, what should the technician do IMMEDIATELY?", "options": ["Copy the files to removable media so a second technician can verify", "Delete the folders and finish the drive replacement as scheduled", "Raise it with the employee directly before telling anyone else", "Stop work, alter nothing, secure the workstation, and report it under policy"], "answer": 1, "explanation": "When encountering illegal material or severe policy violations, the mandatory first-responder procedure is: 1. Immediately cease all interaction with the system to avoid altering file timestamps or evidence, 2. Secure and isolate the device to prevent tampering, and 3. Promptly notify management, corporate legal counsel, and the designated Incident Response / Security team in accordance with organizational policy. Copying data, deleting evidence (spoliation), or confronting the suspect compromises the investigation.", "distractor_analysis": {"1": "Copying the material spreads it and puts the technician in possession of it. Never move the data.", "2": "Deleting it destroys evidence and may itself be an offence.", "3": "Warning the subject gives them time to destroy evidence and puts the technician at risk."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["incident-response", "first-responder", "prohibited-activity", "policy"], "id": "C2N-O-019"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "A database contains customer Social Security numbers, dates of birth, full legal names, and home addresses. Under privacy frameworks (such as GDPR and NIST standards), how is this data categorized?", "options": ["Public Domain open-source telemetry", "Non-confidential marketing metadata", "Personally Identifiable Information (PII)", "Protected Health Information (PHI) exclusively"], "answer": 2, "explanation": "Personally Identifiable Information (PII) refers to any data that can be used alone or in combination with other relevant information to identify, contact, or locate a specific individual (e.g., SSNs, full names, birthdates, biometric records, driver's license numbers). Protected Health Information (PHI) specifically involves medical records/health conditions tied to an individual. Public domain data is unrestrictedly open, and marketing metadata is non-identifying aggregate data.", "distractor_analysis": {"1": "PHI (Protected Health Information) specifically encompasses medical diagnoses, treatment notes, and healthcare billing records governed by HIPAA.", "2": "Public domain information is freely publishable without restriction, which is the exact opposite of highly sensitive customer SSNs.", "3": "Social Security numbers and residential addresses are strictly confidential regulatory data, not non-confidential marketing telemetry."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["privacy-regulations", "pii", "phi", "gdpr", "compliance"], "id": "C2N-O-020"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.6", "type": "single", "difficulty": "medium", "question": "A business purchases 50 standalone commercial software licenses for an image editing program. During an internal audit, the IT team discovers the software is installed on 85 corporate workstations. What type of compliance violation has occurred?", "options": ["Hardware warranty expiration", "Software license compliance violation / under-licensing breach", "Denial of Service (DoS) attack", "Physical asset theft"], "answer": 3, "explanation": "Software licensing compliance requires organizations to possess valid, legal license entitlements for every active installation of proprietary commercial software. Having 85 active installations with only 50 purchased seats represents an under-licensing breach (software piracy/contract violation) that exposes the company to severe financial penalties and legal liability from vendor audits (e.g., BSA). It is not a DoS attack, physical theft, or warranty expiration.", "distractor_analysis": {"1": "A Denial of Service attack is a network cyberattack designed to overwhelm system resources, not a software license accounting deficit.", "2": "Physical asset theft involves stealing physical hardware devices, whereas under-licensing is an intellectual property contract infringement.", "3": "Hardware warranty expiration marks the end of OEM hardware repair coverage and does not relate to software seat count compliance."}, "video_reference": {"title": "Incident Response - CompTIA A+ 220-1202 - 4.6", "url": "https://www.youtube.com/watch?v=jKhIYQioCE8", "duration": "6:43", "objective": "4.6"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["licensing", "compliance", "commercial-license", "open-source"], "id": "C2N-O-021"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "easy", "question": "A frustrated user calls the help desk in an agitated state because a projector failed right before a major executive presentation. Which communication technique should the technician employ FIRST?", "options": ["Put the user on hold for 15 minutes to allow them to calm down", "Argue with the user and state that AV equipment is not IT's responsibility", "Practice active listening: remain calm, do not interrupt, acknowledge the user's urgency with empathy, and clarify the problem concisely", "Immediately interrupt the user and explain that projectors fail all the time"], "answer": 2, "explanation": "CompTIA professional communication guidelines emphasize active listening and de-escalation when interacting with distressed or angry customers: maintain a calm, professional tone, allow the customer to explain without interruption, validate their situation with genuine empathy, and ask clarifying diagnostic questions to resolve the issue swiftly. Interrupting, argumentative behavior, or placing agitated users on long holds damages customer rapport and escalates tension.", "distractor_analysis": {"1": "Interrupting the customer invalidates their concern, creates defensive hostility, and prevents gathering essential troubleshooting details.", "2": "Placing an agitated user on an unannounced hold increases customer frustration and delays time-critical presentation support.", "3": "Arguing with customers or deflecting responsibility is unprofessional and directly violates customer service standards."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "communication", "active-listening", "customer-service"], "id": "C2N-O-023"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "medium", "question": "While explaining a printer connectivity issue to a non-technical marketing executive, how should the technician describe the root cause?", "options": ["Tell the user that 'the DHCP pool exhausted its lease scope and ARP requests dropped with 100% packet loss on the 802.1Q trunk'", "Refuse to explain the issue because non-technical users cannot understand networking", "Advise the user to read the IEEE 802.3 Ethernet standards documentation", "Use clear, plain language avoiding obscure acronyms and technical jargon, explaining that the printer lost its network address assignment"], "answer": 1, "explanation": "Professional IT communication requires adapting technical language to the audience. When speaking with non-technical users, technicians should avoid heavy technical jargon, obscure protocol acronyms, and condescending terminology. Explaining concepts clearly in plain terms builds trust and ensures effective communication. Inundating users with low-level protocol acronyms or dismissing their questions violates professional standards.", "distractor_analysis": {"1": "Overloading non-technical clients with complex networking jargon confuses the customer and hampers collaborative communication.", "2": "Refusing to communicate technical status is disrespectful, unhelpful, and fosters a toxic IT-business relationship.", "3": "Instructing business executives to review IEEE technical specifications is dismissive and unprofessional."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "jargon", "communication", "clarity"], "id": "C2N-O-022"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.7", "type": "single", "difficulty": "medium", "question": "A technician determines that a replacement laptop display panel must be ordered from the vendor, which will take two business days to arrive. What should the technician communicate to the customer?", "options": ["Take the user's laptop home over the weekend without logging a ticket", "Set realistic expectations by explaining the parts timeline, provide a temporary loaner laptop if available, and update the ticket with follow-up milestones", "Promise the customer that the laptop will definitely be ready in one hour", "Close the ticket immediately and tell the customer to check back next week"], "answer": 3, "explanation": "Setting clear and realistic expectations is a fundamental tenet of IT customer service. When parts must be ordered, the technician should provide an honest delivery timeline, offer interim solutions (such as a loaner machine) to maintain user productivity, document the status in the ticketing system, and provide periodic progress updates. Falsely promising unrealistic turnaround times, closing unresolved tickets, or removing hardware off-site violates professional ethics.", "distractor_analysis": {"1": "Promising a one-hour resolution when parts require two days to ship sets false expectations and destroys customer trust.", "2": "Closing active tickets before hardware repair completion distorts service queues and leaves the customer without resolution tracking.", "3": "Taking company hardware off-site without authorization violates asset management, security policy, and professional ethics."}, "video_reference": {"title": "Professionalism - CompTIA A+ 220-1202 - 4.7", "url": "https://www.youtube.com/watch?v=8kKg8RJHAFQ", "duration": "4:47", "objective": "4.7"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["professionalism", "expectations", "follow-up", "documentation"], "id": "C2N-O-024"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "hard", "question": "A systems administrator is reviewing automated administrative maintenance scripts across Windows and Linux environments. Which script file extension is correctly paired with its native scripting interpreter?", "options": ["`.sh` - Windows Command Prompt batch processor", "`.bat` - Linux Bourne-Again Shell (Bash)", "`.py` - AppleScript interpreter", "`.ps1` - Microsoft PowerShell"], "answer": 1, "explanation": "In system administration scripting: `.ps1` files execute in Microsoft PowerShell, `.sh` files are shell scripts executed by Unix/Linux shells (such as Bash), `.bat` and `.cmd` files are legacy batch scripts executed by Windows `cmd.exe`, and `.py` files execute in the Python runtime interpreter. `.vbs` represents VBScript and `.js` represents JavaScript.", "distractor_analysis": {"1": "`.sh` files are Unix/Linux Bourne/Bash shell scripts, not Windows Command Prompt batch files.", "2": "`.bat` files are MS-DOS/Windows batch scripts, whereas Linux uses `.sh` shell scripts.", "3": "`.py` files are executed by the Python runtime environment, whereas AppleScript uses `.scpt` or `.applescript`."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "file-extensions", "powershell", "bash", "python"], "id": "C2N-O-025"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "medium", "question": "A technician writes a script that must iterate through a text file containing 100 computer hostnames and execute a ping test on each machine one by one. Which programming construct is used to repeat this operation across the list?", "options": ["A comment block (`#` or `REM`)", "An environment variable export", "A loop construct (such as a `for` or `foreach` loop)", "A constant variable declaration"], "answer": 2, "explanation": "A loop construct (such as `for`, `foreach`, or `while`) iterates over a collection or list of items (like 100 hostnames from a file), executing the defined block of commands once for each element in sequence until the collection is exhausted. Constants store immutable single values, comments are non-executing documentation annotations, and environment variables hold global OS session values.", "distractor_analysis": {"1": "Constants store fixed, non-changing data values and cannot iterate through arrays of hostnames.", "2": "Comments provide explanatory notes within source code and are completely ignored by the script interpreter during execution.", "3": "Environment variables store global system paths and configuration data rather than executing iterative programming logic."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "constructs", "variables", "loops", "conditionals"], "id": "C2N-O-026"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.8", "type": "single", "difficulty": "hard", "question": "In a PowerShell or Python script, a variable is assigned the value `$isServerOnline = $true` (or `is_server_online = True`). Which basic computer data type does this variable represent?", "options": ["String (text character sequence)", "Boolean (representing true or false)", "Integer (whole numeric value)", "Floating-point number (decimal value)"], "answer": 3, "explanation": "A Boolean data type represents one of two binary truth values: True or False (often represented as 1 or 0). It is universally used in programming and scripting to evaluate conditionals (`if`/`else` statements). Integers represent whole numbers (e.g., 42), floating-point numbers represent decimals (e.g., 3.14), and strings represent alphanumeric text strings enclosed in quotes.", "distractor_analysis": {"1": "Integers represent whole numbers without decimal points (e.g., -5, 0, 100), not binary True/False logic states.", "2": "Floating-point variables represent fractional numbers containing decimal points (e.g., 19.99), not Boolean truth states.", "3": "Strings represent character arrays and textual data enclosed in quotation marks (e.g., \"Server01\"), not native Boolean primitives."}, "video_reference": {"title": "Scripting Languages - CompTIA A+ 220-1202 - 4.8", "url": "https://www.youtube.com/watch?v=nJKUP1twjbY", "duration": "6:00", "objective": "4.8"}, "notes_reference": "32_Change_Management_Safety_Environment_Scripting.md", "tags": ["scripting", "data-types", "string", "integer", "boolean"], "id": "C2N-O-027"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "A systems administrator needs to establish a fully encrypted graphical desktop management session into a remote Windows Server across the corporate LAN. Which native protocol and default TCP port does Windows Remote Desktop utilize?", "options": ["Telnet over TCP port 23", "VNC over TCP port 5900", "SSH over TCP port 22", "RDP over TCP port 3389"], "answer": 1, "explanation": "Windows Remote Desktop utilizes Microsoft's proprietary Remote Desktop Protocol (RDP), which by default listens on TCP port 3389 (and optionally UDP 3389 for enhanced performance). RDP provides an encrypted, full GUI desktop session. Telnet operates on port 23 in unencrypted plaintext CLI, VNC defaults to TCP port 5900, and SSH operates over TCP port 22 for secure CLI access.", "distractor_analysis": {"1": "Telnet is a cleartext text-mode session with no graphical desktop and no encryption.", "2": "VNC does provide a remote desktop, but it is not native to Windows and is not RDP.", "3": "SSH is encrypted but gives a command-line session unless X11 forwarding is added."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "rdp", "port-3389", "windows-remote-desktop"], "id": "C2N-O-028"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "hard", "question": "A help desk technician needs to view an end user's desktop screen and provide guidance while the user remains logged in and actively watching the session. Which Windows built-in tool is designed specifically for this collaborative screen-sharing scenario?", "options": ["Secure Shell (`ssh.exe`)", "Diskpart (`diskpart.exe`)", "Windows Remote Assistance (`msra.exe`) / Quick Assist", "Standard Remote Desktop Connection (`mstsc.exe`)"], "answer": 2, "explanation": "Windows Remote Assistance (`msra.exe`) and Quick Assist allow a technician and a remote user to view the same desktop screen simultaneously, share mouse/keyboard control upon user permission, and chat without logging the user out. In contrast, standard Remote Desktop (`mstsc.exe`) locks the local user's screen or disconnects their active interactive console session on client editions of Windows. SSH provides a CLI shell, and Diskpart manages disk partitions.", "distractor_analysis": {"1": "Standard Remote Desktop (`mstsc.exe`) locks out the local user or terminates their interactive desktop session, preventing collaborative troubleshooting.", "2": "SSH (`ssh.exe`) opens a secure command-line terminal session without providing a shared graphical desktop interface.", "3": "Diskpart is a command-line disk partitioning and storage configuration utility, completely unrelated to remote desktop assistance."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "msra", "remote-assistance", "rdp-vs-msra"], "id": "C2N-O-029"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.9", "type": "single", "difficulty": "medium", "question": "A systems engineer needs to securely connect to a remote headless Linux database server's command-line shell to modify configuration files over an untrusted network. Which protocol and default port must be used?", "options": ["TFTP over UDP port 69", "SSH (Secure Shell) over TCP port 22", "Telnet over TCP port 23", "FTP over TCP port 21"], "answer": 3, "explanation": "SSH (Secure Shell) operates over TCP port 22 and provides strong public-key/password authentication and symmetric encryption for remote command-line access, file transfers (SFTP/SCP), and port forwarding. Telnet (port 23) transmits all session text unencrypted, FTP (port 21) transfers files in plaintext, and TFTP (UDP 69) is a simple unauthenticated UDP file transfer protocol.", "distractor_analysis": {"1": "Telnet operates on TCP port 23 and transmits all passwords and commands in cleartext, making it insecure for remote administration.", "2": "FTP (File Transfer Protocol) runs on port 21 for transferring files and does not provide an interactive remote shell environment.", "3": "TFTP (Trivial File Transfer Protocol) uses UDP 69 for basic bootstrap firmware transfers without authentication or shell access."}, "video_reference": {"title": "Remote Access - CompTIA A+ 220-1202 - 4.9", "url": "https://www.youtube.com/watch?v=B-xa0hjmuAs", "duration": "12:49", "objective": "4.9"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["remote-access", "ssh", "port-22", "linux-management"], "id": "C2N-O-030"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.10", "type": "single", "difficulty": "hard", "question": "A junior software developer pastes proprietary internal source code and customer database connection strings into a public, consumer-tier Generative AI chatbot to optimize a query. What major security and privacy risk has occurred?", "options": ["A denial of service against the production database from the chatbot", "A licence violation, because the generated output carries a copyleft licence", "A credential rotation failure, because the strings were URL encoded", "A data privacy breach and IP exfiltration, since prompts may be retained for training"], "answer": 1, "explanation": "Pasting proprietary source code, credentials, API keys, or Personally Identifiable Information (PII) into public, unvetted consumer AI platforms exposes the organization to massive intellectual property leaks and regulatory compliance violations. Many public AI services retain prompt data to train future models, potentially exposing confidential data to external users. Enterprise AI deployments require data-retention opt-outs and privacy boundaries. It does not cause DoS attacks or hardware processor damage.", "distractor_analysis": {"1": "The chatbot never touched the database. Nothing was flooded; data simply left the boundary.", "2": "Output licensing is a separate commercial question and is not the risk created by pasting secrets.", "3": "Encoding does not protect a secret. The credentials were disclosed the moment they were pasted."}, "video_reference": {"title": "Managing AI - CompTIA A+ 220-1202 - 4.10", "url": "https://www.youtube.com/watch?v=oofb6ROU7LM", "duration": "10:38", "objective": "4.10"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["artificial-intelligence", "data-privacy", "confidentiality", "ip-leakage"], "id": "C2N-O-031"}, {"exam": "core2", "domain": "4.0 Operational Procedures", "objective": "4.10", "type": "single", "difficulty": "medium", "question": "An IT technician uses an AI assistant to generate a complex PowerShell script for server provisioning. The AI produces code referencing non-existent cmdlet parameters that fail when executed. What AI phenomenon describes this behavior, and what operational procedure MUST the technician always follow?", "options": ["Phishing attack; the technician should immediately format the workstation drive", "SQL Injection; the technician should replace the server RAM modules", "AI Hallucination; the technician must always review, verify, and test all AI-generated code and configuration scripts in a sandbox before executing in production", "Buffer Overflow; the technician should delete the PowerShell application from Windows"], "answer": 2, "explanation": "AI Hallucination refers to generative AI models confidently producing plausible-sounding but factually incorrect, synthetically fabricated, or non-existent syntax, commands, or data. IT operational best practices mandate that human engineers treat all AI-generated content as unverified drafts: technicians must critically review the syntax, verify command parameters against official documentation, and rigorously test scripts in an isolated sandbox environment before running them in production.", "distractor_analysis": {"1": "Buffer overflow is a memory management vulnerability in binary software, not an AI model generating non-existent script parameters.", "2": "Phishing is social engineering via deceptive communication; receiving incorrect AI responses is not a phishing attack requiring drive wiping.", "3": "SQL injection is a web database attack; erroneous AI script suggestions have zero connection to physical RAM hardware defects."}, "video_reference": {"title": "Managing AI - CompTIA A+ 220-1202 - 4.10", "url": "https://www.youtube.com/watch?v=oofb6ROU7LM", "duration": "10:38", "objective": "4.10"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["artificial-intelligence", "hallucinations", "verification", "copilot"], "id": "C2N-O-032"}, {"id": "C2N-OS-001", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "easy", "question": "A user wants to change which program opens PDF files by default in Windows. Where is this configured?", "options": ["Windows Defender Firewall", "Settings, Apps, Default apps", "Device Manager", "Disk Management"], "answer": 3, "explanation": "Default apps in Windows Settings lets a user choose the application associated with each file type and protocol, either per application or by picking a file extension such as .pdf and selecting the handler. Device Manager lists hardware, Disk Management handles volumes and partitions, and the firewall controls network traffic; none of them govern file associations. Technicians see this after a new program installs itself as the default and the user wants the old one back.", "distractor_analysis": {"1": "Device Manager manages drivers and hardware.", "2": "Disk Management handles storage volumes.", "3": "The firewall filters network connections."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "default-apps"]}, {"id": "C2N-OS-002", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A technician needs to remove a program that does not appear in the Windows Settings Apps list but is visible in the classic Control Panel. Which Control Panel applet is used?", "options": ["Devices and Printers", "Internet Options", "Ease of Access Center", "Programs and Features"], "answer": 1, "explanation": "Programs and Features is the long-standing Control Panel applet for uninstalling, changing or repairing installed applications and for turning Windows features on or off. Some older installers register only there. Devices and Printers manages hardware, Internet Options configures legacy browser and proxy settings, and Ease of Access holds accessibility options. Knowing both the Settings and Control Panel locations matters because Windows still splits functions between them.", "distractor_analysis": {"1": "Devices and Printers handles peripherals.", "2": "Internet Options sets proxy, security zones and browser defaults.", "3": "Ease of Access covers accessibility features."}, "video_reference": {"title": "The Windows Control Panel - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=AhGWshIRcKw", "duration": "23:09", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "control-panel", "programs-and-features"]}, {"id": "C2N-OS-003", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A user's laptop goes to sleep after two minutes of inactivity during presentations. Which Control Panel applet or Settings page adjusts this?", "options": ["Network and Sharing Center", "User Accounts", "Power Options, or Settings, System, Power and battery", "Sound"], "answer": 2, "explanation": "Sleep and display timeouts live in the power plan. The classic Power Options applet exposes plan settings including sleep timers, lid actions and advanced options, and the modern Settings equivalent is System, Power and battery. Creating a presentation plan with sleep disabled on mains power solves the complaint without leaving the laptop awake forever. Sound, network and account applets have no control over power behaviour.", "distractor_analysis": {"1": "Sound manages audio devices.", "2": "Network and Sharing Center configures connections.", "3": "User Accounts manages local accounts and credentials."}, "video_reference": {"title": "The Windows Control Panel - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=AhGWshIRcKw", "duration": "23:09", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "control-panel", "power-options"]}, {"id": "C2N-OS-004", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "An office requires all browsers on a PC to send web traffic through a corporate proxy. Which legacy Control Panel applet holds the system-wide proxy setting that Windows and many applications use?", "options": ["Indexing Options", "Internet Options, on the Connections tab under LAN settings", "Programs and Features", "Administrative Tools"], "answer": 3, "explanation": "The system proxy is configured in Internet Options under Connections, LAN settings, or equivalently in Settings, Network and internet, Proxy. Windows components and most browsers read that setting, so it is the single place to point a machine at a proxy or a configuration script. In managed environments it is usually pushed by Group Policy. Programs and Features uninstalls software, Administrative Tools is a collection of consoles, and Indexing Options controls search indexing.", "distractor_analysis": {"1": "Programs and Features manages installed software.", "2": "Administrative Tools is a folder of management consoles.", "3": "Indexing Options governs Windows Search."}, "video_reference": {"title": "The Windows Control Panel - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=AhGWshIRcKw", "duration": "23:09", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "control-panel", "internet-options", "proxy"]}, {"id": "C2N-OS-005", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A user with low vision needs larger text and a high-contrast colour scheme across Windows. Where should the technician configure this?", "options": ["Device Manager", "Disk Cleanup", "Task Scheduler", "Settings, Accessibility (Ease of Access), for text size and contrast themes"], "answer": 1, "explanation": "Accessibility settings, called Ease of Access in older versions, gather text scaling, contrast themes, Magnifier, Narrator, colour filters and mouse and keyboard aids in one place. Text size applies system-wide without changing resolution, and contrast themes replace the colour scheme for readability. Configuring accessibility correctly is a routine part of supporting users with disabilities. The other tools manage hardware, disk space and scheduled jobs.", "distractor_analysis": {"1": "Device Manager is for hardware and drivers.", "2": "Disk Cleanup frees storage.", "3": "Task Scheduler runs jobs at set times."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "accessibility"]}, {"id": "C2N-OS-006", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A technician needs to view a PC's processor, installed memory, Windows edition and whether it is joined to a domain. Which single location displays every one of those details?", "options": ["Default apps", "Personalization", "Settings, System, About (or the System applet in Control Panel)", "Sound settings"], "answer": 2, "explanation": "The About page summarises device specifications and Windows specifications: processor, RAM, device name, system type, edition, version and build, and provides links to rename the PC and to domain or workgroup settings. It replaces the classic System applet and is the first stop when confirming a machine meets an application's requirements or checking which update branch it is on. Audio, application defaults and appearance pages do not show system specifications.", "distractor_analysis": {"1": "Sound settings manage audio.", "2": "Default apps handle file associations.", "3": "Personalization controls appearance."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "system-about"]}, {"id": "C2N-OS-007", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A shared office PC must be configured so that a second local user can sign in with their own profile. Where does the technician add the account?", "options": ["Settings, Gaming", "Settings, Accounts, Other users (or the User Accounts applet)", "Settings, Privacy", "Settings, Time and language"], "answer": 3, "explanation": "Local and Microsoft accounts are added under Accounts, Other users, where the technician chooses a local account or an online account and sets the account type to standard or administrator. Standard accounts are the default for shared machines so one user cannot alter system settings for everyone. The classic User Accounts applet does the same. Privacy, regional and gaming settings do not create users.", "distractor_analysis": {"1": "Privacy controls app permissions and diagnostics.", "2": "Time and language sets region, clock and keyboards.", "3": "Gaming settings concern the Game Bar and captures."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "accounts", "local-user"]}, {"id": "C2N-OS-008", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A user reports that Windows automatically restarted overnight to install updates and they lost unsaved work. Which setting reduces the chance of this happening again?", "options": ["Disabling the firewall", "Changing the desktop wallpaper", "Removing the user's account", "Active hours in Settings, Windows Update, so restarts are not scheduled during the user's working times"], "answer": 1, "explanation": "Windows Update allows the user or administrator to define active hours during which the system will not restart automatically, and to schedule or pause restarts. Setting realistic active hours, and reminding users to save work, avoids overnight surprises without leaving the machine unpatched. Security settings, appearance and account changes are irrelevant, and updates should never be disabled entirely on a production PC.", "distractor_analysis": {"1": "The firewall has nothing to do with update scheduling and should stay on.", "2": "Wallpaper is cosmetic.", "3": "Removing the account solves nothing and loses the profile."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "windows-update", "active-hours"]}, {"id": "C2N-OS-009", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "single", "difficulty": "medium", "question": "A technician must find out which application is allowed to use the webcam and turn that access off for an untrusted program. Which Settings page controls this?", "options": ["Settings, System, Storage", "Settings, Apps, Startup", "Settings, Privacy and security, Camera", "Settings, Personalization, Themes"], "answer": 2, "explanation": "The Privacy and security section lists each sensitive capability, such as camera, microphone and location, shows which apps have requested it and allows access to be switched off globally or per application. It also shows recent usage. This is the right place both for privacy concerns and for troubleshooting an application that cannot see the camera. Themes, storage and startup pages do not manage hardware permissions.", "distractor_analysis": {"1": "Themes change appearance.", "2": "Storage shows disk usage.", "3": "Startup controls which apps run at sign-in, not their camera access."}, "video_reference": {"title": "Windows Settings - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=0qfZtEZCvn0", "duration": "6:34", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "settings", "privacy", "camera"]}, {"id": "C2N-OS-010", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.6", "type": "match", "difficulty": "medium", "question": "Match each Windows configuration task to the Control Panel applet or Settings page that performs it.", "pairs": [{"left": "Uninstall a legacy program", "right": "Programs and Features"}, {"left": "Set the system proxy", "right": "Internet Options"}, {"left": "Change sleep timers", "right": "Power Options"}, {"left": "Choose the default PDF viewer", "right": "Default apps"}, {"left": "Enable a high-contrast theme", "right": "Accessibility (Ease of Access)"}], "explanation": "Windows keeps configuration in two places, the classic Control Panel and the modern Settings app, and a technician needs to know both. Programs and Features handles software removal, Internet Options holds the proxy and legacy browser settings, Power Options manages plans and timers, Default apps assigns file handlers, and Accessibility gathers vision, hearing and input aids. Going straight to the right location saves time on every support call.", "video_reference": {"title": "The Windows Control Panel - CompTIA A+ 220-1202 - 1.6", "url": "https://www.youtube.com/watch?v=AhGWshIRcKw", "duration": "23:09", "objective": "1.6"}, "notes_reference": "18_Windows_Settings_and_Configuration.md", "tags": ["windows", "control-panel", "settings", "match"]}, {"id": "C2N-OS-011", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A technician must give a Windows server a fixed IP address, subnet mask, gateway and DNS servers. Where is this configured?", "options": ["Disk Management", "The IPv4 properties of the network adapter, reached through Network Connections or Settings, Network and internet", "Programs and Features", "Device Manager's driver tab"], "answer": 3, "explanation": "Static addressing is set on the adapter itself. In Network Connections the adapter's properties expose Internet Protocol Version 4 settings where the address, mask, gateway and DNS servers are typed, and the modern Settings path offers the same through Edit IP assignment. Servers and printers get static addresses; workstations should stay on DHCP. Software removal, driver details and storage management do not touch IP configuration.", "distractor_analysis": {"1": "Programs and Features manages installed software.", "2": "The driver tab updates or rolls back drivers, not addressing.", "3": "Disk Management is for volumes."}, "video_reference": {"title": "Windows IP Address Configuration - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=wA0BV7FzH9Q", "duration": "6:45", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "networking", "static-ip", "adapter-properties"]}, {"id": "C2N-OS-012", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A developer runs a web server on a Windows PC for testing and colleagues cannot connect to it, although the developer can browse it locally. What is the most likely fix?", "options": ["Disable the network adapter", "Change the PC's wallpaper", "Uninstall the web server", "Create an inbound rule in Windows Defender Firewall allowing the server's port"], "answer": 1, "explanation": "Windows Firewall blocks unsolicited inbound connections by default, so a service that works locally but not from other machines is almost always being filtered. Adding an inbound rule for the specific port or program, scoped to the local network profile, allows colleagues in while keeping the default protection. Turning the whole firewall off is never the right answer. Disabling the adapter or removing the server defeats the purpose, and appearance settings are irrelevant.", "distractor_analysis": {"1": "Disabling the adapter removes all connectivity.", "2": "Wallpaper has no effect on networking.", "3": "Removing the server is the opposite of the goal."}, "video_reference": {"title": "Configuring Windows Firewall - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=ZmtkzwzVDaE", "duration": "6:32", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "firewall", "inbound-rule", "networking"]}, {"id": "C2N-OS-013", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A laptop shows its Wi-Fi network profile as Public, and the user cannot see shared printers on the home network. What should be changed?", "options": ["Change the Wi-Fi channel on the router", "Turn off the laptop's Bluetooth", "Set the network profile to Private so network discovery and sharing rules apply", "Reinstall the wireless driver"], "answer": 2, "explanation": "Windows applies different firewall and discovery rules depending on whether a network is marked Public or Private. On a Public network, discovery and file and printer sharing are blocked to protect the laptop in cafes and airports. Marking a trusted home or office network as Private enables discovery and the sharing rules. The choice is made in the network's properties. Drivers, router channels and Bluetooth do not influence the profile.", "distractor_analysis": {"1": "The adapter is connected and working.", "2": "Channel selection affects radio performance, not discovery rules.", "3": "Bluetooth is unrelated to network profiles."}, "video_reference": {"title": "Windows Network Technologies - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=1OlbYiS-xHY", "duration": "8:37", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "networking", "network-profile", "discovery"]}, {"id": "C2N-OS-014", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A user wants a shared folder on a server to appear as drive S: every time they sign in. Which action achieves this?", "options": ["Add the server to the hosts file", "Map a network drive to the UNC path and tick Reconnect at sign-in", "Create a shortcut on the desktop", "Copy the folder to the local disk"], "answer": 3, "explanation": "Mapping a network drive assigns a letter to a UNC path such as a server share, and the reconnect option stores the mapping in the user's profile so it returns at each sign-in. In domains this is usually done centrally by Group Policy or a logon script so every user gets the same letters. A shortcut opens the share but gives no drive letter, copying breaks the single shared copy, and the hosts file only maps names to addresses.", "distractor_analysis": {"1": "A shortcut does not create a drive letter for applications that need one.", "2": "A local copy diverges from the shared data.", "3": "The hosts file does name resolution, not drive mapping."}, "video_reference": {"title": "Windows Network Technologies - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=1OlbYiS-xHY", "duration": "8:37", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "networking", "mapped-drive", "unc"]}, {"id": "C2N-OS-015", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "medium", "question": "A remote worker must connect to the office network from a Windows laptop using the built-in client. Which Settings area is used to add the connection?", "options": ["Settings, Apps, Optional features", "Settings, System, Display", "Settings, Accounts, Sign-in options", "Settings, Network and internet, VPN"], "answer": 1, "explanation": "Windows includes a VPN client supporting IKEv2, SSTP, L2TP over IPsec and PPTP, configured under Network and internet, VPN with the server address, protocol and credentials. Many organisations use a third-party client instead, but the built-in one is common for small deployments. The connection then appears alongside Wi-Fi in the network flyout. Optional features, display and sign-in options do not create network connections.", "distractor_analysis": {"1": "Optional features adds Windows components such as fonts or tools.", "2": "Display settings manage screens.", "3": "Sign-in options manage PINs and biometrics."}, "video_reference": {"title": "Windows Network Technologies - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=1OlbYiS-xHY", "duration": "8:37", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "networking", "vpn", "settings"]}, {"id": "C2N-OS-016", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.7", "type": "single", "difficulty": "hard", "question": "A PC on a corporate network has a valid address but cannot reach a server on another subnet, while it can reach everything on its own subnet. Which setting on the PC is the most likely cause?", "options": ["A disabled screen saver", "The wrong time zone", "An incorrect or missing default gateway", "The wrong computer name"], "answer": 2, "explanation": "Traffic to any address outside the local subnet is sent to the default gateway. If that setting is blank or points to the wrong router, local communication works perfectly and every remote destination fails. Checking the adapter's IPv4 configuration with ipconfig and correcting the gateway, or renewing the DHCP lease, fixes it. Names, screen savers and time zones cannot affect whether packets leave the subnet.", "distractor_analysis": {"1": "The computer name does not affect routing.", "2": "Screen savers are unrelated to networking.", "3": "Time zone affects clocks, not routing."}, "video_reference": {"title": "Windows IP Address Configuration - CompTIA A+ 220-1202 - 1.7", "url": "https://www.youtube.com/watch?v=wA0BV7FzH9Q", "duration": "6:45", "objective": "1.7"}, "notes_reference": "20_Windows_Networking_and_Troubleshooting_Tools.md", "tags": ["windows", "networking", "default-gateway", "troubleshooting"]}, {"id": "C2N-OS-017", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.11", "type": "single", "difficulty": "easy", "question": "A team wants to write a document together at the same time, seeing each other's edits as they type. Which category of software provides this?", "options": ["A firmware update utility", "Cloud productivity suites with real-time co-authoring, such as Microsoft 365 or Google Workspace", "A local text editor", "A disk imaging tool"], "answer": 3, "explanation": "Cloud productivity tools store the document in the provider's service and let several people edit simultaneously in a browser or desktop app, with changes merged live, comments and version history. Sharing is controlled by links and permissions. Technicians support sign-in, sharing permissions, sync clients and the occasional conflicted copy. A local editor holds one copy on one machine, and imaging and firmware tools have nothing to do with documents.", "distractor_analysis": {"1": "A local editor cannot merge simultaneous edits from several people.", "2": "Imaging tools copy disks.", "3": "Firmware utilities update device firmware."}, "video_reference": {"title": "Cloud Productivity Tools - CompTIA A+ 220-1202 - 1.11", "url": "https://www.youtube.com/watch?v=FTRbdIjK1DU", "duration": "5:47", "objective": "1.11"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["cloud", "productivity", "co-authoring"]}, {"id": "C2N-OS-018", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.11", "type": "single", "difficulty": "medium", "question": "A user shared a cloud document with a colleague using a link, and the colleague can read it but cannot make changes. What should the user do?", "options": ["Email the file as an attachment every time it changes", "Reinstall the office application", "Convert the document to a PDF", "Change the sharing permission on the link or the person from view to edit"], "answer": 1, "explanation": "Cloud sharing separates access from permission level. A link or a named share can grant view only, comment or edit rights, and the default for many organisations is view. Changing the permission in the share dialog gives the colleague edit access without creating copies. Emailing attachments loses the single-source benefit, the application is working, and a PDF is designed not to be edited.", "distractor_analysis": {"1": "Attachments create diverging copies.", "2": "The application is not at fault.", "3": "PDFs are for fixed-layout distribution, not collaborative editing."}, "video_reference": {"title": "Cloud Productivity Tools - CompTIA A+ 220-1202 - 1.11", "url": "https://www.youtube.com/watch?v=FTRbdIjK1DU", "duration": "5:47", "objective": "1.11"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["cloud", "productivity", "sharing", "permissions"]}, {"id": "C2N-OS-019", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.11", "type": "single", "difficulty": "medium", "question": "A user overwrote an important section of a shared cloud spreadsheet and saved. How can the earlier content be recovered?", "options": ["Reinstall the browser", "Ask the internet provider for a backup", "Open the file's version history and restore or copy from an earlier version", "Recover it from the local recycle bin"], "answer": 2, "explanation": "Cloud productivity services keep a version history for every document, recording each saved state with the author and time. Opening the history allows a previous version to be viewed, restored in place or copied out, so an overwritten section is recoverable in minutes. The recycle bin holds deleted files rather than earlier versions, the browser is not at fault, and providers do not hold customers' document versions.", "distractor_analysis": {"1": "The file was not deleted; it was changed.", "2": "The browser is a viewer, not the store of the document.", "3": "Internet providers have no access to a cloud document's contents."}, "video_reference": {"title": "Cloud Productivity Tools - CompTIA A+ 220-1202 - 1.11", "url": "https://www.youtube.com/watch?v=FTRbdIjK1DU", "duration": "5:47", "objective": "1.11"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["cloud", "productivity", "version-history", "recovery"]}, {"id": "C2N-OS-020", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.11", "type": "single", "difficulty": "medium", "question": "A company moves from locally installed office software to a subscription cloud suite. Which support change should the help desk expect?", "options": ["The end of all password resets", "Fewer installation and patching tasks, and more identity, licensing and sharing-permission requests", "No change at all", "More work replacing hard drives"], "answer": 3, "explanation": "With a cloud suite the provider hosts the applications and applies updates, so the help desk spends less time installing and patching. In exchange, the common tickets become sign-in and multi-factor issues, licence assignment, sharing permissions, sync client problems and questions about where files live. Understanding the shift lets a support team retrain and adjust its knowledge base. Hardware failures and password resets continue much as before.", "distractor_analysis": {"1": "The workload changes in character even if not in volume.", "2": "Cloud suites do not affect disk failure rates.", "3": "Identity issues increase rather than disappear."}, "video_reference": {"title": "Cloud Productivity Tools - CompTIA A+ 220-1202 - 1.11", "url": "https://www.youtube.com/watch?v=FTRbdIjK1DU", "duration": "5:47", "objective": "1.11"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["cloud", "productivity", "support", "saas"]}, {"id": "C2N-OS-021", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.11", "type": "single", "difficulty": "medium", "question": "A user cannot open a cloud document on a train and asks why, since the same document opened fine at the office. What is the most likely explanation?", "options": ["The document was deleted by the provider", "The laptop's battery is too low to open documents", "The file is too large for the laptop's screen", "The document is not marked for offline access and the train has no internet connection"], "answer": 1, "explanation": "Cloud documents live on the provider's servers and are fetched on demand. Without connectivity they open only if the app or sync client has been told to keep an offline copy. Enabling offline access for the needed files before travelling, or using the sync client's always-available option, prevents this. The document still exists, battery level does not prevent opening files, and screen size is irrelevant to whether a file loads.", "distractor_analysis": {"1": "The provider does not delete customer documents.", "2": "A laptop that is on can open documents regardless of charge level.", "3": "File size and screen size are unrelated."}, "video_reference": {"title": "Cloud Productivity Tools - CompTIA A+ 220-1202 - 1.11", "url": "https://www.youtube.com/watch?v=FTRbdIjK1DU", "duration": "5:47", "objective": "1.11"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["cloud", "productivity", "offline-access"]}, {"id": "C2N-OS-022", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "Before installing a new design application, the technician checks its requirements: 16 GB of RAM, a 64-bit processor, 20 GB of disk space and a graphics card with 4 GB of memory. The target PC has 8 GB of RAM. What should the technician do?", "options": ["Uninstall the antivirus to free memory", "Reduce the screen resolution to save RAM", "Do not install until the PC meets the minimum requirements, because running below them causes poor performance or failure", "Install anyway and hope it works"], "answer": 2, "explanation": "Application system requirements state the minimum hardware the vendor supports. A machine with half the required memory will thrash, crash or refuse to install, and the vendor will not support it. The correct action is to upgrade the RAM, if the machine allows it, or choose different hardware. Installing regardless wastes time, removing security software is dangerous and frees little memory, and resolution has no meaningful effect on the memory the application needs.", "distractor_analysis": {"1": "Ignoring requirements leads to instability and unsupported configurations.", "2": "Antivirus uses a small fraction of memory and must not be removed.", "3": "Resolution changes negligible memory use."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["applications", "system-requirements", "installation"]}, {"id": "C2N-OS-023", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "A user tries to install a 64-bit application on a Windows PC and the installer refuses. The PC has a 64-bit processor but the operating system is 32-bit. What is the situation?", "options": ["The application is incompatible with all Windows versions", "A 32-bit operating system cannot run 64-bit applications; the OS would need to be reinstalled as 64-bit", "The application only needs a reboot", "The processor must be replaced"], "answer": 3, "explanation": "The operating system's architecture decides which applications can run. A 64-bit Windows runs both 64-bit and most 32-bit programs, but a 32-bit Windows can run only 32-bit programs regardless of how capable the processor is. Because the CPU is 64-bit, the fix is a clean installation of 64-bit Windows, which also unlocks more than 4 GB of memory. The processor is fine, a reboot changes nothing, and the application would run on a 64-bit installation.", "distractor_analysis": {"1": "Rebooting does not change the operating system architecture.", "2": "The processor already supports 64-bit.", "3": "The application is compatible with 64-bit Windows."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["applications", "32-bit", "64-bit", "architecture"]}, {"id": "C2N-OS-024", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "A department downloaded an installer from a file-sharing site because the vendor's download was slow. What is the primary risk and the correct practice?", "options": ["The download will be slower", "The installer will be in the wrong language", "There is no risk as long as the file name matches", "The installer may be tampered with or bundled with malware; always download from the vendor or an approved repository and verify the hash or signature"], "answer": 1, "explanation": "Installers from unofficial sources are a standard malware delivery method: the program works, and something else is installed alongside it. Organisations should obtain software only from the vendor, an app store or a managed repository, and check the publisher's digital signature or published checksum before running it. Speed and language are not the concern, and a matching file name proves nothing about the file's contents.", "distractor_analysis": {"1": "Speed is a convenience issue, not the danger.", "2": "Language would be an inconvenience, not a security risk.", "3": "File names are trivially faked."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["applications", "installation", "security", "distribution"]}, {"id": "C2N-OS-025", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "An organisation wants to install the same application on 200 PCs without visiting each one. Which approach should the technician recommend?", "options": ["Carry a USB drive to each desk", "Ask users to find it online", "Deploy the package centrally with a management tool such as Intune, Group Policy or a software deployment platform, using a silent install", "Email the installer to every user with instructions"], "answer": 2, "explanation": "Enterprise application deployment uses management platforms that push a packaged installer with silent-install switches to targeted devices, report success and failure, and can also update and remove the software later. It is consistent, auditable and scales without staff time per machine. Emailing installers, walking around with media and telling users to search online produce inconsistent versions, security exposure and a large support load.", "distractor_analysis": {"1": "Users install inconsistently and often incorrectly.", "2": "Two hundred desk visits is impractical and error-prone.", "3": "Users searching online may download the wrong or a malicious version."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["applications", "deployment", "installation", "management"]}, {"id": "C2N-OS-026", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.10", "type": "single", "difficulty": "medium", "question": "A new application installed on a shared PC changed the file associations, added a startup entry and installed a browser extension. Which consideration did the technician skip?", "options": ["Changing the desktop background", "Reviewing the impact of the installation on the device, other applications and the network before and during installation", "Checking the monitor's brightness", "Cleaning the keyboard"], "answer": 3, "explanation": "Installing software is not only about whether it runs. A technician should read what the installer will change, decline bundled extras and default changes, consider the effect on other users of a shared machine, and understand any network traffic or licensing implications. Reviewing these impacts, and testing on one machine before wide deployment, prevents exactly the side effects described. Physical cleaning and appearance settings are unrelated to installation practice.", "distractor_analysis": {"1": "Brightness has nothing to do with installation impact.", "2": "Keyboard hygiene is unrelated.", "3": "Wallpaper is cosmetic."}, "video_reference": {"title": "Installing Applications - CompTIA A+ 220-1202 - 1.10", "url": "https://www.youtube.com/watch?v=G2Equ2pG7aY", "duration": "16:27", "objective": "1.10"}, "notes_reference": "23_Windows_Editions_and_OS_Installation.md", "tags": ["applications", "installation", "impact", "best-practice"]}, {"id": "C2N-OS-027", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A user wants to format a 128 GB USB drive so it can be read and written on both Windows and macOS computers and hold files larger than 4 GB. Which file system should be chosen?", "options": ["FAT32", "NTFS", "ext4", "exFAT"], "answer": 1, "explanation": "exFAT was designed for removable media and is read and written natively by Windows and macOS, with no 4 GB file size limit and support for very large volumes. FAT32 is universally readable but caps individual files at 4 GB, which rules out large videos and disk images. NTFS is read-only on macOS without third-party software, and ext4 is a Linux file system that neither Windows nor macOS mounts by default.", "distractor_analysis": {"1": "FAT32 cannot store a single file larger than 4 GB.", "2": "macOS can read NTFS but not write to it natively.", "3": "ext4 is for Linux systems."}, "video_reference": {"title": "File Systems - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=lwCu2rpXP1E", "duration": "5:51", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["file-systems", "exfat", "removable-media"]}, {"id": "C2N-OS-028", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "Which Windows file system supports file-level permissions, encryption, compression and journaling, and is required for the system drive?", "options": ["exFAT", "APFS", "NTFS", "FAT32"], "answer": 2, "explanation": "NTFS is the native Windows file system. Its access control lists provide per-file and per-folder permissions, it supports Encrypting File System and compression attributes, journals changes for recovery after a crash, and handles very large volumes and files. Windows must be installed on NTFS. FAT32 and exFAT have no permissions or journaling, and APFS is Apple's file system for macOS and iOS.", "distractor_analysis": {"1": "FAT32 has no security features and a 4 GB file limit.", "2": "exFAT is for removable media and lacks permissions.", "3": "APFS is Apple's file system."}, "video_reference": {"title": "File Systems - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=lwCu2rpXP1E", "duration": "5:51", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["file-systems", "ntfs", "windows"]}, {"id": "C2N-OS-029", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A company standardises laptops on Windows but the design team needs macOS for a particular application, and a developer wants Linux. Which statement about supporting several operating systems is accurate?", "options": ["Linux cannot be managed centrally", "Each operating system has its own update cycle, management tooling and end-of-life schedule, so the support plan must cover all three", "One operating system's updates automatically apply to the others", "Only Windows requires security updates"], "answer": 3, "explanation": "Mixed environments are normal, but each platform must be planned for separately: patching cadence, management agents, backup, security software and the date the vendor stops supporting a version. Running an operating system past its end of life leaves it unpatched and often out of compliance. Updates never cross platforms, every operating system needs security patches, and Linux is routinely managed at scale with configuration management tools.", "distractor_analysis": {"1": "Updates are platform-specific.", "2": "macOS and Linux receive regular security updates too.", "3": "Linux has mature central management options."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["operating-systems", "end-of-life", "mixed-environment"]}, {"id": "C2N-OS-030", "exam": "core2", "domain": "1.0 Operating Systems", "objective": "1.1", "type": "single", "difficulty": "medium", "question": "A school runs a fleet of inexpensive laptops that boot straight into a browser-based environment with automatic updates and very little local storage. Which operating system is this?", "options": ["Windows Server", "macOS", "iOS", "ChromeOS"], "answer": 1, "explanation": "ChromeOS is Google's lightweight operating system built around the Chrome browser and web applications, with data kept in cloud accounts, verified boot and automatic updates. It is popular in education because devices are cheap, easy to manage centrally and reset quickly. Windows Server is a data centre operating system, macOS runs on Apple laptops and desktops, and iOS is the operating system on iPhones.", "distractor_analysis": {"1": "Windows Server is for servers, not classroom laptops.", "2": "macOS runs only on Apple hardware, which is not inexpensive.", "3": "iOS is a phone operating system."}, "video_reference": {"title": "Operating Systems Overview - CompTIA A+ 220-1202 - 1.1", "url": "https://www.youtube.com/watch?v=IhcZqUs1IF8", "duration": "12:59", "objective": "1.1"}, "notes_reference": "17_Support_Procedures_Professionalism_OS_Types.md", "tags": ["operating-systems", "chromeos", "education"]}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "hard", "question": "A datacenter security manager needs to prevent unauthorized individuals from following authorized employees through the server room entrance (tailgating/piggybacking). Which physical security control is MOST effective at enforcing single-person entry?", "options": ["A keycard badge reader that sounds an audible beep upon successful swipe", "A biometric fingerprint scanner installed on a standard swing door", "An access control vestibule (mantrap) with interlocking doors and weight sensors", "A high-definition CCTV security camera mounted above the doorway"], "answer": 2, "explanation": "An access control vestibule (mantrap) features two interlocking doors where the second door cannot open until the first door closes and the occupant is validated (often combined with weight sensors or optical counters). This physical barrier strictly prevents tailgating. CCTV cameras record footage but do not physically block tailgating. Standard badge readers and biometric scanners on a single door validate access but allow an unauthorized person to slip in behind an authorized user while the door is open.", "distractor_analysis": {"1": "CCTV cameras provide detective controls and forensic video logs, but they do not physically restrict entry or prevent piggybacking in real time.", "2": "A single-door badge reader unlocks the latch for several seconds, allowing an unauthenticated follower to catch the door before it closes.", "3": "Biometric scanners verify identity accurately, but when fitted to a single swing door, they cannot physically stop a second person from walking in behind the authenticated individual."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["physical-security", "access-control", "mantrap", "datacenter"], "id": "C2N-S-001"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A company requires all systems engineers to authenticate to administrative consoles using multifactor authentication (MFA). Which authentication combination fulfills true MFA requirements?", "options": ["A username and password combined with answering three secret security questions", "An SMS verification code sent to a mobile phone alongside an emailed OTP code", "A complex 16-character alphanumeric password and a secondary memorized PIN", "A hardware smart card (PIV card) and an associated 6-digit PIN entered on the keypad"], "answer": 3, "explanation": "True MFA requires credentials from at least two different authentication categories: something you know (PIN/password), something you have (smart card/hardware token), or something you are (biometrics). A smart card (something you have) combined with a PIN (something you know) satisfies two distinct factors. Passwords plus PINs or passwords plus security questions represent two items from the same category (something you know). SMS codes and email OTPs are both token-based possession factors and do not provide distinct category separation when used without a knowledge/biometric factor.", "distractor_analysis": {"0": "A password and a PIN are both knowledge factors ('something you know'), making this single-factor authentication with two knowledge inputs.", "2": "Security questions and passwords both belong to the 'something you know' category, failing the multi-category requirement of true MFA.", "3": "SMS and email codes are both possession-based delivery channels and do not constitute distinct multi-category factors on their own."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["authentication", "mfa", "smart-card", "piv"], "id": "C2N-S-002"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "medium", "question": "A junior administrator is assigned to provision accounts in Active Directory. To enforce the principle of least privilege, how should the administrator configure the junior technician's permissions?", "options": ["Add the junior technician's user account directly to the Domain Admins global group", "Provide the junior technician with the built-in local Administrator account password for all domain controllers", "Grant Full Control permissions across the root of Active Directory Domain Services", "Assign the junior technician role-based access control (RBAC) permissions delegated specifically to the target Organizational Unit"], "answer": 1, "explanation": "The principle of least privilege dictates that users receive only the minimum permissions required to perform their specific job functions. Delegating specific administrative tasks (such as user creation and password resets) within a designated Organizational Unit (OU) using Role-Based Access Control (RBAC) limits their scope without granting domain-wide control. Domain Admins membership, root Full Control, and built-in local DC Administrator rights grant unlimited domain supremacy, creating immense security risk.", "distractor_analysis": {"1": "Adding the technician to Domain Admins grants complete control over the entire domain infrastructure, directly violating least privilege.", "2": "Sharing the built-in local Administrator password gives unmonitored, unchecked control over core domain controllers.", "3": "Full Control at the domain root allows modifying schema and enterprise policies, far exceeding account provisioning needs."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["access-control", "rbac", "least-privilege", "active-directory"], "id": "C2N-S-003"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.1", "type": "single", "difficulty": "hard", "question": "A network architect is deploying centralized authentication for datacenter network switches and firewalls. The team requires encryption of the entire authentication and command authorization packet payload, not just the password. Which AAA protocol must be selected?", "options": ["RADIUS over UDP port 1812", "LDAP over TCP port 389", "Kerberos over UDP port 88", "TACACS+ over TCP port 49"], "answer": 1, "explanation": "TACACS+ (Terminal Access Controller Access-Control System Plus) operates over TCP port 49, separates Authentication, Authorization, and Accounting (AAA), and encrypts the entire packet payload (headers remain clear). In contrast, RADIUS (UDP ports 1812/1813) only encrypts the password field within the Access-Request packet, leaving username, attributes, and accounting data unencrypted. LDAP is a directory access protocol, and Kerberos is a ticket-based authentication protocol, neither of which provides granular AAA command authorization for network devices.", "distractor_analysis": {"1": "RADIUS encrypts only the password attribute in transit; the remainder of the packet and authorization data is transmitted in plaintext.", "2": "Standard LDAP transmits directory queries in plaintext on port 389 and does not provide AAA command accounting for switch management.", "3": "Kerberos provides ticket-granting authentication for domain environments but does not separate AAA command-level authorization on network gear."}, "video_reference": {"title": "Physical Security - CompTIA A+ 220-1202 - 2.1", "url": "https://www.youtube.com/watch?v=ZseOfNiOaYM", "duration": "10:06", "objective": "2.1"}, "notes_reference": "28_Physical_Security.md", "tags": ["authentication", "radius", "tacacs", "aaa"], "id": "C2N-S-004"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "A company laptop containing proprietary engineering schematics is stolen from a technician's vehicle. Which Windows security feature prevents the thief from reading the storage drive contents by connecting the drive to another computer?", "options": ["NTFS permissions configured on the parent folder", "Windows Defender SmartScreen filter enabled in the browser", "BitLocker Drive Encryption backed by a Trusted Platform Module (TPM)", "User Account Control (UAC) set to the Always Notify level"], "answer": 2, "explanation": "BitLocker encrypts the entire volume (data, OS, system files) using AES-128 or AES-256 encryption tied to the hardware TPM chip or recovery key. If the drive is removed and connected to a secondary machine, the data remains unreadable ciphertext without the encryption key. NTFS permissions and UAC are enforced only by the running local operating system; attaching the drive to a secondary OS completely bypasses NTFS and UAC. SmartScreen protects against malicious URLs and executables, not physical drive theft.", "distractor_analysis": {"1": "UAC prevents unauthorized administrative software execution within an active Windows session but offers zero protection against offline disk access.", "2": "NTFS access control lists (ACLs) are ignored when a hard drive is attached as a secondary drive to an external operating system.", "3": "SmartScreen warns users about untrusted download files and phishing websites, having no role in volume-level data-at-rest encryption."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["bitlocker", "encryption", "tpm", "windows-security"], "id": "C2N-S-005"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "hard", "question": "To protect against offline and online password brute-force attacks across 500 domain-joined workstations, an administrator must enforce a policy where accounts lock for 30 minutes after five consecutive failed attempts. Where should this policy be configured?", "options": ["In the System Properties Advanced tab under User Profiles settings", "In the Default Domain Policy Group Policy Object (GPO) under Computer Configuration -> Windows Settings -> Security Settings -> Account Policies", "In the Local Group Policy Editor (gpedit.msc) on the administrator's desktop under User Configuration", "In the Windows Defender Firewall with Advanced Security inbound rules on each local client"], "answer": 3, "explanation": "Domain-wide account policies (Password Policy, Account Lockout Policy, and Kerberos Policy) are enforced at the domain level through the Default Domain Policy GPO linked to the root of the domain. In Active Directory, domain user accounts evaluate account lockout settings defined in the Default Domain Policy. Local Group Policy affects only the local machine accounts, not domain accounts across 500 workstations. Windows Firewall controls network traffic, and User Profiles settings manage local profile storage.", "distractor_analysis": {"1": "Editing Local Group Policy on a single desktop modifies only that specific machine's local SAM account database, not Active Directory domain accounts.", "2": "Windows Defender Firewall manages packet filtering by port, protocol, and application, but cannot enforce Active Directory account lockout thresholds.", "3": "The User Profiles dialog manages roaming and temporary profile caching, having no capability to configure domain security policies."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["gpo", "active-directory", "account-lockout", "password-policy"], "id": "C2N-S-006"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "medium", "question": "A systems administrator needs to block all inbound Telnet connections (TCP port 23) across a Windows Server fleet while allowing SSH (TCP port 22) and HTTPS (TCP port 443). Which management tool is used to create this granular port rule?", "options": ["Device Manager (devmgmt.msc)", "Disk Management (diskmgmt.msc)", "Task Scheduler (taskschd.msc)", "Windows Defender Firewall with Advanced Security (wf.msc)"], "answer": 1, "explanation": "Windows Defender Firewall with Advanced Security (launched via wf.msc or the Windows Tools menu) allows administrators to create granular inbound and outbound filtering rules based on specific protocols (TCP/UDP), port numbers, IP addresses, programs, and IPsec security associations. Device Manager configures hardware drivers, Disk Management configures partition layouts, and Task Scheduler automates background batch jobs.", "distractor_analysis": {"1": "Device Manager is used to inspect, update, and troubleshoot hardware device drivers, not network firewall filtering rules.", "2": "Disk Management is responsible for volume formatting, drive partitioning, and VHD management.", "3": "Task Scheduler triggers scheduled scripts and maintenance tasks based on time triggers or system events, not packet inspection."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["windows-firewall", "security-rules", "advanced-security", "port-filtering"], "id": "C2N-S-007"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.2", "type": "single", "difficulty": "hard", "question": "A standard domain user attempts to install an unapproved monitoring utility on a Windows 11 workstation. The screen dims and presents a User Account Control (UAC) credential prompt requesting administrative credentials. What security boundary is UAC enforcing in this scenario?", "options": ["It blocks the network interface card from communicating with the local default gateway", "It forces the user's domain password to expire and triggers an Active Directory lockout", "It prevents unauthorized software installation by requiring administrative token elevation before modifying system files and registry keys", "It automatically quarantines the installer executable in Windows Defender Antivirus storage"], "answer": 2, "explanation": "User Account Control (UAC) ensures that standard users cannot perform system-level changes (such as writing to Program Files or HKLM in the registry) without explicit administrative elevation. When a standard user runs an installer, UAC prompts for an administrator username and password (over-the-shoulder credential prompt). UAC does not quarantine files (which is Defender's job), disable network interfaces, or expire user account passwords.", "distractor_analysis": {"1": "Quarantining malicious software is the function of Windows Defender Antivirus / Microsoft Defender for Endpoint, not the UAC prompt mechanism.", "2": "UAC does not modify network adapter states or sever gateway communication.", "3": "Triggering a UAC prompt is a standard privilege control and does not invalidate domain credentials or lock the user account."}, "video_reference": {"title": "Defender Antivirus - CompTIA A+ 220-1202 - 2.2", "url": "https://www.youtube.com/watch?v=zAArPlmVssU", "duration": "5:01", "objective": "2.2"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["uac", "windows-security", "privilege-escalation", "elevation"], "id": "C2N-S-008"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "hard", "question": "A network engineer is upgrading a corporate campus wireless network from WPA2-Personal to WPA3-Personal. Which key cryptographic improvement in WPA3 replaces the Pre-Shared Key (PSK) 4-way handshake to prevent offline dictionary attacks?", "options": ["Extensible Authentication Protocol-MD5 (EAP-MD5)", "Simultaneous Authentication of Equals (SAE)", "Temporal Key Integrity Protocol (TKIP)", "Wired Equivalent Privacy with RC4 (WEP)"], "answer": 3, "explanation": "WPA3-Personal replaces the vulnerable WPA2 PSK 4-way handshake with Simultaneous Authentication of Equals (SAE), also known as the Dragonfly handshake. SAE uses zero-knowledge proofs and forward secrecy, making offline dictionary attacks impossible even if an attacker captures the initial wireless exchange. TKIP and WEP are obsolete, broken protocols that use weak RC4 encryption. EAP-MD5 is an insecure legacy authentication method susceptible to collision attacks.", "distractor_analysis": {"1": "TKIP was a stopgap protocol for WPA based on RC4; it was deprecated due to fundamental cryptographic vulnerabilities.", "2": "WEP is an obsolete, insecure legacy standard using static 64-bit/128-bit RC4 keys that can be cracked in minutes.", "3": "EAP-MD5 provides only client-to-server password hashes over clear text without server authentication or dynamic key generation."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "wpa3", "sae", "encryption"], "id": "C2N-S-009"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "An organization wants to eliminate shared Wi-Fi passwords and require every employee to authenticate to the corporate SSID using their individual Active Directory domain credentials. Which wireless security configuration must be implemented?", "options": ["WPA2-Personal with a 63-character Pre-Shared Key (PSK)", "Disabling SSID broadcast and enabling MAC address filtering", "Configuring an unencrypted captive portal with a shared guest PIN", "WPA2/WPA3-Enterprise using 802.1X and a backend RADIUS server"], "answer": 1, "explanation": "WPA2/WPA3-Enterprise utilizes IEEE 802.1X port-based network access control combined with an authentication server (such as RADIUS/NPS). Each user connects using their personal directory credentials or digital certificates, generating unique per-session encryption keys and enabling individual revocation. WPA2-Personal relies on a shared passphrase. SSID hiding and MAC filtering provide zero cryptographic protection, and captive portals on open networks leave traffic unencrypted.", "distractor_analysis": {"1": "WPA2-Personal still uses a single Pre-Shared Key shared across all devices, preventing individual credential tracking or selective access revocation.", "2": "Hiding SSIDs and filtering MAC addresses are security-by-obscurity measures easily bypassed with packet sniffers and MAC spoofing.", "3": "Captive portals on open networks authenticate users after connection but transmit all ongoing wireless data payloads completely unencrypted."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "802.1x", "wpa2-enterprise", "radius"], "id": "C2N-S-010"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "hard", "question": "A financial institution requires the highest level of wireless authentication security for executive laptops, requiring mutual authentication where both the client and the authentication server validate each other using digital certificates. Which EAP protocol is required?", "options": ["EAP-FAST", "LEAP", "EAP-TLS", "PEAP-MSCHAPv2"], "answer": 2, "explanation": "EAP-TLS (Transport Layer Security) is the gold standard for enterprise wireless authentication because it mandates mutual authentication: the RADIUS server presents a server certificate to the client, and the client device must present a valid client certificate issued by the organization's Public Key Infrastructure (PKI). PEAP-MSCHAPv2 requires only a server-side certificate while authenticating users via passwords. LEAP is an insecure proprietary Cisco protocol susceptible to dictionary attacks. EAP-FAST relies on Protected Access Credentials (PACs).", "distractor_analysis": {"1": "PEAP-MSCHAPv2 authenticates the server with a certificate, but authenticates the client using username and password rather than a client-side digital certificate.", "2": "EAP-FAST uses PAC files rather than requiring mandatory client-side X.509 digital certificates.", "3": "LEAP is a deprecated, vulnerable protocol that transmits MS-CHAP challenge-responses in a format easily cracked with offline tools."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "eap-tls", "certificates", "pki"], "id": "C2N-S-011"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.3", "type": "single", "difficulty": "medium", "question": "A technician is configuring an access point for WPA2. Which encryption cipher suite must be selected to comply with the standard and provide AES-based confidentiality?", "options": ["MD5-HMAC", "AES-CCMP", "RC4-TKIP", "DES-CBC"], "answer": 3, "explanation": "WPA2 mandates the use of CCMP (Counter Mode Cipher Block Chaining Message Authentication Code Protocol), which is built on the Advanced Encryption Standard (AES) cipher algorithm with 128-bit keys. TKIP is based on RC4 and was only used in original WPA as an interim fix for WEP. DES is an obsolete 56-bit symmetric cipher, and MD5 is a hashing algorithm, not an encryption cipher suite.", "distractor_analysis": {"1": "TKIP uses the deprecated RC4 stream cipher and does not meet WPA2 AES compliance standards.", "2": "DES is an insecure legacy symmetric encryption algorithm with a 56-bit key space that is easily brute-forced.", "3": "MD5-HMAC is an integrity checksum/hashing mechanism, not a symmetric encryption cipher used for payload confidentiality."}, "video_reference": {"title": "Wireless Encryption - CompTIA A+ 220-1202 - 2.3", "url": "https://www.youtube.com/watch?v=oQV7ZLu25KI", "duration": "6:19", "objective": "2.3"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["wireless-security", "aes-ccmp", "encryption-standards", "wpa2"], "id": "C2N-S-012"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A user arrives at work to discover all documents on their local drive have been renamed with a .locked extension. A text file on the desktop demands a Bitcoin payment to obtain the private decryption key. What type of malware has infected the computer?", "options": ["Spyware that quietly reports browsing activity", "Keylogger that records every keystroke typed", "Rootkit that hides itself at kernel level", "Ransomware, also called crypto-malware"], "answer": 1, "explanation": "Ransomware (specifically crypto-malware) encrypts user files using strong asymmetric/symmetric algorithms, appends custom extensions, and demands extortion payments (usually in cryptocurrency) in exchange for the decryption tool. Spyware stealthily monitors user activity without altering file availability. Keyloggers capture keystrokes to harvest passwords. Rootkits conceal malware processes and maintain persistent kernel-level access.", "distractor_analysis": {"1": "Spyware avoids attention so it can keep collecting. The renamed files and ransom note are the opposite.", "2": "A keylogger steals what the user types. It does not encrypt files on disk.", "3": "A rootkit hides other malware. Hiding is not what is happening here; the attacker wants to be seen."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "ransomware", "crypto-malware", "threats"], "id": "C2N-S-013"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "hard", "question": "A compromised system exhibits severe performance degradation, yet standard Task Manager and user-mode antivirus scans report zero abnormal processes or detections. A bootable offline scanner reveals unauthorized modifications to the OS kernel and boot loader. Which malware type is responsible?", "options": ["Macro virus", "Logic bomb", "Rootkit", "Adware"], "answer": 2, "explanation": "Rootkits operate at deep system levels (Ring 0 / kernel space or boot loader / UEFI level) to hook system APIs and intercept calls from monitoring tools like Task Manager and antivirus software, effectively rendering themselves invisible to the active OS. Detecting rootkits typically requires offline scanning tools or hardware-rooted verification (Secure Boot). Adware displays unwanted advertising, macro viruses embed inside Office documents, and logic bombs execute only when specific conditions are triggered.", "distractor_analysis": {"1": "Adware generates pop-ups and banner advertisements in user space and does not subvert kernel-level OS reporting.", "2": "Macro viruses run within script-enabled document environments (like Word or Excel) rather than replacing core OS kernel components.", "3": "Logic bombs lie dormant until a specific trigger event occurs (e.g., date or employee termination) but do not inherently hide kernel API calls."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "rootkit", "kernel", "stealth"], "id": "C2N-S-014"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.4", "type": "single", "difficulty": "medium", "question": "A user downloads a free third-party PDF utility from an untrusted forum. After installation, the PDF tool functions as expected, but the computer secretly begins communicating with an external command-and-control server as part of a botnet. Which classification BEST describes this malware?", "options": ["Polymorphic virus", "Trojan", "Worm", "Ransomware"], "answer": 3, "explanation": "A Trojan (Trojan horse) masquerades as a legitimate, desirable application (such as a utility, media player, or game) while secretly carrying a malicious payload (like a backdoor or botnet agent). Unlike worms, Trojans do not self-replicate across the network; they rely on user deception to execute. Ransomware holds data hostage for payment, and polymorphic viruses alter their code signature to evade static hash detection.", "distractor_analysis": {"1": "Worms self-propagate autonomously across network vulnerabilities without requiring user interaction or disguised legitimate wrappers.", "2": "Ransomware locks or encrypts files and displays extortion demands, rather than stealthily operating as a functional utility.", "3": "A polymorphic virus is defined by its ability to mutate its binary signature upon replication, whereas the question describes disguised delivery."}, "video_reference": {"title": "Malware - CompTIA A+ 220-1202 - 2.4", "url": "https://www.youtube.com/watch?v=lB5VwnsUG3E", "duration": "17:23", "objective": "2.4"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["malware", "trojan", "social-engineering", "payload"], "id": "C2N-S-015"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "The Chief Financial Officer receives an urgent email that appears to come from the Chief Executive Officer, referencing an upcoming confidential acquisition and requesting an immediate wire transfer to an offshore escrow account. Which social engineering attack is taking place?", "options": ["Vishing, a phishing attempt placed by voice", "Shoulder surfing at the executive's desk", "A watering hole attack on a trusted site", "Whaling, spear phishing aimed at an executive"], "answer": 1, "explanation": "Whaling is a highly targeted form of spear phishing directed specifically at high-profile senior executives (such as CEOs, CFOs, or board members) with personalized context, often aiming to authorize fraudulent wire transfers or disclose sensitive corporate data. Vishing takes place over voice telephone calls. Shoulder surfing involves visually observing someone's screen or keyboard. A watering hole attack infects a third-party website frequented by the target organization.", "distractor_analysis": {"1": "Vishing arrives by telephone. This lure came as email.", "2": "Shoulder surfing needs physical proximity to read a screen or keypad.", "3": "A watering hole compromises a site the target visits. No site was involved here."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "spear-phishing", "whaling", "email-security"], "id": "C2N-S-016"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "medium", "question": "An unauthenticated person in delivery attire carrying heavy cardboard boxes approaches a secure building entrance. As an employee badges into the facility, the delivery person asks the employee to hold the door open for them. What social engineering tactic is being used?", "options": ["Smishing", "Brute-force attack", "Tailgating / Piggybacking", "Dumpster diving"], "answer": 2, "explanation": "Tailgating (or piggybacking) is a physical social engineering technique where an unauthorized person follows an authorized individual through a secure door, often exploiting social norms of politeness (such as holding the door for someone carrying packages). Dumpster diving involves rummaging through trash for sensitive documents. Smishing is phishing conducted via SMS text messages. Brute-force attacks use automated password guessing.", "distractor_analysis": {"1": "Dumpster diving searches physical waste receptacles for discarded paperwork, passwords, or hardware asset tags.", "2": "Smishing is social engineering delivered through mobile SMS/MMS text messages containing malicious links.", "3": "Brute-force attacks systematically attempt password combinations using cryptographic software tools."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["social-engineering", "tailgating", "physical-security", "piggybacking"], "id": "C2N-S-017"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "hard", "question": "A threat actor on a local subnet transmits unsolicited ARP reply packets associating the default gateway's IP address with the attacker's own MAC address. This allows the attacker to intercept and modify all outbound traffic from subnet workstations. What attack is occurring?", "options": ["Cross-Site Scripting (XSS)", "On-path attack (Man-in-the-Middle via ARP poisoning)", "Denial of Service (DoS) ping flood", "SQL injection attack"], "answer": 3, "explanation": "ARP poisoning (ARP spoofing) corrupts the ARP cache on local hosts, causing them to send traffic destined for the gateway directly to the attacker's MAC address. This places the attacker in the middle of the communication stream, executing an On-Path (Man-in-the-Middle) attack to eavesdrop or alter data. A ping flood overwhelms bandwidth without routing traffic through the attacker. SQL injection targets backend database queries, and XSS exploits client-side browser script execution.", "distractor_analysis": {"1": "A ping flood (ICMP flood) aims to exhaust device processing capacity or network bandwidth, rather than intercepting and inspecting routed packets.", "2": "SQL injection injects malicious SQL statements into web input fields to manipulate database tables.", "3": "Cross-Site Scripting injects malicious JavaScript into trusted web pages to steal session cookies from other users' web browsers."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["network-attacks", "mitm", "on-path", "arp-poisoning"], "id": "C2N-S-018"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.5", "type": "single", "difficulty": "hard", "question": "Security researchers discover a critical remote code execution flaw in a widely used web server application for which no security patch or update currently exists from the software vendor. How is this vulnerability classified?", "options": ["Zero-day vulnerability", "Brute-force vulnerability", "Default credential flaw", "Legacy protocol deprecation"], "answer": 0, "explanation": "A zero-day vulnerability is a software security flaw that is known to researchers or actively exploited in the wild before the software developer has released an official patch or fix (leaving zero days of protection). Administrators must rely on workarounds, web application firewalls (WAFs), or disabling affected services until a patch is published. Default credentials and legacy protocols are known configuration issues, not unpatched zero-day flaws.", "distractor_analysis": {"1": "Brute-force is an attack method that guesses credentials iteratively; it is not a term describing unpatched zero-day vulnerabilities.", "2": "Default credential flaws stem from failing to change factory passwords (e.g., admin/admin), not zero-day software code flaws.", "3": "Legacy protocol deprecation refers to retiring outdated standards (like SSLv3 or TLS 1.0) due to known architectural weaknesses."}, "video_reference": {"title": "Social Engineering - CompTIA A+ 220-1202 - 2.5", "url": "https://www.youtube.com/watch?v=9xtzpbY1n9I", "duration": "13:37", "objective": "2.5"}, "notes_reference": "26_Threats_Attacks_Social_Engineering.md", "tags": ["vulnerabilities", "zero-day", "patching", "threats"], "id": "C2N-S-019"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "hard", "question": "A technician verifies that a workstation is infected with an active ransomware variant that is attempting to encrypt mapped network shares. Following the CompTIA 7-step malware removal process, what is the technician's IMMEDIATE next step?", "options": ["Quarantine the infected system by disconnecting its network cable and disabling Wi-Fi", "Disable System Restore in the system settings", "Run a full anti-malware scan using updated definitions", "Educate the end user on recognizing malicious email attachments"], "answer": 0, "explanation": "The CompTIA 7-step malware removal process is: 1. Investigate and verify symptoms, 2. Quarantine infected systems, 3. Disable System Restore, 4. Remediate infected systems, 5. Schedule scans and run updates, 6. Enable System Restore and create a restore point, 7. Educate the end user. Once symptoms are verified, Step 2 is immediately quarantining the machine (disconnecting network/Wi-Fi) to prevent malware spread. Disabling System Restore is Step 3, remediation is Step 4, and user education is Step 7.", "distractor_analysis": {"1": "Disabling System Restore is Step 3 of the process and must only occur after the machine is quarantined to stop lateral network transmission.", "2": "Remediating the system with scans is Step 4; running scans on a connected machine allows ransomware to continue encrypting shared files.", "3": "User education is the 7th and final step of the methodology, performed after the system is fully cleansed, protected, and restored."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "methodology", "comptia-7-step", "quarantine"], "id": "C2N-S-020"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "Why does the CompTIA malware removal methodology require disabling Windows System Restore BEFORE initiating anti-malware scans and remediation?", "options": ["To prevent the malware from hiding copies of itself inside previous system restore snapshots and reinfecting the system later", "To free up disk space required by the anti-malware scanning engine", "To speed up the network download rate of updated signature definitions", "To allow standard users to perform administrative scans without a UAC prompt"], "answer": 0, "explanation": "Disabling System Restore purges all existing restore points. If System Restore remains enabled, infected system files and registry hives can be archived into restore snapshots. If the system is later restored to a prior date, the malware will be resurrected, reinfecting the cleansed workstation. Disabling System Restore does not affect signature download speeds, free disk space for engine installation, or bypass UAC controls.", "distractor_analysis": {"1": "While disabling System Restore does clear disk space, the explicit security rationale is eliminating infected snapshot backups.", "2": "System Restore operates locally on disk volume snapshots and has no bearing on network bandwidth or definition update downloads.", "3": "UAC security boundaries are unaffected by the operational state of the Volume Shadow Copy / System Restore service."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "system-restore", "methodology", "remediation"], "id": "C2N-S-021"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "A technician is attempting to remediate an infected workstation, but the malware actively terminates the antivirus process whenever an on-demand scan begins. What remediation environment should the technician use to overcome this active defense?", "options": ["Boot into Windows Safe Mode or use a standalone bootable WinPE / Linux rescue disk", "Launch the anti-malware utility from a secondary standard user account", "Increase the paging file size in Advanced System Settings", "Run the `ipconfig /flushdns` command in Command Prompt"], "answer": 0, "explanation": "When active malware intercepts or terminates security software, booting into Windows Safe Mode prevents third-party autorun drivers and rogue services from loading. Alternatively, booting into an offline pre-installation environment (such as a WinPE or Linux rescue USB drive) mounts the drive without running any host OS binaries, allowing the scanner to detect and delete locked malware files. Secondary standard accounts, paging file adjustments, and DNS flushes do not stop running malware hooks.", "distractor_analysis": {"1": "The malware runs at system/admin level and will continue terminating security processes across all interactive user logon sessions.", "2": "Adjusting virtual memory paging files has zero effect on active process termination or malicious rootkit hooks.", "3": "Flushing DNS resolver cache clears cached name-to-IP mappings but does not disable or terminate resident malware processes."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "safe-mode", "remediation", "clean-boot"], "id": "C2N-S-022"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.6", "type": "single", "difficulty": "medium", "question": "A technician has successfully remediated a severe trojan infection, scheduled daily automated anti-malware scans, and applied all pending operating system updates. What is the NEXT step in the CompTIA malware removal methodology?", "options": ["Enable System Restore and create a clean baseline restore point", "Reformat the drive and reinstall the operating system from scratch", "Close the trouble ticket without contacting the end user", "Disable the Windows Defender Real-time Protection engine"], "answer": 0, "explanation": "Following Step 5 (Schedule scans and run updates), Step 6 of the CompTIA malware removal methodology is to re-enable System Restore and create a new, verified clean restore point. This establishes a clean recovery baseline. Reformatting is unnecessary after successful remediation. Closing the ticket without educating the user violates Step 7 (Educate the end user), and disabling real-time protection leaves the host vulnerable.", "distractor_analysis": {"1": "Reformatting is a last-resort measure when remediation fails; performing it after successful remediation destroys user productivity.", "2": "Step 7 requires engaging and educating the end user on prevention strategies rather than closing tickets silently.", "3": "Disabling real-time protection leaves the cleansed system completely defenseless against immediate reinfection."}, "video_reference": {"title": "Removing Malware - CompTIA A+ 220-1202 - 2.6", "url": "https://www.youtube.com/watch?v=job81SfpQNU", "duration": "11:30", "objective": "2.6"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["malware-removal", "restore-point", "user-education", "methodology"], "id": "C2N-S-023"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "In a healthcare facility, medical staff frequently step away from workstation terminals to assist patients, leaving electronic health records visible on unattended displays. Which security control BEST mitigates this risk?", "options": ["Configuring an automatic screen saver lockout policy after 3 minutes of inactivity via Group Policy", "Requiring users to change their complex passwords every 14 days", "Disabling the local USB storage ports on all medical workstations", "Installing anti-glare privacy filters on desktop monitors"], "answer": 0, "explanation": "Enforcing an automatic screen lock policy after a brief period of inactivity (such as 3 minutes) ensures that unattended workstations secure themselves, requiring valid user re-authentication to resume. This directly prevents unauthorized passersby from viewing or tampering with open records. Frequent password changes do not lock unattended screens, USB port restrictions prevent data exfiltration via flash drives, and privacy filters protect against side-angle viewing but leave the terminal fully accessible to anyone sitting at the desk.", "distractor_analysis": {"1": "High-frequency password rotations cause user fatigue and bad password habits without solving unattended active sessions.", "2": "Disabling USB storage prevents unauthorized data copying but leaves open patient charts exposed to visual inspection.", "3": "Privacy filters prevent shoulder surfing from oblique angles, but do not prevent a person from walking up to the open console."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "screen-lock", "inactivity-timeout", "gpo"], "id": "C2N-S-024"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "medium", "question": "During a routine workstation security audit, a security engineer notices that the built-in Guest account is enabled on several standalone accounting PCs. What security best practice should be applied IMMEDIATELY?", "options": ["Disable the built-in Guest account across all machines", "Assign the Guest account to the local Administrators group", "Set the Guest account password to never expire", "Rename the Guest account to Administrator"], "answer": 0, "explanation": "Security best practices mandate disabling built-in default accounts that are not in use, specifically the Guest account. An enabled Guest account provides unauthenticated or low-privilege access to local system resources and network shares. Elevating the Guest account to Administrators creates a catastrophic security hole, setting its password to never expire prolongs the vulnerability, and renaming it to Administrator introduces confusion and violates renaming guidelines.", "distractor_analysis": {"1": "Adding the Guest account to Administrators gives anonymous or unverified users complete control over the local operating system.", "2": "Allowing passwords to never expire on unsecured built-in accounts exacerbates vulnerabilities.", "3": "Renaming Guest to Administrator creates administrative ambiguity and does not disable the vulnerable anonymous logon pathway."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "account-management", "guest-account", "hardening"], "id": "C2N-S-025"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.7", "type": "single", "difficulty": "hard", "question": "A defense contractor needs to prevent employees from copying confidential project files onto personal USB thumb drives while still allowing authorized USB keyboards and mice. Which technology provides this specific protection?", "options": ["Data Loss Prevention (DLP) / Endpoint USB Removable Media blocking policies", "Disabling the USB Host Controller in system UEFI/BIOS", "Configuring an IPsec tunnel between workstations and domain controllers", "Enabling Network Address Translation (NAT) on the edge router"], "answer": 0, "explanation": "Endpoint Data Loss Prevention (DLP) solutions and Windows Group Policy Removable Storage Access rules allow administrators to specifically block or restrict USB Mass Storage class devices (flash drives, external HDDs) while allowing Human Interface Devices (HID) like USB mice, keyboards, and smart card readers to operate normally. Disabling the USB controller in BIOS cuts power to all USB peripherals. IPsec encrypts network traffic, and NAT translates private IP addresses, neither of which manages USB device classes.", "distractor_analysis": {"1": "Disabling the hardware USB controller in UEFI completely disables all USB ports, preventing the use of necessary USB keyboards and mice.", "2": "IPsec provides network layer encryption and integrity between hosts but has no mechanism to govern local USB hardware classes.", "3": "NAT manages IP address translation at the network boundary and cannot enforce endpoint hardware peripheral policies."}, "video_reference": {"title": "Security Best Practices - CompTIA A+ 220-1202 - 2.7", "url": "https://www.youtube.com/watch?v=6OR_EiHoG8k", "duration": "15:15", "objective": "2.7"}, "notes_reference": "22_Windows_Security_Accounts_Shares_Permissions.md", "tags": ["security-best-practices", "data-loss-prevention", "dlp", "usb-blocking"], "id": "C2N-S-026"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A sales executive leaves their company-enrolled smartphone in a taxi while traveling abroad. The smartphone contains sensitive customer databases and corporate emails. Which Mobile Device Management (MDM) action should the IT help desk execute immediately?", "options": ["Issue a remote wipe command to erase all device data or corporate container data", "Disable the user's Active Directory account and wait for the phone to run out of battery", "Send an SMS message to the phone offering a cash reward to the finder", "Configure a new SSID on the corporate wireless controller"], "answer": 0, "explanation": "When an enrolled mobile device is lost or stolen, Mobile Device Management (MDM) allows administrators to trigger a remote wipe over cellular or Wi-Fi networks. This immediately erases cryptographic keys and sanitizes the flash memory (or corporate container in MAM environments), protecting sensitive data from being extracted. Disabling user accounts prevents new authentications but leaves cached offline data vulnerable on the physical device. SMS messages and SSID changes do not protect device data.", "distractor_analysis": {"1": "Disabling the user account stops future server synchronization but leaves all cached emails and local documents unencrypted and readable on the stolen phone.", "2": "Sending SMS messages relies on the thief's goodwill and does nothing to protect confidential data from forensic extraction.", "3": "Altering corporate SSIDs affects local office Wi-Fi and provides zero security mitigation for a lost device in a foreign taxi."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "mdm", "remote-wipe", "byod"], "id": "C2N-S-027"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "hard", "question": "An employee modifies their corporate Android smartphone's operating system to bypass vendor security restrictions and install unapproved .apk packages from third-party websites. What security term describes this action, and what major risk does it introduce?", "options": ["Rooting / Sideloading; it removes application sandboxing and exposes the device to unverified malicious code", "Tethering; it consumes excessive cellular data bandwidth", "Carrier unlocking; it violates cellular SIM card roaming agreements", "Containerization; it encrypts the personal profile partition"], "answer": 0, "explanation": "Rooting (on Android) or Jailbreaking (on iOS) circumvents OS security boundaries, granting superuser/root privileges to the user and any malicious apps. Sideloading allows installing software packages (.apk) from unverified third-party sources rather than official curated app stores (Google Play, Apple App Store). This bypasses the OS application sandbox, allowing malware to access other apps' data, keystrokes, and system files. Tethering shares internet connections, carrier unlocking changes SIM providers, and containerization is a defensive security control.", "distractor_analysis": {"1": "Tethering shares a phone's cellular internet connection with nearby Wi-Fi or USB devices, having nothing to do with OS privilege escalation.", "2": "Carrier unlocking enables a phone to connect to different cellular network providers and does not compromise the OS kernel sandbox.", "3": "Containerization is an MDM security technique that separates corporate and personal data; it is the opposite of insecure OS rooting."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "sideloading", "jailbreaking", "rooting"], "id": "C2N-S-028"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A financial firm requires field employees to use time-based one-time password (TOTP) codes for cloud portal access. Which mobile security technology generates these rolling 6-digit codes without requiring cellular SMS connectivity?", "options": ["Software authenticator applications (such as Microsoft Authenticator or Google Authenticator)", "Standard SMS cellular text messaging", "Automated interactive voice response (IVR) phone calls", "Unencrypted email delivery to the user's personal inbox"], "answer": 0, "explanation": "Software authenticator applications use an algorithm (RFC 6238 TOTP) combining a shared secret cryptographic seed and the current Unix epoch time to generate synchronized 6-digit codes every 30 seconds. Because calculation happens locally on the smartphone, no cellular reception, SMS service, or internet connection is required at the moment of code generation. SMS and voice calls depend entirely on cellular carrier networks and are vulnerable to SIM-swapping attacks.", "distractor_analysis": {"1": "SMS text messaging relies on cellular carrier transmission and is vulnerable to interception, SS7 exploits, and SIM swap fraud.", "2": "Automated voice calls require active cellular connectivity and are susceptible to eavesdropping and call forwarding rerouting.", "3": "Email-based OTP delivery requires internet access and exposes OTP tokens to email account compromises."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security", "biometrics", "authenticator-app", "totp"], "id": "C2N-S-029"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "hard", "question": "A datacenter administrator is decommissioning 50 obsolete magnetic hard disk drives (HDDs) that previously stored classified government data. Which physical sanitization method uses powerful electromagnetic pulses to permanently disrupt magnetic domains and render the platters unrecoverable?", "options": ["Degaussing", "Performing a Windows Quick Format in Disk Management", "Overwriting the drive with a single pass of zeroes (Zero-fill)", "Executing the `format /q` command in Command Prompt"], "answer": 0, "explanation": "Degaussing subjects magnetic media (such as traditional HDDs and magnetic tapes) to an extremely strong magnetic field (measured in oersteds/gauss), permanently destroying the magnetic domains on the platters and corrupting the factory-written servo tracks, rendering the drive completely inoperable and unrecoverable. Quick format only removes filesystem index tables while leaving all underlying data intact. Single-pass zero-filling does not meet high-security classified destruction standards. (Note: Degaussing does NOT sanitize flash-based SSDs).", "distractor_analysis": {"1": "A Quick Format only rebuilds file allocation structures and root directories, leaving raw file data completely retrievable with forensic carving tools.", "2": "Single-pass zero-fills sanitize logical sectors on functioning drives but do not meet strict classified physical destruction mandates and are ineffective on bad sectors.", "3": "`format /q` is identical to a Quick Format and provides zero cryptographic or magnetic data sanitization."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "degaussing", "magnetic-media", "disposal"], "id": "C2N-S-030"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "medium", "question": "A company contracts a certified e-waste disposal vendor to shred failed solid-state drives (SSDs) containing financial records. Which document MUST the vendor provide to legally prove compliance with data privacy regulations?", "options": ["A formal Certificate of Destruction detailing serial numbers, method, and date", "An invoice receipt listing total scrap metal weight", "A copy of the technician's CompTIA A+ certification card", "A manufacturer warranty replacement RMA slip"], "answer": 0, "explanation": "A Certificate of Destruction is a legally recognized document provided by a certified disposal company that specifies the exact serial numbers of destroyed assets, the precise destruction method used (such as cross-cut shredding or incineration), the date and time of destruction, and the signature of the certified witness. This document is essential for passing regulatory audits (e.g., PCI-DSS, HIPAA, GDPR). Weight receipts, training cards, and RMA slips provide no legal proof of data destruction.", "distractor_analysis": {"1": "An invoice with scrap metal weight proves an exchange of raw material but fails to document individual drive serial numbers or verify data destruction.", "2": "A technician's personal certification does not provide legal chain-of-custody documentation or evidence of asset destruction.", "3": "An RMA slip documents a warranty exchange with a manufacturer and indicates the drive was returned rather than destroyed."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "certificate-of-destruction", "compliance", "asset-disposal"], "id": "C2N-S-031"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.9", "type": "single", "difficulty": "hard", "question": "A technician is preparing an NVMe Solid-State Drive (SSD) for repurposing within the same corporate department. Standard magnetic degaussing is ineffective on flash memory. Which method properly sanitizes the SSD in accordance with NIST 800-88 Clear/Purge guidelines?", "options": ["Executing the drive's built-in cryptographic erase (PSID revert) or ATA/NVMe Secure Erase command", "Running a standard magnetic degausser wand over the NAND flash chips", "Deleting the volume partition in Windows Disk Management", "Performing a standard file deletion and emptying the Recycle Bin"], "answer": 0, "explanation": "NAND flash memory stores data electronically in floating-gate or charge-trap cells, making magnetic degaussing completely ineffective. To sanitize an SSD without physically destroying it, technicians execute the drive controller's built-in NVMe Format / ATA Secure Erase or Cryptographic Erase (Sanitize/PSID revert) command, which flashes voltage to all memory blocks or destroys the hardware encryption key. Deleting partitions or emptying the Recycle Bin merely removes pointers, leaving raw NAND cells intact.", "distractor_analysis": {"1": "Degaussing relies on altering magnetic orientations and has zero effect on the electronic charges stored within solid-state NAND flash cells.", "2": "Deleting partitions removes the partition table header but leaves the underlying data blocks accessible to data recovery software.", "3": "Emptying the Recycle Bin simply marks file index records as available for overwriting without modifying actual data on disk."}, "video_reference": {"title": "Data Destruction - CompTIA A+ 220-1202 - 2.9", "url": "https://www.youtube.com/watch?v=VCQpo2pas1o", "duration": "6:04", "objective": "2.9"}, "notes_reference": "31_Backup_Data_Handling_AI.md", "tags": ["data-destruction", "ssd-sanitization", "nvme", "purge", "nist-800-88"], "id": "C2N-S-032"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "A technician is installing a new SOHO router for a small accounting firm. Which baseline hardening step must the technician perform FIRST before connecting the router to the internet?", "options": ["Change the default administrative username and password and update to the latest firmware", "Enable Remote Management over HTTP on the WAN port for external support", "Enable Wi-Fi Protected Setup (WPS) to simplify printer connections", "Assign public IP addresses directly to all internal client workstations"], "answer": 0, "explanation": "The very first and most critical step when setting up any SOHO router is changing the factory default administrator credentials (such as admin/admin or admin/password), followed immediately by updating the firmware to patch known security vulnerabilities. Leaving default credentials allows automated bots and attackers to take over the device. Remote WAN management and WPS represent critical security vulnerabilities, and assigning public IPs directly exposes internal clients.", "distractor_analysis": {"1": "Enabling remote WAN management over HTTP exposes the router's administrative login interface to unencrypted internet-wide attacks.", "2": "WPS (Wi-Fi Protected Setup) is fundamentally vulnerable to PIN brute-force attacks and should always be disabled in secure environments.", "3": "Public IP assignment bypasses router NAT and firewall protections, exposing internal workstations directly to internet scans."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "router-hardening", "default-credentials", "firmware"], "id": "C2N-S-034"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "A small business owner wants to offer complimentary Wi-Fi to visiting customers while ensuring they cannot access the company's internal point-of-sale (POS) terminals or network printers. How should the technician configure the SOHO router?", "options": ["Enable a dedicated Guest Wi-Fi network with client isolation enabled", "Share the primary WPA3 enterprise passphrase with customers on request", "Disable encryption on the primary SSID and filter customer MAC addresses", "Configure port forwarding on port 80 to the point-of-sale terminal"], "answer": 0, "explanation": "Enabling a dedicated Guest Network (or guest SSID/VLAN) creates an isolated subnet separated from the internal LAN. Enabling client isolation prevents guest devices from communicating with one another or discovering internal business assets such as POS terminals and printers. Sharing the primary passphrase allows full LAN lateral movement, unencrypted Wi-Fi exposes traffic, and port forwarding opens internal devices to incoming external connections.", "distractor_analysis": {"1": "Sharing the primary business SSID allows visiting customers full network visibility and lateral access to sensitive internal POS systems.", "2": "Disabling encryption allows anyone nearby to sniff traffic, and MAC filtering is trivial to spoof without offering subnet isolation.", "3": "Port forwarding redirects incoming internet traffic to internal servers and does not provide Wi-Fi network segmentation."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["soho-security", "guest-network", "iot-isolation", "vlan"], "id": "C2N-S-033"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user attempts to navigate to their corporate webmail portal and receives a severe browser warning: 'Your connection is not private - NET::ERR_CERT_AUTHORITY_INVALID'. What is the MOST likely cause of this warning?", "options": ["The web server's SSL/TLS certificate is self-signed or issued by a Certificate Authority (CA) not trusted in the client's root certificate store", "The client computer's network cable is disconnected from the wall jack", "The web browser's pop-up blocker is preventing the webmail page from loading", "The user entered an incorrect username and password on the login screen"], "answer": 0, "explanation": "The 'ERR_CERT_AUTHORITY_INVALID' error occurs when the browser cannot verify the cryptographic chain of trust because the website's SSL/TLS certificate was issued by an untrusted CA, is self-signed, or the enterprise private CA root certificate has not been installed in the operating system's trusted root certificate store. Physical disconnections prevent page loading entirely (DNS/timeout error), pop-up blockers do not trigger certificate warnings, and authentication errors occur at the application layer after a secure TLS session is established.", "distractor_analysis": {"1": "A disconnected network cable causes an immediate network unreachable or DNS resolution failure, not a cryptographic TLS certificate error.", "2": "Pop-up blockers suppress child browser windows without interfering with HTTPS certificate chain-of-trust verification.", "3": "Authentication errors happen after TLS handshake negotiation and display application login failures, not root CA validation warnings."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser-security", "certificates", "https", "tls-warning"], "id": "C2N-S-035"}, {"exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user reports that search queries in their web browser constantly redirect to untrusted shopping websites, and intrusive advertising banners appear on every page. Inspection reveals three unknown browser add-ons installed. What actions should the technician take to resolve the issue?", "options": ["Remove the unauthorized browser extensions, clear browser cache and cookies, and reset the default search engine", "Reinstall the operating system using a clean ISO image", "Disable the Windows Defender Firewall private profile", "Change the display resolution in Windows Display Settings"], "answer": 0, "explanation": "Malicious or unwanted browser extensions (adware/hijackers) frequently modify the default search provider, inject scripts into web sessions, and redirect search traffic. The proper remediation is removing all rogue extensions, clearing cached files and tracking cookies, resetting the default homepage and search engine, and running an anti-malware scan. Full OS reinstallation is excessive for simple extension hijacking, disabling the firewall weakens security, and display resolution is irrelevant.", "distractor_analysis": {"1": "Reinstalling the entire operating system is a drastic last resort when simple browser extension removal and resetting resolves the issue.", "2": "Disabling the Windows Defender Firewall removes critical network filtering without addressing malicious browser add-ons.", "3": "Changing screen resolution adjusts monitor display scaling and has zero relationship with browser redirection or extension management."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["browser-security", "extensions", "privacy", "cookies", "cache"], "id": "C2N-S-036"}, {"id": "C2N-S2-001", "exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user wants to install a browser extension that promises free coupons. It requests permission to read and change all data on every website. What should the technician advise?", "options": ["Decline it, because that permission lets the extension read passwords and banking pages, and obtain extensions only from the official store with minimal permissions", "Install it because extensions are always safe", "Install it but only use it for shopping sites", "Install it and disable the antivirus to avoid conflicts"], "answer": 0, "explanation": "Browser extensions run inside the browser with whatever permissions they are granted. An extension allowed to read and change data on all sites can capture credentials, inject advertisements and redirect traffic, and coupon and download-helper extensions are a common vehicle for this. Extensions should come from the official store, be from a trusted publisher, request only the permissions they need and be reviewed periodically. Turning off security software compounds the risk.", "distractor_analysis": {"1": "Extensions are software and can be malicious.", "2": "The permission applies to every site regardless of how it is used.", "3": "Disabling antivirus removes a layer of protection for no reason."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "browser", "extensions", "permissions"]}, {"id": "C2N-S2-002", "exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user is about to enter card details on a shopping website. Which browser indicator confirms the connection to the site is encrypted?", "options": ["A padlock icon and an address beginning with https, with a valid certificate for the site's domain", "A colourful logo on the page", "The presence of a shopping cart", "A message on the page saying it is secure"], "answer": 0, "explanation": "The padlock and the https prefix mean the browser has verified the site's certificate and is encrypting the session, so card details cannot be read in transit. Clicking the padlock shows the certificate and the organisation it was issued to, which should match the shop. Anything the page itself displays, including logos and text claiming security, is under the site owner's control and proves nothing. The user should also confirm the domain is the genuine retailer, not a look-alike.", "distractor_analysis": {"1": "Logos are just images on the page.", "2": "A cart is a feature, not a security indicator.", "3": "Text on the page can say anything."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "browser", "https", "certificate"]}, {"id": "C2N-S2-003", "exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A shared kiosk PC in a library must not retain any browsing history, cookies or saved passwords between users. Which browser feature or setting supports this?", "options": ["Private or incognito browsing, or a policy that clears browsing data on exit and disables password saving", "Enabling the bookmarks bar", "Setting a colourful theme", "Increasing the default zoom"], "answer": 0, "explanation": "Private browsing discards history, cookies and site data when the window closes, and browsers can be configured by policy to clear data on exit, block password saving and disable autofill. Together these stop one library user finding the previous user's accounts still signed in. Kiosk software often enforces this automatically. Appearance and layout settings have no effect on what the browser stores.", "distractor_analysis": {"1": "Bookmarks bar visibility does not affect stored data.", "2": "Themes are cosmetic.", "3": "Zoom changes display size only."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "browser", "private-browsing", "kiosk"]}, {"id": "C2N-S2-004", "exam": "core2", "domain": "2.0 Security", "objective": "2.11", "type": "single", "difficulty": "medium", "question": "A user complains that a website they visit daily keeps showing a pop-up that they cannot close, and the browser warns that the site is trying to open new windows. Which browser feature is protecting the user and what else should be done?", "options": ["The pop-up blocker; the user should keep it enabled and the site should be checked for compromise or reported rather than allowed", "The download manager; the user should download the pop-up", "The bookmark manager; the user should bookmark the pop-up", "The print dialog; the user should print the page"], "answer": 0, "explanation": "Browsers block scripted pop-up windows by default because they are used for advertising, scams and drive-by downloads. A legitimate site that suddenly generates aggressive pop-ups may itself be compromised or serving malicious advertisements. The user should not add it to the allow list, should close the tab using the tab control or Task Manager if necessary, and the technician can scan the PC and report the site. Downloading, bookmarking or printing a pop-up is nonsensical.", "distractor_analysis": {"1": "Downloading content from a suspicious pop-up is how malware arrives.", "2": "Bookmarking a pop-up serves no purpose.", "3": "Printing does not address the security issue."}, "video_reference": {"title": "Browser Security - CompTIA A+ 220-1202 - 2.11", "url": "https://www.youtube.com/watch?v=aIcO1ZMj92U", "duration": "18:56", "objective": "2.11"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "browser", "pop-up-blocker"]}, {"id": "C2N-S2-005", "exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A company allows staff to use personal phones for email. Which control ensures a lost phone does not expose company mail even if the finder guesses the phone is unlocked?", "options": ["Requiring a screen lock with a short timeout and device encryption, enforced by MDM, with the ability to wipe the corporate data remotely", "Asking staff to be careful", "Printing the emails instead", "Using a shorter email signature"], "answer": 0, "explanation": "Mobile security for business data rests on a few enforced controls: a screen lock with a short auto-lock so the phone is rarely found unlocked, full device encryption so the storage cannot be read directly, and a management platform that can remove the corporate container or the whole device remotely. Policies that depend on user diligence alone fail, and the other options do not address the risk at all.", "distractor_analysis": {"1": "Good intentions are not a security control.", "2": "Paper is harder to protect and does not remove the phone risk.", "3": "Signatures are irrelevant to data protection."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["security", "mobile", "screen-lock", "encryption", "mdm"]}, {"id": "C2N-S2-006", "exam": "core2", "domain": "2.0 Security", "objective": "2.8", "type": "single", "difficulty": "medium", "question": "A phone's settings offer a feature that erases the device after ten failed unlock attempts. What is the trade-off a technician should explain before enabling it?", "options": ["It defeats brute-force guessing of the passcode but risks accidental erasure, so a current backup is essential", "It makes the phone charge faster", "It disables the camera", "It has no downside of any kind"], "answer": 0, "explanation": "The failed-attempts wipe stops an attacker cycling through passcodes, and combined with encryption it renders a stolen phone worthless. The cost is that a child pressing buttons or a phone bouncing in a bag can trigger it. With a verified cloud or computer backup, the erased device is restored in an hour and the protection is well worth it; without a backup the setting is dangerous. It has nothing to do with charging or the camera.", "distractor_analysis": {"1": "The setting is unrelated to charging.", "2": "The camera is unaffected.", "3": "Accidental erasure is a real downside."}, "video_reference": {"title": "Mobile Device Security - CompTIA A+ 220-1202 - 2.8", "url": "https://www.youtube.com/watch?v=WNWFV4r_6Wk", "duration": "10:28", "objective": "2.8"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["security", "mobile", "failed-attempts", "wipe", "backup"]}, {"id": "C2N-S2-007", "exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "A small business has just installed a new wireless router. Which first step most improves its security?", "options": ["Change the default administrator password and update the router firmware", "Place the router near a window", "Leave the default password so staff can remember it", "Turn off the router's LEDs"], "answer": 0, "explanation": "Default credentials for every router model are published online, so any device left with them can be taken over from the LAN or, if remote management is on, from the internet. Setting a strong unique administrator password and applying the latest firmware, which fixes known vulnerabilities, are the first two actions on any new router. After that, WPA3 or WPA2 with a strong passphrase, a separate guest network and disabling remote administration complete the basic hardening.", "distractor_analysis": {"1": "Window placement affects coverage, not security.", "2": "Default passwords are the single most common router compromise.", "3": "LEDs have no security relevance."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["security", "soho", "router", "default-password", "firmware"]}, {"id": "C2N-S2-008", "exam": "core2", "domain": "2.0 Security", "objective": "2.10", "type": "single", "difficulty": "medium", "question": "A cafe wants customers to have Wi-Fi without any access to the till system and office PCs on the same router. Which router feature achieves this?", "options": ["A guest network that is isolated from the main LAN", "Increasing the Wi-Fi transmit power", "Changing the network name to something friendly", "Disabling encryption for the customers"], "answer": 0, "explanation": "Most small-business routers offer a guest network: a separate wireless name with its own passphrase whose clients are placed on an isolated segment that can reach the internet but not the devices on the main network. It is the simplest way to share connectivity with visitors while protecting point-of-sale and office systems. Power, naming and removing encryption do nothing to separate customer traffic from the business network.", "distractor_analysis": {"1": "More power extends reach for everyone, including attackers.", "2": "A friendly name is cosmetic.", "3": "Open networks expose customers to eavesdropping and do not isolate them."}, "video_reference": {"title": "Securing a SOHO Network - CompTIA A+ 220-1202 - 2.10", "url": "https://www.youtube.com/watch?v=pq_CKhYYYVQ", "duration": "15:03", "objective": "2.10"}, "notes_reference": "27_Wireless_Security_SOHO_Router_Hardening.md", "tags": ["security", "soho", "guest-network", "isolation"]}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A workstation encounters repeated Blue Screen of Death (BSOD) stop errors shortly after a graphics driver update. Which tool or log should the technician examine first to identify the exact failing driver binary?", "options": ["Read the minidump with WinDbg or BlueScreenView to name the faulting driver", "Run Disk Cleanup to clear the temporary setup files left by the update", "Open Device Manager and disable the network adapter to isolate the fault", "Rebuild the boot configuration data with bootrec /rebuildbcd"], "answer": 0, "explanation": "When Windows encounters a kernel panic (BSOD/bugcheck), it creates a crash dump file in the minidump folder or %SystemRoot%\\MEMORY.DMP. Analyzing this dump with debugging tools such as WinDbg or BlueScreenView pinpoints the precise driver file (e.g., nvlddmkm.sys) and memory address that caused the crash. Disk Cleanup removes temporary files but does not diagnose kernel panics, disabling network cards does not diagnose graphics driver faults, and BCD rebuilds are for boot-loader discovery issues.", "distractor_analysis": {"1": "Freeing disk space does not identify which driver module faulted.", "2": "The crash followed a graphics update, so disabling the network adapter tests the wrong device.", "3": "The machine boots far enough to bugcheck, so the boot configuration is intact."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "bsod", "driver", "minidump"], "id": "C2N-W-001"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows 11 machine displays corrupt icon resources and crashes when opening system dialogs. The technician runs `sfc /scannow`, but it reports: 'Windows Resource Protection found corrupt files but was unable to fix some of them.' Which command should the technician execute next?", "options": ["DISM /Online /Cleanup-Image /RestoreHealth", "chkdsk /f /r on the system volume", "sfc /scannow again from Safe Mode", "bootrec /rebuildbcd from recovery"], "answer": 0, "explanation": "When the System File Checker (`sfc /scannow`) cannot repair corrupt system binaries because its local component store cache (WinSxS) is also corrupted, running the Deployment Image Servicing and Management tool (`DISM /Online /Cleanup-Image /RestoreHealth`) repairs the Windows component store by downloading pristine replacement files from Windows Update. `chkdsk` repairs NTFS filesystem metadata and disk sectors, `gpupdate` refreshes Group Policy, and `ipconfig` manages DHCP leases.", "distractor_analysis": {"1": "chkdsk repairs file system structures and bad sectors, not the protected file payload.", "2": "Rerunning SFC fails the same way because its source, the component store, is the damaged part.", "3": "bootrec repairs boot records. The machine boots fine; the component store does not."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "sfc", "dism", "system-integrity"], "id": "C2N-W-002"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Upon powering on a desktop, the screen displays: 'BOOTMGR is missing. Press Ctrl+Alt+Del to restart.' What is the MOST effective method to repair the boot sequence?", "options": ["Boot into WinRE and run Startup Repair, or bootrec /fixboot and /rebuildbcd", "Flash the motherboard UEFI to the current firmware revision", "Replace the power supply, since BOOTMGR loads before POST", "Run Disk Defragmenter in Safe Mode to relocate the boot files"], "answer": 0, "explanation": "The 'BOOTMGR is missing' error indicates that the BIOS/UEFI cannot find the Windows Boot Manager file or the Boot Configuration Data (BCD) pointer is corrupted. Booting into WinRE and executing automated Startup Repair or using the Command Prompt with `bootrec /fixmbr`, `bootrec /fixboot`, and `bootrec /rebuildbcd` repairs the master boot record and rebuilds the BCD store. Motherboard flashing, PSU replacement, and disk defragmentation do not repair boot sector files.", "distractor_analysis": {"1": "A firmware update does not recreate a missing boot manager entry and risks bricking a working board.", "2": "The message appears after POST completes, so the supply is delivering power correctly.", "3": "Safe Mode needs a bootable system, which is exactly what is missing, and defrag does not repair the BCD."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "bootmgr", "bcd", "startup-repair"], "id": "C2N-W-003"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Immediately following an automatic driver update for a network interface card (NIC), a workstation loses all network connectivity. What is the fastest and least disruptive method to restore connectivity?", "options": ["Open Device Manager, view the NIC properties, and select 'Roll Back Driver'", "Format the C: drive and reinstall Windows from scratch", "Replace the motherboard network interface hardware", "Delete the `System32` directory from Command Prompt"], "answer": 0, "explanation": "Device Manager includes a dedicated 'Roll Back Driver' button on the Driver tab of any hardware device's properties dialog. This feature immediately restores the previously working driver package and registry settings without requiring a full system restore or OS reinstall. Reinstalling Windows is unnecessarily disruptive, hardware replacement is premature, and deleting system directories causes complete system destruction.", "distractor_analysis": {"1": "Reinstalling the entire operating system causes severe downtime and data loss when a simple 10-second driver rollback solves the issue.", "2": "Replacing hardware is unwarranted when the fault was directly triggered by a software driver installation.", "3": "Deleting `System32` destroys core operating system executables and permanently bricks the Windows installation."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "driver-rollback", "device-manager", "video"], "id": "C2N-W-004"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A user logs into Windows and receives the message: 'You have been logged on with a temporary profile.' Any files saved to the desktop disappear after rebooting. How should the technician permanently fix this corrupted profile?", "options": ["Back up the user data, rename the corrupt ProfileList key, and let Windows rebuild the profile", "Increase the paging file on C: so the profile hive can load", "Run netstat -ano to find the socket holding the profile open", "Turn off User Account Control and sign the user back in"], "answer": 0, "explanation": "When Windows cannot load a user's `NTUSER.DAT` registry hive, it loads a temporary profile and renames the user's ProfileList SID key in `HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\ProfileList` with a `.bak` extension. To resolve it permanently, the technician backs up data from the old user directory, removes the corrupted `.bak` registry reference, and allows Windows to regenerate a clean profile upon the next logon. Paging files, netstat, and UAC have no impact on profile registry locks.", "distractor_analysis": {"1": "The paging file has nothing to do with loading NTUSER.DAT. The hive is corrupt or locked, not short of memory.", "2": "netstat lists network sockets. A profile hive is a local file, not a network connection.", "3": "Disabling UAC lowers protection and leaves the corrupt ProfileList entry exactly where it was."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "profile-corruption", "registry", "user-profile"], "id": "C2N-W-005"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user complains that their Windows 11 laptop takes over five minutes to reach a usable desktop after entering their password. Which tool should the technician use to identify and disable high-impact startup applications?", "options": ["Task Manager under the Startup apps tab", "Windows Memory Diagnostic", "Disk Management", "Disk Cleanup"], "answer": 0, "explanation": "The 'Startup apps' tab in Windows Task Manager (or Settings -> Apps -> Startup) displays all applications configured to launch during user login, along with their measured 'Startup impact' (High, Medium, Low, or None). Disabling non-essential high-impact startup applications directly reduces boot and login times. Windows Memory Diagnostic tests physical RAM cells, Disk Management manages partitions, and Disk Cleanup removes temporary files.", "distractor_analysis": {"1": "Windows Memory Diagnostic executes offline memory pattern tests to detect faulty physical RAM chips, not slow application startups.", "2": "Disk Management is used for partitioning, drive letter assignment, and volume resizing, having no visibility into startup apps.", "3": "Disk Cleanup deletes cache and log files but does not manage the list of applications configured to execute upon user login."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "slow-boot", "task-manager", "startup-apps"], "id": "C2N-W-006"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A critical line-of-business accounting database service fails to start automatically upon Windows boot, preventing users from connecting. In `services.msc`, the service startup type is set to 'Automatic'. What configuration change ensures the service starts even if dependent network services take longer to initialize?", "options": ["Set the startup type to Automatic (Delayed Start) and configure Recovery restart actions", "Set the startup type to Disabled and start it by hand each morning", "Change the service logon account to the local Guest account", "Delete and reregister the service with sc.exe from an elevated prompt"], "answer": 0, "explanation": "Setting the startup type to 'Automatic (Delayed Start)' instructs the Windows Service Control Manager to launch the service shortly after the main boot cycle completes, giving prerequisite network and database infrastructure time to fully initialize. Additionally, configuring the 'Recovery' tab enables Windows to automatically restart the service upon first and second failures. Setting it to Disabled stops it permanently, Guest accounts lack necessary service permissions, and deleting the binary destroys the service.", "distractor_analysis": {"1": "Disabling the service guarantees the outage rather than fixing the start order.", "2": "Guest has no rights to the database files, so the service fails immediately on start.", "3": "Reregistering rebuilds the entry but keeps the same race against its dependencies at boot."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "services", "services-msc", "service-startup"], "id": "C2N-W-007"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A custom financial reporting tool crashes on startup with the error: 'Component custom_math.dll failed to load or is not registered.' The DLL file exists in the application directory. Which command-line utility registers the DLL with the Windows subsystem?", "options": ["`regsvr32 custom_math.dll`", "`sfc /scannow custom_math.dll`", "`bcdedit /set custom_math.dll`", "`chkdsk /f custom_math.dll`"], "answer": 0, "explanation": "The Microsoft Register Server tool (`regsvr32.exe`) is used to register and unregister COM DLLs and ActiveX controls in the Windows Registry (under HKEY_CLASSES_ROOT). Running `regsvr32 custom_math.dll` from an elevated prompt writes the required class IDs and interfaces. `sfc` scans protected Windows system files, `bcdedit` edits the boot database, and `chkdsk` verifies disk sectors.", "distractor_analysis": {"1": "`sfc /scannow` checks only core protected Microsoft Windows binaries against system manifest hashes; it does not register third-party COM DLLs.", "2": "`bcdedit` manages Windows Boot Configuration Data store parameters and has no functionality related to DLL registration.", "3": "`chkdsk` accepts drive letters (e.g., C:) to check disk volume structures, not individual DLL registration parameters."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "dll-missing", "regsvr32", "application-crash"], "id": "C2N-W-008"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A technician needs to isolate whether an application crash is caused by third-party startup software and background services versus the core operating system. Which utility is used to perform a 'clean boot' by selectively disabling non-Microsoft startup services?", "options": ["System Configuration (`msconfig`)", "Registry Editor (`regedit`)", "Disk Defragmenter (`dfrgui`)", "Driver Verifier (`verifier`)"], "answer": 0, "explanation": "System Configuration (`msconfig`) allows technicians to perform a clean boot by going to the 'Services' tab, checking 'Hide all Microsoft services', and clicking 'Disable all', combined with disabling startup items in Task Manager. This starts Windows with only core Microsoft services, isolating third-party software conflicts. Registry Editor edits raw hive keys, Disk Defragmenter reorganizes clusters, and Driver Verifier stresses kernel drivers.", "distractor_analysis": {"1": "Registry Editor modifies low-level configuration hives directly but lacks the automated clean-boot toggle workflow provided by `msconfig`.", "2": "Disk Defragmenter optimizes hard drive storage layout and has no capability to manage service startup states.", "3": "Driver Verifier is a developer tool that subjects kernel-mode drivers to extreme stress tests to catch memory leaks, rather than performing clean boots."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "safe-mode", "msconfig", "clean-boot"], "id": "C2N-W-009"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A business-critical accounting program hangs randomly once per day without displaying an error dialog. Where in Event Viewer should the technician look to find the crash logs and faulting module details?", "options": ["Windows Logs -> Application (filtering for Event ID 1000 Error or Event ID 1002 Hang)", "Windows Logs -> Security (filtering for Event ID 4624)", "Applications and Services Logs -> Microsoft -> Windows -> Windows Defender -> Operational", "Windows Logs -> Setup"], "answer": 0, "explanation": "In Windows Event Viewer, the `Application` log records application-level failures. Event ID 1000 indicates an Application Error (listing the faulting application name, version, faulting module, and exception code), and Event ID 1002 indicates an Application Hang. The Security log records audit events like successful logons (4624), the Defender log tracks antivirus malware detections, and the Setup log records OS upgrade and patch milestones.", "distractor_analysis": {"1": "The Security log tracks user authentication, privilege use, and object access (e.g., Event ID 4624 for successful logon), not software crashes.", "2": "The Windows Defender Operational log records malware scans, threat remediations, and signature updates.", "3": "The Setup log records operating system installation events, servicing stack updates, and feature updates."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "event-viewer", "system-log", "application-hang"], "id": "C2N-W-010"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user logs into Windows and the display turns completely black, showing only a working mouse cursor. Which key combination can the technician press to immediately restart the graphics driver subsystem in Windows 10/11?", "options": ["Win + Ctrl + Shift + B", "Ctrl + Alt + Del followed by Escape", "Alt + F4", "Win + Pause/Break"], "answer": 0, "explanation": "In Windows 10 and 11, pressing `Win + Ctrl + Shift + B` triggers an instant beep and flashes the screen, signaling the OS to discard the graphics surface buffer and restart the video graphics display driver. This often resolves black screen issues caused by a hung graphics driver without rebooting the system. `Ctrl + Alt + Del` opens the security screen, `Alt + F4` closes the active window, and `Win + Pause/Break` opens the System About dialog.", "distractor_analysis": {"1": "`Ctrl + Alt + Del` interrupts processing to display the Windows Security screen (Lock, Switch User, Task Manager), but does not restart the display driver subsystem.", "2": "`Alt + F4` sends a close command to the active foreground application window.", "3": "`Win + Pause/Break` opens the Windows Settings About page showing system processor and RAM specifications."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "black-screen", "graphics-driver", "keyboard-shortcut"], "id": "C2N-W-011"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A workstation frequently freezes and reports read errors when opening large spreadsheet files on the D: drive. Which command should the technician run to scan the volume for file system metadata errors and recover readable data from bad sectors?", "options": ["`chkdsk D: /f /r`", "`sfc /scanfile=D:\\`", "`format D: /fs:NTFS`", "`robocopy D:\\ C:\\ /mir`"], "answer": 0, "explanation": "The Check Disk command (`chkdsk D: /f /r`) scans the specified volume (D:). The `/f` switch fixes file system directory errors on disk, while the `/r` switch locates bad physical sectors and recovers readable information (which also implies `/f`). `sfc` only scans Windows OS system files on the boot drive, `format` wipes all data on the volume, and `robocopy /mir` mirrors directories without diagnosing disk health.", "distractor_analysis": {"1": "`sfc` is designed specifically to verify operating system core binaries and does not check general secondary data volumes for NTFS sector corruption.", "2": "Formatting the drive destroys all existing data on the volume without attempting to repair or recover current files.", "3": "`robocopy` is a file replication tool that will fail or hang when encountering the unreadable bad sectors."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "chkdsk", "ntfs", "bad-sectors"], "id": "C2N-W-012"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "Following the installation of an incompatible system utility, Windows fails to reach the login screen and continuously loops into the Automatic Repair screen. How can the technician revert Windows to its state prior to the utility installation without losing the user's personal documents?", "options": ["Open Advanced Options in WinRE and run System Restore to a point before the install", "Choose Reset this PC with the Remove everything option", "Run format C: from the WinRE command prompt and reinstall", "Boot into UEFI setup and disable the TPM 2.0 device"], "answer": 0, "explanation": "Windows System Restore (accessible from WinRE under Troubleshoot -> Advanced Options -> System Restore, or `rstrui.exe`) reverts system files, registry keys, and installed drivers to a previously created snapshot (restore point) without altering, deleting, or overwriting user personal files (such as documents, photos, or emails). 'Reset this PC - Remove everything' and `format C:` destroy all data, and disabling TPM prevents secure booting entirely.", "distractor_analysis": {"1": "That wipes user data to solve a problem a restore point already covers.", "2": "Formatting is the most destructive option available and is not needed here.", "3": "Disabling the TPM breaks BitLocker unlock and does nothing about the bad utility."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "system-restore", "rstrui", "winre"], "id": "C2N-W-013"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A desktop computer experiences random application crashes and intermittent Blue Screen errors with stop codes `MEMORY_MANAGEMENT` and `PAGE_FAULT_IN_NONPAGED_AREA`. Which built-in Windows utility should be scheduled to test the physical RAM modules?", "options": ["Windows Memory Diagnostic (`mdsched.exe`)", "Resource Monitor (`resmon.exe`)", "Performance Monitor (`perfmon.exe`)", "System Information (`msinfo32.exe`)"], "answer": 0, "explanation": "Windows Memory Diagnostic (`mdsched.exe`) prompts the user to restart the computer immediately or on the next boot, loading a specialized pre-boot diagnostic environment that writes test patterns to RAM cells to detect hardware memory defects. Resource Monitor and Performance Monitor track live runtime resource metrics, and System Information (`msinfo32`) reports hardware and software inventory without testing physical silicon integrity.", "distractor_analysis": {"1": "Resource Monitor provides real-time graphs and PID breakdown of memory usage but cannot test physical RAM silicon for defective memory cells.", "2": "Performance Monitor logs historical performance counters and OS telemetry over time rather than executing low-level hardware memory tests.", "3": "System Information (`msinfo32`) displays hardware summaries, BIOS versions, and environment variables without performing diagnostics."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows-troubleshooting", "memory-diagnostic", "ram", "hardware-fault"], "id": "C2N-W-014"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "hard", "question": "A user brings a corporate smartphone to the help desk, noting that the screen is bulging outwards and separating from the aluminum chassis. The phone feels warm even when powered off. What is the MANDATORY safety action the technician must take?", "options": ["Immediately power down the device, do not charge it, and place it in an airtight fireproof / sand-filled battery safety container", "Press firmly on the glass display to snap the bezel back into the chassis", "Connect the smartphone to a fast charger to test the power management IC", "Pierce the battery pouch with a fine probe to release the trapped gas"], "answer": 0, "explanation": "A bulging screen or separated chassis indicates a swollen lithium-ion battery caused by internal shorting, thermal runaway, or gas accumulation. Swollen batteries pose a severe fire and explosion risk. The mandatory safety protocol is to immediately disconnect all power, turn off the device, handle it with care, and store it in a dedicated fireproof battery container or sand bucket away from flammable materials until safe disposal. Never puncture, charge, or apply pressure to a swollen battery.", "distractor_analysis": {"1": "Applying physical pressure to a swollen lithium-ion battery can puncture the separator membrane, triggering an explosive chemical fire.", "2": "Charging a compromised lithium battery introduces additional current and heat, likely causing catastrophic thermal runaway.", "3": "Puncturing a lithium battery pouch causes immediate air exposure, resulting in violent chemical combustion and toxic gas release."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "swollen-battery", "safety", "hardware"], "id": "C2N-W-015"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A smartphone battery depletes from 100% to 15% in less than three hours while sitting idle in a pocket. Which diagnostic step should the technician perform first on the device?", "options": ["Open Settings, Battery, and look for rogue background apps and battery health", "Replace the mainboard, since the charging circuit has failed", "Factory reset the device before taking any backup of the data", "Turn on the hotspot and full brightness to reproduce the drain"], "answer": 0, "explanation": "The built-in Battery utility in iOS and Android provides detailed telemetry showing which specific applications consume battery power in the background, along with overall Battery Health (maximum capacity percentage). A rogue app stuck in a background synchronization or location loop is the most common cause of sudden drain. Motherboard replacement and factory resets are extreme, and enabling hotspots and maximum brightness increases battery drain further.", "distractor_analysis": {"1": "The device holds charge and then loses it, which points at consumption rather than a charging fault.", "2": "Resetting without a backup destroys user data before you have diagnosed anything.", "3": "Deliberately adding load confirms nothing and empties the battery you were meant to test."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "battery-drain", "background-apps", "power"], "id": "C2N-W-016"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user's tablet screen is fully illuminated and displaying the home screen, but the touchscreen does not respond to any touch, tap, or swipe gestures. What is the FIRST troubleshooting step the technician should perform?", "options": ["Force a hardware restart with the physical button combination", "Replace the digitizer and LCD assembly on the bench", "Reseat the display ribbon cable inside the chassis", "Roll the cellular modem firmware back a revision"], "answer": 0, "explanation": "An unresponsive touchscreen on a functioning display is frequently caused by a frozen OS input handler or temporary software glitch. Performing a forced hard restart (using the device-specific physical button combination, e.g., Volume Up + Power) forces the OS and hardware digitizer controller to reinitialize. If the issue persists after rebooting and removing screen protectors, hardware digitizer replacement may be considered. Submerging devices or modifying modem firmware is destructive or irrelevant.", "distractor_analysis": {"1": "Parts replacement is the last step, not the first, and the panel is clearly still driving an image.", "2": "Opening the chassis before a soft reset is disproportionate and voids the warranty.", "3": "Modem firmware has no connection to touch input."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "touchscreen", "unresponsive-screen", "reboot"], "id": "C2N-W-017"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A mobile device shuts down unexpectedly during video recording outdoors on a sunny day and displays a high-temperature warning icon upon attempting to power on. What is causing this behavior?", "options": ["Thermal protection safeguards shutting down the device to prevent permanent semiconductor and battery damage", "The cellular carrier network disconnecting the SIM card", "A corrupted display driver inside the operating system", "A malicious ransomware encryption process completing"], "answer": 0, "explanation": "Mobile devices contain internal thermistors that monitor battery, CPU, and ambient temperatures. When operating in direct sunlight or under heavy compute loads (such as 4K video recording), the device triggers thermal throttling and eventually an automated thermal shutdown to protect the lithium-ion battery from fire and prevent silicon degradation. Moving the device to a cool, shaded environment allows it to recover once cooled. Carrier disconnects, display drivers, and ransomware do not cause physical temperature shutdowns.", "distractor_analysis": {"1": "Cellular SIM disconnects result in 'No Service' status indicators, not hardware thermal protection shutdowns.", "2": "Display driver crashes cause screen flickers or OS reboots, not high-temperature thermal warning screens.", "3": "Ransomware targets files for encryption; temperature cutoffs are hardware-driven thermal sensor protections."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "overheating", "thermal-throttling", "performance"], "id": "C2N-W-018"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "A smartphone user reports that mobile apps crash immediately upon launching, camera photos fail to save, and system updates cannot download. Storage settings reveal 0 MB of available internal storage. What should the technician advise the user to do first?", "options": ["Offload unused apps, clear cached media and temporary files, and move photos to cloud storage", "Replace the internal flash module, since the storage chip has worn out", "Reset the APN so the carrier can push a storage expansion profile", "Turn off the lock screen PIN to release the encrypted scratch space"], "answer": 0, "explanation": "When internal flash storage is completely exhausted (0 MB free), mobile operating systems cannot create temporary scratch files, write application state caches, or download update packages, leading to immediate app crashes and save errors. Freeing storage space by deleting unused large apps, clearing app caches, and offloading photos/videos to cloud storage immediately restores stability. Memory chips are soldered and cannot be replaced individually, APN settings manage cellular data, and PIN settings are unrelated.", "distractor_analysis": {"1": "Internal flash is not a serviceable part on a phone, and a full volume is not a worn volume.", "2": "The APN configures data connectivity. Carriers do not provision local storage.", "3": "Removing the PIN weakens security and frees no space; encryption does not reserve a scratch area."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "storage-full", "app-crash", "os-updates"], "id": "C2N-W-019"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user's smartphone fails to connect to both corporate Wi-Fi and Bluetooth headsets simultaneously, showing erratic connection drops. What is the quickest first-level troubleshooting step to reset all local wireless radio stacks?", "options": ["Toggle Airplane Mode on for 15 seconds, or run a network settings reset", "Factory wipe the handset and restore it from the last cloud backup", "Swap the physical SIM for an eSIM profile from the carrier", "Raise the display timeout so the radios are not powered down"], "answer": 0, "explanation": "Toggling Airplane Mode ON powers down all internal wireless transceivers (Wi-Fi, Bluetooth, Cellular, NFC, GPS) and turning it back OFF reinitializes the hardware radio controllers and restarts connection handshakes. If toggling fails, performing a 'Reset Network Settings' clears corrupted Wi-Fi profiles and Bluetooth pairings. Factory wipes are overly disruptive for basic radio glitches, SIM swaps do not fix Wi-Fi/Bluetooth, and display timeout is unrelated.", "distractor_analysis": {"1": "A wipe is the last resort, not a first-level step, and it costs the user a full restore.", "2": "The SIM handles cellular registration and has no role in Wi-Fi or Bluetooth.", "3": "Screen timeout does not gate the radios; modern handsets keep them alive when connected."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "connectivity", "airplane-mode", "bluetooth", "wi-fi"], "id": "C2N-W-020"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A mobile device only charges when the USB-C charging cable is held tightly at an upward angle. Trying multiple known-good cables produces the same loose, intermittent connection. What is the MOST likely cause?", "options": ["Lint and debris compacted inside the device charging port preventing the cable from seating completely", "A corrupted battery driver inside the mobile operating system", "The electrical wall outlet delivering incorrect AC frequency", "A malware infection on the mobile device"], "answer": 0, "explanation": "Pocket lint and dust frequently accumulate and become compacted at the bottom of mobile charging ports (USB-C or Lightning). This physical barrier prevents charging cables from clicking fully into place, causing loose or angle-dependent connections. Carefully cleaning the port with a non-conductive wooden or plastic pick clears the obstruction. Battery drivers, AC wall frequencies, and malware do not cause mechanical cable loose-fit symptoms.", "distractor_analysis": {"1": "Battery software drivers cannot cause physical looseness or mechanical failure of the cable connector latch.", "2": "AC wall frequency does not affect the physical fit or retention clips of the USB-C connector inside the smartphone.", "3": "Malware is malicious software and cannot alter the mechanical tolerance of physical hardware ports."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "charging", "lightning", "usb-c", "lint"], "id": "C2N-W-021"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A single banking application crashes immediately upon launch on an Android device, while all other applications function perfectly. Which sequence of troubleshooting steps should the technician perform for this specific app?", "options": ["Clear the app cache and data, check for an app update, then reinstall the app", "Wipe the device and replace the battery before testing again", "Turn off mobile data and use the public Wi-Fi network instead", "Change the system language and reboot to rebuild the app cache"], "answer": 0, "explanation": "When an isolated application crashes, the issue is almost always a corrupted local application cache/data store or a version bug. The standard troubleshooting sequence is: 1. Force stop the app, 2. Clear app cache and data in Settings, 3. Check the Google Play Store / App Store for an updated version, and 4. Uninstall and cleanly reinstall the application. Formatting devices or replacing batteries is unwarranted, and changing system language does not fix application crashes.", "distractor_analysis": {"1": "One app is failing while everything else works, so a device-wide wipe is disproportionate.", "2": "The transport is not the fault. Other apps use the same connection without a problem.", "3": "A language change does not clear that app's cache and can introduce new resource faults."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "app-crashes", "app-cache", "update"], "id": "C2N-W-022"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "hard", "question": "A delivery driver reports that their mobile mapping application places their location several miles away from their actual physical position. What troubleshooting steps should be checked to resolve inaccurate location tracking?", "options": ["Set Location Services to high accuracy, get a clear view of the sky, and calibrate the compass", "Replace the SIM so the device re-registers with the carrier location service", "Factory reset the handset to clear a corrupt assisted GPS almanac", "Turn off Wi-Fi scanning so the device stops using access point positioning"], "answer": 0, "explanation": "Mobile location accuracy relies on assisted GPS (A-GPS), which combines satellite GPS signals, nearby Wi-Fi network BSSID scanning, and cellular tower triangulation. Setting Location to 'High Accuracy' / 'Precise Location', verifying that the vehicle's metallic roof or windshield tint is not blocking satellite line-of-sight, and calibrating the device compass resolves drift. SIM replacement does not improve GPS triangulation, and disabling Wi-Fi scanning degrades location precision.", "distractor_analysis": {"1": "The SIM handles carrier registration. Position comes from GNSS plus Wi-Fi and cell assistance, not from the SIM.", "2": "A factory reset is far past a first step and loses the user data for a fault that settings usually fix.", "3": "Wi-Fi scanning improves accuracy indoors. Turning it off usually makes the error worse."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "gps", "location-services", "cellular-triangulation"], "id": "C2N-W-023"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "An iPhone user reports that the device vibrates for incoming calls and notifications, but no ringtone or audio plays through the internal speaker. Media in the Music app plays audio normally. What is the MOST likely cause?", "options": ["The Ring/Silent switch is set to Silent, or a Focus mode is enabled", "The internal speaker has failed and needs replacement", "The charging port is defective and has muted the audio path", "The SIM is PIN locked, which disables the ringer"], "answer": 0, "explanation": "Because media audio plays normally through the speaker, the physical speaker hardware is completely functional. The separation between media audio and alert audio indicates that the physical Ring/Silent switch is set to Silent (showing the orange indicator) or software Focus / Do Not Disturb mode is silencing incoming calls and notification alerts. Physical speaker failure would affect all audio including music, port defects affect charging, and SIM locks block cellular connectivity entirely.", "distractor_analysis": {"1": "A failed speaker would mute Music playback too. Media plays fine, so the hardware works.", "2": "A bad port affects charging and wired audio. It does not silence the internal speaker.", "3": "A PIN locked SIM blocks the cellular radio entirely, so calls would not arrive at all."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-troubleshooting", "sound", "speaker", "dnd", "mute-switch"], "id": "C2N-W-024"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "hard", "question": "A Mobile Device Management (MDM) console flags an executive's enrolled tablet as 'Non-Compliant' and automatically blocks access to Microsoft 365 email. The MDM agent reports an unauthorized superuser binary (`/system/xbin/su`). What has occurred?", "options": ["The tablet is rooted or jailbroken, so MDM revoked corporate data access", "The device passcode was entered incorrectly three times", "The device has dropped below the 20 percent battery policy", "The corporate access point was offline during the compliance check"], "answer": 0, "explanation": "MDM agents actively monitor enrolled devices for indicators of compromise, specifically rooting (on Android) or jailbreaking (on iOS), evidenced by the presence of binaries like `su` or Cydia/Magisk. Because rooting breaks OS kernel sandboxing and exposes corporate data to malware, the MDM compliance policy automatically marks the device non-compliant and revokes access to corporate email and resources. Forgotten PINs trigger device lockouts, and low battery or Wi-Fi outages do not generate `su` binary alerts.", "distractor_analysis": {"1": "Repeated passcode failures lock the device locally; they do not raise a superuser binary finding.", "2": "Battery level is not a compliance criterion in any standard MDM baseline.", "3": "An access point outage stops check-in, which reports as stale rather than non-compliant."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "mdm-compliance", "jailbreak-detection", "byod"], "id": "C2N-W-025"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user notices their corporate smartphone incurs massive cellular data overage charges (50 GB in three days) while remaining idle on their desk. The battery is constantly hot. What security issue should the technician investigate?", "options": ["Malicious spyware or crypto-mining malware running in the background and exfiltrating data or computing hashes", "The user enabling Dark Mode in system settings", "A defective SIM card sending duplicate cellular pings", "The cellular carrier upgrading local cell towers to 5G"], "answer": 0, "explanation": "Sudden extreme data consumption combined with constant thermal heat and battery drain on an idle mobile device is a classic symptom of malicious background activity, such as spyware exfiltrating audio/video/files to a command-and-control server or a covert crypto-miner utilizing the GPU/CPU. Dark mode actually saves battery on OLED displays, SIM cards do not transfer gigabytes of payload data on their own, and carrier 5G upgrades do not cause unauthorized client data transmission.", "distractor_analysis": {"1": "Dark Mode reduces display power consumption on OLED screens and has zero effect on network data usage.", "2": "A damaged SIM card produces cellular registration errors, not massive 50 GB background data transfers.", "3": "Carrier network upgrades change radio tower frequencies without generating unauthorized data transmissions from client devices."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "data-usage", "spyware", "unauthorized-access"], "id": "C2N-W-026"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "hard", "question": "While connected to public airport Wi-Fi, a user's mobile browser begins displaying invalid SSL/TLS certificate warnings for major banking and search websites. What mobile security threat is the user experiencing?", "options": ["An on-path attack from a rogue access point intercepting TLS sessions", "The device certificate store was cleared by the last OS update", "The captive portal has not been accepted, so requests are redirected", "The device clock is wrong, so valid certificates read as not yet valid"], "answer": 0, "explanation": "When connecting to untrusted public Wi-Fi, attackers can deploy an Evil Twin access point or ARP spoofing to intercept traffic. When the attacker attempts SSL stripping or decrypts HTTPS sessions with a fake proxy certificate, the user's browser detects that the certificate was not signed by a trusted root CA and triggers invalid certificate warnings. Battery health, camera hardware, and SMS carrier status have no relationship with TLS certificate validation on Wi-Fi.", "distractor_analysis": {"1": "A wiped trust store breaks every site everywhere, not only while on this one network.", "2": "A captive portal redirect usually shows the portal page, and it would not target banking sites specifically.", "3": "Clock skew is a real cause of certificate warnings, but it would follow the device off the airport network."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "rogue-certificates", "mitm", "ssl-inspection"], "id": "C2N-W-027"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user discovers several unfamiliar game applications and utility toolbars installed on their corporate Android tablet that they never downloaded from the Google Play Store. What setting should the technician verify and disable to prevent this in the future?", "options": ["Disable 'Install unknown apps' / third-party sideloading permissions in Settings -> Security", "Enable Bluetooth Discoverable mode permanently", "Disable the screen lock passcode", "Enable developer USB debugging and leave it unattended"], "answer": 0, "explanation": "Android security controls include the 'Install unknown apps' permission (or 'Unknown sources' in older versions). Disabling this permission prevents the device from installing `.apk` packages downloaded from web browsers, messaging apps, or unverified third-party repositories, restricting software installation strictly to vetted enterprise or official app stores. Enabling Bluetooth discoverability, removing passcodes, and enabling USB debugging all decrease device security.", "distractor_analysis": {"1": "Keeping Bluetooth in discoverable mode exposes the device to unauthorized pairing and Blueborne/Bluesnarfing attacks.", "2": "Disabling screen lock passcodes leaves the device completely vulnerable to unauthorized physical access.", "3": "Enabling USB debugging allows any connected computer to execute shell commands via Android Debug Bridge (ADB), creating a massive security risk."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "unauthorized-apps", "sideloading", "remediation"], "id": "C2N-W-028"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user notices the green/orange privacy indicator dot at the top of their smartphone screen illuminates randomly when no applications are actively in use. What does this indicate, and how should it be investigated?", "options": ["An app is using the camera or microphone; check the permission manager and revoke access", "The screen backlight is failing and the panel needs replacement", "The battery has reached 100 percent and charging has stopped", "The cellular radio has attached to a 4G LTE tower nearby"], "answer": 0, "explanation": "Modern mobile operating systems (iOS and Android) display visual privacy indicators (an orange or green dot in the status bar) whenever an application accesses the device's microphone or camera. If this occurs while the user is idle, a background app is recording audio or video. The technician should immediately open Privacy / Permission Manager, review the access log, revoke microphone/camera permissions from suspicious apps, and uninstall unauthorized software. It is not a backlight failure, charging indicator, or cellular beacon.", "distractor_analysis": {"1": "A failing backlight dims or flickers the whole panel. It does not paint a single coloured dot.", "2": "Charge state shows in the status bar battery icon, not as a privacy indicator.", "3": "Radio attachment is shown by the signal bars and network label."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "permissions", "privacy", "camera-microphone"], "id": "C2N-W-029"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "hard", "question": "A senior manager suddenly loses all cellular service on their smartphone, displaying 'No Service' or 'SOS only'. Minutes later, they receive email notifications that their bank password and cloud account recovery details were changed from an unknown location. What attack has occurred?", "options": ["SIM card swapping / port-out fraud by a social engineering threat actor targeting the carrier", "A standard local micro-SIM mechanical failure", "The smartphone's Wi-Fi antenna burning out", "The mobile carrier performing scheduled tower maintenance"], "answer": 0, "explanation": "SIM swapping occurs when an attacker impersonates the victim to the cellular carrier (or bribes an insider) to transfer (port) the victim's phone number to a new SIM card under the attacker's control. Once transferred, the victim's phone immediately loses cellular connection ('No Service'), and the attacker receives all SMS-based 2FA codes and password reset tokens, enabling rapid account takeovers. Mechanical SIM failures and tower maintenance do not coincide with immediate targeted account takeovers.", "distractor_analysis": {"1": "A simple physical SIM failure disables cellular connectivity but would not result in simultaneous unauthorized password resets across external banking accounts.", "2": "A burnt-out Wi-Fi antenna affects Wi-Fi connections only and has no effect on cellular tower reception or SIM registration.", "3": "Carrier maintenance temporarily interrupts signal but does not trigger concurrent fraudulent account takeovers and credential resets."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "sim-swapping", "account-takeover", "cellular"], "id": "C2N-W-030"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "An employee working in a public coffee shop receives multiple unsolicited Bluetooth pairing requests from unknown device names attempting to establish connections. What immediate actions should the employee take?", "options": ["Reject the pairing requests and turn off Bluetooth (or disable Bluetooth discoverability)", "Accept the pairing requests to inspect the remote device identity", "Factory reset the mobile device immediately", "Enter '0000' or '1234' on the keypad"], "answer": 0, "explanation": "Receiving unsolicited Bluetooth pairing requests indicates a nearby attacker attempting Bluejacking (sending unsolicited messages) or Bluesnarfing (unauthorized access to contacts and data via Bluetooth). The user must immediately reject the requests and turn off Bluetooth or ensure the device is not set to discoverable mode. Accepting requests or entering default PINs gives the attacker an active paired connection into the device.", "distractor_analysis": {"1": "Accepting the pairing request establishes a trusted Bluetooth channel, allowing the attacker to access data or exploit protocol vulnerabilities.", "2": "Factory resetting the smartphone is an extreme overreaction when simply disabling Bluetooth stops the attempt immediately.", "3": "Entering default PINs completes pairing authentication with the attacker's unauthorized device."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile-security-troubleshooting", "bluetooth-security", "bluesnarfing", "pairing"], "id": "C2N-W-031"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user reports that whenever they open their web browser, dozens of pop-up windows appear claiming the PC is infected with 43 viruses and offering a toll-free number to purchase 'Tech Support Gold.' The default homepage has also been changed. What security issue is present?", "options": ["Rogue antivirus / Scareware and browser hijacking", "A hardware failure of the network interface card", "A legitimate Windows Defender security alert", "A standard Windows operating system update prompt"], "answer": 0, "explanation": "Rogue antivirus (scareware) uses fake alert dialogs, artificial virus counts, and persistent pop-ups designed to frighten users into paying for fraudulent tech support or downloading malware payloads. This is frequently accompanied by browser hijacking (changing default homepages and search engines). Legitimate Windows Defender alerts appear in the Windows Notification Center and never ask users to call a phone number with payment information.", "distractor_analysis": {"1": "Network interface card hardware faults cause complete loss of network connectivity, not fake pop-up advertisement generation.", "2": "Microsoft Defender Antivirus integrates directly into the Windows Security Center and never displays third-party phone numbers or payment demands.", "3": "Windows Update prompts appear in Settings and system notifications, focusing exclusively on OS and security patch installations."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "popups", "adware", "browser-redirects"], "id": "C2N-W-032"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "Several corporate clients notify the help desk that they received phishing emails containing invoice attachments sent directly from a company account executive's email address. The executive states they never sent these messages. What is the FIRST step the technician should take?", "options": ["Immediately disable or reset the executive's domain/cloud account password, terminate all active login sessions, and enable MFA", "Reformat the executive's desktop computer immediately", "Delete the executive's entire email mailbox from the mail server", "Reply to all recipient clients stating the emails were genuine"], "answer": 0, "explanation": "When an email account is actively sending unauthorized spam/phishing messages, the account credentials have been compromised (often via credential harvesting or session token theft). The immediate containment step is resetting the user's password, revoking/terminating all active OAuth tokens and web sessions, and verifying/enforcing multifactor authentication (MFA). Reformatting the PC does not stop cloud-based webmail access, deleting the mailbox destroys business records, and validating phishing emails causes further compromise.", "distractor_analysis": {"1": "Reformatting the local PC does not revoke stolen cloud session tokens or change compromised domain passwords being used by attackers remotely.", "2": "Deleting the entire mailbox permanently erases vital company communications and forensic evidence required for the security investigation.", "3": "Confirming phishing emails as genuine misleads clients and accelerates financial fraud against the organization's partners."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "compromised-account", "spam-email", "incident-response"], "id": "C2N-W-033"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "An administrator suspects an unauthorized user is accessing a shared accounting workstation after hours. Which Windows log in Event Viewer should be audited to inspect successful and failed logon attempts, and which Event IDs are relevant?", "options": ["Security Log (Event ID 4624 for Successful Logon and Event ID 4625 for Failed Logon)", "Application Log (Event ID 1000 for Application Error)", "System Log (Event ID 6005 for Event Log service started)", "Setup Log (Event ID 1 for OS servicing update)"], "answer": 0, "explanation": "The Windows `Security` event log records all security audit events. Event ID 4624 documents every successful logon (including logon type, username, workstation name, and source IP address), while Event ID 4625 documents failed logon attempts. The Application log tracks program errors, the System log tracks OS service and driver events, and the Setup log tracks Windows installation and update events.", "distractor_analysis": {"1": "The Application log records software crashes (Event ID 1000) and application-level exceptions, not user authentication events.", "2": "The System log records operating system kernel, hardware, and service milestones (such as Event ID 6005 for service startup).", "3": "The Setup log records operating system feature installation and upgrade packages, having no user logon audit telemetry."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "unauthorized-access", "audit-logs", "event-viewer"], "id": "C2N-W-034"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "Users across an entire office cannot access the internal HR intranet portal, receiving browser alerts that the website's security certificate is invalid because the 'Valid to' date has passed. What is the root cause and proper remediation?", "options": ["The server certificate has expired; the administrator must renew it and bind the new one", "The intranet DNS record now points at the wrong web server", "The clients do not trust the internal CA that issued the certificate", "The site is served over plain HTTP, so the browser marks it insecure"], "answer": 0, "explanation": "X.509 digital certificates have strict validity date ranges ('Valid from' and 'Valid to'). Once the expiration timestamp passes, browsers reject the certificate and warn users of a potential security breach. The resolution is for the web server administrator to generate a new Certificate Signing Request (CSR), obtain a renewed certificate from the Certificate Authority (CA), and bind it to the HTTPS service on the web server. Disk space, switch duplex, and user passwords do not cause certificate expiration.", "distractor_analysis": {"1": "A wrong DNS record gives a name mismatch warning or the wrong site, not an expiry date warning.", "2": "An untrusted issuer reads as untrusted authority. The browser named the Valid to date instead.", "3": "Plain HTTP shows a not secure label with no certificate to expire."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "certificate-expired", "pki", "https-errors"], "id": "C2N-W-035"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user notices that the Windows Defender Security Center icon has a red warning indicator. Opening the console reveals that 'Real-time protection' is turned off and the toggle switch is greyed out. What is the MOST likely cause?", "options": ["Malware or Group Policy has disabled Defender, or a third-party suite has taken over", "The Security Center service is stopped and set to manual start", "Tamper Protection is on, which greys out the toggle by design", "The signature package is more than 30 days out of date"], "answer": 0, "explanation": "When Windows Defender real-time protection is disabled and greyed out, it typically indicates that malicious software has altered system registry keys (e.g., `DisableAntiSpyware` under HKLM) or Group Policy to prevent the antivirus from running. Alternatively, installing a registered third-party antivirus package intentionally disables Defender to prevent engine conflicts. Monitor refresh rates, CMOS batteries, and RAM channel modes have no control over Windows Security services.", "distractor_analysis": {"1": "A stopped Security Center service leaves the console unable to report at all, rather than showing a disabled toggle.", "2": "Tamper Protection blocks changes made by other software, but the console itself still shows protection as on.", "3": "Stale signatures raise an out-of-date warning while real-time protection stays enabled."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "services-disabled", "security-center", "antivirus"], "id": "C2N-W-036"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "During an investigation of an endpoint suspected of malware infection, a technician runs `netstat -ano` from an elevated prompt and spots an established TCP connection on port 4444 to an unknown external IP address with Process ID (PID) 3812. What action should the technician take to identify the executable?", "options": ["Map PID 3812 to its executable with tasklist or the Task Manager Details tab", "Reboot into UEFI setup so the socket is torn down on restart", "Run ipconfig /flushdns to clear the resolver entry for that host", "Delete pagefile.sys so the process cannot page its payload back in"], "answer": 0, "explanation": "The `netstat -ano` command lists active network sockets along with their owning Process Identifier (PID). Using Task Manager (Details tab, sorting by PID) or executing `tasklist /fi \"PID eq 3812\"` correlates PID 3812 with the exact executable binary name, user account, and directory path. Right-clicking the process in Task Manager and selecting 'Open file location' reveals the binary for quarantine. BIOS reboots, DNS flushes, and pagefile deletions do not identify or analyze the running malicious process.", "distractor_analysis": {"1": "Rebooting destroys the volatile evidence you were just handed and may let the malware restart cleanly.", "2": "Flushing the resolver cache does not stop a process or reveal which binary opened the socket.", "3": "The paging file is not where malware lives, and it is locked while Windows is running."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "open-ports", "netstat", "c2-traffic"], "id": "C2N-W-037"}, {"exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user notices that files in their Documents folder are rapidly changing to have `.cryptolocker` file extensions and icons are turning blank. What is the IMMEDIATE containment action the technician must instruct the user to take?", "options": ["Disconnect the machine from the network immediately, wired and wireless", "Open one file in Notepad to confirm the encryption is genuine", "Email a sample encrypted file to the whole team as a warning", "Run Disk Defragmenter so the original clusters can be recovered"], "answer": 0, "explanation": "Active file renaming with ransomware extensions indicates a live encryption process that will rapidly spread across mapped network drives and shared enterprise storage. The immediate emergency containment action is physically disconnecting the machine from the network (pulling the Ethernet cable and disabling Wi-Fi/Bluetooth) to isolate the infection and stop lateral encryption across network shares. Opening files in Notepad, emailing infected attachments, and running defragmentation worsen the disaster.", "distractor_analysis": {"1": "Opening a file wastes time while encryption spreads to mapped drives.", "2": "Mailing the sample risks spreading the payload and clogs mailboxes during an incident.", "3": "Defragmenting overwrites the free space where deleted originals might still be recoverable."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security-troubleshooting", "file-renamed", "ransomware", "containment"], "id": "C2N-W-038"}, {"id": "C2N-X-001", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows laptop takes several minutes to reach the desktop and then remains sluggish for another few minutes before settling down. Which tool should the technician use first to identify the cause?", "options": ["Task Manager's Startup tab to review programs launching at sign-in and their impact rating", "Disk Management to shrink the system volume", "Device Manager to roll back the display driver", "Windows Update to pause updates"], "answer": 0, "explanation": "Slow boot followed by a sluggish first few minutes is the classic footprint of too many startup programs competing for disk and CPU while the desktop loads. The Startup tab in Task Manager lists each item with a measured startup impact and lets the technician disable the unnecessary ones without uninstalling anything. Only if startup is clean should storage health, drivers or pending updates be examined. Shrinking volumes, driver rollbacks and pausing updates do not address startup load.", "distractor_analysis": {"1": "Volume size has nothing to do with boot-time load.", "2": "A display driver problem shows as graphics faults, not general slowness after boot.", "3": "Pausing updates hides symptoms and does not reduce startup programs."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "slow-boot", "startup", "task-manager"]}, {"id": "C2N-X-002", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user's Windows PC shows a blue screen with a stop code shortly after a new graphics driver was installed. Windows still boots occasionally. What is the most appropriate first repair?", "options": ["Boot into Safe Mode and roll back or uninstall the new graphics driver", "Reinstall Windows from scratch", "Replace the graphics card", "Run Disk Cleanup"], "answer": 0, "explanation": "A blue screen that begins immediately after a driver change points at that driver. Safe Mode loads Windows with generic drivers so the faulty one is not active, and Device Manager's Roll Back Driver or Uninstall Device option removes it. If the machine then runs stable, the driver was the cause and a different version can be tried. Reinstalling Windows or replacing hardware is premature when a software change is the obvious variable, and Disk Cleanup addresses disk space rather than crashes.", "distractor_analysis": {"1": "A reinstall destroys the user's setup to fix a single driver.", "2": "The hardware worked before the driver update.", "3": "Disk space does not cause driver-related stop errors."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "bsod", "driver", "safe-mode"]}, {"id": "C2N-X-003", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows PC displays a message that a critical system file is missing or corrupt and will not finish booting. Which recovery tool should be tried first?", "options": ["Startup Repair from the Windows Recovery Environment", "Reset this PC with the remove everything option", "Format the drive", "Update the firmware"], "answer": 0, "explanation": "The Windows Recovery Environment is reached automatically after repeated failed boots or from installation media, and its Startup Repair option scans for and replaces missing or damaged boot files and fixes the boot configuration. It is non-destructive and should always be tried before anything that erases data. If it fails, System Restore or the command-line tools such as sfc and bootrec are the next steps. Resetting or formatting throws away the user's data for a problem that is usually repairable.", "distractor_analysis": {"1": "A full reset erases the user's files and is a last resort.", "2": "Formatting destroys everything and is never the first step.", "3": "Firmware updates do not repair Windows boot files."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "boot", "startup-repair", "winre"]}, {"id": "C2N-X-004", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "Several Windows applications crash when opened, and Event Viewer shows errors referencing corrupted system files. Which command should the technician run from an elevated prompt?", "options": ["sfc /scannow", "chkdsk /r", "ipconfig /flushdns", "gpupdate /force"], "answer": 0, "explanation": "System File Checker compares protected Windows files against known good copies and replaces any that are damaged or modified. When the log reports corruption sfc cannot fix, running DISM with the RestoreHealth option repairs the component store first, then sfc is run again. Check Disk targets file system and disk surface errors rather than system file integrity, and the networking and Group Policy commands are unrelated to application crashes.", "distractor_analysis": {"1": "chkdsk repairs file system structures and bad sectors, not protected system files.", "2": "Flushing DNS affects name resolution only.", "3": "gpupdate refreshes policy and has no effect on file integrity."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "sfc", "dism", "corruption"]}, {"id": "C2N-X-005", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows PC freezes for several seconds at a time throughout the day, and Task Manager shows disk utilisation pinned at 100 percent during the freezes. What is the most likely cause?", "options": ["A failing or heavily fragmented mechanical hard drive, or an indexing or antivirus scan saturating a slow disk", "The monitor's refresh rate is too low", "The keyboard driver needs updating", "The user has too many browser bookmarks"], "answer": 0, "explanation": "Sustained 100 percent disk time with system-wide pauses means every process is waiting on storage. On a spinning drive this happens when the drive is developing bad sectors and retrying reads, or when background tasks such as search indexing, antivirus scans or update installs monopolise a slow disk. Checking the drive's health with the vendor tool or SMART data, then reviewing the processes on the Disk column, isolates the cause. Refresh rate, keyboard drivers and bookmarks have no effect on disk queue.", "distractor_analysis": {"1": "Refresh rate affects display smoothness, not disk activity.", "2": "Keyboard drivers do not generate disk load.", "3": "Bookmarks are a tiny file and irrelevant."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "performance", "disk", "freeze"]}, {"id": "C2N-X-006", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "After a Windows feature update, a user's specialised accounting program no longer opens. The vendor has not released a compatible version. Which option restores the program with the least disruption?", "options": ["Roll back the feature update within the rollback window using Recovery settings", "Delete the user profile", "Reinstall the printer drivers", "Change the display language"], "answer": 0, "explanation": "Windows keeps the previous version for a limited period after a feature update, and Settings offers a Go back option that returns the system to the earlier build with programs and files intact. This buys time until the vendor supports the new version, after which the update can be reapplied. Deleting the profile, reinstalling unrelated drivers and changing language settings do not address an application that is incompatible with the new operating system build.", "distractor_analysis": {"1": "The profile is not the problem; the operating system build is.", "2": "Printer drivers are unrelated to the accounting program.", "3": "Display language has no bearing on application compatibility."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "update", "rollback", "compatibility"]}, {"id": "C2N-X-007", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows PC reports low memory warnings and applications close unexpectedly, although the machine has 16 GB of RAM. Task Manager shows one browser process using 11 GB. What should the technician do first?", "options": ["Identify and close or fix the runaway process, such as the browser with excessive tabs or a faulty extension", "Install a larger hard drive", "Lower the screen resolution", "Disable Windows Defender"], "answer": 0, "explanation": "Low memory with one process consuming most of the RAM is a runaway application, not a hardware shortage. The Processes tab in Task Manager makes the offender obvious. Closing it relieves the pressure immediately, and the longer fix is to find the cause, commonly dozens of open tabs, a misbehaving extension or a memory leak fixed by an update. Storage capacity, display settings and security software are not the constraint here.", "distractor_analysis": {"1": "Disk capacity is unrelated to RAM exhaustion.", "2": "Resolution changes have negligible memory impact.", "3": "Disabling security software does not free the memory the browser holds."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "memory", "task-manager", "performance"]}, {"id": "C2N-X-008", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A Windows service that a line-of-business application depends on fails to start at boot, and the application reports it cannot connect. Where should the technician look to find out why the service failed?", "options": ["The System log in Event Viewer, then the service's properties in the Services console for its dependencies and log-on account", "Disk Cleanup", "The Fonts control panel", "Display settings"], "answer": 0, "explanation": "Service failures are recorded in the System log with an event that names the service and the reason, such as a dependency that did not start, a log-on account whose password changed, or a timeout. The Services console then shows the dependencies tab and the account the service runs under, which are the usual culprits. Setting the service to Automatic (Delayed Start) also resolves timing problems. Cleanup, fonts and display settings have no relationship to service startup.", "distractor_analysis": {"1": "Disk Cleanup removes temporary files.", "2": "Fonts are unrelated to services.", "3": "Display settings do not affect background services."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "services", "event-viewer", "troubleshooting"]}, {"id": "C2N-X-009", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "hard", "question": "A user reports that Windows reboots itself at random with no blue screen displayed. Event Viewer shows an unexpected shutdown event each time but no stop error. Which setting would help the technician capture the cause next time?", "options": ["Disable automatic restart on system failure and enable a memory dump in Startup and Recovery settings", "Turn on the screen saver", "Increase the desktop icon size", "Set the default browser"], "answer": 0, "explanation": "By default Windows restarts immediately after a stop error, so a crash can look like a spontaneous reboot. Unticking automatic restart in the Startup and Recovery dialog makes the blue screen stay on screen with its stop code, and enabling a kernel or small memory dump writes a file that can be analysed to name the failing driver. If no stop error appears even then, the cause is likely power or hardware such as overheating or a failing supply.", "distractor_analysis": {"1": "Screen savers do not diagnose crashes.", "2": "Icon size is cosmetic.", "3": "The browser default is unrelated to system stability."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "reboot", "memory-dump", "diagnostics"]}, {"id": "C2N-X-010", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "single", "difficulty": "medium", "question": "A user's Windows profile loads with a plain desktop, missing shortcuts and documents, and a notification says they have been signed in with a temporary profile. What is the correct approach?", "options": ["Do not save work in the temporary profile; repair the profile registry entry or create a new profile and migrate the user's data", "Tell the user the files are gone", "Reinstall Windows immediately", "Delete the user's account"], "answer": 0, "explanation": "A temporary profile appears when Windows cannot load the user's real profile, usually because the profile folder is locked or its registry entry under ProfileList is damaged. The user's data still exists in their original profile folder. Anything saved in the temporary profile is discarded at sign-out, so the first step is to warn the user, then either fix the registry entry or create a fresh profile and copy the documents, desktop and settings across. Reinstalling or deleting the account is unnecessary and risks the data.", "distractor_analysis": {"1": "The data is intact in the original profile folder.", "2": "A profile problem does not require reinstalling the operating system.", "3": "Deleting the account can remove the profile folder and the data with it."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "user-profile", "temporary-profile", "troubleshooting"]}, {"id": "C2N-X-011", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "multi", "difficulty": "medium", "question": "A Windows PC has become slow over several months. Which TWO actions are appropriate early steps before considering hardware upgrades? (Select TWO.)", "options": ["Review and disable unnecessary startup programs and background applications", "Check for malware and confirm the disk has adequate free space and is healthy", "Replace the motherboard", "Reinstall the printer", "Change the desktop wallpaper to a solid colour"], "answers": [0, 1], "explanation": "Gradual slowdown is almost always software accumulation: programs that install themselves at startup, background updaters and synchronisation agents, and sometimes malware. Trimming startup items and scanning for threats addresses the common causes, and confirming the disk is not nearly full or failing rules out the storage bottleneck that dominates on older machines. Hardware replacement comes only after those checks, and printers and wallpaper have no bearing on general performance.", "distractor_analysis": {"2": "Motherboard replacement is expensive and unjustified without a diagnosis.", "3": "Printer software rarely affects overall speed.", "4": "Wallpaper has a negligible performance effect on modern systems."}, "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "performance", "startup", "malware"]}, {"id": "C2N-X-012", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.1", "type": "order", "difficulty": "medium", "question": "Order the recovery steps for a Windows PC that fails to boot after a driver update, from least to most disruptive.", "sequence": ["Boot into Safe Mode and roll back or uninstall the recently changed driver", "Use System Restore to return the system to a restore point taken before the change", "Run Startup Repair and the sfc and DISM tools from the recovery environment", "Use Reset this PC with the keep my files option", "Perform a clean installation of Windows and restore data from backup"], "explanation": "Troubleshooting escalates from the reversible to the destructive. Removing the specific driver targets the known change with no side effects. System Restore rolls back system files and registry while leaving documents alone. Repair tools rebuild boot files and system components. Reset reinstalls Windows but preserves personal files at the cost of applications. A clean install is the last resort because it discards everything not backed up. Each step is tried only if the previous one fails.", "video_reference": {"title": "Troubleshooting Windows - CompTIA A+ 220-1202 - 3.1", "url": "https://www.youtube.com/watch?v=qIenQsBAg2U", "duration": "17:30", "objective": "3.1"}, "notes_reference": "21_Remote_Access_Performance_OS_Troubleshooting.md", "tags": ["windows", "recovery", "procedure", "escalation"]}, {"id": "C2N-X-013", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "easy", "question": "A user's phone has become very slow and apps take a long time to open. Storage shows 98 percent used. What should the technician recommend first?", "options": ["Free storage by removing unused apps, clearing caches and offloading photos to the cloud", "Replace the phone's battery", "Turn off Wi-Fi", "Change the ringtone"], "answer": 0, "explanation": "Mobile operating systems need free space to write caches, update apps and manage memory. When storage is nearly full the device spends its time shuffling data and everything slows down. Deleting apps that are no longer used, clearing large app caches such as browsers and messaging, and moving photos and videos to cloud storage recovers space and speed. The battery, Wi-Fi and ringtone have nothing to do with a storage shortage.", "distractor_analysis": {"1": "Battery health affects runtime, not app launch speed.", "2": "Wi-Fi state does not change storage pressure.", "3": "Ringtones are cosmetic."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "storage", "performance"]}, {"id": "C2N-X-014", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A single app on a phone crashes every time it is opened, while every other app works. Which sequence of steps is most appropriate?", "options": ["Force close the app, clear its cache, update it, and if it still fails uninstall and reinstall it", "Factory reset the phone immediately", "Replace the phone", "Remove the SIM card"], "answer": 0, "explanation": "When one application misbehaves and the rest of the device is fine, the fault is confined to that app's code or data. Force closing clears its running state, clearing the cache removes corrupted temporary files, an update may include the bug fix, and reinstalling gives it a clean start while most apps restore their data from the account. A factory reset or a new phone is a huge intervention for a single app, and the SIM is unrelated.", "distractor_analysis": {"1": "A reset wipes the whole device for one app's problem.", "2": "The hardware is fine because every other app works.", "3": "The SIM affects cellular service, not app stability."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "app-crash", "cache", "reinstall"]}, {"id": "C2N-X-015", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user says their phone's battery, which used to last all day, now dies by mid-afternoon after installing a new social media app. What should the technician check?", "options": ["The battery usage screen to see whether the new app is consuming power in the background, then restrict its background activity or location access", "Whether the phone's case is the wrong colour", "Whether the SIM card is too old", "Whether the charger cable is too long"], "answer": 0, "explanation": "Both major platforms show battery consumption per app. An app that refreshes constantly, tracks location continuously or keeps the radio busy will appear at the top of that list. Restricting its background activity, revoking always-on location and disabling unnecessary notifications, or removing it, restores battery life. The case, SIM age and cable length do not affect how quickly the battery drains during use.", "distractor_analysis": {"1": "Case colour has no effect on power.", "2": "SIM cards do not degrade battery life.", "3": "Cable length affects charging speed marginally, not drain."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "battery", "background-apps", "troubleshooting"]}, {"id": "C2N-X-016", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A phone becomes noticeably hot and its screen dims while a user plays a graphics-heavy game outdoors on a sunny day. What is happening?", "options": ["The phone is throttling performance and brightness to protect itself from overheating, which is expected behaviour", "The battery is about to explode and the phone must be thrown away", "The screen protector is melting", "The SIM card is overheating"], "answer": 0, "explanation": "Heavy processing, charging and direct sun together push a phone toward its thermal limit, and the operating system responds by lowering the processor clock and dimming the display, sometimes showing a temperature warning. Moving into shade, closing the game and pausing charging lets it recover. It is a protective mechanism rather than a fault, though a phone that overheats at idle or has a swollen back is a different, serious matter. Protectors and SIMs do not generate heat.", "distractor_analysis": {"1": "Normal thermal throttling is not a battery emergency; swelling or smoke would be.", "2": "Screen protectors tolerate far higher temperatures than a phone reaches.", "3": "A SIM is a passive chip with negligible heat."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "overheating", "throttling"]}, {"id": "C2N-X-017", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A phone's touchscreen stops responding entirely, though the screen still displays normally and the buttons work. The phone was not dropped. What should the technician try first?", "options": ["Force restart the phone using the hardware button combination", "Replace the display assembly", "Remove the SIM card", "Delete all photos"], "answer": 0, "explanation": "An unresponsive digitizer with a working display is frequently a software hang in the touch controller or the operating system, and because the screen cannot be used to shut down, the hardware button combination that forces a restart is the way out. If touch returns after the restart the fault was software. Only if it stays dead, or fails in patches, is the digitizer suspect and a repair justified. The SIM and photos have no relationship to touch input.", "distractor_analysis": {"1": "Hardware replacement is premature before a restart is tried.", "2": "The SIM affects cellular service only.", "3": "Storage contents do not control the digitizer."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "touchscreen", "force-restart", "troubleshooting"]}, {"id": "C2N-X-018", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user cannot install a new app from the official store; the store reports that the app is not compatible with the device. What is the most likely reason?", "options": ["The phone's operating system version is older than the minimum the app requires", "The phone's screen protector is blocking the download", "The user has too many contacts", "Bluetooth is turned off"], "answer": 0, "explanation": "App stores check the device against the app's requirements: operating system version, hardware features and sometimes region. The most common failure is an old operating system that the developer no longer supports. Updating the phone's operating system resolves it if an update is available; if the phone is too old to update, the app cannot be installed and the user needs an alternative or a newer device. Protectors, contacts and Bluetooth play no part in store compatibility.", "distractor_analysis": {"1": "A protector is physical and cannot affect downloads.", "2": "Contact count is irrelevant to app installation.", "3": "Bluetooth is not used for store downloads."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "app-install", "os-version", "compatibility"]}, {"id": "C2N-X-019", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A phone fails to install an operating system update, reporting insufficient space, even though the update is 3 GB and the phone shows 4 GB free. Why does it fail?", "options": ["Updates need additional working space to download, unpack and apply, often double the update's size", "The update is only for phones with a different colour", "The SIM card is full", "Updates can only be installed over Bluetooth"], "answer": 0, "explanation": "An operating system update is downloaded as a compressed package, expanded, and then applied alongside the running system so it can be rolled back if it fails. That process needs considerably more free space than the package itself, so 4 GB free is not enough for a 3 GB update. Clearing space, or updating through a computer where the download is staged on the PC, resolves it. Colour, the SIM and Bluetooth have nothing to do with updates.", "distractor_analysis": {"1": "Updates are tied to model and region, not colour.", "2": "SIM cards store subscriber data only.", "3": "Updates arrive over Wi-Fi or cellular, not Bluetooth."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "os-update", "storage", "troubleshooting"]}, {"id": "C2N-X-020", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user's phone randomly reboots several times a day after a recent operating system update. All apps are current. What is the recommended next step?", "options": ["Back up the phone and perform a factory reset, then restore, to clear corrupted system state left by the update", "Remove the screen protector", "Change the wallpaper", "Turn off the flashlight"], "answer": 0, "explanation": "Random reboots that start after an update and persist with current apps suggest the update left the system in an inconsistent state. Once a backup is confirmed, a factory reset reinstalls the operating system cleanly and restoring from backup returns the user's data. If reboots continue after a clean reset with minimal apps, the fault is hardware, typically the battery or board. Cosmetic settings and accessories are irrelevant.", "distractor_analysis": {"1": "A protector has no effect on stability.", "2": "Wallpaper does not cause reboots.", "3": "The flashlight is unrelated."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "reboot", "factory-reset", "os-update"]}, {"id": "C2N-X-021", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A phone's screen auto-rotates unpredictably and the compass in the maps app points the wrong way. Which action addresses both symptoms?", "options": ["Recalibrate the sensors, for example by moving the phone in a figure-eight pattern, and remove any magnetic case or mount", "Replace the SIM card", "Clear the browser history", "Reduce the screen brightness"], "answer": 0, "explanation": "Rotation and heading both come from the phone's motion and magnetic sensors. A magnetic case, a car mount or a nearby speaker skews the magnetometer, and sensor drift confuses the accelerometer and gyroscope. Removing the magnet source and running the calibration gesture that maps apps prompt for fixes both problems. If they persist after calibration and a restart, the sensor hardware may be faulty. The SIM, browser and brightness have nothing to do with motion sensing.", "distractor_analysis": {"1": "The SIM does not feed sensor data.", "2": "Browser data is unrelated to sensors.", "3": "Brightness does not affect orientation detection."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "sensors", "auto-rotate", "calibration"]}, {"id": "C2N-X-022", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user reports that their phone's Bluetooth car connection drops every few minutes, but only since a recent phone update. Other Bluetooth devices work. What should be tried first?", "options": ["Forget the car in the phone's Bluetooth settings and delete the phone from the car, then pair again", "Replace the car's battery", "Factory reset the phone", "Turn off the car's headlights"], "answer": 0, "explanation": "An update can invalidate stored pairing keys or change the Bluetooth profiles negotiated with a car, leading to unstable connections with that one device while others work. Clearing the pairing on both sides and re-pairing establishes fresh keys and profile negotiation and resolves the majority of post-update car issues. A vehicle head unit update may also be needed. Resetting the whole phone is disproportionate, and the car's battery and lights are irrelevant.", "distractor_analysis": {"1": "The car's power system does not govern Bluetooth pairing keys.", "2": "A full reset is a last resort when re-pairing fails.", "3": "Headlights are unrelated."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "bluetooth", "pairing", "connectivity"]}, {"id": "C2N-X-023", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A user cannot send text messages with photos, though plain texts send and data works elsewhere. Which setting is most likely wrong?", "options": ["The carrier's MMS or APN settings on the phone", "The phone's wallpaper", "The screen timeout", "The keyboard layout"], "answer": 0, "explanation": "Picture messages travel over MMS, which uses the carrier's data path and a specific access point configuration. If the APN or MMS settings are missing or wrong, often after a SIM swap or a carrier change, plain SMS still works because it uses the signalling channel, but photos fail. Resetting network settings or entering the carrier's published APN values fixes it. Cosmetic and input settings have no connection to messaging.", "distractor_analysis": {"1": "Wallpaper is cosmetic.", "2": "Screen timeout does not affect message delivery.", "3": "Keyboard layout changes typing, not transmission."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "mms", "apn", "messaging"]}, {"id": "C2N-X-024", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A tablet's Wi-Fi shows connected but apps report no internet, while the same network works for other devices. Which troubleshooting step is most likely to fix it?", "options": ["Reset the tablet's network settings so it obtains fresh addressing and clears stale saved network data", "Replace the tablet's screen", "Reduce the tablet's volume", "Uninstall the calculator app"], "answer": 0, "explanation": "When one device fails on a network that works for others, the problem is on that device: a stale DHCP lease, a bad saved DNS or proxy setting, or a corrupted network profile. Resetting network settings clears every saved network, VPN and cellular setting to defaults and forces a clean reconnection, which resolves most of these cases at the cost of re-entering Wi-Fi passwords. Hardware, audio and unrelated apps are not involved.", "distractor_analysis": {"1": "The display has no part in networking.", "2": "Volume is audio only.", "3": "A calculator app does not affect connectivity."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "wi-fi", "network-reset", "connectivity"]}, {"id": "C2N-X-025", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "hard", "question": "A corporate tablet is stuck displaying the manufacturer logo after a failed update and never reaches the home screen. Which approach should the technician take?", "options": ["Boot into recovery mode and use a computer with the vendor's tool to reapply the operating system, restoring from backup afterwards", "Leave it charging for a week", "Remove the screen protector", "Send a text message to the tablet"], "answer": 0, "explanation": "A device frozen on its logo has a corrupted or incomplete operating system and needs the firmware reapplied. Both platforms offer a recovery or download mode reachable with a button combination, and the vendor's desktop tool can reflash the system without necessarily wiping data, though a full restore is often required. Once it boots, the backup restores the user's content. Waiting, cosmetic accessories and messaging cannot repair a boot loop.", "distractor_analysis": {"1": "Charging does not repair corrupted system software.", "2": "A protector has nothing to do with booting.", "3": "A device that has not booted cannot receive messages."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "boot-loop", "recovery-mode", "os-update"]}, {"id": "C2N-X-026", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "single", "difficulty": "medium", "question": "A phone's camera app opens but shows a black image, while a third-party camera app shows the picture normally. What does this indicate?", "options": ["The camera hardware works and the default camera app's data is corrupted; clear its cache and data or reinstall its update", "The camera lens is broken", "The phone needs a new battery", "The SIM must be replaced"], "answer": 0, "explanation": "A working image in a different app proves the sensor, lens and camera service are functional, so the black screen belongs to the stock app. Clearing its cache and storage, removing its latest update, or updating it restores the app without any hardware work. If every camera app showed black, the sensor connection or a privacy block would be suspected instead. Batteries and SIMs are unrelated to camera output.", "distractor_analysis": {"1": "A broken lens would affect every app.", "2": "Battery state does not black out the camera.", "3": "The SIM has nothing to do with imaging."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "camera", "app-data", "troubleshooting"]}, {"id": "C2N-X-027", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "multi", "difficulty": "medium", "question": "A user's phone has poor battery life and frequent app crashes. Which TWO actions are reasonable first steps? (Select TWO.)", "options": ["Install pending operating system and app updates", "Review battery usage by app and restrict or remove the heaviest offenders", "Remove the SIM card permanently", "Cover the phone's cameras with tape", "Set the clock back a year"], "answers": [0, 1], "explanation": "Outdated software is a common cause of both instability and battery drain, because updates fix leaks and crashes, so bringing the system and apps current is the first move. The battery screen then identifies any app that is out of proportion, and restricting its background activity or removing it addresses drain directly. The remaining options are nonsensical: the SIM, cameras and clock have no role in either symptom.", "distractor_analysis": {"2": "The SIM is needed for cellular service and does not affect crashes.", "3": "Cameras do not consume power when not in use.", "4": "A wrong clock breaks certificates and sync rather than helping."}, "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "battery", "updates", "app-crash"]}, {"id": "C2N-X-028", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.2", "type": "order", "difficulty": "easy", "question": "Order the troubleshooting steps for a phone app that will not open, from least to most disruptive.", "sequence": ["Force close the app and reopen it", "Restart the phone", "Clear the app's cache and check for an app update", "Uninstall and reinstall the app", "Back up the phone and perform a factory reset"], "explanation": "Mobile troubleshooting follows the same escalation logic as desktop support. Force closing clears the app's running state, a restart clears the whole system's state, clearing cache and updating fix corrupted temporary data and known bugs, and reinstalling gives the app a completely clean copy. A factory reset is the final step because it affects every app and setting on the device and requires a restore.", "video_reference": {"title": "Troubleshooting Mobile Devices - CompTIA A+ 220-1202 - 3.2", "url": "https://www.youtube.com/watch?v=F5NxaV7t6Bc", "duration": "11:30", "objective": "3.2"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "procedure", "app-troubleshooting"]}, {"id": "C2N-X-029", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user's Android phone shows advertisements on the lock screen and in the notification area even when no app is open. What is the most likely cause?", "options": ["An installed app is adware, probably a recently added free utility or game", "The carrier is testing a new feature", "The phone's screen protector is displaying the ads", "The battery is low"], "answer": 0, "explanation": "Ads outside any app, on the lock screen or as persistent notifications, come from an installed application abusing overlay and notification permissions. Reviewing recently installed apps, checking which app owns the notification by long-pressing it, and uninstalling the offender resolves it. Booting into Safe Mode, which disables third-party apps, confirms the diagnosis if the ads stop. Carriers do not inject lock-screen ads, protectors are passive, and battery level does not produce ads.", "distractor_analysis": {"1": "Carriers do not push lock-screen advertising through the operating system.", "2": "A protector is a sheet of glass or film.", "3": "Battery state does not cause advertisements."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "adware", "security", "malware"]}, {"id": "C2N-X-030", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A phone's cellular data usage tripled this month with no change in the user's habits, and the battery drains quickly. Which security concern should the technician investigate?", "options": ["Malware or a malicious app transmitting data in the background", "The SIM card has expanded", "The phone case is too tight", "The ringtone volume is too high"], "answer": 0, "explanation": "Unexplained data consumption paired with battery drain is a signature of software doing work the user did not ask for: spyware uploading contacts and recordings, a click-fraud app loading ads invisibly, or a compromised app mining or relaying traffic. The data usage screen shows which app consumed the data, and removing it, running a reputable mobile security scan and reviewing permissions follows. The other options are physically meaningless.", "distractor_analysis": {"1": "SIM cards do not change size or generate traffic.", "2": "A case cannot consume data.", "3": "Volume settings are unrelated to data use."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "data-usage", "malware", "security"]}, {"id": "C2N-X-031", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user installed a game from a website rather than the official store, and the phone now behaves erratically. Which statement describes the risk the user took?", "options": ["Sideloaded apps bypass the store's security review and may carry malware or request excessive permissions", "Apps from websites are always safer than store apps", "Sideloading improves battery life", "Sideloading is impossible on any phone"], "answer": 0, "explanation": "Official stores scan submissions, enforce permission rules and can remotely remove malicious apps. Installing from an unknown source, called sideloading, skips those protections and is the primary way mobile malware spreads, often as cracked versions of paid games. Android permits it when the user enables unknown sources; iOS restricts it heavily. The remedy is to uninstall the app, scan the device, review permissions and disable installation from unknown sources.", "distractor_analysis": {"1": "Store review makes store apps generally safer, not the reverse.", "2": "Sideloading has no battery benefit and malware often drains power.", "3": "Android allows sideloading; that is exactly what happened here."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "sideloading", "unknown-sources", "security"]}, {"id": "C2N-X-032", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A corporate phone reports that it has been jailbroken or rooted, and the company's email app refuses to run. Why does the app block itself?", "options": ["Rooting removes the operating system's security controls, so managed apps refuse to run on a device whose integrity cannot be trusted", "Rooting deletes the email account", "Rooting disables the phone's speaker", "Rooting changes the phone's colour"], "answer": 0, "explanation": "Jailbreaking an iPhone or rooting an Android device grants unrestricted system access, which defeats sandboxing, allows unsigned code and lets malware read other apps' data. MDM platforms and security-sensitive apps detect this state and refuse to operate, and company policy usually requires the device to be wiped or replaced. The device will not be trusted again until it is restored to stock firmware. The other options are not effects of rooting.", "distractor_analysis": {"1": "Accounts remain; the app declines to run for integrity reasons.", "2": "Audio hardware is unaffected by rooting.", "3": "Rooting is a software change with no cosmetic effect."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "jailbreak", "root", "mdm", "security"]}, {"id": "C2N-X-033", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user receives a text message claiming to be from their bank with a link to verify a transaction. The link leads to a page that looks like the bank's site. What is this attack called?", "options": ["Smishing, a phishing attack delivered by SMS", "A firmware update", "Bluetooth pairing", "A software licence check"], "answer": 0, "explanation": "Phishing over text messaging is called smishing. The message creates urgency and links to a look-alike site that harvests credentials or one-time codes. Users should never follow links in unexpected messages; they should open the bank's app or type the known address instead, and report the message to the carrier and the bank. Technicians see the aftermath as compromised accounts and should advise resetting passwords and enabling multi-factor authentication.", "distractor_analysis": {"1": "Firmware updates arrive through the operating system, not text links.", "2": "Bluetooth pairing does not involve bank messages.", "3": "Licence checks do not happen through SMS."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "smishing", "phishing", "security"]}, {"id": "C2N-X-034", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user complains that a flashlight app they installed asked for access to contacts, microphone, location and call logs. What should the technician advise?", "options": ["Deny the permissions and uninstall the app, because a flashlight has no legitimate need for that data and the request indicates spyware or data harvesting", "Grant every permission so the flashlight works properly", "Grant only the microphone permission", "Ignore it because permissions do not matter on phones"], "answer": 0, "explanation": "Permission requests should match an app's purpose. A torch needs the camera flash and nothing else; demanding contacts, microphone, location and call history is the pattern of apps built to harvest and sell personal data or to spy. Modern operating systems let users deny individual permissions and show which apps have used sensitive ones recently, but the safest course is to remove an app that overreaches and choose a reputable alternative.", "distractor_analysis": {"1": "None of those permissions is required for a flashlight.", "2": "A torch has no use for the microphone either.", "3": "Permissions are the main defence against data theft on mobile."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "permissions", "spyware", "security"]}, {"id": "C2N-X-035", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A phone connected to public Wi-Fi at a hotel shows a certificate warning when opening the company's webmail. What should the user do?", "options": ["Not proceed, disconnect from that network and use cellular data or a VPN, because the warning may indicate a man-in-the-middle interception", "Tap continue because certificate warnings are always harmless", "Enter the password anyway and change it later", "Turn off the phone's screen lock"], "answer": 0, "explanation": "A browser trusts a site only when its certificate chains to a known authority and matches the address. A warning on a network you do not control is a strong sign that something between the phone and the server is presenting its own certificate to read the traffic, a classic attack on public hotspots. The correct response is to stop, leave the network and use a trusted path such as cellular or the corporate VPN. Continuing hands credentials to the attacker.", "distractor_analysis": {"1": "Warnings exist because the connection cannot be verified.", "2": "Entering the password exposes it immediately to the interceptor.", "3": "Screen lock is unrelated and should stay on."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "certificate", "public-wi-fi", "man-in-the-middle"]}, {"id": "C2N-X-036", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user's phone is sending text messages to their contacts that the user did not write, containing a link. What has most likely happened and what should be done?", "options": ["The phone or the user's messaging account is compromised; scan and remove malicious apps, change the account password, enable multi-factor authentication and warn contacts not to open the link", "The carrier is sending promotional messages on the user's behalf", "The contacts are imagining the messages", "The phone's battery is faulty"], "answer": 0, "explanation": "Self-propagating messages with links are how mobile malware and account takeovers spread: either an installed app has SMS permission and is sending them, or the account behind a messaging service has been hijacked. Containment means removing suspicious apps, changing passwords, adding multi-factor authentication, and telling the recipients not to click, since the link will try to infect them too. Carriers do not send messages from users' numbers, and batteries cannot send texts.", "distractor_analysis": {"1": "Carriers send from their own numbers, not from a customer's.", "2": "Multiple recipients receiving the same link is real, not imagined.", "3": "Battery hardware has no messaging capability."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "malware", "account-compromise", "security"]}, {"id": "C2N-X-037", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A company phone was left unlocked in a cafe for ten minutes. When the user returned, an unfamiliar app had been installed and the location sharing setting was on. What should the technician recommend?", "options": ["Treat the device as compromised: remove the app, review all permissions and accounts, change passwords, and consider a wipe and restore under company policy", "Ignore it because nothing seems broken", "Only turn off location sharing", "Change the wallpaper to something less attractive to thieves"], "answer": 0, "explanation": "Physical access to an unlocked phone is a complete compromise: an attacker can install stalkerware, add their own account to cloud services, register a new authenticator, or export data. The visible changes are only what they did not bother to hide. The safe response is to assume the worst, remove the obvious app, audit accounts, permissions and installed profiles, rotate passwords, and follow the company's incident process, which often means a wipe. Leaving it in place or fixing only one setting leaves hidden access behind.", "distractor_analysis": {"1": "Hidden changes are exactly what a careful attacker would make.", "2": "Location sharing is one symptom, not the whole compromise.", "3": "Wallpaper is irrelevant to security."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "physical-access", "compromise", "incident"]}, {"id": "C2N-X-038", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "hard", "question": "An executive reports that their phone's battery drains quickly, the device is warm at idle, and the camera indicator occasionally lights when no app is open. Which threat matches these symptoms?", "options": ["Spyware or stalkerware secretly recording audio, video and location in the background", "A cracked screen", "An outdated ringtone", "A slow Wi-Fi router"], "answer": 0, "explanation": "Covert monitoring software keeps the processor, sensors and radio busy, which shows as heat and battery drain while the phone appears idle, and the operating system's camera and microphone indicators expose its activity. Such apps hide their icons and often require physical access or a compromised account to install. The response is a full security review, removal via safe mode or a wipe, password changes and, for a high-profile target, escalation to the security team. Screens, ringtones and routers do not cause these signs.", "distractor_analysis": {"1": "A cracked screen does not activate the camera or drain power.", "2": "Ringtones are cosmetic.", "3": "Router speed does not warm an idle phone."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "spyware", "stalkerware", "security"]}, {"id": "C2N-X-039", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user's phone connects to a Bluetooth device they do not recognise whenever they are at a particular coffee shop. What should the technician advise?", "options": ["Remove the unknown device from the paired list, set Bluetooth to non-discoverable when not pairing, and turn it off in public when not needed", "Pair with every device nearby to see which one it is", "Leave Bluetooth permanently discoverable", "Share the phone's contacts with the device to identify it"], "answer": 0, "explanation": "An unrecognised pairing means a device was accepted at some point and now reconnects automatically. Unwanted Bluetooth connections can be used to push files, eavesdrop through audio profiles or track the phone. Removing the pairing, keeping the phone non-discoverable except during an intentional pairing and switching Bluetooth off in public spaces closes the door. Pairing with unknown devices or sharing data with them does the attacker's work for them.", "distractor_analysis": {"1": "Pairing with unknown devices invites exactly the risk being avoided.", "2": "Permanent discoverability advertises the phone to attackers.", "3": "Sharing contacts with an unknown device leaks personal data."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "bluetooth", "unauthorised-pairing", "security"]}, {"id": "C2N-X-040", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user reports that their phone's cloud account shows a sign-in from a city they have never visited. What should they do first?", "options": ["Change the account password immediately, sign out all other sessions, enable multi-factor authentication and review recovery contacts", "Wait to see if it happens again", "Delete all their photos", "Turn off the phone for a day"], "answer": 0, "explanation": "An unfamiliar sign-in location is direct evidence that someone else holds the credentials. The account's security page allows the user to reset the password, revoke every active session and device, add multi-factor authentication and check that the recovery email and phone number have not been changed to the attacker's. Speed matters because the intruder can otherwise lock the legitimate owner out. Waiting, deleting data or powering off the phone does not remove the attacker's access.", "distractor_analysis": {"1": "Delay gives the attacker time to change recovery details.", "2": "Deleting photos destroys the user's data without affecting the intruder.", "3": "The attacker is using the account from elsewhere; the phone being off changes nothing."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "account-compromise", "mfa", "security"]}, {"id": "C2N-X-041", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A user cannot install an app because the phone reports that installation from unknown sources is blocked, and they ask the technician to turn the block off. What is the appropriate response?", "options": ["Explain that the block protects against malware and recommend obtaining the app from the official store or the company's managed app catalogue instead", "Disable the block permanently on every corporate phone", "Root the phone so the block cannot reappear", "Tell the user to download it from any website that offers it"], "answer": 0, "explanation": "The unknown sources restriction exists because sideloaded packages bypass store screening and are the leading vector for mobile malware. On a managed device the policy is set by the company and should not be overridden for convenience. If the app is legitimately required, the correct path is the official store or the MDM's private catalogue, where the organisation has vetted it. Disabling protections fleet-wide, rooting or downloading from arbitrary sites each create the exact risk the control prevents.", "distractor_analysis": {"1": "A fleet-wide bypass removes protection from every device.", "2": "Rooting destroys the device's security model entirely.", "3": "Arbitrary download sites frequently host trojanised apps."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "unknown-sources", "policy", "security"]}, {"id": "C2N-X-042", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "single", "difficulty": "medium", "question": "A phone user notices that a popular banking app was replaced on the home screen by one with a nearly identical icon after they installed a free utility. What should they do?", "options": ["Stop using the suspicious app, uninstall both the utility and the fake app, reinstall the bank's app from the official store, and change banking credentials", "Log in to the look-alike app to check whether it works", "Ignore the change because the icon looks the same", "Only change the phone's wallpaper"], "answer": 0, "explanation": "Overlay and impostor apps mimic legitimate banking apps to capture logins and one-time codes. A utility that installs or swaps a banking icon is malware. Logging in would hand over the credentials. The user should remove both apps, obtain the genuine app from the official store, change the banking password from a trusted device and notify the bank, which may be able to flag the account for monitoring. Ignoring it or changing cosmetic settings leaves the trap in place.", "distractor_analysis": {"1": "Logging in gives the impostor the credentials it was built to steal.", "2": "The identical icon is the deception, not reassurance.", "3": "Wallpaper has no security effect."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "fake-app", "overlay", "banking", "security"]}, {"id": "C2N-X-043", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "multi", "difficulty": "medium", "question": "Which TWO symptoms on a phone most strongly suggest malware rather than an ordinary fault? (Select TWO.)", "options": ["Pop-up advertisements appearing outside any app", "Unexplained spikes in data usage and battery drain while idle", "The screen has a small scratch", "The phone case has faded in the sun", "The volume buttons are stiff"], "answers": [0, 1], "explanation": "Malware needs to earn money or steal data, and both leave traces: advertising injected across the system and network and battery consumption that does not match the user's activity. Other red flags include unknown apps, permissions granted that the user does not remember, and settings changed on their own. Physical wear such as scratches, faded cases and stiff buttons is mechanical and has no software cause.", "distractor_analysis": {"2": "A scratch is cosmetic damage.", "3": "Fading is ultraviolet exposure to the case material.", "4": "Stiff buttons are a mechanical wear issue."}, "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "malware", "symptoms", "security"]}, {"id": "C2N-X-044", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.3", "type": "match", "difficulty": "medium", "question": "Match each mobile security symptom to its most likely cause.", "pairs": [{"left": "Ads on the lock screen", "right": "Adware installed with a free app"}, {"left": "Certificate warning on hotel Wi-Fi", "right": "Possible man-in-the-middle interception"}, {"left": "Contacts receive links the user did not send", "right": "Compromised messaging account or SMS malware"}, {"left": "Managed email app refuses to run", "right": "Device detected as rooted or jailbroken"}, {"left": "Camera indicator lights while idle", "right": "Spyware recording in the background"}], "explanation": "Each symptom maps to a distinct class of threat and therefore a distinct response. Adware is removed by finding the offending app. Certificate warnings on untrusted networks are avoided by leaving the network. Unsolicited messages mean an account or app compromise requiring password changes. Integrity failures mean the device must be restored to stock. Sensor activity at idle means covert monitoring. Recognising the pattern lets the technician act correctly the first time.", "video_reference": {"title": "Troubleshooting Mobile Device Security - CompTIA A+ 220-1202 - 3.3", "url": "https://www.youtube.com/watch?v=_nsBbRwyNMo", "duration": "12:16", "objective": "3.3"}, "notes_reference": "30_Mobile_Security_and_Troubleshooting.md", "tags": ["mobile", "security", "match"]}, {"id": "C2N-X-045", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A Windows user reports that their browser's home page changed to a search site they never chose and new toolbars appeared. What has most likely happened?", "options": ["A browser hijacker or potentially unwanted program was installed, often bundled with a free download", "Windows Update changed the browser", "The keyboard is faulty", "The monitor's colour profile was reset"], "answer": 0, "explanation": "Unwanted home page changes, new toolbars and redirected searches are the fingerprints of a browser hijacker, a category of potentially unwanted program that installs alongside free software when the user clicks through an installer without reading. Removal means uninstalling the offending program, removing the browser extension, resetting the browser's settings and running an anti-malware scan. Windows Update does not alter browser choices, and hardware settings cannot add toolbars.", "distractor_analysis": {"1": "Updates do not change home pages or install third-party toolbars.", "2": "A keyboard fault produces wrong characters, not browser changes.", "3": "Colour profiles affect display appearance only."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "browser-hijacker", "pup", "malware"]}, {"id": "C2N-X-046", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's files have been renamed with a strange extension and a text file on the desktop demands payment in cryptocurrency to restore them. What should the technician do first?", "options": ["Disconnect the machine from the network immediately to stop the encryption spreading to shares, then follow the incident response process", "Pay the ransom as quickly as possible", "Run Disk Cleanup", "Restart the machine repeatedly"], "answer": 0, "explanation": "This is ransomware. The first priority is containment: unplugging the network cable and disabling Wi-Fi prevents it encrypting mapped drives and other machines. The incident should then be reported so the organisation can identify the strain, preserve evidence, remove the malware and restore from known-good backups. Paying funds criminals and does not guarantee recovery. Cleanup tools and reboots do nothing for encrypted files and waste time while the malware spreads.", "distractor_analysis": {"1": "Payment is discouraged by law enforcement and often fails to recover data.", "2": "Disk Cleanup removes temporary files and is irrelevant.", "3": "Rebooting can trigger further encryption and destroys volatile evidence."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "ransomware", "containment", "incident-response"]}, {"id": "C2N-X-047", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A Windows PC shows a full-screen message claiming to be from a well-known software company, stating the computer is infected and giving a phone number to call for support. What is this?", "options": ["A fake security alert or scareware designed to trick the user into calling a scam support line", "A genuine operating system warning", "A hardware diagnostic result", "A firmware update prompt"], "answer": 0, "explanation": "Legitimate operating system and antivirus alerts never display a phone number to call. Scareware pages hijack the browser in full-screen mode and use alarming language to push users toward a fraudulent call centre that charges for fake repairs or installs remote access tools. The fix is to close the browser through Task Manager, clear its data, scan the machine and educate the user. Genuine warnings, diagnostics and firmware prompts do not ask you to phone anyone.", "distractor_analysis": {"1": "Real operating system alerts do not include phone numbers.", "2": "Hardware diagnostics report component status, not infection claims.", "3": "Firmware prompts come from the manufacturer's tool, not a browser page."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "scareware", "fake-alert", "scam"]}, {"id": "C2N-X-048", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's antivirus has been disabled and cannot be re-enabled, Task Manager will not open, and the PC is unusually slow. What do these symptoms together suggest?", "options": ["An active malware infection that is defending itself by disabling security tools", "A pending Windows update", "A low battery", "A misconfigured printer"], "answer": 0, "explanation": "Malware that has gained a foothold commonly disables antivirus, blocks the tools an administrator would use to find it and consumes resources with its own activity. When protection cannot be re-enabled and system utilities are blocked, the machine should be treated as compromised: isolate it, boot from trusted media or into Safe Mode, scan with an offline or alternative tool and remediate following the malware removal procedure. Updates, power and printers do not disable security software.", "distractor_analysis": {"1": "Updates do not block Task Manager.", "2": "Battery level has no effect on security tools.", "3": "Printer problems affect printing only."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "malware", "antivirus-disabled", "symptoms"]}, {"id": "C2N-X-049", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user reports receiving automated replies from contacts to emails they never sent, and their sent folder contains messages they do not recognise. What has happened?", "options": ["The email account has been compromised and is being used to send spam or phishing", "The email server is testing delivery", "The user's keyboard is sending emails on its own", "The antivirus is sending reports"], "answer": 0, "explanation": "Messages the user did not write appearing in the sent folder mean someone else has access to the account, typically after a phishing attack or password reuse. The attacker uses the trusted account to phish the user's contacts. Remediation is to change the password, revoke all sessions and app passwords, enable multi-factor authentication, check for malicious forwarding rules the attacker may have added, and warn contacts. Servers, keyboards and antivirus products do not compose emails.", "distractor_analysis": {"1": "Servers do not send messages from user accounts.", "2": "Keyboards cannot compose and send mail.", "3": "Antivirus reports go to administrators, not out to the user's contacts."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "account-compromise", "email", "phishing"]}, {"id": "C2N-X-050", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's browser shows a certificate error for every secure website, including major sites that were fine yesterday. The system clock shows a date two years in the past. What is the fix?", "options": ["Correct the system date and time, then check the CMOS battery if the clock keeps resetting", "Reinstall the browser", "Disable HTTPS for all sites", "Replace the network cable"], "answer": 0, "explanation": "Certificates are valid only between their start and expiry dates. If the computer's clock is wrong, every certificate appears not yet valid or expired and the browser correctly refuses to trust it. Setting the right time restores normal browsing at once. A clock that repeatedly resets indicates a failing CMOS battery. The browser is behaving properly, disabling encryption would be dangerous and pointless, and cabling has nothing to do with certificate validation.", "distractor_analysis": {"1": "The browser is doing its job; the clock is at fault.", "2": "Turning off HTTPS exposes all traffic and does not fix the clock.", "3": "Cabling affects connectivity, not certificate dates."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "certificate", "system-clock", "troubleshooting"]}, {"id": "C2N-X-051", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user says they can no longer reach several websites, and the browser lands on a different site than the address typed. Other computers on the network reach the sites normally. What should the technician check on the affected PC?", "options": ["The hosts file and the configured DNS servers for malicious entries or a rogue DNS setting", "The screen resolution", "The mouse driver", "The sound card"], "answer": 0, "explanation": "Redirection that affects only one machine points at its name resolution. Malware commonly edits the hosts file to send banking or security sites to attacker servers, or changes the network adapter's DNS servers to a rogue resolver. Inspecting the hosts file for unexpected entries and confirming the DNS settings match the network's, then scanning for malware and resetting the browser, resolves it. Display, mouse and audio settings are unrelated to where addresses resolve.", "distractor_analysis": {"1": "Resolution does not affect name resolution.", "2": "Mouse drivers cannot redirect web addresses.", "3": "Audio hardware has no networking role."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "dns", "hosts-file", "redirection", "malware"]}, {"id": "C2N-X-052", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "Windows Update fails repeatedly on a PC, and the antivirus definitions have not updated in weeks. The internet works for browsing. What might explain both failures?", "options": ["Malware blocking access to update and security vendor servers to protect itself", "The keyboard batteries are low", "The user has too many desktop icons", "The printer is offline"], "answer": 0, "explanation": "Many malware families block connections to operating system and security update servers through hosts file entries, firewall rules or a malicious proxy, so they cannot be detected or removed by newly released signatures. A machine where general browsing works but security and update services specifically fail should be scanned from trusted offline media, its hosts file and proxy settings inspected, and then updated once cleaned. Peripherals and desktop clutter cannot cause targeted update failures.", "distractor_analysis": {"1": "Keyboard power affects typing only.", "2": "Desktop icons have no effect on update connectivity.", "3": "Printer state is unrelated to updates."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "malware", "update-failure", "symptoms"]}, {"id": "C2N-X-053", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user received an email with an invoice attachment from an unknown sender and opened it. Nothing visible happened, but the technician wants to be safe. What is the best course of action?", "options": ["Disconnect the PC from the network, run a full scan with updated anti-malware, and check for new scheduled tasks, startup entries and unusual processes", "Assume it is fine because nothing appeared on screen", "Forward the attachment to colleagues to ask their opinion", "Delete the email and take no further action"], "answer": 0, "explanation": "Malicious documents are designed to run silently: a macro or exploit installs a downloader that fetches the real payload later. Absence of symptoms means nothing. Isolating the machine limits any spread, a full scan with current definitions catches known threats, and checking persistence points such as scheduled tasks, Run keys and startup folders finds droppers that scanners miss. Forwarding the file spreads the risk, and deleting the email does not undo whatever it already did.", "distractor_analysis": {"1": "Modern malware avoids visible symptoms deliberately.", "2": "Forwarding a malicious attachment exposes more people.", "3": "Deleting the message does not remove code already executed."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "phishing", "attachment", "incident-response"]}, {"id": "C2N-X-054", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "hard", "question": "After removing malware from a Windows PC, the technician wants to make sure the infection cannot return from a saved snapshot. Which step in the malware removal process addresses this?", "options": ["Disable System Restore during remediation so infected restore points are discarded, then re-enable it and create a clean restore point afterwards", "Delete the user's documents folder", "Uninstall the antivirus", "Change the desktop theme"], "answer": 0, "explanation": "System Restore snapshots capture system files and the registry, including any malware present at the time. If a user later rolls back to one of those points, the infection returns. The standard removal procedure therefore disables System Restore while cleaning, which deletes the existing points, and re-enables it once the system is verified clean so a fresh, trustworthy restore point can be made. The user's documents are unrelated, the antivirus should stay, and themes are cosmetic.", "distractor_analysis": {"1": "User documents are not restore points and should be preserved.", "2": "Removing protection after an infection is the opposite of the goal.", "3": "Themes have no security relevance."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "malware-removal", "system-restore", "procedure"]}, {"id": "C2N-X-055", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's cursor moves on its own and windows open and close while they are not touching the mouse. The PC recently had a remote support session from a caller claiming to be from an internet provider. What is the most likely explanation?", "options": ["A remote access tool was installed during the fraudulent support call and an attacker now controls the PC", "The mouse has a low battery", "The screen saver is active", "Windows is applying a theme"], "answer": 0, "explanation": "Unsolicited callers posing as providers or software vendors persuade victims to install legitimate remote access tools, then use them later to steal data, install malware or commit fraud. Cursor movement and window activity with no user input is the attacker at work. The PC must be disconnected immediately, the remote tool and anything else installed during the call removed, passwords changed from a different device, and the incident reported. Peripheral power and cosmetic features do not open and close windows.", "distractor_analysis": {"1": "A weak mouse battery causes lag or dropouts, not deliberate actions.", "2": "Screen savers do not manipulate windows.", "3": "Themes change appearance without opening applications."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "remote-access", "tech-support-scam", "compromise"]}, {"id": "C2N-X-056", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user's browser constantly opens new tabs with gambling and shopping sites even when the user is not clicking anything. The antivirus scan is clean. What should the technician check next?", "options": ["The browser's installed extensions and any unfamiliar programs in the installed apps list, since adware often lives outside the antivirus's detection scope", "The BIOS boot order", "The monitor cable", "The paper tray of the printer"], "answer": 0, "explanation": "Adware and browser hijackers are frequently classified as potentially unwanted rather than malicious, so a standard antivirus may not flag them. The browser's extension list and the operating system's installed programs are where they hide. Removing suspicious extensions and programs, resetting browser settings and running a dedicated anti-adware tool completes the clean-up. Firmware boot order and cabling have no bearing on browser behaviour, and the printer is irrelevant.", "distractor_analysis": {"1": "Boot order determines which device starts, not what a browser does.", "2": "A display cable cannot open tabs.", "3": "Printers do not affect web browsers."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "adware", "browser-extensions", "pup"]}, {"id": "C2N-X-057", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "single", "difficulty": "medium", "question": "A user notices that a file they saved yesterday has vanished, and several other documents have changed size. No ransom note is present. Which possibility should the technician consider alongside user error?", "options": ["Malware or a compromised account altering or deleting files, so check file history, audit logs and scan the system before restoring from backup", "The files were too heavy for the hard drive", "The monitor deleted them", "The mouse pad is worn"], "answer": 0, "explanation": "Files that disappear or change without the user's knowledge can be accidental, but they are also a symptom of malware that corrupts, exfiltrates or quietly encrypts data, or of an attacker with access to the account or a synced cloud folder. Checking version history and the cloud recycle bin, reviewing sign-in logs for unfamiliar sessions and scanning the machine should precede restoring from backup, so the restored files are not damaged again. The other options are physically impossible.", "distractor_analysis": {"1": "Files have no weight; storage either has space or does not.", "2": "Displays cannot modify storage.", "3": "A worn mouse pad affects tracking only."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "missing-files", "malware", "investigation"]}, {"id": "C2N-X-058", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "multi", "difficulty": "medium", "question": "Which TWO are common symptoms that a Windows PC is infected with malware? (Select TWO.)", "options": ["Security software has been disabled and cannot be turned back on", "The browser redirects to unexpected sites and shows extra pop-ups", "The keyboard has a sticky key", "The desktop background is a photograph", "The PC has two monitors"], "answers": [0, 1], "explanation": "Malware protects itself and monetises the victim, so disabled security tools and browser redirection with pop-ups are two of the most reliable indicators, alongside slow performance, unknown processes, altered system files, failed updates and unexplained network activity. Physical keyboard wear and ordinary personalisation such as wallpapers and multi-monitor setups are normal and carry no security meaning.", "distractor_analysis": {"2": "A sticky key is mechanical wear.", "3": "Wallpaper choice is normal personalisation.", "4": "Multiple monitors are a common productivity setup."}, "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "malware", "symptoms"]}, {"id": "C2N-X-059", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "order", "difficulty": "medium", "question": "Order the best-practice steps for removing malware from a Windows PC.", "sequence": ["Investigate and verify the malware symptoms", "Quarantine the infected system by disconnecting it from the network", "Disable System Restore so infected restore points are not kept", "Remediate: update anti-malware, scan and remove the infection, using Safe Mode or offline media if needed", "Schedule scans and run updates, then enable System Restore and create a clean restore point", "Educate the end user on how the infection occurred and how to avoid it"], "explanation": "This is the standard malware removal sequence. Verification prevents treating a hardware fault as an infection. Quarantine stops spread. Disabling System Restore removes the risk of reinfection from a snapshot. Remediation with current definitions, in an environment where the malware is not running, removes it. Re-enabling protection with a fresh restore point and scheduled scans hardens the machine, and educating the user addresses the root cause, since most infections begin with a click.", "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "malware-removal", "procedure"]}, {"id": "C2N-X-060", "exam": "core2", "domain": "3.0 Software Troubleshooting", "objective": "3.4", "type": "match", "difficulty": "medium", "question": "Match each PC security symptom to its most likely cause.", "pairs": [{"left": "Files renamed with an odd extension and a payment demand", "right": "Ransomware"}, {"left": "Home page and search engine changed with new toolbars", "right": "Browser hijacker"}, {"left": "Full-screen warning with a phone number to call", "right": "Scareware or fake alert"}, {"left": "Certificate errors on every site with a wrong system date", "right": "Incorrect system clock"}, {"left": "Cursor moving on its own after a suspicious support call", "right": "Unauthorised remote access tool"}], "explanation": "Security symptoms are diagnostic when read carefully. Encryption with a demand is ransomware and needs containment and restoration. Browser changes are hijackers removed through extensions and installed programs. A phone number in a warning is always a scam. Certificate errors everywhere are a clock problem rather than an attack. Remote control after a cold call means an attacker still has access and the machine must be isolated. Matching symptom to cause selects the right response.", "video_reference": {"title": "Troubleshooting Security Issues - CompTIA A+ 220-1202 - 3.4", "url": "https://www.youtube.com/watch?v=OCLOLvwgdMY", "duration": "10:16", "objective": "3.4"}, "notes_reference": "29_Workstation_Browser_Security_Malware.md", "tags": ["security", "symptoms", "match"]}]};
